insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', 'ISA', $b$Y-Êsai$b$, $b$["Sămƀŭt Bơh", "Y-ÊSAI"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','ISA',1,1,null,$b$Nau Y-Êsai kon bu klâu Y-Amôt tâm saơ di ma bri Yuđa jêh ri ma ƀon Yêrusalem tâm rnôk Y-Usia, Y-Jôtham, Y-Ahas, jêh ri Y-Hêsêkia phung hađăch Yuđa.$b$,true),
('bunong-vn','ISA',1,2,null,$b$Ơ trôk, gŭ iăt hom! Ơ neh ntu, rkêng hom tôr! Yor lah Yêhôva ngơi jêh: “Gâp siăm jêh ri rong jêh phung kon bu klâu, ƀiă lah khân păng tâm rdâng jêh đah gâp.$b$,true),
('bunong-vn','ISA',1,3,null,$b$Ndrôk gĭt năl nơm mât păng, seh bri gĭt năl hip gơ̆ kôranh păng, ƀiă lah phung Israel mâu gĭt ôh, phung ƀon lan gâp mâu geh nau gĭt rbăng ôh.”$b$,true),
('bunong-vn','ISA',1,4,null,$b$Ơ ndŭl mpôl tih mhĭk, du phung ƀon lan jâk ma nau kue, kon sau phung ƀai, phung kon gŭ ƀư nau ƀơ̆ ƀơch! Khân păng cha lơi jêh Yêhôva, khân păng tâm rmot jêh ma nơm kloh ueh Israel, khân păng nkhah du jêh.$b$,false),
('bunong-vn','ISA',1,5,null,$b$Mâm ƀư ăt khân may ŭch bu dong khân may yor nau khân may tâm rdâng ƀa ƀơ? Ji lam bôk, jêh ri lĕ nuih n'hâm jêng ra ai rgănh jêh.$b$,true),
('bunong-vn','ISA',1,6,null,$b$Bơh mpang jâng tât ta bôk, mâu geh du ntŭk soih ôh, geh knŏng ntŭk bŭr jêh ri toh-ok, jêh ri sôt luh mham, bu mâu mâp pet ndâng ôh, mâu lĕ mâp put, mâu lĕ mâp mhĭng ma dak play ôlivơ.$b$,false),
('bunong-vn','ISA',1,7,null,$b$Bri khân may jêng rngol jêh, lĕ ƀon toyh khân may bu su ma ŭnh. Phung bu-năch sŏk pit bri khân may ta năp măt khân may. Păng jêng rngol tâm ban ma phung bu năch ƀư rai jêh păng.$b$,false),
('bunong-vn','ISA',1,8,null,$b$Jêh ri bu cha lơi kon bu ur Siôn hôm tâm ban ma du mlâm ndưp tâm đang n'gar bu tăm rpŭng, tâm ban ma du rplay ƀon bu nchueng jêh.$b$,false),
('bunong-vn','ISA',1,9,null,$b$Tơ lah Yêhôva ma phung ka han mâu lơi ma he du phung djê̆ hôm, he jêng jêh tâm ban ma ƀon Sôdôm, tâm ban ma ƀon Gômôrơ. Nau kuăl ma nau tâm rmal ngăn.$b$,false),
('bunong-vn','ISA',1,10,null,$b$Gŭ iăt hom nau Yêhôva ngơi. Ơ phung chiă uănh ƀon Sôdôm! Rkêng tôr ma nau vay Brah Ndu he, khân may phung ƀon lan Gômôrơ!$b$,true),
('bunong-vn','ISA',1,11,null,$b$Yêhôva lah, “Moh khlay ma gâp âk ndơ khân may ƀư brah? Gâp mpay đah mpa nhhơr gŭch biăp nkuăng jêh ri ngi mpô mpa rong. Gâp mâu maak ôh đah mham ndrôk nkuăng, kon biăp mâu lah be nkuăng.$b$,false),
('bunong-vn','ISA',1,12,null,$b$Tơ lah khân may văch nhhiơ ta năp gâp, mbu mâp dăn ăn khân may văch jot lơi nkuĭl gâp?$b$,false),
('bunong-vn','ISA',1,13,null,$b$Lơi hôm njŭn mpa nhhơr mâu khlay ôh, Gâp tâm rmot ma mpa ƀâu kah, ma nau nhêt sông ta khay mhe luh, ma nar sa ƀat, jêh ri ma nau kuăl tâm rƀŭn. Gâp mâu dơi dơn ôh nau kue jêh ri nau tâm rƀŭn yơk.$b$,false),
('bunong-vn','ISA',1,14,null,$b$Gâp tâm rmot ma nau nhêt sông khay mhe jêh ri ma nau nhêt sông tĭng nâm tâm nal jêh. Khân păng ƀư jâk gâp, gâp rgănh tuy khân păng.$b$,false),
('bunong-vn','ISA',1,15,null,$b$Tơ lah khân may yơr ti khân may, gâp mra pôn măt gâp ma khân may, Nđâp tơ lah khân may mbơh sơm âk, gâp mâu mra iăt ôh. Ti khân may bêng ma mham.$b$,false),
('bunong-vn','ISA',1,16,null,$b$Rao hom khân may nơm, ƀư kloh hom khân may nơm, sŏk lơi nau mhĭk tâm nau khân may ƀư ta năp măt gâp, rlu hom ƀư nau mhĭk.$b$,false),
('bunong-vn','ISA',1,17,null,$b$Ăn khân may nti ƀư nau ueh, tĭng joi nau sŏng N'gang an bunuyh bu tŭn jot, ƀư nau di ma kon đơi mbơ̆ , ngơi n'gang an ma bu ur ndrô.$b$,false),
('bunong-vn','ISA',1,18,null,$b$Yêhôva lah, “Văch hom, ăn he sek uănh ndrel n'grŭp. Nđâp tơ lah nau tih khân may jêng chăng-rhŏnh, păng mra jêng nglang tâm ban ma pler; nđâp tơ lah păng jêng chăng-krăk. Khân păng mra jêng tâm ban ma rsau biăp.$b$,true),
('bunong-vn','ISA',1,19,null,$b$Tơ lah khân may ŭch jêh ri tông bâr, khân may mra sa play ueh lơn tâm bri.$b$,false),
('bunong-vn','ISA',1,20,null,$b$Ƀiă lah tơ lah khân may dun jêh ri tâm rdâng, đao gưm mra ƀư rai khân may, Yor lah trôm mbung Yêhôva ngơi jêh.” Nau phat dôih jêh ri nau tâm chuai ƀon Siôn.$b$,false),
('bunong-vn','ISA',1,21,null,$b$Ƀaih, ƀon răp jăp nkhơng jêng jêh ka n'hong! Kăl e păng bêng ma nau sŏng nau sŏng gŭ tâm păng, ƀiă lah aƀaơ aơ geh phung tâm nkhĭt bunuyh.$b$,true),
('bunong-vn','ISA',1,22,null,$b$Prăk may tâm rgâl jêng ndŏk, dak play kriăk ƀâu may tâm lŭk lai jêh đah ngi.$b$,false),
('bunong-vn','ISA',1,23,null,$b$Phung chiă uănh may jêng phung tâm rdâng, băl đah phung ntŭng. Ăp nơm rŏng ma drăp blŏl jêh ri tĭng nau nkhôm. Khân păng mâu n'gang phung kon đơi mbơ̆ ôh, mâu lĕ khân păng chrê ma nau sŏng bu ur ndrô.$b$,false),
('bunong-vn','ISA',1,24,null,$b$Yor nây Kôranh Brah, Yêhôva ma phung ta han, Nơm Brah Israel lah: “Ơ, gâp mra ƀư tât nau gâp ji nuih ma phung rlăng đah gâp, gâp mra plơng bôk đah phung rlăng đah gâp.$b$,true),
('bunong-vn','ISA',1,25,null,$b$Gâp mra rle ƀư ma may, gâp mra ăn lêk lĕ ndŏk may, jêh ri sŏk lơi lĕ ndruyh ndrak may.$b$,false),
('bunong-vn','ISA',1,26,null,$b$Gâp mra rdâk tay phung kôranh phat dôih may tâm ban nôk lor, jêh ri phung kôranh nchră may tâm ban ma ntơm sa ơm jêh nau nây bu rnha ma may jêng ƀon sŏng srăng, jêng ƀon răp jăp.$b$,false),
('bunong-vn','ISA',1,27,null,$b$Bu mra tâm chuai ƀon Siôn ma nau sŏng jêh ri tâm chuai lĕ phung rmal ma nau tih tâm păng ma nau sŏng srăng.$b$,true),
('bunong-vn','ISA',1,28,null,$b$Ƀiă lah phung tâm rdâng jêh ri phung tih mra rai yot, jêh ri phung cha lơi Yêhôva mra rai yot.$b$,false),
('bunong-vn','ISA',1,29,null,$b$Yor lah may mra bêk yor tơm si têrêbin khân may rŏng; jêh ri khân may mra chăng muh măt yor n'gar kao khân may săch jêh.$b$,false),
('bunong-vn','ISA',1,30,null,$b$Yor lah khân may mra jêng tâm ban ma du n'gâng tơm si têrêbin n'ha klêu, tâm ban ma n'gar kao mâu geh dak ôh.$b$,false),
('bunong-vn','ISA',1,31,null,$b$Bunuyh ktang mra jêng tâm ban ma ndŏk mhay bu ƀư brai, jêh ri kan păng tâm ban kao ŭnh; lĕ bar khân păng ŭnh mra sa ndrel n'grŭp, jêh ri mâu geh nơm ƀư ngôm khân păng ôh.$b$,false),
('bunong-vn','ISA',2,1,null,$b$Nau Y-Êsai kon bu klâu Y-Amôt saơ di ma bri Yuđa jêh ri ƀon Yêrusalem.$b$,true),
('bunong-vn','ISA',2,2,null,$b$Tâm rnôk lôch dŭt yôk ngih Yêhôva bu mra n'hao ăn jêng kô yôk prêh lơn, jêh tâm n'hao păng ta klơ lĕ rngôch mbon; Jêh ri lĕ rngôch ndŭl mpôl bunuyh mra nsŭn hăn ta păng.$b$,true),
('bunong-vn','ISA',2,3,null,$b$Âk phung ƀon lan mra văch jêh ri lah, “Kay lŏng, ăn he hăn hao ta yôk Yêhôva ta ngih Brah Ndu phung Yakôb, gay ma păng sâm nti trong păng ma he, jêh ri gay ma he dơi hăn tâm trong păng.” Yor lah nau vay mra luh bơh ƀon Siôn, jêh ri nau Yêhôva ngơi mra luh bơh ƀon Yêrusalem$b$,false),
('bunong-vn','ISA',2,4,null,$b$Păng mra phat dôih phung ndŭl mpôl bunuyh jêh ri păng mra ngơi dôih ma âk phung ƀon lan. Khân păng mra chiăr đao gưm khân păng njêng kau kai, jêh ri tak khân păng njêng ƀư nhuĕ. Du phung ndŭl mpôl bunuyh mâu mra tŏk đao gưm ƀư ma ndŭl mpôl êng ôh, mâu lĕ khân păng mra nti tâm lơh.$b$,false),
('bunong-vn','ISA',2,5,null,$b$Ơ ngih phung Yakôb, văch hom, ăn he hăn tâm nau ang Yêhôva.$b$,true),
('bunong-vn','ISA',2,6,null,$b$Yor lah may dun jêh phung ƀon lan may ngih phung Yakôb. Yor lah khân păng bêng ma nau rƀên bơh bri pa lơ, jêh ri ƀư tâm ban ma phung n'hŭm phung Philistin, jêh ri khân păng tâm kuăn ti đah phung bu năch mâu chroh ôh.$b$,false),
('bunong-vn','ISA',2,7,null,$b$Bri khân păng bêng ma prăk jêh ri mah, mâu geh n'har ôh ma nau ndrŏng khân păng. Bri khân păng bêng ma seh, jêh ri ndeh seh,$b$,false),
('bunong-vn','ISA',2,8,null,$b$Bri khân păng bêng ma rup brah, khân păng chon mon mbah ma kon ti khân păng nơm ƀư, ndơ nglao ti khân păng nơm nkra.$b$,false),
('bunong-vn','ISA',2,9,null,$b$Phung jê̆ bu mra ngroh phung toyh bu mra n'glưh. Lơi ta yô̆ ma khân păng ôh.$b$,false),
('bunong-vn','ISA',2,10,null,$b$Lăp hom tâm lŭ, jêh ri du krap hom tâm nduyh neh ta năp Yêhôva nhhu, jêh ri đah nau ntral nau chrêk rmah păng.$b$,true),
('bunong-vn','ISA',2,11,null,$b$Muh măt bunuyh rnam bu mra n'glưh jêh ri bu mra ƀư dêh rhêt phung sưr. Knŏng Yêhôva mra geh nau tâm n'hao tâm nar nây.$b$,false),
('bunong-vn','ISA',2,12,null,$b$Yor lah Yêhôva ma phung ka han tâm nal jêh du nar păng mra ƀư ma lĕ phung sưr, ma phung rnam, jêh ri ma lĕ phung tâm n'hao khân păng nơm;$b$,true),
('bunong-vn','ISA',2,13,null,$b$ƀư ma lĕ rngôch tơm si sêdar sưr bri Liban, jêh ri ma lĕ rngôch tơm si têrêbin ta bri Basan;$b$,false),
('bunong-vn','ISA',2,14,null,$b$nđâp yôk, ma lĕ rngôch gôl prêh;$b$,false),
('bunong-vn','ISA',2,15,null,$b$ma lĕ rngôch ngih tŭm prêh, ma lĕ rngôch pêr king,$b$,false),
('bunong-vn','ISA',2,16,null,$b$ma lĕ rngôch kumpăn Tarsis, jêh ri ma lĕ rngôch ndơ ƀư maak ma măt$b$,false),
('bunong-vn','ISA',2,17,null,$b$Păng mra tông bâr phung rnam, jêh ri mra n'hŭch phung sưr. Knŏng êng Yêhôva mra geh nau tâm n'hao tâm nar nây.$b$,false),
('bunong-vn','ISA',2,18,null,$b$Rup brah mra rlau lôch.$b$,true),
('bunong-vn','ISA',2,19,null,$b$Phung bunuyh mra lăp tâm trôm yôk lŭ jêh ri tâm trôm ndruyh neh bơh ta năp nau Yêhôva nhhu jêh ri nau ntral nau chrêk rmah păng, tơ lah păng dâk gay ma nhhu nkrit neh ntu.$b$,true),
('bunong-vn','ISA',2,20,null,$b$Tâm nar nây phung bunuyh mra klŭp lơi ma đe jêh ri ma rêt mbing rup brah prăk jêh ri rup brah mah khân păng, khân păng ƀư jêh prăp yơk mbah.$b$,false),
('bunong-vn','ISA',2,21,null,$b$Khân păng mra lăp tâm trôm nđa lŭ jêh ri tâm ntŭk ntu lŭng tâm lŭ ta năp nau Yêhôva nhhu nkrit jêh ri bơh nau ntral chrêk rmah păng, tơ lah păng dâk gay nhhu krit neh ntu.$b$,false),
('bunong-vn','ISA',2,22,null,$b$Lơi hôm rnơm ma bunuyh blau suh n'hâm, yor lah moh nau păng khlay?$b$,true),
('bunong-vn','ISA',3,1,null,$b$Yor lah aơ, Kôranh Brah Yêhôva ma phung ta han mra sŏk rdu lơi bơh ƀon Yêrusalem jêh ri bri Yuđa jêng ndơ bu rnơm lĕ ndơ sông sa jêh ri dak,$b$,true),
('bunong-vn','ISA',3,2,null,$b$nơm janh ktang jêh ri ta han, kôranh phat dôih jêh ri kôranh-nơm-mbơh lor, nơm rƀên jêh ri bu bŭnh bu ranh,$b$,false),
('bunong-vn','ISA',3,3,null,$b$kôranh ma prăm jât nuyh ta han jêh ri kôranh toyh, kôranh nchră, nơm blau kan jêh ri n'hŭm.$b$,false),
('bunong-vn','ISA',3,4,null,$b$Gâp mra ăn phung ndăm jêng kôranh chiă uănh khân păng; Jêh ri phung kon se mra chiă uănh khân păng.$b$,false),
('bunong-vn','ISA',3,5,null,$b$Phung ƀon lan mra tâm tŭn jot ndrăng khân păng, ăp nơm ƀư ma băl păng jêh ri ăp nơm ƀư ma phung chiau meng păng. Kon se mra suai rak ma nơm bu ranh, jêh ri bunuyh dơm dam mra ƀư ma nơm bu yơk.$b$,true),
('bunong-vn','ISA',3,6,null,$b$Tơ lah du huê bunuyh mra kuăn rdâng oh nâu păng tâm ngih mbơ̆ păng, lah, “May geh bok ao, ăn may jêng kôranh hên! Ăn may chiă uănh ntŭk rai jêh aơ.”$b$,true),
('bunong-vn','ISA',3,7,null,$b$Tâm nar nây păng mra plơ̆ lah, “Gâp mâu mra jêng nơm ƀư bah ôh, tâm ngih gâp mâu geh ndơ sông sa, mâu lĕ geh bok ao. Lơi ăn gâp jêng kôranh ma phung ƀon lan ôh.”$b$,false),
('bunong-vn','ISA',3,8,null,$b$Yor lah ƀon Yêrusalem lơi cha lôt jêh, jêh ri bri Yuđa rlâm jêh; yor lah nau khân păng ngơi jêh ri kon pah tâm rdâng đah Yêhôva, mâu chrê ôh ma nau chrêk rmah păng gŭ ndrel.$b$,true),
('bunong-vn','ISA',3,9,null,$b$Muh măt khân păng tâm mpơl mbơh tâm rdâng đah khân păng nơm khân păng nkoch rah vah nau tih khân păng nâm bu ƀon Sôdôm, mâu mo ôh. Rêh ni ngăn ma huêng khân păng, yor lah khân păng ăn tât jêh nau mhĭk ma khân păng nơm.$b$,false),
('bunong-vn','ISA',3,10,null,$b$Lah hom ma phung sŏng, ueh maak yơh ma khân păng, yor lah khân păng mra sa play bơh kan khân păng.$b$,true),
('bunong-vn','ISA',3,11,null,$b$Rêh ni ngăn ma nơm ƀai; mra jêng mhĭk ma păng yor lah bu mra ƀư ma păng moh nau ti păng ƀư jêh.$b$,false),
('bunong-vn','ISA',3,12,null,$b$Bi phung ƀon lan gâp, phung kon se tŭn jot khân păng, jêh ri phung bu ur chiă uănh khân păng. Ơ phung ƀon lan gâp, phung njŭn leo khân may ăn khân may nhhơt bri, jêh ri ƀư vĭ trong khân may.$b$,true),
('bunong-vn','ISA',3,13,null,$b$Yêhôva gŭ râng ŭch tâm rlăch, păng gŭ râng gay phat dôih phung ƀon lan păng$b$,true),
('bunong-vn','ISA',3,14,null,$b$Yêhôva mra phat dôih phung bu bŭnh bu ranh jêh ri phung kôranh phung ƀon lan păng: “Khân may yơh sa lơi jêh n'gar play kriăk ƀâu; drăp ndơ ntŭng bơh phung o-ach, gŭ tâm ngih khân may.$b$,false),
('bunong-vn','ISA',3,15,null,$b$Moh nau khân may jot lơi phung ƀon lan gâp jêh ri jot rchal lơi muh măt phung o-ach?” Kôranh Brah Yêhôva ma phung ta han lah.$b$,false),
('bunong-vn','ISA',3,16,null,$b$Yêhôva lah, “Yor lah phung kon bu ur ƀon Siôn jêng rnam, hăn ntoch trô ko, jêh ri măt uănh ma nau kơnh, khân păng hăn nhuat gle gleh, jêh ri ăn nteh kông jâng khân păng.$b$,true),
('bunong-vn','ISA',3,17,null,$b$Yor nây Kôranh Brah ăn hil klơ ndoh bôk phung bu ur ƀon Siôn, Yêhôva mra ăn toh ok ta bôk khân păng.$b$,false),
('bunong-vn','ISA',3,18,null,$b$Tâm nar nây Kôranh Brah mra sŏk lơi ndơ nkrơ̆ kông jâng khân păng, yŭ sŏk jêh ri kông văn ta trô-ko,$b$,false),
('bunong-vn','ISA',3,19,null,$b$thek ta tôr, kông ta ti, jêh ri bok n'guăch trô ko,$b$,false),
('bunong-vn','ISA',3,20,null,$b$đon hađăch jê̆, rse rvăk ta jâng, rse vân bŭt, nông dak ƀâu kah, jêh ri lŭ brah,$b$,false),
('bunong-vn','ISA',3,21,null,$b$rgên chrăk jêh ri kông ta trôm muh,$b$,false),
('bunong-vn','ISA',3,22,null,$b$bok ao prăp nhêt sông jêh ri ao jâr, ao mbâl, jêh ri dŭng,$b$,false),
('bunong-vn','ISA',3,23,null,$b$nal bok, ao mhay, bok mpân bôk jêh ri bok put muh măt.$b$,false),
('bunong-vn','ISA',3,24,null,$b$Ndơ ƀâu ôm mra ntrok ma ndơ ƀâu kah, du njăr rse buănh nsro jêng rse bŭt, bôk hil nsro ma sŏk krô, dŭng ƀau nsro ma ao mbâl, nau bêk nsro ma nau ueh.$b$,false),
('bunong-vn','ISA',3,25,null,$b$Phung bu klâu may mra prah ma đao gưm, phung janh ktang may mra khĭt tâm nau tâm lơh.$b$,false),
('bunong-vn','ISA',3,26,null,$b$Phung gŭ ta mpông pêr ƀon mra nhĭm nhhiăng jêh ri ndrê ndjăng. Bu mra pit sŏk jêh ri ƀư rai ƀon nây.$b$,true),
('bunong-vn','ISA',4,1,null,$b$Tâm nar nây pơh nuyh bu ur mra kuăn rdâng du huê bu klâu, lah, “Hên mra sa ndơ sông sa hên nơm jêh ri soh bok ao hên nơm, knŏng ăn bu rnha hên ma amoh may. Ăn may sŏk lơi nau bêk hên.”$b$,true),
('bunong-vn','ISA',4,2,null,$b$Tâm nar nây nkeh Yêhôva mra jêng ueh jêh ri chrêk rmah, phung Israel klaih jêh mra hâk răm jêh ri n'hao nuih yor play tâm bri neh.$b$,true),
('bunong-vn','ISA',4,3,null,$b$Jêh ri bu mra rnha phung hôm tâm ƀon Siôn jêh ri phung hôm tâm ƀon Yêrusalem phung kloh ueh, ăp nơm mbu nâm bu chih prăp jêh ma nau rêh tâm ƀon Yêrusalem.$b$,false),
('bunong-vn','ISA',4,4,null,$b$Kôranh Brah mra rao lơi nau ƀơ̆ ƀơch phung kon bu ur ƀon Siôn, jêh ri ƀư kloh lơi mham tă bơh tâm nklang ƀon Yêrusalem ma nau phat dôih jêh ri huêng brah nau su.$b$,false),
('bunong-vn','ISA',4,5,null,$b$Ta klơ ntŭk yôk Siôn gŭ jêh ri ta klơ phung ƀon tâm rƀŭn Yêhôva mra rhăk ndâr tŭk dôl nar jêh ri nhhŭk ŭnh jêh ri nau ang mpiăt ŭnh hit dôl măng, yor lah mra geh ndơ nkŭm ta klơ lĕ rngôch ndơ chrêk rmah.$b$,false),
('bunong-vn','ISA',4,6,null,$b$Ndơ nkŭm mra ăn gui n'hâm king duh nôk nar jêh ri jêng ntŭk du krap jêh ri ntŭk rnơm ma sial phŭt jêh ri mih.$b$,false),
('bunong-vn','ISA',5,1,null,$b$Ăn gâp mprơ ma nơm gâp rŏng du nau mprơ di ma đang play kriăk ƀâu păng. Nơm gâp rŏng geh du đang play kriăk ƀâu ta gôl jêng ngăn, jêh ri tăm tơm play kriăk ƀâu ueh lơn.$b$,true),
('bunong-vn','ISA',5,2,null,$b$Păng rdâk du rplay ngih tŭm ta nklang păng jêh ri kuyh ntu iet play. Păng kâp gân ma păng geh play ueh, ƀiă lah păng geh knŏng play mhĭk.$b$,false),
('bunong-vn','ISA',5,3,null,$b$Pô ri aƀaơ aơ, Ơ phung gŭ tâm ƀon Yêrusalem jêh ri phung bu klâu bri Yuđa, phat hom dôih gâp đah đang play kriăk ƀâu gâp.$b$,true),
('bunong-vn','ISA',5,4,null,$b$Moh nau khlay hôm tâm đang play kriăk ƀâu gâp, gâp mâu hŏ ƀư an ma păng ôh? Dôl gâp kâp gân ma păng mra geh play ueh mâm păng geh hĕ play mhĭk?$b$,false),
('bunong-vn','ISA',5,5,null,$b$Pô ri aƀaơ aơ gâp mra mbơh ma may nau gâp mra ƀư ma đang play kriăk ƀâu gâp. Gâp mra rôk lơi n'gar păng, jêh ri mpô mpa mra păng lĕ rngôch. Gâp mra ƀư rlâm lơi n'gar păng, jêh ri bu mra jot lơi păng.$b$,true),
('bunong-vn','ISA',5,6,null,$b$Gâp mra ăn păng rai, bu mâu mra nkra n'gĭng, mâu hôm brôi tơm păng ôh, rtau lok jêh ri lok tơm mra hon ta nây. Jêh ri gâp mra ntăm ma tŭk mâu hôm ăn dak mih ma păng ôh.$b$,true),
('bunong-vn','ISA',5,7,null,$b$Đang play kriăk ƀâu Yêhôva ma phung ta han jêng ngih Israel, jêh ri phung bu klâu Yuđa jêng ndơ ueh păng tăm. Păng kâp gân geh nau sŏng, ƀiă lah aơ, bu ƀư pling mham jêh, jêh ri păng kâp gân ma nau sŏng srăng, ƀiă lah aơ, geh nau nter nđêng. Nau rêh ni mbơh jêh ma phung ƀai.$b$,true),
('bunong-vn','ISA',5,8,null,$b$Rêh ni ngăn ma phung rdâk ngih dăch đah du rplay mir êng kŏ mâu hôm geh ntŭk ôh jêh ri bu ăn khân may gŭ êng ta nklang bri.$b$,true),
('bunong-vn','ISA',5,9,null,$b$Yêhôva ma phung ta han lah jêh ma tôr gâp: “Na nê̆ âk rplay ngih mra jêng rngol, ngih toyh jêh ri ueh mâu hôm geh bunuyh gŭ ôh.$b$,true),
('bunong-vn','ISA',5,10,null,$b$Jât hectar đang play kriăk ƀâu mra geh du bat, jêh ri du ôm er ntil mra geh knŏng du êpha.”$b$,false),
('bunong-vn','ISA',5,11,null,$b$Rêh ni ngăn ma phung kah rngăl gay tĭng joi ndrănh gŭ nhêt kŏ tât măng kŏ dak play kriăk ƀâu srŏng khân păng.$b$,false),
('bunong-vn','ISA',5,12,null,$b$Khân păng geh n'hôm jêh ri gong rêng, gong, jêh ri rlet, jêh ri dak play kriăk ƀâu tâm nau khân păng nhêt sông, ƀiă lah khân păng mâu chrê ma kan Yêhôva ôh, mâu lĕ saơ kan ti păng ƀư.$b$,false),
('bunong-vn','ISA',5,13,null,$b$Yor pưt nau blau mĭn phung ƀon lan gâp mra hăn jêng bu nă. Phung bu yơk tâm khân păng khĭt rvet, jêh ri phung âk khân păng kroh ko ma nau ji hir.$b$,false),
('bunong-vn','ISA',5,14,null,$b$Yor nây ƀon phung khĭt kâp sa khân păng, jêh ri hă ăn huy mbung păng rlau keh. Phung kôranh jêh ri phung ƀon lan ƀon Siôn trŭnh hăn ta nây, lĕ rngôch phung âk nđâp phung sưr tŭp tâm nây.$b$,false),
('bunong-vn','ISA',5,15,null,$b$Phung ƀon lan toyh nđâp jê̆ mra ra ai nuih n'hâm, măt phung sưr bu tâm njŭr.$b$,true),
('bunong-vn','ISA',5,16,null,$b$Ƀiă lah Yêhôva ma phung ka han geh nau n'hao tâm nau sŏng, jêh ri Brah Ndu Kloh Ueh mra tâm mpơl păng nơm kloh ueh tâm nau sŏng srăng.$b$,true),
('bunong-vn','ISA',5,17,null,$b$Rnôk nây kon biăp mra sa gơ̆ nâm bu ndrêch gơ̆ khân păng nơm, jêh ri phung bu năch mra sa ta nklang ntŭk mir lĕ mƀăr phung ndrŏng.$b$,false),
('bunong-vn','ISA',5,18,null,$b$Rêh ni ngăn ma phung dŭng đŏt nau kue ma nau mƀruh jêh ri nchâp bu ƀư tih nâm bu ma rse biăt lui ndeh,$b$,true),
('bunong-vn','ISA',5,19,null,$b$khân păng, “Ăn Yêhôva ƀư ndal, ăn păng ƀư ndăn kan păng, gay ma he dơi saơ. Ăn nau Nơm Kloh Ueh Israel văch êp hom, gay ma he dơi gĭt nau nây.”$b$,false),
('bunong-vn','ISA',5,20,null,$b$Rêh ni ngăn ma phung rnha ntơ nau mhĭk jêng ueh, jêh ri nau ueh jêng mhĭk, phung kơp nau ngo nsro ma nau ang, jêh ri ang nsro ma nau ngo, phung ăn nau tăng nsro nau njŭng, jêh ri nau njŭng nsro nau tăng.$b$,true),
('bunong-vn','ISA',5,21,null,$b$Rêh ni ngăn ma phung kơp khân păng nơm jêng phung gĭt mĭn jêh ri kơp ma khân păng nơm jêng phung gĭt rbăng.$b$,false),
('bunong-vn','ISA',5,22,null,$b$Rêh ni ngăn ma phung dăng nhêt dak play kriăk ƀâu, jêh ri phung dăng nhêt ndrănh,$b$,true),
('bunong-vn','ISA',5,23,null,$b$Phung kơp sŏng nơm ƀai yor drăp blŏl, jêh ri dun ƀư nau di ma phung sŏng.$b$,false),
('bunong-vn','ISA',5,24,null,$b$Yor nây, tâm ban ma mpiăt ŭnh sa rhe, jêh ri tâm ban ma mpiăt ŭnh sa gơ̆ kro, tâm ban pô nây lĕ reh khân păng mra jêng tâm ban ma ndơ ôm rai, jêh ri kao khân păng mra nthông tâm ban ma ndruyh neh; yor lah khân păng dun jêh nau vay Yêhôva ma phung ta han jêh ri tâm rmot nau Nơm Kloh Ueh Israel ngơi.$b$,true),
('bunong-vn','ISA',5,25,null,$b$Yor nây nau Yêhôva ji nuih hit đah phung ƀon lan păng; păng yơr jêh ti tâm rdâng đah khân păng jêh ri dong khân păng. Yôk sâr n'gơ jêh ri săk jăn khĭt khân păng jêng tâm ban ma ndŏk ta nklang trong. Nđâp lah lĕ nau nây kđôi, ăt nau păng ji nuih ê teng ôh, ƀiă lah ti păng ăt hôm yơr ƀư ƀa ƀơ.$b$,true),
('bunong-vn','ISA',5,26,null,$b$Păng mra n'hao bok pla (bok kơ) ma phung ndŭl mpôl gŭ ngai jêh ri huăch kuăl khân păng bơh dŭt bri neh, jêh ri aơ, khân păng văch ma nau ndal, ngăch ngăn.$b$,true),
('bunong-vn','ISA',5,27,null,$b$Mâu geh du huê tâm khân păng mra rgănh, mâu lĕ geh du huê chêh, mâu geh nơm mra lâng săk bêch ôh. Rse bŭt khân păng mâu mra klaih ôh, rse ntâu jot khân păng mâu lĕ tăch.$b$,false),
('bunong-vn','ISA',5,28,null,$b$Hăr khân păng mplanh, jêh ri lĕ rngôch na khân păng van jêh. Nchop jâng seh khân păng jêng tâm ban ma lŭ, jêh ri jâng ndeh khân păng jêng tâm ban sial vănh blông$b$,false),
('bunong-vn','ISA',5,29,null,$b$Nau khân nter troh jêng tâm ban ma yau mŭr ngrông (ngŭr); khân păng nter tâm ban ma kon yau mŭr păng ngrông jêh ri kăp jun khân păng, khân păng djôt leo mpa khân păng kăp jêh, mâu geh nơm dơi nklaih ôh.$b$,false),
('bunong-vn','ISA',5,30,null,$b$Tâm nar nây khân păng mra ngrông (ngŭr) yor ma phung nây, tâm ban ma nteh dak mƀŭt. Tơ lah bu uănh ma bri neh, aơ nau ngo jêh ri nau uh ah, jêh ri ndâr nkŭm lơi nau ang păng.$b$,false),
('bunong-vn','ISA',6,1,null,$b$Năm Hađăch Usia khĭt, gâp saơ Kôranh Brah gŭ ta du mlâm sưng hađăch, n'hao prêh ngăn jêh ri bu yơk, jêh ri mbân ao jâr păng ƀư bêng ngih brah Yuđa.$b$,true),
('bunong-vn','ISA',6,2,null,$b$Phung Sêraphim gŭ ta klơ păng; ăp nơm khân păng geh prao plơp năr, bar plơp nkŭm muh măt, bar plơp nkŭm jâng jêh ri bar plơp prăp mpăr.$b$,false),
('bunong-vn','ISA',6,3,null,$b$Khân păng nter ndrăng khân păng, lah, “Kloh ueh, kloh ueh, kloh ueh yơh Yêhôva ma phung ta han, lĕ neh ntu bêng ma nau chrêk rmah păng.”$b$,false),
('bunong-vn','ISA',6,4,null,$b$Mbon mpông sâr n'gơ yor bâr phung nter, jêh ri ngih brah bêng ma nhhŭk ŭnh.$b$,true),
('bunong-vn','ISA',6,5,null,$b$Gâp lah, “Rêh ni ngăn ma gâp! Gâp roh jêh; Yor lah gâp jêng bunuyh geh mpiăt ƀơ̆ ƀơch, gâp gŭ rêh ta nklang du phung ƀon lan geh mpiăt ƀơ̆ ƀơch, yor lah măt gâp saơ jêh Hađăch, Yêhôva ma phung ta han !”$b$,true),
('bunong-vn','ISA',6,6,null,$b$Rnôk nây phung Sêraphim mpăr văch ta gâp djôt ŭnh sa ônh păng sŏk tă bơh nơng ma nkăp jê̆.$b$,true),
('bunong-vn','ISA',6,7,null,$b$Păng rbot trôm mbung gâp ma ndơ nây jêh ri lah, “Ndơ aơ rbot jêh trôm mbung may; bu sŏk lơi jêh nau kue may jêh ri nau tih may yô̆ an jêh,”$b$,false),
('bunong-vn','ISA',6,8,null,$b$Jêh ri gâp tăng bâr Kôranh Brah lah, “Mbu nâm gâp mra prơh hăn? Mbu nâm mra hăn an ma he?” Rnôk nây gâp lah, “Ta aơ gâp, prơh hom gâp hăn.”$b$,true),
('bunong-vn','ISA',6,9,null,$b$Păng lah, “Hăn hom, lah ma phung ƀon lan aơ.” Iăt hom khân may, ƀiă lah mâu gĭt rbăng ôh?$b$,false),
('bunong-vn','ISA',6,10,null,$b$Ăn may ƀư dăng lơi nuih n'hâm phung ƀon lan aơ; ƀư jâk lơi trôm tôr khân păng, jêh ri ƀư nhêp lơi măt khân păng, klach lah khân păng saơ ma măt khân păng, tăng ma tôr khân păng, jêh ri nuih n'hâm khân păng gĭt rbăng, jêh ri khân păng plơ̆ sĭt jêh ri bu ƀư bah.”$b$,true),
('bunong-vn','ISA',6,11,null,$b$Rnôk nây gâp lah, “Ơ Kôranh Brah, ndah nâm jŏ?” Păng plơ̆ lah, “Kŏ âk ƀon toyh rai jêh, mâu geh bunuyh gŭ ôh, jêh ri mâu geh du huê gŭ tâm ngih ôh, jêh ri lĕ bri neh jêng rngol,$b$,true),
('bunong-vn','ISA',6,12,null,$b$Jêh ri Yêhôva nsot ngai phung bunuyh jêh ri ntŭk rngol mra jêng âk ta nklang bri neh.$b$,false),
('bunong-vn','ISA',6,13,null,$b$Nđâp tơ lah hôm ta nây du kô̆ tâm jât khân păng bu mra ƀư rai lơi păng ƀiă lah tâm ban ma tơm si têrêbin jêh ri tơm si sen ăt hôm knŏng yôk ngâl tơ lah jêh bu kăl tơm khân păng, ndŭl mpôl kloh ueh jêng yôk ngâl păng.$b$,false),
('bunong-vn','ISA',7,1,null,$b$Tâm rnôk Y-Ahas kon bu klâu Y-Jôham sau Y-Usia hađăch bri Yuđa, geh Y-Rêsin hađăch bri Siri ndrel ma Y-Pêka kon bu klâu Y-Rêmalia, hađăch bri Israel hăn hao ta ƀon Yêrusalem ŭch tâm lơh, ƀiă lah khân păng mâu dơi đah phung ƀon nây ôh.$b$,true),
('bunong-vn','ISA',7,2,null,$b$Tơ lah bu văch mbơh ta ngih Y-Đavit, lah, “Phung Siri tâm rnglăp jêh đah phung Êphraim,” nuih n'hâm păng nđâp ma nuih n'hâm phung ƀon lan păng râm sâr tâm ban ma tơm si tâm krŏng n'gơ ma sial.$b$,false),
('bunong-vn','ISA',7,3,null,$b$Yêhôva lah ma Y-Êsai, “Ăn may hăn tâm mâp đah Y-Ahas, may ndrel Y-Sêarjasup kon bu klâu may ta dŭt n'hor ta tu mbŏng dak ta trong mir phung ƀư kloh bok,$b$,true),
('bunong-vn','ISA',7,4,null,$b$Jêh ri lah ma păng, ‘Njrăng hom, gŭ đăp mpăn hom, lơi klach ôh, lơi ăn may ndje nuih n'hâm ôh yor bar mlâm yôk ngâl luh nhhŭk ŭnh nây, yor nau ji nuih ktang Y-Rêsin jêh ri bri Siri jêh ri kon bu klâu Y-Rêmalia.$b$,false),
('bunong-vn','ISA',7,5,null,$b$Yor lah phung Siri ndrel ma phung Êphraim jêh ri kon bu klâu Y-Rêmalia mĭn ŭch ƀư mhĭk ma may, lah,$b$,false),
('bunong-vn','ISA',7,6,null,$b$“Ăn hao hom ƀư ma bri Yuđa, rkhŭk păng, jêh ri sŏk tâm pă bri nây ma he nơm, jêh ri njêng kon bu klâu Y-Tabel hađăch ta nklang păng.”$b$,false),
('bunong-vn','ISA',7,7,null,$b$Pô aơ nau Kôranh Brah Yêhôva lah, “Nau nây mâu mra jêng jêh ri mâu mra tât ôh.$b$,false),
('bunong-vn','ISA',7,8,null,$b$Yor lah bôk ma bri Siri jêng ƀon Damas, jêh ri bôk ƀon Damas jêng Y-Rêsin Tâm prao jât ma prăm năm phung Êphraim mra rai kŏ khân păng mâu hôm jêng du phung ƀon lan đŏng ôh.$b$,false),
('bunong-vn','ISA',7,9,null,$b$Bôk ma ƀon Êphraim jêng ƀon Samari, Jêh ri bôk ma Samari jêng kon bu klâu Y-Rêmalia Tơ lah may mâu iăt ôh, na nê̆ may mâu mra jêng nâp ôh.”$b$,false),
('bunong-vn','ISA',7,10,null,$b$Yêhôva ngơi tay đah Y-Ahas, lah,$b$,true),
('bunong-vn','ISA',7,11,null,$b$“Dăn hom du nau tâm mbên bơh Yêhôva Brah Ndu may; dăn nau jru tâm ban ma Ƀon phung khĭt mâu lah prêh tâm ban ma trôk.”$b$,false),
('bunong-vn','ISA',7,12,null,$b$Ƀiă lah Y-Ahas lah, “Gâp mâu mra dăn ôh, mâu lĕ gâp rlong uănh Yêhôva.”$b$,false),
('bunong-vn','ISA',7,13,null,$b$Y-Êsai lah, “Hơi ngih Y-Đavit, iăt hom, jêng du nau jê̆ ir ma khân may mâm khân may ƀư rgănh phung bunuyh kŏ khân may ƀư rgănh Brah Ndu gâp tâm ban đŏng?$b$,true),
('bunong-vn','ISA',7,14,null,$b$Yor nây Kôranh Brah nơm mra ăn du nau tâm mbên ma khân may: Aơ, du huê bu ur druh mra ntreo jêh ri deh ma du huê kon bu klâu. Păng mra ntơ amoh kon nây Êmanuel. Nâm bu ntĭt: Brah Ndu gŭ ndrel ma he’$b$,true),
('bunong-vn','ISA',7,15,null,$b$Păng mra sa glo dak toh ndrôk jêh ri dak sŭt, tơ lah păng blau dun nau mhĭk jêh ri săch nau ueh.$b$,false),
('bunong-vn','ISA',7,16,null,$b$Yor lah lor ma kon nây blau dun nau mhĭk jêh ri săch nau ueh, bri neh geh bar hê hađăch may klach nây mra jêng rngol.$b$,false),
('bunong-vn','ISA',7,17,null,$b$Yêhôva mra ăn tât ma may, ma phung ƀon lan may, jêh ri ma ngih mbơ̆ may du rnôk ê mâp tât ôh ntơm bơh nar phung Êphraim tâm nkhah đah phung Yuđa, nâm bu ntĭt hađăch bri Asiri.”$b$,true),
('bunong-vn','ISA',7,18,null,$b$Tâm nar nây Yêhôva mra kuăl huăch rhuay gŭ ta tu dak krong bri Êjipt jêh ri sŭt bơh bri Asiri.$b$,false),
('bunong-vn','ISA',7,19,null,$b$Lĕ rngôch khân păng mra văch jêh ri gŭ tâm trâp, tâm nđa lŭ đang, ta lĕ rngôch pôm lok jêh ri ta lĕ rngôch ndrêch gơ̆ dŏng.$b$,false),
('bunong-vn','ISA',7,20,null,$b$Tâm nar Kôranh Brah mra pêih poih păng nkhôm bu mpeh đah rĭ dak krong, nâm bu ntĭt đah hađăch bri Asiri, bôk jêh ri rsau jâng khân may; păng mra poih nđâp ma têp kang khân may tâm ban lĕ.$b$,true),
('bunong-vn','ISA',7,21,null,$b$Tâm nar nây bu mra rong du mlâm ndrôk me jêh ri bar mlâm biăp me;$b$,false),
('bunong-vn','ISA',7,22,null,$b$Jêh ri yor khân păng mra ăn âk ngăn dâk toh, păng mra sa glo dak toh; yor lah lĕ rngôch phung hôm klen tâm bri mra sa glo dak toh jêh ri dak sŭt.$b$,false),
('bunong-vn','ISA',7,23,null,$b$Tâm nar nây ta ăp ntŭk geh du rbăn tơm play kriăk ƀâu, rnoh klăp du rbăn sêkel prăk mra plăch jêng rtau lok jêh ri tơm lok.$b$,true),
('bunong-vn','ISA',7,24,null,$b$Bu mra văch ta nây ma hăr jêh ri na, yor lah lĕ bri geh knŏng rtau lok jêh ri tơm lok.$b$,true),
('bunong-vn','ISA',7,25,null,$b$Jêh ri lĕ rngôch gôl bu hŏ kuyh chôk ma ndroh kăl e, bu mâu mra hăn ta nây ôh klach ma rtau lok jêh ri tơm lok; ƀiă lah bu mra prăp mƀơk ndrôk ta nây jêh ri ăn biăp jot ntŭk nây.$b$,true),
('bunong-vn','ISA',8,1,null,$b$Yêhôva lah ma gâp, “Sŏk hom du pŏk kađar toyh jêh ri chih ta nây nau chih bunuyh dơi gĭt rbăng. Y-Maher-Salal-has- bas “(nâm bu ntĭt: Sŏk pit gơnh, sŏk ndăn rơ)”$b$,true),
('bunong-vn','ISA',8,2,null,$b$Jêh ri gâp mbơh phung sŏk răp jăp, kôranh ƀư brah Y-Uri jêh ri Y-Sakari kon bu klâu Y-Yêbêrêkia ŭch jêng phung mbơh ăn na nê̆.$b$,false),
('bunong-vn','ISA',8,3,null,$b$Jêh ri gâp hăn gŭ ndrel ma kôranh nơm-mbơh-lor bu ur, păng ntreo jêh ri deh ma du huê kon bu klâu. Yêhôva lah ma gâp, “Tâm amoh păng Y-Maher-Sapal-Has-Bas;$b$,false),
('bunong-vn','ISA',8,4,null,$b$Yor lah lor ma kon se nây gĭt kuăl, ‘Mbơ̆ gâp,’ mâu lah, ‘Mê̆ gâp,’ bu mra njŭn leo ma hađăch Asiri nau ndrŏng ƀon Damas jêh ri ndơ pit sŏk bơh ƀon Samari.”$b$,false),
('bunong-vn','ISA',8,5,null,$b$Yêhôva lah đŏng ma gâp:$b$,true),
('bunong-vn','ISA',8,6,null,$b$“Yor lah phung ƀon lan aơ dun ma dak Silôê kloh đăp mpăn, jêh ri hâk maak yor Y-Rêsin jêh ri kon bu klâu Y-Remalia,$b$,false),
('bunong-vn','ISA',8,7,null,$b$Yor nây aƀaơ aơ Kôranh Brah n'hao toyh dak lip bơh dak krong ktang jêh ri âk văch tâm rdâng đah khân păng, nâm bu ntĭt hađăch bri Asiri ndrel ma lĕ nau chrêk rmah păng. Dak krong mra hao lêng lam bơh tâm nklang păng jêh ri ler lĕ rngôch kơh păng.$b$,false),
('bunong-vn','ISA',8,8,null,$b$Păng mra n'ho hoch lăp tâm bri Yuđa, păng mra ler kơh rlêng băm trô-ko, jêh ri mra bêng lĕ bri neh may, Ơ Êmanuel.”$b$,false),
('bunong-vn','ISA',8,9,null,$b$Ơ phung ƀon lan ăn khân may rngot jêh ri ioh nuih n'hâm. Ơ lĕ rngôch bri ngai, rkêng hom tôr. Rêt hom rse bŭt jêh ri geh nau rngot; rêt hom rse bŭt jêh ri geh nau ioh nuih n'hâm.$b$,true),
('bunong-vn','ISA',8,10,null,$b$Tâm nchră hom ndrăng khân may, ƀiă lah nau nây mra jêng dơm dam. Nkra dăp kan ƀư, ƀiă lah nau nây mâu mra gŭ nâp ôh, yor lah Brah Ndu gŭ ndrel ma hên.$b$,false),
('bunong-vn','ISA',8,11,null,$b$Yêhôva ngơi pô nây jêh ri pah ti ktang ta gâp, jêh ri ntăm jêh ma gâp, lơi hăn ôh tâm trong phung ƀon lan aơ, lah:$b$,true),
('bunong-vn','ISA',8,12,null,$b$“Lơi rnha ôh nau tâm rdâng ma lĕ rngôch nau phung ƀon lan aơ mra rnha nau tâm rdâng; jêh ri lơi klach ôh nau khân păng klach, mâu lĕ râm sâr.$b$,false),
('bunong-vn','ISA',8,13,null,$b$Ƀiă lah ăn khân may kơp Yêhôva ma phung ta han kloh ueh. Ăn păng jêng nơm khân may klach, jêh ri nơm khân may râm sâr.$b$,false),
('bunong-vn','ISA',8,14,null,$b$Păng mra jêng du ntŭk kloh ueh, du mlâm lŭ chêh jâng bu, jêh ri lŭ toyh ƀư prah ma lĕ bar đah ndŭl mpôl Israel, yŭ jêh ri dăk sân ma phung gŭ tâm ƀon Yêrusalem.$b$,false),
('bunong-vn','ISA',8,15,null,$b$Jêh ri âk bunuyh mra chêh ta nây; khân păng mra prah jêh ri chah, khân păng mra geh dăk jêh ri bu mra nhŭp.”$b$,false),
('bunong-vn','ISA',8,16,null,$b$Klôt nklâm hom nau mbơh, tâp pŏng hom nau nti ta nklang phung oh mon gâp.$b$,true),
('bunong-vn','ISA',8,17,null,$b$Gâp mra gŭ kâp Yêhôva, nơm pôn muh măt păng bơh ngih Yakôb, jêh ri gâp mra kâp gân păng.$b$,true),
('bunong-vn','ISA',8,18,null,$b$Aơ, gâp jêh ri phung kon Yêhôva ăn jêh ma gâp jêng nau tâm mbên jêh ri nau tâm ntĭt tâm bri Israel bơh Yêhôva ma phung ta han, nơm gŭ ta yôk Siôn$b$,false),
('bunong-vn','ISA',8,19,null,$b$Jêh ri tơ lah khân păng mra lah ma khân may, “Ăn khân may sek ôp phung ngơi đah phung khĭt jêh ri phung rƀên, phung ngơi tâm ban ma sĭm nhhiăng jêh ri ngơi mâu ntoh ôh.” Mâu di hĕ phung ƀon lan bu ôp ma Brah Ndu khân păng? Di lĕ bu mra joi ôp phung khĭt jêh ŭch gĭt nau di ma phung rêh?$b$,false),
('bunong-vn','ISA',8,20,null,$b$Sek hom nau nti jêh ri nau mbơh! Tơ lah khân păng ngơi mâu di nâm bu nau ngơi aơ, khân păng mâu geh nau ang ôh.$b$,false),
('bunong-vn','ISA',8,21,null,$b$Khân păng mra nsong rgăn tâm bri, uh ah ngăn jêh ri ji ngot. Tơ lah khân păng ji ngot, khân păng mra ji nuih jêh ri n'gơr uănh ta klơ jêh ri rtăp rak hađăch khân păng jêh ri ma Brah Ndu khân păng.$b$,false),
('bunong-vn','ISA',8,22,null,$b$Jêh ri khân păng mra uănh ta neh ntu, ƀiă lah aơ, geh knŏng nau uh ah, jêh ri nau ngo, nau rngot klâng, jêh ri bu mra dŏt mƀăr khân păng tâm nau ngo mbâl.$b$,false),
('bunong-vn','ISA',9,1,null,$b$Ƀiă lah mâu mra geh nau ngo ôh ma phung geh jêh nau rngot klâng. Tâm rnôk lor păng ăn bu tâm rmot ma bri Sabulôn jêh ri bri Naptali, ƀiă lah tâm rnôk lôch dŭt păng mra ăn nau chrêk rmah ma bri rgŏ dak mƀŭt, bri đah rĭ dak krong Yurdan, bri Galilê prăp ma phung bu năch.$b$,true),
('bunong-vn','ISA',9,2,null,$b$Phung ƀon lan hăn jêh tâm nau ngo saơ jêng nau ang toyh nau ang nchrat jêh ma phung gŭ tâm bri ngo klĕng.$b$,true),
('bunong-vn','ISA',9,3,null,$b$May ăn bĭk rơ̆ jêh bri nây, may n'hao jêh nau hâk maak ma păng. Khân păng hâk maak ta năp may tâm ban ma bu hâk maak yan rek, tâm ban ma bu hâk maak tơ lah tâm pă ndơ pit in$b$,true),
('bunong-vn','ISA',9,4,null,$b$Yor lah may ƀư deh jêh tâm ban ma nar Midian, knŏng nau jâk păng, mâng kât ta săng nglik păng, jêh ri mâng nê̆ nơm tŭn jot păng.$b$,false),
('bunong-vn','ISA',9,5,null,$b$Yor lah lĕ rngôch ndrom jâng phung ta han soh tâm nau tâm lơh, jêh ri lĕ kho ao mprănh mham bu mra prăp ma ndơ ŭnh sa.$b$,true),
('bunong-vn','ISA',9,6,null,$b$Yor lah bu deh jêh ma he du huê kon, bu ăn jêh ma he du huê kon bu klâu; jêh ri păng mra tuy nau chiă uănh. Jêh ri bu mra rnha amoh păng, jêng Nơm Khlay Ngăn, jêng Nơm Nchră, jêng Brah Ndu, jêng Mbơ̆ N'ho ro, jêng Kôranh Brah Đăp Mpăn.$b$,false),
('bunong-vn','ISA',9,7,null,$b$Mâu mra blau lôch ôh ma nau geh jêng nau păng chiă uănh jêh ri nau đăp mpăn, ta sưng hađăch Y-Đavit jêh ri ma ƀon bri hađăch păng, ƀư ăn nâp njêng păng ma nau di jêh ri ma nau sŏng srăng bơh nar nây tât ƀa ƀơ n'ho ro. Nau gơih nđơr Yêhôva ma phung ta han mra ƀư nau nây!$b$,true),
('bunong-vn','ISA',9,8,null,$b$Kôranh Brah njuăl du rplay ngơi tâm rdâng đah phung Yakôb, jêh ri nau ngơi nây tŭp ta ngih phung Israel.$b$,false),
('bunong-vn','ISA',9,9,null,$b$Lĕ rngôch phung ƀon lan mra gĭt, phung Êphraim jêh ri phung gŭ tâm ƀon Samari, phung lah ma nau sưr jêh ri ma nuih n'hâm janh:$b$,false),
('bunong-vn','ISA',9,10,null,$b$“Glo neh uk rlâm jêh, ƀiă lah he mra rdâk ma lŭ trah; bu kăl jêh tơm si Sikamôr, ƀiă lah he mra dơm si Sêdar ta ntŭk khân păng.”$b$,false),
('bunong-vn','ISA',9,11,null,$b$Yor nây Yêhôva mra n'hao phung rlăng bơh Y-Rêsin ƀư ma khân păng, jêh ri păng mra nsônh phung rlăng khân păng.$b$,false),
('bunong-vn','ISA',9,12,null,$b$Phung Siri pa lơ jêh ri phung Philistin pa dâng, mra ha trôm mbung rvăn sa phung Israel. Nđâp lĕ nau nây kđôi; nau păng ji nuih mâu du ôh, ƀiă lah ti păng ăt hôm yơr ƀư mro.$b$,true),
('bunong-vn','ISA',9,13,null,$b$Phung ƀon lan mâu sĭt ôh ma nơm dong khân păng, mâu lĕ khân păng joi Yêhôva ma phung ta han.$b$,false),
('bunong-vn','ISA',9,14,null,$b$Yor nây Yêhôva mra koh lơi bơh phung Israel bôk jêh ri chiăng, n'gĭng play đung jêh ri mbêng dak tâm du nar.$b$,false),
('bunong-vn','ISA',9,15,null,$b$Bu bŭnh bu ranh jêh ri nơm bu yơk jêng bôk jêh ri Kôranh nơm mbơh lor nti lah nau mƀruh jêng$b$,false),
('bunong-vn','ISA',9,16,null,$b$Yor lah phung leo gai phung ƀon lan aơ ƀư ăn khân păng nhhơt trong, jêh ri phung njŭn khân păng lĕ roh rai jêh.$b$,false),
('bunong-vn','ISA',9,17,null,$b$Yor nây Kôranh Brah mâu maak ôh đah phung bu klâu ndăm khân păng, mâu lĕ khân păng yô̆ ma kon đơi khĭt mbơ̆ jêh ri phung bu ur ndrô sai khân păng. Yor lah ăp nơm jêng phung mâu blau yơk ma Brah Ndu ôh, jêh ri phung ƀư ƀai, jêh ri lĕ rngôch trôm mbung ngơi ma nau rluk. Nđâp lĕ nau nây kđôi lĕ, nau păng ji nuih mâu du ôh, ƀiă lah ti păng ăt yơr ƀư mro.$b$,true),
('bunong-vn','ISA',9,18,null,$b$Yor lah nau ƀai sa tâm ban ma ŭnh, păng sa rtau lok jêh ri tơm lok, păng sa krŏng mbâl, tă bơh nây nhhŭk ŭnh hao leo klơ.$b$,true),
('bunong-vn','ISA',9,19,null,$b$Ŭnh sa bri yor nau Yêhôva ma phung ta han ji nuih, jêh ri phung ƀon lan jêng tâm ban ma ndơ ŭnh sa. Mâu geh du huê nhhuach ma oh nâu păng ôh.$b$,true),
('bunong-vn','ISA',9,20,null,$b$Khân păng sŏk ndơ pa ma, ƀiă lah ât ji ngot; khân păng sa ndơ pa chiau, ƀiă lah mâu hôm ôh. Ăp nơm sa nglay săk kon păng nơm.$b$,false),
('bunong-vn','ISA',9,21,null,$b$Phung Manasê kăp sa phung Êphraim, phung Êphraim kăp sa phung Manasê, jêh ri ndrel n'grŭp khân păng ƀư ma phung Yuđa. Nđâp ma lĕ nau nây kđôi, nau păng ji nuih mâu du ôh, ƀiă lah ti ăt yơr ƀư mro.$b$,true),
('bunong-vn','ISA',10,1,null,$b$Rêh ni ngăn ma phung ƀư nau ntăm kue, jêh ri ma phung chih nau vay tŭn jot.$b$,true),
('bunong-vn','ISA',10,2,null,$b$Ŭch dun nau sŏng ma phung pưt, jêh ri mâu ƀư nau di ôh ma phung o-ach tâm phung ƀon lan gâp, gay sŏk pit ndơ phung bu ur ndrô sai jêh ri sŏk pit ndơ phung kon đơi khĭt mbơ̆ .$b$,false),
('bunong-vn','ISA',10,3,null,$b$Moh khân may mra ƀư ta nar nau tâm rmal, tơ lah nau ƀư rai tât ma khân may bơh ngai? Ma mbu nâm khân may mra du hăn gay geh nau kơl, jêh ri ta ntŭk khân may mra-lơi nau ndrŏng khân may?$b$,false),
('bunong-vn','ISA',10,4,null,$b$Hôm knŏng dơi păn ta nklang phung bu-nă, mâu lah cha lôt ndrel ma phung khĭt, Nđâp ma lĕ nau nây kđôi, nau păng ji nuih mâu du ôh, ƀiă lah ti păng ăt hôm yơr ƀư mro.$b$,false),
('bunong-vn','ISA',10,5,null,$b$Rêh ni ngăn ma hađăch Asiri, mâng nê̆ nau gâp ji nuih, nơm djôt mâng tak jra nau gâp ji nuih!$b$,true),
('bunong-vn','ISA',10,6,null,$b$Gâp mprơh păng hăn ƀư ma ndŭl mpôl mâu blau yơk ma Brah Ndu ôh, gâp ntăm păng hăn tâm rdâng đah phung ƀon lan ăn gâp ji nuih, gay sŏk pit jêh ri pit ndô ndơ, jêh ri jot khân păng tâm ban ma neh bŏk ta trong.$b$,false),
('bunong-vn','ISA',10,7,null,$b$Ƀiă lah hađăch Asiri mâu nkra ƀư pô nây ôh, mâu lĕ mâp mĭn ƀư pô nây. Ƀiă lah păng mĭn tâm nuih n'hâm păng ma nau ƀư rai, gay ma ngroh âk ndŭl mpôl phung bunuyh.$b$,false),
('bunong-vn','ISA',10,8,null,$b$Yor lah păng lah, “Mâu di hĕ lĕ rngôch kôranh ta han gâp jêng phung hađăch?$b$,false),
('bunong-vn','ISA',10,9,null,$b$Mâu di hĕ ƀon Kalnô jêng tâm ban ma ƀon Karkêmis, ƀon Hamat jêng tâm ban ma ƀon Arpat, ƀon Samari jêng tơm ban ma ƀon Damas?$b$,false),
('bunong-vn','ISA',10,10,null,$b$Tâm ban ma ti gâp ƀư jêh ma ƀon bri hađăch kôranh ma rup brah tâm ƀon Yêrusalem jêh ri ƀon Samari,$b$,false),
('bunong-vn','ISA',10,11,null,$b$Mâu di hĕ gâp mra ƀư ma ƀon Yêrusalem jêh ri ma rup brah păng tâm ban ma gâp ƀư jêh ma ƀon Samari jêh ri ma rup brah păng?”$b$,false),
('bunong-vn','ISA',10,12,null,$b$Tơ lah Kôranh Brah mra ƀư jêh lĕ kan păng ta yôk Siôn jêh ri ta ƀon Yêrusalem, Păng mra tâm rmal nau hađăch Asiri tâm rnê ma păng nơm tâm nuih n'hâm sưr păng.$b$,true),
('bunong-vn','ISA',10,13,null,$b$Yor lah hađăch Asiri lah, “Gâp ƀư lĕ nau nây ma nau ktang tâm ti gâp, jêh ri ma nau blau mĭn gâp yor lah gâp geh nau gĭt rbăng. Gâp trơn tĭt jêh n'har neh phung ndŭl mpôl bunuyh, jêh ri pit in drăp ndơ khân păng. Tâm ban ma du huê janh ktang gâp n'glưh jêh phung gŭ ta sưng hađăch.$b$,true),
('bunong-vn','ISA',10,14,null,$b$Ti gâp sŏk jêh drăp phung mpôl băl bunuyh, tâm ban ma tă bơh rsuăn sĭm; jêh ri tâm ban ma bu dônh sŏk tăp iăr me cha lơi jêh, tâm ban pô nây lĕ gâp dônh sŏk jêh neh ntu. Mâu geh mpât năr, mâu lah ha trôm mbung, mâu lah huôch ôh.”$b$,false),
('bunong-vn','ISA',10,15,null,$b$Sung mra tâm rnê lĕ ma păng nơm rlau lơn ma nơm dŏng păng? Tâm ban mâng rnê̆ ƀư mpât nơm yơk păng, mâu lah tâm ban ma mâng tak jra dôl ti nơm djôt tak jra!$b$,true),
('bunong-vn','ISA',10,16,null,$b$Yor nây, Kôranh Brah Yêhôva ma phung ta han mra njuăl nau ji ma phung ta han janh ktang păng, jêh ri tâm dâng nau chrêk rmah păng bu mra sênh ŭnh ăn sa păng.$b$,false),
('bunong-vn','ISA',10,17,null,$b$Nau ang phung Israel mra jêng ŭnh, jêh ri Nơm Kloh Ueh khân păng mra jêng mpiăt ŭnh, jêh ri sa rtau lok jêh ri tơm lok păng knŏng tâm du nar.$b$,false),
('bunong-vn','ISA',10,18,null,$b$Ŭnh mra sa nau ueh krŏng jêh ri mir păng play âk, nđâp ma huêng jêh ri săk jăn; nau nây mra jêng tâm ban ma du huê bunuyh ji dăch$b$,false),
('bunong-vn','ISA',10,19,null,$b$Đơ si hôm tâm krŏng păng mra jêng djê̆, kŏ du huê kon se dơi chih rnoh âk păng.$b$,false),
('bunong-vn','ISA',10,20,null,$b$Tâm nar đơ rnoh phung Israel hôm jêh ri đơ phung klaih tâm ngih Yakôb mâu hôm lŏ rnơm đŏng ôh ma phung dong khân păng, ƀiă lah mra rnơm ngăn ma Yêhôva, Nơm Kloh Ueh Israel.$b$,true),
('bunong-vn','ISA',10,21,null,$b$Du kô̆ mra sĭt ma Brah Ndu nau brah, du kô̆ bơh phung Yakôb.$b$,false),
('bunong-vn','ISA',10,22,null,$b$Nđâp tơ lah phung ƀon lan may Israel mra jêng âk tâm ban ma choih tâm dak mƀŭt, knŏng du kô̆ khân păng mra plơ̆ sĭt. Bu tâm nal jêh nau ƀư rai kŏ ƀư rai ma nau sŏng srăng.$b$,true),
('bunong-vn','ISA',10,23,null,$b$Yor lah kô ranh Brah Yêhôva ma phung ta han mra ăn lôch lĕ tĭng nâm nau tâm nal jêh ta nklang neh ntu.$b$,false),
('bunong-vn','ISA',10,24,null,$b$Yor nây kô ranh Brah Yêhôva ma phung ta han lah pô aơ: “Ơ phung ƀon lan gâp gŭ tâm ƀon Siôn, lơi klach ôh ma phung Asiri tơ lah, khân păng dong khân may ma mâng rvĕ jêh ri yơr mâng rvĕ khân păng ƀư ma khân may tâm ban ma phung Êjipt ƀư jêh.$b$,true),
('bunong-vn','ISA',10,25,null,$b$Yor lah hôm knŏng djê̆ dơm nau gâp ji nuih ma khân may mra bah, jêh ri nau gâp ji nuih mra plơ̆ ƀư rai khân păng.$b$,true),
('bunong-vn','ISA',10,26,null,$b$Yêhôva ma phung ta han mra ƀư ma khân păng tâm ban ma păng sreh nkhĭt phung Midian ta lŭ Ôrep; jêh ri păng mra yơr mâng nê̆ păng ta klơ dak mƀŭt, tâm ban ma păng ƀư jêh ma phung Êjipt.$b$,false),
('bunong-vn','ISA',10,27,null,$b$Tâm nar nây păng mra sŏk lơi ndơ jâk păng bơh săng nglik khân may jêh ri ƀư rai mâng rnŏng păng tă trô-ko khân may; mâng rnŏng mra deh yor lah khân may jêng lay jêh.$b$,false),
('bunong-vn','ISA',10,28,null,$b$Păng tât jêh ta ƀon Ayat; Păng rgăn ƀon Migrôn, păng bun ndơ păng rƀên ta ƀon Mikmas.$b$,true),
('bunong-vn','ISA',10,29,null,$b$Khân păng rgăn trong vah vang bar gôl yôk; khân păng bêch ta ƀon Gêba; ƀon Rama râm sâr, phung ƀon lan Gêba ƀon Y-Sôl nchuăt du jêh.$b$,false),
('bunong-vn','ISA',10,30,null,$b$Nter ăn huy, Ơ kon bu ur ƀon Galim! Gŭ iăt hom, Ơ ƀon Laisa jêh ri ƀon Anathôt!$b$,false),
('bunong-vn','ISA',10,31,null,$b$Ƀon Matmêna nkhah du; phung gŭ tâm ƀon Gêbim du jêh joi nau rnơm.$b$,false),
('bunong-vn','ISA',10,32,null,$b$Nar aơ yơh păng mra jưh ta ƀon Nôp. Păng mra rtuh ti păng ta yôk kon bu ur Siôn, gôl ƀon Yêrusalem.$b$,false),
('bunong-vn','ISA',10,33,null,$b$Aơ, Kôranh Brah Yêhôva ma phung ta han mra koh lơi n'gĭng ma nau nkrit; tơm si prêh lơn bu mra kăl, bu mra ntŭp tơm si nây.$b$,true),
('bunong-vn','ISA',10,34,null,$b$Păng mra kăl si toyh tâm krŏng ma sung, jêh ri bri Liban mra rlâm ta năp Nơm Brah.$b$,false),
('bunong-vn','ISA',11,1,null,$b$Du mlâm nkeh mra hon bơh tơm Y-Yêsê, jêh ri du mlâm N'gĭng mra hon bơh reh păng jêh ri play.$b$,true),
('bunong-vn','ISA',11,2,null,$b$Brah Huêng Ueh Yêhôva mra gŭ ta klơ păng, Brah Huêng Ueh nau njêh, jêh ri nau gĭt rbăng, Brah Huêng Ueh nau nchră jêh ri brah. Brah Huêng Ueh nau blau mĭn jêh ri nau klach yơk ma Yêhôva.$b$,false),
('bunong-vn','ISA',11,3,null,$b$Păng mra hâk maak tâm nau klach yơk ma Yêhôva. Păng mâu mra phat dôih tĭng nâm măt păng saơ ôh, mâu lĕ păng mra mĭn ŭch ƀư tĭng nâm tôr păng tăng.$b$,false),
('bunong-vn','ISA',11,4,null,$b$Ƀiă lah păng mra phat dôih phung pưt mpa ma nau sŏng srăng, păng mra mĭn ŭch ƀư nau di ma phung o-ach ta neh ntu. Păng mra dong neh ntu ma mâng nê̆ lah bơh trôm mbung păng, jêh ri ma n'hâm bơh trôm mbung păng, păng mra nkhĭt phung ƀai.$b$,false),
('bunong-vn','ISA',11,5,null,$b$Nau sŏng srăng mra jêng rse vân bŭt păng, jêh ri păng mra vân nau răp jăp.$b$,false),
('bunong-vn','ISA',11,6,null,$b$So bri mra gŭ ndrel ma kon biăp, jêh ri yau brăch mra gŭ rlu ndrel ma kon be, nđâp ma kon ndrôk. Yau mŭr, jêh ri mpô mpa rong mra gŭ ndrel, jêh ri du huê kon se jê̆ mra têk khân păng.$b$,true),
('bunong-vn','ISA',11,7,null,$b$Ndrôk me jêh ri kau mra sa gơ̆ ndrel, kon khân păng mra gŭ rlu ndrel jêh ri yau mŭr mra sa rhe tâm ban ma ndrôk sa rhe.$b$,false),
('bunong-vn','ISA',11,8,null,$b$Kon se gŭ pu toh mra pâl ta trôm bêh rmâng, jêh ri kon lơi jêh pu toh mra dơm ti păng ta trôm mbung bêh ŭnh.$b$,true),
('bunong-vn','ISA',11,9,null,$b$Khân păng mâu mra ƀư mhĭk ôh, mâu lĕ ƀư rai tâm lĕ yôk kloh ueh gâp, yor lah neh ntu mra bêng ma nau gĭt nal Yêhôva tâm ban ma dak nkŭm dak mƀŭt.$b$,false),
('bunong-vn','ISA',11,10,null,$b$Tâm nar nay reh Y-Yêsê mra gŭ ta nây tâm ban ma bok pla ma lĕ rngôch phung ƀon lan; phung ndŭl mpôl bunuyh mra joi păng, jêh ri ntŭk păng gŭ rlu mra geh nau chrêk rmah.$b$,true),
('bunong-vn','ISA',11,11,null,$b$Tâm nar nây Kôranh Brah mra yơr ti păng tal bar gay ma nsĭt rnoh phung ƀon lan păng hôm bơh bri Asiri, bri Êjipt, bri Patrôs, bri Êthiôpi, bri Êlam, bri Sinar, bri Hamat jêh ri bơh lĕ rngôch bri kơh dak mƀŭt.$b$,true),
('bunong-vn','ISA',11,12,null,$b$Păng mra n'hao bok pla ma phung ndŭl mpôl bunuyh, jêh ri rgum phung Israel bu nsot jêh; jêh ri păng mra tâm rƀŭn phung Yuđa nchah rai bơh puăn njônh neh ntu.$b$,false),
('bunong-vn','ISA',11,13,null,$b$Phung Êphraim mra roh nau nach, jêh ri bu mra ƀư rai lơi phung ƀư mhĭk ma phung Yuđa. Phung Êphraim mâu mra nach ma phung Yuđa ôh, jêh ri phung Yuđa mâu mra ƀư mhĭk ma phung Êphraim ôh.$b$,false),
('bunong-vn','ISA',11,14,null,$b$Ƀiă lah khân păng mra jŭr hăn ƀư ma phung Êphraim pa dâng; ndrel n'grŭp khân păng mra pit sŏk phung ƀon lan bri pa lơ. Khân păng mra yơr ti ƀư ma phung Êđôm jêh ri phung Môap, jêh ri phung Amôn mra tông ma khân păng$b$,false),
('bunong-vn','ISA',11,15,null,$b$Yêhôva mra ƀư rai lĕ dak mƀŭt bri Êjipt; păng mra yơr ti păng ta klơ dak krong ma sial duh. Păng mra dong tâm pă dak krong nây jêng pơh ntŭk dak n'hor kŏ bunuyh dơi hăn rgăn ma jâng mâu bĕ ôh.$b$,false),
('bunong-vn','ISA',11,16,null,$b$Jêh ri mra geh du trong toyh bơh bri Asiri prăp ma rnoh phung ƀon lan Yêhôva hôm, tâm ban hŏ mâp geh jêh ma phung Israel nar khân păng luh bơh bri Êjipt.$b$,false),
('bunong-vn','ISA',12,1,null,$b$Tâm nar nây may mra lah: “Gâp mra tâm rnê ma may, Ơ Yêhôva, yor lah nđâp tơ lah may ji nuih jêh ma gâp, nau may ji nuih lĕ bah jêh, jêh ri may bonh jêh gâp.$b$,true),
('bunong-vn','ISA',12,2,null,$b$Aơ, Brah Ndu jêng nơm tâm rklaih gâp, gâp mra rnơm jêh ri mâu klach ôh. Yêhôva Brah Ndu jêng nau ktang gâp jêh ri nau mprơ gâp, jêh ri păng jêng jêh nơm tâm rklaih gâp.”$b$,false),
('bunong-vn','ISA',12,3,null,$b$Ma nau hâk răm may mra bâk dak bơh ntu dak nau tâm rklaih.$b$,true),
('bunong-vn','ISA',12,4,null,$b$Tâm nar nây may mra lah; “Tâm rnê ma Yêhôva kuăl mbơh sơm ma amoh păng; nkoch bri hom kan păng ƀư ta nklang phung ndŭl mpôl bunuyh; mbơh hom amoh Yêhôva geh nau yơk.$b$,false),
('bunong-vn','ISA',12,5,null,$b$Mprơ tâm rnê hom ma Yêhôva yor lah păng ƀư jêh nau khlay; ăn bu gĭt năl nau nây lam bri neh.$b$,false),
('bunong-vn','ISA',12,6,null,$b$Nter huy jêh ri nter maak hom, Ơ phung gŭ tâm ƀon Siôn, yor lah Nơm Kloh Ueh Israel jêng toyh ta nklang khân may.”$b$,false),
('bunong-vn','ISA',13,1,null,$b$Nau Brah Ndu ngơi di ma bri Babilôn. Y-Êsai kon bu klâu Y-Amôt saơ jêh.$b$,true),
('bunong-vn','ISA',13,2,null,$b$N'hao hom bok pla ta klơ yôk hil, nter ăn huy ma khân păng, vơch ti jă khân păng lăp mpông pêr phung kôranh toyh$b$,false),
('bunong-vn','ISA',13,3,null,$b$Gâp nơm ntăm jêh ma phung kloh ueh gâp; gâp kuăl jêh phung bunuyh janh ktang, ăn khân păng ƀư tât nau gâp ji nuih, phung răm maak kâp ƀư nau gâp ŭch.$b$,false),
('bunong-vn','ISA',13,4,null,$b$Iăt hom, geh nau uh ah ta klơ yôk, tâm ban ma geh âk bunuyh! Iăt hom, âk ƀon bri hađăch drơu drơu, tâm ban ma phung bunuyh tâm rƀŭn ndrel n'grŭp! Yêhôva ma phung ta han tâm rƀŭn phung ta han ma nau tâm lơh.$b$,false),
('bunong-vn','ISA',13,5,null,$b$Yêhôva jêh ri phung păng đă ƀư tât nau păng ji nuih, văch bơh âk bri ngai, bơh dŭt trôk, gay ƀư rai lĕ bri.$b$,true),
('bunong-vn','ISA',13,6,null,$b$Nhĭm nhhiăng hom, yor lah nau Yêhôva dăch jêh; nar nây mra tât tâm ban ma nau ƀư rai bơh Nơm Geh Lĕ Nau Brah.$b$,true),
('bunong-vn','ISA',13,7,null,$b$Yor nây lĕ rngôch ti mra jêng ra ai, jêh ri nuih n'hâm ăp nơm bunuyh mra hŭch.$b$,false),
('bunong-vn','ISA',13,8,null,$b$Khân păng mra uh ah, nau ji ktang jêh ri nau rngot mra tât ma khân păng; khân păng mra gŭ ji tâm ban ma bu ur bêch veng ŭnh. Khân păng mra tâm uănh ndrăng khân păng nơm ma nau klach, muh măt khân păng mra jêng tâm ban ma ŭnh.$b$,false),
('bunong-vn','ISA',13,9,null,$b$Aơ, nar Yêhôva ntơm văch jêh, jêng nar mhĭk, ma nau ji nuih jêh ri ji nuih ktang, gay ăn bri neh jêng rngol, jêh ri ŭch ƀư rai phung tih bơh nây.$b$,false),
('bunong-vn','ISA',13,10,null,$b$Yor lah mănh tâm trôk jêh ri lĕ rngôch mănh ang tâm trôk, mâu mra sol nau ang ôh; nar mra jêng ngo tơ lah păng lah, jêh ri khay mâu hôm nchrat ang ôh.$b$,false),
('bunong-vn','ISA',13,11,null,$b$Gâp mra tâm rmal neh ntu yor nau mhĭk khân păng, jêh ri phung ƀai yor nau kue khân păng. Gâp mra ƀư lôch nau sưr phung rnam, jêh ri gâp mra ƀư roh nau sưr phung ƀư ƀai.$b$,true),
('bunong-vn','ISA',13,12,null,$b$Gâp mra ăn bunuyh ni lơn ma mah rhên, mpêt lơn ma mah chrêk bơh bri Ôphir.$b$,false),
('bunong-vn','ISA',13,13,null,$b$Yor nây gâp mra ăn trôk râm sâr, jêh ri neh ntu mra mpât n'gơ bơh ntŭk păng, yor nau Yêhôva ma phung ta han ji nuih, tâm nar nau păng ji nuih.$b$,false),
('bunong-vn','ISA',13,14,null,$b$Rnôk nây tâm ban ma du mlâm nkrŏng bu tĭng pănh, tâm ban ma phung biăp mâu geh nơm chiăp, ăp nơm mra sĭt ma phung ƀon lan păng nơm, ăp nơm mra du ta bri păng nơm.$b$,false),
('bunong-vn','ISA',13,15,null,$b$Bu mra ntâp bluh rho ăp nơm păng saơ, ăp nơm bu nhŭp mra khĭt ma đao.$b$,false),
('bunong-vn','ISA',13,16,null,$b$Bu mra mprah nkhĭt kon jê̆ khân păng ta năp măt khân păng nơm; bu mra sŏk pit ndơ tâm ngih khân păng, jêh ri bu tom ur khân păng.$b$,false),
('bunong-vn','ISA',13,17,null,$b$Aơ, gâp mra nsônh phung Mêdơ ƀư ma khân păng, phung nây mâu chrê ma prăk, jêh ri mâu rŏng ma mah ôh.$b$,false),
('bunong-vn','ISA',13,18,null,$b$Khân păng mra nkhĭt phung bu klâu ndăm ma na; khân păng mâu mra yô̆ ôh ma phung kon se oh-bê, măt khân păng mâu mra nhhuach ma phung kon se ôh.$b$,false),
('bunong-vn','ISA',13,19,null,$b$Jêh ri Babilôn, ƀon chrêk rmah lơn ma lĕ rngôch bri hađăch ƀon ueh nchrat phung Kaldê yơk, mra jêng tâm ban ma ƀon Sôdôm jêh ri ƀon Gômôrơ tơ lah Brah Ndu ƀư rai khân păng.$b$,false),
('bunong-vn','ISA',13,20,null,$b$Mâu mra geh bunuyh hôm gŭ tâm ƀon nây ôh, tâm lĕ rô̆. Phung Arap mâu mra rdâk ngih bok khân păng ta nây ôh; phung rmăk biăp mâu lĕ khân păng ăn biăp khân păng bêch ta nây.$b$,false),
('bunong-vn','ISA',13,21,null,$b$Ƀiă lah mpa bri mra bêch ta nây, ngih ƀon nây mra bêng ma klang kô, sĭm ôtrus mra gŭ ta nây, be bri mra pâl rlưn ta nây.$b$,false),
('bunong-vn','ISA',13,22,null,$b$So bri mra mblu tâm pôih ƀon nây, jêh ri so bri mra mblu tâm ngih hađăch ueh. Mông bu tâm nal ma păng dăch tât jêh, jêh ri bu mâu mra njong nar đŏng ôh.$b$,false),
('bunong-vn','ISA',14,1,null,$b$Yêhôva mra yô̆ ma phung Yakôp, jêh ri hôm du tơ̆ mra săch phung Israel, jêh ri mra dơm khân păng tâm bri khân păng nơm, phung bu năch mra tâm rnglăp đah khân păng jêh ri mra gŭ ndrel đah ngih brah Yakôp.$b$,true),
('bunong-vn','ISA',14,2,null,$b$Phung ndŭl mpôl bunuyh mra sŏk phung Israel jêh ri njŭn khân păng ta ntŭk khân păng nơm. Jêh ri ngih Israel mra dŏng khân păng tâm bri Yêhôva jêng oh mon bu klâu jêh ri bu ur. Phung Israel mra sŏk njêng bu nă phung hŏ njêng khân păng ƀư bu nă, jêh ri khân păng mra chiă uănh phung tŭn jot jêh khân păng.$b$,false),
('bunong-vn','ISA',14,3,null,$b$Tơ lah jêh Yêhôva ăn ma khân may nau rlu bơh nau khân may rêh ni jêh ri uh ah bơh kan ŏk rgănh bu ăn jêh ma khân may ƀư,$b$,true),
('bunong-vn','ISA',14,4,null,$b$khân may mra lah nau mưch aơ ma hađăch Babilôn: “Hih rhâl saơ nơm tŭn jot rlu jêh! Nơm nhhu nkrit rlu jêh!$b$,false),
('bunong-vn','ISA',14,5,null,$b$Yêhôva nkêch lơi jêh mâng mbăk phung ƀai, may hađăch phung chiă uănh,$b$,false),
('bunong-vn','ISA',14,6,null,$b$Phung dong jêh phung ƀon lan ma nau ji nuih mâu rlu ôh, phung chiă uănh phung ndŭl mpôl bunuyh ma nau ji nuih, ma nau ƀư mhĭk mro.$b$,false),
('bunong-vn','ISA',14,7,null,$b$Lĕ neh ntu gŭ rlu jêh ri đăp mpăn; khân păng mprơ ma nau răm maak.$b$,false),
('bunong-vn','ISA',14,8,null,$b$Tơm si n'ho răm maak yor may, tơm si Sêdar tâm bri Liban lah, “Bơh nar bu ăn may tŭp, mâu geh du huê nơm văch tât kăl hên ôh”$b$,false),
('bunong-vn','ISA',14,9,null,$b$Ƀon Phung Khĭt ŭch ngăn tâm mâp đah may tơ lah may tât. Păng rlay phung khĭt jêh ri chiă may, lĕ rngôch phung nây jêng jêh kôranh ta neh ntu. Păng yơk lĕ rngôch hađăch phung ndŭl mpôl bunuyh bơh sưng hađăch khân păng.$b$,true),
('bunong-vn','ISA',14,10,null,$b$Lĕ rngôch khân păng mra lah ma may, “Nđâp may tâm ban lĕ nkhơng jêng ra ai tâm ban ma hên; may jêng jêh tâm ban ma hên.”$b$,false),
('bunong-vn','ISA',14,11,null,$b$Bu njŭr jêh nau lư ueh rnam may ta Ƀon Phung Khĭt, ndrel ma nteh bâr gong rêng may. Rhai jêng sưng bêch may, jêh ri rhai jêng nah may ntâk.$b$,false),
('bunong-vn','ISA',14,12,null,$b$Hih rhâl saơ may tŭp jêh tă bơh trôk, Ơ mănh mbing, kon bu klâu ƀhit rvi Ang! Bu klŭp jêh may ta neh, Ơ nơm ƀư rai jêh phung ndŭl mpôl bunuyh!$b$,true),
('bunong-vn','ISA',14,13,null,$b$May lah jêh tâm nuih n'hâm may, “Gâp mra hao ta klơ trôk, gâp mra n'hao sưng hađăch gâp ta klơ lơn ma mănh Brah Ndu, gâp mra gŭ ta sưng hađăch ta klơ yôk nau tâm rƀŭn tâm nkual bôl dŭt ta dor.$b$,false),
('bunong-vn','ISA',14,14,null,$b$Gâp mra hao prêh lơn ma ndâr, gâp mra njêng gâp nơm tâm ban ma nơm klơ lơn.”$b$,false),
('bunong-vn','ISA',14,15,null,$b$Ƀiă lah bu njŭr jêh may ta Ƀon Phung Khĭt, ta nkual nglĕ dŭt Trôm Jru.$b$,false),
('bunong-vn','ISA',14,16,null,$b$Phung saơ may mra gŭ uănh ma may mâu mƀrêh măt ôh, jêh ri sek uănh nau tât ma may, “Di lĕ bunuyh aơ jêng nơm ăn neh ntu mpât n'gơ,$b$,true),
('bunong-vn','ISA',14,17,null,$b$Nơm rgu jêh âk ƀon hađăch, nơm ăn neh ntu jêng tâm ban ma bri rdah, ƀư rai jêh âk ƀon toyh păng, mâu mƀơk ôh phung bu năch păng sĭt ta ngih ô băl nơm?”$b$,false),
('bunong-vn','ISA',14,18,null,$b$Lĕ rngôch hađăch phung ndŭl mpôl bunuyh gŭ bêch tâm nau bu yơk, ăp nơm tâm môch păng nơm.$b$,false),
('bunong-vn','ISA',14,19,null,$b$Ƀiă lah bu mƀăr may pa dih jêh bơh môch may, tâm ban ma n'ging bu koh lơi jêh, ăn may gŭ ndrel ma phung bu nkhĭt, phung bu ntâp jêh ma đao, phung jŭr hăn jêh ta lŭ Trôm Jru. Tâm ban ma du săk jăn khĭt bu jot blên tâm dâng jâng,$b$,false),
('bunong-vn','ISA',14,20,null,$b$may mâu mra tâm rnglăp tâm môch ndrel ma khân păng ôh. Yor lah may ƀư rai jêh bri may, may nkhĭt jêh phung ƀon lan may. Lơi ăn bu kah gĭt ngơi ôh ma phung kon sau phung ƀư ƀai.$b$,false),
('bunong-vn','ISA',14,21,null,$b$Nkra hom ntŭk tâm nkhĭt ma phung kon bu klâu păng, yor nau kue phung che khân păng; lơi ăn khân păng plơ̆ dâk jêh ri sŏk pit neh ntu, jêh ri ăn bêng neh ntu ma ƀon toyh khân păng.$b$,false),
('bunong-vn','ISA',14,22,null,$b$“Gâp mra dâk ƀư ma khân păng.” Yêhôva ma phung ta han lah, “Gâp mra jut lơi amoh jêh ri phung hôm bơh ƀon Babilôn, nđâp ma phung kon jêh ri phung sau se.” Yêhôva lah,$b$,true),
('bunong-vn','ISA',14,23,null,$b$“Gâp mra ăn păng jêng ntŭk blŏ gŭ jêh ri ntŭk dak nglao. Gâp mra pêih lơi păng ma n'ha mpêh nau ƀư rai.” Yêhôva ma phung ta han lah.$b$,false),
('bunong-vn','ISA',14,24,null,$b$Yêhôva ma phung ta han ton săk jêh. “Tĭng nâm gâp nkra jêh nau dăp, pô nây yơh mra tât, jêh ri tĭng nâm nau gâp ton jêh, pô nây yơh păng mra jêng.$b$,true),
('bunong-vn','ISA',14,25,null,$b$Gâp mra ƀư rai phung Asiri tâm bri gâp, gâp mra jot păng ma jâng ta klơ yôk gâp, jêh ri nkêch lơi mâng mbăk păng bơh phung ƀon lan gâp, jêh ri sŏk rdu ndơ jâk păng bơh săng-nglik khân păng.”$b$,false),
('bunong-vn','ISA',14,26,null,$b$Pô ri yơh nau gâp ton ƀư ma lĕ neh ntu; jêh ri aơ yơh ti yơr ƀư ma lĕ rngôch phung ndŭl mpôl bunuyh.$b$,false),
('bunong-vn','ISA',14,27,null,$b$Yor lah Yêhôva ma phung ta han ton jêh, mbu nâm mra ƀư roh lơi nau nây? Ti păng yơr jêh ŭch ƀư, mbu mra nkân lơi?$b$,false),
('bunong-vn','ISA',14,28,null,$b$Năm hađăch Ahas khĭt geh nau ngơi pô aơ:$b$,true),
('bunong-vn','ISA',14,29,null,$b$“Lơi khân may răm ôh. Ơ lĕ bri Philistin yor lah mâng dong may lĕ deh jêh; yor lah bơh reh bri nây mra luh du mlâm bêh ŭnh, jêh ri kon păng mra jêng du mlâm bêh ŭnh mpăr.$b$,false),
('bunong-vn','ISA',14,30,null,$b$Phung o-ach lơn mra sông sa, jêh ri phung pưt ndơ mra bêch ma nau rnơm. Ƀiă lah gâp mra nkhĭt reh may ma nau sa sât ji ngot; đơ phung may hôm nau nây mra tâm nkhĭt.$b$,false),
('bunong-vn','ISA',14,31,null,$b$Nhĭm nhhiăng hom, Ơ mpông pêr! Nter hom, Ơ ƀon toyh! Rai lôch hom, Ơ lĕ phung Philistin! Yor lah nhhŭk tă luh bơh yôk, Jêh ri mâu geh ôh nơm gŭ pa kơi tâm phung ta han păng.$b$,false),
('bunong-vn','ISA',14,32,null,$b$Moh nau mra plơ̆ lah ma phung ntuh bâr bơh ndŭl mpôl aơ văch tât? “Yêhôva rdâk jêh ƀon Siôn, jêh ri phung bu tŭn jot tâm phung ƀon lan păng mra mbe tâm ƀon nây.”$b$,true),
('bunong-vn','ISA',15,1,null,$b$Nau ngơi di ma phung Môap: Ƀon Ar tâm bri Môap rai jêh tâm du măng!$b$,true),
('bunong-vn','ISA',15,2,null,$b$Phung ƀon Dibôn hao jêh ta ngih brah khân păng, khân păng hăn hao ta ntŭk prêh gay nhĭm nhhiăng; phung Môap nhĭm nhhiăng yor yôk Nêbô jêh ri ƀon Mêdêba. Ăp bôk plưn jêh, lĕ rngôch têp kang poih jêh.$b$,false),
('bunong-vn','ISA',15,3,null,$b$Tâm trong sâng khân păng soh ao dŭr, ta klơ chor bôk pho jêh ri tâm ngih tăch drăp, ăp nơm nhĭm nhhiăng jêh ri luh dak măt.$b$,false),
('bunong-vn','ISA',15,4,null,$b$Ƀon Hêsbôn jêh ri ƀon Êlêala lŭng nter, bu tăng bâr khân păng tât ta ƀon Jahas. Yor nây phung ta han bri Môap gŭ nter huy, huêng khân păng râm sâr.$b$,false),
('bunong-vn','ISA',15,5,null,$b$Nuih n'hâm gâp nter lŭng yor bri Môap, phung bunuyh khân păng nchuăt du ta ƀon Êglat-Sêlisija. Khân păng hăn hao ta ƀon Luhit nhĭm jăng jai, jêh ri njŏ trong ƀon Hôrônaim khân păng nter yor nau ƀư rai.$b$,false),
('bunong-vn','ISA',15,6,null,$b$Dak Nimrim suăt jêh, hĭp kro jêh hĭp nse văm jêh, mâu geh ndơ ndrêh ôh.$b$,false),
('bunong-vn','ISA',15,7,null,$b$Yor nây ndơ khân păng geh jêh, jêh ri ndơ khân păng bun jêh, khân păng rdeng leo rgăn n'hor Dak Tơm Sôl.$b$,true),
('bunong-vn','ISA',15,8,null,$b$Yor lah bu tăng bâr nter ndăch jŭm bri Môap, bu tăng nau khân păng nhĭm nhhiăng tât ta ƀon Êphraim, jêh ri nau rngot klâng tât ta Ƀon Bê-ê-lim.$b$,false),
('bunong-vn','ISA',15,9,null,$b$Yor lah dak ƀon Dibôn, du mlâm yau mŭr ƀư ma đơ phung klaih tâm phung Môap, ma phung hôm tâm bri neh.$b$,false),
('bunong-vn','ISA',16,1,null,$b$Njuăl hom âk kon biăp jêng pi ma kôranh chiă uănh, bơh ƀon Sêla ta trong rgăn bri rdah, ta yôk Kon Bu ur Siôn$b$,true),
('bunong-vn','ISA',16,2,null,$b$Phung bu ur Môap ta mbŏng thơl ntŭk dơi rgăn dak krong Arnôn jêng tâm ban ma sĭm mpăr du, tâm ban ma kon sĭm bu ntrŭt du tă bơh rsuăn.$b$,false),
('bunong-vn','ISA',16,3,null,$b$Tâm nchră an ƀư nau sŏng. Ta nar nklang bôk ăn gui nkâm may jêng tâm ban ma dôl măng; pôn lơi phung bu nsot, lơi rlăng ôh ma nơm du.$b$,true),
('bunong-vn','ISA',16,4,null,$b$Ăn phung Môap bu nsot jêh gŭ ndrel ma may; ăn may jêng ntŭk khân păng krap bơh nơm ƀư rai. Nơm tŭn jot mra roh, nau ƀư rai mra rlu; Jêh ri nơm tŭn jot mra du bơh bri neh.$b$,false),
('bunong-vn','ISA',16,5,null,$b$Bu mra rdâk du rplay sưng hađăch ma nau rŏng răp jăp, du huê bơh ngih bok Y-Đavit, du huê phat dôih joi nau di, jêh ri gơnh ƀư nau sŏng srăng.$b$,false),
('bunong-vn','ISA',16,6,null,$b$Hên tăng jêh nau phung Môap sưr, nau păng sưr ngăn, nau păng ra nam, jêh ri nau păng mưch, ƀiă lah nau păng sưr jêng dơm dam.$b$,true),
('bunong-vn','ISA',16,7,null,$b$Yor nây phung Môap nhĭm nhhiăng, lĕ rngôch nhĭm nhhiăng ma bri Môap. Ăn khân may rngot klâng rêh ni ngăn. Yor roh ƀănh play kriăk ƀâu ƀon Kir Harêsat.$b$,false),
('bunong-vn','ISA',16,8,null,$b$Neh mir ƀon Hêsbôn jêh ri tơm play kriăk ƀâu ƀon Sipma kroh klêu. Phung kôranh phung ndŭl mpôl bunuyh jot lơi jêh n'gĭng ueh lơn păng, n'gĭng nây tât jêh ta ƀon Jaser, nchah hăn tât ta bri rdah. Nkeh păng ntoch jong, n'ho tât ta kơh dak mƀŭt.$b$,false),
('bunong-vn','ISA',16,9,null,$b$Yor nây gâp mra nhĭm ma tơm play kriăk ƀâu ƀon Sipma tâm ban ma ƀon Jaser nhĭm. Ơ ƀon Hêsbôn jêh ri ƀon Êlêala, gâp mra ƀư bĕ may ma dak măt, nau bu nter hâk yor play dŭm may jêh ri play yăn rek may gŭ rklăk.$b$,true),
('bunong-vn','ISA',16,10,null,$b$Nau rhơn jêh ri nau maak bu ăn roh jêh bơh đang tơm play; bu mâu mprơ ôh tâm đang play kriăk ƀâu, mâu lĕ geh nau răm maak. Mâu geh nơm jot play kriăk ƀâu tâm thŭng, Yor lah gâp ăn lôch jêh nau bu răm maak.$b$,false),
('bunong-vn','ISA',16,11,null,$b$Nuih n'hâm gâp nđêng tâm ban ma gong rêng yor bri Môap, jêh ri yor ƀon Kin Hêres.$b$,false),
('bunong-vn','ISA',16,12,null,$b$Tơ lah phung Môap hăn ta ntŭk prêh khân păng, păng knŏng ƀư rgănh păng nơm tơ lah păng lăp tâm ntŭk kloh ueh păng gay mbơh sơm, păng mâu mra dơi ôh.$b$,false),
('bunong-vn','ISA',16,13,null,$b$Aơ yơh jêng nau Yêhôva ngơi jêh di ma phung Môap.$b$,true),
('bunong-vn','ISA',16,14,null,$b$Ƀiă lah aƀaơ Yêhôva lah. “Tâm pe năm tâm ƀon ma năm bunuyh bu nkhôm, nau chrêk rmah phung Môap jêh ri phung bunuyh păng jêng âk mra plăch jêng ndơ bu tâm rmot, jêh ri phung hôm mra jêng djê̆ ngăn jêh ri ra ai.” (Rdja)$b$,false),
('bunong-vn','ISA',17,1,null,$b$Nau ngơi di ma ƀon Damas: “Aơ, ƀon Damas mâu mra jêng du rplay ƀon ôh, păng mra du nku ndơ rai.$b$,true),
('bunong-vn','ISA',17,2,null,$b$Ƀon Arôer mra jêng rngol, păng mra jêng ntŭk ma biăp bêch rlu, jêh ri mâu geh nơm nhhu khân păng ôh.$b$,false),
('bunong-vn','ISA',17,3,null,$b$Bri Êphraim mâu mra lŏ geh pôih ôh, ƀon Damas mâu mra dơi chiă uănh ôh; Jêh ri phung hôm bơh bri Siri mra jêng tâm ban ma nau chrêk rmah phung kon Israel.” Yêhôva ma phung ta han lah Nau Phat Dôih Ma Phung Israel$b$,false),
('bunong-vn','ISA',17,4,null,$b$Tâm nar nây phung Yakôb mra roh nau chrêk rmah; jêh ri săk jăn khân păng mra rgay.$b$,false),
('bunong-vn','ISA',17,5,null,$b$Mra tât ma păng tâm ban ma nơm rek ba, ti păng kuăn nkong ba, tâm ban ma bu dônh nkong ba tâm rlŭng Rêphaim.$b$,false),
('bunong-vn','ISA',17,6,null,$b$Ăt mra geh djê̆ ba hôm tâm nây, tâm ban ma bu n'gu tơm play ôlivơ cha lat bar pe găr ta chiông si prêh lơn, puăn prăm găr ta n'gĭng tơm play.” Yêhôva Brah Ndu Phung Israel lah,$b$,true),
('bunong-vn','ISA',17,7,null,$b$Tâm nar nây phung bunuyh mra yơk ma Nơm Rhăk khân păng, jêh ri măt khân păng mra Uănh ta Nơm Kloh Ueh phung Israel.$b$,false),
('bunong-vn','ISA',17,8,null,$b$Khân păng mâu mra rŏng ôh ma nơng, kan ti khân păng nơm ƀư, mâu lĕ khân păng mra uănh ma ndơ nglao ti khân păng njêng jêh, gĭt lah rup brah Asêrim mâu lah nơng gŭch ndơ ƀâu kah.$b$,false),
('bunong-vn','ISA',17,9,null,$b$Tâm nar nây lĕ rngôch ƀon toyh nâp rjăp khân păng mra jêng tâm ban ma ntŭk phung Hivit jêh ri phung Amôrit cha lơi jêh ta năp phung kon Israel, jêh ri mra jêng ntŭk rngol.$b$,true),
('bunong-vn','ISA',17,10,null,$b$Yor lah may chuêl jêh Brah Ndu nơm tâm rklaih may; jêh ri mâu kah gĭt ôh ma lŭ ntŭk may du krap. Yor nây nđâp tơ lah may tăm jêh ndơ ueh reh, jêh ri tăm âk tơm play kriăk ƀâu brah bu năch,$b$,false),
('bunong-vn','ISA',17,11,null,$b$nđâp tơ lah may ăn khân păng jêng ta nar may tăm, jêh ri ăn khân păng geh kao ta ôi may tăm, ăt yan pĕ play mâu mra tât ôh tâm nar geh nau rngot jêh ri nau ji mâu blau bah ôh.$b$,false),
('bunong-vn','ISA',17,12,null,$b$Phung ƀon âk ƀư nteh drơu drơu tâm ban ma nteh rbuh dak mƀŭt! Jêh ri phung ndŭl mpôl bunuyh ƀư nteh tâm ban ma dak mƀŭt sial rbuh.$b$,true),
('bunong-vn','ISA',17,13,null,$b$Nđâp tơ lah phung ndŭl mpôl mra ƀư nteh tâm ban ma dak njach rbuh, ƀiă lah păng mra nduyh bu, jêh ri khân păng mra du ngai. Bu nsot khân păng tâm ban ma rhe ba tâm yôk ta năp sial, tâm ban ma ndruyh tâm sial khôm.$b$,false),
('bunong-vn','ISA',17,14,null,$b$Ta mhaơ, aơ, geh nau tâm nhhu; lor ma tât ôi mâu hôm saơ khân păng ôh. Pô ri jêng nau mra tât ma phung sŏk pit ndô ndơ he, nau mra tât ma phung ntŭng tă bơh he.$b$,false),
('bunong-vn','ISA',18,1,null,$b$Ơ bri neh geh nteh tâm ban ma rtuh năr đah rĭ dak krong bri Êthiôpi.$b$,true),
('bunong-vn','ISA',18,2,null,$b$May prơh phung oh mon hăn ta dak mƀŭt, ncho duk ƀư ma rpho ta klơ mpiăt dak. Ơ phung mbơh hăn ngăch, hăn hom ta ngih phung mpôl jong lĭng jêh ri ntâu kranh, ma du phung ƀon lan nkrit nhhu bơh ntơm geh păng tât aƀaơ ri, du ndŭl mpôl ktang jêh ri tŭn jot, bri khân păng geh âk dak krong tâm pă.$b$,false),
('bunong-vn','ISA',18,3,null,$b$Ơ lĕ rngôch phung gŭ tâm neh ntu, tơ lah bu n'hao jêh bok pla ta klơ yôk khân may mra saơ. Tơ lah bu uh nŭng, khân may mra tăng.$b$,false),
('bunong-vn','ISA',18,4,null,$b$Yor lah pô aơ nau Yêhôva lah jêh ma gâp, “Ma nau rngơt rklăk gâp mra uănh bơh ntŭk gâp gŭ tâm ban ma duh ring nar nchrat, tâm ban thŭl dak ngom dôl duh nar yăn rek.”$b$,true),
('bunong-vn','ISA',18,5,null,$b$Yor lah lor yăn rek tât tơ lah yan kao lôch jêh, jêh ri kao jêng jêh play kriăk ƀâu ntơm dŭm, păng mra sreh nkeh play kriăk ƀâu ma yeh, păng mra sŏk sreh mƀăr n'gĭng pŭm.$b$,false),
('bunong-vn','ISA',18,6,null,$b$Bu mra cha lơi lĕ khân păng ma sĭm, klang tâm yôk jêh ri ma mpa bri ta neh ntu. Klang, grât mra sa khân păng dôl yăn kăl vai, jêh ri lĕ rngôch mpa bri ta neh ntu mra sa khân păng dôl yăn sĭt puh.$b$,false),
('bunong-vn','ISA',18,7,null,$b$Tâm rnôk nây khân păng mra njŭn mpa nhhơr ma Yêhôva ma phung ta han, bơh du phung ƀon lan jong lĭng jêh ri ntâu kranh du phung ƀon lan tâm nkrit nhhu ntơm bơh geh păng tât aƀaơ ri, du phung ndŭl mpôl ktang jêh ri tŭn jot, bri khân păng geh âk dak krong tâm pă nkhah. Khân păng mra njŭn mpa nhhơr nây ta yôk Siôn, ntŭk prăp ma Amoh Yêhôva ma phung ta han.$b$,true),
('bunong-vn','ISA',19,1,null,$b$Nau ngơi di ma phung Êjipt: Aơ, Yêhôva hao ta ndâr tŭk, hăn ngăch, văch ta Êjipt. Rup brah bri Êjipt mra râm sân ta năp păng, jêh ri nuih n'hâm phung Êjipt mra djoh.$b$,true),
('bunong-vn','ISA',19,2,null,$b$“Gâp mra nsônh nuih phung Êjipt tâm lơh đah phung Êjipt nơm; khân păng mra tâm rdâng ăp nơm đah oh nâu khân păng, ăp nơm đah phung chiau meng khân păng, ƀon ndrăng ƀon, ƀon bri hađăch ndrăng ƀon bri hađăch.$b$,false),
('bunong-vn','ISA',19,3,null,$b$Phung Êjipt rdja, jêh ri gâp mra ngroh lơi nau khân păng tâm nchră. Khân păng mra joi ôp rup brah jêh ri phung n'hŭm, phung ngơi đah phung khĭt jêh ri phung rƀên.$b$,false),
('bunong-vn','ISA',19,4,null,$b$Jêh ri gâp mra jao phung Êjipt tâm ti du huê kôranh dăng; du huê hađăch djơh-mhĭk mra chiă uănh khân păng.” Pô ri Kôranh Brah Yêhôva ma phung ta han lah,$b$,true),
('bunong-vn','ISA',19,5,null,$b$Dak krong mra suăt, dak krong mra sơh jêh ri kroh.$b$,false),
('bunong-vn','ISA',19,6,null,$b$Lĕ dak n'hor mra ƀâu ôm; n'hor dak nkhah tă bơh dak krong Nil ta bri Êjipt mra djoh jêh ri sơh. Treng jêh ri rpho mra ôm.$b$,false),
('bunong-vn','ISA',19,7,null,$b$Ndrêch dăch đah dak krong Nil mra sơh, jêh ri lĕ rngôch ndơ bu srih ta kơh dak krong Nil mra kro, sial mra rpuh rdu ndơ nây ta ntŭk êng jêh ri ăn roh lơi$b$,false),
('bunong-vn','ISA',19,8,null,$b$Phung seng ka mra rngot klâng jêh ri nhĭm nhhiăng, lĕ rngôch phung chê̆ ndar tâm dak krong Nil mra rngot; Phung vay nthăng nhuăl tâm dak mra khĭt rngot.$b$,false),
('bunong-vn','ISA',19,9,null,$b$Phung ƀư brai mhay mra djoh nuih n'hâm$b$,true),
('bunong-vn','ISA',19,10,null,$b$Phung tơm bri mra roh, jêh ri lĕ rngôch phung pah kan nkhôm mra rngot.$b$,false),
('bunong-vn','ISA',19,11,null,$b$Phung kôranh ƀon Sôan jêng rluk mâl phung kôranh njêh Pharaôn nchŏng ntĭm rluk ma khân păng. Mâm ƀư khân may janh lah ma Pharaôn, “Gâp jêng kon bu klâu phung njêh, kon sau phung hađăch rnôk kăl e?”$b$,true),
('bunong-vn','ISA',19,12,null,$b$Pô ri, mbah phung njêh may? Ăn khân păng nkoch tâm mpơl ma may nau Yêhôva ma phung ta han gay ŭch ƀư ma bri Êjipt.$b$,false),
('bunong-vn','ISA',19,13,null,$b$Phung kôranh ƀon Sôan jêng jêh phung rluk, phung kô ranh ƀon Nôp tŭp tâm nau ndơm; phung kôranh tâm nkuĭl êng êng ƀư hiơ̆ trong phung Êjipt.$b$,false),
('bunong-vn','ISA',19,14,null,$b$Yêhôva ăn jêh nau mĭn tâm lŭk rlăk ta nklang bri Êjipt; khân păng ăn phung Êjipt hăn tĭng nau vĭ blă blơ tâm lĕ nau khân păng ƀư, tâm ban ma du huê bunuyh nhŭl ndrănh prah tâm hok păng.$b$,true),
('bunong-vn','ISA',19,15,null,$b$Tâm bri Êjipt bu mâu hôm dơi kơl ôh, gĭt lah bôk mâu lah chiăng, mpak tơm play đung mâu lah rpho.$b$,false),
('bunong-vn','ISA',19,16,null,$b$Tâm nar nây phung Êjipt mra jêng tâm ban ma phung bu ur. Khân păng mra râm sâr ma nau klach ta năp ti Yêhôva ma phung ta han mpoh ta klơ khân păng.$b$,true),
('bunong-vn','ISA',19,17,null,$b$Jêh ri bri Yuđa mra jêng du nau tâm nhhu nkrit ma bri Êjipt; ăp nơm tăng nau Yêhôva mra klach, yor nau ntơ amoh Yêhôva ma phung ta han gay ŭch ƀư ma khân păng.$b$,false),
('bunong-vn','ISA',19,18,null,$b$Tâm nar nây mra geh prăm rplay ƀon toyh tâm bri Êjipt mra ngơi nau bri Kanaan jêh ri ton săk mra tông ma Yêhôva ma phung ta han bu mra rnha Ƀon Nau Ƀư Rai ma du rplay tâm prăm rplay ƀon nây.$b$,false),
('bunong-vn','ISA',19,19,null,$b$Tâm nar nây mra geh du rplay nơng prăp ma Yêhôva ta nklang bri Êjipt, jêh ri du n'gâng meh prăp ma Yêhôva ta n'har neh păng.$b$,true),
('bunong-vn','ISA',19,20,null,$b$Ndơ nây mra jêng du ntil ndơ tâm mbên jêh ri du nau mbơh ma Yêhôva ma phung ta han tâm bri Êjipt. Tơ lah khân păng mra nter ma Yêhôva yor phung tŭn jot, păng mra mprơh hăn ma khân păng du huê nơm tâm rklaih, jêh ri nơm brah, jêh ri nơm nây mra tâm rklaih khân păng.$b$,false),
('bunong-vn','ISA',19,21,null,$b$Pô ri Yêhôva mra tâm mpơl păng nơm ma phung Êjipt, jêh ri phung Êjipt mra gĭt năl Yêhôva tâm nar nây. Khân păng mra mbah yơk ma nau ƀư brah jêh ri nhhơr mpa nhhơr mpa nhhơr. Khân păng mra ƀư nau ton ma Yêhôva jêh ri ƀư nanê̆ ngăn nau nây.$b$,true),
('bunong-vn','ISA',19,22,null,$b$Yêhôva mra dong bri Êjipt, mra dong jêh ri plơ̆ ƀư bah khân păng đŏng; Jêh ri khân păng mra sĭt ma Yêhôva. Khân păng mra iăt nau bu mbơh sơm jêh ri ƀư bah khân păng.$b$,true),
('bunong-vn','ISA',19,23,null,$b$Tâm nar nây mra geh du trong toyh bơh bri Êjipt tât ta bri Asiri, jêh ri phung Asiri mra hăn ta bri Êjipt, jêh ri phung Êjipt hăn ta bri Asiri. Phung Êjipt mra mbah yơk ndrel ma phung Asiri.$b$,true),
('bunong-vn','ISA',19,24,null,$b$Tâm nar nây bri Israel mra tâm rnglăp jêng bri mrô pe ndrel ma bri Êjipt jêh ri bri Asiri, jêng du nau ueh uĭn ta nklang neh ntu,$b$,true),
('bunong-vn','ISA',19,25,null,$b$Phung Yêhôva ma phung ta han mât ton jêh, lah, “Ueh maak ngăn ma bri Êjipt phung ƀon lan gâp, jêh ri bri Asiri kan ti gâp, jêh ri bri Israel drăp krâm gâp.”$b$,false),
('bunong-vn','ISA',20,1,null,$b$Tâm năm Sargôn hađăch bri Asiri prơh njuăl Kôranh hăn Y-Tartan văch ta ƀon Asdôt, tâm lơh jêh ri sŏk ƀon nây,$b$,true),
('bunong-vn','ISA',20,2,null,$b$dôl nây Yêhôva ngơi jêh ma Y-Êsai, kon bu klâu Y-Amôt, lah, “Hăn hom doh hom ao ƀau ta bŭt may jêh ri doh lơi ntâu jot may.” Păng ƀư pô nây, hăn săk lưn jêh ri jâng dơm.$b$,false),
('bunong-vn','ISA',20,3,null,$b$Jêh ri Yêhôva lah, “Tâm ban ma oh mon gâp Y-Êsai hăn săk hưl jêh ri jâng dơm tâm pe năm jêng du nau tâm mbên tâm rdâng đah bri Êjipt jêh ri ma bri Êthiôpi,$b$,true),
('bunong-vn','ISA',20,4,null,$b$tâm ban pô nây lĕ hađăch bri Asiri têk leo phung Êjipt jêh ri phung Êthiôpi jêng bu nă bơh bri khân păng, phung druh ndăm jêh ri phung bu ranh, hăn săk hưl jêh ri jâng dơm, nglay săt mpơl, gay ƀư bêk bri Êjipt.$b$,false),
('bunong-vn','ISA',20,5,null,$b$Rnôk nây khân păng mra ioh nuih n'hâm jêh ri uh ah yor bri Êthiôpi jêh ri bri Êjipt.$b$,true),
('bunong-vn','ISA',20,6,null,$b$Jêh ri phung gŭ rŏ kơh dak mƀŭt mra lah tâm nar nây, ‘Aơ, pô ri yơh tât jêh ma phung he rnơm jêh ri ma phung he gay geh nau tâm rklaih bơh hađăch bri Asiri-Bi he mâm he mra klaih?’$b$,false),
('bunong-vn','ISA',21,1,null,$b$Nau ngơi di ma bri rdah dăch dak mƀŭt: Tâm ban ma sial văch blông bơh bri Nêgep; nau ngơi luh văch bơh bri rdah bơh bri rđŭng.$b$,true),
('bunong-vn','ISA',21,2,null,$b$Bu mbơh ma gâp du nau mpơl saơ klach krit ngăn: Nơm pit sŏk kâp pit sŏk, nơm ƀư rai kâp ƀư rai! Hăn hao hom, Ơ phung Êlam. Nchueng hom, Ơ phung Mêđơ. Gâp mra ƀư lôch lĕ nau vơl nơm ƀư rai ăn tât jêh.$b$,false),
('bunong-vn','ISA',21,3,null,$b$Yor nây bŭt gâp ji ngăn, gâp geh nau ji tâm ban ma nau ji du huê bu ur veng deh. Gâp uh ah kŏ tât gâp mâu dơi tăng ôh, gâp djoh nuih n'hâm kŏ gâp mâu dơi saơ ôh.$b$,true),
('bunong-vn','ISA',21,4,null,$b$Nau mĭn gâp uh ah, nau djôh mhĭk nhhu gâp, ngo suâr vâr gâp ŭch kâp hŏ, ăn tât rgâl jêng nau râm sâr ma gâp.$b$,false),
('bunong-vn','ISA',21,5,null,$b$Bu gak sưng sông, bu dơm phung, bu sông sa, bu nhêt. Dâk hom, Ơ phung Kôranh! Mhĭng hom khêl ma dak play ôlivơ.$b$,false),
('bunong-vn','ISA',21,6,null,$b$Yor lah pô aơ Kôranh Brah lah jêh ma gâp: “Hăn hom, dơm du huê nơm gak. Ăn păng mbơh moh nau may saơ.$b$,true),
('bunong-vn','ISA',21,7,null,$b$Tơ lah păng saơ phung ncho seh, phung ncho seh bar bar, phung ncho seh bri, phung ncho seh samô, ăn păng kâp iăt na nê̆ ma nau njrăng ngăn.”$b$,false),
('bunong-vn','ISA',21,8,null,$b$Jêh ri nơm gak nter: “Ơ Kôranh Brah gâp gŭ râng lôch nar ta tŭm gak, jêh ri gâp gŭ ta ntŭk gâp gak lôch măng.$b$,false),
('bunong-vn','ISA',21,9,null,$b$Jêh ri aơ, geh phung ta han ncho seh, khân păng văch ncho seh bar bar.” Bu plơ̆ lah: “Tŭp jêh ƀon Babilôn, tŭp ngăn jêh! Jêh ri lĕ rngôch rup brah păng nchah lơi lĕ ta neh!”$b$,false),
('bunong-vn','ISA',21,10,null,$b$Ơ phung ƀon lan gâp, phung bu dong nkra jêh! Moh nau gâp tăng jêh bơh Yêhôva ma phung ta han, Brah Ndu ma phung Israel, gâp mbơh nau nây ma khân may.$b$,true),
('bunong-vn','ISA',21,11,null,$b$Nau ngơi di ma ƀon Duma: Bu kuăl gâp bơh yôk Sêir “Ơ nơm gak, mâm măng aơ? Hơi nơm gak, mâm măng aơ?”$b$,true),
('bunong-vn','ISA',21,12,null,$b$Nơm gak lah, “Ôi tât jêh ri măng tât tâm ban lĕ. Tơ lah may ŭch ôp, ôp hom, jêh ri plơ̆ văch hom.”$b$,false),
('bunong-vn','ISA',21,13,null,$b$Nau ngơi di ma bri Arabi: Ơ phung Dêdan ncho seh samô, phung bêch tâm krŏng bri Arabi.$b$,true),
('bunong-vn','ISA',21,14,null,$b$Ơ phung gŭ tâm bri Têma, djôt dak ma phung ji hir, tâm mâp hom đah phung du njŭn piăng let ma khân păng.$b$,false),
('bunong-vn','ISA',21,15,null,$b$Yor lah khân păng du jêh đah đao, bơh đao bu tŏk jêh, bơh na bu van jêh, bơh nau tâm lơh$b$,false),
('bunong-vn','ISA',21,16,null,$b$Yor lah pô aơ Kôranh Brah lah jêh ma gâp, “Tâm du năm, tĭng nâm năm du huê pah kan nkhôm, lĕ nau chrêk rmah bri Kêdar mra roh.$b$,false),
('bunong-vn','ISA',21,17,null,$b$Phung janh ktang djôt na tâm phung kon bu klâu bri Kêdar mra jêng knŏng djê̆.” Yêhôva, Brah Ndu ma phung Israel lah jêh nau nây.”$b$,false),
('bunong-vn','ISA',22,1,null,$b$Nau jâk di ma rlŭng nau tâm saơ: Moh nau tât ƀư rŭng khân may kŏ lĕ rngôch khân may hao jêh ta klơ bôk pho.$b$,true),
('bunong-vn','ISA',22,2,null,$b$Ơ ƀon bêng ma nau drưh drưh, jêh ri nteh nter ƀư nau blă blơ? Phung khĭt may mâu bu nkhĭt ma đao ôh, mâu lĕ khân păng khĭt tâm nau tâm lơh.$b$,true),
('bunong-vn','ISA',22,3,null,$b$Lĕ rngôch phung kôranh chiă uănh khân may nchuăt du ndrel n'grŭp; bu nhŭp chăp khân păng mâu dŏng na ôh. Bu nhŭp chăp jêh lĕ rngôch tâm phung ƀon lan khân may bu saơ, nđâp tơ lah khân păng lĕ du ngai jêh.$b$,false),
('bunong-vn','ISA',22,4,null,$b$Yor nây gâp lah, “Lơi uănh ta gâp ôh, ăn gâp nhĭm rngot ngăn. Lơi joi nau bonh leng gâp ôh, yor nau ƀư rai kon bu ur phung ƀon lan gâp.”$b$,false),
('bunong-vn','ISA',22,5,null,$b$Yor lah Kôranh Brah Yêhôva ma phung ta han ƀư tât nar nau uh ah nau tŭn jot, jêh ri nau mĭn luk rlăk tâm rlŭng nau tâm saơ, nau ƀư rlâm pêr jêh ri nau nter tât ta yôk.$b$,false),
('bunong-vn','ISA',22,6,null,$b$Phung Êlam cheng dĭng hăr ndrel ma âk ndeh seh jêh ri phung ta han ncho seh. Phung Kir djôt khêl.$b$,true),
('bunong-vn','ISA',22,7,null,$b$Lĕ rngôch rlŭng may ueh lơn bêng ma ndeh seh, jêh ri phung ta han ncho seh dăp jêh ma nau tâm lơh ta mpông pêr ƀon.$b$,false),
('bunong-vn','ISA',22,8,null,$b$Păng sŏk lơi jêh ndơ n'gang bri Yuđa. Tâm nar nây khân may rnơm ma ndơ tâm lơh tâm Ngih Krŏng.$b$,false),
('bunong-vn','ISA',22,9,null,$b$Khân may saơ âk trôm bluh tâm ƀon Đavit; khân may sŏk rgum ndrel dak bơh dak nglao tâm dâng.$b$,true),
('bunong-vn','ISA',22,10,null,$b$Khân may kơp ngih tâm ƀon Yêrusalem, jêh ri khân may nkêch lơi khân păng gay ma ăn nâp pêr.$b$,false),
('bunong-vn','ISA',22,11,null,$b$Khân may ƀư trôm huy vah vang bar tăp pêr gay prăp dak bơh dak nglao ơm, ƀiă lah khân may mâu rnơm ôh ma Nơm ƀư nau nây, mâu lĕ khân may uănh ma Nơm ŭch ƀư nau nây bơh kăl e.$b$,false),
('bunong-vn','ISA',22,12,null,$b$Tâm nar nây Kôranh Brah Yêhôva ma phung ta han, kuăl khân may ma nau nhĭm, jêh ri nau rngot klâng, ma nau poih bôk, jêh ri ma nau soh ao ƀau.$b$,false),
('bunong-vn','ISA',22,13,null,$b$Ƀiă lah aơ, geh nau răm jêh ri nau maak, bu chôk ndrôk jêh ri nkhĭt biăp, bu sa puăch puăch jêh ri nhêt dak play kriăk ƀâu. “Ăn he sông sa jêh ri nhêt, yor lah ôi taơ he mra khĭt.”$b$,false),
('bunong-vn','ISA',22,14,null,$b$Yêhôva ma phung ta han tâm mpơl jêh păng nơm ngơi ma tôr gâp, “Na nê̆ bu mâu mra yô̆ an ma khân may nau kue aơ ôh tât khân may khĭt. “Kôranh Brah Yêhôva ma phung ta han lah.$b$,true),
('bunong-vn','ISA',22,15,null,$b$Pô ri Kôranh Brah Yêhôva ma phung ta han lah, “Hăn lah hom ma nơm chiă drăp, Y-Sêpna, nơm jêng kôranh ngih:$b$,true),
('bunong-vn','ISA',22,16,null,$b$Moh nau may ƀư ta aơ, jêh ri mbu nâm may geh ta aơ, kŏ may kuyh jêh ma may nơm du trôm môch ta aơ? May kuyh ma may nơm du ntu môch ta ntŭk prêh, may trah ntŭk gŭ ma may nơm tâm trôm lŭ.$b$,false),
('bunong-vn','ISA',22,17,null,$b$Aơ, Ơ bunuyh ktang, Yêhôva mra mƀăr may dŭt dăng. Păng mra kuăn may nâp,$b$,false),
('bunong-vn','ISA',22,18,null,$b$Păng mra ndăch may ngăch jêh ri klŭp may tâm ban ma klŭp play chưng ma du ntŭk huy. Ta nây may mra khĭt, ta nây lĕ ndeh seh chrêk rmah may mra gŭ. Ơ nơm ƀư bêk ngih kôranh may.$b$,false),
('bunong-vn','ISA',22,19,null,$b$Gâp mra nsot may bơh kan may; bu mra mƀăr may bơh ntŭk may gŭ.$b$,false),
('bunong-vn','ISA',22,20,null,$b$Tâm nar nây gâp mra kuăl oh mon gâp, Y-Êliakim kon bu klâu Y-Hil$b$,true),
('bunong-vn','ISA',22,21,null,$b$Gâp mra sâm nsoh păng ma ao may, gâp mra vân păng ma rse bŭt may, jêh ri gâp mra jao nau may chiă uănh tâm ti păng. Păng mra jêng du huê mbơ̆ ma phung gŭ tâm ƀon Yêrusalem jêh ri ma ngih Yuđa.$b$,false),
('bunong-vn','ISA',22,22,null,$b$Gâp mra dơm lăk lê mpông Y-Đavit ta klơ săng nglik păng; Păng mra pơk jêh ri mâu geh nơm dơi chăng ôh; Păng mra chăng jêh ri mâu geh nơm dơi pơk ôh.$b$,false),
('bunong-vn','ISA',22,23,null,$b$Gâp mra pâng păng tâm ban ma loih kađĭn (đăch gôl) tâm ntŭk nâp, jêh ri păng mra jêng du rplay sưng hađăch chrêk rmah ma ngih mbơ̆ păng.$b$,false),
('bunong-vn','ISA',22,24,null,$b$Bu mra yông kât ta păng lĕ nau chrêk rmah mbơ̆ păng, Phung sau se nđâp phung tâm ngih, lĕ rngôch khăl ngan jê-jê̆ bơh mâm thaih n'ho ma yăng jê̆.$b$,false),
('bunong-vn','ISA',22,25,null,$b$Tâm nar nây Yêhôva ma phung ta han lah, loih kađĭn pâng jêh tâm ntŭk nâp mra tŏk lơi; bu mra kăl păng, jêh ri păng mra cha lôt, jêh ri ndơ jâk ta păng bu mra ƀư rai lơi.” Yêhôva lah jêh nau nây.$b$,true),
('bunong-vn','ISA',23,1,null,$b$Nau jâk di ma ƀon Tir: Nhĭm nhhiăng hom. Ơ kŭmpăn Tarsis, yor lah bu ƀư rai jêh ƀon Tir, mâu hôm geh ngih ôh, mâu hôm geh ntŭk gŭ ôh. Tă bơh n'gor Kitim bu mpơl nau nây ma khân păng.$b$,true),
('bunong-vn','ISA',23,2,null,$b$Gŭ klăk hom, ơ phung gŭ ta kơh dak mƀŭt, Ơ phung tăch rgâl ƀon Sidôn phung khân may prơh hăn rgăn jêh dak mƀŭt, jêh ri gŭ jêh ta ntŭk âk dak êng,$b$,true),
('bunong-vn','ISA',23,3,null,$b$Drăp sa kao păng jêng ba bơh dak krong Sihôr, ndơ roih rek bơh dak krong Nil. Khân may jêng nơm tăch rgâl ma phung ndŭl mpôl bunuyh.$b$,false),
('bunong-vn','ISA',23,4,null,$b$Ăn may bêk, Ơ ƀon Sidôn, yor lah dak mƀŭt ngơi jêh, pôih dak mƀŭt lah jêh, “Gâp mâu bêch veng ŭnh ôh, mâu lĕ mâp deh, mâu lĕ mâp siăm rong phung bu klâu ndăm, mâu lah phung bu ur druh.”$b$,true),
('bunong-vn','ISA',23,5,null,$b$Tơ lah nau mhe mhan nây tât ta bri Êjipt, khân păng mra rngot ngăn yor nau mhe mhan di ma ƀon Tir.$b$,false),
('bunong-vn','ISA',23,6,null,$b$Rgăn hăn ta ƀon Tarsis, nhĭm nhhiăng hom, ơ phung gŭ ta kơh dak mƀŭt.$b$,true),
('bunong-vn','ISA',23,7,null,$b$Aơ hĕ ƀon hâk răm khân may, ƀon tơm geh bơh rnôk ơm kăl e, jâng păng njŭn păng hăn gŭ ntŭk ngai?$b$,false),
('bunong-vn','ISA',23,8,null,$b$Mbu nâm gay ŭch ƀư nau aơ ma ƀon Tir, ƀon ăn đon hađăch, phung tăch rgâl păng jêng phung kon hađăch, phung ndranh păng jêng phung bu yơk tâm neh ntu?$b$,true),
('bunong-vn','ISA',23,9,null,$b$Yêhôva ma phung ta han yơh hŏ gay ŭch ƀư nau nây, gay ƀư ƀơ̆ nau sưr lĕ nau chrêk rmah, gay ƀư bêk lĕ rngôch phung bu yơk ta neh ntu.$b$,true),
('bunong-vn','ISA',23,10,null,$b$Lêng lam bri may tâm ban ma dak krong Nil. Ơ Kon bu ur ƀon Tarsis, mâu hôm geh nau kân ôh.$b$,true),
('bunong-vn','ISA',23,11,null,$b$Yêhôva yơr jêh ti păng ta klơ dak mƀŭt, păng rtuh jêh âk ƀon bri hađăch. Yêhôva ăn jêh nau ntăm di ma bri Kanaan gay ƀư rai lĕ pôih păng.$b$,false),
('bunong-vn','ISA',23,12,null,$b$Păng lah: “Ay mâu hôm răm maak ôh. Ơ kon bu ur druh ƀon Sidôn bu tŭn jot jêh. “Dâk hom ay, ăn ay rgăn hăn ta n'gor Kitim. Nđâp ta nây mâu lĕ ay geh nau rlu.”$b$,true),
('bunong-vn','ISA',23,13,null,$b$Aơ bri neh phung Kaldê, mâu hôm geh phung ƀon lan nây ôh. Phung Asiri njêng ntŭk nây jêng ntŭk prăp ma jun bri. Khân păng rdâk ngih tŭm, khân păng rơih lơi ngih hađăch păng, khân păng ƀư rai lơi.$b$,true),
('bunong-vn','ISA',23,14,null,$b$Nhĭm nhhiăng hom, Ơ lĕ rngôch kŭmpăn Tarsis, yor lah pôih khân may rai jêh.$b$,true),
('bunong-vn','ISA',23,15,null,$b$Tâm nar nây bu mra chuêl ƀon Tir dôl tâm pơh jât năm, tâm ban ma năm du huê hađăch gŭ rêh. Tăch pơh jât năm mra tât ta ƀon Tir tĭng nâm nau du huê bu ur văng tĭr mprơ:$b$,true),
('bunong-vn','ISA',23,16,null,$b$“Sŏk gong rêng nsong hom tâm ƀon, Ơ bu ur ka n'hong bu chuêl jêh! Kreh hom ăn ueh, mprơ hom ăn âk, gay ma bu kah gĭt ma ay.”$b$,false),
('bunong-vn','ISA',23,17,null,$b$Tăch pơh jât năm Yêhôva mra tâm khâl đah ƀon Tir, jêh ri ƀon Tir mra plơ̆ sĭt ma nau nkhôm păng, jêh ri mra ƀư nau văng tĭr đah lĕ rngôch ƀon bri hađăch ta klơ neh ntu.$b$,true),
('bunong-vn','ISA',23,18,null,$b$Ƀiă lah ndơ păng tăch jêh ri rnoh nkhôm păng mra prăp ma Yêhôva. Bu mâu mra bun prăp ôh, ƀiă lah ndơ păng tăch mra prăp dơi jêng ndơ sông sa rmeh ler jêh ri bok ao ueh ma phung gŭ ta năp Yêhôva.$b$,false),
('bunong-vn','ISA',24,1,null,$b$Aơ, Yêhôva mra ƀư rai neh ntu ăn jêng rngol. Păng mra plăch tâm dâng klơ jêh ri ƀư chah rai lơi phung ƀon lan.$b$,true),
('bunong-vn','ISA',24,2,null,$b$Jêh ri kôranh ƀư brah mra jêng tâm ban ma ƀon lan, kôranh mra jêng tâm ban ma dĭk păng, kôranh ngih bu ur mra jêng tâm ban ma oh mon bu ur păng, nơm tăch mra jêng tâm ban ma nơm rvăt, nơm chan jêng tâm ban ma nơm ăn chan nơm iang rnon jêng tâm ban ma nơm rnon.$b$,false),
('bunong-vn','ISA',24,3,null,$b$Neh ntu mra rai jêh ri mra pit in lĕ, Yor lah Yêhôva lah jêh nau nây.$b$,false),
('bunong-vn','ISA',24,4,null,$b$Neh ntu rngot klâng jêh ri huănh; neh ntu rngot jêh ri huănh; phung bunuyh bu yơk mra rai yot.$b$,true),
('bunong-vn','ISA',24,5,null,$b$Neh ntu mra ƀơ̆ yor ƀon lan păng nơm, yor lah khân păng rlau jêh nau vay, mâu tông ôh nau ntăm, khân păng rlau jêh nau tâm rnglăp n'ho ro.$b$,false),
('bunong-vn','ISA',24,6,null,$b$Yor nây nau rtăp rak sa neh ntu, jêh ri phung ƀon lan păng dơn nau rêh ni yor nau tih khân păng. Yor nây ŭnh sa jêh phung gŭ tâm neh ntu, jêh ri hôm knŏng djê̆ bunuyh.$b$,false),
('bunong-vn','ISA',24,7,null,$b$Dak play kriăk ƀâu mhe lĕ suăt, tơm păng lĕ huănh, lĕ rngôch phung geh nuih n'hâm hâk răm vơl da dê.$b$,true),
('bunong-vn','ISA',24,8,null,$b$Mâu hôm geh maak nteh gâr ôh nteh phung răm maak lôch jêh, mâu hôm maak nteh gong rêng ôh.$b$,false),
('bunong-vn','ISA',24,9,null,$b$Khân păng mâu hôm nhêt dak play kriăk ƀâu dôl mprơ ôh; ndrăng jêng tăng ma phung nhêt.$b$,false),
('bunong-vn','ISA',24,10,null,$b$Ƀon uh ah hŏ rai jêh, lĕ rngôch ngih mra chăng jêh mâu hôm geh bunuyh lăp ta nây ôh.$b$,true),
('bunong-vn','ISA',24,11,null,$b$Bu nter ta trong sâng yor mâu geh dak play kriăk ƀâu; lĕ rngôch nau hâk răm du jêh; nau maak neh ntu lôch jêh.$b$,false),
('bunong-vn','ISA',24,12,null,$b$Ƀon toyh rai jêh, jêh ri mpông pêr rlâm jêh.$b$,true),
('bunong-vn','ISA',24,13,null,$b$Yor lah neh ntu mra jêng tâm ban pô nây, ta nklang phung mpôl băl bunuyh, tâm ban ma tơ lah bu rgu tơm play ôlivơ, tâm ban ma bu dônh play kriăk ƀâu hôm tơ lah jêh yăn pĕ play.$b$,false),
('bunong-vn','ISA',24,14,null,$b$Phung bunuyh nter mprơ ma nau răm rhơn, yor nau chrêk rmah Yêhôva khân păng nter troh bơh bri pa dâng.$b$,true),
('bunong-vn','ISA',24,15,null,$b$Yor nây ăn nau chrêk rmah ma Yêhôva tâm bri pa lơ, tâm bri rgŏ kơh dak mƀŭt ăn nau chrêk rmah ma amoh Yêhôva Brah Ndu Israel.$b$,false),
('bunong-vn','ISA',24,16,null,$b$Bơh dŭt bri neh he tăng bu mprơ, “Chrêk rmah ma nơm sŏng.” Ƀiă lah gâp lah, “Gâp roh jêh, gâp roh jêh, rêh ni ngăn gâp! Yor lah phung ƀai ƀư nau ƀai, na nê̆ phung ƀai ƀư nau ƀai ngăn.”$b$,true),
('bunong-vn','ISA',24,17,null,$b$Ơ phung gŭ tâm neh ntu, nau klach, brŏng jru, jêh ri nhuăl kâp ƀư ma may.$b$,false),
('bunong-vn','ISA',24,18,null,$b$Mbu nâm klach bơh nteh bu nhhu mra tŭp tâm ntu jru; jêh ri mbu nâm luh tă bơh ntu jru mra geh nhuăl. Yor lah mpông bloh jê̆ ta trôk pơk jêh, jêh ri mbon neh ntu mpât n'găr da dê.$b$,false),
('bunong-vn','ISA',24,19,null,$b$Neh ntu rai jêh, neh ntu khêk jêh, neh ntu n'gơ ktang ngăn.$b$,false),
('bunong-vn','ISA',24,20,null,$b$Neh ntu hăn rklĭng drĭt tâm ban ma du huê bunuyh nhŭl ndrănh, păng nchah tâm ban ma njao; nau tih păng ƀư jâk păng, păng prah, jêh ri mâu mra hôm dâk ôh.$b$,true),
('bunong-vn','ISA',24,21,null,$b$Tâm nar nây tâm trôk Yêhôva mra tâm rmal phung ta han tâm trôk, jêh ri ta neh ntu Yêhôva mra tâm rmal phung hađăch neh ntu.$b$,true),
('bunong-vn','ISA',24,22,null,$b$Bu mra tâm rgum khân păng tâm ban ma bu rƀŭn phung bu nă tâm ntu, bu mra krŭng khân păng tâm ndrung bu nă; jêh ri rlau âk nar bu mra tâm rmal khân păng.$b$,false),
('bunong-vn','ISA',24,23,null,$b$Dôl nây khay mâu hôm nchrat ang ôh jêh ri nar mra bêk; yor lah Yêhôva ma phung ta han mra chiă uănh ta yôk Siôn jêh ti ta ƀon Yêrusalem, jêh ri păng mra tâm mpơl nau chrêk rmah păng ta năp phung bu ranh păng.$b$,false),
('bunong-vn','ISA',25,1,null,$b$Ơ Yêhôva, may jêng Brah Ndu gâp; gâp mra mât ton ma may, gâp mra tâm rnê ma amoh may, yor lah may ƀư jêh nau khlay mbor kan may nkra jêh bơh kăl e ma nau răp jăp jêh ri na nê̆.$b$,true),
('bunong-vn','ISA',25,2,null,$b$Yor lah may ăn jêh ƀon toyh jêng du nku bun lŭ, ƀon nâp jêng jêh ndơ rai; ngih hađăch phung bu năch mâu hôm jêng ƀon ôh, bu mâu mra đŏng rdâk păng ôh.$b$,false),
('bunong-vn','ISA',25,3,null,$b$Yor nây phung ƀon lan ktang mra ăn nau chrêk rmah ma may; âk ƀon toyh phung ndŭl mpôl mhĭk ƀai mra klach yơk ma may.$b$,true),
('bunong-vn','ISA',25,4,null,$b$Yor lah may jêng ntŭk krap ma phung o-ach, ntŭk nâp ma phung pưt ndơ tâm nau rêh ni khân păng, du ntŭk krap bơh sial phŭt, n'hâm king duh nar; Yor lah nau phung ƀai ƀư jêng tâm ban ma sial phŭt njach pêr,$b$,false),
('bunong-vn','ISA',25,5,null,$b$tâm ban ma nau duh tâm ntŭk sơh. May mra king nteh phung bu năch, tâm ban ma nau duh roh tơ lah geh n'hâm gui ndâr tŭk, pô nây lĕ nau mprơ phung ƀai mra rlu.$b$,false),
('bunong-vn','ISA',25,6,null,$b$Ta yôk aơ Yêhôva ma phung ta han mra nkra nau nhêt sông ma ndơ lay ma lĕ rngôch phung ƀon lan, nau nhêt sông dak play kriăk ƀâu ơm, mpa lay bêng ma glo nting, dak play kriăk ƀâu ơm bu trih jêh.$b$,true),
('bunong-vn','ISA',25,7,null,$b$Ta yôk aơ păng mra ƀư rai ndơ nkŭm lĕ rngôch phung ƀon lan.$b$,true),
('bunong-vn','ISA',25,8,null,$b$Păng mra ƀư lôch lơi nau khĭt n'ho ro. Kôranh Brah Yêhôva mra jut dak măt bơh lĕ rngôch muh măt, jêh ri păng mra sŏk lơi nau bêk phung ƀon lan păng bơh lam neh ntu, Yor lah Yêhôva lah jêh.$b$,false),
('bunong-vn','ISA',25,9,null,$b$Tâm nar nây bu mra lah, “Aơ yơh Brah Ndu he, he kâp gân jêh păng gay ma păng tâm rklaih he. Aơ yơh Yêhôva he kâp gân jêh păng; ăn he răm jêh ri maak yor nau păng tâm rklaih.$b$,true),
('bunong-vn','ISA',25,10,null,$b$Yor lah ti Yêhôva mra gŭ ta yôk aơ, jêh ri bu mra jot bri Môap ta ntŭk păng tâm ban ma bu jot rhe tâm ntŭk bu nkhŭt ndŏk.$b$,false),
('bunong-vn','ISA',25,11,null,$b$Ta nklang ntŭk nây păng mra yơr ti tâm ban ma du huê yơr ti dôl re dak; ƀiă lah Yêhôva mra nklơ̆ nau sưr păng ndrel nau njêh ti păng.$b$,false),
('bunong-vn','ISA',25,12,null,$b$Yêhôva mra ƀư rlâm ntŭk king nâp ta klơ pêr păng, nklơ̆ kŏ cha lôt ta neh rmuy.$b$,false),
('bunong-vn','ISA',26,1,null,$b$Tâm nar nây bu mra mprơ nau mprơ aơ tâm bri Yuđa: He geh du ƀon toyh nâp, Yêhôva ăn nau tâm rklaih jêng pêr mbâl jêh ri ntŭk n'gang.$b$,true),
('bunong-vn','ISA',26,2,null,$b$Pơk hom mpông pêr gay ma ndŭl mpôl sŏng djôt prăp nau chroh dơi lăp.$b$,false),
('bunong-vn','ISA',26,3,null,$b$May prăp nuih n'hâm ma nau đăp mpăn rah vah nơm gŭ mĭn ƀa ƀơ ma may yor lah păng rnơm ma may.$b$,false),
('bunong-vn','ISA',26,4,null,$b$Nsing hom ma Yêhôva ƀa ƀơ n'ho ro, yor lah Yêhôva Brah Ndu jêng lŭ gŭ n'ho ro.$b$,false),
('bunong-vn','ISA',26,5,null,$b$Păng n'glưh jêh phung gŭ ta ntŭk prêh tâm ƀon toyh. Păng n'glưh ƀon nây tât ta neh, klŭp păng ta neh muy.$b$,true),
('bunong-vn','ISA',26,6,null,$b$Jâng phung o-ach jot păng.$b$,false),
('bunong-vn','ISA',26,7,null,$b$Trong phung sŏng jêng lâng. Ơ Nơm Sŏng, may ƀư ăn lâng trong phung sŏng.$b$,true),
('bunong-vn','ISA',26,8,null,$b$Ơ Yêhôva hên gŭ kâp may ta trong nau may phat dôih tâm mpơl. Nuih n'hâm hên rŏng ngăn ma amoh may hên kah gĭt.$b$,true),
('bunong-vn','ISA',26,9,null,$b$Nuih n'hâm gâp klâng ma may dôl măng na nê̆ tâm trôm săk gâp huêng gâp nđơr ŭch joi may. Yor lah tơ lah nau may phat dôih hao gŭ ta neh ntu, phung gŭ tâm neh tu mra nti nau sŏng srăng,$b$,false),
('bunong-vn','ISA',26,10,null,$b$Tơ lah bu yô̆ ma nơm ƀai păng mâu nti nau sŏng srăng ôh. Păng mra ƀư nau mhĭk tâm bri sŏng srăng jêh ri mâu saơ ôh nau rnam Yêhôva.$b$,false),
('bunong-vn','ISA',26,11,null,$b$Ơ Yêhôva, ti may yơr jêh, ƀiă lah khân păng mâu saơ ôh. Ăn khân păng saơ nau may nđơr ŭch ma phung ƀon lan may jêh ri ăn khân păng bêk. Ăn ŭnh prăp jêh ma phung rlăng đah may sa lơi khân păng.$b$,true),
('bunong-vn','ISA',26,12,null,$b$Ơ Yêhôva, may mra njêng nau đăp mpăn ma hên, may ƀư an jêh ma hên lĕ kan hên ƀư.$b$,true),
('bunong-vn','ISA',26,13,null,$b$Ơ Yêhôva Brah Ndu hên, phung kôranh êng rlau ma may mâp chiă uănh jêh phung hên, ƀiă lah hên mra kuăl vơl knŏng ma amoh may.$b$,false),
('bunong-vn','ISA',26,14,null,$b$Khân păng khĭt jêh, khân păng mâu mra rêh ôh. Khân păng jêng phan jêh, khân păng mâu mra plơ̆ dâk ôh. May tâm rmal ƀư rai jêh khân păng, jêh ri jut lơi lĕ nau bu kah gĭt ma khân păng.$b$,false),
('bunong-vn','ISA',26,15,null,$b$Ƀiă lah may ăn bĭk rơ̆ jêh ndŭl mpôl hên, Ơ Yêhôva, may hŏ ƀư bĭk jêh ndŭl mpôl hên; may geh jêh nau chrêk rmah. May ƀư ăn toyh jêh lĕ rngôch n'har neh bri hên.$b$,true),
('bunong-vn','ISA',26,16,null,$b$Ơ Yêhôva, dôl geh nau rêh ni khân păng joi may; khân păng kuăl mbơh sơm tơ lah may nkra khân păng.$b$,false),
('bunong-vn','ISA',26,17,null,$b$Tâm ban ma du huê bu ur ntreo dăch ji deh jêh ri nter dôl mông jêr jŏk tât ma păng, tâm ban pô nây lĕ hên jêng ta năp may, Ơ Yêhôva.$b$,false),
('bunong-vn','ISA',26,18,null,$b$Hên ntreo jêh, hên gŭ jêh tâm nau ji, jêh ri tâm ban ma hên deh ma sial. Hên mâu ƀư nau tâm rklaih ma neh ntu ôh, mâu lĕ hên deh ma neh ntu.$b$,false),
('bunong-vn','ISA',26,19,null,$b$Phung khĭt may mra ăn plơ̆ rêh, săk jăn khân păng mra ăn plơ̆ dâk. Ơ phung gŭ tâm ndruyh neh, kah rngăl bêch nter răm hom. Yor lah dak ngom may jêng dak ngom lam môch, jêh ri neh ntu mra deh ma phung ƀon lan păng khĭt jêh.$b$,false),
('bunong-vn','ISA',26,20,null,$b$Văch hom, Ơ phung ƀon lan gâp, lăp hom tâm jrô khân may, jêh ri chăng mpông pa kơi khân may. Du krap hom khân may ƀât lât kŏ nau ji nuih rlau jêh.$b$,true),
('bunong-vn','ISA',26,21,null,$b$Yor lah aơ, Yêhôva mra luh bơh ntŭk păng gay tâm rmal phung gŭ ta neh ntu yor nau kue khân păng, neh ntu mra tâm mpơl mham pling jêh tâm păng, jêh ri mâu mra nkŭm đŏng ôh phung bu nkhĭt jêh.$b$,false),
('bunong-vn','ISA',27,1,null,$b$Tâm nar nây Yêhôva mra tâm rmal Lêviathan, bêh du ngăch, ma đao păng dăng, toyh ktang; păng mra tâm rmal Lêviathan, bêh kue kuăt; jêh ri păng mra nkhĭt bêh nhŭk nhăk gŭ tâm dak mƀŭt.$b$,true),
('bunong-vn','ISA',27,2,null,$b$Tâm nar nây, “Mprơ hom ma đang play kriăk ƀâu ueh!$b$,true),
('bunong-vn','ISA',27,3,null,$b$Gâp, jêng Yêhôva, jêng nơm chiă gâp djrah dak ma păng ƀa ƀơ, gâp chiă uănh păng, nar jêh ri măng, klach bu ƀư mhĭk ma păng.$b$,true);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','ISA',27,4,null,$b$Gâp mâu geh nau nuih ôh. Ueh lơn tơ lah geh tơm si lok mâu lah rtau lok tâm rdâng đah gâp. Tơ lah pô nây gâp mra hăn tâm lơh đah khân păng, gâp mra su lơi khân păng ndrel n'grŭp.$b$,false),
('bunong-vn','ISA',27,5,null,$b$Mâu lah ăn khân păng sŏk dơn nau gâp n'gang, ăn khân păng joi nau đăp mpăn đah gâp.”$b$,false),
('bunong-vn','ISA',27,6,null,$b$Tâm rnôk kăndơ̆ phung. Yakôp mra njŭr reh, phung Israel mra ăn jêng kao jêh ri nkeh, jêh ri khân păng mra ăn bêng neh ntu ma play.$b$,false),
('bunong-vn','ISA',27,7,null,$b$Yêhôva mâp dong jêh lĕ khân păng tâm ban ma păng dong jêh phung dong khân păng? Mâu lah bu nkhĭt jêh lĕ khân păng tâm ban ma bu nkhĭt phung nkhĭt jêh khân păng?$b$,true),
('bunong-vn','ISA',27,8,null,$b$Ma nau veh keh yơh may tâm rmal jêh khân păng ma nau nsot khân păng bơh bri; Păng nsot khân păng ma nau păng ntrŭt ktang tâm nar geh sial bơh lơ.$b$,false),
('bunong-vn','ISA',27,9,null,$b$Yor nây ma nau aơ bu mra ƀư kloh nau kue phung Yakôb jêh ri pô aơ jêng lĕ nau tât yor nau ƀư kloh nau tih khân păng: Brah Ndu mra ăn lĕ rngôch lŭ nơng jêng tâm ban ma lŭ klo lêk jêh, mâu mra geh brah Asêrim jêh ri nơng gŭch mpa ƀâu kah ăt hôm ôh.$b$,true),
('bunong-vn','ISA',27,10,null,$b$Yor lah ƀon pôih gŭ êng, jêng ntŭk gŭ bu cha lơi jêh, hŏng tâm ban ma bri ndah. Ta nây ntŭk kon ndrôk sa gơ̆ , khân păng bêch jêh ri sa n'ha n'gĭng si ta nây.$b$,false),
('bunong-vn','ISA',27,11,null,$b$Tơ lah n'gĭng păng kro, bu kêch lơi, phung bu ur sŏk gay ƀư long. Yor lah phung ƀon lan aơ mâu geh nau gĭt rbăng ôh. Yor nây nơm njêng khân păng mâu mra yô̆ ma khân păng ôh; nơm njêng khân păng mâu mra tâm mpơl nau ueh ma khân păng ôh.$b$,false),
('bunong-vn','ISA',27,12,null,$b$Tâm nar nây Yêhôva mra rchŭ n'gŏch ntơm bơh dak krong Me tât ta dak n'hor bri Êjipt, jêh ri ơ phung ƀon lan Israel, bu mra dônh khân may du huê du huê.$b$,true),
('bunong-vn','ISA',27,13,null,$b$Tâm nar nây bu mra uh nŭng toyh. Phung roh jêh tâm bri Asiri jêh ri phung bu nsot jêh ta bri Êjipt mra văch mbah yơk ma Yêhôva ta yôk kloh ueh ta ƀon Yêrusalem.$b$,false),
('bunong-vn','ISA',28,1,null,$b$Rêh ni ngăn ma rvang kao ƀư sưr phung vay nhŭl ndrănh ta bri Êphraim, ma kao ueh păng nhop jêh, gŭ ta klơ kô yôk rlŭng jêng ngăn, ma ƀon nây ƀon sưr phung vay nhŭl ndrănh!$b$,true),
('bunong-vn','ISA',28,2,null,$b$Aơ, Kôranh Brah geh du huê brah jêh ri ktang, tâm ban ma sial phŭt geh pler, tâm ban ma sial ƀư rai, tâm ban ma sial phŭt dak ktang ler rlau kơh, păng mra klŭp ô băl dŭt dăng ta neh.$b$,false),
('bunong-vn','ISA',28,3,null,$b$Păng mra jot rvang kao ƀư sưr phung vay nhŭl ndrănh ta bri Êphraim.$b$,true),
('bunong-vn','ISA',28,4,null,$b$Jêh ri kao ueh păng klêu, nkhơng gŭ ta klơ yôk rlŭng jêng ngăn mra jêng tâm ban ma play rvi dŭm lor yăn kăl vai. Tơ lah du huê saơ play nây tâm ti păng, păng sa ro.$b$,false),
('bunong-vn','ISA',28,5,null,$b$Tâm nar nây Yêhôva ma phung ta han mra jêng du mlâm đon hađăch nau chrêk rmah, jêh ri đon hađăch ueh ma kô̆ ƀon lan păng hôm.$b$,true),
('bunong-vn','ISA',28,6,null,$b$Păng mra jêng nau mĭn nau sŏng prăp ma kôranh phat dôih, jêh ri nau ktang ma phung mprơh phung rlăng rŭch bơh mpông pêr.$b$,false),
('bunong-vn','ISA',28,7,null,$b$Phung aơ tâm ban lĕ ve măt yor ndrănh, jêh ri hăn nsing drit yor nhŭl ndrănh: Phung kôranh ƀư brah jêh ri phung kôranh nơm mbơh lor ve măt yor ndrănh ƀư, ndrănh ƀư rluk jêh khân păng; khân păng hăn nsing drit ndrănh ktang ƀư, khân păng vĭ rblang tih nau tâm saơ, khân păng ƀư chêh prah dôl gŭ phat dôih.$b$,true),
('bunong-vn','ISA',28,8,null,$b$Yor lah lĕ rngôch sưng sông bêng hok, mâu geh ntŭk kloh ôh.$b$,false),
('bunong-vn','ISA',28,9,null,$b$“Ma mbu nâm păng mra nti nau gĭt mĭn? Ma mbu nâm păng mra rblang nau nti? Di lĕ ma phung kon se cha lơi pu toh, mhe klaih pu toh?$b$,true),
('bunong-vn','ISA',28,10,null,$b$Yor lah geh pô aơ. Ƀư jêh ri đŏng, ƀư hom, ƀư jêh ri lĕ ƀư đŏng, mbor ntop ma mbor, mbor lĕ ntop đŏng ma mbor, ta aơ djê̆ ta ri djê̆.”$b$,false),
('bunong-vn','ISA',28,11,null,$b$Na nê̆ păng mra ngơi ma phung ƀon lan aơ ma mpiăt ngơi nau phung bu năch.$b$,false),
('bunong-vn','ISA',28,12,null,$b$Ma khân păng yơh păng lah, “Aơ ntŭk rlu, ăn hom nơm rgănh dơi rlu; aơ ntŭk đăp mpăn.” Ƀiă lah khân păng mâu ŭch iăt ôh.$b$,false),
('bunong-vn','ISA',28,13,null,$b$Yor nây nau Yêhôva ngơi mra geh ma khân păng, ƀư jêh ri ƀư tay đŏng, lĕ ƀư jêh ri ƀư đŏng, mbor ntop ma mbor, lĕ mbor jêh ntop đŏng ma mbor, ta aơ djê̆, ta ri djê̆, gay ma khân păng dơi hăn jêh ri prah talang, chah geh dăk jêh ri bu geh nhŭp.$b$,false),
('bunong-vn','ISA',28,14,null,$b$Yor nây gŭ iăt hom nau Yêhôva ngơi, Ơ phung dăng mưch, phung chiă uănh phung ƀon lan aơ ta ƀon Yêrusalem!$b$,true),
('bunong-vn','ISA',28,15,null,$b$Yor lah khân may lah jêh, “Hên ƀư jêh nau tâm rnglăp đah nau khĭt, jêh ri hên tâm rnglăp jêh đah Ƀon Phung Khĭt. Tơ lah nau rêh ni rmeh ler mra rgăn, nau nây mâu mra tât ma hên ôh; yor lah hên ăn jêh nau mƀruh jêng ntŭk hên krap, jêh ri nau mâu ngăn jêng ntŭk hên du krap.”$b$,false),
('bunong-vn','ISA',28,16,null,$b$Yor nây Kôranh Brah Yêhôva lah pô aơ: “Aơ gâp dơm tâm Siôn du mlâm lŭ, du glo lŭ bu rlong uănh jêh, lŭ njônh khlay tâm mbon nâp. Mbu nâm chroh mâu mra rdja nuih n'hâm ôh.$b$,true),
('bunong-vn','ISA',28,17,null,$b$Gâp mra ăn nau di ƀư rse veh, jêh ri nau sŏng srăng jêng ndơ veh rnhuan; jêh ri pler mra ƀư rai lơi ntŭk nau mƀruh khân may krap, jêh ri dak mra lip ntŭk khân may du krap.$b$,false),
('bunong-vn','ISA',28,18,null,$b$Rnôk nây nau khân may tâm rnglăp đah nau khĭt mâu mra hôm jêng ôh, nau khân may tâm rnglăp đah Ƀon Phung Khĭt mâu mra gŭ nâp ôh. Tơ lah nau rêh ni rmeh ler mra rgăn, khân may mra rai yot.$b$,false),
('bunong-vn','ISA',28,19,null,$b$Ăp tơ̆ păng mra rgăn, păng mra nhŭp rdu khân may. Yor lah păng mra rgăn ăp ôi, nar jêh ri măng.” Jêh ri khân may mra klach ngăn tơ lah gĭt rbăng nau mbơh nây.$b$,false),
('bunong-vn','ISA',28,20,null,$b$Yor lah sưng bêch jêng gleh ir ma bu dơi lâng săk ta nây, jêh ri nah jê̆ ma bu dơi ntâk.$b$,false),
('bunong-vn','ISA',28,21,null,$b$Yor lah Yêhôva mra dâk tâm ban ma păng ƀư jêh ta yôk Pêrasim, păng mra ji nuih tâm ban ma tâm rlŭng Gibaôn, gay ma păng dơi ƀư jêh kan păng hih rhâl, jêh ri ƀư kan păng bu mâu gĭt năl ôh.$b$,true),
('bunong-vn','ISA',28,22,null,$b$Yor nây aƀaơ aơ, lơi hôn mưch ôh, klach lah rse kât rêt tay khân may, yor lah gâp tăng jêh bơh Kôranh Brah Yêhôva ma phung ta han nau păng ntăm mra ƀư rai lĕ bri neh.$b$,true),
('bunong-vn','ISA',28,23,null,$b$Rkêng tôr, jêh ri gŭ iăt bâr gâp. Rkêng tôr hom jêh ri iăt nau gâp ngơi.$b$,true),
('bunong-vn','ISA',28,24,null,$b$Di lĕ nơm kai mir ŭch srih mâu lah gŭ kai ƀa ƀơ? Di lĕ păng pŏk jêh ri ƀư hăch ƀa ƀơ neh păng?$b$,false),
('bunong-vn','ISA',28,25,null,$b$Tơ lah jêh păng rli lâng neh, mâu di păng srih ntil aơ jêh ri ntil kumin; jêh ri saơ ba ƀlê geh mbor, ba orgơ di ntŭk tâm nal jêh, jêh ri ba êng ta pĭt mir?$b$,false),
('bunong-vn','ISA',28,26,null,$b$Yor lah Brah Ndu păng nti ma păng, jêh ri sâm nti păng ƀư di.$b$,false),
('bunong-vn','ISA',28,27,null,$b$Bu mâu tôp ôh ntil aơ ma nôp, jêh ri jâng ndeh seh mâu jot ôh ntil kumin; ƀiă lah bu dong ntil aơ ma mâng, jêh ri ntil kumin ma mâng lĕ.$b$,false),
('bunong-vn','ISA',28,28,null,$b$Bu ƀư hăch ba ƀlê, bu mâu mprah păng mro ôh. Nđâp tơ lah bu ăn jâng ndeh jot păng, seh păng mâu ƀư hăch păng ôh.$b$,false),
('bunong-vn','ISA',28,29,null,$b$Nau nây tâm ban lĕ luh bơh Yêhôva ma phung ta han, păng jêng nơm nchră khlay ngăn, jêh ri nơm blau mĭn ngăn.$b$,false),
('bunong-vn','ISA',29,1,null,$b$Rêh ni ngăn ma ƀon Ariêl, ma ƀon Ariêl. Ƀon Y-Đavit ƀư ntŭk păng gŭ! Ntop đŏng năm ma năm, ăn lĕ rngôch nau sông sa tât tĭng năm di ndăch.$b$,true),
('bunong-vn','ISA',29,2,null,$b$Gâp mra ăt ƀư rêh ni ƀon Ariêl; Jêh ri mra geh nau rngot klâng jêh ri mra geh nau lŭng nter, jêh ri păng mra jêng ma gâp tâm ban ma ƀon Ariêl.$b$,false),
('bunong-vn','ISA',29,3,null,$b$Gâp mra ƀư pôih nchueng may, gâp mra nchueng jŭm may ma phung ta han, gâp mra rdâk ntŭk tâm lơh đah may.$b$,true),
('bunong-vn','ISA',29,4,null,$b$May mra ngơi bơh ntŭk jru tâm dâng neh, jêh ri bâr may mra luh bơh ndruyh neh, bâr may mra luh bơh neh tâm ban ma bâr phan, jêh ri may mra ngơi ƀrŏk ƀrŏl bơh ndruyh neh.$b$,false),
('bunong-vn','ISA',29,5,null,$b$Ƀiă lah phung rlăng đah may âk lơn mra jêng tâm ban ma ndruyh neh muy. Phung âk janh ƀai mra jêng tâm ban ma lâk nkhoh khôm rdu.$b$,true),
('bunong-vn','ISA',29,6,null,$b$Ƀât lât Yêhôva ma phung ta han mra văch ma may, ma bâr nglaih, ma nau sâr neh ntu, jêh ri nteh ktang, ma sial blông, sial phŭt, jêh ri ma mpiăt ŭnh hit.$b$,false),
('bunong-vn','ISA',29,7,null,$b$Lĕ phung ndŭl mpôl âk tâm lơh đah ƀon Ariêl, lĕ rngôch phung ƀư ma păng jêh ri pôih păng, phung ƀư rêh ni ma păng mra jêng tâm ban ma nau mbơi, tâm ban ma du nâu tâm saơ dôl măng,$b$,true),
('bunong-vn','ISA',29,8,null,$b$tâm ban ma du huê ji ngot mbơi sông sa, ƀiă lah tơ lah păng kah rngăl ndŭl ăt hŏng; mâu lah tâm ban ma du huê ji hir mbơi nhêt dak, ƀiă lah tơ lah păng kah rngăl păng rgănh jêh ri ăt ji hir. Tâm ban pô nây lĕ, lĕ rngôch phung ndŭl mpôl âk tâm lơh đah yôk Siôn mra jêng.$b$,false),
('bunong-vn','ISA',29,9,null,$b$Ăn khân may ndrŏt jêh ri gŭ hih rhâl! Ăn khân may nhêp măt jêh ri jêng phung chieh măt. Ăn khân may nhŭl ndrănh, ƀiă lah mâu geh ma dak ndrănh ktang ôh; ăn khân may hăn nsing drit, ƀiă lah mâu tăp yor ndrănh ôh.$b$,true),
('bunong-vn','ISA',29,10,null,$b$Yor lah Yêhôva ăn tât jêh ma khân may nau bêch ngăn; păng ƀư nhêp jêh măt khân may, măt khân may nâm bu ntĭt phung kôranh nơm mbơh lor, păng nkŭm jêh bôk khân may, bôk nâm bu ntĭt phung geh nau tâm saơ.$b$,false),
('bunong-vn','ISA',29,11,null,$b$Lĕ rngôch nau khân may tâm saơ aơ jêng tâm ban ma rplay ngơi tâm du pŏk ndrom sa mƀŭt bu nchăng jêh. Tơ lah bu ăn ndrom sa mƀŭt nây ma du huê bunuyh blau uănh sămƀŭt jêh ri lah, “Uănh hom nau aơ,” pô ri păng plơ̆ lah, “Gâp mâu dơi ôh, yor lah bu nchăng păng jêh.”$b$,false),
('bunong-vn','ISA',29,12,null,$b$Jêh ri tơ lah bu ăn ndrom sămƀŭt nây na du huê bunuyh mâu blau uănh sămƀŭt ôh, lah: “Uănh hom nau aơ.” Pô ri păng plơ̆ lah: “Gâp mâu blau uănh sămƀŭt ôh.”$b$,false),
('bunong-vn','ISA',29,13,null,$b$Kôranh Brah lah: “Yor lah phung ƀon lan aơ văch êp gâp jêh ri yơk ma gâp ma bâr mbung jêh ri mpiăt khân păng, dôl nuih n'hâm khân păng ngai đah gâp; Jêh ri nau khân păng klach yơk ma gâp knŏng jêng nau bunuyh ntăm khân păng nti răk jêh.$b$,true),
('bunong-vn','ISA',29,14,null,$b$Yor nây, aơ gâp mra ƀư kan khlay ma phung ƀon lan aơ, kan brah jêh ri khlay ngăn. Nau gĭt mĭn phung blau mĭn khân păng mra dơm dam, jêh ri nau gĭt rbăng phung khân păng blau sek uănh mra roh.”$b$,false),
('bunong-vn','ISA',29,15,null,$b$Rêh ni ngăn phung pôn bơh Yêhôva nau khân păng tâm nchră, kan khân păng gŭ tâm nau ngo, jêh ri khân păng lah: “Mbu dơi saơ he?” Jêh ri “Mbu dơi gĭt năl he?”$b$,true),
('bunong-vn','ISA',29,16,null,$b$Khân may plăch ndơ tâm dâng klơ yơh! Bu mra kơp nơm mon tâm ban ma uk lĕ, kŏ ndơ ƀư, lah ma nơm ƀư. “Păng mâu mâp ƀư gâp ôh.” Păng mâu geh nau gĭt rbăng ôh.$b$,true),
('bunong-vn','ISA',29,17,null,$b$Mâu di hĕ hôm knŏng ƀât bri Liban mra rgâl jêng du đang play, jêh ri đang play mra jêng tâm ban ma krŏng?$b$,true),
('bunong-vn','ISA',29,18,null,$b$Tâm nar nây phung tĭk mra tăng nau ngơi bơh du pŏk ndrom sămƀŭt, jêh ri măt phung chieh mra saơ bơh nau ngo, vêt-vê.$b$,false),
('bunong-vn','ISA',29,19,null,$b$Phung tông bâr mra răm maak âk lơn dôl tâm Yêhôva, jêh ri phung o ach mra răm maak yor Nơm Kloh Ueh Israel.$b$,false),
('bunong-vn','ISA',29,20,null,$b$Yor lah nơm janh ƀai mra rai yot, nơm mưch mra roh, jêh ri lĕ rngôch phung kâp ƀư nau kue bu mra ƀư rai.$b$,false),
('bunong-vn','ISA',29,21,null,$b$Phung nây nsŭk bu ma nau khân păng ngơi; ƀư vĭ kôranh phat dôih ta mpông pêr, jêh ri mbơh nau mƀruh ƀư nsak ma nơm sŏng.$b$,false),
('bunong-vn','ISA',29,22,null,$b$Yor nây, Yêhôva, jêng Nơm tâm chuai jêh Y-Abraham, lah di ma ngih Yakôb, “Aƀaơ aơ phung Yakôb mâu mra bêk ôh, muh măt khân păng mâu lĕ jêng pal.$b$,true),
('bunong-vn','ISA',29,23,null,$b$Yor lah tơ lah khân păng saơ phung kon khân păng jêng kan ti gâp ƀư ta nklang khân păng, khân păng mra yơk ma amoh gâp; khân păng mra yơk ma Nơm Kloh Ueh Y-Yakôb, jêh ri mra klach ma Brah Ndu$b$,false),
('bunong-vn','ISA',29,24,null,$b$Phung geh nau mĭn vĭ mra tât ta nau gĭt rbăng, jêh ri phung ngơi ƀrôk mra sŏk dơn nau sâm nti.”$b$,false),
('bunong-vn','ISA',30,1,null,$b$Yêhôva lah: “Rêh ni ngăn ma phung kon tâm rdâng, nkhơng ma iăt nau phung nchră kan, ƀiă lah mâu iăt ôh nau gâp, phung ƀư nau tâm rnglăp, ƀiă lah mâu di bơh Brah Huêng Ueh Gâp ôh, gay ma khân păng dơi ntop nau tih ma nau tih.$b$,true),
('bunong-vn','ISA',30,2,null,$b$Khân păng jŭr hăn ta bri Êjipt mâu ôp gâp lor ôh; gay krap rnơm nau ktang hađăch Pharaôn n'gang, jêh ri joi ntŭk mbe tâm dâng n'hâm gui bri Êjipt!$b$,false),
('bunong-vn','ISA',30,3,null,$b$Yor nây nau ktang Pharaôn n'gang mra plăch jêng nau bêk ma khân may, jêh ri ntŭk mbe tâm dâng n'hâm gui bri Êjipt jêng nau bêk toyh ma khân may.$b$,false),
('bunong-vn','ISA',30,4,null,$b$Yor lah nđâp tơ lah phung kôranh păng gŭ ta ƀon Sôan, jêh ri phung nơm ntuh bâr Kôranh Brah tât ta ƀon Hanês,$b$,false),
('bunong-vn','ISA',30,5,null,$b$lĕ rngôch mra bêk yor du phung ƀon lan mâu jêng khlay ma khân păng ôh, mâu ăn nau khlay mâu lah nau kơl ôh, ƀiă lah nau bêk jêh ri nau mưch.”$b$,false),
('bunong-vn','ISA',30,6,null,$b$Nau jâk di ma jun bri n'gor rđŭng: Bơh lam bri uh ah jêh ri rngot, tă bơh nây luh yau mŭr me, jêh ri nkuăng, bêh rmâng jêh ri bêh nhŭk nhăk mpăr, khân păng rdeng drăp ndơ khân păng ma seh bri jêh ri drăp khlay khân păng ta klơ kuk seh Samô ma du phung ƀon lan mâu mra jêng khlay ma khân păng ôh.$b$,true),
('bunong-vn','ISA',30,7,null,$b$Yor lah nau bri Êjipt kơl mâu khlay ôh jêh ri dơm dam. Yor nây gâp rnha păng, “H'Rahap, jêng nơm gŭ rơp gơp.$b$,false),
('bunong-vn','ISA',30,8,null,$b$Hăn hom aƀaơ, tor nau nây ta klơ kađar ta năp khân păng, jêh ri chih nau nây tâm du ndrom Sămƀŭt, gay prăp nau nây ma rnôk kăndơ̆ , jêng nau nkoch mbơh n'ho ro.$b$,true),
('bunong-vn','ISA',30,9,null,$b$Yor lah khân păng jêng du phung ƀon lan tâm rdâng phung kon mƀruh, phung kon mâu ŭch iăt ôh nau Yêhôva sâm nti,$b$,false),
('bunong-vn','ISA',30,10,null,$b$Phung lah ma phung tâm saơ. “Lơi hôm tâm saơ ôh”, Jêh ri ma phung kôranh nơm mbơh lor. “Lơi mbơh lor ma hên nau di ôh; ngơi hom ma hên nau ƀư maak ma tôr, mbơh lor hom ma hên nau tâm saơ vĭ.$b$,false),
('bunong-vn','ISA',30,11,null,$b$Ăn khân may teng du bơh trong sŏng, lơi hôm ăn he iăt ôh nau Nơm Kloh Ueh Israel:$b$,true),
('bunong-vn','ISA',30,12,null,$b$Yor nây Nơm Kloh Ueh Israel lah pô aơ: “Yor lah khân may dun ma nau ngơi aơ, rnơm ma nau tŭn jot jêh ri nau kue,$b$,false),
('bunong-vn','ISA',30,13,null,$b$Yor nây nau kue aơ mra jêng ma khân may tâm ban ma ntŭk trôm đang tâm pêr prêh dăch rlâm, jêh ri chah plŭng ƀât lât dơm.$b$,false),
('bunong-vn','ISA',30,14,null,$b$Păng rai tâm ban ma glah uk bu nchah lơi ăn hăch, kŏ tât ndah hôm e mâu hôm geh rsong ôh, ŭch sŏk ŭnh bơh năk, mâu lah ŭch bâk dak bơh ntu.$b$,true),
('bunong-vn','ISA',30,15,null,$b$Yor lah Kôranh Brah Yêhôva, Nơm Kloh Ueh Israel, lah pô aơ: “Tâm nau khân may rmal jêh ri khân may mra klaih, tâm nau rlu đăp mpăn jêh ri nau rnơm khân may mra geh nau ktang.” Ƀiă lah khân may mâu ŭch ôh,$b$,true),
('bunong-vn','ISA',30,16,null,$b$Jêh ri khân may lah: “Mâu! Hên mra du ngăch ma seh.” Pô nây yơh khân may mra du! Khân may lah: “Hên mra du ncho seh nchuăt ngăch.” Yor nây phung tĭng khân may mra nchuăt ngăch đŏng.$b$,false),
('bunong-vn','ISA',30,17,null,$b$Du rbăn nuyh mra du yor du huê thăm rmat; Jêh ri yor prăm nuyh thăm rmat khân may mra du lĕ kŏ khân may jêng tâm du mlâm n'gâng ta klơ yôk, tâm ban ma bok pla ta klơ gôl.$b$,true),
('bunong-vn','ISA',30,18,null,$b$Yor nây Yêhôva ăt ŭch ngăn ƀư nau ueh ma khân may; Yor nây păng dâk ŭch yô̆ ma khân may. Yor lah Yêhôva jêng Brah Ndu Sŏng; ueh maak ngăn ma lĕ rngôch phung kâp gân ma păng.$b$,true),
('bunong-vn','ISA',30,19,null,$b$Ơ phung ƀon lan Siôn gŭ ta ƀon Yêrusalem khân may mâu mra đŏng nhĭm ôh. Na nê̆ păng mra yô̆ ma khân may tơ lah khân may nter. Tơ lah păng tăng khân may nter, păng mra plơ̆ lah ma khân may.$b$,false),
('bunong-vn','ISA',30,20,null,$b$Nđâp tơ lah Kôranh Brah ăn ma khân may piăng let nau rngot jêh ri dak nau rêh ni, ăt Nơm Sâm Nti khân may mâu mra pôn păng nơm ôh, ƀiă lah măt khân may mra saơ Nơm Sâm Nti khân may.$b$,false),
('bunong-vn','ISA',30,21,null,$b$Tơ lah khân may mra teng pa ma mâu lah pa chiau, tôr khân may mra tăng pa kơi khân may bâr lah: “Aơ trong, hăn ta aơ.”$b$,false),
('bunong-vn','ISA',30,22,null,$b$Jêh ri khân may mra ƀư ƀơ̆ rup trah khân may ndop ma prăk jêh ri rup khân may tŏ chiăr ndop ma mah. Khân may mra mƀăr lơi khân păng tâm ban ma ndơ ƀơ̆ , khân may mra lah ma khân păng: “Du hom.”$b$,false),
('bunong-vn','ISA',30,23,null,$b$Păng mra ăn trôk mih ma găr ntil khân may srih jêh ta neh, jêh ri ba, play bơh neh, mra jêng ueh jêh ri rmeh ler. Tâm nar nây mpô mpa khân may rong mra sa gơ̆ tâm ndrêch toyh.$b$,true),
('bunong-vn','ISA',30,24,null,$b$Ndrôk jêh ri seh bri kai mir mra sa ba kah bu gŭm ma ra-i ndrel dông.$b$,false),
('bunong-vn','ISA',30,25,null,$b$Tơ klơ lĕ rngôch yôk prêh jêh ri dor yôk mra geh dak n'hor hoch, ta nar geh nau tâm nkhĭt toyh tơ lah pôih rlâm.$b$,true),
('bunong-vn','ISA',30,26,null,$b$Nđâp ma nau ang khay mra jêng tâm ban ma nau ang nar, jêh ri nau ang nar mra jêng pơh tơ̆ ktang lơn, tâm ban ma ang pơh nar, tâm nar Yêhôva mra nkŭm lơi ntŭk sôt phung ƀon lan păng, jêh ri ƀư bah ntŭk păng dong ƀư sôt jêh.$b$,false),
('bunong-vn','ISA',30,27,null,$b$Aơ, amoh Yêhôva văch tă bơh ngai ma nau păng duh nuih jêh ri ma nhhŭk ŭnh hao thŭl. Trôm mbung păng bêng ma nau ji nuih, jêh ri mpiăt păng tâm ban ma ŭnh sa.$b$,true),
('bunong-vn','ISA',30,28,null,$b$N'hâm păng jêng tâm ban ma n'hor dak jru ler kơh hao tât ta trô ko, gay ma nsiăng phung ndŭl mpôl ma dông gŭm nau ƀư rai, jêh ri dơm tâm trôm mbung phung ƀon lan loih n'glap nau tâm nkhah.$b$,false),
('bunong-vn','ISA',30,29,null,$b$Khân may mra mprơ tâm ban ma tâm măng bu ƀư nau nhêt sông kloh ueh. Khân may mra geh nuih n'hâm maak tâm ban ma bu ntơm hăn ta yôk Yêhôva, ma Lŭ Israel, dôl bu uh n'hôm.$b$,true),
('bunong-vn','ISA',30,30,null,$b$Jêh ri Yêhôva mra ăn bu iăt bâr păng, jêh ri ăn bu saơ ti păng dong ma nau ji nuih ktang jêh ri ma mpiăt ŭnh hit, ma sial ktang, sial phŭt, jêh ri pler.$b$,false),
('bunong-vn','ISA',30,31,null,$b$Yor lah phung Asiri mra râm sâr tơ lah tăng bâr Yêhôva, tơ lah Yêhôva dong khân păng ma mâng nê̆.$b$,false),
('bunong-vn','ISA',30,32,null,$b$Ăp tong Yêhôva dong khân păng ma mâng rnê̆ mra tŭp ta khân păng ma nau nteh gâr jêh ri gong rêng. Yêhôva mra yơr ti tâm lơh đah khân păng.$b$,false),
('bunong-vn','ISA',30,33,null,$b$Yor lah bơh jŏ jêh bu nkra ntŭk gŭch. Nanê̆ bu nkra păng ma hađăch, păng jru jêh ri dĭ, geh ŭnh jêh ri long âk, n'hâm Yêhôva tâm ban ma n'hor lŭ mô ŭnh mra sênh ăn ŭnh hit. Phung Êjipt Jêng Bunuyh,$b$,false),
('bunong-vn','ISA',31,1,null,$b$Rêh ni ngăn ma phung jŭr hăn ta bri Êjipt ŭch geh nau kơl, phung rnơm ma seh jêh ri rnơm ma ndeh seh, yor lah geh âk, jêh ri rnơm ma phung ncho seh yor lah khân păng ktang ngăn, ƀiă lah mâu uănh ôh ma Nơm Kloh Ueh Israel, mâu lĕ joi Yêhôva!$b$,true),
('bunong-vn','ISA',31,2,null,$b$Ƀiă lah Yêhôva jêng nơm blau mĭn jêh ri dơi ăn nau rêh ni tât. Păng mâu rgâl ôh nau păng ngơi jêh, ƀiă lah mra dâk tâm rdâng đah ngih phung ƀư mhĭk, jêh ri ma phung kơl phung ƀư nau kue.$b$,false),
('bunong-vn','ISA',31,3,null,$b$Phung Êjipt jêng bunuyh, mâu tăp Brah Ndu ôh; seh khân păng jêng nglay puăch, mâu tăp huêng brah ôh. Tơ lah Yêhôva mra yơr ti păng, nơm kơl mra chêh, nđâp nơm bu kơl mra prah, jêh ri lĕ rngôch khân păng mra rai yot ndrel n'grŭp.$b$,false),
('bunong-vn','ISA',31,4,null,$b$Yor lah pô aơ Yêhôva lah jêh ma gâp: “Tâm ban ma yau mŭr mâu lah kon yau mŭr ngrông dăch mpa păng kăp jêh, jêh ri nđâp tơ lah bu kuăl phung rmăk biăp ƀư ma păng, păng mâu klach ôh ma bâr khân păng, mâu lĕ phit yor nteh khân păng, tâm ban pô nây lĕ Yêhôva ma phung ta han mra jŭr văch tâm lơh ta yôk Siôn jêh ri ta yôk păng.$b$,true),
('bunong-vn','ISA',31,5,null,$b$Tâm ban ma sĭm mpăr du ntŭk ta klơ kon khân păng, tâm ban pô nây lĕ Yêhôva ma phung ta han mra n'gang ƀon Yêrusalem. Păng mra n'gang jêh ri tâm rklaih păng, păng yô̆ jêh ri koh dŏng păng.”$b$,false),
('bunong-vn','ISA',31,6,null,$b$Ơ phung ƀon lan Israel, plơ̆ sĭt hom ma nơm khân may tâm rdâng jêh.$b$,true),
('bunong-vn','ISA',31,7,null,$b$Yor lah tâm nar nây ăp nơm mra mƀăr lơi rup brah prăk jêh ri mah, rup brah ti khân may nơm ƀư jêh, lĕ nau tih khân may.$b$,false),
('bunong-vn','ISA',31,8,null,$b$“Nơm Asiri mra prah yor ma đao, mâu tăp đao bunuyh ôh; jêh ri đao mâu tăp đao bunuyh ôh mra nkhĭt păng. Păng mra du bơh đao nây, jêh ri phung bu klâu ndăm păng mra jêng dĭk.$b$,false),
('bunong-vn','ISA',31,9,null,$b$Lŭ păng rnơm mra roh yor nau klach jêh ri phung kôranh ta han păng mra uh ah nchuăt du bơh bok pla păng.” Pô ri Yêhôva lah, nơm jêng tâm ban ma ŭnh tâm yôk Siôn, jêh ri ŭnh năk tâm ƀon Yêrusalem.$b$,true),
('bunong-vn','ISA',32,1,null,$b$Aơ, du huê hađăch mra chiă uănh ma nau sŏng srăng, jêh ri phung kôranh chiă uănh ma nau di.$b$,true),
('bunong-vn','ISA',32,2,null,$b$Ăp nơm mra jêng tâm ban ma ntŭk krap ma sial, ntŭk rnơm klach ma sial phŭt, tâm ban ma n'hor dak tâm ntŭk sơh, tâm ban ma gui n'hâm lŭ toyh tâm neh ntu.$b$,false),
('bunong-vn','ISA',32,3,null,$b$Dôl nây măt phung blau saơ mâu mra bêch ôh, jêh ri ti phung gĭt tăng mra rkêng.$b$,false),
('bunong-vn','ISA',32,4,null,$b$Nuih n'hâm phung ngăch ƀư mra blau mĭn, jêh ri mpiăt phung rlăm mra ngơi ngăch jêh ri rah vah.$b$,false),
('bunong-vn','ISA',32,5,null,$b$Bu mâu hôm mra rnha bunuyh rluk nơm khư bu yơk ôh, mâu lĕ yơk ma nơm ndơm.$b$,true),
('bunong-vn','ISA',32,6,null,$b$Yor lah bunuyh rluk ngơi nau rluk, jêh ri nuih n'hâm păng mĭn ƀư nau kue, ŭch ƀư nau ƀơ̆ ƀơch, jêh ri ngơi nau vĭ tâm rdâng đah Yêhôva, ăn phung ji ngot gŭ ndŭl hŏng, jêh ri sŏk dak nhêt bơh nơm ji hir.$b$,true),
('bunong-vn','ISA',32,7,null,$b$Trong phung ndơm jêng mhĭk; khân păng tâm nchră ƀư ƀai, gay ƀư rai phung o-ach ma nau ngơi mƀruh, nđâp tơ lah phung pưt ndơ dăn jêng di.$b$,true),
('bunong-vn','ISA',32,8,null,$b$Ƀiă lah nơm khlay mĭn ma nau khlay, jêh ri păng gŭ nâp tâm nau khlay păng ƀư.$b$,false),
('bunong-vn','ISA',32,9,null,$b$Ơ phung bu ur gŭ rlu, dâk iăt hom bâr gâp. Ơ phung kon bu ur mâu njrăng, rkêng hom tôr ma nau gâp ngơi.$b$,true),
('bunong-vn','ISA',32,10,null,$b$Tâm du năm khân may mra râm sâr, yor lah mâu mra geh yăn pĕ play kriăk ƀâu ôh, mâu lĕ geh yăn pĕ play êng.$b$,false),
('bunong-vn','ISA',32,11,null,$b$Ơ phung bu ur gŭ rlu, râm sâr hom, ăn khân ay uh ah. Ơ phung bu ur mâu njrăng. Doh lơi bok ao khân ay, gŭ rhôk; vân hom kalŭng ta bŭt khân ay.$b$,false),
('bunong-vn','ISA',32,12,null,$b$Tŭr ntang ntơh khân may yor mir ueh jêh ri yor tơm play kriăk ƀâu play.$b$,true),
('bunong-vn','ISA',32,13,null,$b$Yor neh phung ƀon lan gâp hon lok tơm jêh ri lok rtau, nđâp yor lĕ rngôch ngih maak tâm ƀon răm maak.$b$,false),
('bunong-vn','ISA',32,14,null,$b$Yor lah bu mra cha lơi ngih hađăch, ƀon toyh mra jêng rngol, yôk jêh ri ngih tŭm mra jêng trôm mpa bri ntơm bơh aơ rlet pa năp, ntŭk maak ma seh bri jêh ri ndrêch gơ̆ ma biăp,$b$,false),
('bunong-vn','ISA',32,15,null,$b$kŏ tât Brah Ndu nkhŭt Brah Huêng Ueh ma he tă bơh klơ, jêh ri ndrêch rdah rlơ̆ jêng mir geh play, Jêh ri bu uănh ta mir geh play tâm ban ma krŏng.$b$,false),
('bunong-vn','ISA',32,16,null,$b$Dôl nây mra geh nau di tâm ndrêch rdah, jêh ri nau sŏng srăng tâm mir geh play.$b$,false),
('bunong-vn','ISA',32,17,null,$b$Rplay khlay ngăn bơh nau sŏng srăng mra jêng nau đăp mpăn, jêh ri rplay khlay bơh nau sŏng srăng jêng nau rlu jêh ri nau rnơm ƀa ƀơ.$b$,false),
('bunong-vn','ISA',32,18,null,$b$Phung ƀon lan gâp mra gŭ tâm ntŭk đăp mpăn, tâm ntŭk gŭ rnơm, tâm ntŭk rlu mpăn ngăn.$b$,false),
('bunong-vn','ISA',32,19,null,$b$Nđâp tơ lah dak pler ƀư rai tâm krŏng, jêh ri ƀon toyh mra rlâm,$b$,false),
('bunong-vn','ISA',32,20,null,$b$Ueh maak ngăn ma khân may phung srih tĭng njŏ lĕ rngôch dak, mâu klêng ôh jâng ndrôk jêh ri seh bri.$b$,false),
('bunong-vn','ISA',33,1,null,$b$Rêh ni ngăn ma may, ơ nơm ƀư rai bu, ƀiă lah bu mâu ƀư rai may ôh, nơm ndơm bu, ƀiă lah bu mâu mâp ndơm may ôh! Tơ lah may rlu jêh nau ƀư rai, bu mra ƀư rai may đŏng; tơ lah may lôch jêh ƀư nau ndơm, bu mra ndơm may đŏng.$b$,true),
('bunong-vn','ISA',33,2,null,$b$Ơ Yêhôva, yô̆ nđach an ma hên ƀă, hên kâp gân may. Ăn may jêng nau ktang ma hên ăp ôi, jêh ri nơm tâm rklaih hên tâm$b$,true),
('bunong-vn','ISA',33,3,null,$b$Tơ lah tăng nteh drưh drưh phung ƀon lan du; tơ lah may dâk, phung ndŭl mpôl bunuyh nchah du pru.$b$,false),
('bunong-vn','ISA',33,4,null,$b$Bu dônh ndơ sŏk pit tâm ban ma rhai sa; bu tuy sŏk ndơ nây tâm ban ma krah nsăt.$b$,false),
('bunong-vn','ISA',33,5,null,$b$Yêhôva geh nau yơk yor lah păng gŭ tâm ntŭk klơ. Păng mra mbêng ƀon Siôn ma nau di jêh ri nau sŏng srăng.$b$,true),
('bunong-vn','ISA',33,6,null,$b$Jêh ri păng mra ăn nâp rnôk khân may, jêng nau tâm rklaih rmeh ler, nau blau mĭn, nau gĭt rbăng, nau klach yơk ma Yêhôva jêng drăp khlay păng.$b$,false),
('bunong-vn','ISA',33,7,null,$b$Aơ, phung janh ktang nhĭm pa dih, phung oh mon ktang ma nau đăp mpăn nhĭm rngot ngăn.$b$,true),
('bunong-vn','ISA',33,8,null,$b$Trong toyh rngol jêh, bu mâu hôm hăn ta trong ôh. Bu rlau nau vay tâm rnglăp, bu tâm rmot ma phung mbơh ăn ngăn, bu mâu chrê ma bunuyh ôh.$b$,false),
('bunong-vn','ISA',33,9,null,$b$Bri neh gŭ klân rvê jêh ri rngot klâng. Bri Liban bêk jêh ri klêu, bri Sarôn jêng tâm ban ma ndrêch rdah, bri Basan jêh ri yôk Karmel ƀư rŭng n'ha khân păng.$b$,false),
('bunong-vn','ISA',33,10,null,$b$Yêhôva lah: “Aƀaơ aơ gâp mra dâk, aƀaơ gâp mra hao, aƀaơ aơ gâp mra geh nau yơk.$b$,true),
('bunong-vn','ISA',33,11,null,$b$Khân may mra ntreo ma lâk nkhoh, deh ma rhe, n'hâm khân may mra jêng ŭnh su khân may nơm.$b$,false),
('bunong-vn','ISA',33,12,null,$b$Phung ƀon lan mra jêng tâm ban may klo gŭch jêh, tâm ban ma lok bu sreh su jêh tâm ŭnh.”$b$,false),
('bunong-vn','ISA',33,13,null,$b$Ơ phung gŭ ngai, iăt hom nau gâp ƀư jêh, jêh ri Ơ phung gŭ êp, ăn khân may gĭt nau brah gâp.$b$,true),
('bunong-vn','ISA',33,14,null,$b$Phung ƀư tih tâm ƀon Siôn klach, phung mâu yơk ôh ma Brah Ndu râm sâr, “Mbu tâm phung he dơi gŭ tâm ŭnh hit? Mbu tâm phung he dơi gŭ tâm mpiăt ŭnh hit n'ho ro?.”$b$,false),
('bunong-vn','ISA',33,15,null,$b$Nơm gŭ ngao krau sach ma nau sŏng jêh ri ngơi nau di, nơm tâm rmot ma drăp sa ma nau tŭn jot, nơm rteh ti klach lah sŏk dơn drăp blŏl, nơm sêt tôr mâu ŭch iăt ôh nau rung mham, jêh ri nhêp măt mâu ŭch uănh ma nau mhĭk ôh.$b$,false),
('bunong-vn','ISA',33,16,null,$b$Păng mra gŭ tâm ntŭk prêh, pôih lŭ mra jêng ntŭk păng du krap. Bu mra ăn ndơ sông sa ma păng, păng mâu mra pưt dak ôh.$b$,false),
('bunong-vn','ISA',33,17,null,$b$Măt may mra saơ hađăch tâm nau ueh păng. Măt may mra uănh du rplay bri tât ta n'har ngai.$b$,true),
('bunong-vn','ISA',33,18,null,$b$Nuih n'hâm may mra gŭ mĭn ma nau tâm nhhu: “Mbah nơm kơp prăk? Mbah nơm veh prăk di? Mbah nơm kơp ngih tŭm?”$b$,false),
('bunong-vn','ISA',33,19,null,$b$May mâu hôm mra saơ ôh phung ƀon lan ƀai, phung ƀon lan nây ngơi nau ngo may mâu dơi gĭt rbăng ôh, ngơi mâu rah vah nau bu năch may mâu dơi gĭt rbăng ôh.$b$,false),
('bunong-vn','ISA',33,20,null,$b$Uănh hom ta Siôn, ƀon he kah gĭt prăp ƀư nau nhêt sông. Măt may mra saơ ƀon Yêrusalem, ntŭk gŭ đăp mpăn, ngih bok bu mâu rdu ta ntŭk êng ôh, mâng bu pâng bu mâu mra mâp tŏk ôh, jêh ri rse buănh păng bu mâu mra ƀư tăch.$b$,true),
('bunong-vn','ISA',33,21,null,$b$Ƀiă lah ta nây Yêhôva mra gŭ ndrel đah he ma nau rnam, jêng ntŭk dak krong huy jêh ri dak n'hor. Ta nây kŭmpăn bu vah mâu dơi lăp ôh, jêh ri kŭmpăn toyh mâu dơi nsong lĕ.$b$,false),
('bunong-vn','ISA',33,22,null,$b$Yor lah Yêhôva jêng kôranh phat dôih he, Yêhôva jêng nơm ăn nau vay ma he, păng mra jêng nơm tâm rklaih he.$b$,false),
('bunong-vn','ISA',33,23,null,$b$Brăt may mra mƀơk jêh, păng mâu dơi kât nâp n'gâng bok ôh, mâu lah ling bok. Dôl nây bu mra tâm pă âk ndơ sŏk pit, nđâp phung rvĕn mra sŏk âk ndơ sŏk pit.$b$,false),
('bunong-vn','ISA',33,24,null,$b$Mâu geh du huê bunuyh ƀon lan mra lah, “Gâp ji.” Phung ƀon lan gŭ ta nây mra geh nau yô̆ an ma nau kue khân păng.$b$,false),
('bunong-vn','ISA',34,1,null,$b$Ơ phung ndŭl mpôl bunuyh, văch dăch hom, gay khân may tăng, jêh ri rkêng tôr hom, Ơ phung ƀon lan! Ăn neh ntu jêh ri lĕ rngôch ndơ mbêng păng gŭ iăt, neh ntu jêh ri lĕ mpa luh bơh păng.$b$,true),
('bunong-vn','ISA',34,2,null,$b$Yor lah Yêhôva ji nuih ma lĕ rngôch ndŭl mpôl bunuyh, jêh ri nuih ma lĕ rngôch phung ta han khân păng. Păng prăp jêh khân păng ma nau ƀư rai, păng jao phung nây ăn bu nkhĭt.$b$,false),
('bunong-vn','ISA',34,3,null,$b$Bu mra mƀăr pa dih bunuyh khân păng khĭt, phan khân păng n'hôl ƀâu ôm, jêh ri mham khân păng mra hoch tâm yôk.$b$,false),
('bunong-vn','ISA',34,4,null,$b$Lĕ rngôch phung ta han tâm trôk mra rai lơi, bu mra klôn lơi trôk tâm ban ma bu klôt sămƀŭt. Lĕ rngôch phung ta han păng mra tŭp tâm ban ma n'ha si rŭng tă bơh tơm play kriăk ƀâu, tâm ban ma rŭng n'ha tă bơh tơm play rvi.$b$,true),
('bunong-vn','ISA',34,5,null,$b$Yor lah đao gâp nhêt mpay jêh tâm trôk; aơ păng mra jŭr ŭch phat dôih bri Êđôm, ma phung ƀon lan gâp rtăp rak jêh.$b$,true),
('bunong-vn','ISA',34,6,null,$b$Yêhôva geh du n'gâr đao păng bêng ma mham, jêh ri ngi, ma mham kon biăp jêh ri be, ma ngi play leh biăp nkuăng. Yor lah Yêhôva geh jêh nau ƀư brah ta ƀon Bôsra, nau tâm nkhĭt toyh tâm bri Êđôm$b$,true),
('bunong-vn','ISA',34,7,null,$b$Ndrôk bri mra cha lôt ndrel ma khân păng, jêh ri kon ndrôk nkuăng ndrel ma ndrôk nkuăng ktang. Neh bri khân păng ƀư bĕ ma mham, jêh ri neh mra jêng mbĭr yor nglay ngi mpa khĭt.$b$,false),
('bunong-vn','ISA',34,8,null,$b$Yor lah Yêhôva prăp jêh nar ma nau plơng bôk, du năm mplơ̆ nau nkhôm ma phung rlăng yor Yêhôva ŭch n'gang nau ƀon Siôn.$b$,false),
('bunong-vn','ISA',34,9,null,$b$N'hor dar tâm bri Êđôm mra rgâl jêng dak rhach, ndruyh neh păng mra jêng lŭ mô-ŭnh, jêh ri neh păng mra jêng dak chai rhach ŭnh sa.$b$,true),
('bunong-vn','ISA',34,10,null,$b$Măng nar păng mâu mra ngôm ôh, nhhŭk ŭnh păng mra hao n'ho ro. Tâm lĕ rngôch rnôk păng mra jêng rngol, mâu mra geh bunuyh rgăn ta nây ôh. N'ho ro ôh$b$,false),
('bunong-vn','ISA',34,11,null,$b$Ƀiă lah sĭm jêh ri blŏ mra sŏk ntŭk nây, klang-kô jêh ri nđak mra gŭ ta nây. Yêhôva mra nthăng rse ma nau ƀư rai bri nây, jêh ri yông ndơ jâk ma nau rngot păng.$b$,false),
('bunong-vn','ISA',34,12,null,$b$Bu mra tâm amoh bri nây mâu geh ƀon bri hađăch ta nây ôh, jêh ri lĕ rngôch phung kôranh păng mra roh.$b$,true),
('bunong-vn','ISA',34,13,null,$b$Lok mra hon tâm pôih păng, tơm lok jêh ri rtau lok tâm ntŭk king păng. Păng mra jêng ntŭk prăp ma so bri, ntŭk gŭ sĭm ô trus.$b$,false),
('bunong-vn','ISA',34,14,null,$b$Jun bri mra tâm mâp đah so bri, jêh ri be nkuăng bri tâm kuăl ndrăng băl khân păng. Klang kô măng mra drâm ta nây, jêh ri geh ntŭk rlu.$b$,false),
('bunong-vn','ISA',34,15,null,$b$Ta nây klang kô mra ƀư rsuăn jêh ri tăp. Păng mra păn jêh ri deh kon tâm dâng gui păng. Ta nây klang grât mra tâm rƀŭn nkuăng me.$b$,false),
('bunong-vn','ISA',34,16,null,$b$Joi tâm ndrom Sămƀŭt Yêhôva jêh ri uănh: Mâu mra pưt nguay tâm ndơ nây ôh, mâu geh du mlâm pưt nkuăng mâu lah me ôh. Yor lah mbung Yêhôva ntăm jêh nau nây. Brah Huêng Ueh păng tâm rƀŭn jêh lĕ khân păng.$b$,true),
('bunong-vn','ISA',34,17,null,$b$Păng ƀư nau tâm nchroh ma bu, jêh ri ti păng nthăng jêh njăr rse tâm pă. Khân păng mra geh ntŭk nây n'ho ro, khân păng mra gŭ ta nây tâm lĕ rngôch rnôk.$b$,false),
('bunong-vn','ISA',35,1,null,$b$Bri hŏng jêh ri neh sơh mra maak. Ndrêch rdah mra răm maak jêh ri ăn kao. Tâm ban ma kao Rôs,$b$,true),
('bunong-vn','ISA',35,2,null,$b$Păng mra geh kao âk, jêh ri hâk ma nau maak jêh ri nau mprơ. Bu mra ăn ma păng nau chrêk rmah bri Liban, nau rnam yôk Karmel jêh ri bri Sarôn. Khân păng mra saơ nau chrêk rmah Yêhôva, nau rnam Brah Ndu he.$b$,false),
('bunong-vn','ISA',35,3,null,$b$Ăn ktang hom ti rdja, jêh ri ăn nâp hom kômâk rdja.$b$,true),
('bunong-vn','ISA',35,4,null,$b$Lah hom ma phung geh nuih n'hâm klach, “Gŭ ktang hom, lơi klach ôh! Aơ Brah Ndu khân may mra văch, păng mra văch ma nau plơng bôk, ma nau nkhôm bơh Brah Ndu. Păng mra văch jêh ri tâm rklaih khân may.”$b$,false),
('bunong-vn','ISA',35,5,null,$b$Dôl nây bu mra lin măt phung chih, jêh ri ƀư rbăng tôr phung tĭk.$b$,true),
('bunong-vn','ISA',35,6,null,$b$Dôl nây nơm rvĕn mra kadăt kadưt tâm ban ma jun, jêh ri mpiăt bunuyh mlo mra mprơ ma nau maak. Yor lah dak mra bruh kloh tâm bri hŏng, jêh ri mra geh n'hor dak tâm ndrêch rdah.$b$,false),
('bunong-vn','ISA',35,7,null,$b$Choih duh mra jêng dak nglao, jêh ri neh sơh mra jêng tu dak. Ntŭk so bri gŭ mra rgâl jêng nung rpho, gơ̆ jêh ri proh treng.$b$,false),
('bunong-vn','ISA',35,8,null,$b$Mra geh ta nây du ntŭk trong sâng toyh bu rnha păng Trong Kloh Ueh: Phung ƀơ̆ ƀơch mâu mra hăn ta nây ôh, ƀiă lah mra prăp ma phung hăn tâm nau kloh ueh, jêh ri phung rluk mâu mra nsong mblêng ta nây ôh.$b$,true),
('bunong-vn','ISA',35,9,null,$b$Ta trong nây mâu mra geh yau mŭr ôh, mâu lĕ geh du mlâm mpa bri mra hăn ta nây; bu mâu mra saơ khân păng ta nây ôh, ƀiă lah phung Brah Ndu tâm chuai jêh mra hăn ta nây.$b$,false),
('bunong-vn','ISA',35,10,null,$b$Phung Yêhôva tâm chuai jêh mra sĭt, jêh ri văch ta ƀon Siôn ma nau mprơ, sâm ndô đon hađăch hâk răm n'ho ro. Khân păng mra geh nau maak jêh ri nau hâk răm, nau rngot jêh ri nau vơl mra lôch.$b$,false),
('bunong-vn','ISA',36,1,null,$b$Năm tal jât ma puăn hađăch Senakêrip chiă uănh. Y-Senakêrip hađăch bri Asiri hao văch tâm lơi đah lĕ rngôch ƀon geh pôih tâm bri Yuđa jêh ri nhŭp khân păng$b$,true),
('bunong-vn','ISA',36,2,null,$b$Hađăch bri Asiri prơh kôranh toyh hăn bơh ƀon Lakis ta hađăch Hêsêkia ta ƀon Yêrusalem đah du phung ta han âk. Kôranh toyh nây njưh ta pĭt n'hor ta tu dak rdâng ta trong hăn ta mir ƀư kloh bok.$b$,false),
('bunong-vn','ISA',36,3,null,$b$Y-Êliakim kon bu klâu Y-Hilkia Kôranh ma ngih hađăch hăn tâm mâp đah păng, ndrel ma Y-Sêp na, nơm chih Sămƀŭt, jêh ri Y-Jôa kon bu klâu Y-Asap nơm kâp chih nau tât.$b$,false),
('bunong-vn','ISA',36,4,null,$b$Kôranh toyh nây lah ma khân păng: “Lah hom ma Y-Hêsêkia. Pô aơ hađăch toyh, hađăch bri Asiri lah: Moh jêng nau may rnơm?$b$,true),
('bunong-vn','ISA',36,5,null,$b$May mĭn bu dơi tâm lơh knŏng ma rplay ngơi lĕ? Ma mbu may mra rnơm kŏ tât may tâm rdâng đah gâp?$b$,false),
('bunong-vn','ISA',36,6,null,$b$Aơ, may rnơm ma mâng rpho deh nây, nâm bu ntĭt bri Êjipt. Tơ lah du huê rnơm ma păng, păng mra ntâp ti nơm nây. Tâm ban nây lĕ Pharaôn hađăch bri Êjipt jêng ma lĕ rngôch phung rnơm ma păng.$b$,false),
('bunong-vn','ISA',36,7,null,$b$Ƀiă lah tơ lah may lah ma gâp: “Hên rnơm ma Yêhôva Brah Ndu hên.” Mâu di hĕ ntŭk prêh păng jêh ri nơng păng yơh Y-Hêsêkia sŏk lơi jêh, lah ma phung Yuđa jêh ri ma ƀon Yêrusalem. “Khân may mra mbah yơk ta năp nơng aơ?”$b$,false),
('bunong-vn','ISA',36,8,null,$b$“Pô ri aƀaơ aơ, ăn may ƀư nau tâm rnglăp đah kôranh gâp hađăch bri Asiri. Gâp mra ăn ma may bar rbăn mlâm seh tơ lah may dơi geh bunuyh ncho khân păng.$b$,true),
('bunong-vn','ISA',36,9,null,$b$Phâm may dơi ăn rŭch du huê kôranh ta han jê̆ lơn tâm phung oh mon kôranh gâp, nđâp tơ lah may rnơm ma bri Êjipt gay geh ndeh seh jêh ri phung ncho seh?$b$,false),
('bunong-vn','ISA',36,10,null,$b$Rmeh ma nây mâu geh Yêhôva hĕ gâp hao văch ƀư ma bri aơ, gay ƀư rai păng? Yêhôva nơm lah ma gâp, hao ƀư hom ma bri aơ jêh ri ƀư rai lơi păng.”$b$,false),
('bunong-vn','ISA',36,11,null,$b$Jêh ri Y-Êliakim, Y-Sêpna, jêh ri Y-Jôa lah ma kôranh toyh. “Dăn ma may ngơi ma phung oh mon may tâm nau ngơi Aram, yor lah hên gĭt rbăng nau nây; lơi ngơi ôh ma hên nau ngơi phung Yuđa ta tôr phung ƀon lan gŭ ta klơ pêr.”$b$,true),
('bunong-vn','ISA',36,12,null,$b$Ƀiă lah kôranh toyh lah: “Di lĕ kôranh gâp mprơh gâp hăn knŏng ma kôranh khân may jêh ri ma khân may ăn lah nau aơ, jêh ri mâu di ôh ma phung bu klâu gŭ ta klơ pêr, phung mra sa ek khân păng nơm jêh ri nhêt dak chrach cho khân păng nơm ndrel ma khân may?”$b$,false),
('bunong-vn','ISA',36,13,null,$b$Jêh ri kôranh toyh nây gŭ râng jêh ri nter ma bâr huy tâm nau ngơi Yuđa. “Gŭ iăt hom nau hađăch toyh, hađăch bri Asiri ngơi:$b$,true),
('bunong-vn','ISA',36,14,null,$b$Pô aơ hađăch lah”, Lơi ăn Y-Hêsêkia ndơm khân may ôh, yor lah păng mâu dơi tâm rklaih khân may ôh.$b$,false),
('bunong-vn','ISA',36,15,null,$b$Lơi ăn ôh Y-Hêsêkia ăn khân may rnơm ma Yêhôva dôl lah, “Yêhôva mra tâm rklaih he na nê̆, jêh ri bu mâu mra jao ƀon aơ tâm ti hađăch bri Asiri ôh.”$b$,false),
('bunong-vn','ISA',36,16,null,$b$Lơi ta iăt Y-Hêsêkia ôh, yor lah pô aơ nau hađăch bri Asiri lah: Ƀư nau đăp mpăn đah gâp, jêh ri ăn may văch ta gâp; jêh ri ăp nơm khân may mra sa play bơh tơm play kriăk ƀâu, jêh ri play rvi păng nơm, jêh ri ăp nơm khân may mra nhêt dak ntu păng nơm,$b$,true),
('bunong-vn','ISA',36,17,null,$b$Kŏ gâp văch jêh ri sŏk njŭn khân may ta bri tâm ban ma bri khân may nơm, bri geh ba jêh ri dak play kriăk ƀâu, bri geh ndơ sông sa jêh ri đang play Kriăk ƀâu.$b$,false),
('bunong-vn','ISA',36,18,null,$b$Njrăng hom, klach lah Y-Hêsêkia ndơm khân may jêh ri lah: “Yêhôva mra tâm rklaih he.” Geh lĕ du huê brah phung ndŭl mpôl êng mâp tâm rklaih bri păng bơh ti hađăch Asiri?$b$,false),
('bunong-vn','ISA',36,19,null,$b$Mbah ntŭk phung brah ƀon Hamat jêh ri ƀon Arpat? Mbah ntŭk phung brah ƀon Sêpharvam? Khân păng hŏ mâp tâm rklaih jêh lĕ bri Samari bơh ti gâp?$b$,false),
('bunong-vn','ISA',36,20,null,$b$Mbu nâm tâm lĕ rngôch brah phung bri aơ mâp tâm rklaih jêh bri khân păng bơh ti gâp? Pô ri mâm Yêhôva dơi tâm rklaih ƀon Yêrusalem bơh ti gâp?”$b$,false),
('bunong-vn','ISA',36,21,null,$b$Ƀiă lah khân păng gŭ rklăk, jêh ri mâu plơ̆ lah ma păng du play ngơi ôh, yor lah hađăch ntăm jêh. “Lơi hôm plơ̆ lah ma păng ôh!$b$,true),
('bunong-vn','ISA',36,22,null,$b$Jêh ri Y-Êliakim Kon bu klâu Y-Hilkia kôranh ngih hađăch. Y-Sêpna nơm chih sămƀŭt, jêh ri Y-Jôa kon bu klâu Y-Asap nơm kâp chih nau tât, hăn ta Y-Hêsêkia, soh bok ao khân păng nkhêk jêh, jêh ri mbơh ma păng nau kôranh toyh nây ngơi.$b$,false),
('bunong-vn','ISA',37,1,null,$b$Tơ lah hađăch Hêsêkia tăng nau nây, păng nkhêk bok ao păng, soh ƀau jêh ri lăp tâm ngih Yêhôva.$b$,true),
('bunong-vn','ISA',37,2,null,$b$Păng mprơh Y-Êliakim kôranh ngih hađăch. Y-Sêpna, nơm chih sămƀŭt, jêh ri phung kôranh ƀư brah ranh lơn soh ƀau nau ma kôranh nơm mbơh lor Y-Êsai kon bu klâu Y-Amôt.$b$,false),
('bunong-vn','ISA',37,3,null,$b$Khân păng lah ma Y-Êsai: “Pô aơ Y-Hêsêkia lah, ‘Nar aơ jêng nar rŭng răng nau nduyh, jêh ri bêk, tâm ban ma tât jêh mông deh ma kon ƀiă lah mâu geh nau ktang ăn tât deh ôh.$b$,false),
('bunong-vn','ISA',37,4,null,$b$Klăp lah Yêhôva Brah Ndu khân may tăng jêh nau kôranh toyh nây ngơi, nơm hađăch bri Asiri kôranh păng prơh hăn văch ăn mưch ma Brah Ndu rêh, jêh ri mra nduyh nau ngơi amoh Yêhôva Brah Ndu may tăng jêh. Yor nây ăn may mbơh sơm, yor kô̆ phung bunuyh hôm.”$b$,false),
('bunong-vn','ISA',37,5,null,$b$Tơ lah phung oh mon hađăch Hêsêkia tât ta Y-Êsai.$b$,true),
('bunong-vn','ISA',37,6,null,$b$Y-Êsai lah ma khân păng. “Lah hom ma kôranh khân may. Pô aơ Yêhôva lah: Lơi klach ôh ma nau ngơi may tăng nây. Nau phung oh mon hađăch bri Asiri suai rak ma gâp.$b$,false),
('bunong-vn','ISA',37,7,null,$b$Aơ, gâp mra dơm brah tâm păng, pô ri păng mra tăng du nau, jêh ri mra plơ̆ sĭt ta bri păng nơm, jêh ri gâp mra ăn păng khĭt ma đao tâm bri păng nơm.”$b$,false),
('bunong-vn','ISA',37,8,null,$b$Tơ lah păng tăng lư hađăch du jêh bơh ƀon Lakis, pô ri kôranh toyh nây plơ̆ sĭt jêh ri saơ hađăch bri Asiri tâm lơh đah ƀon Lipna.$b$,true),
('bunong-vn','ISA',37,9,null,$b$Hađăch tăng nau bu mbơh nau Y-Tirhaka hađăch bri Êthiôpi ƀư. “Păng jŭr văch ŭch tâm lơh đah hađăch tăng nau nây, păng prơh phung hăn mbơh ma Y-Hêsêkia, lah:$b$,false),
('bunong-vn','ISA',37,10,null,$b$“Pô aơ khân păng mra ngơi ma Y-Hêsêkia hađăch bri Yuđa: ‘Lơi ăn ôh Brah Ndu may, nơm may rnơm, ndơm may ton.’ Gâp mâu mra jao ôh ƀon Yêrusalem tâm ti hađăch bri Asiri$b$,false),
('bunong-vn','ISA',37,11,null,$b$Aơ, may tăng jêh moh nau phung hađăch bri Asiri ƀư jêh ma lĕ rngôch bri, ƀư rai jêh lĕ khân păng. Jêh ri may mra klaih lĕ?$b$,false),
('bunong-vn','ISA',37,12,null,$b$Brah phung ndŭl mpôl bunuyh mbơ̆ gâp ƀư rai jêh mâp tâm rklaih jêh khân păng, bri Gôsan, ƀon Haran, ƀon Rêsep, jêh ri phung kon Eđen gŭ ta ƀon Têlasar?$b$,false),
('bunong-vn','ISA',37,13,null,$b$Mbah ntŭk hađăch ƀon Hamat, hađăch ƀon Arpat, hađăch ƀon Sepharvam, hađăch ƀon Hêna, jêh ri hađăch ƀon Iva?”$b$,false),
('bunong-vn','ISA',37,14,null,$b$Y-Hêsêkia sŏk dơn sămƀŭt nây bơh ti phung mbơh jêh ri uănh păng. Jêh ri Y-Hêsêkia hăn hao ta ngih Yêhôva, pơk tâm mpơl păng ta năp Yêhôva.$b$,true),
('bunong-vn','ISA',37,15,null,$b$Y-Hêsêkia mbơh sơm ma Yêhôva, lah:$b$,false),
('bunong-vn','ISA',37,16,null,$b$“Ơ Yêhôva ma phung ta han, Brah Ndu Israel, nơm gŭ ta klơ phung Chêrubim, knŏng êng may yơh jêng Brah Ndu ma lĕ rngôch ƀon bri hađăch ta neh ntu; may yơh nơm rhăk trôk jêh ri neh ntu.$b$,false),
('bunong-vn','ISA',37,17,null,$b$Ơ Yêhôva, rkêng hom tôr may, jêh ri iăt! Ơ Yêhôva lin hom măt jêh ri uănh! Iăt hom lĕ rngôch nau Y-Sênakêrip ngơi njuăl jêh gay mưch ma Brah Ndu rêh.$b$,false),
('bunong-vn','ISA',37,18,null,$b$Na nê̆, Ơ Yêhôva phung hađăch bri Asiri ƀư rai jêh lĕ rngôch phung ndŭl mpôl bunuyh nây jêh ri bri neh khân păng,$b$,false),
('bunong-vn','ISA',37,19,null,$b$jêh ri klŭp jêh rup brah khân păng tâm ŭnh, yor lah brah nây mâu jêng brah ngăn ôh, knŏng ti kon bunuyh ƀư ma si jêh ri ma lŭ. Yor nây phung Asiri ƀư rai jêh brah nây.$b$,false),
('bunong-vn','ISA',37,20,null,$b$Pô ri aƀaơ aơ, Ơ Yêhôva Brah Ndu hên, tâm rklaih hom hên, bơh ti păng, gay ma lĕ rngôch ƀon bri hađăch ta neh ntu dơi gĭt knŏng êng may yơh. Ơ Yêhôva, jêng Brah Ndu.”$b$,false),
('bunong-vn','ISA',37,21,null,$b$Jêh ri Y-Êsai, kon bu klâu Y-Amôt prơh bu hăn ta Y-Hêsêkia, lah: “Pô aơ Yêhôva Brah Ndu Israel lah: “Yor lah may mbơh sơm jêh ma gâp yor Y-Senakêrip hađăch bri Asiri,$b$,true),
('bunong-vn','ISA',37,22,null,$b$aơ, nau Yêhôva ngơi jêh di ma păng: ‘Bu ur druh ƀon Siôn tâm rmot ma may, păng gơm mưch ma may; kon bu ur ƀon Yêrusalem rteh bôk ma may dôl may du.$b$,false),
('bunong-vn','ISA',37,23,null,$b$Ma mbu nâm may mưch jêh ri suai rak? Ma mbu nâm may tâm rdâng ma bâr nter jêh ri uănh ma nau sưr? Ma Nơm Kloh Ueh phung Israel yơh!$b$,false),
('bunong-vn','ISA',37,24,null,$b$Đah phung oh mon may, may mưch jêh ma Kôranh Brah, jêh ri may lah jêh: ‘Ma ndeh seh gâp âk lơn, gâp hao jêh ta klơ kô yôk ta ntŭk ngai lơn tâm bri Liban; gâp kăl jêh tơm si sêdar păng prêh lơn, si n'ho păng ueh lơn; jêh ri gâp tât jêh ta klơ yôk, tâm krŏng păng mbâl lơn.$b$,false),
('bunong-vn','ISA',37,25,null,$b$Gâp kuyh jêh ntu dak jêh ri nhêt jêh dak. Ma mpang jâng gâp, gâp ƀư suăt jêh lĕ rngôch dak n'hor bri Êjipt!$b$,false),
('bunong-vn','ISA',37,26,null,$b$“May mâu tăng hĕ gâp hŏ ƀư jêh nau nây jŏ jêh. Bơh rnôk kăl e gâp nkra dăp nau kan jêh ri gâp ƀư ăn tât nau nây, gay ma may dơi ƀư rai lơi âk ƀon toyh nâp, ăn may bun ndŏk.$b$,true),
('bunong-vn','ISA',37,27,null,$b$Yor nây phung ƀon lan khân păng mâu hôm geh nau ktang ôh, rdja nuih n'hâm jêh ri bêk. Khân păng jêng jêh tâm ban ma trau n'ha tâm mir jêh ri gơ̆ nse, tâm ban ma gơ̆ hon ta klơ bôk pho ngih, kro hêng lor ma păng hung.$b$,true),
('bunong-vn','ISA',37,28,null,$b$Gâp gĭt tơ lah may gŭ, tơ lah may luh jêh ri tơ lah may lăp, jêh ri nau may ji nuih ma gâp.$b$,false),
('bunong-vn','ISA',37,29,null,$b$Yor lah may ji nuih jêh ma gâp, jêh ri gâp tăng jêh nau may ngơi sưr, gâp mra klĕ may ta trôm muh jêh ri chê̆ loih n'gla gâp tâm trôm mbung may, jêh ri gâp mra mplơ̆ may ta trong may văch jêh.$b$,false),
('bunong-vn','ISA',37,30,null,$b$“Aơ mra jêng nau mbên ma may, Ơ Y-Hêsêkia: “Năm aơ may mra sa play hon êng păng nơm, jêh ri năm tal bar ndơ hon êng păng nơm tâm ban lĕ. Năm tal pe ăn may rek, tăm tơm play kriăk ƀâu jêh ri sa play păng.$b$,true),
('bunong-vn','ISA',37,31,null,$b$Phung kô̆ hôm bơh ngih Yuđa mra đŏng njŭr reh tâm dâng jêh ri play ta klơ.$b$,false),
('bunong-vn','ISA',37,32,null,$b$Yor lah du kô̆ phung bunuyh hôm mra luh bơh ƀon Yêrusalem, jêh ri du phung klaih jêh mra luh bơh yôk Siôn. Nau Yêhôva ma phung ta han duh nđơr mra ƀư nau aơ.$b$,false),
('bunong-vn','ISA',37,33,null,$b$“Yor nây Yêhôva lah pô aơ di ma hađăch bri Asiri: “Păng mâu mra lăp ôh tâm ƀon toyh aơ, mâu lah pănh du mlâm hăr ta nây, mâu lah văch ta năp păng ma khêl, mâu lah n'hao mbon nchueng ƀư ma păng.$b$,true),
('bunong-vn','ISA',37,34,null,$b$Păng mra plơ̆ sĭt ta trong păng văch jêh, jêh ri păng mâu mra lăp ôh tâm ƀon toyh aơ? Yêhôva lah:$b$,false),
('bunong-vn','ISA',37,35,null,$b$Yor lah gâp mra n'gang ƀon toyh aơ gay tâm rklaih păng yor gâp nơm jêh ri yor oh mon gâp Y-Đavit.”$b$,false),
('bunong-vn','ISA',37,36,null,$b$Tông mpăr ueh Yêhôva hăn jêh ri nkhĭt tâm nkual phung Asiri njưh du rsen pham rmưn prăm rbăn bunuyh. Ri tơ lah bu dâk ơm ôi, aơ lĕ rngôch phung nây jêng phan jêh.$b$,true),
('bunong-vn','ISA',37,37,null,$b$Pô ri Y-Sena kêrip hađăch bri Asiri hăn sĭt jêh ri gŭ ta ƀon Ninivơ.$b$,false),
('bunong-vn','ISA',37,38,null,$b$Dôl păng gŭ mbah yơk tâm ngih Nirok brah păng, Y-Adramêlek jêh ri Y-Saresar phung kon bu klâu păng nkhĭt păng ma đao, jêh ri hăn du ta bri Ararat. Y-Esar-Hadôn kon bu klâu păng chiă uănh ntrok păng.$b$,false),
('bunong-vn','ISA',38,1,null,$b$Rnôk nây Y-Hêsêkia ji dăch khĭt. Kôranh nơm-mbơh lor Y-Êsai kon bu klâu Y-Amôt hăn ta păng jêh ri lah: “Pô aơ Yêhôva lah nkra kan tâm ngih may, yor lah may mra khĭt, mâu hôm gŭ rêh ôh.”$b$,true),
('bunong-vn','ISA',38,2,null,$b$Jêh ri Y-Hêsêkia n'gĭl măt păng mpeh ta mpir, jêh ri mbơh sơm ma Yêhôva.$b$,true),
('bunong-vn','ISA',38,3,null,$b$“Ơ Yêhôva, gâp vơl ma may, ăn may kah gĭt aƀaơ aơ nau gâp gŭ ngao krau sach jêh ta năp may ma nau răp jăp jêh ri ma lĕ nuih n'hâm jêh ri ƀư jêh nau ueh ta năp măt may.” Y-Hêsêkia nhĭm rngot ngăn.$b$,false),
('bunong-vn','ISA',38,4,null,$b$Jêh ri Yêhôva ngơi đah Y-Êsai:$b$,true),
('bunong-vn','ISA',38,5,null,$b$“Hăn hom lah ma Y-Hêsêkia, pô aơ Yêhôva Brah Ndu Y-Đavit che may lah: Gâp tăng jêh nau may mbơh, gâp saơ jêh dak măt may; aơ, gâp mra ntop tay jât ma prăm năm ma nar may gŭ rêh.$b$,false),
('bunong-vn','ISA',38,6,null,$b$Gâp mra tâm rklaih may jêh ri ƀon toyh aơ bơh ti hađăch bri Asiri, jêh ri gâp mra n'gang ƀon aơ.$b$,false),
('bunong-vn','ISA',38,7,null,$b$Aơ mra jêng nau mbên ma may bơh Yêhôva ma nau Yêhôva mra ăn tât nau păng ton nây:$b$,true),
('bunong-vn','ISA',38,8,null,$b$‘Aơ, gâp mra ăn gui n'hâm nar tŭp rŭch sĭt jât vang pa kơi ta mông Y-Ahas neh gui.’ ” Pô ri nar rŭch jât vang ta mông veh gui bơh ntŭk păng hăn jêh.$b$,false),
('bunong-vn','ISA',38,9,null,$b$Nau Y-Hêsêkia hađăch bri Yuđa chih jêh păng bah nau ji:$b$,true),
('bunong-vn','ISA',38,10,null,$b$Gâp lah; “Ta nklang rnôk gâp gŭ rêh, gâp mra du hăn ta mpông pêr Ƀon Phung khĭt, gay roh năm hôm ma gâp?”$b$,false),
('bunong-vn','ISA',38,11,null,$b$Gâp lah: “Gâp mâu mra saơ Yêhôva ôh, ta neh ntu phung rêh. Gâp mâu mra saơ bunuyh ôh mâu lah gŭ ndrel đah phung bunuyh ta neh ntu.$b$,false),
('bunong-vn','ISA',38,12,null,$b$Bu ƀư rlâm lơi ngih gâp gŭ, jêh ri rdu tă bơh gâp tâm ban ma du rplay ngih bok rmăk biăp gâp klôt lơi nau rêh gâp tâm ban ma nơm tanh; păng koh lơi gâp tă bơh ndơ dŏng tanh. Ntơm bơh nar tât măng may ƀư roh gâp.$b$,false),
('bunong-vn','ISA',38,13,null,$b$Gâp srôih kâp tât ôi, păng nchah lơi lĕ nting gâp tâm ban ma du mlâm yau mŭr. Mông nar tât ta măng may ƀư roh gâp.$b$,true),
('bunong-vn','ISA',38,14,null,$b$Gâp nter tâm ban ma sĭm re dak mâu lah sĭm kuk kreo, gâp nđêng tâm ban ma plŭk. Măt gâp rgănh jêh n'gơr klơ, Ơ Kôranh Brah, gâp rŭng răng dăn may kơl gâp!$b$,true),
('bunong-vn','ISA',38,15,null,$b$Ƀiă lah moh gâp dơi lah? Yor lah păng ngơi jêh đah gâp jêh ri păng nơm yơh ƀư nau aơ. Gâp mra nsong mblêng lĕ năm gâp gŭ rêh yor nau rngot huêng gâp.$b$,true),
('bunong-vn','ISA',38,16,null,$b$Ơ Kôranh Brah, ma nau aơ phung bunuyh gŭ rêh; tâm lĕ nau aơ lĕ huêng gâp gŭ rêh. Pô ri ƀư bah hom gâp jêh ri ăn gâp gŭ rêh!$b$,false),
('bunong-vn','ISA',38,17,null,$b$Aơ, gâp geh jêh nau rngot gay ăn tât nau ueh ma gâp; may n'gang nau rêh gâp bơh ntu kuyh ƀư rai, yor lah may klŭp jêh lĕ rngôch nau tih gâp pa kơi gâp.$b$,true),
('bunong-vn','ISA',38,18,null,$b$Yor lah Ƀon Phung Khĭt mâu dơi tâm rnê ma may ôh, nau khĭt mâu dơi mât ton ma may ôh. Phung trŭnh hăn jêh ta ntu jru mâu dơi kâp gân ôh ma nau răp jăp may.$b$,true),
('bunong-vn','ISA',38,19,null,$b$Nơm rêh, nơm gŭ rêh yơh, mra tâm rnê ma may, tâm ban ma gâp ƀư nar aơ. Phung mbơ̆ nkoch bri ma phung kon khân păng, ăn gĭt năl nau may răp jăp.$b$,true),
('bunong-vn','ISA',38,20,null,$b$Yêhôva mra tâm rklaih gâp, jêh ri he mra mprơ ndrel ma gong rêng, lĕ rngôch nar he gŭ rêh, tâm ngih brah Yêhôva.$b$,false),
('bunong-vn','ISA',38,21,null,$b$Y-Êsai lah: “Ăn bu djôt play rvi jêh ri iang ta ntŭk eh gay ma păng dơi bah.”$b$,true),
('bunong-vn','ISA',38,22,null,$b$“Moh jêng nau tâm mbên ma gâp mra hăn hao ta ngih brah Yêhôva?”$b$,true),
('bunong-vn','ISA',39,1,null,$b$Rnôk nây Y-Merôdak-Baladan kon bu klâu Y-Baladan hađăch Babilôn njuăl prơh phung oh mon ktang hăn njŭn sămƀŭt jêh ri ndơ nhhơr ma Y-Hêsêkia, yor lah păng tăng lư păng ji jêh ri bah jêh.$b$,true),
('bunong-vn','ISA',39,2,null,$b$Y-Hêsêkia rom khân păng ma nau răm, jêh ri ntĭm ma khân păng ngih păng prăp ndơ khlay, prăk, mah, dak si ƀâu kah jêh ri dak play ôlivơ khlay, lĕ ngih prăp ndơ tâm lơh, jêh ri lĕ rngôch ndơ tâm ngih drăp khlay. Mâu geh ôh du ntil ndơ Y-Hêsêkia mâu geh mpơl ma khân păng tâm ngih păng jêh ri tâm lĕ ƀon bri hađăch păng.$b$,true),
('bunong-vn','ISA',39,3,null,$b$Jêh ri kôranh nơm mbơh lor Y-Êsai hăn tă hađăch Hêsêkia jêh ri lah ma păng, “Moh phung bunuyh nây lah? Jêh ri mbah tă khân păng văch ta may?” Y-Hêsêkia lah: “Khân păng văch ta gâp ta bơh bri ngai, bơh Babilôn.”$b$,true),
('bunong-vn','ISA',39,4,null,$b$Y-Êsai lah: “Moh ndơ khân păng saơ jêh tâm ngih may?” Y-Hêsêkia plơ̆ lah: “Khân păng saơ jêh lĕ rngôch ndơ tâm ngih gâp, mâu geh du ntil ndơ tâm ngih drăp khlay gâp, gâp mâu mpơl ma khân păng ôh.”$b$,false),
('bunong-vn','ISA',39,5,null,$b$Jêh ri Y-Êsai lah ma Y-Hêsêkia. “Iăt hom nau Yêhôva ma phung ta han ngơi$b$,false),
('bunong-vn','ISA',39,6,null,$b$Aơ nar mra tât tơ lah bu mra sŏk njŭn leo ta ƀon Babilôn lĕ rngôch ndơ tâm ngih may jêh ri lĕ rngôch ndơ tâm ngih che may bun prăp jêh tât ta nar aơ; mâu mra hôm du ntil ndơ ôh, Yêhôva lah:$b$,false),
('bunong-vn','ISA',39,7,null,$b$Jêh ri bu mra sŏk leo ƀa ƀă phung kon sau bu mra deh ma păng khân păng mra jêng phung oh mon bu char tâm ngih hađăch Babilôn.”$b$,false),
('bunong-vn','ISA',39,8,null,$b$Y-Hêsêkia lah ma Y-Êsai: “Nau Yêhôva ngơi may mbơh jêng ueh.” Yor lah păng mĭn, “Mra geh nau đăp mpăn jêh ri nau rnơm dôl rnôk gâp gŭ rêh.”$b$,true),
('bunong-vn','ISA',40,1,null,$b$Brah Ndu khân may lah: Tâm bonh hom, tâm bonh hom phung ƀon lan gâp.$b$,true),
('bunong-vn','ISA',40,2,null,$b$Ngơi hom ma nau rdơ̆ ma ƀon Yêrusalem jêh ri nter mbơh ma păng nau păng jêng dĭk lôch jêh, nau kue păng yô̆ ăn jêh, nau păng sŏk dơn jêh bơh ti Yêhôva, nau tâm rmal bar tơ̆ âk lơn ma lĕ rngôch nau tih păng.$b$,false),
('bunong-vn','ISA',40,3,null,$b$Geh bâr nter lah: “Nkra hom trong ma Yêhôva tâm bri, ƀư ăn sŏng du ntŭk trong toyh ma Brah Ndu he tâm ndrêch rdah.$b$,true),
('bunong-vn','ISA',40,4,null,$b$Lĕ rngôch rlŭng mra hao ta klơ, lĕ rngôch yôk jêh ri mbon mra rlâm tâm dâng, ntŭk rklĭng (sop) mra lâng, jêh ri ntŭk ntu lŭng mra jêng tâm ban.$b$,false),
('bunong-vn','ISA',40,5,null,$b$Nau chrêk rmah Yêhôva mra tâm mpơl, jêh ri rngôch bunuyh ndrel n'grŭp mra saơ nau chrêk rmah nây, yor lah trôm mbung Yêhôva ngơi jêh nau nây.”$b$,false),
('bunong-vn','ISA',40,6,null,$b$Geh bâr lah: “Nter hom!” Jêh ri gâp lah: “Moh nau gâp mra nter?” “Lĕ rngôch bunuyh jêng tâm ban ma gơ̆ nse, jêh ri lĕ rngôch nau ueh păng jêng tâm ban ma kao tâm mir.$b$,true),
('bunong-vn','ISA',40,7,null,$b$Gơ̆ kro, kao klêu, tơ lah n'hâm Yêhôva khôm ta klơ păng. Nanê̆ phung ƀon lan jêng tâm ban ma gơ̆ nse.$b$,false),
('bunong-vn','ISA',40,8,null,$b$Gơ̆ kro, kao klêu, ƀiă lah nau Brah Ndu he ngơi mra hôm ƀa ƀơ n'ho ro.”$b$,false),
('bunong-vn','ISA',40,9,null,$b$Hao hom ta klơ yôk prêh, Ơ ƀon Siôn, ƀon mbơh nau mhe mhan ueh. Nter troh hom ma nau ktang, Ơ Yêrusalem, ƀon mbơh nau mhe mhan ueh. Nter hom may, lơi klach ôh; lah hom ma lĕ rngôch ƀon bri Yuđa, “Aơ, Brah Ndu khân may.”$b$,true),
('bunong-vn','ISA',40,10,null,$b$Aơ, Kôranh Brah Yêhôva văch ma nau brah, jêh ri păng mra chiă uănh ma ti păng. Aơ, păng njŭn jêh ri mra ăn nau nkhôm.$b$,false),
('bunong-vn','ISA',40,11,null,$b$Păng mra sĭm lĕ rngôch bi ăp păng tâm ƀon ma du huê rmăk biăp; păng mra ra u kon biăp tâm ti păng, chông ut tâm ntang ntơh păng, jêh ri păng mra njŭn ma nau groi biăp me ăn pu kon.$b$,false),
('bunong-vn','ISA',40,12,null,$b$Mbu nâm veh jêh lĕ rngôch dak tâm ti păng, veh trôk ma mpang ti, bun ndruyh neh ma du ndơ veh, kơp jêh rnoh jâk yôk ma njing jêh ri ƀư tâm sŏng gay njing gôl yôk?$b$,true),
('bunong-vn','ISA',40,13,null,$b$Mbu nâm gai Brah Huêng Ueh Yêhôva mâu lah jêng nơm nchră păng, sâm nti an păng?$b$,false),
('bunong-vn','ISA',40,14,null,$b$Đah mbu nâm păng tâm nchră gay geh nau ang, mbu nti păng trong nau sŏng? Mbu sâm nti păng nau blau mĭn, jêh ri ntĭm ma păng trong gĭt rbăng?$b$,false),
('bunong-vn','ISA',40,15,null,$b$Aơ, phung ndŭl mpôl bunuyh jêng tâm ban ma du ntruh dak tâm thŭng; bu kơp khân păng tâm ban ma ndruyh neh ta klơ njing. Aơ păng yơt chông kô dak mƀŭt tâm ban ma ndơ jê̆ ngăn.$b$,false),
('bunong-vn','ISA',40,16,null,$b$Bri Liban mâu tŏng ôh long ŭnh sa, jêh ri lĕ rngôch mpô mpa păng mâu lĕ tŏng jêng mpa nhhơr gŭch.$b$,false),
('bunong-vn','ISA',40,17,null,$b$Lĕ rngôch ndŭl mpôl bunuyh jêng tâm ban ma dơm dam ta năp păng, păng kơp khân ô băl jêng dơm dam jêh ri hŏng.$b$,false),
('bunong-vn','ISA',40,18,null,$b$Đah mbu may ŭch tâm ban ma Brah Ndu, mâu lah moh ndơ may dơi tâm ban ma păng?$b$,true),
('bunong-vn','ISA',40,19,null,$b$Bi rup brah, du huê bunuyh tŏ ƀư păng jêh ri nơm chiăr mah mblum păng ma mah jêh ri tŏ ƀư rse rvăk rhên ma prăk ma păng.$b$,false),
('bunong-vn','ISA',40,20,null,$b$Nơm o-ach ngăn săch du mlâm tơm si mâu blau ôm ôh; păng joi du huê bunuyh blau mĭn ŭch trah rup brah mâu blau n'gơ ôh.$b$,false),
('bunong-vn','ISA',40,21,null,$b$Khân may mâm mâu gĭt? Khân may mâm mâu mâp tăng? Bu mâu mâp mbơh hĕ ma khân may nau nây ntơm bơh kăl? Khân may mâu mâp gĭt rbăng hĕ bơh rnôk rdâk mbon neh ntu?$b$,true),
('bunong-vn','ISA',40,22,null,$b$Păng yơh gŭ ta klơ rvang neh ntu, jêh ri phung gŭ tâm neh ntu jêng tâm ban ma krah. Păng pơk trôk tâm ban ma du blah bok; Păng pơk glah tâm ban ma du blah ngih bok ŭch gŭ.$b$,false),
('bunong-vn','ISA',40,23,null,$b$Păng yơh ăn phung kôranh jêng dơn dam, jêh ri ăn phung chiă uănh neh ntu mâu jêng khlay ôh.$b$,false),
('bunong-vn','ISA',40,24,null,$b$Mhe bu tăm, mhe bu srih, mhe tơm khân păng ntrŭnh reh tâm neh, păng khôm ta khân păng jêh ri khân păng klêu, jêh ri sial phŭt nthông rdu khân păng tâm ban ma rhe.$b$,false),
('bunong-vn','ISA',40,25,null,$b$Pô nây Nơm Kloh Ueh lah: “Đah mbu khân may tâm rđĭl ăn tâm ban ma gâp, gay ăn gâp tâm ban ma păng?$b$,true),
('bunong-vn','ISA',40,26,null,$b$N'gơr măt khân may klơ jêh ri uănh hom: Mbu nâm rhăk njêng ndơ nây? Păng ngluh phung ta han nây tĭng nâm ndah geh khân păng; Păng ntơ lĕ rngôch phung nây ma amoh khân păng. Ma nau brah păng toyh jêh ri yor lah păng jêng ktang tâm nau brah, mâu pưt du ntil ôh.$b$,false),
('bunong-vn','ISA',40,27,null,$b$Ơ phung Yakôb, mâm ƀư khân may lah, jêh ri ơ phung Israel, mâm ƀư khân may ngơi. “Trong gâp ndâp ma Yêhôva, jêh ri Brah Ndu gâp mâu chrê ôh ma nau khư ma gâp?”$b$,true),
('bunong-vn','ISA',40,28,null,$b$May mâu gĭt hĕ? May mâu tăng hĕ? Yêhôva jêng Brah Ndu gŭ n'ho ro. Nơm rhăk njêng jêh bôl dŭt neh ntu. Păng mâu hŏt ôh, mâu lĕ rgănh, bu mâu dơi sek uănh ôh lĕ nau păng gĭt mĭn,$b$,false),
('bunong-vn','ISA',40,29,null,$b$păng ăn nau gơih nđơr ma phung huăr jêh, jêh ri păng n'hao nau brah ma mbu nâm mâu geh nau$b$,false),
('bunong-vn','ISA',40,30,null,$b$Nđâp phung druh ndăm mra huăr jêh ri rgănh, jêh ri phung bu klâu ndăm mra prah;$b$,false),
('bunong-vn','ISA',40,31,null,$b$ƀiă lah mbu phung gŭ kâp Yêhôva, mra ƀư mhe nau ktang khân păng, khân păng mra mpăr hao tâm ban ma klang, khân păng mra nchuăt jêh ri mâu rgănh ôh, khân păng mra hăn jêh ri mâu huăr ôh.$b$,false),
('bunong-vn','ISA',41,1,null,$b$Ơ lĕ rngôch kô dak mƀŭt, gŭ rklăk hom ta năp gâp jêh ri kâp iăt! Ăn phung ƀon lan ƀư mhe hom nau ktang khân păng. Ăn khân păng văch dăch jêh ri ăn khân păng ngơi, ăn he hăn dăch ndrel n'grŭp gay ma phat dôih.$b$,true),
('bunong-vn','ISA',41,2,null,$b$“Mbu nâm ngluh jêh du huê tă pa lơ, nơm geh nau dơi lĕ ntŭk păng hăn? Bu jao jêh ma păng mpôl băl bunuyh, pô ri păng jot phung hađăch. Păng ăn bu jêng tâm ban ma ndruyh neh ma đao păng, tâm ban ma rhe sial khôm$b$,false),
('bunong-vn','ISA',41,3,null,$b$Ta trong jâng păng mâu mâp hăn ôh, păng tĭng jêh ri rlet khân păng mâu geh nau mhĭk ôh.$b$,false),
('bunong-vn','ISA',41,4,null,$b$Mbu nâm ƀư jêh ri ƀư hom nau nây, kuăl jêh rnôk bơh ntơm sa ơm? Gâp yơh, Yêhôva, nơm lor lơn, jêh ri nơm gŭ tât nglĕ dŭt, gâp yơh nơm nây.”$b$,false),
('bunong-vn','ISA',41,5,null,$b$Lĕ rngôch bri kơh dak mƀŭt saơ jêh ri klach, bôl neh ntu n'găr sâr; khân păng văch dăch.$b$,false),
('bunong-vn','ISA',41,6,null,$b$Ăp nơm kơl phung chiau meng păng, jêh ri lah ma oh nâu păng. “N'hao nuih hom.”$b$,false),
('bunong-vn','ISA',41,7,null,$b$Nơm trah meh n'hao hom nuih nơm tŏ mah, nơm chiăr ma kon nâp n'hao nuih nơm ta klơ ăn nâp, lah ma kan han. “Păng jêng ueh jêh”; Bu pâng păng ma loih kađĭn gay lơi ăn n'gơ.$b$,false),
('bunong-vn','ISA',41,8,null,$b$“Ƀiă lah khân may ơ phung Israel, oh mon gâp, phung Yakôb, phung gâp săch jêh, mpôl ntil Y-Abraham mĭt jiăng gâp;$b$,true),
('bunong-vn','ISA',41,9,null,$b$khân may yơh nơm gâp sŏk jêh bơh bôl bri neh, jêh ri kuăl jêh tă bơh kuel păng, jêh ri lah ma khân may, ‘khân may jêng oh mon gâp;’ gâp săch jêh khân may, mâu mƀăr lơi ôh.”$b$,false),
('bunong-vn','ISA',41,10,null,$b$Lơi Klach ôh, yor lah gâp gŭ ndrel ma khân may. Lơi rdja nuih ôh, yor lah gâp jêng Brah Ndu khân may. Gâp mra ƀư ktang khân may, gâp mra kơl khân may. Gâp mra kuăn rdâng khân may ma ti ma nau sŏng gâp.$b$,false),
('bunong-vn','ISA',41,11,null,$b$Aơ, lĕ rngôch phung ji nuih ma khân may bu mra ƀư bêk jêh ri ƀư rŭng. Phung tâm rdâng đah khân may mra jêng dơm dam jêh ri rai yot.$b$,false),
('bunong-vn','ISA',41,12,null,$b$Khân may mra joi phung tâm rdâng đah khân may, ƀiă lah mâu saơ ôh. Phung tâm lơh đah khân may mra jêng dơm dam, mâu khlay ôh.$b$,false),
('bunong-vn','ISA',41,13,null,$b$Yor lah gâp jêng Yêhôva Brah Ndu khân may, nơm kuăn ti ma khân may, lah ma khân may, “Lơi klach ôh, gâp mra kơl khân may.$b$,false),
('bunong-vn','ISA',41,14,null,$b$Lơi klach ôh, Ơ Y-Yakôb, nơm jêng tâm ban ma brăn, jêh ri khân may, Ơ phung Israel! Gâp nơm mra kơl khân may.” Yêhôva lah: Nơm Tâm Chuai khân may, Nơm Kloh Ueh phung Israel.$b$,false),
('bunong-vn','ISA',41,15,null,$b$Aơ, gâp mra ăn khân may jêng du mlâm ndeh mprah ba, mhe, bêng ma sêk mplanh. Khân may mra mprah yôk jêh ri ƀư chah lơi khân păng, jêh ri khân may mra ăn gôl jêng tâm ban ma lâk nse.$b$,true),
('bunong-vn','ISA',41,16,null,$b$Khân may mpruh khân păng jêh ri sial vănh blông mra khôm khân păng, sial phŭt mra nthông rdu khân păng. Ƀiă lah khân may mra maak tâm Yêhôva, khân may mra tâm rnê ma phung Kloh Ueh, phung Israel.$b$,false),
('bunong-vn','ISA',41,17,null,$b$“Phung o ach jêh ri phung pưt ndơ joi dak, ƀiă lah mâu geh ôh; jêh ri mpiăt khân păng sơh yor ji hir. Gâp yơh, Yêhôva, mra plơ̆ lah ma khân păng; gâp yơh, Brah Ndu Phung Israel, mâu mra lơi khân păng ôh.$b$,false),
('bunong-vn','ISA',41,18,null,$b$Gâp mra ăn dak hoch tă bơh yôk hil, jêh ri ntu dak ta nklang rlŭng. Gâp mra ăn bri hŏng jêng dak nglao, jêh ri neh sơh jêng tu dak luh.$b$,false),
('bunong-vn','ISA',41,19,null,$b$Gâp mra dơm tâm bri hŏng tơm si sêdar, tơm si akasi, tơm si mirtơ, jêh ri tơm si ôlivơ. Gâp mra dơm ndrel n'grŭp tâm ndrêch rdah, tơm si Chiprơ, tơm si n'ho, jêh ri tơm si buis,$b$,false),
('bunong-vn','ISA',41,20,null,$b$gay ma phung bunuyh dơi saơ jêh ri gĭt, dơi sek uănh jêh ri gĭt rbăng ndrel n'grŭp ma ti Yêhôva ƀư jêh nau aơ, Nơm Kloh Ueh phung Israel rhăk khân păng.$b$,false),
('bunong-vn','ISA',41,21,null,$b$“Tâm mpơl hom nau khân may” Yêhôva lah: “Tâm mpơl hom nau khân may dơi ƀư nanê̆ ngăn”, hađăch phung Yakôb lah.$b$,true),
('bunong-vn','ISA',41,22,null,$b$Ăn khân păng tâm mpơl nau nây, jêh ri mbơh ma hên moh nau mra tât. Nkoch bri hom nau geh kăl e, moh khân păng jêng, gay ma hên dơi sek uănh khân păng, jêh ri gĭt rbăng nau nglĕ dŭt khân păng. Mâu lah mbơh ma hên nau mra tât;$b$,false),
('bunong-vn','ISA',41,23,null,$b$mbơh hom ma hên nau mra tât ta kăndơ̆ , gay ma hên dơi gĭt khân may jêng phung brah. Ăn khân may ƀư nau ueh, mâu lah nau mhĭk, gay ma hên rdja nuih n'hâm jêh ri rŭng răng.$b$,false),
('bunong-vn','ISA',41,24,null,$b$Aơ, khân may jêng dơm dam, jêh ri kan khân may mâu khlay ôh. Nơm săch khân may jêng nơm Yêhôva tâm rmot.$b$,true),
('bunong-vn','ISA',41,25,null,$b$“Gâp ngluh jêh du huê tă bơh mpư̆ yôk, jêh ri păng mra ntơm văch, du huê tă bơh ntŭk luh nar, nơm kuăl amoh gâp. Păng mra jot phung kô ranh chiă uănh tâm ban ma ndơ bu buănh, tâm ban ma nơm mon glah jot uk.$b$,true),
('bunong-vn','ISA',41,26,null,$b$Mbu nâm mbơh jêh nau nây bơh ntơm sa ơm gay ma he dơi gĭt, jêh ri bơh rnôk lor gay ma he dơi lah, “Păng jêng di lĕ? Mâu geh nơm mbơh nau nây ôh-mâu geh nơm tâm mpơl ôh, mâu geh nơm tăng nau may ngơi ôh.$b$,false),
('bunong-vn','ISA',41,27,null,$b$Gâp jêng nơm tal lor lơn mbơh jêh nau nây ma ƀon Siôn, jêh ri gâp njuăl hăn ta ƀon Yêrusalem du huê nơm mbơh nau mhe mhan ueh.$b$,false),
('bunong-vn','ISA',41,28,null,$b$Ƀiă lah tơ lah gâp uănh, mâu geh nơm ôh; ta nklang khân păng mâu geh nơm nchră ôh, mâu geh nơm dơi plơ̆ lah tơ lah gâp tâm rmot ma khân păng.$b$,false),
('bunong-vn','ISA',41,29,null,$b$Aơ, lĕ rngôch khân păng jêng phung ndơm, kan khân păng mâu khlay ôh; rup brah khân păng tŏ chiăr jêng sial dơm dam.$b$,false),
('bunong-vn','ISA',42,1,null,$b$Aơ, Oh mon gâp, nơm gâp kuăn rdâng, nơm gâp săch jêh, tâm păng huêng gâp geh nau maak. Gâp dơm jêh Brah Huêng Ueh gâp ta păng, păng mra njŭn nau sŏng ma phung mpôl băl bunuyh.$b$,true),
('bunong-vn','ISA',42,2,null,$b$Păng mâu mra nter huy ôh, mâu lĕ ăn bu tăng bâr păng tâm trong sâng.$b$,true),
('bunong-vn','ISA',42,3,null,$b$Păng mâu mra rtăch lơi ôh rpho deh jêh, jêh ri păng mâu mra khôm ôh ŭnh jrêng dăch nhhât jêh. Păng mra njŭn nau sŏng ma nau na nê̆.$b$,false),
('bunong-vn','ISA',42,4,null,$b$Păng mâu mra rdja mâu lah huơi ôh, kŏ păng ƀư tât nau sŏng ta neh ntu; jêh ri lĕ rngôch bri kơh dak mƀŭt gŭ kâp nau vay păng.$b$,true),
('bunong-vn','ISA',42,5,null,$b$Pô aơ Brah Ndu Yêhôva lah, nơm rhăk jêh ri pơk jêh trôk, nơm lăk jêh neh ntu jêh ri mpa luh bơh păng, nơm ăn suh n'hâm ma phung ƀon lan tâm păng, jêh ri nau rêh ma phung hăn ta nây:$b$,true),
('bunong-vn','ISA',42,6,null,$b$“Gâp jêng Yêhôva kuăl jêh may tâm nau sŏng srăng; gâp kuăn jêh may ta ti gâp mra chiă uănh may ăn may jêng du nau tâm rnglăp ma phung ƀon lan, nau ang ma phung ndŭl mpôl bunuyh,$b$,false),
('bunong-vn','ISA',42,7,null,$b$gay pơk măt phung chih, gay ngluh phung bu nă bơh ndrung bu krŭng, jêh ri phung tă bơh ndrung bu nă, phung gŭ tâm nau ngo.$b$,false),
('bunong-vn','ISA',42,8,null,$b$Gâp jêng Yêhôva, pô nây yơh amoh gâp! Gâp mâu mra ăn ôh nau chrêk rmah gâp ma nơm êng, mâu lĕ ăn nau tâm rnê gâp ma rup brah trah.$b$,true),
('bunong-vn','ISA',42,9,null,$b$Aơ, nau lor tât ngăn jêh, jêh ri aƀaơ aơ gâp mbơh nau mhe; lor nau nây tât gâp mbơh jêh ma may.$b$,false),
('bunong-vn','ISA',42,10,null,$b$Mprơ hom ma Yêhôva du nau mprơ mhe, mprơ tâm rnê hom ma păng bơh n'har neh ntu, Ơ phung hăn ta dak mƀŭt, nđâp ma lĕ rngôch mpa tâm păng, Ơ lĕ rngôch bri kơh dak mƀŭt jêh ri phung gŭ tâm nây.$b$,true),
('bunong-vn','ISA',42,11,null,$b$Ăn ndrêch rdah jêh ri lĕ ƀon toyh nter troh, nđâp lĕ rngôch ƀon phung Kêdar gŭ. Ăn phung gŭ tâm Sêla mprơ, ăn khân păng nter hâk bơh dor yôk.$b$,true),
('bunong-vn','ISA',42,12,null,$b$Ăn khân păng ƀư chrêk rmah ma Yêhôva, jêh ri mbơh nau tâm rnê ma păng tâm lĕ rngôch bri kơh dak mƀŭt.$b$,false),
('bunong-vn','ISA',42,13,null,$b$Yêhôva hăn pa năp tâm ban ma du huê brah, păng nsônh nau păng nuih tâm ban ma du huê bunuyh tâm lơh. Păng nter, păng ngơi huy, păng mra dơi đah păng rlăng đah păng.$b$,false),
('bunong-vn','ISA',42,14,null,$b$“Jŏ jêh gâp gŭ rklăk, gâp gŭ rklăk, gâp kuăn rdâng gâp nơm. Ƀiă lah aƀaơ aơ gâp jêng tâm ban ma du huê bu ur ji deh, gâp nter, ƀư sĭt sut jêh ri suh n'hâm.$b$,false),
('bunong-vn','ISA',42,15,null,$b$Gâp mra ƀư rai yôk jêh ri gôl, gâp mra ăn kro lĕ rngôch gơ̆ ndrêh. Gâp mra tâm rgâl dak krong jêng neh dăng, jêh ri gâp mra ƀư suăt dak nglao.$b$,true),
('bunong-vn','ISA',42,16,null,$b$Gâp mra njŭn phung chieh măt ta trong khân păng mâu mâp gĭt năl ôh, gâp mra têk khân păng tâm trong jê̆ khân păng mâu gĭt saơ ôh. Gâp mra rgâl nau ngo jêng nau ang ta năp khân păng, jêh ri ntŭk neh nduh ndăp jêng neh lâng. Pô nây yơh gâp mra ƀư, jêh ri mâu lơi khân păng ôh.$b$,false),
('bunong-vn','ISA',42,17,null,$b$Ƀiă lah gâp mra rŭch pa kơi jêh ri ăn bêk ngăn phung rnơm ma rup brah trah, phung lah ma phung rup tŏ chiăr. Khân may jêng phung brah hên! Phung Israel Mâu Dơn Nau Nkra Ôh.$b$,false),
('bunong-vn','ISA',42,18,null,$b$“Ơ phung tĭk gŭ iăt hom, Ơ phung chieh măt, Uănh hom, gay ma khân may dơi saơ!$b$,true),
('bunong-vn','ISA',42,19,null,$b$Mbu chieh măt, mâu tăp hĕ oh mon gâp? Mâu lah mbu nâm tĭk tâm ban ma nơm gâp hŏ njuăl hăn? Mbu chieh măt tâm ban ma nơm gâp prăp an jêh, chieh măt tâm ban ma oh mon Yêhôva?$b$,false),
('bunong-vn','ISA',42,20,null,$b$Khân may saơ jêh âk mpa, ƀiă lah mâu mâp sek uănh ôh; tôr khân may pơk jêh, ƀiă lah khân may mâu tăng ôh.”$b$,false),
('bunong-vn','ISA',42,21,null,$b$Yor nau sŏng srăng păng nơm, Yêhôva maak gay ăn bĭk jêh ri ƀư chrêk rmah nau vay păng.$b$,false),
('bunong-vn','ISA',42,22,null,$b$Ƀiă lah aơ jêng du phung ƀon lan bu ntŭng jêh ri pit sŏk jêh ndô ndơ, lĕ rngôch khân păng văk jêh nhuăl tâm trôm ntu bu pôn jêh tâm ngih bu nă. Khân păng jêng jêh phung bu pit sŏk, jêh ri mâu geh nơm tâm rklaih khân păng ôh; khân păng jêng jêh ndơ bu pit sŏk, mâu geh nơm lah ôh, “Nsĭt lơi hom khân păng!$b$,false),
('bunong-vn','ISA',42,23,null,$b$Mbu nâm tâm phung khân may mra rkêng tôr ma nau aơ, mra kâp jêh ri gŭ iăt ma rnôk mra tât?$b$,true),
('bunong-vn','ISA',42,24,null,$b$Mbu nâm jao jêh phung Yakôb ma nơm pit sŏk, jêh ri phung Israel ma phung ntŭng? Khân păng mâu ŭch hăn ôh tâm trong păng, mâu lĕ khân păng tông ma nau vay păng.$b$,false),
('bunong-vn','ISA',42,25,null,$b$Yor nây păng nkhŭt jêh ta klơ khân păng nau păng ji nuih duh jêh ri nau mhĭk tâm nau tâm lơh. Nau nây su jêh văr jŭm khân păng, ƀiă lah khân păng mâu gĭt rbăng ôh; ŭnh sa jêh khân păng, ƀiă lah khân păng mâu chrê ôh.$b$,false),
('bunong-vn','ISA',43,1,null,$b$Ƀiă lah aƀaơ aơ pô aơ Yêhôva lah: Nơm rhăk jêh khân may, Ơ phung Yakôb, jêh ri nơm njêng khân may, Ơ phung Israel: “Lơi klach ôh, yor lah gâp chuai jêh khân may; gâp kuăl jêh khân ma amoh khân may nơm, khân may jêng ndơ gâp.$b$,true),
('bunong-vn','ISA',43,2,null,$b$Tơ lah khân may rgăn dak, gâp mra gŭ ndrel ma khân may, jêh ri tơ lah khân may rgăn dak krong, khân may mâu mra ngâm ôh. Tơ lah khân may hăn tâm ŭnh păng mâu mra su khân may ôh, mpiăt ŭnh mâu lĕ păng hŭt khân may.$b$,false),
('bunong-vn','ISA',43,3,null,$b$Yor lah gâp jêng Yêhôva, Brah Ndu khân may. Nơm Kloh Ueh phung Israel, Nơm Tâm Rklaih khân may. Gâp ăn jêh bri Êjipt jêng ndơ tâm chuai khân may, bri Êthiôpi jêh ri bri Sêba jêng rnoh tâm chuai$b$,false),
('bunong-vn','ISA',43,4,null,$b$Yor lah khân may jêng khlay jêh ri geh nau yơk ta năp măt gâp, jêh ri yor lah gâp rŏng ma khân may, gâp mra ăn phung bunuyh jêng rnoh tâm chuai khân may, jêh ri phung ƀon lan jêng ndơ tâm chuai nau rêh khân may.$b$,false),
('bunong-vn','ISA',43,5,null,$b$Lơi klach ôh, yor lah gâp gŭ ndrel ma khân may; gâp mra njŭn phung kon sau khân tă bơh lơ, jêh ri gâp mra tâm rƀŭn khân tă bơh dâng.$b$,false),
('bunong-vn','ISA',43,6,null,$b$Gâp mra lah ma mpư̆ yôk. ‘Ăn mƀơk hom!’ Jêh ri ma rđŭng, ‘lơi kuan prăp ôh.’ Njŭn leo hom phung kon bu klâu gâp văch tă bơh ngai, jêh ri phung kon bu ur gâp bơh bôl dŭt bri neh$b$,false),
('bunong-vn','ISA',43,7,null,$b$ăp nơm mbu nâm bu kuăl ma amoh gâp, phung gâp rhăk jêh ma nau chrêk rmah gâp, phung gâp njêng jêh.”$b$,false),
('bunong-vn','ISA',43,8,null,$b$Njŭn leo hom phung ƀon lan chieh măt ƀiă lah ăt geh măt, jêh ri phung tĭk ăt geh tôr?$b$,true),
('bunong-vn','ISA',43,9,null,$b$Lĕ rngôch phung ndŭl mpôl bunuyh tâm rƀŭn ndrel n'grŭp, jêh ri phung ƀon lan gŭ tâm rƀŭn. Mbu tâm phung khân păng dơi mbơh lor nau aơ, jêh tâm mpơl ma he nau tât rnôk lor? Ăn khân păng njŭn phung ƀư ngăn gay bu dơi kơp khân păng sŏng, jêh ri ăn khân păng gŭ iăt jêh ri lah: “Nau nây ngăn yơh.”$b$,false),
('bunong-vn','ISA',43,10,null,$b$Yêhôva lah: “Khân may jêng phung mbơh ngăn ma gâp, jêh ri oh mon gâp săch jêh, gay ma khân păng dơi gĭt năl jêh ri chroh ma gâp, jêh ri gĭt rbăng gâp jêng Yêhôva yơh. Lor ma gâp mâu mâp geh brah êng ôh, mâu mra geh lĕ pa kơi gâp.$b$,false),
('bunong-vn','ISA',43,11,null,$b$Gâp, gâp yơh Yêhôva, rlau ma gâp mâu hôm geh nơm êng tâm rklaih ôh.$b$,false),
('bunong-vn','ISA',43,12,null,$b$Gâp mbơh jêh, gâp tâm rklaih jêh, jêh ri gâp tâm mpơl jêh, gâp nơm yơh mâu geh ôh brah bu năch ta nklang khân may; khân may jêng phung mbơh ngăn ma gâp.” Yêhôva lah:$b$,false),
('bunong-vn','ISA',43,13,null,$b$Gâp jêng Brah Ndu jêh ri bơh rnôk n'ho ro gâp jêng Brah Ndu yơh; mâu geh nơm dơi tâm rklaih bơh ti gâp ôh. Gâp pah kan, jêh ri mbu nâm dơi tâm rgâl nau nây?”$b$,false),
('bunong-vn','ISA',43,14,null,$b$Pô aơ Yêhôva lah: Nơm Tâm Chuai khân may, Nơm Kloh Ueh phung Israel, “Yor khân may yơh gâp mra njuăl bu hăn ta ƀon Babilôn, jêh ri têk leo phung Babilôn jêng phung du, tâm kŭmpăn khân păng rŏng jêh.$b$,true),
('bunong-vn','ISA',43,15,null,$b$Gâp jêng Yêhôva, Nơm Kloh Ueh khân may, nơm rhăk phung Israel, hađăch khân may.”$b$,false),
('bunong-vn','ISA',43,16,null,$b$Pô aơ Yêhôva lah: Nơm ƀư jêh du ntŭk trong tâm dak mƀŭt, du ntŭk rlong tâm dak klŏng brah,$b$,false),
('bunong-vn','ISA',43,17,null,$b$nơm ngluh ndeh jêh ri seh, phung ta han jêh ri phung kâp kơl. Khân păng tŭp ndrel n'grŭp, khân păng mâu hôm dơi dâk ôh, khân păng khĭt jêh tâm ban ma bu khôm ŭnh jrêng:$b$,false),
('bunong-vn','ISA',43,18,null,$b$“Lơi hôm kah gĭt ôh ma ndơ rnôk lor, mâu lĕ mĭn ma ndơ rnôk ơm.$b$,false),
('bunong-vn','ISA',43,19,null,$b$Aơ, gâp gŭ ƀư du nau mhe, aƀaơ aơ păng luh; khân păng mâu gĭt rbăng hĕ nau nây? Gâp mra ƀư du ntŭk trong tâm bri hŏng, gâp mra ăn dak krong hoch tâm bri rdah.$b$,false),
('bunong-vn','ISA',43,20,null,$b$Lĕ rngôch mpa bri mra yơk ma gâp, so bri jêh ri sĭm ôtrus, yor lah gâp ăn dak tâm bri hŏng, jêh ri dak krong hoch tâm bri rdah, gay ăn dak nhêt ma phung ƀon lan gâp săch jêh,$b$,false),
('bunong-vn','ISA',43,21,null,$b$Phung ƀon lan gâp njêng jêh ma gâp nơm, gay ma khân păng dơi mbơh nau tâm rnê ma gâp.$b$,false),
('bunong-vn','ISA',43,22,null,$b$Ƀiă lah khân may mâu mâp kuăl mbơh sơm ma gâp ôh, Ơ phung Yakôb; jêh ri khân may rgănh jêh đah gâp, Ơ phung Israel.$b$,true),
('bunong-vn','ISA',43,23,null,$b$Khân may mâu nhhơr ôh ma gâp biăp khân may, jêng mpa nhhơr gŭch, mâu lĕ khân may yơk ma gâp ma mpa khân may ƀư brah. Gâp mâu mâp ƀư jâk khân may ma mpa nhhơr ôh mâu lĕ mâp ƀư rgănh khân may su ndơ n'hôl ƀâu kah.$b$,true),
('bunong-vn','ISA',43,24,null,$b$Khân may mâu mâp rvăt rpu ma gâp ma prăk ôh, mâu lĕ mâp khân may ƀư mpay gâp ma ngi mpa khân may ƀư brah. Ƀiă lah khân may ƀư jâk gâp ma nau tih khân may, khân may ƀư rgănh jêh gâp ma nau kue khân may.$b$,false),
('bunong-vn','ISA',43,25,null,$b$“Gâp, gâp yơh jêng nơm jut lơi nau khân may rlau nau vay yor amoh gâp, jêh ri gâp mâu mra kah gĭt ôh ma nau tih khân may.$b$,false),
('bunong-vn','ISA',43,26,null,$b$Kah gĭt hom ma gâp, ăn he tâm dun ndrel n'grŭp; tâm mpơl hom nau khân may mĭn nau khân may sŏng srăng.$b$,false),
('bunong-vn','ISA',43,27,null,$b$Mbơ̆ khân may sa ơm ri ƀư tih jêh, jêh ri phung tâm tang khân may rlau jêh nau vay gâp.$b$,true),
('bunong-vn','ISA',43,28,null,$b$Yor nây gâp mra ƀư ƀơ̆ phung kôranh jrô kloh ueh, gâp jao phung Yakôb ma nau ƀư rai, jêh ri phung Israel ma nau bu suai rak.$b$,false),
('bunong-vn','ISA',44,1,null,$b$“Ƀiă lah gŭ iăt hom aƀaơ aơ, Ơ phung Yakôb, phung oh mon gâp, Ơ phung Israel, phung gâp săch jêh!$b$,true),
('bunong-vn','ISA',44,2,null,$b$Pô aơ Yêhôva lah, Nơm njêng jêh khân may, nơm mon jêh khân may tâm ndŭl, nơm mra kơl khân may: Lơi klach ôh. Ơ phung Yakôb, phung oh mon gâp, Ơ Yêrusalem, nơm gâp săch jêh.$b$,false),
('bunong-vn','ISA',44,3,null,$b$Yor lah gâp mra nkhŭt dak ta bri ji hir, jêh ri n'hor dak ta neh sơh, gâp mra nkhŭt Brah Huêng Ueh gâp ma phung kon sau khân may, jêh ri nau ueh uĭn gâp ma phung sau se khân may.$b$,false),
('bunong-vn','ISA',44,4,null,$b$Khân păng mra hon ta nklang gơ̆ , tâm ban ma tâm si Y-Sôl dăch n'hor dak hoch.$b$,false),
('bunong-vn','ISA',44,5,null,$b$Nơm aơ mra lah: ‘Gâp jêng ndơ Yêhôva!’ Nơm êng mra tâm amoh păng nơm ma amoh Yakôb, nơm êng mra chih ta ti păng. ‘Ndơ Yêhôva’ jêh ri mra tâm amoh păng nơm ma Y-Israel.”$b$,false),
('bunong-vn','ISA',44,6,null,$b$Pô aơ Yêhôva lah, Hađăch jêh ri Nơm Tâm Chuai. Yêhôva ma phung ta han: “Gâp jêng lor lơn jêh ri nơm nglĕ dŭt; jêh ri rlau ma gâp mâu hôm geh brah êng ôh.$b$,true),
('bunong-vn','ISA',44,7,null,$b$Mbu nâm jêng tâm ban ma gâp? Ăn mbơh nau nây, jêh ri mpơl nau nây ma gâp lĕ nau tât ntơm bơh rnôk gâp njŭn phung ƀon lan ơm gâp, jêh ri nau mra tât. Ăn khân păng mbơh moh nau mra tât.$b$,false),
('bunong-vn','ISA',44,8,null,$b$Lơi klach ôh mâu lĕ krit, mâu di hĕ gâp mbơh nau nây ma khân may bơh jŏ jêh, jêh ri tâm mpơl jêh nau nây? Khân may jêng phung mbơh ngăn gâp! Geh lĕ du huê Brah Ndu êng rlau lơn ma gâp? Mâu! Mâu geh Lŭ ôh; gâp mâu gĭt nơm êng ôh.”$b$,false),
('bunong-vn','ISA',44,9,null,$b$Lĕ rngôch phung ƀư rup brah jêng dơm dam, jêh ri ndơ ƀư maak ma khân păng mâu geh nau khlay. Phung mbơh ngăn ma rup brah nây mâu blau saơ ôh, mâu lĕ gĭt rbăng, gay ma ƀư bêk khân păng nơm.$b$,true),
('bunong-vn','ISA',44,10,null,$b$Mbu nâm trah du mlâm rup brah mâu lah tŏ chiăr rup brah ndơ nây mâu geh play khlay ma păng.$b$,true),
('bunong-vn','ISA',44,11,null,$b$Păng jêh ri lĕ rngôch phung băl păng mra bêk, jêh ri phung pah kan jêng knŏng bunuyh. Ăn lĕ rngôch khân păng tâm rƀŭn, ăn lĕ rngôch khân păng dâk; khân păng mra klach, khân păng mra bêk ndrel n'grŭp.$b$,false),
('bunong-vn','ISA',44,12,null,$b$Nơm chiăr loih nkra păng, păng pah kan dơm păng tâm sa ônh, păng tôp ma kon nôp, jêh ri chiăr păng ma nting tur ktang păng, păng ji ngot jêh ri roh nau ktang păng, păng mâu nhêt dak ôh, jêh ri pă$b$,true),
('bunong-vn','ISA',44,13,null,$b$Nơm trah meh nthăng rse ueh, păng treh ntrong ma mâng chih; păng nsut si ma mpu, jêh ri veh păng ma kômpa; mon păng tĭng nâm rup bunuyh, tĭng nâm nau ueh bunuyh, gay ma ăn păng gŭ tâm ngih brah.$b$,false),
('bunong-vn','ISA',44,14,null,$b$Păng kăl si sêdar, păng săch si n'ho mâu lah si têrêbin, ăn păng văch ma toyh tâm krŏng. Păng tăm si sêdar jêh ri dak mih ăn păng văch ma toyh.$b$,false),
('bunong-vn','ISA',44,15,null,$b$Tơm si nây prăp ma bunuyh su; păng sŏk du gâl jêh ri sênh ŭnh njâr, păng sênh ŭnh jêh ri gŭch piăng let tâm ban lĕ păng bu rup jêh ri yơk mbah ma rup nây. Păng trah rup brah jêh ri păn mbah ma rup.$b$,false),
('bunong-vn','ISA',44,16,null,$b$Păng su ma ŭnh du gâl si nây, ma du gâl êng nây păng gâm puăch, păng mpĭt puăch jêh ri păng sa kŏ hơm. Păng njâr ŭnh nây tâm ban lĕ jêh ri lah: “Ah hah, gâp răm jêh, gâp saơ jêh ŭnh!”$b$,false),
('bunong-vn','ISA',44,17,null,$b$Jêh ri ma du gâl si hôm, păng ƀư rup brah păng trah păng nơm. Păng păn mbah ta ăp rup, jêh ri kuăl mbơh sơm ma păng, lah: “Tâm rklaih hom gâp, yor lah may jêng brah gâp!”$b$,false),
('bunong-vn','ISA',44,18,null,$b$Khân păng mâu gĭt rbăng ôh, mâu lĕ blau sek uănh; yor lah bu n'grêp jêh măt khân păng, pô ri khân păng mâu dơi saơ ôh, jêh ri bu chăng nau mĭn khân păng, pô ri khân păng mâu dơi gĭt rbăng$b$,false),
('bunong-vn','ISA',44,19,null,$b$Mâu geh nơm gŭ mĭn ôh, mâu lĕ geh nau gĭt rbăng mâu lah nau sek uănh kŏ tât lah, “Gâp jêh du gâl tơm si nây tâm ŭnh, ta klơ sa ônh păng gâp gŭch piăng let, gâp mpĭt puăch jêh ri gâp sa jêh. Jêh ri hôm n'gul gâp mra njêng du ndơ bu tâm rmot? Gâp mra păn mbah lĕ ta năp du mlâm tơm si?”$b$,false),
('bunong-vn','ISA',44,20,null,$b$Păng siăm păng nơm ma ŭnh buh; nuih n'hâm ƀư ăn păng teng, jêh ri păng mâu dơi tâm rklaih huêng păng ôh, mâu lĕ dơi lah: “Mâu di hĕ ndơ gâp djôt tâm ti gâp jêng nau mƀruh?”$b$,false),
('bunong-vn','ISA',44,21,null,$b$Ăn khân may kah gĭt ma nau aơ, Ơ phung Yakôb, jêh ri Ơ phung Israel, yor lah khân may jêng phung oh mon gâp. Gâp njêng jêh khân may, khân may jêng phung oh mon gâp. Ơ phung Israel, gâp mâu mra chuêl khân may ôh.$b$,true),
('bunong-vn','ISA',44,22,null,$b$Gâp jut jêh nau khân may rlau nau vay tâm ban ma tŭk, jêh ri nau tih khân may tâm ban ma dak hŭl. Plơ̆ sĭt hom ma gâp, yor lah gâp tâm chuai jêh khân may.$b$,false),
('bunong-vn','ISA',44,23,null,$b$Ơ trôk, mprơ rhơn hom, yor lah Yêhôva ƀư jêh nau nây. Ơ ntŭk tâm dâng neh ntu nter troh hom, Ơ yôk, mprơ huy hom. Ơ krŏng jêh ri lĕ rngôch tơm si ta nây! Yor lah Yêhôva tâm chuai jêh phung Yakôb, jêh ri tâm mpơl nau chrêk rmah păng tâm phung Israel.$b$,false),
('bunong-vn','ISA',44,24,null,$b$“Pô aơ nau Yêhôva lah, Nơm Tâm Chuai khân may, ơm njêng khân may tâm ndŭl: Gâp jêng Yêhôva, nơm njêng jêh lĕ rngôch ndơ, gâp yơh pơk jêh trôk, nơm lăk jêh neh ntu,$b$,true),
('bunong-vn','ISA',44,25,null,$b$nơm ƀư roh nau tâm mbên phung mbơh lor tih, jêh ri nơm ăn phung n'hŭm jêng rluk, nơm rŭch lơi phung blau mĭn, jêh ri ăn nau khân păng gĭt rbăng jêng nau rluk;$b$,false),
('bunong-vn','ISA',44,26,null,$b$nơm ƀư na nê̆ nau oh mon păng ngơi, jêh ri ăn tât moh nau phung păng prơh hăn mbơh; nơm lah ma ƀon Yêrusalem. Bu mra gŭ tâm păng. Jêh ri ma lĕ rngôch ƀon bri Yuđa. ‘Bu mra rdâk tay khân păng, jêh ri gâp mra yơk rdâk tay ndơ ndăk khân păng rai jêh’$b$,false),
('bunong-vn','ISA',44,27,null,$b$nơm lah ma ntu jru, ‘Suăt hom may, gâp mra ăn suăt lơi dak krong may’;$b$,false),
('bunong-vn','ISA',44,28,null,$b$nơm lah ma Sirus, păng jêng rmăk biăp gâp, jêh ri păng mra ƀư lĕ nau gâp ton’, dôl lah di ma ƀon Yêrusalem. ‘Ăn bu rdâk păng’; jêh ri ma ngih brah Yuđa, Ăn bu dơm mbon may.”$b$,false),
('bunong-vn','ISA',45,1,null,$b$“Pô aơ Yêhôva ma nơm păng tŏ jêh dak ƀâu kah, ma Y-Sirus nơm gâp kuăn ti ma, gay ma nglăp phung ndŭl mpôl ma păng, jêh ri doh lơi rse bŭt phung hađăch, gay pơk mpông bloh ta năp păng, jêh ri bu mâu mra chăng ôh mpông pêr$b$,true),
('bunong-vn','ISA',45,2,null,$b$Gâp mra hăn lor ma may, jêh ri ƀư lâng lĕ trong nduh ndăp; gâp mra ƀư rai ăn hăch rhên mpông pêr kông, jêh ri nkêch lơi mâng loih nđăng.$b$,false),
('bunong-vn','ISA',45,3,null,$b$Gâp mra ăn ma may drăp khlay nau ngo, nau ndrŏng bu prăp tâm ntŭk ndâp, gay ma dơi gĭt gâp yơh jêng Yêhôva Brah Ndu phung Israel, nơm kuăl may ma amoh may.$b$,false),
('bunong-vn','ISA',45,4,null,$b$Yor phung oh mon gâp, phung Yakôb, jêh ri phung Israel, phung gâp săch jêh, gâp kuăl jêh ma amoh may, gâp ăn amoh may bu yơk, nđâp tơ lah may mâu năl gâp ôh.$b$,false),
('bunong-vn','ISA',45,5,null,$b$Gâp jêng Yêhôva, mâu geh Nơm êng ôh, rlau mâu hôm geh Brah Ndu ôh. Gâp mra rêt an rse bŭt may, nđâp tơ lah may mâu gĭt năl gâp ôh,$b$,false),
('bunong-vn','ISA',45,6,null,$b$gay ma phung bunuyh dơi gĭt ntơm bơh ntŭk nar luh jêh ri tă pa dâng mâu geh nơm êng ôh rlau ma gâp. Gâp jêng Yêhôva, jêh ri mâu geh nơm êng ôh.$b$,false),
('bunong-vn','ISA',45,7,null,$b$Gâp njêng nau ang jêh ri nau ngo. Gâp ƀư nau hao bĭk jêh njêng nau ƀư rai. Gâp jêng Yêhôva jêh ri ƀư lĕ rngôch nau aơ Yêhôva Nơm Rhăk Njêng$b$,false),
('bunong-vn','ISA',45,8,null,$b$“Ơ trôk, mih hom tă bơh klơ, jêh ri ăn trôk nkhŭt nau sŏng srăng. Ăn neh ntu pơk ăn toyh, gay ma tât nau tâm rklaih, jêh ri ăn nau đăp mpăn chiă uănh ndrel n'grŭp. Gâp jêng Yêhôva rhăk jêh nau nây.$b$,false),
('bunong-vn','ISA',45,9,null,$b$“Rêh ni ngăn ma nơm tâm rlăch đah nơm rhăk njêng păng, păng jêng du rplay yăng ta nklang yăng âk êng ta neh di lĕ uk mra lah ma nơm mon păng! “Moh may ƀư?” Mâu lah, lah: ‘Kan may mâu geh ntŭk djôt ôh?’$b$,true),
('bunong-vn','ISA',45,10,null,$b$Rêh ni ngăn ma nơm lah ma mbơ̆ păng: ‘Mbu may deh jêh?’ Mâu lah ma me păng: ‘Mâm ƀư ay ji n'gơch nkeng?’$b$,false),
('bunong-vn','ISA',45,11,null,$b$“Pô aơ Yêhôva, Nơm Kloh Ueh Israel jêh ri nơm njêng păng lah: Bi ma nau mra tât kăndơ̆ , may mra ôp gâp lĕ ma phung kon gâp, mâu lah ntăm ma gâp lĕ ma kan ti gâp ƀư?$b$,false),
('bunong-vn','ISA',45,12,null,$b$Gâp yơh njêng jêh neh ntu, jêh ri rhăk jêh bunuyh ta klơ păng. Ti gâp nơm yơh ling jêh trôk, jêh ri gâp njêng jêh lĕ rngôch phung ta han păng.$b$,false),
('bunong-vn','ISA',45,13,null,$b$Gâp n'hao jêh nơm nây ma nau sŏng srăng gâp, jêh ri gâp mra ƀư sŏng lĕ trong păng. Păng mra ndâk ƀon toyh gâp, jêh ri jêng kon me ma phung mra nsot bơh bri, mâu tăp yor rnoh ôh mâu lĕ yor nau nkhôm” Yêhôva ma phung ta han lah,$b$,false),
('bunong-vn','ISA',45,14,null,$b$Pô aơ Yêhôva lah: “Drăp ndơ bri Êjipt jêh ri ndơ tăch bri Êthiôpi jêh ri phung Sabê, bunuyh juat prêh mra văch ma khân may, jêh ri jêng ndơ khân may. Khân păng mra tĭng ndô̆ khân may, khân păng mra văch kât ma nse rvăk, jêh ri păn ta năp khân may, khân păng mra vơh vơl ma khân may, lah: ‘Nanê̆ Brah Ndu gŭ ndrel ma khân may, mâu geh nơm êng ôh, mâu geh brah êng ôh.’ ”$b$,false),
('bunong-vn','ISA',45,15,null,$b$Na nê̆ may jêng Brah Ndu pôn may nơm, Ơ Brah Ndu, Nơm Tâm Rklaih phung Israel.$b$,false),
('bunong-vn','ISA',45,16,null,$b$Lĕ rngôch phung ƀư rup brah mra bêk jêh ri uh ah.$b$,false),
('bunong-vn','ISA',45,17,null,$b$Ƀiă lah Yêhôva mra tâm rklaih phung Israel ma nau tâm rklaih n'ho ro. Khân may mâu mra bêk mâu lah uh ah ôh, tâm lĕ rngôch rnôk n'ho ro.$b$,false),
('bunong-vn','ISA',45,18,null,$b$Yor lah pô aơ Yêhôva lah, Nơm rhăk trôk, păng yơh jêng Brah Ndu, nơm mon neh ntu jêh ri njêng păng, păng yơh ăn nâp, păng mâu rhăk ăn jêng ntŭk hŏng ôh, ƀiă lah njêng păng ma ntŭk bu gŭ. Gâp jêng Yêhôva, mâu hôm geh nơm êng ôh.$b$,true),
('bunong-vn','ISA',45,19,null,$b$Gâp mâu mâp ngơi ndâp ôh tâm bri nau ngo. Gâp mâu lah ôh ma phung kon sau Yakôb. ‘Di lĕ khân may joi gâp mâu geh play khlay ôh? Gâp yơh Yêhôva ngơi nau na nê̆, gâp mbơh nau sŏng.’$b$,false),
('bunong-vn','ISA',45,20,null,$b$“Tâm rƀŭn hom khân may jêh ri văch hom, văch êp ndrel n'grŭp, khân may phung ndŭl mpôl du jêh! Phung tung rup brah trah ma si mâu geh nau gĭt rbăng ôh, jêh ti kuăl mbơh sơm ma brah, nây mâu dơi tâm rklaih khân păng ôh.$b$,false),
('bunong-vn','ISA',45,21,null,$b$Mbơh hom jêh ri tâm mpơl nau khân may; ăn khân păng tâm nchră ndrel n'grŭp! Mbu nâm mpơl jêh nau aơ ntơm bơh kăl e? Mbu nâm mbơh jêh nau aơ bơh sa ơm? Mâu di hĕ gâp nơm, Yêhôva? Jêh ri rlau ma gâp mâu hôm geh brah êng ôh, du huê Brah Ndu sŏng jêh ri Nơm Tâm Rklaih. Rlau ma gâp mâu hôm geh nơm êng ôh.$b$,false),
('bunong-vn','ISA',45,22,null,$b$“Sĭt hom ma gâp jêh ri geh nau tâm rklaih. Ơ lĕ rngôch ntŭk dŭt bri dŭt neh! Yor lah gâp jêng Brah Ndu, jêh ri mâu geh nơm êng ôh.$b$,true),
('bunong-vn','ISA',45,23,null,$b$Gâp ton săk jêh đah gâp nơm, nau ngơi luh jêh bơh bâr mbung gâp ma nau ngăn, jêh ri mâu mra rgâl ôh: Lĕ rngôch chon kômâk ta năp gâp, jêh ri lĕ rngôch mpiăt mra ton săk ma gâp.”$b$,false),
('bunong-vn','ISA',45,24,null,$b$Di ma gâp bu mra lah, ‘Knŏng tâm Yêhôva yơh geh nau sŏng srăng jêh ri nau ktang?” Lĕ rngôch mbu nâm nuih ma păng mra văch ta păng jêh ri bêk.$b$,false),
('bunong-vn','ISA',45,25,null,$b$Ƀiă lah tâm Yêhôva, lĕ rngôch kon sau Israel mra geh nau sŏng jêh ri nau chrêk rmah.$b$,false),
('bunong-vn','ISA',46,1,null,$b$Brah Bel păn, brah Nêbô prah; rup brah khân păng gŭ ta klơ ndŭr kơi mpô mpa jêh ri ndrôk. Mpa nây khân may rdeng jêng du ndơ jâk, ƀư rgănh mpô mpa.$b$,true),
('bunong-vn','ISA',46,2,null,$b$Phung brah nây păn jêh ri prah ndrel n'grŭp; khân păng mâu dơi tâm rklaih ndơ jâk ôh, ƀiă lah khân păng nơm hăn du jêng bu nă.$b$,false),
('bunong-vn','ISA',46,3,null,$b$Gŭ iăt hom gâp, Ơ ngih Yakôb lĕ rngôch phung hôm bơh ngih Israel, phung gâp mât mray jêh bơh nar bu deh ma khân may, phung gâp sŏk chông bơh ndŭl me khân may.$b$,true),
('bunong-vn','ISA',46,4,null,$b$Kŏ khân may jêng ranh gâp ăt jêng tâm ban, kŏ khân may hon sŏk (sŏk) nglang gâp mra chông khân may. Gâp njêng jêh, jêh ri gâp mra mât mray; gâp mra chông jêh ri rklaih khân may.$b$,false),
('bunong-vn','ISA',46,5,null,$b$“Ma mbu đah khân may tâm ban jêh ri tâm ban ma gâp?$b$,true),
('bunong-vn','ISA',46,6,null,$b$Phung dâk âk mah bơh dŭng jêh ri veh prăk ma njing, nkhôm du huê bunuyh chiăr mah, ăn păng ƀư rup brah. Jêh ri khân păng păn jêh ri mbah yơk!$b$,false),
('bunong-vn','ISA',46,7,null,$b$Khân păng chông tuy păng ta săng nglik, khân păng rdâk ta ntŭk păng jêh ri păng gŭ dâk ta nây; păng mâu mpât du bơh ntŭk păng ôh. Nđâp tơ lah bu nter ma păng, păng mâu dơi plơ̆ lah ôh, mâu lĕ tâm rklaih păng bơh nau uh ah.$b$,false),
('bunong-vn','ISA',46,8,null,$b$Ăn khân may kah gĭt nau aơ jêh ri sek mĭn. Ơ phung rlau nau vay, ăn khân may lŏ kah gĭt ma nau nây.$b$,true),
('bunong-vn','ISA',46,9,null,$b$Ăn khân may kah gĭt ma nau rnôk kăl e, yor lah gâp jêng Brah Ndu, mâu geh nơm êng ôh. Gâp jêng Brah Ndu jêh ri mâu geh nơm tâm ban ma gâp ôh.$b$,false),
('bunong-vn','ISA',46,10,null,$b$Gâp mbơh nau mra tât bơh kăl e tât kêng dŭt, jêh ri mbơh bơh rnôk kăl e nau ê tât ôh lah, ‘Nau gâp nchră mra ăt hôm jêh ri gâp mra ƀư lĕ nau gâp ŭch jêng ueh.’$b$,false),
('bunong-vn','ISA',46,11,null,$b$Gâp mra kuăl tă pa lơ du mlâm sĭm klang, du huê bunuyh bơh bri ngai ƀư tât nau gâp ŭch. Nau gâp ngơi jêh gâp mra ƀư tât nau nây.$b$,false),
('bunong-vn','ISA',46,12,null,$b$Gŭ iăt hom gâp, ơ phung geh nuih n'hâm dăng, phung gŭ ngai bơh nau sŏng srăng.$b$,false),
('bunong-vn','ISA',46,13,null,$b$Gâp njŭn nau sŏng srăng gâp văch dăch, păng mâu gŭ ngai ôh, jêh ri nau gâp tâm rklaih mâu mra gŭ kâp jŏ ôh. Gâp mra ăn nau tâm rklaih tâm ƀon Siôn, prăp nau chrêk rmah gâp ma phung Israel.”$b$,false),
('bunong-vn','ISA',47,1,null,$b$“Trŭnh jêh ri gŭ hom tâm ndruyh neh, Ơ kon bu ur druh ƀon Babilôn. Gŭ hom ta neh mâu geh sưng hađăch ôh, Ơ kon bu ur phung Kaldê! Yor lah bu mâu mra rnha ma may rdơ̆ rbăn ueh lăng ôh.$b$,true),
('bunong-vn','ISA',47,2,null,$b$Sŏk hom mpăl jêh ri kĭn rnih; sŏk hom bok nkŭm muh măt may, doh lơi ao jâr may, lơi nkŭm tơm blu may ôh, rgăn hom dak krong.$b$,true),
('bunong-vn','ISA',47,3,null,$b$Nau rhôk may mra mpơl, jêh ri bu mra saơ nau may bêk. Gâp mra har plơng bôk, gâp mâu mra nhhuach du huê ôh.”$b$,true),
('bunong-vn','ISA',47,4,null,$b$Nơm Tâm- Chuai he, amoh păng Yêhôva ma phung ta han jêng Nơm Kloh Ueh phung Israel.$b$,false),
('bunong-vn','ISA',47,5,null,$b$Gŭ rklăk hom, jêh ri hăn du ta ntŭk ngo, Ơ kon bu ur phung Kaldê, yor lah bu mâu mra rnha ay ôh hađăch ma lĕ rngôch ƀon hađăch.$b$,true),
('bunong-vn','ISA',47,6,null,$b$Gâp ji nuih jêh ri ma phung ƀon lan gâp, gâp ƀư ƀơ̆ jêh phung jêng drăp ndơn gâp; gâp jao jêh khân păng tâm ti may. May mâu mâp yô̆ ôh ma khân păng, hŏ dơm jêh mbăk mâng jâk ngăn ta klơ bunuyh ranh.$b$,false),
('bunong-vn','ISA',47,7,null,$b$Ay lah jêh. ‘Gâp mra jêng hađăch bu ur n'ho ro,’ ƀiă lah ay mâu mâp mĭn ma nau aơ, mâu lĕ ay kah gĭt ma nau mra tât ta kêng dŭt.$b$,false),
('bunong-vn','ISA',47,8,null,$b$“Yor nây, aƀaơ aơ iăt hom nau aơ, Ơ nơm rŏng ma nau kơnh, nơm gŭ ma nau rnơm jêh ri lah tâm nuih n'hâm ay nơm, ‘Knŏng gâp yơh, jêh ri rlau ma gâp mâu geh nơm êng ôh. Gâp mâu mra jêng bu ndrô sai ôh, jêh ri gâp mâu mra roh phung kon gâp ôh!$b$,false),
('bunong-vn','ISA',47,9,null,$b$Ƀiă lah bar nau tât aơ mra tât ma ay ƀât lât tâm du nar: Nau roh phung kon jêh ri nau bu ur ndrô sai. Khân păng mra tât ma ay hŏ nŭm jêh ma ay nđâp tơ lah ay jêng n'hŭm njêh, jêh ri geh nau brah toyh blau rƀên kđôi lĕ.$b$,false),
('bunong-vn','ISA',47,10,null,$b$Ay mĭn ay geh nau rnơm tâm nau ƀai ay. Ay lah. “Mâu geh nơm saơ gâp ôh! Nau njêh, jêh ri nau ay gĭt rbăng tâm nkhah đah ay, tơ lah ay lah jêh tâm nuih n'hâm. ‘Knŏng gâp yơk, jêh ri rlau ma gâp mâu geh nơm êng ôh.’$b$,false),
('bunong-vn','ISA',47,11,null,$b$Ƀiă lah nau djơh mhĭk mra tât ma ay, ay mâu gĭt ôh mbah ta păng văch; nau rêh ni mra tŭp ta ay, ay mâu dơi geh nau yô̆ an ôh; jêh ri nau ƀư rai mra tât ma ay ƀât lât dơm, ay mâu năn gĭt ôh.$b$,false),
('bunong-vn','ISA',47,12,null,$b$“Gŭ ƀư hom nau rƀên ay jêh ri tâm nau ay jêng n'hŭm njêh. Tâm nau nây ay pah kan jêh bơh rnôk ay hôm druh. Năng ai ay mra geh nau dơi, klăp lah ay dơi nhhu bu.$b$,true),
('bunong-vn','ISA',47,13,null,$b$Ay rgănh jêh ma nau ay tâm nchră âk; ăn nau nchră nây văch tâm rklaih ay; ăn phung gĭt năl trôk, phung sek mănh, phung sek khay mhe, ŭch dâk tâm rklaih ay ma nau mra tât ma ay.$b$,false),
('bunong-vn','ISA',47,14,null,$b$Aơ, khân păng jêng tâm ban ma rhe, ŭnh sa khân păng. Khân păng mâu dơi tâm nklaih khân păng nơm ôh bơh nau brah mpiăt ŭnh. Ŭnh aơ mâu jêng ôh tâm ban ma sa ônh bu njâr!$b$,false),
('bunong-vn','ISA',47,15,null,$b$Phung pah kan jêh ndrel ma ay jêng dơm dam tâm ban pô nây đŏng ma ay, phung ay tăch rgâl jêh bơh rnôk ay hôm druh. Ăp nơm khân păng nsong mblêng tĭng nâm trong tih păng nơm, mâu dơi geh nơm tâm rklaih ay ôh.$b$,true),
('bunong-vn','ISA',48,1,null,$b$“Gŭ iăt hom nau aơ, Ơ ngih Yakôb, bu tâm amoh Israel, phung luh văch bơh kŭr bŭt Y-Yuđa, phung ton sơm đah amoh Yêhôva, jêh ri vơh vơl ma Brah Ndu phung Israel, ƀiă lah mâu di đah nau na nê̆ mâu lah ma nau sŏng ôh.$b$,true),
('bunong-vn','ISA',48,2,null,$b$Yor lah khân may rnha khân may nơm phung ƀon lan bơh ƀon kloh ueh, jêh ri rnơm ma Brah Ndu Phung Israel, amoh păng Yêhôva ma phung ta han.$b$,false),
('bunong-vn','ISA',48,3,null,$b$Nau kăl e gâp mbơh jêh bơh rnôk kăl e, bâr mbung gâp ngơi jêh di ma nau nây, jêh ri gâp tâm mpơl jêh nau nây. Ƀât lât dơm gâp ƀư nau nây, jêh ri păng tât ngăn.$b$,true),
('bunong-vn','ISA',48,4,null,$b$Yor lah gâp gĭt jêh khân may jêng dăng bôk, trô ko khân may jêng du njăr rse loih, jêh ri ndăr kleng khân may jêng kông.$b$,false),
('bunong-vn','ISA',48,5,null,$b$Gâp mbơh jêh nau nây ma khân may bơh rnôk kăl e; lor ma nau nây tât gâp tâm mpơl jêh khân păng ma khân may, klach lah khân may lah, ‘Rup brah gâp ƀư jêh nau nây; rup gâp trah jêh ri rup gâp tŏ chiăr ntăm jêh nau nây.’$b$,false),
('bunong-vn','ISA',48,6,null,$b$Khân may tăng jêh, aƀaơ aơ uănh hom lĕ nau nây. Jêh ri may mâu mra mbơh hĕ nau nây? Ntơm bơh rlet pa năp gâp mra tâm mpơl nau mhe ma khân may, ndơ ndâp khân may mâu mâp gĭt ôh.$b$,false),
('bunong-vn','ISA',48,7,null,$b$Bu rhăk nau nây aƀaơ aơ, mâu geh ôh tâm rnôk kăl e; lor ma nar aơ khân may mâu mâp tăng nau aơ ôh. Klach lah khân may lah, ‘Aơ, gâp gĭt jêh nau nây.’$b$,false),
('bunong-vn','ISA',48,8,null,$b$Khân may mâu mâp tăng ôh, khân may mâu mâp gĭt ôh, bơh kăl e tôr khân may mâu mâp pơk ôh. Yor lah gĭt jêh khân may mra ƀư ma nau ƀlăch ƀlêr, jêh ri bơh nar me deh bu rnha khân may nơm tâm rdâng.$b$,false),
('bunong-vn','ISA',48,9,null,$b$Yor nây gâp nơm, gâp ât lơi nau gâp ji nuih, yor nau tâm rnê ma gâp nơm, gâp nkân lơi nau nây, gay ma gâp mâu ƀư rai lơi khân may ôh.$b$,false),
('bunong-vn','ISA',48,10,null,$b$Aơ, gâp ƀư kloh jêh khân may, ƀiă lah mâu geh tâm ban ma prăk ôh; gâp rlong uănh jêh khân may tâm năk ŭnh nau rêh ni.$b$,false),
('bunong-vn','ISA',48,11,null,$b$Yor ma gâp nơm, yor ma gâp nơm yơh, gâp ƀư nau nây. Yor lah mâm ƀư bu mra ƀư ƀơ̆ amoh gâp? Gâp mâu mra ăn ôh nau chrêk rmah gâp ma nơm êng.$b$,false),
('bunong-vn','ISA',48,12,null,$b$“Iăt hom gâp, Ơ phung Yakôb, jêh ri phung Israel, phung gâp kuăl jêh! Gâp nơm yơh, gâp jêng nơm lor lơn, gâp jêng nơm nglĕ dŭt đŏng.$b$,true),
('bunong-vn','ISA',48,13,null,$b$Ti gâp nơm dơm jêh mbon neh ntu, jêh ri ti ma gâp ling jêh trôk. Tơ lah gâp kuăl khân păng, khân păng dâk ndrel n'grŭp.$b$,false),
('bunong-vn','ISA',48,14,null,$b$Tâm rƀŭn hom lĕ rngôch khân may, jêh ri iăt hom! Mbu nâm tâm phung khân păng mbơh jêh nau aơ? Yêhôva rŏng ma nơm jêng ueh, mra ƀư tât nau păng rdâng ma ƀon Babilôn, jêh ri nting tur păng mra tâm rdâng đah phung Kaldê.$b$,false),
('bunong-vn','ISA',48,15,null,$b$Gâp, gâp yơh, ngơi jêh; Ơ gâp kuăl jêh păng, gâp mra njŭn tât păng, jêh ri păng mra dơi tâm kan păng.$b$,false),
('bunong-vn','ISA',48,16,null,$b$Ăn khân may văch êp ma gâp, iăt hom: “Bơh sa ơm nau nây gâp gŭ jêh ta nây.” Jêh ri aƀaơ aơ Kôranh Brah Yêhôva prơh jêh gâp hăn jêh ri Brah Huêng Ueh păng.$b$,false),
('bunong-vn','ISA',48,17,null,$b$Pô aơ Yêhôva lah, Nơm Tâm Chuai khân may, Nơm Kloh Ueh Israel: “Gâp nơm Yêhôva, Brah Ndu khân may, nơm sâm nti khân may dơi geh nau khlay, nơm njŭn khân may tâm trong may mra hăn.$b$,true),
('bunong-vn','ISA',48,18,null,$b$Ơ ŭch ngăn tơ lah khân may gŭ iăt jêh ma nau gâp ntăm! Tơ lah pô nây nau đăp mpăn khân may jêng jêh tâm ban ma dak krong, jêh ri nau sŏng srăng khân may tâm ban ma mpiăt dak rlai.$b$,false),
('bunong-vn','ISA',48,19,null,$b$Tâm ban lĕ phung kon khân may jêng jêh tâm ban ma choih, jêh ri sau se khân may tâm ban găr choih; nây khân păng bu mâu mra jut ôh, mâu dơi ăn roh bơh ta năp gâp n'ho ro.”$b$,false),
('bunong-vn','ISA',48,20,null,$b$Luh hom bơh ƀon Babilôn, du hom bơh bri Kaldê! Nter troh hom mbơh nau aơ, nkoch bri hom, njŭn mbơh nau aơ tât ta dŭt bri dŭt neh. Lah hom, “Yêhôva tâm chuai jêh oh mon păng phung Yakôb.”$b$,true),
('bunong-vn','ISA',48,21,null,$b$Khân păng mâu ji hir ôh tơ lah păng njŭn khân păng ndrêch rdah; păng ăn dak luh ma khân păng bơh lŭ. Păng rlah lŭ, jêh ri dak luh du pa dih.$b$,false),
('bunong-vn','ISA',48,22,null,$b$Yêhôva lah, “Mâu geh nau đăp mpăn ôh ma phung ƀai.”$b$,false),
('bunong-vn','ISA',49,1,null,$b$Ơ lĕ rngôch kô dak, iăt hom gâp! Ơ phung ƀon lan gŭ ngai, rkêng hom tôr! Yêhôva kuăl jêh gâp bơh ndŭl, bơh ndŭl me gâp păng tâm amoh gâp.$b$,true),
('bunong-vn','ISA',49,2,null,$b$Păng ăn trôm mbung gâp jêng tâm ban ma đao hơr ngăn păng pôn jêh gâp tâm gui ti păng; păng njêng gâp du mlâm hăr mplanh, păng pôn jêh gâp tâm trôm dĭng kăm (dĭng hăr) păng.$b$,false),
('bunong-vn','ISA',49,3,null,$b$Păng lah ma gâp, “May jêng oh mon gâp, Israel, tâm may gâp mra mpơl nau chrêk rmah gâp.”$b$,false),
('bunong-vn','ISA',49,4,null,$b$Ƀiă lah gâp lah, “Gâp pah kan jêh dơm dam, gâp dŏng jêh nau ktang gâp ma nau dơm, mâu khlay ôh. Ƀiă lah na nê̆ nau khư ma gâp gŭ ndrel ma Yêhôva, jêh ri nau nkhôm gâp gŭ ndrel ma Brah Ndu.”$b$,false),
('bunong-vn','ISA',49,5,null,$b$Aƀaơ aơ, pô aơ Yêhôva, nơm njêng jêh gâp tâm ndŭl ăn jêng oh mon păng, gay njŭn sĭt phung Yakôk ma păng, jêh ri tâm rƀŭn phung Israel ma păng, yor lah gâp geh nau yơk ta năp măt Yêhôva, jêh ri Brah Ndu gâp jêng jêh nau ktang gâp.$b$,false),
('bunong-vn','ISA',49,6,null,$b$Păng lah, “Jêng nau jê̆ ir ma may jêng oh mon gâp gay rdâk đŏng phung ndŭl mpôl Yakôb jêh ri rdâk đŏng phung Israel hôm. Gâp tâm ban lĕ ăn may mra jêng nau ang ma phung bu năch, gay ma nau gâp tâm rklaih dơi tât ta dŭt bri dŭt neh.”$b$,true),
('bunong-vn','ISA',49,7,null,$b$Pô aơ Yêhôva, Nơm Tâm Chuai jêh ri nơm Kloh Ueh Israel lah ma nơm bu rmot ngăn, ma nơm phung ndŭl mpôl bunuyh nuih, ma oh mon phung Kôranh Chiă Uănh: “Phung hađăch mra saơ jêh ri dâk, nđâp phung kon hađăch mra păn mbah, yor Yêhôva, nơm jêng răp jăp, Nơm Kloh Ueh Israel, nơm săch jêh may.”$b$,false),
('bunong-vn','ISA',49,8,null,$b$Pô aơ Yêhôva lah: “Tâm nar di gâp mra lŏ plơ̆ lah ma may, jêh ri tâm nar nau tâm rklaih gâp mra kơl may; gâp mra n'gang prăp may jêh ri ăn may jêng du nau tâm rnglăp đah phung ƀon lan, gay plơ̆ rdâk bri, gay tâm pă chăm drăp ntŭk rngol;$b$,true),
('bunong-vn','ISA',49,9,null,$b$lah ma phung bu nă. ‘Luh hom!’ Ma phung gŭ tâm nau ngo, ‘Tâm mpơl hom may nơm!’ Khân păng mra sông sa rŏ trong, jêh ri khân păng mra nkuĭl gơ̆ ta klơ lĕ rngôch yôk hil.$b$,false),
('bunong-vn','ISA',49,10,null,$b$Khân păng mâu mra ji ngot ôh, mâu lĕ ji hir, sial duh mâu lah ring duh nar mâu mra ƀư ma khân păng ôh, yor lah nơm yô̆ ma khân păng mra njŭn khân păng, păng mra gai khân păng dăch tu dak.$b$,false),
('bunong-vn','ISA',49,11,null,$b$Gâp mra ăn lĕ rngôch yôk gâp jêng trong, trong toyh gâp bu mra n'hao.$b$,true),
('bunong-vn','ISA',49,12,null,$b$Aơ phung aơ mra văch tă bơh ngai bơh dor lơ jêh ri bơh dâng, phung êng tă bơh bri Sinim.”$b$,false),
('bunong-vn','ISA',49,13,null,$b$Ơ trôk, mprơ hâk răm hom, maak hom, Ơ neh ntu; Ơ yôk, nter troh mprơ hom! Yor lah Yêhôva bonh leng jêh phung ƀon lan păng, jêh ri mra yô̆ ma phung rêh ni.$b$,true),
('bunong-vn','ISA',49,14,null,$b$Ƀiă lah ƀon Siôn lah, “Yêhôva dun jêh gâp. Kôranh Brah gâp chuêl jêh gâp.”$b$,true),
('bunong-vn','ISA',49,15,null,$b$Dơi lĕ du huê bu ur chuêl pu toh ma kon păng, kŏ păng mâu yô̆ ôh ma kon păng bơh ndŭl păng? Nđâp tơ lah păng dơi chuêl, ăt gâp mâu mra chuêl may ôh.$b$,false),
('bunong-vn','ISA',49,16,null,$b$Aơ, gâp tor treh jêh may ta mpang ti gâp; pêr may hôm ƀa ƀơ ta năp măt gâp.$b$,false),
('bunong-vn','ISA',49,17,null,$b$Phung plơ̆ rdâk may ƀư ngăch, jêh ri phung ƀư rai jêh may du bơh may.$b$,false),
('bunong-vn','ISA',49,18,null,$b$N'gơr măt may uănh văr jŭm dăr; lĕ rngôch khân păng tâm rƀŭn ndrel văch ma may. Tĭng nâm gâp gŭ rêh. Yêhôva lah, may mra sâm nsoh may nơm ma lĕ rngôch khân păng tâm ban ma ndơ nkrơ̆ ueh, may mra rêt may nơm đah khân păng tâm ban ma du huê bu ur tâm nkol jêh.$b$,true);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','ISA',49,19,null,$b$“Nanê̆ ntŭk hŏng may, ntŭk rngol may, jêh ri neh may bu ƀư rai jêh mra jêng hăt ir ma phung ƀon lan may, jêh ri phung ƀư rai may mra gŭ ngai.$b$,false),
('bunong-vn','ISA',49,20,null,$b$Phung kon may deh dôl rnôk nhĭm nhhiăng ăt mra lah ma tôr may, ‘Ntŭk aơ rhăt ir ma hên, ăn hom ntŭk toyh lơn ma hên dơi gŭ!$b$,false),
('bunong-vn','ISA',49,21,null,$b$Dôl nây mra lah tâm nuih n'hâm may,’ Mbu deh jêh phung aơ ma gâp? Yor lah gâp roh jêh kon jêh ri jêng bu ur ndrô gâng, bu nsot jêh gâp, bu cha lơi jêh gâp. Ƀiă lah mbu nâm rong an phung aơ? Aơ, bu cha lơi gâp gŭ êng, bơh phung aơ văch tât?$b$,false),
('bunong-vn','ISA',49,22,null,$b$Pô aơ Kôranh Brah Yêhôva lah; “Aơ, gâp mra yơr ti gâp ma phung ndŭl mpôl bunuyh gâp mra n'hao bok pla gâp ma âk phung ƀon lan, jêh ri khân păng mra chông phung kon bu klâu may ta ntang ntơh khân păng, jêh ri khân păng mra tuy an phung kon bu ur may ta klơ săng nglik khân păng.$b$,true),
('bunong-vn','ISA',49,23,null,$b$Phung hađăch bu klâu mra jêng mbơ̆ rong siăm may, jêh ri phung hađăch bu ur mra jêng me sâm pu may. Khân păng mra chŭn măt nđĭl ta neh ta năp may, jêh ri rli ndruyh ta jâng may. Dôl nây may mra gĭt gâp jêng Yêhôva; mbu nâm kâp gân gâp mâu mra bêk ôh.”$b$,true),
('bunong-vn','ISA',49,24,null,$b$Dơi lĕ bu sŏk lơi ndơ pit bơh nơm ktang. Mâu lah bu dơi tâm rklaih lĕ phung bu nă bơh nơm janh ƀai?$b$,true),
('bunong-vn','ISA',49,25,null,$b$Na nê̆ Yêhôva lah pô aơ: “Nđâp ma bu mra sŏk sĭt phung bu nă bơh nơm ktang, jêh ri bu mra tâm rklaih ndơ sŏk pit bơh phung janh ƀai; yor lah gâp mra tâm rlăch đah phung tâm rlăch đah may, jêh ri gâp mra tâm rklaih phung kon may.$b$,false),
('bunong-vn','ISA',49,26,null,$b$Gâp mra ăn phung tŭn jot may sa nglay khân păng nơm; khân păng mra nhŭl nhêt mham khân păng nơm tâm ban ma nhêt dak ndrănh mhe. Dôl nây lĕ rngôch bunuyh mra gĭt ma gâp jêng Yêhôva, Nơm Tâm Rklaih may, Nơm Tâm Chuai may, Nơm Brah Phung Yakôb.”$b$,false),
('bunong-vn','ISA',50,1,null,$b$Pô aơ Yêhôva lah: “Mbah sămƀŭt tâm cha lơi ur sai mê̆ may, ma sămƀŭt nây gâp cha lơi jêh păng? Aơ, yor nau kue may yơh bu tăch jêh may, jêh ri yor nau may rlau nau vay bu cha lơi jêh mê̆ may.$b$,true),
('bunong-vn','ISA',50,2,null,$b$Mâm ƀư tơ lah gâp văch, mâu geh bunuyh ôh? Tơ lah gâp kuăl, mâu geh bunuyh plơ̆ lah ôh hĕ? Ti gâp jêng gleh ir hĕ kŏ păng mâu dơi tâm chuai? Mâu lah gâp mâu geh nau brah mâu dơi tâm rklaih hĕ? Aơ, ma nau gâp nduyh gâp ƀư suăt dak mƀŭt, gâp ăn dak krong jêng ndrêch dĭ, ka khân păng ƀâu ôm yor mâu geh dak ôh, jêh ri khĭt yor ji hir dar.$b$,false),
('bunong-vn','ISA',50,3,null,$b$Gâp sâm nsoh trôk ma nau ngo, jêh ri ăn ƀau jêng ndơ nkŭm păng.”$b$,false),
('bunong-vn','ISA',50,4,null,$b$Kôranh Brah Yêhôva ăn jêh ma gâp mpiăt phung nti jêh, gay ma, ma nau gâp ngơi gâp dơi rdâng nơm rgănh. Ăp ôi păng pơk tôr gâp gay ma gâp gŭ iăt tâm ban ma nơm nti.$b$,true),
('bunong-vn','ISA',50,5,null,$b$Kôranh Brah Yêhôva pơk jêh tôr gâp, gâp mâu tâm rdâng ôh, gâp mâu n'gĭl pa kơi ôh.$b$,false),
('bunong-vn','ISA',50,6,null,$b$Gâp jao jêh ndŭr kơi gâp ma phung dong, jêh ri trô bom gâp ma phung păk têp kang gâp; gâp mâu mâp pôn măt gâp ôh ma nau bu ƀư bêk jêh ri soh dak diu.$b$,false),
('bunong-vn','ISA',50,7,null,$b$Yor lah Kôranh Brah Yêhôva kơl gâp, gâp mâu geh nau bêk ôh; yor nây đah lĕ nuih n'hâm gâp gŭ kram tâm ban ma lŭ, jêh ri gâp gĭt bu mâu mra ƀư bêk gâp ôh.$b$,true),
('bunong-vn','ISA',50,8,null,$b$Nơm kơp gâp sŏng gŭ dăch. Mbu mra tâm rdâng đah gâp? Ăn he dâk ndrel n'grŭp. Mbu jêng nơm phung gâp? Ăn păng văch êp gâp.$b$,true),
('bunong-vn','ISA',50,9,null,$b$Aơ, Kôranh Brah Yêhôva kơl gâp; mbu mra mbơh gâp jêng tih? Aơ, lĕ rngôch khân păng mra mŭnh sat tâm ban ma bok ao; nchiăr mra sa khân păng.$b$,false),
('bunong-vn','ISA',50,10,null,$b$Mbu nâm tâm phung khân may klach mbah yơk ma Yêhôva, jêh ri tông bâr ma oh mon păng, nơm hăn tâm nau ngo jêh ri mâu geh nau ang ôh? Ăn păng rnơm ma amoh Yêhôva, kâp rnơm ma Brah Ndu păng.$b$,true),
('bunong-vn','ISA',50,11,null,$b$Aơ, lĕ rngôch phung khân may sênh ŭnh, su ŭnh rdo, hăn hom tâm nau ang ŭnh jêh ri ŭnh rdo khân may su jêh! Bơh ti gâp yơh khân may mra geh nau aơ: Khân may mra lâng săk ma nau rêh ni.$b$,true),
('bunong-vn','ISA',51,1,null,$b$“Gŭ iăt hom gâp, Ơ khân may phung joi nau sŏng srăng, phung joi Yêhôva. Ăn khân may uănh ma lŭ ntŭk bu trah jêh khân may, ma ntu jru ntŭk bu đŏt sŏk jêh khân may.$b$,true),
('bunong-vn','ISA',51,2,null,$b$Ăn khân may uănh Y-Abraham mbơ̆ khân may, jêh ri ma H'Sara nơm deh ma khân may. Tơ lah gâp kuăl jêh păng, păng gŭ knŏng du huê, gâp mât ton ma păng, jêh ri ăn păng jêng bĭk.$b$,false),
('bunong-vn','ISA',51,3,null,$b$Na nê̆ Yêhôva mra tâm bonh ƀon Siôn. Păng mra tâm bonh lĕ rngôch ntŭk păng hŏng, păng mra ăn bri rdah păng jêng tâm ban ma Êđen, păng mra ăn bri hŏng păng jêng tâm ban ma đang trau Yêhôva. Nau hâk jêh ri nau maak mra gŭ ta nây, nau tâm rnê jêh ri bâr mprơ.$b$,true),
('bunong-vn','ISA',51,4,null,$b$“Ơ phung ƀon lan gâp, iăt hom gâp. Ơ phung ndŭl mpôl gâp, rkêng hom tôr ma gâp. Yor lah nau vay mra luh bơh gâp, jêh ri nau sŏng gâp mra jêng nau ang ma phung ndŭl mpôl bunuyh.$b$,true),
('bunong-vn','ISA',51,5,null,$b$Nau sŏng srăng gâp dăch tât ngăch, nau gâp tâm rklaih dăch tât jêh, jêh ri nting tur gâp mra ƀư tât nau di ma phung ndŭl mpôl bunuyh. Lĕ rngôch bri kơh dak mƀŭt, kâp gân gâp, khân păng rnơm ma nting tur gâp.$b$,false),
('bunong-vn','ISA',51,6,null,$b$N'gơr hom măt khân may klơ trôk, jêh ri uănh hom ta neh ntu tâm dâng. Yor lah trôk mra roh nâm bu nhhŭk ŭnh, neh ntu ơm mra sat nâm bu kho ao, jêh ri phung gŭ ta nây mra khĭt tâm ban ma rhuay. Ƀiă lah nau gâp tâm rklaih mra hôm n'ho ro, jêh ri nau sŏng srăng gâp mâu blau lôch ôh.$b$,true),
('bunong-vn','ISA',51,7,null,$b$“Iăt hom gâp, Ơ khân may phung gĭt nau sŏng srăng, phung ƀon lan geh nau vay gâp tâm nuih n'hâm khân may. Lơi klach ôh ma nau bunuyh nduyh, jêh ri lơi uh ah ôh ma nau khân păng rak suai.$b$,true),
('bunong-vn','ISA',51,8,null,$b$Yor lah nchiăr mra sa khân păng tâm ban ma du blah bok, jêh ri rhai mra sa khân păng tâm ban ma brai rsau biăp. Ƀiă lah nau sŏng srăng gâp mra gŭ n'ho ro, jêh ri nau gâp tâm rklaih mra tât ma lĕ rngôch rnôk.”$b$,false),
('bunong-vn','ISA',51,9,null,$b$Kah rngăl hom, kăl rngăl hom, soh hom nau ktang, Ơ nting tur Yêhôva! Kah rngăl hom tâm ban ma rnôk kăl e ri, rnôk sa ơm. Mâu di hĕ may koh jêh bri Êjipt jê̆ jê̆, nơm ntâp jêh bêh nhŭk nhăk?$b$,true),
('bunong-vn','ISA',51,10,null,$b$Mâu di may hĕ ƀư suăt jêh dak mƀŭt, dak tâm ntŭk jru ngăn, nơm ăn ntŭk jru tâm dak mƀŭt jêng trong gay ma phung may tâm chuai jêh dơi rgăn?$b$,false),
('bunong-vn','ISA',51,11,null,$b$Phung Yêhôva tâm chuai jêh mra lŏ sĭt, jêh ri văch ta ƀon Siôn ma nau mprơ, ndô đon hađăch nau maak n'ho ro; khân păng mra geh nau maak jêh ri nau hâk răm, nau rngot jêh ri nau vơl nđor mra du lĕ.$b$,true),
('bunong-vn','ISA',51,12,null,$b$“Gâp, gâp yơh jêng nơm tâm bonh khân may. Mbu may jêng kŏ may klach ma bunuyh blau khĭt, jêh ri ma kon bu klâu bunuyh jêng tâm ban ma gơ̆ ?$b$,true),
('bunong-vn','ISA',51,13,null,$b$May chuêl jêh Yêhôva, Nơm Njêng may, nơm ling jêh trôk jêh ri dơm jêh ntu neh ntu. May klach mro lĕ nar yor nau nơm tŭn jot ji nuyh, tơ lah păng nkra ŭch ƀư rai. Mbah nau ji nuyh nơm tŭn jot?$b$,false),
('bunong-vn','ISA',51,14,null,$b$Djê̆ lê̆ ta nây bu mra tâm rklaih phung jêng bună. Khân păng mâu mra khĭt tâm ndrung bu nă ôh, mâu lĕ khân păng pưt ndơ sông sa.$b$,false),
('bunong-vn','ISA',51,15,null,$b$Yor lah gâp jêng Yêhôva Brah Ndu khân may, nơm ăn dak mƀŭt rbuh jêh ri ăn mpiăt dak păng ƀư nteh. “Yêhôva ma phung ta han jêng amoh păng.$b$,false),
('bunong-vn','ISA',51,16,null,$b$Gâp dơm jêh nau gâp ngơi tâm trôm mbung may, jêh ri pôn jêh may ma gui ti gâp, dôl ling trôk jêh ri dơm mbon neh ntu, jêh ri lah ma ƀon Siôn. ‘Khân may jêng phung ƀon lan gâp.’ ”$b$,false),
('bunong-vn','ISA',51,17,null,$b$Kah rngăl hom, kah rngăl hom! Dâk hom may, Ơ ƀon Yêrusalem, phung nhêt jêh bơh ti Yêhôva kachok nau păng ji nuih, phung nhêt kŏ lĕ jêh tâm khăl ăn hăn ndĭt ndiu.$b$,true),
('bunong-vn','ISA',51,18,null,$b$Mâu geh du huê tâm phung kon bu klâu păng deh jêh blau gai păng ôh; mâu geh ôh du huê tâm lĕ rngôch phung kon bu klâu păng rong jêh mra kuăn ti păng.$b$,false),
('bunong-vn','ISA',51,19,null,$b$Bar nau jêr aơ tât jêh ma khân may. Mbu nâm nhĭm nhhiăng yor may? Nau jêng rngol jêh ri nau ƀư rai, nau sa sât ji ngot jêh ri đao tak; mbu mra tâm bonh khân may?$b$,false),
('bunong-vn','ISA',51,20,null,$b$Phung kon bu klâu may khĭt huăr jêh, khân păng gŭ lâng săk tâm lĕ njônh trong tâm ban ma jun geh nhuăl. Khân păng bêng ma nau Yêhôva ji nuih, nau Brah Ndu khân may nduyh.$b$,true),
('bunong-vn','ISA',51,21,null,$b$Yor nây iăt hom nau aơ, Ơ nơm rêh ni, nơm nhŭl ndrănh ƀiă lah mâu di ma dak play kriăk ƀâu ôh.$b$,true),
('bunong-vn','ISA',51,22,null,$b$Pô aơ Kôranh Brah may, Yêhôva Brah Ndu may, nơm n'gang nau ƀon lan păng lah: “Aơ, gâp sŏk lơi jêh ka chok nau hăn ndĭt ndĭl bơh ti may; may mâu mra nhêt đŏng ôh khăl nau gâp ji nuih.$b$,false),
('bunong-vn','ISA',51,23,null,$b$Gâp mra dơm păng tâm ti phung ƀư rêh ni may, phung lah jêh ma may. ‘Kŭnh hom may, gay ma hên dơi rgăn.’ Jêh ri may ăn jêh ndŭr kơi may jêng tâm ban ma neh, tâm ban ma trong ăn khân păng rgăn.”$b$,true),
('bunong-vn','ISA',52,1,null,$b$Kah rngăl hom, kah rngăl hom, Ơ ƀon Siôn, soh hom nau ktang may. Soh hom bok ao ueh may. Ơ Yêrusalem, ƀon kloh ueh. Yor lah mâu mra geh ôh phung mâu koh ntâu jêh ri phung mâu kloh lăp tâm may.$b$,true),
('bunong-vn','ISA',52,2,null,$b$Rtuh hom ndruyh neh bơh may, dâk hom may, Ơ ƀon Yêrusalem; doh lơi rse ta trô ko may, Ơ bu nă kon bu ur ƀon Siôn.$b$,false),
('bunong-vn','ISA',52,3,null,$b$Yor lah pô aơ Yêhôva lah: “Bu tăch jêh may dơm dam, jêh ri bu mra tâm chuai may dơm dam tâm ban lĕ.”$b$,false),
('bunong-vn','ISA',52,4,null,$b$Yor lah pô aơ Kôranh Brah Yêhôva lah: “Lor lơn phung ƀon lan gâp hăn ta bri Êjipt ŭch gŭ ƀât ta nây; jêh ri phung Asi ri tŭn jot jêh khân păng mâu geh nau.”$b$,false),
('bunong-vn','ISA',52,5,null,$b$“Pô ri aƀaơ aơ, moh gâp geh ta aơ.” Yêhôva lah: Yor lah bu sŏk jêh mâu geh nau phung ƀon lan gâp”, Yêhôva lah. “Phung Kôranh chiă uănh khân păng mưch, jêh ri bu suai rak ma amoh gâp ăp nar ƀa ƀơ.$b$,false),
('bunong-vn','ISA',52,6,null,$b$Yor nây phung ƀon lan gâp mra gĭt năl amoh gâp. Yor nây khân păng mra gĭt tâm nar nây, gâp jêng nơm ngơi yơh, aơ, ta aơ gâp.”$b$,false),
('bunong-vn','ISA',52,7,null,$b$Ueh ngăn ta klơ yôk jâng phung njŭn nau mhe mhan ma nau ueh, phung mbơh nau tâm rklaih, phung lah ma ƀon Siôn, “Brah Ndu khân may gŭ chiă$b$,true),
('bunong-vn','ISA',52,8,null,$b$Iăt hom, phung gak may nter troh, khân păng mprơ ndrel n'grŭp ma nau hâk. Yor lah ăp nơm saơ ma măt khân păng nau Yêhôva plơ̆ lah ma ƀon Siôn.$b$,false),
('bunong-vn','ISA',52,9,null,$b$Nter troh hom ma nau mprơ ndrel n'grŭp, Ơ ntŭk hŏng tâm ƀon Yêrusalem, yor lah Yêhôva tâm bonh jêh phung ƀon lan păng, păng tâm chuai jêh ƀon Yêrusalem.$b$,false),
('bunong-vn','ISA',52,10,null,$b$Yêhôva tâm mpơl jêh kan nting tur kloh ueh păng ƀư, ta năp măt lĕ rngôch phung ndŭl mpôl bunuyh, jêh ri lĕ rngôch dŭt bri dŭt neh mra saơ nau Brah Ndu he tâm rklaih.$b$,false),
('bunong-vn','ISA',52,11,null,$b$Du hom, du hom, luh hom bơh ntŭk nây! Lơi pah du ntil ndơ mâu kloh ôh! Luh hom bơh tâm nklang păng, ƀư kloh hom may nơm, Ơ phung djôt sen ngan Yêhôva!$b$,true),
('bunong-vn','ISA',52,12,null,$b$Yor lah khân may mâu mra luh ma nau ndal ôh, mâu lĕ khân may du ma nau bu tĭng, yor lah Yêhôva mra hăn ta năp khân may, jêh ri Brah Ndu Israel mra jêng nơm gak pa kơi khân may.$b$,true),
('bunong-vn','ISA',52,13,null,$b$Aơ, oh mon gâp mra bĭk rơ̆ , bu mra gŭ yơk ma păng jêh ri sâm n'hao păng, păng mra gŭ ta ntŭk prêh ngăn.$b$,true),
('bunong-vn','ISA',52,14,null,$b$Tâm ban ma âk bunuyh gŭ hih rhâl ma păng. Yor muh măt păng sôt rlau lơn ma bunuyh mâp geh, jêh ri săk jăn păng sôt lơn ma phung kon bu klâu bunuyh.$b$,false),
('bunong-vn','ISA',52,15,null,$b$Tâm ban pô nây đŏng păng mra hih rhâl âk phung ndŭl mpôl bunuyh; yor păng phung hađăch mra n'grêp trôm mbung khân păng. Yor lah khân păng mra saơ nau bu mâu mâp nkoch bri ma khân păng ôh, jêh ri khân păng mra gĭt rbăng nau khân păng mâu mâp tăng ôh.$b$,false),
('bunong-vn','ISA',53,1,null,$b$Mbu nâm chroh jêh ma nau hên mbơh, jêh ri ma mbu nâm kan nting tur Yêhôva ƀư tâm mpơl jêh?$b$,true),
('bunong-vn','ISA',53,2,null,$b$Yor lah păng văch ma toyh jêh ta năp Yêhôva tâm ban ma du ndơ nse bu tăm, tâm ban ma nkeh luh jêh bơh neh sơh. Păng mâu hôm jêng đŏng mâu lah nau ueh ôh kŏ ăn he ŭch uănh ma păng, jêh ri mâu geh nau ueh ôh kŏ he rŏng ma păng.$b$,false),
('bunong-vn','ISA',53,3,null,$b$Păng jêng nơm bu tâm rmot jêh ri dun jêh, du huê bunuyh gĭt rngot jêh ri gĭt năl nau ji. Tâm ban ma du huê bu pôn muh măt păng, bu tâm rmot ma păng, jêh ri he mâu yơk ma păng ôh.$b$,false),
('bunong-vn','ISA',53,4,null,$b$Na nê̆ păng tuy jêh nau ji kuet he, păng anh jêh nau rngot klâng he, ƀiă lah he kơp păng tâm ban ma nơm Brah Ndu tâm rmal, nơm Brah Ndu dong jêh ri ƀư rêh ni.$b$,true),
('bunong-vn','ISA',53,5,null,$b$Ƀiă lah bu ƀư sôt jêh păng yor nau he rlau nau vay ƀư rmanh jêh păng yor nau kue he; nau tâm rmal tŭp ta păng ăn nau ngăch prăl ma he, jêh ri yor nau plưch sôt păng he bah jêh.$b$,false),
('bunong-vn','ISA',53,6,null,$b$Lĕ rngôch he tâm ban ma biăp nkhah du jêh, ăp nơm he teng tĭng trong păng nơm; jêh ri Yêhôva dơm jêh ta păng nau kue lĕ rngôch he.$b$,false),
('bunong-vn','ISA',53,7,null,$b$Bu tŭn jot păng jêh ri ƀư rêh ni păng, ƀiă lah păng mâu mâp ha mbung păng ôh; tâm ban ma du mlâm kon biăp bu njŭn ta ntŭk bu sreh nkhĭt, tâm ban ma du mlâm kon biăp mlo ta năp phung nkăp rsau păng, tâm ban pô nây lĕ păng mâu hă mbung păng ôh.$b$,true),
('bunong-vn','ISA',53,8,null,$b$Ma nau tŭn jot jêh ri nau phat dôih bu ngroh lơi jêh păng, bi ma phung rnôk păng mbu mâp mĭn ma bu nkhĭt jêh păng yor nau phung ƀon lan gâp rlau jêh nau vay?$b$,false),
('bunong-vn','ISA',53,9,null,$b$Bu ăn môch ma păng ndrel ma phung ƀai, ndrel ma du huê bunuyh ndrŏng tơ lah păng khĭt, nđâp tơ lah păng mâu mâp ƀư nau mhĭk kđôi lĕ, jêh ri trôm mbung păng mâu mâp ngơi nau ndơm ôh.$b$,false),
('bunong-vn','ISA',53,10,null,$b$Ƀiă lah jêng nau ƀư maak ma Yêhôva ƀư bŭr sôt mâm săk ô băl; ƀư ăn ô băl ji tơ lah bu ăn huêng ô băl jêng ndơ nhhơr yor nau tih; bu mra saơ phung kon sau ô băl, jêh ri mra njong nar ô băl jêh ri nau Yêhôva ŭch dơi jêng ngăn tâm ti Păng.$b$,true),
('bunong-vn','ISA',53,11,null,$b$Jêh ri mra saơ rplay khlay bơh nau rêh ni nây jêh ri mra maak. Ma nau păng blau mĭn Oh Mon Sŏng gâp mra ăn bu kơp sŏng âk bunuyh; jêh ri păng mra tuy nau kue khân păng.$b$,false),
('bunong-vn','ISA',53,12,null,$b$Yor nây gâp mra tâm pă ma păng du kô̆ ndrel ma phung toyh, jêh ri păng mra pă ndơ pit sŏk ndrel ma phung ktang, yor lah păng nkhŭt jêh huêng păng ma nau khĭt, jêh ri bu kơp păng ndrel ma phung rlau nau vay. Ƀiă lah păng tuy jêh nau tih âk bunuyh, jêh ri mbơh sơm an ma phung rlau nau vay.$b$,true),
('bunong-vn','ISA',54,1,null,$b$Mprơ hom, ơ bu ur ndrô gâng, nơm mâu mâp deh, mprơ hom nau mprơ rhơn răm, Ơ nơm mâu mâp ji deh ôh! Yor lah phung kon bu ur bu cha lơi jêh mra jêng âk lơn ma phung kon bu ur geh sai. Yêhôva lah$b$,true),
('bunong-vn','ISA',54,2,null,$b$“Ƀư huy hom ntŭk ngih bok ay, ăn bu lăk ăn dĭ bok nching ntŭk ay gŭ; lơi ta rdâng ôh, nthăng rse ay jêh ri ƀư nâp mâng rdâng may.$b$,false),
('bunong-vn','ISA',54,3,null,$b$Yor lah ay mra ƀư bĭk mpeh pa ma jêh ri mpeh pa chiau, phung kon sau ay mra sŏk pha ay phung ndŭl mpôl bunuyh, jêh ri ăn bêng ma bunuyh ƀon toyh khân păng lĕ jêng rngol jêh.$b$,false),
('bunong-vn','ISA',54,4,null,$b$Lơi klach ôh, yor lah ay mâu mra bêk ôh; lơi uh ah ôh, yor lah bu mâu mra ƀư bêk ay ôh. Yor lah ay mra chuêl nau ay bêk dôl kon se, jêh ri ay mâu mra kah gĭt ôh ma nau ay bêk jêng bu ur ndrô sai.$b$,true),
('bunong-vn','ISA',54,5,null,$b$Yor lah Nơm Rhăk ay jêng sai ay, Yêhôva ma phung ta han jêng amoh păng; jêh ri Nơm Kloh Ueh Israel jêng Nơm Tâm Chuai, bu rnha păng Brah Ndu ma lĕ neh ntu.$b$,false),
('bunong-vn','ISA',54,6,null,$b$Yor lah Yêhôva kuăl jêh ay tâm ban ma du huê ur bu cha lơi jêh, jêh ri geh nuih n'hâm rngot, tâm ban ma du huê ur druh, tơ lah bu cha lơi, Brah Ndu may lah.$b$,false),
('bunong-vn','ISA',54,7,null,$b$Gâp cha lơi jêh ay ƀât lât, ƀiă lah ma nau yô̆ toyh gâp mra plơ̆ kuăl ay.$b$,true),
('bunong-vn','ISA',54,8,null,$b$Tâm nau ji nuih rmeh rmai gâp pôn jêh muh măt gâp ma ay ƀât lât, ƀiă lah ma nau rŏng n'ho ro gâp mra yô̆ ma ay.” Yêhôva Nơm Tâm Chuai ay lah:$b$,false),
('bunong-vn','ISA',54,9,null,$b$“Yor lah gâp kơp nau aơ jêng tâm ban ma rnôk Y-Nôê; tâm ban ma gâp ton sơm jêh gâp mâu mra bêk ma ay ôh, mâu lĕ nduyh ay n'ho ro.$b$,false),
('bunong-vn','ISA',54,10,null,$b$Yor lah yôk dơi du, jêh ri mbon mra rgâl ntŭk, ƀiă lah nau gâp rŏng răp jăp mâu mra du bơh ay ôh, nau gâp tâm rnglăp ma nau đăp mpăn mâu dơi rgâl lĕ.” Yêhôva lah, nơm geh nau rŏng ma ay.$b$,false),
('bunong-vn','ISA',54,11,null,$b$Ơ nơm rêh ni, nơm sial phŭt rpuh đô̆ jêh ri nơm mâu geh bonh leng ôh, aơ, gâp mra mhĭng lŭ ay ma dak ƀlĭt ueh lơn, jêh ri gâp mra dơm mbon may ma lŭ saphir.$b$,true),
('bunong-vn','ISA',54,12,null,$b$Gâp mra ƀư bôk pho may ma lŭ rubi, mpông pêr may ma lŭ êskabuk, jêh ri lĕ pêr may ma lŭ khlay.$b$,true),
('bunong-vn','ISA',54,13,null,$b$Yêhôva mra sâm nti lĕ rngôch phung kon bu klâu may jêh ri kon bu klâu may mra bĭk rơ̆ ngăn.$b$,false),
('bunong-vn','ISA',54,14,null,$b$Gâp mra ƀư nâp may ma nau sŏng srăng; may mra gŭ ngai đah nau bu tŭn jot, yor lah may mâu mra klach ôh, jêh ri gŭ ngai đah nau bu nhhu, yor lah nau nây mâu mra văch dăch may ôh.$b$,false),
('bunong-vn','ISA',54,15,null,$b$Tơ lah bu nsônh nau tâm rdâng, nau nây mâu luh tă bơh gâp ôh; mbu nâm mra nsônh nau tâm rdâng đah may mra rai yor may.$b$,false),
('bunong-vn','ISA',54,16,null,$b$Aơ, gâp rhăk jêh nơm chiăr, nơm suh nuh ŭnh sa ônh jêh ri ƀư ndơ tâm lơh prăp dŏng ma nau tâm lơh. Jêh ri gâp rhăk lĕ nơm ƀư rai gay ƀư rai.$b$,false),
('bunong-vn','ISA',54,17,null,$b$Mâu geh ôh du ndơ tâm lơh bu nkra gay ƀư ma may mra dơi, may mra dơi ma ăp mpiăt ngơi dôih tâm rdâng đah may. Nau aơ yơh jêng drăp ndơn ma phung oh mon Yêhôva, jêh ri nau sŏng srăng khân păng geh tă bơh gâp.” Yêhôva lah.$b$,true),
('bunong-vn','ISA',55,1,null,$b$“Hơi, ăp nơm ji hir, văch ta dak; jêh ri mbu nâm mâu geh prăk ôh, văch hom, rvăt jêh ri sa! Văch hom, rvăt dak play kriăk ƀâu jêh ri dak toh ndrôk mâu geh ma prăk, mâu geh ma rnoh ôh.$b$,true),
('bunong-vn','ISA',55,2,null,$b$Mâm ƀư khân may dâk prăk ma ndơ mâu jêng ndơ sông sa ôh, jêh ri pah kan ma ndơ mâu blau hơm ôh? Iăt gâp na nê̆, sa hom moh ndơ, jêh ri ƀư maak khân may nơm ma ndơ sa ueh kah.$b$,true),
('bunong-vn','ISA',55,3,null,$b$Rkêng hom tôr khân may jêh ri văch hom ma gâp; gŭ iăt hom gay ma huêng khân may dơi rêh; jêh ri gâp mra ƀư ma khân may nau tâm rnglăp n'ho ro, nâm bu ntŭk nau rŏng răp jăp ngăn ma Y-Đavit.$b$,false),
('bunong-vn','ISA',55,4,null,$b$Aơ, gâp ăn păng jêng nơm mbơh ngăn ma phung ƀon lan.$b$,false),
('bunong-vn','ISA',55,5,null,$b$Aơ, khân may mra kuăl phung ndŭl mpôl khân may mâu gĭt năl ôh, jêh ri phung ndŭl mpôl mâu gĭt năl khân may mra nchuăt ran ta khân may, yor Yêhôva Brah Ndu khân may, jêh ri yor Nơm Kloh Ueh Phung Israel, yor lah păng ƀư jêh ăn chrêk rmah khân may.”$b$,false),
('bunong-vn','ISA',55,6,null,$b$Joi hom Yêhôva dôl bu dơi saơ păng; kuăl mbơh sơm hom ma păng dôl păng gŭ dăch.$b$,true),
('bunong-vn','ISA',55,7,null,$b$Ăn phung ƀai cha lơi hom trong păng nơm, jêh ri ăn bunuyh kue cha lơi nau păng mĭn. Ăn păng nơm sĭt ma Yêhôva, gay ma păng geh nau yô̆, ma Brah Ndu he yor lah păng mra yô̆ an rmeh ler.$b$,false),
('bunong-vn','ISA',55,8,null,$b$“Yor lah gâp mĭn mâu jêng nau khân may mĭn ôh, trong khân may mâu lĕ jêng trong gâp.” Yêhôva lah:$b$,true),
('bunong-vn','ISA',55,9,null,$b$“Yor lah tâm ban ma trôk prêh lơn ma neh ntu, pô nây lĕ trong gâp jêng prêh lơn ma trong khân may, jêh ri nau gâp mĭn prêh lơn ma nau khân may mĭn.$b$,false),
('bunong-vn','ISA',55,10,null,$b$Yor lah tâm ban ma dak mih jêh ri pler jŭr bơh trôk, mâu hôm sĭt ta nây ôh, ƀiă lah djrah neh, ăn păng hon ndơ jêh ri kao, jêh ri ăn ntil ma nơm srih jêh ri ndơ sông sa ma nơm sa,$b$,false),
('bunong-vn','ISA',55,11,null,$b$tâm ban pô nây lĕ nau gâp ngơi luh bơh trôm mbung gâp mra jêng păng mâu mra sĭt ma gâp dơm dam ôh, ƀiă lah păng mra ƀư jêh nau gâp ŭch, jêh ri păng mra dơi tâm nau gâp mprơh păng hăn jêh.$b$,false),
('bunong-vn','ISA',55,12,null,$b$Yor lah khân may mra hăn ma nau răm, jêh ri bu mra njŭn khân may ma nau đăp mpăn; Yôk jêh ri dor mra mprănh nau mprơ ta năp khân may, jêh ri lĕ rngôch tơm si tâm bri mra tap ti.$b$,false),
('bunong-vn','ISA',55,13,null,$b$Nsro ma lok, tơm si n'ho mra hon; nau nây mra jêng ndơ kah gĭt ma Yêhôva, nau tâm mbên n'ho ro bu mâu dơi ngroh ôh.”$b$,true),
('bunong-vn','ISA',56,1,null,$b$Pô aơ Yêhôva lah: “Ndjôt prăp hom nau di, jêh ri ƀư hom nau sŏng srăng, yor lah nau gâp tâm rklaih dăch tât jêh, jêh ri nau sŏng srăng gâp mra gơnh tâm mpơl.$b$,true),
('bunong-vn','ISA',56,2,null,$b$Ueh maak ngăn ma bunuyh ƀư nau nây, jêh ri ma kon bunuyh djôt prăp păng nâp, nơm prăp nar Saƀat mâu ƀư ƀơ̆ păng ôh, jêh ri nkân ti păng mâu ƀư du ntil nau mhĭk ôh.”$b$,false),
('bunong-vn','ISA',56,3,null,$b$Lơi ăn bu năch tâm rnglăp păng nơm đah Yêhôva lah: “Na nê̆ ngăn Yêhôva mra tâm nkhah gâp bơh phung ƀon lan păng.” Lơi ăn oh mon nter lah: “Aơ, gâp jêng du n'gâng tơm si kro.”$b$,false),
('bunong-vn','ISA',56,4,null,$b$Yor lah pô aơ Yêhôva lah: “Ma phung oh mon bu chor djôt prăp nar Saƀat gâp, săch nau ƀư maak ma gâp, jêh ri djôt prăp nâp nau gâp tâm rnglăp,$b$,false),
('bunong-vn','ISA',56,5,null,$b$ma khân păng yơh gâp mra ăn tâm ngih gâp jêh ri tâm nkuĭl gâp du nau bu kah gĭt jêh ri du amoh ueh lơn ma phung kon bu klâu jêh ri ma phung kon bu ur. Gâp mra ăn ma khân păng du amoh n'ho ro, bu mâu mra jut lơi ôh.$b$,false),
('bunong-vn','ISA',56,6,null,$b$Jêh ri phung bu năch tâm rnglăp khân păng nơm đah Yêhôva, gay pah kan ma păng, gay rŏng ma amoh Yêhôva, gay jêng phung oh mon păng, ăp nơm djôt prăp nar Saƀat mâu ƀư ƀơ̆ păng ôh, jêh ri djôt prăp nâp nau gâp tâm rnglăp,$b$,true),
('bunong-vn','ISA',56,7,null,$b$khân păng yơh gâp mra njŭn leo ta yôk kloh ueh gâp, jêh ri ăn khân păng răm maak tâm ngih gâp mbơh sơm. Mpa khân păng gŭch jêh ri mpa khân păng ƀư brah gâp mra dơn ta klơ nơng gâp; yor lah ngih gâp bu mra rnha ngih mbơh sơm prăp ma lĕ rngôch phung ndŭl mpôl bunuyh.”$b$,false),
('bunong-vn','ISA',56,8,null,$b$Kôranh Brah Yêhôva, nơm tâm rƀŭn phung Israel bu mprơh jêh, lah: “Gâp mra tâm rƀŭn phung êng ma păng, êng đah phung rƀŭn jêh.”$b$,false),
('bunong-vn','ISA',56,9,null,$b$Ơ lĕ rngôch mpa bri, Ơ lĕ rngôch mpa tâm krŏng, văch sa hom!$b$,true),
('bunong-vn','ISA',56,10,null,$b$Phung bunuyh Yêhôva đă gak jêng chieh măt, lĕ rngôch khân păng mâu geh nau gĭt rbăng ôh, lĕ rngôch khân păng jêng so mlo, mâu dơi groh ôh; khân păng kuen, khân păng mbơi, khân păng rŏng bêch.$b$,false),
('bunong-vn','ISA',56,11,null,$b$Lĕ rngôch so nây hay, mâu blau hơm ôh. Khân păng jêng phung rmăk biăp mâu geh nau gĭt rbăng ôh; lĕ rngôch khân păng plơ̆ tĭng trong khân păng nơm, ăp nơm ŭch sa kao ma păng nơm da dê.$b$,false),
('bunong-vn','ISA',56,12,null,$b$Khân păng lah: “Văch hom, he joi hom dak ndrănh, jêh ri he mra nhêt ndrănh mhe, jêh ri ôi taơ mra jêng tâm ban ma nar aơ, du nar toyh rlau keh.”$b$,false),
('bunong-vn','ISA',57,1,null,$b$Nơm sŏng rai yot, jêh ri mâu geh nơm chrê ôh ma nau nây; bu nhŭp rdu lơi jêh phung klach yơk ma Brah Ndu, jêh ri mâu geh nơm gĭt rbăng ôh. Yor lah bu nhŭp rdu lơi jêh nơm sŏng srăng lor tât nau mhĭk.$b$,true),
('bunong-vn','ISA',57,2,null,$b$Phung hăn tâm nau sŏng srăng lăp tâm nau đăp mpăn, khân păng saơ nau rlu dôl bêch tâm nau khĭt.$b$,false),
('bunong-vn','ISA',57,3,null,$b$“Ƀiă lah, bi khân may, Ơ phung kon bu klâu, bu ur n'hŭm, phung kon nơm văng tĭr jêh ri bu ur ka n'hong văch dăch hom.$b$,true),
('bunong-vn','ISA',57,4,null,$b$Ma mbu nâm khân may mưch? Ma mbu khân may ha huy trôm mbung jêh ri lĭl mpiăt? Mâu di hĕ khân may jêng phung kon rlau nau vay, kon sau phung mƀruh?$b$,false),
('bunong-vn','ISA',57,5,null,$b$Khân may hư̆ hưn ma nau kơnh ƀơ̆ ta nklang tơm si têrêbin, tâm dâng lĕ rngôch tơm si ndrêh, phung tâm nkhĭt phung kon khân may tâm rlŭng, tâm dâng trôm đang lŭ.$b$,false),
('bunong-vn','ISA',57,6,null,$b$Ta nklang lŭ klêr tâm rlŭng jêng ntŭk prăp ma khân may; ndơ nây, ndơ nây yơh kô̆ prăp ma khân. Ma ndơ nây yơh khân may nkhŭt jêh ndơ nhhơr nhêt, khân may nhhơr jêh ndơ nhhơr piăng let muy. Nau nây mra rthi nuih n'hâm gâp ji nuih lĕ?$b$,true),
('bunong-vn','ISA',57,7,null,$b$Ta yôk prêh ngăn khân may nkra jêh sưng bêch khân may, ta nây lĕ khân may hao ŭch nhhơr ndơ ƀư brah.$b$,false),
('bunong-vn','ISA',57,8,null,$b$Khân may dơm ndơ khân may kah gĭt pa kơi mpông pêr jêh ri n'gâng, yor lah khân may cha lơi jêh gâp jêh ri pơk tâm mpơl sưng bêch khân may, khân may hao bêch jêh, khân may ƀư ăn păng toyh, jêh ri khân may ƀư nau tâm rnglăp đah phung nây. Khân may rŏng sưng bêch nây, khân may uănh jêh nau rhôk khân păng.$b$,false),
('bunong-vn','ISA',57,9,null,$b$Khân may hăn ma hađăch ma dak play ôlivơ, jêh ri ƀư bĭk dak si ƀâu kah khân may, khân may prơh njuăl phung oh mon ktang khân may ta ntŭk ngai, jêh ri prơh njuăl khân păng ma Ƀon Phung Khĭt.$b$,false),
('bunong-vn','ISA',57,10,null,$b$Khân may rgănh jêh yor trong khân may ngai, ƀiă lah khân may mâu lah ôh, ‘Nau nây dơm dam! Khân may geh nau ƀư mhe đŏng nuih n'hâm ktang khân may, yor nây khân may mâu khĭt huăr ôh.$b$,true),
('bunong-vn','ISA',57,11,null,$b$Ma mbu khân may rnam jêh ri klach kŏ tât khân may mƀruh ma gâp, jêh ri may kah gĭt ma gâp, mâu lĕ mĭn ma gâp? Mâu di hĕ yor lah jŏ jêh gâp gŭ rklăk, pô ri khân may mâu klach ma gâp ôh?$b$,true),
('bunong-vn','ISA',57,12,null,$b$Gâp mra mbơh nau sŏng srăng khân may jêh ri kan khân may ƀư, jêng mâu khlay da dê ma khân may.$b$,false),
('bunong-vn','ISA',57,13,null,$b$Tơ lah khân may nter nau kơl, ăn phung rup brah khân may tâm rklaih khân may. Sial mra khôm rdu lĕ khân păng, du tơ̆ khôm mra sŏk rdu lơi khân păng. Ƀiă lah mbu nâm du krap tâm gâp mra sŏk pha bri, jêh ri mra dơn yôk kloh ueh gâp.$b$,false),
('bunong-vn','ISA',57,14,null,$b$Bu mra lah; “Nkra hom, nkra hom, rli ăn lâng hom trong! Sŏk hom lŭ ƀư chêh bơh trong phung ƀon lan gâp.”$b$,true),
('bunong-vn','ISA',57,15,null,$b$Yor lah pô aơ nơm klơ lơn lah, nơm gŭ n'ho ro, amoh păng jêng Kloh Ueh: “Gâp gŭ tâm ntŭk ta klơ jêh ri kloh ueh, jêh ri tâm ban lĕ ndrel ma nơm geh nuih n'hâm rngot ma nau tih jêh ri blau tông bâr, gay plơ̆ ăn rêh nuih n'hâm phung tông bâr, gay ăn rêh tay nuih n'hâm nơm rngot ma nau tih.$b$,true),
('bunong-vn','ISA',57,16,null,$b$Yor lah gâp mâu mra tâm rlăch mro ôh, mâu lĕ mra nuih mro; yor lah huêng bunuyh mra rdja nuih n'hâm ta năp gâp, jêh ri n'hâm phung gâp rhăk jêh mra lôch.$b$,false),
('bunong-vn','ISA',57,17,null,$b$Yor nau păng kue đah nau kơnh gâp ji nuih, jêh ri gâp dong jêh păng, gâp pôn jêh muh măt gâp ma nau ji nuih; ƀiă lah păng ăt plơ̆ tĭng nâm trong nuih n'hâm păng.$b$,true),
('bunong-vn','ISA',57,18,null,$b$Gâp saơ jêh trong păng, ƀiă lah gâp mra ƀư bah păng. Gâp mra njŭn păng jêh ri mplơ̆ ma păng nau tâm bonh, gâp mra ăn phung nhĭm nhhiăng blau tâm rnê ma gâp.”$b$,false),
('bunong-vn','ISA',57,19,null,$b$Yêhôva lah: “Nau đăp mpăn, nau đăp mpăn ma nơm gŭ ngai jêh ri ma phung gŭ dăch; jêh ri gâp mra ƀư bah khân păng.”$b$,false),
('bunong-vn','ISA',57,20,null,$b$Ƀiă lah phung ƀai jêng tâm ban ma dak mƀŭt rbuh, mâu blau rlu ôh, jêh ri dak păng ƀư rchoh bŏk jêh ri neh ƀơ̆ .$b$,true),
('bunong-vn','ISA',57,21,null,$b$Brah Ndu gâp lah: “Mâu geh nau đăp mpăn ôh ma phung ƀai!”$b$,false),
('bunong-vn','ISA',58,1,null,$b$“Nter huy hom, lơi dŭt ôh; nter huy tâm ban ma du mlâm nŭng. Mbơh hom ma phung ƀon lan gâp nau khân păng rlau nau vay, jêh ri ma ngih Yakôb nau tih khân păng.$b$,true),
('bunong-vn','ISA',58,2,null,$b$Ƀiă lah ăp nar khân păng joi gâp, jêh ri jan lah maak gĭt năl trong gâp, tâm ban ma khân păng jêng du ndŭl mpôl ƀư nau sŏng srăng jêh ri mâu cha lơi ôh nau Brah Ndu khân păng ntăm. Khân păng dăn ma gâp nau phat dôih sŏng, khân păng jan lah maak Brah Ndu hăn dăch khân păng.$b$,false),
('bunong-vn','ISA',58,3,null,$b$Khân păng ôp: ‘Moh khlay hên ver sông sa tơ lah may mâu saơ ôh? Moh khlay hên ƀư jêr hên nơm tơ lah may mâu chrê ma nau nây ôh?” Ƀiă lah nar khân may ver sông sa khân may joi nau ƀư maak ma khân may nơm. Jêh ri tŭn jot lĕ rngôch phung pah kan ma khân may.$b$,false),
('bunong-vn','ISA',58,4,null,$b$Aơ, khân may ât sông sa gay ma tâm djrel jêh ri tâm rlăch, jêh ri ŭch tŭr ma ti nau ƀai. Nau khân may ât sông sa tâm ban ma nar aơ mâu mra ăn ôh bu tăng bâr khân may ta klơ.$b$,true),
('bunong-vn','ISA',58,5,null,$b$Di lĕ nau ât sông sa pô aơ gâp săch jêh, knŏng prăng du nar bunuyh tâm tông bâr păng nơm? Di lĕ knŏng kŭnh bôk tâm ban ma du mlâm rpho jêh ri gŭ ta klơ ƀau jêh ri buh? Khân may mra rnha nau nây jêng ât sông sa jêh ri du nar ƀư maak ma Yêhôva lĕ?$b$,true),
('bunong-vn','ISA',58,6,null,$b$“Mâu di hĕ pô aơ jêng nau ât sông sa gâp săch; doh lơi rse rvăk nau ƀai, rơih lơi brăt kât mâng mbăk, ăn jêng kon me phung bu tŭn jot, jêh ri kêch lơi ăp mâng mbăk?$b$,true),
('bunong-vn','ISA',58,7,null,$b$Mâu di hĕ jêng nau tâm pă ndơ sông sa khân may ma nơm ji ngot, jêh ri njŭn leo tâm ngih khân may phung o-ach mâu geh ngih ôh, tơ lah khân may saơ nơm rhôk, sâm soh an păng, jêh ri lơi dun ma ndŭl mpôl khân may ôh?$b$,true),
('bunong-vn','ISA',58,8,null,$b$Rnôk nây nau maak khân may mra nchrat tâm ban ma ƀhit rvi, jêh ri nau ƀư bah khân may mra tât gơnh; nau sŏng srăng khân may mra hăn ta năp khân may, jêh ri nau chrêk rmah Yêhôva mra gak pa kơi khân may.$b$,true),
('bunong-vn','ISA',58,9,null,$b$Rnôk nây khân may mra kuăl, jêh ri Yêhôva mra plơ̆ lah: Khân may mra nter vơh vơl jêh ri păng mra lah: Aơ, ta aơ gâp. “Tơ lah sŏk lơi mâng mbăk bơh tâm nklang khân may, nđâp nau nchŏng nglao ti jêh ri nau ngơi ƀai,$b$,false),
('bunong-vn','ISA',58,10,null,$b$tơ lah khân may ăn ndơ sông sa may nơm ma nơm ji ngot tơ lah khân may n'hơm bunuyh rêh ni, rnôk nây nau ang khân may mra luh tâm nau ngo, jêh ri nau ngo khân may mra jêng tâm ban ma nar nklang bôk.$b$,false),
('bunong-vn','ISA',58,11,null,$b$Yêhôva mra njŭn khân may ƀa ƀơ; păng mra têk leo khân may tâm ntŭk duh nar nđat, jêh ri păng mra ăn nting khân may jêng ktang. Khân may mra jêng tâm ban ma du lôk đang trau bu djrah dak, tâm ban ma du ntu dak mâu blau suăt ôh.$b$,false),
('bunong-vn','ISA',58,12,null,$b$Bu mra rdâk tay ntŭk ơm khân may rai jêh, khân may mra nkra tay mbon ơm bơh âk rnôk rlau jêh; bu mra rnha khân may phung trôm pêr rhuh phung nkra tay trong geh ngih bu gŭ.$b$,false),
('bunong-vn','ISA',58,13,null,$b$“Tơ lah khân may rlu pah kan tâm nar Saƀat, mâu ƀư ôh nau khân may ŭch tâm nar kloh ueh gâp, jêh ri rnha nar Saƀat jêng nau maak jêh ri nar kloh ueh Yêhôva khư bu yơk; jêh ri tơ lah khân may yơk ma nar Saƀat mâu ƀư ôh tĭng nâm trong khân may nơm, mâu joi ôh nau ƀư maak ma khân may nơm, mâu lĕ ngơi nau dơm dam,$b$,true),
('bunong-vn','ISA',58,14,null,$b$Rnôk nây khân may mra gŭ nau maak tâm Yêhôva jêh ri gâp mra ăn khân may hao ta ntŭk prêh lơn tâm bri neh; gâp mra siăm khân may ma drăp ndơn Y-Yakôb che khân may” yor lah trôm mbung Yêhôva ngơi jêh nau nây.$b$,false),
('bunong-vn','ISA',59,1,null,$b$Aơ, ti Yêhôva mâu jêng gleh ôh dĭng păng mâu dơi tâm rklaih, tôr păng mâu lĕ sêt lơi dĭng păng mâu dơi tăng.$b$,true),
('bunong-vn','ISA',59,2,null,$b$Ƀiă lah nau kue khân may yơh tâm nkhah khân may đah Brah Ndu khân may. Nau tih khân may yơh pôn lơi muh măt păng bơh khân may dĭng păng mâu tăng ôh.$b$,true),
('bunong-vn','ISA',59,3,null,$b$Yor lah ti khân may ƀơ̆ jêh ma mham, jêh ri nglao ti khân may ma nau kue; mbung khân may ngơi nau mƀruh, mpiăt khân may ngơi nau ƀai.$b$,false),
('bunong-vn','ISA',59,4,null,$b$Mâu geh du huê phong ma nau sŏng ôh. Khân păng rnơm ma nau ngơi dơm dam jêh ri ngơi mƀruh. Khân păng mĭn ma nau mhĭk jêh ri ƀư nau kue.$b$,false),
('bunong-vn','ISA',59,5,null,$b$Khân păng gŭ păn tăp bêh ŭnh, jêh ri khân păng tanh ek ndrŭng. Mbu nâm sa play khân păng khĭt yơh, jêh ri tơ lah bu nchah lơi du mlâm, du mlâm bêh rmâng lah.$b$,true),
('bunong-vn','ISA',59,6,null,$b$Ek ndrŭng khân păng mâu mra jêng bok ao ôh; mâu lĕ khân păng dơi nkŭm ma kan khân păng nơm. Kan khân păng jêng kan nau kue, jêh ri kan ti khân păng ƀư jêng nau ƀai.$b$,false),
('bunong-vn','ISA',59,7,null,$b$Jâng khân păng nchuăt ŭch ƀư nau mhĭk, jêh ri khân păng ngăch ƀư pling mham mâu tih ôh. Nau mĭn khân păng jêng kue, nau ƀư roh jêh ri nau ƀư rai gŭ ta trong khân păng.$b$,false),
('bunong-vn','ISA',59,8,null,$b$Khân păng mâu gĭt năl trong nau đăp mpăn ôh, jêh ri mâu geh nau sŏng ôh tâm trong khân păng. Khân păng ăn trong khân păng jêng kue, mbu nâm hăn ta nây mâu gĭt nau đăp mpăn ôh.$b$,false),
('bunong-vn','ISA',59,9,null,$b$Yor nây nau sŏng gŭ ngai đah hên, jêh ri nau sŏng srăng mâu dơi ban hên ôh. Hên joi nau ang, ƀiă lah aơ, nau ngo tât; hên joi nau rmah, ƀiă lah hên hăn tâm nau ngo.$b$,true),
('bunong-vn','ISA',59,10,null,$b$Hên joi rvơ mpir, tâm ban ma bunuyh chieh măt, hên joi rvơ tâm ban ma phung mâu geh măt ôh. Hên chêh dôl ang nar nklang bôk tâm ban ma suâr vâr păr vik; ta nklang phung geh nau ngăch prăl, hên jêng tâm ban ma phung khĭt.$b$,true),
('bunong-vn','ISA',59,11,null,$b$Lĕ rngôch phung hên ngrông tâm ban ma kau, hên nđêng rngot tâm ban ma plŭk. Hên joi nau sŏng, ƀiă lah mâu geh ôh; hên joi nau tâm rklaih, ƀiă lah păng gŭ ngai đah hên.$b$,false),
('bunong-vn','ISA',59,12,null,$b$Yor lah nau hên rlau nau vay jêng bĭk ta năp may, jêh ri nau tih hên mbơh tâm rdâng đah hên. Nau hên rlau nau vay tâm mpơl jêh, jêh ri hên gĭt năl nau kue hên:$b$,true),
('bunong-vn','ISA',59,13,null,$b$Rlau nau vay, dun Yêhôva, plơ̆ sĭt mâu tĭng ndô̆ ôh Brah Ndu hên, ngơi ma nau tŭn jot jêh ri nau tâm rdâng, mĭn jêh ri hă ngơi nau mƀruh bơh nuih n'hâm.$b$,false),
('bunong-vn','ISA',59,14,null,$b$Nau sŏng rŭch du jêh, jêh ri nau sŏng srăng gŭ ngai; yor lah nau na nê̆ prah jêh tâm trong sâng, jêh ri nau sŏng srăng mâu dơi lăp ôh.$b$,true),
('bunong-vn','ISA',59,15,null,$b$Hên pưt nau na nê̆, jêh ri mbu nâm dơi đah nau mhĭk njêng păng nơm jêng ndơ bu pit. Yêhôva saơ nau nây, jêh ri nau nây ƀư rngot păng yor mâu geh nau sŏng ôh.$b$,false),
('bunong-vn','ISA',59,16,null,$b$Păng saơ mâu geh du huê bunuyh ôh, păng hih rhâl yor mâu geh nơm kơl koh dŏng an. Rnôk nây ma ti păng nơm păng ƀư tât nau tâm rklaih, jêh ri nau sŏng srăng păng nơm rdâng păng.$b$,false),
('bunong-vn','ISA',59,17,null,$b$Păng soh nau sŏng srăng tâm ban ma du blah ao loih, jêh ri păng ndô đon nau tâm rklaih păng soh nau har plơng bôk jêng bok aơ, jêh ri păng nkŭm păng nơm ma nau ŭch ngăn jêng du blah ao mbâl.$b$,false),
('bunong-vn','ISA',59,18,null,$b$Păng mra mplơ̆ ma ăp nơm tĭng nâm kan păng, nau ji nuih ma phung rdâng đah păng, nau nkhôm mhĭk ma phung rlăng păng. Păng mra mplơ̆ nau tâm ban ma lĕ rngôch bri kô dak mƀŭt.$b$,false),
('bunong-vn','ISA',59,19,null,$b$Pô ri khân păng mra klach ma amoh Yêhôva ntơm bơh pa dâng, jêh ri yơk ma nau chrêk rmah păng bơh ntŭk nar luh; yor lah păng mra văch tâm ban ma n'hor dak jru, Sial Yêhôva khôm mpruh.$b$,true),
('bunong-vn','ISA',59,20,null,$b$“Jêh ri Nơm Tâm Chuai mra văch ma ƀon Siôn ma phung tâm ngih Yakôb, plơ̆ du bơh nau tih.” Yêhôva lah.$b$,false),
('bunong-vn','ISA',59,21,null,$b$Bi gâp be, aơ jêng nau gâp tâm rnglăp đah khân păng, Yêhôva lah: “Brah Huêng Ueh gâp nơm gŭ ta klơ khân may, jêh ri nau gâp ngơi gâp dơm jêh tâm trôm mbung khân may, nđâp ma tă bơh trôm mbung phung kon khân may, mâu lĕ luh tă bơh trôm mbung phung sau khân may, ntơm bơh aƀaơ tât ta n'ho ro.” Yêhôva lah.$b$,true),
('bunong-vn','ISA',60,1,null,$b$“Dâk hom, sol hom, yor lah nau ang may tât jêh, jêh ri nau chrêk rmah Yêhôva luh jêh ta klơ may.$b$,true),
('bunong-vn','ISA',60,2,null,$b$Yor lah aơ, nau ngo nkŭm neh ntu, jêh ri nau ngo mbâl nkŭm phung ƀon lan; ƀiă lah Yêhôva dâk ta klơ may, jêh ri bu mra saơ nau chrêk rmah păng ta klơ may.$b$,false),
('bunong-vn','ISA',60,3,null,$b$Phung ndŭl mpôl bunuyh mra văch ma nau ang may, jêh ri phung hađăch ma nau lơp rmah nau may dâk.$b$,false),
('bunong-vn','ISA',60,4,null,$b$“N'gơr hom măt may jêh ri uănh ndăch jŭm: Lĕ rngôch khân păng tâm rƀŭn ndrel văch ma may. Phung kon bu klâu văch tă bơh ngai, jêh ri bu chông ta ti phung kon bu ur may$b$,true),
('bunong-vn','ISA',60,5,null,$b$Rnôk nây mra saơ jêh ri sol ang, jêh ri nuih n'hâm may mra mpât jêh ri răm maak; Yor lah ndơ rmeh ler bơh dak mƀŭt bu mra njŭn ma may, drăp ndơ phung ndŭl mpôl bunuyh mra văch ma may.$b$,false),
('bunong-vn','ISA',60,6,null,$b$Âk seh samô mra nkŭm bri neh may, âk kon seh samô bơh bri Madian jêh ri bri Êpha: Lĕ rngôch seh sa mô bơh Sêba mra văch. Khân păng mra rdeng leo mah jêh ri ndơ ƀâu kah, jêh ri mra mbơh nau tâm rnê ma Yêhôva.$b$,false),
('bunong-vn','ISA',60,7,null,$b$Lĕ rngôch biăp be bơh bri Kêdar mra tâm rƀŭn ma may, lĕ rngôch biăp nkuăng bơh bri Nêbalôt mra pah kan ma may. Gâp mra dơn bu nhhơr khân păng ta nơng may.$b$,false),
('bunong-vn','ISA',60,8,null,$b$“Mbu phung aơ mpăr tâm ban ma ndâr tŭk, tâm ban ma plŭk ma rsuăn khân păng?$b$,false),
('bunong-vn','ISA',60,9,null,$b$Na nê̆ phung ƀon lan bri kơh dak mƀŭt mra kâp gâp, jêh ri kumpăn bơh bri Tarsir văch lor, gay njŭn phung kon bu klâu may bơh ngai, ndrel ma prăk jêh ri mah khân păng, prăp ma amoh Yêhôva Brah Ndu may, jêh ri prăp ma Nơm Kloh Ueh Israel, yor lah păng ăn jêh nau chrêk rmah ma may,$b$,false),
('bunong-vn','ISA',60,10,null,$b$“Phung bu năch mra rdâk tay pêr may, jêh ri phung hađăch khân păng mra pah kan ma may. Nđâp tơ lah gâp dong jêh may dôl gâp ji nuih, ƀiă lah dôl yô̆ ma may gâp mra ƀư ueh ma may.$b$,false),
('bunong-vn','ISA',60,11,null,$b$Mpông pêr may ăt mra pơk mro, măng nar bu mâu mra chăng khân păng ôh, gay ma bu dơi njŭn ma may drăp ndơ phung ndŭl mpôl bunuyh, jêh ri phung hađăch khân păng mra têk leo ma nau dơi.$b$,false),
('bunong-vn','ISA',60,12,null,$b$Yor lah ndŭl mpôl jêh ri ƀon bri hađăch mâu ŭch kan ma may ôh mra rai lôch, bu mra ƀư rai lơi phung ndŭl mpôl nây lĕ ƀhiau.$b$,false),
('bunong-vn','ISA',60,13,null,$b$Nau chrêk rmah bri Liban mra văch ma may, tơm si chiprơ, si n'ho jêh ri tơm si buis, ŭch ƀư ueh jrô kloh ueh gâp; jêh ri gâp mra ăn chrêk rmah ntŭk gâp chrong jâng.$b$,false),
('bunong-vn','ISA',60,14,null,$b$Phung kon bu klâu phung tŭn jot may mra văch chon mbah ma may; jêh ri lĕ rngôch phung tâm rmot ma may mra păn ta năp jâng may. Khân păng mra rnha may Ƀon Yêhôva. Ƀon Siôn ma Nơm Kloh Ueh Israel.$b$,false),
('bunong-vn','ISA',60,15,null,$b$“Nđâp tơ lah bu cha lơi jêh ri tâm rmot jêh ma may, pô ri mâu geh nơm rgăn ta nklang may ôh, gâp mra ăn may jêng nkrơ̆ hôm mro, nau răm maak tâm lĕ rngôch rnôk.$b$,true),
('bunong-vn','ISA',60,16,null,$b$May mra nhêt dak toh lĕ rngôch phung ndŭl mpôl bunuyh; nđâp ma lĕ rngôch phung hađăch mra ăn may pu. Rnôk nây may mra gĭt gâp yơh, Yêhôva jêng Nơm Tâm Rklaih may. Nơm tâm chuai may, Nơm Brah phung Yakôb.$b$,true),
('bunong-vn','ISA',60,17,null,$b$Ntrok kông gâp mra njŭn mah, ntrok loih gâp mra njŭn prăk, ntrok si geh kông, jêh ri ntrok lŭ geh loih. Gâp mra ăn nau đăp mpăn mpeh ma kôranh toyh may, jêh ri nau sŏng srăng may jêng kôranh chiă uănh may.$b$,false),
('bunong-vn','ISA',60,18,null,$b$Bu mâu mra tăng đŏng ôh nau mhĭk ƀai tâm bri may, mâu lĕ geh nau roh jêh ri nau rai tâm n'har bri neh may. May mra rnha pêr may Nau Tâm Rklaih, jêh ri mpông pêr may Nau Tâm Rnê.$b$,true),
('bunong-vn','ISA',60,19,null,$b$Nar mâu hôm jêng nau ang ma may dôl nar ôh, khay mâu mra ăn nau ang lĕ păng nchrat ma may dôl măng; ƀiă lah Yêhôva mra jêng nau ang may n'ho ro. Brah Ndu may mra jêng nau chrêk rmah may.$b$,false),
('bunong-vn','ISA',60,20,null,$b$Nar may mâu mra nhâp đŏng ôh, khay may mâu mra du lĕ; Yor lah Yêhôva mra jêng nau ang may n'ho ro, jêh ri nar may rngot klâng mra lôch.$b$,true),
('bunong-vn','ISA',60,21,null,$b$Rnôk nây lĕ rngôch phung ƀon lan may mra jêng sŏng da dê; khân păng mra dơn bri ƀa ƀơ n'ho ro. Khân păng mra jêng nkeh gâp tăm jêh, kan ti gâp ƀư jêh, gay ma gâp geh nau chrêk rmah.$b$,false),
('bunong-vn','ISA',60,22,null,$b$Nơm djê̆ lơn mra jêng du phung ƀon lan, jêh ri nơm jê̆ lơn mra jêng du mpôl băl bunuyh ktang. Gâp jêng Yêhôva, gâp mra ăn tât gơnh nau nây tâm rnôk păng.$b$,true),
('bunong-vn','ISA',61,1,null,$b$Brah Huêng Ueh Kôranh Brah Yêhôva gŭ ta gâp, yor lah Yêhôva tŏ jêh dak ƀâu kah ta gâp gay mbơh nau mhe mhan ueh ma phung o-ach. Păng mprơh jêh gâp văch gay ƀư bah phung geh nuih n'hâm rngot, gay mbơh nau jêng kon me ma phung bu nă, jêh ri nau pơk ngih bu nă ma phung bu krŭng;$b$,true),
('bunong-vn','ISA',61,2,null,$b$Gay mbơh năm Yêhôva yô̆, jêh ri nar Brah Ndu he plơng bôk, gay ma bonh leng lĕ rngôch phung rngot klâng,$b$,false),
('bunong-vn','ISA',61,3,null,$b$gay ăn ma phung rngot klâng tâm ƀon Siôn gay ăn ma khân păng rvang kao ntrok ŭnh buh, dak ƀâu kah nau răm ntrok nau rngot klâng, bok ao nau tâm rnê ntrok nau rdja nuih. Bu mra rnha khân păng tơm si nau sŏng srăng ndơ Yêhôva tăm jêh, gay ma Yêhôva dơi geh nau chrêk rmah.$b$,false),
('bunong-vn','ISA',61,4,null,$b$Khân păng mra plơ̆ rdâk ntŭk ơm rai jêh, khân păng mra rdâk đŏng ndơ ơm jêng rngot jêh. Khân păng mra nkra tay lĕ rngôch ƀon rai jêh, jêng rngol âk năm jêh.$b$,true),
('bunong-vn','ISA',61,5,null,$b$Phung bu năch mra gŭ ta nây siăm biăp be khân may, phung bu năch mra jêng phung kai chiă tơm play kriăk ƀâu khân may.$b$,true),
('bunong-vn','ISA',61,6,null,$b$Ƀiă lah bu mra rnha khân may phung kôranh ƀư brah Yêhôva, bu rnha khân may jêng phung oh mon Brah Ndu he. Khân may mra sa nau ndrŏng phung ndŭl mpôl bunuyh, jêh ri khân may mra tâm rnê ma khân may nơm ma nau ndrŏng khân păng.$b$,false),
('bunong-vn','ISA',61,7,null,$b$Ntrok nau bêk khân may, khân may mra geh bar tăp nau ndrŏng, Ntrok nau bu mâu yơk ôh, khân may mra răm maak ma kô̆ tâm pă ma khân may. Yor nây khân may mra geh bar tăp âk lơn ndơ nây tâm bri khân may, jêh ri nau răm maak khân may mra gŭ n'ho ro.$b$,false),
('bunong-vn','ISA',61,8,null,$b$“Yor lah gâp yơh, Yêhôva rŏng ma nau sŏng; gâp tâm rmot ma nau ntŭng jêh ri nau kue. Đah nau răp jăp gâp mra ăn nau nkhôm ma khân păng, jêh ri gâp mra ƀư đah khân păng nau tâm rnglăp n'ho ro$b$,false),
('bunong-vn','ISA',61,9,null,$b$Bu mra gĭt năl phung kon sau khân may ta nklang phung ndŭl mpôl bunuyh, jêh ri phung sau se khân păng ta nklang phung ƀon lan. Lĕ rngôch phung saơ khân păng mra gĭt rbăng khân păng jêng du phung ƀon lan Yêhôva mât ton jêh.”$b$,false),
('bunong-vn','ISA',61,10,null,$b$Gâp mra hâk răm ngăn tâm Yêhôva; huêng gâp mra bêng ma nau răm maak tâm Brah Ndu gâp. Yor lah păng sâm soh jêh gâp ma bok ao nau tâm klaih, păng nkŭm jêh gâp ma ao jâr nau sŏng srăng, tâm ban ma bu klâu gŭ ur ndrăp păng nơm ma rvang kao, tâm ban ma du huê bu ur gŭ sai ndrăp păng nơm ma lŭ khlay păng.$b$,true),
('bunong-vn','ISA',61,11,null,$b$Yor lah tâm ban ma neh ăn đeh găr si, jêh ri tâm ban ma đang trau ƀư hon ntil bu srih jêh tâm păng, tâm ban pô nây lĕ Kôranh Brah Yêhôva mra ăn tât nau sŏng srăng jêh ri nau tâm rnê ta năp lĕ rngôch ndŭl mpôl bunuyh.$b$,true),
('bunong-vn','ISA',62,1,null,$b$Yor ƀon Siôn gâp mâu mra gŭ rklăk ôh, yor ƀon Yêrusalem gâp mâu mra rlu ôh, kŏ nau sŏng srăng păng nchrat tâm ban ma nau ang, jêh ri nau tâm rklaih păng tâm ban ma ŭnh rdo hôm hit.$b$,true),
('bunong-vn','ISA',62,2,null,$b$Phung ndŭl mpôl bunuyh mra saơ nau sŏng srăng păng, jêh ri lĕ rngôch phung hađăch mra saơ nau chrêk rmah păng; jêh ri bu mra rnha may ma amoh mhe, Yêhôva nơm mra ăn.$b$,true),
('bunong-vn','ISA',62,3,null,$b$May mra jêng du mlâm đon nau ueh tâm ti Yêhôva, jêh ri đon hađăch tâm ti Brah Ndu may.$b$,false),
('bunong-vn','ISA',62,4,null,$b$Bu mâu mra rnha ôh may Nơm Bu cha lơi, jêh ri bu mâu hôm rnha ôh bri may rngol; ƀiă lah bu mra rnha may Gâp Maak Đah Păng, jêh ri bu mra rnha neh Tâm Kol Jêh; yor lah Yêhôva mra geh nau maak đah may, jêh ri neh may mra geh nau tâm kol.$b$,false),
('bunong-vn','ISA',62,5,null,$b$Yor lah tâm ban ma du huê bu klâu mom ndăm gŭ ur du huê bu ur druh, tâm ban pô nây lĕ phung kon bu klâu may mra gŭ ndrel may; jêh ri tâm ban ma bu klâu gŭ ur răm maak yor bu ur păng gŭ, tâm ban pô nây lĕ Brah Ndu may mra răm maak yor may.$b$,false),
('bunong-vn','ISA',62,6,null,$b$Ơ ƀon Yêrusalem, gâp dơm jêh phung gak ta klơ pêr may, măng nar khân păng mâu mra gŭ rklăk ôh. Ơ khân may phung ăn Yêhôva kah gĭt, lơi gŭ rlu ôh,$b$,true),
('bunong-vn','ISA',62,7,null,$b$jêh ri lơi ăn Yêhôva rlu ôh, kŏ păng ƀư nâp ƀon Yêrusalem, jêh ri njêng păng ƀon bu tâm rnê tâm neh ntu.$b$,false),
('bunong-vn','ISA',62,8,null,$b$Yêhôva hŏ nchŏng jêh đah ti pa ma păng, jêh ri ma ti nau brah păng: “Gâp mâu mra ăn ôh ba may jêng ndơ sông sa ma phung rlăng đah may, jêh ri phung bu năch mâu mra nhêt ôh dak play kriăk ƀâu may; play bơh kan may.$b$,true),
('bunong-vn','ISA',62,9,null,$b$Ƀiă lah phung prăp bun jêh ba mra sông păng, jêh ri tâm rnê ma Yêhôva, jêh ri phung pĕ jêh play kriăk ƀâu mra nhêt dak păng, tâm nkual ngih jrô kloh ueh gâp.”$b$,false),
('bunong-vn','ISA',62,10,null,$b$Rgăn hom, rgăn hom mpông pêr! Nkra hom trong ma phung ƀon lan ƀư lâng hom, ƀư lâng hom trong toyh sŏk rdu lơi lŭ. N'hao hom bok pla ma phung ndŭl mpôl bunuyh.$b$,true),
('bunong-vn','ISA',62,11,null,$b$Aơ, Yêhôva mbơh jêh tât ta dŭt neh: “Lah hom ma kon bu ur ƀon Siôn, Aơ păng djôt leo nau nkhôm, jêh ri ndơ ăn ma bu.’ ”$b$,false),
('bunong-vn','ISA',62,12,null,$b$Bu mra rnha khân păng Phung Ƀon Lan Kloh Ueh. Phung Yêhôva Tâm Chuai Jêh; jêh ri bu mra rnha may Nơm Mra Joi. Ƀon Mâu Hôm Gŭ Rngol Ôh.$b$,false),
('bunong-vn','ISA',63,1,null,$b$Mbu moh aơ văch tă bơh bri Êđôm, bơh ƀon Bôsra, soh bok ao chăng, bok ao chrêk rmah, hăn pa năp ma nau ktang brah păng? “Gâp nơm yơh, nơm mbơh nau sŏng srăng, nơm brah dơi tâm rklaih.”$b$,true),
('bunong-vn','ISA',63,2,null,$b$Mâm ƀư bok ao may chăng, jêng tâm ban ma bok ao nơm jot play kriăk ƀâu tâm drŏng?$b$,false),
('bunong-vn','ISA',63,3,null,$b$“Gâp jot jêh drŏng dak play kriăk ƀâu êng gâp, jêh ri mâu geh du huê phung ƀon lan ndrel ma gâp ô. Gâp jot jêh khân păng ma nau gâp ji nuih, gâp ntrâm jêh khân păng ma nau gâp ji nuih mham khân păng mprănh ta bok ao gâp jêh ri gâp kĭn lêt jêh lĕ rngôch bok ao gâp.$b$,false),
('bunong-vn','ISA',63,4,null,$b$Yor lah nuih n'hâm gâp mĭn ma nar plơng bôk jêh ri năm gâp tâm chuai tât jêh.$b$,false),
('bunong-vn','ISA',63,5,null,$b$Gâp uănh, ƀiă lah mâu geh nơm kơl ôh; gâp hih rhâl lah mâu geh nơm rdâng ôh. Pô ri ti gâp nơm ƀư tât nau tâm rklaih, jêh ri nau gâp ji nuih rdâng gâp.$b$,false),
('bunong-vn','ISA',63,6,null,$b$Gâp jot jêh phung ndŭl mpôl bunuyh ma nau gâp nuih, gâp ăn khân păng nhŭl ndrănh jêh ma nau gâp ji nuih, jêh ri gâp ƀư pling jêh mham khân păng ta neh.”$b$,false),
('bunong-vn','ISA',63,7,null,$b$Gâp mra nkoch bri nau Yêhôva jăp, nau tâm rnê ma Yêhôva, tĭng nâm lĕ nau Yêhôva ƀư ăn jêh ma he, jêh ri nau păng ƀư ueh âk ma ngih Israel, nau păng ăn jêh ma khân păng tĭng nâm nau păng yô̆ jêh ri ƀư răp jăp rmeh ler.$b$,true),
('bunong-vn','ISA',63,8,null,$b$Yor lah păng lah jêh: “Na nê̆ khân păng jêng ƀon lan gâp, phung kon mâu mra ƀư ma nau mƀruh ôh”; pô ri păng jêng jêh Nơm Tâm Rklaih khân păng.$b$,false),
('bunong-vn','ISA',63,9,null,$b$Tâm lĕ rngôch nau rêh ni khân păng, păng geh nau rêh ni lĕ, jêh ri oh mon ueh păng gŭ ndrel tâm rklaih jêh khân păng. Ma nau păng rŏng jêh ri yô̆ păng tâm chuai jêh khân păng; păng chông leo khân păng lĕ rngôch nar rnôk kăl e.$b$,false),
('bunong-vn','ISA',63,10,null,$b$Ƀiă lah khân păng tâm rdâng jêh ri ƀư rngot jêh Brah Huêng Ueh păng; Yor nây păng plơ̆ jêng rlăng khân păng, păng nơm tâm lơh đah khân păng.$b$,true),
('bunong-vn','ISA',63,11,null,$b$Jêh ri phung ƀon lan păng kah gĭt ma nar rnôk kăl e, jêh ri ma Y-Môis oh mon păng. Ntă nơm ăn khân păng luh hao bơh dak mƀŭt ndrel ma rmăk biăp ma phung biăp păng? Ntă nơm dơm jêh Brah Huêng Kloh Ueh păng ta nklang khân păng,$b$,false),
('bunong-vn','ISA',63,12,null,$b$nơm tâm mpơl nau ktang chrêk rmah păng pa ma Y-Môis, nơm nkhah đah ta năp khân păng gay ma njêng păng nơm amoh lư n'gar n'ho ro,$b$,false),
('bunong-vn','ISA',63,13,null,$b$nơm leo khân păng rgăn ta ntŭk jru? Tâm ban ma du mlâm seh tâm ndrêch rdah, khân păng mâu nchêh ôh.$b$,false),
('bunong-vn','ISA',63,14,null,$b$Tâm ban ma ndrôk jŭr hăn ta rlŭng. Brah Huêng Ueh Yêhôva ăn ma khân păng nau rlu. Pô ri may njŭn jêh phung ƀon lan may gay njêng ma may nơm amoh chrêk rmah.$b$,false),
('bunong-vn','ISA',63,15,null,$b$Kŭnh mêt bơh trôk jêh ri uănh bơh ntŭk may gŭ kloh ueh jêh ri chrêk rmah mbah nau duh nđơr may jêh ri kan nau brah may? May mâu hôm tâm mpơl ma hên ôh nau may rŏng jêh ri yô̆.$b$,true),
('bunong-vn','ISA',63,16,null,$b$Yor lah may jêng mbơ̆ hên, nđâp tơ lah Y-Abraham mâu gĭt năl ôh hên, jêh ri Y-Israel mâu lĕ gĭt năl hên; Ơ Yêhôva, may yơh jêng mbơ̆ hên, bơh rnôk n'ho ro nây may jêng Nơm Tâm Chuai hên.$b$,false),
('bunong-vn','ISA',63,17,null,$b$Ơ Yêhôva, mâm ƀư may ăn hên nkhah du bơh trong may, jêh ri ƀư dăng nuih n'hâm hên kŏ hên mâu hôm klach yơk ma may ôh? Plơ̆ sĭt hom yor phung oh mon may, phung ndŭl mpôl drăp ndơn may.$b$,false),
('bunong-vn','ISA',63,18,null,$b$Phung ƀon lan kloh ueh may geh jêh jrô kloh ueh may ƀât lât, ƀiă lah aƀaơ aơ phung rlăng đah hên jot jêh jrô nây.$b$,false),
('bunong-vn','ISA',63,19,null,$b$Hên jêng jêh tâm ban ma phung may mâu mâp chiă uănh ôh, tâm ban ma phung bu mâu rnha ma amoh may ôh.$b$,false),
('bunong-vn','ISA',64,1,null,$b$Ơ, ŭch ngăn may khêk trôk jêh ri jŭr văch, gay ma yôk sâr n'gơ ta năp may!$b$,true),
('bunong-vn','ISA',64,2,null,$b$Tâm ban ma ŭnh sa n'gĭng kro, tâm ban ma ŭnh ƀư khuh dak, gay ăn phung rlăng đah may gĭt amoh may, gay ma phung ndŭl mpôl bunuyh râm sâr ta năp may!$b$,false),
('bunong-vn','ISA',64,3,null,$b$Tơ lah may ƀư ndơ tâm nhhu hên mâu yŏng mĭn ôh, may jŭr, jêh ri yôk n'gơ ta năp may.$b$,false),
('bunong-vn','ISA',64,4,null,$b$Bơh rnôk ơm bu mâu mâp tăng ôh, măt mâu mâp saơ lĕ Brah Ndu pa dih may, nơm pah kan kơl phung gŭ kâp păng.$b$,true),
('bunong-vn','ISA',64,5,null,$b$May tâm mâp đah nơm pah kan sŏng srăng ma nau răm, phung kah gĭt ma may tâm trong may. Aơ, may ji nuih jêh yor lah hên ƀư tih jêh; jŏ jêh hên ƀư tih, jêh ri hên mra geh nau tâm rklaih lĕ?$b$,false),
('bunong-vn','ISA',64,6,null,$b$Lĕ rngôch hên jêng jêh tâm ban ma nơm mâu kloh, jêh ri lĕ kan sŏng srăng hên jêng tâm ban ma bok ao ƀơ̆ jêh. Lĕ rngôch phung hên klêu tâm ban ma n'ha si, jêh ri nau kue hên khôm rdu hên tâm ban ma sial.$b$,true),
('bunong-vn','ISA',64,7,null,$b$Mâu geh nơm kuăl mbơh sơm ma amoh may ôh, mâu lĕ geh nơm kah rngăl bêch gay tâm rnglăp đah may; yor lah pôn jêh muh măt may ma hên, jêh ri may jao jêh hên ma nau brah nau kue hên.$b$,true),
('bunong-vn','ISA',64,8,null,$b$Ƀiă lah, Ơ Yêhôva, may ăt jêng mbơ̆ hên, hên jêng neh bŏk, jêh ri may jêng nơm mon hên; lĕ rngôch hên jêng kan ti may ƀư.$b$,true),
('bunong-vn','ISA',64,9,null,$b$Ơ Yêhôva, lơi nuih rlau keh ôh, gâp kah gĭt n'ho ro, mâu lĕ kah gĭt n'ho ro ma nau kue hên. Ơ, uănh hom, lĕ rngôch hên jêng phung ƀon lan may.$b$,true),
('bunong-vn','ISA',64,10,null,$b$Lĕ rngôch ƀon kloh ueh may nkhơng jêng bri rdah, nđâp yôk Siôn lĕ nkhơng jêng bri dah, ƀon Yêrusalem jêng rngol.$b$,false),
('bunong-vn','ISA',64,11,null,$b$Ngih brah hên kloh ueh jêh ri ueh, ntŭk phung che hên tâm rnê ma may, bu su jêh ma ŭnh, lĕ rngôch ndơ khlay hên jêng ndơ rai jêh$b$,false),
('bunong-vn','ISA',64,12,null,$b$Ơ Yêhôva, may mra dun lĕ mâu kơl ôh yor lĕ nau nây? May mra gŭ rklăk jêh ri ƀư ni hên rlau keh lĕ?$b$,false),
('bunong-vn','ISA',65,1,null,$b$“Gâp tâm mpơl gâp nơm ma phung mâu mâp joi ôp ma gâp ôh; phung mâu mâp joi gâp ôh saơ jêh gâp. Gâp lah; Aơ, ta aơ gâp, aơ ta aơ gâp! Ma du ndŭl mpôl bunuyh mâu mâp mbơh sơm ma amoh gâp ôh.$b$,true),
('bunong-vn','ISA',65,2,null,$b$Gâp yơr jêh ti gâp lĕ nar ma du phung ƀon lan vay tâm rdâng, phung hăn tâm trong mâu ueh, tĭng nâm nau mĭn khân păng nơm;$b$,true),
('bunong-vn','ISA',65,3,null,$b$du phung ƀon lan tâm nsônh nau ji nuih ma gâp mro, nđâp ta năp muh măt gâp khân păng ƀư brah tâm đang trau jêh ri gŭch mpa ƀâu kah ta klơ neh uk;$b$,false),
('bunong-vn','ISA',65,4,null,$b$Phung gŭ tâm ntŭk môch jêh ri gŭ lĕ măng tâm ntŭk ndâp; phung sa puăch (puăch) păng, jêh ri prăp tâm ngan khân păng mâu kloh.$b$,false),
('bunong-vn','ISA',65,5,null,$b$Khân păng lah: “Trơn hom may, lơi văch dăch gâp ôh yor lah gâp jêng kloh ueh lơn ma may! Phung nây jêng tâm ban ma nhhŭk ŭnh tâm trôm jrô gâp, tâm ban ma ŭnh hit nar măng.$b$,false),
('bunong-vn','ISA',65,6,null,$b$Aơ, geh nau chih jêh ta năp gâp: Gâp mâu mra gŭ rklăk ôh, ƀiă lah gâp mra phat dôih nanê̆; gâp mra phat dôih ƀư ma khân păng yor nau kue khân păng,$b$,false),
('bunong-vn','ISA',65,7,null,$b$jêh ri nau kue phung che khân păng ndrel.” Yêhôva lah: “Yor lah khân păng gŭch jêh mpa ƀâu kah ta klơ yôk, jêh ri suai rak gâp ta klơ dor, gâp mra veh nau phat dôih ăn ăp khân păng tĭng nâm kan khân păng ƀư jêh kăl e.”$b$,false),
('bunong-vn','ISA',65,8,null,$b$Pô aơ Yêhôva lah: “Tâm ban ma geh dak play kriăk ƀâu tâm rkŭm, jêh ri bu lah, Lơi ƀư rai păng ôh yor lah ăt geh nau ueh uĭn tâm păng! Tâm ban pô nây lĕ gâp mra ƀư yor phung oh mon gâp, jêh ri mâu ƀư rai lĕ rngôch khân păng ôh.$b$,true),
('bunong-vn','ISA',65,9,null,$b$Gâp mra ăn Y-Yakôb geh phung kon sau, jêh ri ăn phung Yuđa geh phung ndơn drăp yôk gâp; phung gâp săch mra ndơn bri nây, jêh ri phung oh mon gâp mra gŭ ta nây.$b$,false),
('bunong-vn','ISA',65,10,null,$b$Neh lâng Sarôn mra jêng ntŭk ndrêch gơ̆ ma biăp, jêh ri Rlŭng Akôr mra jêng ntŭk ma ndrôk kuen, ntŭk prăp ma phung ƀon lan gâp joi jêh gâp.$b$,false),
('bunong-vn','ISA',65,11,null,$b$Ƀiă lah bi ma khân may phung lơi jêh Yêhôva, phung chuêl yôk kloh ueh gâp, phung nkra sưng sông sa ma Gat, jêh ri mbêng kachok ma dak play kriăk ƀâu tâm lŭk jêh ma “Meni.”$b$,true),
('bunong-vn','ISA',65,12,null,$b$Gâp mra gay ŭch prăp khân may ma đao, jêh ri lĕ rngôch khân may mra chon mon dơn nau bu nkhĭt; yor lah khân may mâu hôm plơ̆ lah ôh tơ lah gâp kuăl, tơ lah gâp ngơi khân may mâu tăng đŏng, ƀiă lah khân may ƀư jêh nau mhĭk ta năp măt gâp, jêh ri khân may săch jêh ŭch ƀư nau mâu maak ma gâp ôh.”$b$,false),
('bunong-vn','ISA',65,13,null,$b$Yor nây Kôranh Brah Yêhôva lah pô aơ: “Aơ, phung oh mon gâp mra sông sa, ƀiă lah khân may mra ji ngot; aơ phung oh mon gâp mra nhêt ƀiă lah khân may mra ji hir; aơ phung oh mon gâp mra maak, ƀiă lah khân may mra geh nau bêk.$b$,true),
('bunong-vn','ISA',65,14,null,$b$Aơ, phung oh mon gâp mra mprơ yor nuih n'hâm maak, ƀiă lah khân may mra nter vơl yor ji nuih n'hâm, jêh ri mra nhĭm nhhiăng yor nau rngot jâk.$b$,false),
('bunong-vn','ISA',65,15,null,$b$Phung gâp săch jêh mra dŏng amoh khân may gay rtăp rak ma bu, jêh ri Kôranh Brah Yêhôva mra nkhĭt khân may; ƀiă lah păng mra rnha phung oh mon ma amoh êng.$b$,false),
('bunong-vn','ISA',65,16,null,$b$Jêh ri mbu mra mât ton tâm bri mra mât ton đah amoh Brah Ndu ma nau răp jăp; jêh ri mbu nâm sân săk tâm bri neh mra ton săk đah Brah Ndu ma nau răp jăp. Yor lah gâp mra chuêl nau uh ah kăl e, jêh ri gâp mâu hôm uănh ma nau nây đŏng ôh.$b$,false),
('bunong-vn','ISA',65,17,null,$b$Yor lah aơ, gâp rhăk trôk mhe jêh ri neh ntu mhe. Bu mâu hôm kah gĭt ôh ma ndơ kăl e, mâu lĕ hôm bu mĭn ma ndơ nây.$b$,true),
('bunong-vn','ISA',65,18,null,$b$Ƀiă lah hâk răm hom khân may ƀa ƀơ yor ndơ gâp rhăk; Yor lah aơ, gâp rhăk ƀon Yêrusalem jêng nau hâk, jêh ri phung ƀon lan păng jêng nau maak.$b$,true),
('bunong-vn','ISA',65,19,null,$b$Gâp mra hâk yor ƀon Yêrusalem, jêh ri maak yor phung ƀon lan gâp; ta nây bu mâu mra tăng ôh bâr nhĭm jêh ri bâr nter nđêng.$b$,false),
('bunong-vn','ISA',65,20,null,$b$Mâu mra geh ôh ta nây nglay săk gŭ rêh knŏng ƀât lât, mâu geh ôh phung bu ranh gŭ rêh jŏk, yor lah tơ lah kon se khĭt geh du rhiăng năm, ăt kơp jêng mom; jêh ri nơm mâu gŭ rêh tât du rhiăng năm bu mra kơp jêng nơm geh nau rtăp rak.$b$,false),
('bunong-vn','ISA',65,21,null,$b$Khân păng mra rdâk ngih jêh ri gŭ ta nây; khân păng mra tăm đang play kriăk ƀâu jêh ri sa play păng.$b$,true),
('bunong-vn','ISA',65,22,null,$b$Khân păng mâu mra rdâk ngih jêh ri nơm êng gŭ ôh; khân păng mâu mra tăm play kriăk ƀâu jêh ri nơm êng sa play păng ôh. Yor lah nar phung ƀon lan gâp gŭ rêh mra jêng tâm ban ma nar tơm si gŭ rêh, jêh ri phung gâp săch mra hâk maak jŏ ma kan ti khân păng ƀư.$b$,false),
('bunong-vn','ISA',65,23,null,$b$Khân păng mâu mra pah kan dơn dam ôh, mâu lĕ khân păng mra deh ma nau ƀư rai; Yor lah khân păng mra jêng kon ma phung geh jêh nau Yêhôva mât ton nđâp ndrel phung sau se khân păng.$b$,false),
('bunong-vn','ISA',65,24,null,$b$Lor ma khân păng kuăl mbơh sơm, gâp mra plơ̆ lah; dôl khân păng ăt hôm ngơi, gâp mra tăng.$b$,false),
('bunong-vn','ISA',65,25,null,$b$So bri jêh ri kon biăp mra sa gơ̆ ndrel, yau mŭr mra sa rhe nâm bu ndrôk, ƀiă lah mra sa ndruyh neh khân păng mâu mra ƀư ji, mâu lĕ ƀư rai ta lĕ yôk kloh ueh gâp.” Yêhôva lah.$b$,false),
('bunong-vn','ISA',66,1,null,$b$Pô aơ nau Yêhôva lah: “Trôk jêng sưng hađăch gâp, jêh ri neh ntu jêng rnơl gâp chrong jâng, pô ri mbah ngih khân may ŭch rdâk ma gâp? Jêh ri ta ntŭk gâp mra rlu?$b$,true),
('bunong-vn','ISA',66,2,null,$b$Yor lah lĕ rngôch ndơ nây ti gâp da dê njêng, pô ri lĕ rngôch ndơ nây jêng jêh.” Yêhôva lah: “Ƀiă lah ma bunuyh tâm ban pô nây gâp mra uănh: Nơm tông bâr jêh ri rngot ma nau tih, jêh ri râm sâr ma nau gâp ngơi.$b$,false),
('bunong-vn','ISA',66,3,null,$b$Mbu nâm nkhĭt du mlâm ndrôk jêng tâm ban ma nơm nkhĭt du huê bunuyh, mbu nâm ƀư brah ma kon biăp, jêng tâm ban ma nơm nkêch lơi trô ko so; mbu nâm nhhơr ndơ piăng let muy jêng tâm ban ma nơm nhhơr mham sŭr; mbu nâm gŭch mpa ƀâu kah jêng tâm ban ma nơm mbah yơk ma rup brah. Phung nây joi jêh trong khân păng nơm, jêh ri huêng khân păng maak tâm nau khân păng ƀư nau gâp tâm rmot.$b$,true),
('bunong-vn','ISA',66,4,null,$b$Gâp tâm ban lĕ mra săch nau ƀư rêh ni ma khân păng, jêh ri ăn tât ma khân păng nau khân păng klach. Yor lah tơ lah gâp kuăl, mâu geh nơm plơ̆ lah ôh, tơ lah gâp ngơi, khân păng mâu tăng ôh, ƀiă lah khân păng ƀư jêh nau mhĭk ta năp măt gâp, jêh ri săch nau mâu maak ma gâp ôh.”$b$,true),
('bunong-vn','ISA',66,5,null,$b$Iăt hom nau Yêhôva ngơi, Ơ khân may phung râm sâr ma nau păng ngơi. “Phung oh nâu khân may tâm rmot ma khân may jêh ri nsot khân may, yor nây gâp lah jêh: “Ăn Yêhôva geh nau chrêk rmah, gay ma hên dơi saơ nau răm maak. Ƀiă lah khân păng yơh bu mra ƀư bêk.$b$,true),
('bunong-vn','ISA',66,6,null,$b$Iăt hom geh bâr drơu drơu bơh ƀon toyh, geh nter bơh ngih brah Yuđa! Păng jêng bâr Yêhôva mplơ̆ nau phat dôih ma phung rlăng đah păng!$b$,false),
('bunong-vn','ISA',66,7,null,$b$“Lor ma păng ji deh, păng tât ndŭl jêh; lor ma nau ji tât ma păng, păng deh jêh ma du huê kon bu klâu.$b$,true),
('bunong-vn','ISA',66,8,null,$b$Mbu mâp tăng jêh tâm ban pô nây? Mbu mâp saơ ndơ tâm ban pô nây? Bu mra nti njêng lĕ du rplay bri tâm du nar? Bu mra rdâk njêng lĕ du ndŭl mpôl bunuyh ƀât lât dơm? Yor lah tơ lah ƀon Siôn ntơm bêch veng ŭnh, păng deh ma phung kon păng.$b$,false),
('bunong-vn','ISA',66,9,null,$b$Gâp mra ăn mông deh tât jêh ri mâu ăn deh lĕ?” Yêhôva lah: “Gâp nơm ăn bu dơi deh pô ri gâp mra buay deh lĕ?” Brah Ndu khân may lah,$b$,false),
('bunong-vn','ISA',66,10,null,$b$“Hâk hom ndrel ma ƀon Yêrusalem jêh ri maak ndrel ma păng. Ơ lĕ rngôch phung khân may rngot klâng ma păng.$b$,false),
('bunong-vn','ISA',66,11,null,$b$Yor lah khân may mra pu jêh ri hơm ma dak toh nau păng tâm bonh; khân may mra pu âk jêh ri maak ma dak toh păng rmeh ler.”$b$,false),
('bunong-vn','ISA',66,12,null,$b$Yor lah pô aơ nau Yêhôva lah: “Aơ, gâp mra tâm n'hao nau đăp mpăn ma păng tâm ban ma dak krong hoch, jêh ri nau chrêk rmah ma phung ndŭl mpôl bunuyh tâm ban ma dak n'hor ler kơh; jêh ri khân may mra pu, bu mra chông khân may jêh ri rbot ta kômâk$b$,true),
('bunong-vn','ISA',66,13,null,$b$Tâm ban me bonh leng kon păng, tâm ban pô nây lĕ gâp mra bonh leng khân may; khân may mra geh nau tâm bonh leng tâm ƀon Yêrusalem.$b$,false),
('bunong-vn','ISA',66,14,null,$b$Khân may mra saơ nau nây, jêh ri nuih n'hâm khân may mra răm maak, nting khân may mra hon nse tâm ban gơ̆ ; jêh ri bu mra gĭt ti Yêhôva gŭ ndrel ma phung oh mon păng ƀiă lah nau păng ji nuih gŭ ƀư ma phung rlăng đah păng.$b$,false),
('bunong-vn','ISA',66,15,null,$b$Yor lah aơ, Yêhôva mra văch tâm ŭnh, jêh ri lĕ rngôch ndeh seh păng mra jêng tâm ban ma sial rpuh; gay ma tâm mpơl nau păng ji nuih ktang, jêh ri nau păng nduyh ma mpiăt ŭnh.$b$,true),
('bunong-vn','ISA',66,16,null,$b$Yor lah ma ŭnh jêh ri ma đao yơh Yêhôva mra phat dôih lĕ rngôch bunuyh; jêh ri phung Yêhôva nkhĭt mra jêng âk.$b$,false),
('bunong-vn','ISA',66,17,null,$b$“Phung prăp an khân păng nơm jêh ri ƀư kloh khân păng nơm gay lăp tâm đang trau tĭng ndô̆ du huê ta nklang phung gŭ sa puăch (puăch) sŭr, ndơ Brah Ndu tâm rmot, jêh ri đe, mra rai yot ndrel,” Yêhôva lah:$b$,false),
('bunong-vn','ISA',66,18,null,$b$“Yor lah gâp gĭt năl kan păng jêh ri nau khân păng mĭn. Gâp mra văch tâm rƀŭn lĕ rngôch phung ndŭl mpôl bunuyh jêh ri lĕ rngôch nau ngơi; khân păng mra văch jêh ri saơ nau chrêk rmah gâp.$b$,false),
('bunong-vn','ISA',66,19,null,$b$Gâp mra du ndơ tâm mbên ta nklang khân păng. Jêh ri bơh phung khân păng ăt hôm gâp mra njuăl hăn ƀa ƀă ma phung ndŭl mpôl bunuyh, ma phung Tarsis, phung Pul, phung Lut blau pănh na, phung Tubal jêh ri phung Javan, phung bri kơh dak mƀŭt ngai, phung mâu mâp tăng lư ôh nau lư n'găr gâp, mâu lĕ mâp saơ nau chrêk rmah gâp; jêh ri khân păng mra mbơh nau chrêk rmah gâp ta nklang phung ndŭl mpôl bunuyh.$b$,false),
('bunong-vn','ISA',66,20,null,$b$Khân păng mra njŭn lĕ rngôch phung oh nâu khân may bơh lĕ rngôch ndŭl mpôl bunuyh jêng mpa nhhơr ma Yêhôva, ncho seh, bêch tâm njao, ncho seh bri jêh ri seh samô, hăn ta yôk kloh ueh mbơh sơm. “Tâm ban ma phung Israel djôt leo mpa nhhơr piăng let muy tâm du mlâm yăng kloh ma ngih Yêhôva.$b$,true),
('bunong-vn','ISA',66,21,null,$b$Ƀa ƀă phung khân păng njŭn nây gâp mra sŏk ăn jêng Kôranh ƀư brah jêh ri phung Lêvi: ” Yêhôva lah:$b$,false),
('bunong-vn','ISA',66,22,null,$b$“Yor lah tâm ban ma trôk mhe jêh ri neh ntu mhe gâp mra njêng mra ăt hôm ta năp gâp.” Yêhôva lah: “Tâm ban pô nây lĕ phung kon sau khân may jêh ri khân may mra ăt hôm e.$b$,false),
('bunong-vn','ISA',66,23,null,$b$Bơh ăp khay mhe ma khay mhe, jêh ri bơh ăp nar Saƀat ma Saƀat mhe lĕ rngôch bunuyh mra văch gay yơk mbah ta năp gâp.” Yêhôva lah:$b$,true),
('bunong-vn','ISA',66,24,null,$b$Khân păng mra luh hăn uănh ta phan phung bunuyh tâm rdâng jêh đah gâp; Yor lah rhai khân păng mâu mra khĭt ôh, ŭnh khân păng mâu mra ngôm lĕ, jêh ri lĕ rngôch bunuyh mra tâm rmot ma khân păng.”$b$,false);
