insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','JER',1,1,null,$b$Nau Y-Yêrêmi, kon bu klâu Y-Hilkia, ngơi. Păng jêng du huê tâm phung kôranh ƀư brah gŭ ta ƀon Anathôt, n'gor Benjamin.$b$,true),
('bunong-vn','JER',1,2,null,$b$Geh nau Yêhôva ngơi ma păng tâm rô̆ Y-Jôsia, kon bu klâu Y-Amôn, hađăch Yuđa, năm rơh jât ma pe rô̆ hađăch nây.$b$,false),
('bunong-vn','JER',1,3,null,$b$Yêhôva plơ̆ ngơi ma păng rô̆ Y-Jêhôjakim, kon bu klâu Y-Jôsia, jêng hađăch Yuđa, tât lôch năm rơh jât ma nguay du rô̆ hađăch Sêdêkia, kon bu klâu Y-Jôsia, hađăch Yuđa, jêng năm bu nhŭp ƀon Yêrusalem ƀư bu nă tâm khay prăm.$b$,false),
('bunong-vn','JER',1,4,null,$b$Yêhôva ngơi ma gâp, lah: “Ê lor rhăk njêng may tâm trôm ndŭl me, gâp hŏ năl jêh may;$b$,true),
('bunong-vn','JER',1,5,null,$b$jêh ri ê lor may deh, gâp hŏ prăp jêh may ma du ntil kan; gâp njêng may jêng kôranh nơm mbơh lor ma lĕ rngôch ntil mpôl bunuyh.$b$,false),
('bunong-vn','JER',1,6,null,$b$Pô ri gâp lah: “Ơ Kôranh Brah Ndu ơi! Aơ gâp mâu blau ngơi ueh ôh, yor lah gâp jêng du huê ndăm.”$b$,true),
('bunong-vn','JER',1,7,null,$b$Ƀiă lah Yêhôva lah ma gâp: “Lơi ta lah ôh: ‘Gâp jêng du huê ndăm.’ Yor lah may mra hăn ma lĕ rngôch phung gâp mra prơh may hăn jêh ri may mra ngơi moh nau gâp ntăm ma may.”$b$,false),
('bunong-vn','JER',1,8,null,$b$Yêhôva lah: “Lơi ta klach ma khân păng ôh, yor lah gâp gŭ ndrel ma may gay tâm rklaih may.”$b$,true),
('bunong-vn','JER',1,9,null,$b$Pô ri, Yêhôva nto ti bi mbung gâp, jêh ri Yêhôva lah đŏng ma gâp pô aơ; “Aơ, gâp dơm jêh nau gâp ngơi tâm mbung may.$b$,true),
('bunong-vn','JER',1,10,null,$b$Uănh hom, nar aơ gâp njêng may tâm lĕ ntil mpôl, tâm lĕ bri dak, gay may rôk, mâu lah nklưh lơi mâu lah ƀư rai, mâu lah ntrŭnh, mâu lah ndâk, mâu lah tăm,”$b$,true),
('bunong-vn','JER',1,11,null,$b$Yêhôva ngơi đŏng ma gâp, lah: “Hơi Y-Yêrêmi, moh ndơ may saơ?” Gâp lah: “Gâp saơ du mlâm n'gĭng tơm play nhăr.”$b$,true),
('bunong-vn','JER',1,12,null,$b$Yêhôva lah ma gâp: “Di jêh may saơ, yor lah gâp gŭ njrăng, nau gâp ngơi gay ƀư ăn n'hêl nanê̆.$b$,false),
('bunong-vn','JER',1,13,null,$b$Yêhôva ngơi đŏng ma gâp tơ̆ bar pô aơ: “Moh ndơ may saơ?” Gâp lah: “Gâp saơ du mlâm glah dak duh tă mpeh klơ dor păng bruh.$b$,true),
('bunong-vn','JER',1,14,null,$b$Yêhôva lah: “Nây jêng nau rêh ni bơh bri klơ dor mra tât ma lĕ rngôch phung gŭ tâm bri aơ.$b$,false),
('bunong-vn','JER',1,15,null,$b$Pô ri, gâp mra kuăl lĕ mpôl băl bunuyh bri klơ dor.” Yêhôva lah: “Khân păng mra văch, jêh ri ăp nơm mra ndâk sưng hađăch păng ta ntŭk lăp mpông pêr ƀon Yêrusalem, gay nchueng lơh ma lĕ rngôch mpêr văr jŭm ƀon Yêrusalem, jêh ri lơh lĕ rngôch mpêr ƀon tâm n'gor Yuđa.$b$,false),
('bunong-vn','JER',1,16,null,$b$Gâp mra ngơi nau phat dôih ma khân păng, yor nau mhĭk khân păng ƀư, khân păng cha lơi jêh gâp. Khân păng su ndơ ƀâu kah ăn ma phung brah êng, jêh ri mbah yơk ma kan ti khân păng nơm ƀư.$b$,false),
('bunong-vn','JER',1,17,null,$b$Pô ri, vân hom rse bŭt may; dâk hom jêh ri lah ma khân păng lĕ rngôch nau gâp ntăm jêh ma may. Lơi klach ôh ta năp khân păng, klach lah gâp nhhu nkrit may ta năp khân păng.$b$,false),
('bunong-vn','JER',1,18,null,$b$Aơ, nau aơ, gâp njêng may du play ƀon nâp, du mlâm n'gâng loih, jêh ri mpêr kông, tâm rdâng đah lĕ bri neh aơ, đah phung hađăch Yuđa, phung kôranh khân păng, phung kôranh ƀư brah khân păng, jêh ri phung ƀon lan.$b$,false),
('bunong-vn','JER',1,19,null,$b$Khân păng mra tâm lơh đah may; ƀiă lah khân păng mâu mra dơi đah may ôh; yor lah gâp gŭ ndrel ma may gay tâm rklaih may.” Yêhôva lah pô nây.$b$,true),
('bunong-vn','JER',2,1,null,$b$Yêhôva ngơi ma gâp, lah:$b$,true),
('bunong-vn','JER',2,2,null,$b$“Hăn hom, mbơh ta trôm tôr phung ƀon Yêhôva, pô aơ Yêhôva lah: “Gâp kah gĭt ma nau may gŭ răp jăp dôl may ndăm. Ma nau may rŏng nâm bu du huê bu ur ntơm gŭ sai. Ma nau may tĭng ndô̆ gâp jêh tâm bri rdah tâm bri bu mâu mâp srih ntil ôh.$b$,false),
('bunong-vn','JER',2,3,null,$b$Phung Israel jêng kloh ueh ma Yêhôva; jêng play dak bôk bơh kan Păng. Ma mbu nơm sa play nây jêng tih jêh, nau mhĭk tât ma păng.” Yêhôva lah pô nây.$b$,true),
('bunong-vn','JER',2,4,null,$b$Iăt hom nau Yêhôva ngơi, Ơ ngih Y-Yakôp, ndrel ma lĕ rngôch ngih Israel, iăt hom nau Yêhôva!$b$,true),
('bunong-vn','JER',2,5,null,$b$Yêhôva lah pô aơ: “Moh nau tih phung che khân may saơ tâm gâp, tât khân păng du ngai bơh gâp, ŭch tĭng ndô̆ nau dơm dam, jêh ri jêng hĕ bunuyh dơm dam?$b$,false),
('bunong-vn','JER',2,6,null,$b$Khân păng mâu lah ôh: “Ta ntŭk Yêhôva gŭ? Nây jêng Nơm hŏ njŭn he du luh tă bơh n'gor bri Êjipt, hŏ têk leo he lăp găn bri mbâng, tâm ntŭk rdah lŭ rdeng leng rdăp, tâm neh choih kroh đang jêh ri ngo klĕng njŭn nau khĭt, jêng bri neh mâu geh du huê bunuyh mâp prot găn ôh, jêh ri mâu geh bunuyh gŭ.”$b$,true),
('bunong-vn','JER',2,7,null,$b$Gâp njŭn leo khân may tât du ntŭk bri neh geh ndơ sông sa rmeh ler, neh geh âk play đo, gay ăn khân may sa play păng jêh ri nau ueh păng. Ƀiă lah, dôl gŭ ta nây, khân may ƀư ƀơ̆ ƀơch neh gâp, jêh ri njêng ma bri krâm ndrâm ngât gâp jêng bri bu tâm rmot.$b$,false),
('bunong-vn','JER',2,8,null,$b$Phung kôranh ƀư brah mâu lah ôh: ‘Ta ntŭk Yêhôva gŭ?’ Phung nti nau vay mâu gĭt lĕ gâp. Phung kôranh chiă uănh ƀư tih đah gâp. Phung kôranh mbơh lor mbơh amoh brah Baal, jêh ri tĭng ndô̆ nau mâu khlay ôh.$b$,true),
('bunong-vn','JER',2,9,null,$b$Yêhôva lah: “Yor nau nây gâp mra ăt hôm tâm dun đah khân may, tât ma kon sau jêh ri tât ma se săn khân may đŏng.$b$,true),
('bunong-vn','JER',2,10,null,$b$Hăn găn hom ma kơh dak mƀŭt Kittim gay uănh! Mâu lah prơh bu hăn ma phung Kêdar, jêh ri uănh n'hêl; uănh hom gĭt lah geh ngăn pô nây.$b$,true),
('bunong-vn','JER',2,11,null,$b$Mâp geh lĕ du bri dak êng tâm rgâl brah păng, nđâp lah brah nây mâu jêng brah ngăn ôh? Ƀiă lah phung ƀon lan gâp tâm rgâl jêh nau chrêk rmah khân păng sŏk ndơ dơm dam!$b$,false),
('bunong-vn','JER',2,12,null,$b$Ơ trôk, hih rhâl hom ma nau nây, klach krit hom, jêh ri rngot rvê hom.” Nau Yêhôva lah.$b$,false),
('bunong-vn','JER',2,13,null,$b$Yor lah phung ƀon lan gâp ƀư jêh bar ntil nau mhĭk: Khân păng hŏ cha lơi gâp jêh, nơm jêng tu dak nau rêh, jêh ri kuyh êng ntu dak ma khân păng nơm, ntu dak lĕ đang, jêh ri luh srip mâu hôm kơn dak.$b$,false),
('bunong-vn','JER',2,14,null,$b$Phung Israel jêng dĭk lĕ, mâu lah oh mon bu deh tâm vâl kôranh păng? Pô ri mâm ƀư păng hŏ jao ăn ma nau ntŭng?$b$,false),
('bunong-vn','JER',2,15,null,$b$Âk phung yau mŭr ngrông, ŭch ƀư ma khân păng, ngrông dŭt huy ngăn, gay ƀư ma bri neh khân păng jêng bri nsoih. Lĕ rngôch ƀon păng lĕ bu su ma ŭnh, mâu geh bunuyh gŭ ôh.$b$,false),
('bunong-vn','JER',2,16,null,$b$Rlau ma nĕ, kon sau ƀon Memphis jêh ri Tahpanhês poih jêh sŏk khân may.$b$,false),
('bunong-vn','JER',2,17,null,$b$Lĕ ntil nau nây mâu di hĕ nau tât ma khân may yor nau cha lơi Yêhôva Brah Ndu khân may dôl păng njŭn khân may rŏ trong?$b$,true),
('bunong-vn','JER',2,18,null,$b$Jêh ri aƀaơ, moh kan khlay ma khân may dĭng khân may hăn ma bri Êjipt ŭch nhêt dak krong Nil? Mâu lah moh kan khlay ăn ma khân may dôl hăn n'gŏ trong hăn ma bri Asiri ŭch nhêt dak krong toyh Ơphrat?$b$,true),
('bunong-vn','JER',2,19,null,$b$Nau tih mhĭk khân may mra phat nkra khân may nơm, nau khân may tâm rdâng mra nduyh khân may, gay ăn khân may gĭt jêh ri saơ nau khân may cha lơi Yêhôva Brah Ndu khân may, jêh ri mâu geh nau klach yơk ma gâp ôh, nây jêng du nau djơh mhĭk jêh ri rngot, kôranh Brah, Brah Ndu ma phung ta han lah pô nây.$b$,true),
('bunong-vn','JER',2,20,null,$b$“Kăl e ri gâp hŏ kêch jêh mâng mbăk khân may, jêh ri ƀư klah jêh rse rvăk kât khân may; jêh ri khân may lah pô aơ: ‘Hên mâu hôm pah kan đŏng ôh; yor ma ntŭk prêh ăp gôl yôk, tâm dâng ăp tơm si lung ndrêh, khân may hŏ kŭnh bôk, khân may ƀư nâm bu bu ur văng tir.$b$,true),
('bunong-vn','JER',2,21,null,$b$Gâp hŏ tăm jêh khân may nâm bu tơm play kriăk ƀâu ueh uĭn, bơh ntil găr ueh da dê; pô ri mbah tă luh khân may tâm rgâl jêng nkhơng tơm play mhĭk nâm bu tơm play kriăk ƀâu bri ăn ma gâp?$b$,false),
('bunong-vn','JER',2,22,null,$b$Nđâp tơ lah khân may sŏk dak sôda jêh ri dŏng âk ntil saƀu gay rao săk jăn kđôi lĕ, ntŭk ƀơ̆ nau tih khân may ăt hôm ta năp gâp.” Kôranh Brah, Brah Ndu lah:$b$,false),
('bunong-vn','JER',2,23,null,$b$“Mâm khân may dơi lah: ‘Gâp mâu geh ƀơ̆ ƀơch; gâp mâu prot hăn tĭng ndô̆ rup brah Baal ôh? Uănh hom trong khân may tâm ntŭk rlŭng; gĭt saơ ro moh ntil nau khân may hŏ ƀư jêh, nâm bu seh samô phơr jêh ri nsong mblêng blă blơ̆ ,$b$,false),
('bunong-vn','JER',2,24,null,$b$nâm bu seh bri me, mơng bên gŭ tâm ntŭk bri rdah, chŭm n'hơp tâm gar me nkuăng! Mbu nâm dơi king dôl mông păng ŭch tâm gar (tâm jơng)? Mâu khlay ôh nkuăng joi me nây; nkuăng mra tâm mâp đah me tơ lah di khay ma me nây.$b$,false),
('bunong-vn','JER',2,25,null,$b$Njrăng hom jâng may lơi ta jâng dơm, lơi ta ăn trô ko may ji hir! Ƀiă lah khân may lah: ‘Mâu hôm geh nau kâp gâp ôh, yor lah gâp rŏng jêh ma phung bunăch, jêh ri gâp mra tĭng ndô̆ khân păng.’$b$,false),
('bunong-vn','JER',2,26,null,$b$“Nâm bu du huê bunuyh ntŭng geh bu nhŭp, prêng hâu ngăn ngên, pô nây lĕ phung Israel, phung hađăch, ƀă phung kôranh ƀư brah, ƀă phung kôranh khân păng, phung kôranh nơm mbơh lor, ăt geh nau prêng tâm ban pô nây lĕ.$b$,false),
('bunong-vn','JER',2,27,null,$b$Khân păng lah ma tơm si pô aơ: ‘May jêng mbơ̆ gâp; jêh ri lah ma glo lŭ: May hŏ deh ăn gâp. Yor lah khân păng hŏ ndôn kơi ma gâp jêh, mâu ŭch rle năp uănh gâp ôh. Ƀiă lah dôl nôk khân păng uh ah khân păng lah: ‘Dâk hom, sâm rklaih hên ƀă!’$b$,false),
('bunong-vn','JER',2,28,null,$b$Pô ri, ta ntŭk phung brah khân may gŭ, phung brah nây ƀơh khân may hŏ ƀư jêh ma khân may nơm? Tơ lah phung brah nây dơi rklaih khân may tâm dôl geh nau uh ah; jêh ri dâk tâm rklaih hom khân may! Ơ phung Yuđa, yor lah phung brah khân may jêng âk tâm ban đah rnoh âk, lĕ rngôch ƀon khân may.$b$,false),
('bunong-vn','JER',2,29,null,$b$“Mâm ƀư khân may ngơi ƀrôk ma gâp? Lĕ rngôch khân may tâm rdâng jêh đah gâp.” Yêhôva lah pô nây.$b$,true),
('bunong-vn','JER',2,30,null,$b$Gâp hŏ dong jêh phung kon khân may jêng mâu khlay ôh: Khân păng mâu ŭch dơn nau ntĭm nti; đao khân may ƀư nkhĭt jêh kôranh nơm mbơh lor khân may nơm nâm bu du mlâm yau mŭr sa hêk.$b$,false),
('bunong-vn','JER',2,31,null,$b$Ơ phung ndŭl mpôl aơ! Iăt hom nau Yêhôva ngơi: “Gâp mâp tă jêng lĕ du ntŭk bri rdah ma phung Israel, mâu lah du n'gor bri ngo vêt vê? Mâm ƀư phung ƀon lan gâp lah aơ; ‘Hên lĕ mpăn jêh, mâu hôm văch ma may đŏng ôh’?$b$,false),
('bunong-vn','JER',2,32,null,$b$Du huê bu ur druh chuêl lĕ ma ndơ nkrơ̆ păng, mâu lah du huê bu ur druh ntơm gŭ sai chuêl lĕ ma bok ao ueh păng? Ƀiă lah phung ƀon lan gâp lĕ chuêl jêh gâp, hŏ jŏ nar jêh mâu hôm dăng kơp ôh.$b$,false),
('bunong-vn','JER',2,33,null,$b$Mâm blau ngăn may nkra trong gay joi phung may rŏng! Kŏ tât may nti ăn ma phung bu ur ƀai tĭng trong may.$b$,true),
('bunong-vn','JER',2,34,null,$b$Tâm ban lĕ ta ao may bu saơ mham phung o ach mâu geh nau tih ôh; mâu di yor may saơ păng lôk mpir gay ŭch ntŭng ôh, ƀiă lah yor moh ntil nau nây kđôi.$b$,false),
('bunong-vn','JER',2,35,null,$b$May lah: ‘Gâp mâu geh tih ôh; n'hêl nanê̆ nau Păng ji nuih du ngai jêh bơh gâp. Aơ, gâp mra njŭn leo may ma nau phat dôih, yor may lah: ‘Gâp mâu prot ƀư tih ôh!$b$,false),
('bunong-vn','JER',2,36,null,$b$Mâm ƀư nơih ngăn may tâm rgâl trong may? Kăl e ri khân prêng đah phung Asiri, aƀaơ ăt mra prêng đah phung Êjipt tâm ban lĕ.$b$,false),
('bunong-vn','JER',2,37,null,$b$May mra juăl ti klơ bôk, du luh bơh ntŭk nây jêng bună, yor lah Yêhôva dun jêh ma phung bunuyh may nsing, may mâu mra dơi chăt jêng ôh yor khân păng.”$b$,false),
('bunong-vn','JER',3,1,null,$b$Bu lah pô aơ: “Tơ lah du huê cha lơi ur, jêh ri tơ lah jêh păng cha lơi ur sŏk sai êng, mâm ƀư, sai ơm nây hôm plơ̆ gŭ bu ur nây lĕ? Tơ lah pô nây mâm ƀư tâm bri neh nây mâu geh hĕ nau ƀơ̆ ƀơch ngăn ngên? Pô ri, may hŏ ƀư jêh nau văng tir đah âk bunuyh may rŏng, jêh ri may mra lŏ plơ̆ sĭt ma gâp lĕ?” Yêhôva lah pô nây,$b$,true),
('bunong-vn','JER',3,2,null,$b$“N'gơr hom măt may, uănh ma yôk prêh! Geh lĕ ntŭk may mâu ƀư nau văng tir? (Ntŭk bu klâu, bu ur bêch ndrel). Ta meng trong may gŭ kâp tât phung may rŏng, nâm bu phung Arap tâm bri rdah; jêh ri khân may hŏ leo mplum ƀơ̆ ƀơch jêh bri neh aơ ma nau văng tir tih mhĭk khân may.$b$,false),
('bunong-vn','JER',3,3,null,$b$Yor nây bu nchăng lơi dak mih, jêh ri yan kao bu mâu ăn tŭp dak mih ôh. Ƀiă lah khân may ăt hôm brơl nâm bu bu ur văng tir, khân may mâu blau prêng ôh.$b$,true),
('bunong-vn','JER',3,4,null,$b$Ntơm bơh aƀaơ tât ô klak kŏ mâu hôm lĕ khân may kuăl mbơ̆ ma gâp, lah: ‘Ơ Mbơ̆ gâp, may jêng Nơm têk ndrêng gâp dôl gâp jêng ndăm?$b$,false),
('bunong-vn','JER',3,5,null,$b$May mra nuih mro mrăng jêh ri djôt nau ji nuih mâu hĕ blau bah?’ Aơ, may lah, ƀiă lah ăt ƀư tih đŏng, tĭng nuih n'hâm may nơm ŭch.”$b$,false),
('bunong-vn','JER',3,6,null,$b$Dôl rô̆ hađăch Y-Jôsia, Yêhôva lah ma gâp pô aơ: “May saơ lĕ moh nau phung Israel, jêng phung ƀon lan tâm rdâng, hŏ ƀư jêh? Khân păng hŏ hao ăp yôk prêh, jêh ri tâm dâng tơm si lung ndrêh, ƀư nau văng tir ta nây.$b$,true),
('bunong-vn','JER',3,7,null,$b$Gâp ntôn lah pô aơ: Jêh păng hŏ ƀư ăp ntil nây, mra plơ̆ sĭt ma gâp. Ƀiă lah lah păng mâu ŭch plơ̆ sĭt ôh. Oh bu ur mâu răp jăp păng jêng phung Yuđa saơ jêh nau nây.$b$,false),
('bunong-vn','JER',3,8,null,$b$Nđâp tơ lah gâp hŏ cha lơi phung Israel ƀư nau văng tir, jêh ri hŏ ăn păng du pŏk sămƀŭt tâm lơi; yor ma păng ƀư nau văng tir, gâp ăt hôm e saơ oh bu ur mâu răp jăp păng, jêng phung Yuđa, mâu klach ôh, ƀiă lah păng ăt hôm brơl ƀư nau văng tir.$b$,false),
('bunong-vn','JER',3,9,null,$b$Yor lah khân păng mĭn nau văng tir mâu jêng mhĭk ôh, khân păng ƀư ƀơ̆ ƀơch bri neh aơ, văng tĭr đah lŭ jêh ri tơm si.$b$,true),
('bunong-vn','JER',3,10,null,$b$Nđâp lah pô nây, oh bu ur mâu răp jăp păng, jêng Yuđa, ăt mâu ŭch sĭt ma gâp ma lĕ nuih n'hâm khân păng, ƀiă lah knŏng ma nau n'hi săk dơm.” Yêhôva lah pô nây.$b$,true),
('bunong-vn','JER',3,11,null,$b$Yêhôva geh lah ma gâp: “Phung Israel tâm rdâng rđĭl gay mpơl khân păng nơm mâu jêng tih lơn ma phung Yuđa mâu răp jăp.$b$,true),
('bunong-vn','JER',3,12,null,$b$Hăn hom, jêh ri mbơh nau ngơi aơ mpeh klơ dor, Yêhôva lah: Ơ phung Israel tâm rdâng; plơ̆ sĭt hom! Gâp mâu mra uănh khân may ma muh măt ji nuih ôh, yor lah gâp yô̆ klâng ngăn; gâp mâu mra ji nuih n'ho ro ôh, Yêhôva lah pô nây.$b$,false),
('bunong-vn','JER',3,13,null,$b$Knŏng ăn may nơm yơh dơn nau may jêng tih; nau may tâm rdâng jêh đah Yêhôva Brah Ndu may; jêh ri may hŏ du nchuăt lam ntŭk rŏng jêh ma brah phung bu năch tâm dâng ăp tơm si lung ndrêh, jêh ri mâu tông ôh bâr gâp. Yêhôva lah pô nây.$b$,false),
('bunong-vn','JER',3,14,null,$b$Yêhôva lah: Ơ phung kon ƀư rlăng, plơ̆ sĭt hom; yor lah gâp jêng sai (jêng kôranh) khân may. Tâm phung mpôl khân may gâp mra săch du ƀon du huê, du noi bar hê, jêh ri gâp mra njŭn leo khân may tât ma ƀon Siôn.$b$,true),
('bunong-vn','JER',3,15,null,$b$“Gâp mra ăn khân may phung rmăk biăp tĭng nâm nuih n'hâm gâp nơm; phung nây sŏk nau blau mĭn jêh ri gĭt rbăng, khân păng siăm khân may.$b$,true),
('bunong-vn','JER',3,16,null,$b$Yêhôva lah: “Tâm lĕ rngôch nar nây, tơ lah khân may lĕ bĭk rơ̆ jêh, jêh ri gum âk tâm bri neh, pô ri bu mâu mra lah tât ma Hip Nau Tâm Rnglăp Yêhôva đŏng ôh! Bu mâu mra mĭn, mâu hôm kah gĭt, mâu hôm klâng ma hip nây ôh; bu mâu mra ƀư păng ôh.$b$,false),
('bunong-vn','JER',3,17,null,$b$Tâm rnôk nây bu mra ntơ moh păng ƀon Yêrusalem Sưng Hađăch Yêhôva, jêh ri lĕ rngôch ndŭl mpôl bunuyh mra tâm rƀŭn ta nây, tâm amoh Yêhôva; jêh ri khân păng mâu jêng dăng bôk ôh ŭch tĭng ndô̆ nuih n'hâm khân păng nơm ŭch.$b$,false),
('bunong-vn','JER',3,18,null,$b$Tâm rnôk rô̆ nây ngih Yuđa mra hăn ndrel tâm rnglăp đah ngih Israel, bar trong hăn ndrel n'grŭp tă bơh bri klơ dor tât ma bri gâp ăn jêh ma phung che khân may jêng drăp ndơn chăm.$b$,false),
('bunong-vn','JER',3,19,null,$b$“Gâp hŏ lah pô aơ: Gâp mra dơm khân may tâm nklang phung kon bu klâu gâp, jêh ri ăn ma khân may du n'gor bri ueh maak, ndơn drăp khlay lơn ma lĕ rngôch ndŭl mpôl bunuyh, mâu blau ntĭt! Gâp hŏ mâp lah: “Khân may mra kuăl ma gâp, Mbơ̆ gâp! Jêh ri lơi hôm teng bơh nau tĭng ndô̆ gâp.$b$,true),
('bunong-vn','JER',3,20,null,$b$Ƀiă lah, Ơ ngih Israel, n'hêl nanê̆ nâm bu du huê bu ur mâu răp jăp cha lơi sai păng, pô ri, khân may ăt mâu răp jăp ma gâp pô nây lĕ, Yêhôva lah.$b$,false),
('bunong-vn','JER',3,21,null,$b$Bu tăng bâr ta klơ n'glơn yôk hil, nau phung kon bu klâu Israel gŭ nhĭm jêh ri vơl, yor lah khân păng hŏ hăn tâm trong tih mhĭk chuêl jêh Yêhôva Brah Ndu khân păng.$b$,true),
('bunong-vn','JER',3,22,null,$b$“Ơ phung kon bu klâu mâu răp jăp, plơ̆ sĭt hom! Gâp mra ƀư bah nau khân may mâu răp jăp.” Khân may lah pô aơ: Aơ, hên sĭt ma may, yor lah may jêng Yêhôva Brah Ndu hên.$b$,false),
('bunong-vn','JER',3,23,null,$b$N'hêl nanê̆, gŭ kâp nau tâm rklaih ntŭk klơ gôl jêng dơm dam, nau ngơi drơu-drơu ăp n'glơn yôk jêng nau rai yot; n'hêl nanê̆ tâm Yêhôva Brah Ndu he geh nau tâm rklaih ma phung Israel.$b$,false),
('bunong-vn','JER',3,24,null,$b$“Ƀiă lah ntơm bơh hên hôm jê̆, nau ƀư prêng hŏ sa rvăn lĕ rngôch play bơh kan chô yau hên hŏ ƀư jêh, phung ndrôk, phung biăp, kon bu klâu, kon bu ur khân păng.$b$,false),
('bunong-vn','JER',3,25,null,$b$Hên mra lâng bêch tâm nau prêng hên nơm, jêh ri nau bu tâm rmot tât ma he nơm! Yor lah hên nđâp ma chô yau hên hŏ ƀư tih jêh đah Yêhôva Brah Ndu hên ntơm bơh hôm jê̆ tât ma nar aơ; hên mâu tông tĭng bâr Yêhôva Brah Ndu hên.”$b$,false),
('bunong-vn','JER',4,1,null,$b$Yêhôva lah: “Ơ phung Israel, tơ lah khân may plơ̆ sĭt ma gâp, plơ̆ sĭt hom, jêh ri tơ lah khân sŏk mƀăr lĕ rngôch nau gâp tâm rmot du ngai bơh măt gâp, pô ri khân may mâu mra trơn ntŭk êng đŏng ôh.$b$,true),
('bunong-vn','JER',4,2,null,$b$Khân may sŏk nau ton n'hêl nê̆, ma nau sŏng, nau di ngăn tĭng nâm Yêhôva gŭ rêh, lĕ rngôch bri dak mra dơi geh nau ueh maak yor tă bơh Păng, jêh ri nau chrêk rmah tâm Păng.$b$,false),
('bunong-vn','JER',4,3,null,$b$Pô aơ, Yêhôva lah ma phung Yuđa jêh ri phung gŭ ta ƀon Yêrusalem: “Chuar hom lŏ sre mhe khân may, jêh ri lơi srih ôh tâm nklang lok.$b$,true),
('bunong-vn','JER',4,4,null,$b$Ơ phung khân may, jêng phung Yuđa jêh ri phung ƀon lan gŭ ta ƀon Yêrusalem. Ăn khân may koh ntâu êng khân may nơm ta năp Yêhôva, jêh ri ăn khân may koh ntâu bơh nuih n'hâm khân may! Lah mâu pô nây, nau gâp nuih mra hit nâm bu ŭnh, sa khân may, mâu geh bunuyh buh nhhât ôh, yor kan tih khân may hŏ ƀư.”$b$,false),
('bunong-vn','JER',4,5,null,$b$“Mbơh hom tâm bri Yuđa jêh ri tâm ƀon Yêrusalem, lah: ‘Uh nŭng hom lam bri Yuđa,’ nter huy, jêh ri lah: ‘Tâm rƀŭn hom, jêh ri ăn he dâk hăn ma ƀon geh mpêr nâp!’$b$,true),
('bunong-vn','JER',4,6,null,$b$N'hao hom bok pla rle mpeh Siôn. Du hom, lơi gŭ hĭr! Yor lah gâp ăn nau mhĭk tât tă bơh dor pa lơ, jêng du nau ƀư rai toyh.$b$,false),
('bunong-vn','JER',4,7,null,$b$Du mlâm yau mŭr tă luh bơh bri păng, du huê nơm ƀư rai lĕ rngôch bri dak ntơm dâk hăn tă bơh ntŭk păng; gay ƀư ma bri khân may rngot njăp; lĕ rngôch ƀon toyh khân may jêng ndơ bu ur rai jêh, mâu hôm geh bunuyh gŭ ôh.$b$,false),
('bunong-vn','JER',4,8,null,$b$Yor nau nây, khân may nsoh hom ao dŭr, jêh ri nhhiăng nhĭm hom; yor lah nau Yêhôva ji nuih ngăn mâu hŏ du ngai ôh bơh he.”$b$,false),
('bunong-vn','JER',4,9,null,$b$Yêhôva lah: “Tâm nôk nây, hađăch jêh ri phung kôranh toyh hâu ngăn klach hôch-hôr tâm nuih n'hâm, phung n'gâng kan ƀư brah mra hih rhâl, jêh ri phung nơm mbơh lor mra ndrŏt.”$b$,false),
('bunong-vn','JER',4,10,null,$b$Jêh ri gâp lah: “Ơ kôranh Brah, Brah Ndu gâp, n'hêl nanê̆ may ndơm jêh phung ƀon lan aơ jêh ri ƀon Yêrusalem, lah pô aơ: ‘Lĕ rngôch khân may mra dơi geh nau đăp mpăn! Ƀiă lah chiông đao hŏ rgŏ tât nau rêh khân păng jêh.”$b$,true),
('bunong-vn','JER',4,11,null,$b$Tâm rnôk nây, bu mra lah ma phung ƀon lan aơ, jêh ri ƀon Yêrusalem pô aơ: “Mra geh sial duh khôm tă bơh n'glơn yôk hil tâm bri rdah, tât ma kon bu ur phung ƀon lan gâp; ƀiă lah mâu di ôh gay ma nsiăng ba mâu lah gŭm mpruh ăn kloh.$b$,true),
('bunong-vn','JER',4,12,null,$b$Hôm geh đŏng sial toyh lơn tât yor ma gâp. Aƀaơ yơh mra ngơi nau phat dôih ma khân păng.”$b$,true),
('bunong-vn','JER',4,13,null,$b$Aơ, păng mra văch nâm bu ndâr tŭk, ndeh seh păng nâm bu sial vănh blông; seh păng prăl nâm bu klang. Rêh ni ngăn ma he, yor he lĕ rai jêh!$b$,true),
('bunong-vn','JER',4,14,null,$b$Ơ ƀon Yêrusalem, ƀư kloh hom nuih n'hâm may bơh nau ƀai, gay ma may dơi klaih. Ndah ŭch jŏ khân may têm prăp nau ƀai gŭ tâm nuih n'hâm khân may?$b$,false),
('bunong-vn','JER',4,15,null,$b$Yor lah geh bâr ngơi mbơh tă bơh bri Dan jêh ri mbơh nau mhĭk bơh yôk Êphraim. Mbơh hom ma lĕ bri dak! Mbơh hom ma Yêrusalem pô aơ:$b$,false),
('bunong-vn','JER',4,16,null,$b$“Phung ta han âk văch tât, tă bơh bri ngai ŭch nchueng lơh lĕ rngôch ƀon n'gor Yuđa.$b$,false),
('bunong-vn','JER',4,17,null,$b$Khân păng nchueng ƀon Yêrusalem nâm bu phung chiă mir; yor lah ƀon nây hŏ tâm rdâng jêh đah gâp, Yêhôva lah pô nây.$b$,false),
('bunong-vn','JER',4,18,null,$b$“Nây jêng nau may gŭ ngao jêh ri kan may ƀư hŏ tât jêh nau aơ ma may. Aơ jêng nau tâm rmal ma may, jêh ri rêh ni ngăn, nau nây ntâp nuih n'hâm may.”$b$,false),
('bunong-vn','JER',4,19,null,$b$Rêh ni ngăn, rêh ni ngăn yơh gâp! Gâp rlĭ rlang tâm nau ji. Nuih n'hâm gâp rngot rvê ngăn. Gâp mâu dơi gŭ klêm ôh! Ơ huêng gâp, may tăng jêh bâr nŭng jêh ri nau bu mbơh geh nau tâm lơh tât.$b$,false),
('bunong-vn','JER',4,20,null,$b$Jêh nau ƀư rai, lơ hâu ƀư rai, bu mbơh mâu blau dŭt, lam bri hŏ rai lĕ jêh; ngih njưh gâp jêh ri bok nchăng ƀât lât dơm rai lĕ jêh.$b$,true),
('bunong-vn','JER',4,21,null,$b$Ndah hŏ jŏ gâp saơ pla bok kơ jêh ri tâm bâr nŭng bu uh hăn dâk nau tâm lơh?$b$,false),
('bunong-vn','JER',4,22,null,$b$“Yor lah phung ƀon lan gâp rluk, khân păng mâu gĭt năl gâp ôh. Nây jêng phung kon se rluk, khân păng mâu geh nau gĭt rbăng ôh. Khân păng mơng ƀư tih, ƀiă lah mâu gĭt ƀư nau ueh ôh.”$b$,false),
('bunong-vn','JER',4,23,null,$b$Gâp uănh ma neh ntu: Aơ, mâu geh rup jêh ri nsoih hŏng dơm; uănh klơ trôk, ƀiă lah mâu geh nau ang.$b$,true),
('bunong-vn','JER',4,24,null,$b$Gâp uănh ma yôk, saơ nau khân păng mpât n'găr; lĕ rngôch yôk n'găr nsâr tâm ban lĕ.$b$,false),
('bunong-vn','JER',4,25,null,$b$Gâp uănh: Mâu hôm saơ bunuyh bu nun jêh ri lĕ rngôch sĭm mpăr du ƀhiau.$b$,false),
('bunong-vn','JER',4,26,null,$b$Gâp uănh, saơ âk mir ba ueh hŏ jêng nkhơng bri rdah, lĕ rngôch ƀon toyh ƀư rai da dê ta năp măt Yêhôva, yor nau Păng ji nuih.$b$,false),
('bunong-vn','JER',4,27,null,$b$Yor lah Yêhôva lah pô aơ: “Lĕ rngôch ƀon rngot njăp, ƀiă lah gâp mâu ƀư rai lĕ ƀhiau ôh.$b$,true),
('bunong-vn','JER',4,28,null,$b$Yor nau nây, neh ntu mra nhĭm vơl jêh ri klơ trôk jêng ngo vêt vê; yor lah gâp ngơi jêh, gâp săch jêh, gâp mâu vơl bơh (nduyh tôr) lĕ, mâu lĕ gâp plơ̆ sĭt.”$b$,true),
('bunong-vn','JER',4,29,null,$b$Tơ lah tăng nteh phung ta han ncho seh jêh ri ta han pănh na, pô ri lĕ rngôch ƀon nchuăt du krap; khân păng lăp tâm rlô pôm lok; ƀă khân păng hao tâm ntŭk lŭ; lĕ rngôch ƀon lĕ cha lơi, jêh ri mâu hôm geh bunuyh gŭ ôh.$b$,true),
('bunong-vn','JER',4,30,null,$b$Bi may, tơ lah may bu hŏ ƀư rai jêh, mâm may mra ƀư? Nđâp tơ lah may nsoh ao mpor chăng, nkrơ̆ tâm săk geh ndơ mah, jêh ri mhĭng dak si tâm muh măt, gay ăn săk jăn jêng ueh, nau nây ăt jêng dơm dam. Bunuyh rŏng ma may ăt rmot đŏng ma may, jêh ri joi nau ŭch nkhĭt may.$b$,false),
('bunong-vn','JER',4,31,null,$b$Yor lah gâp tăng bâr nđêng (rđêng) nâm bu du huê bu ur bêch veng ŭnh, nau ji nâm bu du huê bu ur gŭ deh kon dak bôk. Nây jêng bâr kon bu ur Siôn, gŭ nhĭm ƀrŏk ƀrŏl, jêh ri laih ti, lah: “Rêh ni ngăn yơh gâp! Huêng gâp lĕ khĭt huăr, ta năp phung nkhĭt bunuyh.”$b$,false),
('bunong-vn','JER',5,1,null,$b$“Nchuăt hom ta aơ ta ri n'gŏ trong lam ƀon toyh Yêrusalem, jêh ri n'gơr uănh. Ôp suk hom gay tĭng joi tâm ăp ntŭk tâm nhuang ƀon gĭt lah geh, saơ du huê bunuyh lĕ; tơ lah geh du huê bunuyh ƀư nau sŏng, nau răp jăp, pô ri gâp mra yô̆ an ma ƀon nây.$b$,true),
('bunong-vn','JER',5,2,null,$b$Nđâp tơ lah khân păng lah: Nanê̆ tĭng nâm Yêhôva gŭ rêh! Nây jêng nau ton mƀruh.$b$,false),
('bunong-vn','JER',5,3,null,$b$Ơ Yêhôva, mâu hĕ măt may mêt uănh joi nau n'hêl nanê̆ ? May dong jêh khân păng, khân păng mâu ŭch rngot rvê, may ƀư rai jêh khân păng, ƀiă lah khân păng dun ma nau ntĭm nti. Khân păng dăng muh măt rlau lơn ma lŭ, mâu ŭch nhăl rmal nau tih.$b$,true),
('bunong-vn','JER',5,4,null,$b$Gâp dơi lah: “Aơ jêng knŏng phung o ach, khân păng mâu geh nau gĭt rbăng ôh. Yor lah khân păng mâu gĭt ôh trong Yêhôva, nau vay Brah Ndu$b$,false),
('bunong-vn','JER',5,5,null,$b$Pô ri gâp mra hăn ngơi ma phung kôranh ƀĭt gai ŭch lah đah khân păng, yor lah khân păng gĭt jêh trong Yêhôva, nau sŏng Brah Ndu khân păng.” Ƀiă lah, phung aơ tâm di du ai nau ƀư nkêch lơi mâng mbăk, jêh ri ntăch mbăk lơi rse bu kât.$b$,false),
('bunong-vn','JER',5,6,null,$b$Pô ri dĭng yau mŭr tă bơh bri krŏng nkhĭt khân păng, du mlâm so bri bơh bri rdah ƀư rai khân păng. Du mlâm yau brăch dôl rmiăt pa dih ƀon ŭch ƀư ma ƀon toyh khân păng, mbu nâm luh bơh ƀon, păng mra hêk sa; yor lah nau tih khân păng âk ngăn, nau khân păng cha lơi ntop âk lơn.$b$,false),
('bunong-vn','JER',5,7,null,$b$“Mâm gâp dơi yô̆ an nau tih may? Phung kon may lĕ cha lơi gâp jêh, jêh ri ton săk jêh đah phung brah mâu jêng brah ôh. Gâp hŏ siăm jêh khân păng sông tât hơm, khân păng ƀư tih nau văng tĭr, jêh ri tâm rgum dŭt âk tâm ngih phung bu ur văng tir.$b$,true),
('bunong-vn','JER',5,8,null,$b$Khân păng jêng nâm seh nkuăng lay tĭng gar me, du huê tâm ăp nơm tĭng groi pa kơi nkoch ur phung chiau meng păng.$b$,false),
('bunong-vn','JER',5,9,null,$b$Yêhôva lah: “Gâp mâu mra tâm rmal hĕ khân păng yor nau aơ? Huêng brah gâp mâu mra plơng bôk hĕ ma du bri dak pô nây mâu lah mâu?$b$,true),
('bunong-vn','JER',5,10,null,$b$“Hăn hao hom klơ mpêr păng jêh ri ƀư rai rlâm lơi; ƀiă lah lơi ta ƀư rai lĕ ôh. Te mƀăr hom n'gĭng păng, yor lah mâu jêng ndơ ma Yêhôva ôh.$b$,true),
('bunong-vn','JER',5,11,null,$b$Yor lah ngih Israel jêh ri ngih Yuđa mâu gŭ răp jăp ndrel gâp ôh.” Yêhôva lah.$b$,false),
('bunong-vn','JER',5,12,null,$b$Khân păng hŏ dun mƀăr lơi Yêhôva, jêh ri lah: ‘Mâu di Păng ôh! Nau rêh ni mâu mra ƀư tât ma he; he mâu mra mâp tak đao, ji ngot ji hir ôh.$b$,false),
('bunong-vn','JER',5,13,null,$b$Phung nơm mbơh lor mra jêng nâm bu sial, nau nti lah mâu gŭ tâm khân păng ôh; khân păng mra mâp nau bu ƀư ma khân păng!”$b$,false),
('bunong-vn','JER',5,14,null,$b$Yor nây Yêhôva Brah Ndu ma phung ta han lah pô aơ: “Yor lah khân păng hŏ ngơi jêh nau nây, aơ, gâp mra njêng nau gâp ngơi tâm bâr may jêng nâm bu ŭnh, jêh ri gâp njêng phung ƀon lan aơ, nâm bu long. Jêh ri ŭnh mra sa khân păng.$b$,false),
('bunong-vn','JER',5,15,null,$b$Yêhôva lah: “Ơ Ngih Israel, gâp mra njŭn leo du ndŭl mpôl dăng ktang, jêng ndŭl mpôl ơm jêh, du ndŭl mpôl ngơi nau khân păng may mâu mâp tăng ôh, kŏ khân may mâu gĭt rbăng lĕ nau khân păng lah, tă bơh bri ngai ŭch tâm lơh đah khân may.$b$,true),
('bunong-vn','JER',5,16,null,$b$Dĭng kăm khân păng bêng ma hăr, nkhĭt khân may, lĕ rngôch khân păng jêng phung janh ktang da dê.$b$,true),
('bunong-vn','JER',5,17,null,$b$Khân păng mra sa ba khân may lĕ kăch jêh, jêh ri mpa khân may sông sa, jêng ndơ khân may prăp ăn ma kon bu ur, bu klâu sông sa, păng sa gŭch phung biăp, jêh ri phung ndrôk khân may, sa play kriăk ƀâu jêh ri play rvi khân may. Păng mra sŏk đao ƀư rai ăp ƀon khân may geh mpêr nâp ntŭk khân may nde krap.”$b$,false),
('bunong-vn','JER',5,18,null,$b$Yêhôva lah: “Nđâp lah pô nây, ăt tâm nar nây lĕ, gâp mâu mra ƀư rai lĕ rngôch khân may ôh.$b$,true),
('bunong-vn','JER',5,19,null,$b$Jêh ri tơ lah khân păng lah: “Mâm ƀư Yêhôva Brah Ndu he hŏ ƀư jêh lĕ ntil nau aơ ma hĕ? Pô ri may mra lah ma khân păng pô aơ: ‘Nâm bu khân may lĕ cha lơi gâp jêh, jêh ri mâm pah kan ma brah bu năch tâm bri khân may, ăt pô nây lĕ khân may mra pah kan ma phung ƀon lan bu năch tâm du n'gor bri êng mâu di bri nây jêng bri khân may nơm ôh.$b$,true),
('bunong-vn','JER',5,20,null,$b$“Mbơh hom nau aơ ma ngih Yakôp, tâm mpơl kan aơ tâm bri Yuđa, jêh ri lah:$b$,true),
('bunong-vn','JER',5,21,null,$b$Iăt hom nau aơ, Ơ phung ƀon lan rluk mâl jêh ri mâu gĭt rbăng, jêng phung ƀon lan geh măt ƀiă lah mâu gĭt saơ ôh, geh tôr ƀiă lah mâu gĭt tăng ôh.$b$,false),
('bunong-vn','JER',5,22,null,$b$Yêhôva lah: “Khân may mâu klach yơk hĕ ma gâp? Khân may mâu râm nsâr hĕ ta năp măt gâp? Gâp jêng Nơm hŏ sŏk jêh choih ƀư kơh ma dak mƀŭt, yor tă bơh du nau ntăm n'ho ro, dak mƀŭt rbuh, ăt mâu dơi rlêng lĕ n'har kơh nây.$b$,false),
('bunong-vn','JER',5,23,null,$b$Ƀiă lah phung ƀon lan aơ dăng bôk jêh ri geh nuih n'hâm tâm rdâng, jêh ri lĕ rngôch khân păng du dâk tâm rdâng da dê jêh ri du ngai.$b$,false),
('bunong-vn','JER',5,24,null,$b$Khân păng mâu lah ôh tâm nuih n'hâm pô aơ: ‘He klach yơk hom ma Brah Ndu he nâm bu ntĭt Nơm ăn dak mih di khay yan păng, dak mih tŭp rah di yan jêh ri mih rđah năm (mih yan lôch dŭt), jêh ri yor he mray âk nar ver (nar pơh) tâm nal jêh ma yan kăch khom.$b$,false),
('bunong-vn','JER',5,25,null,$b$Nau kue khân may hŏ king jêh lĕ rngôch nau nây mâu ăn tât ma khân may; nau tih khân may king nau ueh tât ma khân may.$b$,true),
('bunong-vn','JER',5,26,null,$b$Yor lah geh phung ƀai ta nklang phung ƀon lan he; khân păng vay vơr rmiăt nâm bu bunuyh nhŭp sĭm, sân dăk, drăng mong (nhuăl), gay ŭch nhŭp bunuyh.$b$,true),
('bunong-vn','JER',5,27,null,$b$Ngih vâl khân păng bêng ma nau mƀruh ndơm (ƀlêp ƀlêr), nau ƀai nâm bu rgum âk mlâm sĭm. Yor nây khân păng jêng toyh jêh ri ndrŏng.$b$,false),
('bunong-vn','JER',5,28,null,$b$Khân păng jêng lay jêh ri ntâu mƀĭr ƀhiăr. Nau janh ƀai khân păng lĕ rlau keh jêh; mâu ŭch phat dôih ăn nau di ma phung kon đơi, gay ăn nau chăt jêng! Khân păng mâu ƀư nau sŏng ăn ma phung o ach.$b$,true),
('bunong-vn','JER',5,29,null,$b$Yêhôva lah: “Mâm ƀư Gâp mâu mra tâm rmal hĕ ma khân păng yor nau nây? “Huêng brah gâp mâu plơng bôk hĕ ma du ndŭl mpôl tâm ban pô nây?”$b$,true),
('bunong-vn','JER',5,30,null,$b$Tâm bri neh aơ hŏ tât jêh du nau hih rhâl jêh ri djơh mhĭk.$b$,false),
('bunong-vn','JER',5,31,null,$b$Phung nơm mbơh lor mbơh nau mƀruh, jêh ri phung kôranh ƀư brah yor tă bơh nau nây khân păng dơi chiă uănh! Phung ƀon lan gâp geh nau rŏng da dê. Tơ lah tât dăch dŭt, mâm khân may mra ƀư?$b$,false),
('bunong-vn','JER',6,1,null,$b$Ơ phung kon sau Benjamin, du krap hom, luh bơh tâm nklang ƀon Yêrusalem gay dơi geh nau đăp mpăn. Uh hom nŭng tâm ƀon Têkôa, jêh ri n'hao hom du ntil ndơ tâm nal ta ƀon Bêthakêrem, yor lah nau mhĭk tât tă bơh dor, jêh ri nau mhĭk nây ăn tât nau ƀư rai toyh ngăn.$b$,true),
('bunong-vn','JER',6,2,null,$b$Gâp mra ƀư rai bu druh ueh reh jêh ri nơm bu njê, kon druh ƀon Siôn.$b$,false),
('bunong-vn','JER',6,3,null,$b$Phung rmăk biăp ndrel ma phung biăp khân păng mra văch lơh ƀon Siôn; khân păng ƀư ntŭk rmblak văr jŭm păng, ăp nơm mra sa gơ̆ ntŭk bu prăp ma păng.$b$,false),
('bunong-vn','JER',6,4,null,$b$“Ndrăp hom nau tâm lơh đah păng! Dâk hăn hom! Ăn he rduh lơh dôl nklang bôl nar! Rêh ni ngăn! Nar lĕ vet, yor lah gui n'hâm bri mhaơ hŏ jong jêh!$b$,false),
('bunong-vn','JER',6,5,null,$b$Dâk hom ăn he rduh dôl măng, jêh ri ƀư rai ngih hađăch păng!$b$,true),
('bunong-vn','JER',6,6,null,$b$Yor lah Yêhôva ma phung ta han lah pô aơ: “Kăl lơi tơm si ƀon Siôn; jêh ri n'hao mpêr gay ƀư ma Yêrusalem! Aơ yơh ƀon toyh, dơi dơn nau bu tâm rmal; tâm păng bêng âk nau bu tŭn jot.$b$,true),
('bunong-vn','JER',6,7,null,$b$Nâm bu ntu dak prăp dak tu mhe luh, tâm ban pô nây lĕ ƀon Yêrusalem prăp nau ƀai păng. Nau djơh mhĭk jêh ri nau bu ƀư rai bu tăng tâm nklang păng; nau ji kuet jêh ri nau sôt rmanh gŭ pa năp gâp ƀa ƀơ.$b$,false),
('bunong-vn','JER',6,8,null,$b$Njrăng hom, Ơ ƀon Yêrusalem, iăt hom nau ntĭm nti, klach lah gâp ƀư rlăng ma may, gâp njêng ma bri neh may jêng rngol, mâu geh bunuyh gŭ.”$b$,false),
('bunong-vn','JER',6,9,null,$b$Yêhôva ma phung ta han lah pô aơ: “Bu mra dônh mban lĕ rngôch bunuyh hôm e klen tâm bri Israel, nâm bu du huê pĕ play kriăk ƀâu. Nto hom ti pĕ play păng, nâm bu bunuyh pĕ play kriăk ƀâu ta n'gĭng nây lĕ.”$b$,false),
('bunong-vn','JER',6,10,null,$b$Ma mbu moh gâp mra ngơi jêh ri mbơh, gay khân păng gŭ iăt? Aơ, tôr khân păng bu nsêt jêh khân păng mâu dơi tăng. Aơ, nau Yêhôva ngơi jêng ndơ djôt nau rak suai ma khân păng, khân păng mâu maak ma nau ngơi nây ôh.$b$,false),
('bunong-vn','JER',6,11,null,$b$Yor ri gâp bêng ma nau Yêhôva nuih, gâp mâu hôm dơi nkân nau ji nuih nây ôh. Nkhŭt hom nau nây ma phung kon se tâm trong sâng jêh ri ma phung bu klâu ndăm tâm ban lĕ; yor lah bu mra nhŭp lơi ur nđâp ma sai, phung gân toyh nđâp ma phung ranh ngăn.$b$,false),
('bunong-vn','JER',6,12,null,$b$Ngih vâl khân păng mra pha bu êng, mir ba jêh ri ur khân păng ăt ndrel ma nây; yor lah ti gâp mra yơr ma phung gŭ tâm bri nây.” Yêhôva lah.$b$,false),
('bunong-vn','JER',6,13,null,$b$“Yor lah tâm phung khân păng, ntơm bơh phung dŭt jê̆ n'ho tât phung dŭt toyh, ăp nơm khân păng kơnh sa kao nau sa pôn nkhiăn, jêh ri kôranh nơm mbơh lor nđâp kôranh ƀư brah ƀư nau ndơm da dê.$b$,false),
('bunong-vn','JER',6,14,null,$b$Khân păng ƀư bah ntŭk sôt phung ƀon lan gâp djê̆ djê̆ dơm, khân păng lah: ‘Đăp mpăn! Đăp mpăn! Biă lah mâu geh nau đăp mpăn ôh.$b$,false),
('bunong-vn','JER',6,15,null,$b$Khân păng prêng lĕ tơ lah khân păng ƀư geh nau bu ntêh rmot? Mâu, khân păng mâu prot prêng ôh; mâu mâp saơ muh măt chăng yor ma nau prêng. Yor nây khân păng cha lôt ndrel phung hŏ cha lôt jêh. Tơ lah gâp tâm rmal, khân păng mra tâm n'glưh Yêhôva lah.$b$,true),
('bunong-vn','JER',6,16,null,$b$Pô aơ Yêhôva lah: “Gŭ hom êp meng trong jêh ri kâp uănh, joi ôp ma trong ơm nây, ta ntŭk trong nau sŏng, jêh ri chuat hom ta nây, pô ri khân may mra geh nau rlu ma huêng khân may. Ƀiă lah khân păng plơ̆ sĭt lah pô aơ: ‘Hên mâu ŭch njŏ trong nây ôh,’$b$,false),
('bunong-vn','JER',6,17,null,$b$Gâp hŏ dơm jêh phung gak chiă uănh khân may, lah: ‘Rkêng tôr iăt hom bâr nŭng!’ Ƀiă lah khân păng plơ̆ lah: ‘Phung hên mâu mra gŭ iăt ôh.’$b$,false),
('bunong-vn','JER',6,18,null,$b$Yor nây iăt hom, ơ lĕ rngôch ntil mpôl bunuyh lam bri neh ntu, ơ phung tâm rƀŭn, mbơh ngăn, moh nau mra tât ma khân păng.$b$,false),
('bunong-vn','JER',6,19,null,$b$Iăt hom, Ơ neh ntu! Aơ, gâp leo nau mhĭk tât ma phung ƀon lan aơ, nâm bu ntĭt play mbơh ma nau khân păng gŭ mĭn, yor khân păng mâu ŭch iăt nau ngơi gâp, jêh ri hŏ lơi jêh nau vay gâp.$b$,true),
('bunong-vn','JER',6,20,null,$b$Moh nau khlay ma gâp nau khân păng su dak ƀâu kah bơh bri Sêba, mâu lah ndơ nhhơr ƀâu kah bơh bri ngai! Mpa ƀư brah khân may nhhơr mpa gŭch gâp mâu dơn ôh, mpa khân may ƀư brah ăt mâu ƀư maak ma gâp lĕ.”$b$,true),
('bunong-vn','JER',6,21,null,$b$Pô ri yơh Yêhôva lah pô nây. Aơ, gâp mra dơm pa năp phung ƀon lan aơ, ndơ ăn khân păng chêh prah; phung mbơ̆ nđâp phung kon ndrel n'grŭp mra chêh prah ta nây, phung chiau meng jêh ri mĭt jiăng mra rai lôch.$b$,false),
('bunong-vn','JER',6,22,null,$b$Pô aơ nau Yêhôva lah: Aơ, du phung ƀon lan bơh bri dor, du bri dak toyh dâk nkra nau tâm lơh tă bơh ntŭk ngai lơn ta neh ntu aơ.$b$,true),
('bunong-vn','JER',6,23,null,$b$Khân păng djôt na jêh ri tak, khân păng jêng phung janh ƀai mâu geh nau yô̆ ôh; nteh khân păng chuat hăn jêng nâm dak lêng rbuh; khân păng ncho seh, khân păng dăp mbor nâm bu ta han tâm lơh ŭch tâm rdâng đah may; Ơ kon bu ur ƀon Siôn!”$b$,true),
('bunong-vn','JER',6,24,null,$b$Hên tăng lư jêh nau nây, ti hên hươi jêng ra ai jêh; nau rngot tât ma hên jêh, nau ji vănh nâm bu ur ji deh hŏ rduh ran tât ma hên.$b$,true),
('bunong-vn','JER',6,25,null,$b$Lơi ta luh ta mir ôh, mâu lĕ chuat nsong n'gŏ trong; yor lah phung rlăng đao dao, geh nau klach văr jŭm njônh pŭng.$b$,true),
('bunong-vn','JER',6,26,null,$b$Ơ phung kon bu ur ƀon lan gâp, nsoh hom ao dŭr jêh ri lâng bêch tâm ŭnh buh; nhĭm vơl, nđor khĭt nâm bu roh du huê kon bu klâu kon dul, nhĭm vơl ma nau rngot ngăn ngên; yor lah phung ƀư rai mra dăch tât ma he ma nau ndrŏt.$b$,true),
('bunong-vn','JER',6,27,null,$b$“Gâp hŏ njêng may du huê bunuyh ƀư rlong jêh ri rlong uănh phung ƀon lan gâp, gay ma may dơi gĭt năl jêh ri sek uănh trong khân păng.$b$,true),
('bunong-vn','JER',6,28,null,$b$Lĕ rngôch khân păng vay tâm rdâng, hay ngơi nau nchơt, khân păng dăng nâm bu kông jêh ri loih, khân păng ƀư nau tih hâu ngăn ngên.$b$,true),
('bunong-vn','JER',6,29,null,$b$Nuh bu puh dŭt dăng, ndrak lêk đah ŭnh; khân păng kret đŏng ăt sĭt pô nây mâu khlay ôh. Yor lah bunuyh ƀai ăt hôm e mâu hŏ dơi ƀư ngroh lơi ôh.$b$,false),
('bunong-vn','JER',6,30,null,$b$Bu ntơ ma khân păng prăk djah, yor lah Yêhôva cha lơi jêh khân păng.$b$,true),
('bunong-vn','JER',7,1,null,$b$Yêhôva ngơi ma Y-Yêrêmi pô aơ:$b$,true),
('bunong-vn','JER',7,2,null,$b$“Dâk hom ta mpông pêr ngih Yêhôva, jêh ri mbơh nau ngơi aơ: ‘Iăt hom nau Yêhôva ngơi, Ơ lĕ rngôch phung Yuđa lăp ta mpông pêr aơ gay mbah yơk ma Yêhôva.$b$,false),
('bunong-vn','JER',7,3,null,$b$Yêhôva ma phung ta han, Brah Ndu Israel, lah: Rgâl hom trong khân may jêh ri nau khân may ƀư, jêh ri gâp mra ăn khân may gŭ tâm n'gor aơ.$b$,false),
('bunong-vn','JER',7,4,null,$b$Lơi ta khân may rnơm ôh ma nau ngơi ndơm aơ: ‘Aơ jêng ngih brah Yêhôva, ngih brah Yêhôva, ngih brah Yêhôva.’$b$,false),
('bunong-vn','JER',7,5,null,$b$Yor lah tơ lah khân may rgâl ngăn n'hêl nanê̆ trong khân may jêh ri nau khân may ƀư, tơ lah nanê̆ khân may ƀư nau sŏng ndrăng nơm jêng bunuyh chiau meng păng;$b$,false),
('bunong-vn','JER',7,6,null,$b$tơ lah khân may mâu tŭn jot ôh phung bunăch, phung kon đơi mâu lah bu ur khĭt sai, jêh ri mâu ƀư pling mham mâu geh nau tih tâm ntŭk aơ, mâu lĕ tĭng ndô̆ phung brah êng, jêng nau ƀư mhĭk ma khân may nơm,$b$,false),
('bunong-vn','JER',7,7,null,$b$rnôk nây gâp mra ăn khân may gŭ ngai tâm ntŭk aơ, jêh ri tâm neh gâp hŏ ăn jêh ma chô yau khân may ntơm bơh kăl e kŏ tât n'ho ro.$b$,false),
('bunong-vn','JER',7,8,null,$b$Aơ, khân may rnơm nkhơng ma nau ngơi mƀruh nchơt mâu geh nau khlay ôh.$b$,true),
('bunong-vn','JER',7,9,null,$b$Khân may mra ntŭng lĕ, nkhĭt bunuyh lĕ, ton săk mƀruh lĕ, văng tĭr lĕ, su ndơ ƀâu kah ăn ma brah Baal lĕ, jêh ri tĭng ndô̆ brah êng lĕ, jêng brah he mâu gĭt di lĕ?$b$,true),
('bunong-vn','JER',7,10,null,$b$Jêh ri khân may văch gŭ dâk pa năp gâp tâm ngih aơ bu ntơ ma Amoh gâp jêh ri lah: ‘Aơ, hên lĕ dơi rklaih jêh!’. Gay ăn ma khân may dơi ƀư tih lĕ ntil ndơ gâp tâm rmot nây.$b$,false),
('bunong-vn','JER',7,11,null,$b$Pô ri, mâm khân may uănh ma ngih aơ, jêng ntŭk bu dơi ntơ ma Amoh gâp, nâm bu trôm ma phung ntŭng lĕ? Aơ, gâp nơm yơh, saơ jêh nau nây, Yêhôva lah:$b$,false),
('bunong-vn','JER',7,12,null,$b$“Pô nây, hăn hom tât ta ntŭk gâp sa ơm tâm ƀon Silô, jêng ntŭk dơm jêh Amoh gâp rơh lor ri, gay saơ moh nau gâp ƀư jêh ma ƀon nây yor nau tih mhĭk phung ƀon lan gâp Israel.$b$,false),
('bunong-vn','JER',7,13,null,$b$Yêhôva lah: Aƀaơ ri, yor lah khân may hŏ ƀư jêh lĕ nau nây, gâp hŏ dâk ơm srôih ngơi ntĭm nti khân may, ƀiă lah khân may mâu tông ôh; lah gâp kuăl khân may, kŏ khân may mâu plơ̆ sĭt lah lĕ,$b$,false),
('bunong-vn','JER',7,14,null,$b$yor nây gâp ƀư ma ngih aơ, jêng ngih bu ntơ jêh ma Amoh gâp, jêh ri ma ngih nây khân may nsing, jêh ri sâm ƀư an ntŭk gâp hŏ ăn jêh ma khân may jêh ri ma phung che khân may, nâm bu gâp hŏ ƀư jêh ta ƀon Silô;$b$,false),
('bunong-vn','JER',7,15,null,$b$jêh ri gâp mra mprơh khân may bơh pa năp gâp, nâm bu gâp mprơh jêh lĕ rngôch ndŭl mpôl khân may, jêng lĕ rngôch rdŭl mpôl Êphraim.$b$,false),
('bunong-vn','JER',7,16,null,$b$Yor ri may, lơi ta mbơh sơm tâm tang yor ma phung ƀon lan aơ, mâu lĕ vơl dăn an yor khân păng, yor lah gâp mâu iăt nau may ôh.$b$,true),
('bunong-vn','JER',7,17,null,$b$May mâu saơ hĕ moh khân păng gŭ ƀư tâm ăp rplay ƀon n'gor Yuđa jêh ri rŏ trong toyh ƀon Yêrusalem?$b$,false),
('bunong-vn','JER',7,18,null,$b$Phung kon se dônh long, phung mbơ̆ sênh ŭnh, jêh ri phung bu ur mon rnih, gay ƀư ƀănh nhhơr ma hađăch bu ur klơ trôk; jêh ri khân păng nkhŭt ndơ nhhơr nây ăn ma brah êng, gay nsônh nuih gay ăn gâp ji nuih.$b$,false),
('bunong-vn','JER',7,19,null,$b$Yêhôva lah: “Di lĕ khân păng gay nsônh nuih gâp? Mâu di hĕ khân păng nsônh êng khân păng nơm, ăn tât nau rŭng răng ma khân păng nơm?$b$,false),
('bunong-vn','JER',7,20,null,$b$Yor nây, Yêhôva lah pô aơ: Aơ, gâp mra nkhŭt nau gâp ji nuih jêh ri nau gâp ji nuih biănh ma ntŭk aơ, ma phung bunuyh jêh ri ma mpô mpa, ma tơm si tâm mir jêh ri play đo tă bơh neh; ŭnh mra hâr hŭt khân păng jêh ri mâu blau nhhât ôh.”$b$,false),
('bunong-vn','JER',7,21,null,$b$“Pô aơ Yêhôva ma phung ta han, Brah Ndu phung Israel, lah: Ntop hom mpa nhhơr gŭch ma mpa khân may ƀư brah êng, jêh ri sa hom nglay puăch (puăch).$b$,true),
('bunong-vn','JER',7,22,null,$b$Yor lah tâm rnôk gâp njŭn leo phung che khân păng du luh bơh n'gor bri Êjipt, gâp mâu mâp ngơi, jêh ri mâu mâp ntăm ma phung che khân may ma nau nhhơr mpa nhhơr gŭch, jêh ri lĕ ntil ƀư brah ôh.$b$,true),
('bunong-vn','JER',7,23,null,$b$Ƀiă lah, aơ jêng nau ntăm gâp hŏ mbơh ma khân păng: Tông hom bâr gâp, jêh ri gâp mra jêng Brah Ndu khân may, jêh ri khân may mra jêng phung ƀon lan gâp; tĭng ndô̆ hom tâm lĕ trong gâp ntăm ma khân may, gay khân may geh nau ueh maak.$b$,true),
('bunong-vn','JER',7,24,null,$b$Ƀiă lah khân păng mâu tông, jêh ri kŏ mâu rkêng tôr iăt lĕ; khân păng sŏl ko chuat tĭng trong khân păng nơm mĭn, tĭng tâm nau dăng nuih n'hâm khân păng, jêh ri plơ̆ sĭt pa kơi mâu hăn ôh rlet pa năp.$b$,true),
('bunong-vn','JER',7,25,null,$b$Ntơm bơh nar phung che khân may du luh jêh tă bơh n'gor bri Êjipt tât ma nar aơ, gâp ăt prơh hăn ƀa ƀơ lĕ rngôch phung oh mon gâp, phung kôranh nơm mbơh lor tât ma khân păng ăp nar.$b$,false),
('bunong-vn','JER',7,26,null,$b$Ƀiă lah khân păng mâu ŭch iăt bâr gâp ôh, mâu lĕ khân păng rkêng tôr ŭch iăt, ƀiă lah lơ hâu dăng nuih n'hâm khân păng. Khân păng ƀư nau mhĭk lơn ma phung che khân păng.’$b$,false),
('bunong-vn','JER',7,27,null,$b$Pô ri may mra ngơi lĕ rngôch nau aơ ma khân păng, ƀiă lah khân păng mâu mra iăt may ôh. May mra kuăl khân păng, ƀiă lah khân păng mâu mra plơ̆ sĭt lah ma may ôh.$b$,false),
('bunong-vn','JER',7,28,null,$b$May mra lah ma khân păng: ‘Aơ jêng ndŭl mpôl mâu tông bâr ma Brah Ndu khân păng ôh, jêh ri mâu sŏk dơn nau ntĭm nti. Nau n'hêl nanê̆ roh jêh, khân păng mâu hôm ngơi nau nây ôh.$b$,false),
('bunong-vn','JER',7,29,null,$b$Ơ Yêrusalem, poih hom sŏk khân may, klŭp ăn ngai; nhĭm vơl hom ta klơ n'glơn yôk hil! Yor lah Yêhôva dun jêh ri cha lơi jêh ndŭl mpôl aơ, nôk păng ji nuih.’$b$,false),
('bunong-vn','JER',7,30,null,$b$Yêhôva lah: Yor lah phung kon sau Yuđa ƀư jêh nau mhĭk ta năp măt gâp; khân păng dơm jêh ndơ gâp tâm rmot tâm ngih dơi ntơ ma Amoh gâp, gay ƀư ƀơ̆ ƀơch ô băl.$b$,false),
('bunong-vn','JER',7,31,null,$b$Jêh ri khân păng ndâk ntŭk prêh klơ Tôphet, tâm rlŭng kon bu klâu Y-Hinôm, gay nhhơr gŭch phung kon bu klâu jêh ri phung kon bu ur khân păng tâm ŭnh; nau nây gâp mâu prot ntăm ôh mâu lĕ gâp mâp mĭn ma nau nây.$b$,false),
('bunong-vn','JER',7,32,null,$b$Yor nây, Yêhôva lah: Aơ, nar mra tât, aƀaơ ri mâu mra ntơ amoh Tôphet jêh ri rlŭng kon bu klâu Y-Hinôm đŏng ôh, ƀiă lah ntơ rlŭng sreh Nkhĭt, yor lah bu mra tâp bunuyh khĭt ta Tôphet, kŏ tât mâu hôm geh ntŭk tâp.$b$,true),
('bunong-vn','JER',7,33,null,$b$Jêh ri săk jăn khĭt phung ƀon lan aơ mra jêng mpa sa ma phung sĭm mpăr, jêh ri mpô mpa bri, jêh ri mâu geh bunuyh mprơh khân păng ôh.$b$,false),
('bunong-vn','JER',7,34,null,$b$Rnôk nây gâp mra ƀư ăp rplay ƀon n'gor Yuđa jêh ri rŏ trong ƀon toyh Yêrusalem mâu hôm tăng bâr troh răm maak, bâr bu klâu ntơm nsông ur jêh ri bâr bu ur nđăp ma sai, yor lah bri aơ jêng ntŭk rngol.$b$,false),
('bunong-vn','JER',8,1,null,$b$“Yêhôva lah: Tâm rnôk nây, bu mra sơr bơh ntu môch, nting phung hađăch Yuđa, nting phung kôranh, phung kôranh ƀư brah, phung kôranh nơm mbơh lor, jêh ri lĕ rngôch phung gŭ tâm ƀon Yêrusalem.$b$,true),
('bunong-vn','JER',8,2,null,$b$Bu mra ih nđaih lĕ rngôch nting nây tâm duh nar ang khay, jêh ri lĕ rngôch mănh klơ trôk, ndơ nây khân păng rŏng, jêh ri pah kan, ndơ nây khân păng tĭng ndô̆ jêh, jêh ri joi gay mbah yơk. Bu mâu mra plơ̆ rgum đŏng mâu lah tâp tay khân păng ôh; khân păng mra jêng nâm bu ŭnh buh ta klơ neh.$b$,true),
('bunong-vn','JER',8,3,null,$b$Jêh ri phung hôm e klen bơh phung ndŭl mpôl ƀai aơ tâm lam ntŭk gâp mprơh jêh, khân păng mra rŏng ma nau khĭt âk lơn ma nau rêh, Yêhôva ma phung ta han lah.$b$,true),
('bunong-vn','JER',8,4,null,$b$“Pô ri, ăn may mbơh ma khân păng, ‘Pô aơ nau Yêhôva lah: Tơ lah khân păng lĕ cha lôt, khân păng plơ̆ dâk lĕ?$b$,true),
('bunong-vn','JER',8,5,null,$b$Pô ri mâm ƀư phung ƀon lan Yêrusalem aơ nkhah du, cha lơi mro? Khân păng ăt hôm ƀư nau ndơm, Khân păng dun mâu ŭch plơ̆ sĭt.$b$,false),
('bunong-vn','JER',8,6,null,$b$Gâp rkêng tôr iăt jêh ri tăng jêh, ƀiă lah khân păng mâu ngơi nau sŏng ôh; mâu geh du huê rmal nau ƀai păng nơm, jêh ri lah: “Moh nau gâp tă ƀư jêh?” Ăp nơm chuat tĭng trong khân păng nơm, nâm bu du mlâm seh rduh ran pa năp ma nau tâm lơh.$b$,true),
('bunong-vn','JER',8,7,null,$b$Nđâp klang kô̆ k klơ trôk gĭt êng di yan ma păng; ntơp, rlêng jêh ri klang kreo gĭt mông trơn ntŭk gŭ. Ƀiă lah phung ƀon lan gâp mâu gĭt ôh nau vay Yêhôva!$b$,true),
('bunong-vn','JER',8,8,null,$b$“Mâm khân may dơi lah: “Hên jêng phung blau mĭn, jêh ri nau vay Yêhôva gŭ ndrel hên?” Ƀiă lah aơ, phung kôranh chih sămƀŭt chih nau mƀruh.$b$,true),
('bunong-vn','JER',8,9,null,$b$Bu mra ƀư prêng bunuyh blau mĭn khân păng rdja nuih, klach jêh ri bu nhŭp lơi khân ô băl; aơ, khân ô băl dun nau Yêhôva ngơi, jêh ri moh nau blau mĭn gŭ tâm khân ô băl?$b$,true),
('bunong-vn','JER',8,10,null,$b$Yor nây gâp mra ăn ur khân ô băl ma bu êng jêh ri mir khân ô băl pha bu, yor lah ntơm bơh jê̆ lê̆ tât ma nơm toyh lơn, ăp nơm kơnh ma nau sa kao ma nau kue Ntơm bơh kôranh nơm mbơh lor tât ma kôranh ƀư brah, ăp nơm jêng mƀruh da dê.$b$,true),
('bunong-vn','JER',8,11,null,$b$Khân păng ƀư bah ntŭk sôt phung ƀon lan gâp knŏng djê̆ lê̆, khân păng lah: “Đăp mpăn, đăp mpăn!” Ƀiă lah mâu geh nau đăp mpăn ôh.$b$,true),
('bunong-vn','JER',8,12,null,$b$Khân păng prêng lĕ tơ lah khân păng ƀư jêh nau gâp tâm rmot? Mâu, khân păng mâu mâp prêng ôh; khân păng mâu mâp mpơl muh măt chăng yor nau prêng ôh. Yor nây khân păng mra cha lôt ndrel phung lĕ cha lôt jêh; tơ lah gâp tâm rmal khân păng, khân păng bu mra n'glưh, Yêhôva lah.$b$,true),
('bunong-vn','JER',8,13,null,$b$Yêhôva lah: “N'hêl nanê̆ gâp mra ƀư rai lĕ khân păng. Mâu geh play kriăk ƀâu hôm ta n'gĭng păng; mâu hôm geh play rvi ta tơm rvi; n'ha mra kro rŭng lĕ; moh ndơ gâp ăn ma khân păng, gâp mra sŏk sĭt bơh khân păng.”$b$,true),
('bunong-vn','JER',8,14,null,$b$Mâm ƀư he hôm gŭ mro? Tâm rƀŭn ndrel hom! Ăn he lăp tâm ƀon geh mpêr nâp, jêh ri rai lôch ta nây! Yor lah Yêhôva Brah Ndu he tâm nal jêh nau ƀư rai he, jêh ri ăn he nhêt dak kăch khih, yor lah he ƀư tih jêh đah Yêhôva.$b$,true),
('bunong-vn','JER',8,15,null,$b$He gŭ kâp gân jêh ma nau đăp mpăn, ƀiă lah mâu geh nau ueh tât ôh; he kâp gân jêh nau gŭ mpăn nau dơi ƀư bah, ƀiă lah aơ, tât nkhơng nau krit-klach.$b$,true),
('bunong-vn','JER',8,16,null,$b$Tă bơh nkual Dan bu tăng krĭk seh khân păng tât; tơ lah tăng nteh seh tâm lơh păng nter, lam neh ntu n'găr da dê; yor lah khân păng hŏ tât jêh; khân păng văch gay ƀư rai bri neh jêh ri ndô ndơ tâm bri nây, nđâp ma ƀon jêh ri bunuyh gŭ tâm ƀon nây.$b$,true),
('bunong-vn','JER',8,17,null,$b$Aơ, gâp mra njuăl bêh lăp tâm nklang khân may, bêch rmâng bu mâu dơi ƀư ơih păng ôh, jêh ri khân păng mra kăp khân may.” Yêhôva lah.$b$,true),
('bunong-vn','JER',8,18,null,$b$Nau gâp rngot mâu dơi bah ôh, play nuih gâp khĭt huơi tâm trôm gâp.$b$,true),
('bunong-vn','JER',8,19,null,$b$Iăt hom bâr bu ur phung ƀon lan gâp nhĭm bơh bri ngai, lah: “Yêhôva mâu hôm gŭ tâm ƀon Siôn hĕ? Hađăch ƀon nây mâu hôm gŭ tâm ƀon nây hĕ?” “Mâm ƀư khân păng mbah rup trah jêh ri rup brah bri bu năch gay ƀư nsônh ji nuih gâp pô nây?”$b$,true),
('bunong-vn','JER',8,20,null,$b$“Yan kăch rek rlau jêh, yan ta vai lôch, he mâu geh nau tâm rklaih ôh.”$b$,true),
('bunong-vn','JER',8,21,null,$b$Yor nau sôt phung kon bu ur, phung ƀon lan gâp, jêng nau sôt ma nuih n'hâm gâp yơh, gâp klâng ndrê, jêh ri nau rdja nuih tât ma gâp.$b$,true),
('bunong-vn','JER',8,22,null,$b$Mâm ƀư mâu geh hĕ dak si tâm bri Galaat? Mâu geh ôh hĕ kôranh dak si ta ntŭk nây? Mâm ƀư phung kon bu ur phung ƀon lan gâp mâu geh nau ƀư bah ôh?$b$,true),
('bunong-vn','JER',9,1,null,$b$Ơ, ŭch ma bôk gâp jêng ntu dak, jêh ri măt gâp jêng tu dak măt, pô nây gâp dơi nhĭm nar măng yor ma kon bu ur phung ƀon lan gâp lĕ khĭt jêh!$b$,true),
('bunong-vn','JER',9,2,null,$b$Ơ, gay ma gâp geh tâm ndrêch rdah du ntŭk njưh ma phung nsong. Gay gâp dơi cha lơi ƀon lan gâp jêh ri du ngai bơh khân păng; yor lah lĕ rngôch khân păng jêng bunuyh văng tĭr da dê, nây jêng mpôl ƀlêp-ƀlêr.$b$,true),
('bunong-vn','JER',9,3,null,$b$Khân păng van mpiăt khân păng nâm bu van na, ŭch pănh nau mƀruh; mâu di ôh nau n'hêl nanê̆, ƀiă lah nau mƀruh văch ma toyh tâm nklang bri nây. Yor lah tă bơh khân păng nau mhĭk lơ hâu ntop mhĭk, jêh ri khân păng mâu hôm gĭt năl gâp ôh,” Yêhôva lah.$b$,true),
('bunong-vn','JER',9,4,null,$b$“Ăn ăp nơm njrăng ma nơm chiau meng păng, lơi ta rnơm ir ôh tâm du huê bunuyh, tâm nklang oh nâu păng; yor lah ăp nơm oh nâu jêng nơm rlêch ndơm ndrăng oh nâu ngăn, jêh ri ăp nơm phung chiau meng joi nau ngơi, nchơt ma bu.$b$,true),
('bunong-vn','JER',9,5,null,$b$Ăp nơm ndơm phung chiau meng păng, mâu geh nơm ngơi nau n'hêl nanê̆ ôh; khân păng nti jêh mpiăt khân păng mơng ngơi nau mƀruh, jêh ri ƀư rgănh khân păng nơm ƀư nau kue.$b$,true),
('bunong-vn','JER',9,6,null,$b$Khân păng gŭ tâm nklang nau ndơm, yor tâm nau khân păng ndơm nây yơh mâu ŭch gĭt năl gâp ôh.” Yêhôva lah.$b$,true),
('bunong-vn','JER',9,7,null,$b$Pô ri Yêhôva ma phung ta han lah pô aơ: “Aơ, gâp mra ƀư kloh khân păng ma ŭnh jêh ri rlong uănh khân păng; yor lah tơ lah mâu di pô nây, mâm nau êng gâp lŏ dơi ƀư tay ma phung ƀon lan gâp?”$b$,true),
('bunong-vn','JER',9,8,null,$b$Mpiăt khân păng jêng hăr kăch, bêng ma nau ngơi ndơm; bâr mbung pa dih aơ ăp nơm khân păng ngơi đăp mpăn ma phung chiau meng păng, ƀiă lah tâm nuih n'hâm khân păng, khân păng nkra rơm kâp lơh ma ô băl.$b$,true),
('bunong-vn','JER',9,9,null,$b$Yêhôva lah: “Gâp om mâu mra tâm rmal ôh hĕ khân păng, yor nau aơ?” “Jêh ri gâp, mâu mra har plơng bôk lĕ ma du ndŭl mpôl tâm ban pô aơ?”$b$,true),
('bunong-vn','JER',9,10,null,$b$“Gâp mra nhĭm vơl ma yôk, jêh ri nhĭm ndrê yor ndrêch gơ̆ tâm bri rdah, yor lah lĕ rngôch bu su rai da dê, kŏ tât mâu hôm geh ôh bunuyh prot găn ta nây, jêh ri ta nây mâu hôm tăng ƀuh ndrôk ôh, nđâp sĭm mpăr jêh ri mpô mpa bri lĕ du ƀhiau.$b$,true),
('bunong-vn','JER',9,11,null,$b$Gâp mra njêng ƀon Yêrusalem du ntŭk bu bun ndơ rai jêh, jêng ntŭk so bri gŭ; jêh ri gâp mra ăn lĕ rngôch ƀon n'gor Yuđa jêng rngol, mâu geh bunuyh gŭ ôh.”$b$,true),
('bunong-vn','JER',9,12,null,$b$Mbu nơm jêng bunuyh blau mĭn tât păng dơi gĭt rbăng nau aơ? Ma mbu nơm Yêhôva nti jêh, gay ma păng dơi rblang nau nây? Mâm ƀư lĕ rai jêh, jêh ri jêng rngol nâm bu bri rdah, kŏ tât mâu geh bunuyh prot ta nây ôh?$b$,true),
('bunong-vn','JER',9,13,null,$b$Yêhôva plơ̆ lah: “Yor lah khân păng cha lơi jêh nau vay gâp dơm jêh pa năp khân păng, jêh ri khân păng mâu tông ôh bâr gâp, mâu lĕ khân păng chuat tĭng ndô̆ nau vay nây,$b$,false),
('bunong-vn','JER',9,14,null,$b$ƀiă lah khân păng tĭng ndô̆ nuih n'hâm dăng khân păng nơm, jêh ri tĭng ndô̆ brah Baal, tĭng ndô̆ tĭng nâm u che nti ma khân păng.”$b$,false),
('bunong-vn','JER',9,15,null,$b$Yor nây Yêhôva ma phung ta han, Brah Ndu phung Israel lah: “Aơ, gâp mra siăm phung ƀon lan aơ ma gŭn tăng, jêh ri ăn nhêt dak kăch khih.$b$,false),
('bunong-vn','JER',9,16,null,$b$Gâp mra mprơh khân păng du mblêng ta nklang ndŭl mpôl bunuyh, phung nây khân păng nđâp phung che khân păng mâu mâp gĭt năp lĕ. Jêh ri gâp mra ăn bu nkhĭt khân păng ma đao, tât gâp ƀư rai khân păng lĕ rngôch.”$b$,false),
('bunong-vn','JER',9,17,null,$b$Yêhôva ma phung ta han lah: “Sek uănh hom, jêh ri kuăl phung bu ur nhĭm vơl văch tât, prơh bu hăn kuăl phung bu ur njêh, văch tât;$b$,false),
('bunong-vn','JER',9,18,null,$b$ăn khân păng nhĭm vơl ndrel ma he, gay ma măt he nhĭm luh dak măt, jêh ri rsâng măt he bêng dak măt.$b$,false),
('bunong-vn','JER',9,19,null,$b$Yor lah bu tăng nhĭm vơl tâm ƀon Siôn, lah: ‘Rai yot yơh! He prêng hâu ngăn yơh, yor lah he cha lơi bri neh; yor lah khân păng ƀư rai jêh ntŭk he gŭ.”$b$,true),
('bunong-vn','JER',9,20,null,$b$Ơ phung bu ur, iăt hom nau Yêhôva ngơi, ăn tôr khân may sŏk dơn nau ngơi tă bơh bâr mbung păng; nti hom ma phung kon bu ur khân may du nau nhĭm vơl, jêh ri ăp nơm ma nơm chiau meng păng nau mprơ nhĭm vơl$b$,true),
('bunong-vn','JER',9,21,null,$b$Yor lah nau khĭt tât jêh ma mpông bloh he, jêh ri lăp jêh tâm ngih hađăch he, nkhĭt jêh phung kon se rŏ trong toyh jêh ri phung bu klâu ndăm tâm nhuang ƀon.$b$,false),
('bunong-vn','JER',9,22,null,$b$Ngơi hom, Yêhôva lah pô aơ: “Huêng phan phung khĭt cha lôt nâm bu buh ta mir, nâm bu nchăp ba pa kơi nơm rek, jêh ri mâu geh nơm bun khân păng ôh.’ ”$b$,true),
('bunong-vn','JER',9,23,null,$b$Yêhôva lah pô aơ: “Lơi ta ăn bunuyh blau mĭn tâm rnê ma nau blau mĭn păng nơm ôh, lơi ăn bunuyh ktang tâm rnê êng ma nau ktang păng ôh, lơi ăn bunuyh ndrŏng rnê êng ma nau ndrŏng păng nơm ôh;$b$,true),
('bunong-vn','JER',9,24,null,$b$ƀiă lah ăn nơm tâm rnê, tâm rnê ma păng nơm ma nau aơ nâm bu ntĭt, ma nau păng gĭt rbăng jêh ri gĭt năl gâp jêng Yêhôva, jêng Nơm tâm mpơl nau rŏng, nau n'hêl nanê̆, jêh ri nau sŏng ta neh ntu, yor lah tâm nau aơ gâp maak, Yêhôva lah.$b$,false),
('bunong-vn','JER',9,25,null,$b$“Aơ, nar mra tât,” Yêhôva lah: “Tơ lah gâp mra tâm rmal lĕ rngôch phung koh ntâu ƀiă lah nuih n'hâm ê hŏ koh ntâu ôh,$b$,true),
('bunong-vn','JER',9,26,null,$b$phung Êjipt, phung Yuđa, Êđôm, phung kon sau Y-Amôn, phung Môap, jêh ri lĕ rngôch phung gŭ tâm bri rdah phung poih sŏk plưn. Yor lah lĕ rngôch ntil mpôl bunuyh nây mâu geh nau koh ntâu ôh, jêh ri lĕ rngôch Israel mâu geh nau koh ntâu tâm nuih n'hâm ôh.”$b$,false),
('bunong-vn','JER',10,1,null,$b$Ơ ngih Israel, iăt hom nau Yêhôva lah ma khân may,$b$,true),
('bunong-vn','JER',10,2,null,$b$Yêhôva lah pô aơ: “Lơi ta tĭng ôh trong nau vay bri bu êng, mâu klach lĕ, tơ lah saơ nau tâm mpơl klơ trôk, nđâp lah phung bri êng rdja nuih yor nau nây.$b$,false),
('bunong-vn','JER',10,3,null,$b$Yor lah nau vay mbên phung ƀon lan jêng mƀruh. Bu kăl tơm si tâm krŏng, Jêh ri du huê n'hăk trah meh ma du n'gâr sung.$b$,true),
('bunong-vn','JER',10,4,null,$b$Phung bunuyh mblum tơm si nây đah prăk, mah; sŏk kon nôp pâng kđĭn gay nâp, pô nây păng mâu dơi chôt ôh.$b$,true),
('bunong-vn','JER',10,5,null,$b$Rup brah khân păng jêng nâm bu pla mut nhhu bu, mâu gĭt ngơi ôh; bu tung khân păng yor lah mâu blau chuat. Lơi ta klach ôh ma khân păng, yor lah khân păng mâu dơi ƀư nau mhĭk ôh, mâu lĕ khân păng dơi ƀư nau ueh.”$b$,true),
('bunong-vn','JER',10,6,null,$b$Mâu geh nơm tâm ban ma may! Ơ Yêhôva, may jêng toyh, amoh may jêng toyh jêh ri brah$b$,true),
('bunong-vn','JER',10,7,null,$b$Ơ hađăch ma lam bri dak! Mbu moh mâu klach may? Yor lah nau aơ jêng khư ma may. Yor lah ta nklang lĕ rngôch phung blau mĭn tâm phung mpôl băl bunuyh, jêh ri lĕ rngôch ƀon bri hađăch khân păng, mâu geh ôh nơm tâm ban ma may.$b$,false),
('bunong-vn','JER',10,8,null,$b$Khân păng jêng rluk mâl; rup trah tơm si dơm sâm nti khân păng.$b$,true),
('bunong-vn','JER',10,9,null,$b$Bu djôt leo tă bơh ƀon Tarsis prăk ơm bu chiăr rlat, jêh ri mah bơh bri Uphas. Tă bơh ti phung njêh nkra, jêh ri kan ti nơm chiăr mah, bok khân păng geh bok ĭr bok sut ƀư ao, nây ăt kan phung n'hăk vay ƀư.$b$,true),
('bunong-vn','JER',10,10,null,$b$Ƀiă lah Yêhôva jêng Brah Ndu ngăn; Păng jêng Brah Ndu rêh, jêng hađăch n'ho ro. Tơ lah Păng ji nuih; neh ntu n'găr da dê lĕ rngôch bri dak mâu dơi dơn ôh nau ji nuih Păng.$b$,true),
('bunong-vn','JER',10,11,null,$b$Pô aơ may mra lah ma khân păng: ‘Phung brah aơ mâu mâp njêng ôh phung trôk, jêh ri neh ntu, mra rai yot bơh neh ntu jêh ri bơh tâm dâng phung trôk.’ ”$b$,true),
('bunong-vn','JER',10,12,null,$b$Yêhôva yơh hŏ rhăk jêh neh ntu ma nau brah Păng, hŏ ndâk jêh neh ntu ăn nâp ma nau blau mĭn Păng, jêh ri ma nau gĭt rbăng Păng lăk jêh trôk.$b$,true),
('bunong-vn','JER',10,13,null,$b$Tơ lah Păng ngơi, geh nâm bu nteh rbuh dak tâm phung trôk, Păng ăn dak ngom hao lam ntŭk ta neh ntu. Păng ăn lơp nchrang dôl trôk mih, jêh ri Păng ăn Sial khôm tă luh bơh jay Păng;$b$,true),
('bunong-vn','JER',10,14,null,$b$ăp nơm bunuyh jêng rluk jêh ri mâu geh nau blau mĭn ôh; ăp nơm bunuyh chiăr mah geh nau prêng yor rup brah chiăr jêh, Yor lah rup brah păng jêng brah nklă dơm, jêh ri khân păng mâu blau nsôr n'hâm ôh.$b$,false),
('bunong-vn','JER',10,15,null,$b$Khân păng jêng dơm dam, jêng kan nau ndơm; tât nar bu tâm rmal khân păng, khân păng mra rai yot.$b$,true),
('bunong-vn','JER',10,16,null,$b$Drăp Brah Ndu nơm prăp ma phung Yakôp ndơn mâu jêng tâm ban pô nây ôh, yor lah Păng jêng nơm rhăk njêng lĕ rngôch mpa, jêh ri Israel jêng du ndŭl mpôl ndơn drăp Păng. Amoh Păng jêng Yêhôva ma phung ta han.$b$,true),
('bunong-vn','JER',10,17,null,$b$Ơ phung bu nchueng ŭch lơh, rgum hom ndô ndơ khân may,$b$,true),
('bunong-vn','JER',10,18,null,$b$yor lah Yêhôva lah pô aơ: “Aơ, nar aơ gâp mra mƀăr lơi bunuyh ƀon lan, gŭ tâm neh aơ, gâp mra ăn khân păng rêh ni, ăn khân păng kah gĭt.$b$,false),
('bunong-vn','JER',10,19,null,$b$Rêh ni ngăn ma gâp yor ntŭk sôt gâp! Ntŭk sôt mâu blau bah ôh. Ƀiă lah gâp lah: “Aơ yơh jêng ngăn nau nđêh nji, jêh ri gâp mra dơn nau nây.”$b$,true),
('bunong-vn','JER',10,20,null,$b$Ngih bok gâp rai jêh, jêh ri lĕ rngôch rse kât hŏ tăch da dê, phung kon gâp cha lơi gâp, mâu hôm saơ khân păng ôh; mâu hôm geh bunuyh ôh gay kơl rdâk tay ngih bok gâp, jêh ri kơl nching ntŭk gâp gŭ.$b$,true),
('bunong-vn','JER',10,21,null,$b$Yor lah phung rmăk biăp jêng rluk; jêh ri mâu ôp ma Yêhôva ôh; yor nây khân păng mâu chăt jêng ôh, jêh ri lĕ rngôch biăp khân păng nkhah du êng êng.$b$,true),
('bunong-vn','JER',10,22,null,$b$Aơ, geh tăng bâr mbơh, du nau mhe mhan tât! Nau rŭng răng toyh luh bơh n'gor bri pa lơ, gay ƀư ăn lĕ rngôch ƀon n'gor Yuđa jêng rngol, jêng ntŭk trôm so bri gŭ.$b$,true),
('bunong-vn','JER',10,23,null,$b$Ơ Yêhôva, gâp gĭt bunuyh mâu dơi jêng kôranh ma păng nơm ôh, bunuyh mâu dơi gai nhuat păng chuat ôh.$b$,true),
('bunong-vn','JER',10,24,null,$b$Nkra hom gâp, Ơ Yêhôva, ƀiă lah tĭng nâm nau di, mâu di ôh ma nau may ji nuih, klach lah may ƀư rai lơi gâp.$b$,true),
('bunong-vn','JER',10,25,null,$b$Dăn nkhŭt hom nau may ji nuih ma mpôl băl bunuyh, phung mâu hŏ gĭt năl may ôh ma phung ƀon lan mâu kuăl mbơh sơm ma amoh may ôh. Yor lah khân păng ƀư rai jêh phung Yakôp, jêh ri khân păng ƀư rai lĕ khân ô băl, jêh ri ăn ntŭk khân ô băl jêng rngol.$b$,true),
('bunong-vn','JER',11,1,null,$b$Tă bơh ntŭk Yêhôva, ngơi ma Y-Yêrêmi pô aơ:$b$,true),
('bunong-vn','JER',11,2,null,$b$“Iăt hom nau ngơi ma nau tâm rnglăp aơ, jêh ri ngơi hom ma phung Yuđa jêh ri phung ƀon lan gŭ ta ƀon Yêrusalem,$b$,false),
('bunong-vn','JER',11,3,null,$b$Ăn may lah ma khân păng pô aơ: Yêhôva Brah Ndu Israel lah: ‘Rak rtăp lơi ma bunuyh mâu djôt prăp ôh nau ngơi ma nau tâm rnglăp aơ,$b$,false),
('bunong-vn','JER',11,4,null,$b$gâp ntăm jêh ma phung che khân may, tâm nar gâp hŏ njŭn leo khân păng du luh bơh n'gor bri Êjipt, bơh năk ŭnh loih,’ lah: Iăt hom nau gâp, tĭng kơt ntil nau gâp nti ƀư. Pô ri khân may mra jêng phung ƀon lan gâp, gâp mra jêng Brah Ndu ma khân may;$b$,false),
('bunong-vn','JER',11,5,null,$b$gay ma gâp dơi ƀư nanê̆ nau gâp ton jêh ma phung che khân may, ŭch ăn ma khân păng du n'gor bri geh mpa sông sa rmeh ler,’ tĭng nâm geh jêh nar aơ.” Pô ri gâp plơ̆ lah: “Ăn nau nây dơi tât ngăn, ơ Yêhôva.”$b$,false),
('bunong-vn','JER',11,6,null,$b$Yêhôva lah ma gâp: “Mbơh hom lĕ rngôch nau ngơi aơ tâm ăp ƀon n'gor Yuđa jêh ri tâm n'gŏ trong toyh ƀon Yêrusalem: ‘Iăt hom nau ngơi ma nau tâm rnglăp aơ jêh ri tĭng kơt nau nây.$b$,false),
('bunong-vn','JER',11,7,null,$b$Yor lah gâp hŏ đă ngăn phung leo khân păng du luh bơh n'gor Êjipt n'ho tât nar aơ lah: “Tông hom bâr gâp.”$b$,true),
('bunong-vn','JER',11,8,null,$b$Ƀiă lah khân păng mâu ŭch tông ôh mâu lĕ ŭch rkêng tôr iăt ƀiă lah ăp nơm chuat jêh tĭng ndô̆ nau nuih n'hâm dăng nau mhĭk khân păng nơm ŭch. Yor ri gâp hŏ ƀư jêh ma khân păng ăp ntil ma nau ngơi nduyh ma nau tâm rnglăp aơ, jêng nau gâp hŏ ntăm khân păng tĭng kơt ƀiă lah khân păng mâu tông ôh.’ ”$b$,true),
('bunong-vn','JER',11,9,null,$b$Yêhôva lah ma gâp: “Tâm phung Yuđa jêh ri phung ƀon lan gŭ ta ƀon Yêrusalem geh bunuyh hŏ njêng joi nau tâm rdâng.$b$,true),
('bunong-vn','JER',11,10,null,$b$Khân păng plơ̆ sĭt tay tâm nau tih mhĭk phung che khân păng, jêng phung mâu ŭch tông bâr gâp, jêh ri tĭng ndô̆ brah êng ŭch pah kan ma khân păng. Ngih Israel nđâp ma ngih Yuđa hŏ rlau jêh nau gâp tâm rnglăp, ƀư jêh đah phung che khân păng.$b$,true),
('bunong-vn','JER',11,11,null,$b$Yor nây, Yêhôva lah pô aơ: ‘Aơ gâp ntơm ăn nau mhĭk tât ma khân păng, jêh ri khân păng mâu dơi klaih ôh; nđâp lah khân păng vơl tât ta gâp, ƀiă lah gâp mâu hôm n'gĭl iăt khân păng ôh.$b$,true),
('bunong-vn','JER',11,12,null,$b$Nôk nây, lĕ rngôch ƀon n'gor Yuđa jêh ri phung ƀon lan gŭ tâm ƀon Yêrusalem mra hăn dăn vơl ma brah khân păng, su ndơ ƀâu kah, ƀiă lah brah nây mâu dơi tâm rklaih khân păng ôh; dôl khân păng geh nau rŭng răng.$b$,false),
('bunong-vn','JER',11,13,null,$b$Ơ phung Yuđa, khân may geh âk ƀon toyh, geh âk kơt nây lĕ phung brah khân may; Yêrusalem geh âk trong toyh, khân may ăt njêng âk tâm ban lĕ nơng su ndơ ƀâu kah ma brah Baal.’$b$,true),
('bunong-vn','JER',11,14,null,$b$Pô ri khân may lơi mbơh sơm ôh kơl phung ƀon lan aơ, mâu lĕ dơi vơh vơl mâu lah dăn nau kơl ăn ma khân păng, yor lah gâp mâu mra iăt ôh; tơ lah khân păng kuăl mbơh sơm ma gâp, dôl khân păng geh nau rŭng răng.$b$,false),
('bunong-vn','JER',11,15,null,$b$“Moh nau khư ma nơm gâp rŏng, tơ lah păng hŏ ƀư âk nau djơh mhĭk; jêh ri mham kloh lĕ du jêh bơh păng, hôm văch tât đŏng tâm ngih gâp? Ƀiă lah păng hôm ƀư nau răm maak dôl păng ƀư tih jêh?$b$,true),
('bunong-vn','JER',11,16,null,$b$Sa ơm Yêhôva ntơ ma păng tơm play Ôlivơ ndrêh, ueh uănh nđâp ma play rkŭm âk! Aơ n'gôr phŭt sial toyh, Yêhôva su ŭnh ta tơm nây, lĕ rngôch n'gĭng păng đoh lĕ.$b$,false),
('bunong-vn','JER',11,17,null,$b$Yêhôva ma phung ta han, jêng nơm bôr tơm tăm khân may, mbơh jêh nau mhĭk mra ƀư ma khân may, yor nau mhĭk ngih Israel jêh ri ngih Yuđa ƀư jêh, nsônh nuih ăn gâp ji nuih yor khân may su ndơ ƀâu kah ăn ma brah Baal?$b$,true),
('bunong-vn','JER',11,18,null,$b$Yêhôva hŏ mbơh ăn gâp gĭt nau nây, jêh ri gâp lĕ gĭt jêh; Păng hŏ mpơl jêh ma gâp nau mhĭk khân păng ƀư,$b$,true),
('bunong-vn','JER',11,19,null,$b$Bi gâp, nâm bu du mlâm kon biăp rdơ̆ rbăn bu têk leo tât ntŭk bu sreh nkhĭt. Gâp mâu gĭt khân păng joi nau ŭch ƀư mhĭk ma gâp, jêh ri lah: “Ƀư rai hom nđâp tơm jêh ri play păng, kăl mƀăr lơi păng bơh neh ntu phung gŭ rêh, gay ăn amoh păng bu mâu hôm kah gĭt đŏng ôh.$b$,false),
('bunong-vn','JER',11,20,null,$b$Ơ Yêhôva ma phung ta han! May phat dôih ma nau sŏng, mêt uănh nuih n'hâm jêh ri nau mĭn, gay gâp saơ nau may har plơng bôk khân păng, yor lah gâp mpơl jêh kan gâp ma may.$b$,false),
('bunong-vn','JER',11,21,null,$b$Yor nây Yêhôva lah pô aơ ma phung Anathôt, joi ŭch nkhĭt may, jêh ri lah: ‘Tơ lah may mâu ŭch khĭt ma ti gâp, pô ri lơi mbơh ôh amoh Yêhôva.’$b$,true),
('bunong-vn','JER',11,22,null,$b$Pô ri, Yêhôva ma phung ta han lah pô aơ: Aơ, gâp mra tâm rmal khân păng; phung bu klâu ndăm mra khĭt ma đao tak, phung kon bu klâu, kon bu ur khân păng mra khĭt yor nau sa sât ji ngot;$b$,false),
('bunong-vn','JER',11,23,null,$b$mâu geh du huê khân păng dơi klaih ôh. Yor lah tât năm gâp mra tâm rmal, gâp mra ăn nau mhĭk tât ma phung bu klâu ƀon Anathôt.’ ”$b$,false),
('bunong-vn','JER',12,1,null,$b$Ơ Yêhôva, gâp mbơh ma may, may jêng nơm sŏng; nđâp lah pô nây, gâp ŭch mbơh đŏng ma may. Mâm ƀư kan phung ƀai dơi chăt jêng? Mâm ƀư phung ƀlêp ƀlêr dơi đăp rmên?$b$,true),
('bunong-vn','JER',12,2,null,$b$May hŏ bôr tăm khân păng, khân păng jŭr reh; văch ma toyh jêh ri geh play. Bâr mbung khân păng ngơi ueh ma may, ƀiă lah nuih n'hâm khân păng ƀah ngai ma$b$,false),
('bunong-vn','JER',12,3,null,$b$Ơ Yêhôva, may gĭt jêh gâp, saơ jêh gâp, jêh ri rlong uănh nau mĭn gâp đah may. Têk hom khân păng luh pa dih nâm bu biăp bu têk tât ntŭk bu ŭch sreh nkhĭt, jêh ri nkhah êng khân păng ma nar sreh nkhĭt.$b$,false),
('bunong-vn','JER',12,4,null,$b$Tâm n'gor bri nây ndah jŏ bu klâng ndrê, gơ̆ nse tâm ndrêch kro lĕ mâu hôm blau ntĭt? Yor nau ƀai phung gŭ tâm bri nây ƀư, mpô mpa bri jêh ri sĭm och rai yot da dê. Yor lah khân păng lah: “Păng mâu mra saơ nau tât nglĕ dŭt ma he!” Nau Yêhôva plơ̆ lah,$b$,true),
('bunong-vn','JER',12,5,null,$b$“Tơ lah may mâp nchuăt jêh ndrel ma bu, jêh ri khân păng ƀư rgănh may jêh, mâm may dơi tâm rlong nchuăt đah seh lĕ? Tơ lah tâm n'gor nđik mpăn, may dơi đăp rmên, ƀiă lah tơ lah dak krong Yurdan toyh ler bong, mâm may mra ƀư?$b$,false),
('bunong-vn','JER',12,6,null,$b$Yor lah nđâp phung oh nâu may nơm jêh ri ngih mbơ̆ may ƀlêp ƀlêr đah may, khân păng troh nter ŭch ƀư ma may. Nđâp lah khân păng ngơi ueh, may lơi ta iăt ôh!$b$,true),
('bunong-vn','JER',12,7,null,$b$“Gâp cha lơi jêh ngih gâp; hŏ cha lơi jêh drăp gâp ndơn; gâp jao jêh nơm nuih n'hâm gâp rŏng tâm ti phung rlăng păng.$b$,true),
('bunong-vn','JER',12,8,null,$b$Drăp gâp ndơn lĕ jêng jêh ma gâp nâm bu du mlâm yau mŭr tâm krŏng. Păng ngrông tâm rdâng đah gâp, yor nây gâp tâm rmot ma păng.$b$,true),
('bunong-vn','JER',12,9,null,$b$Drăp gâp ndơn, lĕ jêng ma gâp nâm bu du mlâm klang lĕ? Âk klang grât gŭ văr jŭm ŭch ƀư ma păng lĕ? Hăn tâm rƀŭn hom lĕ rngôch mpô mpa bri, njŭn leo ô băl ăn sa drăp găp ndơn nây.$b$,true),
('bunong-vn','JER',12,10,null,$b$Geh âk phung rmăk biăp ƀư rai jêh mir play kriăk ƀâu gâp, khân păng jot nkrâm drăp ndơn gâp tâm dâng mpang jâng, khân păng njêng ntŭk gâp răm maak jêng nâm bu ntŭk bri rdah.$b$,true),
('bunong-vn','JER',12,11,null,$b$Bu ƀư ma neh aơ jêng rngol jêh; yor nau bu ƀư rai nây, bu nhĭm vơl ma gâp. Lam bri lĕ jêng rngol da dê, yor lah mâu geh bunuyh chrê ôh ma nau nây.$b$,false),
('bunong-vn','JER',12,12,null,$b$Phung ƀư rai lĕ tât jêh ta klơ ăp mpư̆ yôk hil ntŭk bri rdah; yor lah đao dao Yêhôva ƀư rai ntơm bôl neh aơ tât bôl neh đah ri; mâu geh nau đăp mpăn ôh.$b$,true),
('bunong-vn','JER',12,13,null,$b$Khân păng srih jêh ba ƀiă lah rek nkhơng lok; khân păng pah kan hŏt rgănh ƀiă lah mâu geh nau khlay ôh, khân may mra prêng ma play khân may rek ƀhôi, yor lah nau Yêhôva ji nuih hâu ngăn.”$b$,true),
('bunong-vn','JER',12,14,null,$b$Yêhôva lah pô aơ: Lĕ rngôch phung chiau meng mhĭk ma gâp, jêng phung sŏk rvan drăp gâp ndơn prăp ăn ma phung ƀon lan gâp, jêng Israel. Aơ, gâp mra rôk khân păng bơh bri khân păng nơm, jêh ri rôk ngih Yuđa du luh bơh tâm nklang khân păng.$b$,true),
('bunong-vn','JER',12,15,null,$b$Ƀiă lah, tơ lah gâp hŏ rôk jêh, gâp ăt mra lĕ plơ̆ đŏng yô̆ yai khân păng, gay khân păng dơi geh drăp ndơn da dê, jêh ri plơ̆ sĭt ma bri khân păng nơm.$b$,false),
('bunong-vn','JER',12,16,null,$b$Tơ lah khân păng gơih nti gay gĭt rbăng trong phung ƀon lan gâp, ŭch ton săk ma amoh gâp, lah: ‘Tĭng nâm Yêhôva rêh!’ Nâm bu khân păng hŏ nti jêh phung ƀon gâp ton săk đah brah Baal, nôk nây gâp mra ndâk khân păng ta nklang phung ƀon lan gâp.$b$,false),
('bunong-vn','JER',12,17,null,$b$Ƀiă lah tơ lah du ndŭl mpôl bunuyh mâu ŭch iăt ôh, pô ri gâp mra rôk ƀư rai lơi khân păng lĕ ƀhiau.” Yêhôva lah.$b$,false),
('bunong-vn','JER',13,1,null,$b$Yêhôva lah ma gâp pô aơ: “Hăn hom, rvăt du blah bok mhay vân bŭt, jêh ri vân ta bŭt may; ƀiă lah lơi ta mbŭk păng ma dak ôh.”$b$,true),
('bunong-vn','JER',13,2,null,$b$Pô ri gâp tông bâr Yêhôva, rvăt bok mhay, vân ta bŭt gâp.$b$,false),
('bunong-vn','JER',13,3,null,$b$Nau Yêhôva lah ma gâp tơ̆ bar pô aơ:$b$,true),
('bunong-vn','JER',13,4,null,$b$“Sŏk hom bok may hŏ rvăt lĕ vân jêh ta bŭt may; jêh ri dâk hăn hom tât ta dak krong Ơphrat, jêh ri pôn tâm nđa lŭ ta nây.$b$,false),
('bunong-vn','JER',13,5,null,$b$Gâp hăn pôn păng ta kơh dak krong, tĭng nâm nau Yêhôva ntăm jêh ma gâp.$b$,true),
('bunong-vn','JER',13,6,null,$b$Jŏ nar jêh nây, Yêhôva lah đŏng ma gâp pô aơ: “Hăn dâk hom, hăn tât ta kơh krong Ơphrat, sŏk bok gâp hŏ đă may pôn ta nây.”$b$,false),
('bunong-vn','JER',13,7,null,$b$Jêh ri gâp hăn tât ta dak krong Ơphrat; kuyh neh sŏk bok tă ntŭk gâp pôn sa ơm ri. Ƀiă lah bok lĕ ôm jêh, mâu hôm jêng dŏng ôh.$b$,false),
('bunong-vn','JER',13,8,null,$b$Pô ri, nau Yêhôva lah ma gâp:$b$,true),
('bunong-vn','JER',13,9,null,$b$“Yêhôva lah pô aơ: Tâm ban lĕ gâp mra ƀư roh lơi nau sưr phung Yuđa jêh ri nau sưr toyh ƀon Yêrusalem.$b$,false),
('bunong-vn','JER',13,10,null,$b$Phung ƀon lan mhĭk aơ dun mâu ŭch iăt ôh nau gâp, chuat tĭng nau dăng nuih n'hâm khân păng nơm ŭch; jêh ri tĭng ndô̆ phung brah êng ŭch pah kan jêh ri mbah yơk ma khân păng, mra jêng nâm bu bok vân bŭt aơ, mâu hôm jêng dŏng ôh.$b$,false),
('bunong-vn','JER',13,11,null,$b$Yêhôva lah: Nâm bu bok krêp ta bŭt may, pô ri yơh gâp gay lĕ rngôch ngih Israel jêh ri lĕ rngôch ngih Yuđa krêp đah gâp, gay ma khân păng dơi jêng phung ƀon lan gâp, ăn amoh gâp dơi lư n'găr, jêng nau tâm rnê gâp, jêh ri jêng nau chrêk lơp. Ƀiă lah khân păng mâu ŭch iăt gâp ôh.$b$,true),
('bunong-vn','JER',13,12,null,$b$“Ăn may lah ma khân păng nau aơ: ‘Pô aơ Yêhôva Brah Ndu Israel lah: Di ngăn, lĕ rngôch yăng mra bêng ma dak kriăk ƀâu.’ Tơ lah khân păng lah ma may: Hên ê hŏ gĭt lĕ rngôch yăng mra bêng ma dak play kriăk ƀâu da dê hĕ?’$b$,true),
('bunong-vn','JER',13,13,null,$b$Jêh ri ăn may lah ma khân păng: ‘Yêhôva lah pô aơ: Aơ, gâp mra ăn lĕ rngôch phung gŭ tâm bri aơ nhŭl ndrănh, phung hađăch gŭ ta sưng hađăch Đavit, phung kôranh ƀư brah, phung kôranh nơm mbơh lor, jêh ri lĕ rngôch phung gŭ tâm ƀon Yêrusalem nhŭl ndrănh da dê.$b$,false),
('bunong-vn','JER',13,14,null,$b$Gâp mra ăn khân păng tâm tom ndrăng nơm, mbơ̆ ma đah kon, Yêhôva lah; Gâp mâu mra yô̆ mâu lah nhhuach ma khân păng ôh, gay ma gâp dơi ƀư rai khân păng.’ ”$b$,false),
('bunong-vn','JER',13,15,null,$b$Rkêng tôr iăt hom, lơi ta sưr, yor lah Yêhôva lah jêh.$b$,true),
('bunong-vn','JER',13,16,null,$b$Nhhơr hom nau chrêk lơp ăn Yêhôva Brah Ndu khân may lor ma Păng ê hŏ ăn nau ngo tât, lor ma păng khân may ê hŏ chêh prah ta klơ yôk dôl ngo nsrŭp măng, rnôk nây khân may kâp nau ang, ƀiă lah Păng mra rgâl jêng ngo, jêh ri njêng ăn geh nau ngo vêt vê.$b$,true),
('bunong-vn','JER',13,17,null,$b$Tơ lah khân may mâu ŭch iăt ôh, huêng gâp mra nhĭm ndâp yor nau sưr khân may. Nanê̆, măt gâp mra nhĭm rngot ngăn, jêh ri hoch truh dak măt, yor lah phung biăp Yêhôva bu mra nhŭp rdu.$b$,true),
('bunong-vn','JER',13,18,null,$b$Lah hom ma hađăch jêh ri hađăch bu ur: “Gŭ dêh rhêt hom, n'hôi săk gŭ tâm neh; yor lah đon hađăch chrêk lơp klơ bôk lĕ tŭp jêh.”$b$,true),
('bunong-vn','JER',13,19,null,$b$Lĕ rngôch ƀon bri rđŭng pa dâng bu mra nchăng da dê, mâu geh ôh bunuyh dơi pơk; lĕ rngôch phung Yuđa lĕ bu nhŭp djôt leo jêh, bu djôt leo khân păng ma bri êng da dê.$b$,true),
('bunong-vn','JER',13,20,null,$b$N'gor hom măt may jêh ri uănh, phung văch tât tă bơh dor pa lơ. Ta ntŭk phung biăp ueh-reh bu hŏ ăn jêh ma may?$b$,true),
('bunong-vn','JER',13,21,null,$b$Tơ lah Yêhôva dơm phung may hŏ nti jêh jêng mĭt jiăng may sa ơm, ƀư kôranh chiă uănh may, mâm may mra lah? Nau rngot rvê bu mâu nhŭp hĕ may nâm bu nhŭp bu ur dôl veng deh?$b$,true),
('bunong-vn','JER',13,22,null,$b$Jêh ri tơ lah may lah êng tâm trôm nuih n'hâm pô aơ: “Mâm ƀư nau aơ tât nkhơng ma gâp?” Nây jêng yor nau tih may toyh ngăn, yor ri bu plơk ntôr aơ may, jêh ri bu mbang ndơl jâng may.$b$,true),
('bunong-vn','JER',13,23,null,$b$Dơi lĕ du huê Êthiôpi tâm rgâl ntâu păng, mâu lah yau brăch tâm rgâl nau rvanh păng? Tơ lah dơi, pô ri lĕ rngôch khân may jêng phung hŏ mơng ƀư mhĭk jêh, mra dơi yơh ƀư ueh.$b$,true),
('bunong-vn','JER',13,24,null,$b$Pô ri gâp mra ƀư chah rai khân may nâm bu lâk sial đô̆, sial bơh ntŭk bri rdah khôm rdu.$b$,true),
('bunong-vn','JER',13,25,null,$b$Yêhôva lah: “Aơ yơh jêng nau prăp ma may, kô̆ nau gâp ntăm ma may. Yor lah may chuêl gâp jêh ri may Rnơm ma nau mƀruh.$b$,true),
('bunong-vn','JER',13,26,null,$b$Gâp nơm plơk ntôr ao may tât ta muh măt may, jêh ri bu mra saơ nau bêk prêng may.$b$,true),
('bunong-vn','JER',13,27,null,$b$Gâp saơ jêh nau mhĭk may ƀư nau may văng tĭr, jêh ri nau may kơnh ƀơ̆ bu, nau văng tir may ta klơ gôl jêh ri tâm mir. Rêh ni ngăn yơh ma may, Ơ ƀon Yêrusalem! Ndah jŏ may mra ƀư kloh?”$b$,true),
('bunong-vn','JER',14,1,null,$b$Nau Yêhôva ngơi ma Y-Yêrêmi di ma nau prăng phang:$b$,true),
('bunong-vn','JER',14,2,null,$b$“N'gor Yuđa dôl klâng ndrê jêh ri lĕ rngôch ƀon păng rngot rvê; khân păng nsoh ao trŭm (krăk) da dê, nhĭm vơl yor neh; jêh ri bu tăng bâr ƀon Yêrusalem vơh vơl.$b$,false),
('bunong-vn','JER',14,3,null,$b$Phung kôranh păng prơh hăn phung oh mon joi dak; khân păng tât ta ndrâm ntu, ƀiă lah lah mâu saơ dak ôh, khân plơ̆ sĭt yăng dơm; khân păng prêng, rŭng răng, jêh ri khân păng nkŭm bôk khân păng.$b$,true),
('bunong-vn','JER',14,4,null,$b$Yor lah neh lĕ đang jêh ntơm bơh trôk mâu hôm tŭp mih, phung ƀư mir lĕ ra-ai jêh, khân păng juăl ti ta bôk khân păng.$b$,true),
('bunong-vn','JER',14,5,null,$b$Nđâp ma jun me deh kon tâm rlâu bri cha lơi kon păng mhe deh, yor lah mâu hôm geh gơ̆ nse ôh.$b$,true),
('bunong-vn','JER',14,6,null,$b$Seh bri gŭ ta klơ n'glơn yôk hil, khân păng nsôr n'hâm nâm bu so bri; măt khân păng lĕ huănh yor mâu geh gơ̆ sa.”$b$,true),
('bunong-vn','JER',14,7,null,$b$“Nđâp lah nau kue hên mbơh tâm rdâng đah hên, ƀư hom, Ơ Yêhôva, yor amoh may. Yor lah nau hên lĕ cha lơi jêh jêng âk; hên ƀư tih đah may jêh.$b$,true),
('bunong-vn','JER',14,8,null,$b$Ơ Yêhôva, jêng Nơm phung Israel kâp gân, Nơm tâm rklaih khân păng tâm rnôk uh ah, Mâm ƀư may jêng nâm bu du huê tâm n'gor, nâm bu du huê hăn nsong trong ngai veh bêch knŏng du măng?$b$,true),
('bunong-vn','JER',14,9,null,$b$Mâm ƀư may nâm bu bunuyh ndrăng, mâu hôm blau ƀư du ntil ndơ, nâm bu du huê dăng ktang mâu dơi tâm rklaih bu ôh? Ơ Yêhôva! Nđâp lah pô nây, may ăt hôm gŭ ta nklang hên! Jêh ri hên dơi ntơ ma amoh may, dăn may lơi ta cha lơi hên ôh!$b$,true),
('bunong-vn','JER',14,10,null,$b$Yêhôva lah ma phung ƀon lan aơ pô aơ: “Khân păng ŭch nkhah du pô nây, khân păng mâu mâp nkân ôh jâng khân păng; yor lah Yêhôva mâu hôm sŏk dơn ôh khân păng, aƀaơ Păng lĕ kah gĭt ma nau kue khân păng, jêh ri rmal lơi ma nau tih khân păng.”$b$,true),
('bunong-vn','JER',14,11,null,$b$Yêhôva lah ma gâp: “Lơi ta mbơh sơm ôh ăn nau ueh ma phung ƀon lan aơ.$b$,true),
('bunong-vn','JER',14,12,null,$b$Nđâp lah khân păng ver, ât sông sa kđôi lĕ, gâp mâu mra iăt nau khân păng vơh vơl, jêh ri nđâp lah khân păng nhhơr mpa nhhơr gŭch mâu lah mpa nhhơr rnih muy kđôi lĕ, gâp mâu mra dơn ôh ndơ khân păng; ƀiă lah gâp mra ƀư rai khân păng ma đao, ma nau sa sât ji ngot, jêh ri ma nau ji ntưp.”$b$,false),
('bunong-vn','JER',14,13,null,$b$Jêh ri gâp lah: Ơ Yêhôva Brah Ndu! Aơ, phung kôranh nơm mbơh lor lah ƀa ƀơ ma khân păng pô aơ: Khân may mâu mra saơ đao dao, mâu mra geh nau sa sât ji ngot lĕ, ƀiă lah n'hêl nanê̆ gâp mra ăn nau đăp mpăn mro mrăng ma khân may gŭ tâm ntŭk aơ.”$b$,true),
('bunong-vn','JER',14,14,null,$b$Yêhôva lah đŏng ma gâp pô aơ: “Nây jêng nau ngơi mƀruh, phung kôranh nơm mbơh lor n'hi amoh săk gâp mbơh nklă. Gâp mâu mâp prơh ôh khân păng hăn, mâu mâp ntăm nau, mâu mâp lah ma khân păng. Khân păng mbơh lor nây nau tâm saơ mâu geh n'hêl nanê̆ ăn ma khân may, nau ƀŭk rƀên dơm dam, jêh ri nau ndơm luh bơh nau mĭn khân păng nơm.$b$,true),
('bunong-vn','JER',14,15,null,$b$Yor nây, Yêhôva lah pô aơ lĕ rngôch phung mbơh lor mâu geh tă luh bơh gâp, ngơi mƀruh n'hi amoh săk gâp, lah pô aơ: ‘Tâm n'gor bri aơ mâu mra geh đao dao, jêh ri sa sât ji ngot! Phung nơm mbơh lor ro yơh bu mra ƀư rai ma đao dao, jêh ri sa sât ji ngot,$b$,false),
('bunong-vn','JER',14,16,null,$b$jêh ri lĕ rngôch phung ƀon lan iăt jêh nau khân păng mbơh nây, mra rai nđâp ma ur, phung kon bu klâu, kon bu ur khân păng khĭt yor đao dao, sa sât ji ngot bu klŭp mƀăr n'gŏ trong ƀon toyh Yêrusalem, mâu geh bunuyh tâp ôh khân păng. Yor lah gâp mra nkhŭt nau ƀai khân păng ta klơ khân păng nơm.$b$,false),
('bunong-vn','JER',14,17,null,$b$Ăn may lah ma khân păng pô aơ: “Ăn măt gâp hoch dak măt nar măng mâu dơi rlu, yor lah kon druh ƀon lan gâp hôm klen, rmanh jru nđêh nji ngăn.$b$,true),
('bunong-vn','JER',14,18,null,$b$Tơ lah gâp hăn tâm mir, ta nây saơ phung bunuyh khĭt bu ntâp ma đao! Tơ lah gâp lăp tâm ƀon, ta aơ, geh bunuyh ji kuet yor ât ji ngot! Yor lah phung nơm mbơh lor jêh n'gâng kan ƀư brah khân păng nơm yơh hăn nsong tâm bri nây, ƀiă lah khân păng mâu geh nau gĭt rbăng ôh.”$b$,true),
('bunong-vn','JER',14,19,null,$b$Pô ri may lĕ cha lơi ngăn hĕ phung Yuđa? May tâm rmot ngăn hĕ ma phung ƀon lan Siôn? Mâm ƀư may dong hên, tât hên mâu hôm dơi săm bah ôh? Hên kâp gân ma nau đăp mpăn, ƀiă lah nau ueh mâu tât ôh; hên kâp gân ma nau ƀư bah, ƀiă lah, aơ mâp nau krit klach.$b$,true),
('bunong-vn','JER',14,20,null,$b$Ơ Yêhôva, hên gĭt saơ jêh ntil nau tih mhĭk hên jêh ri nau tih phung chô-yau phung hên; yor lah hên hŏ ƀư tih da dê jêh đah may.$b$,true),
('bunong-vn','JER',14,21,null,$b$Lơi ta dun ma hên ôh, yor amoh may nơm. Lơi ƀư prêng ôh sưng hađăch chrêk lơp may; kah gĭt hom nau tâm rnglăp đah hên, lơi ta ƀư rai lơi nau nây ôh.$b$,true),
('bunong-vn','JER',14,22,null,$b$Geh lĕ phung brah bri bu êng geh nau dơi ăn tât geh dak mih? Dơi lĕ geh dak mih tŭp tă bơh klơ trôk? Ơ Yêhôva Brah Ndu hên may mâu jêng Nơm nây hĕ? Yor ri hên mra kâp gân may, yor lah may hŏ njêng jêh lĕ rngôch ntil nây.$b$,true),
('bunong-vn','JER',15,1,null,$b$Yêhôva lah jêh ma gâp, pô aơ: Nđâp lah Y-Môis jêh ri Y-Samuel gŭ dâk pa năp măt gâp, ƀiă lah nuih n'hâm gâp mâu hôm plơ̆ sĭt n'gĭl kơl phung ƀon lan aơ ôh. Mprơh du khân păng, du ngai bơh muh măt gâp; jêh ri ăn khân păng hăn du!$b$,true),
('bunong-vn','JER',15,2,null,$b$Tơ lah khân păng ôp ma may, lah: ‘Ta ntŭk hên mra hăn?’ Ăn may lah ma khân păng; ‘pô aơ Yêhôva lah: “Phung bu thăm jêh ma nau khĭt, mra khĭt; phung bu thăm ma đao dao, mra ƀư nkhĭt ma đao dao; phung bu thăm ma nau ât ji ngot, mra khĭt ma nau ji ngot; phung bu thăm ma nau jêng bună, mra jêng bună.’$b$,true),
('bunong-vn','JER',15,3,null,$b$Yêhôva lah: “Gâp mra tâm nal ma khân păng geh puăn ntil ndơ ƀư rai; đao dao prăp ƀư nkhĭt, so kăp sa hêk, sĭm mpăr jêh ri mpô mpa bri mra kăp sa jêh ri ƀư rai.$b$,false),
('bunong-vn','JER',15,4,null,$b$Yor tă Manasê, kon bu klâu Y-Hêsêkia, hađăch Yuđa, jêh ri yor ma lĕ ntil ndơ păng ƀư trong ƀon Yêrusalem gâp njêng khân păng jêng ndơ bu klŭp hăn klŭp sĭt tâm ăp bri dak ta neh ntu aơ.$b$,true),
('bunong-vn','JER',15,5,null,$b$Ơ Yêrusalem, mbu moh hôm yô̆ an ma may? Mbu klâng ndrê ma may? Mbu nơm mra veh ôp ma nau tât ma may?$b$,true),
('bunong-vn','JER',15,6,null,$b$Yêhôva lah: “May hŏ dun jêh ma gâp, jêh ri may ăt hôm cha lơi mro mrăng; yor nây yơh gâp mra yơr ti gâp gay ƀư rai may, jêh ri gâp mâu hôm yô̆ ma may đŏng ôh.$b$,true),
('bunong-vn','JER',15,7,null,$b$Gâp hŏ sŏk dông nsiăng khân păng ta bôk mpông ƀon toyh bri neh aơ. Gâp mra ăn khân păng nhĭm nhhiăng ma kon sau khân păng, jêh ri gâp mra ƀư rai phung ƀon lan gâp, yor khân păng mâu ŭch plơ̆ rŭch bơh trong tih khân păng.$b$,true),
('bunong-vn','JER',15,8,null,$b$Gâp mra ăn phung bu ur ndrô sai khân păng ntop âk lơn choih mƀŭt. Gâp mra ăn phung rlăng ƀư rai ta nar nklang bôk, ƀư ma mê̆ phung bu klâu ndăm. Gâp mra ăn nau rngot klâng krit klach nau tât ƀư nau khân păng ƀât lât.$b$,true),
('bunong-vn','JER',15,9,null,$b$Du huê bu ur hŏ deh pơh nuyh kon mra khĭt huăr jêh ri roh n'hâm. Nau ang păng rlơ̆ jêng ngo dôl hôm e măt nar; bu mra suai rak jêh ri ƀư prêng ma păng. Bi ma phung khân păng hôm klen, gâp mra jao ma phung rlăng nkhĭt ma chiông đao.” Yêhôva lah.$b$,true),
('bunong-vn','JER',15,10,null,$b$Rêh ni ngăn ma gâp, Ơ mê̆ ơi! Yor lah ay hŏ deh jêh ma gâp, jêng bunuyh mâp nau tâm rlăch tâm dun yor ma tâm lĕ du bri! Gâp mâu mâp ăn bu manh ôh, mâu lĕ mâp gâp manh bu, ƀiă lah lĕ rngôch khân păng rtăp rak ma gâp.$b$,true),
('bunong-vn','JER',15,11,null,$b$Ƀiă lah Yêhôva lah jêh: “N'hêl nanê̆ gâp mra tâm rklaih may prăp ma kan khlay. Tơ lah dôl geh nau rŭng răng jêh ri nau rêh ni, n'hêl nanê̆ gâp mra ăn phung rlăng may vơh vơl ma may.$b$,true),
('bunong-vn','JER',15,12,null,$b$Loih jêh ri kông luh bơh bri dor pa lơ, dơi lĕ bu kêch păng?$b$,true),
('bunong-vn','JER',15,13,null,$b$Yor tă nau tih khân ay may ƀư jêh, lam lĕ kual bri dak khân ay may, gâp mra jao drăp ndơ khlay ma phung pit in sŏk dơm, mâu ăn rnoh khlay ôh.$b$,true),
('bunong-vn','JER',15,14,null,$b$Gâp mra ƀư ăn lĕ rngôch ndô ndơ nây hăn ndrel ma phung rlăng may, tâm bri may mâu hŏ gĭt năl, yor nau gâp ji nuih geh ŭnh hit jêh ri hit mra, gay su ƀư rai khân may.”$b$,true),
('bunong-vn','JER',15,15,null,$b$Ơ Yêhôva! May hŏ gĭt vât jêh. Dăn kah gĭt hom ma gâp, chop khâl gâp, jêh ri har plơng bôk ma phung ƀư mhĭk ma gâp. Lơi ta may mƀăr lơi gâp tâm nau bu rak suai may; ăn may kah gĭt ma gâp yor gâp may dơn nau bu nduyh!$b$,true),
('bunong-vn','JER',15,16,null,$b$Gâp lĕ tăng nau may ngơi, jêh ri gâp hŏ sa rvăn jêh, nau may ngơi jêng nau răm rhơn ma gâp, jêh ri ƀư nau hâk maak nuih n'hâm gâp tâm ban lĕ. Ơ Yêhôva Brah Ndu ma phung ta han, yor lah gâp bu dơi ntơ ma amoh may!$b$,true),
('bunong-vn','JER',15,17,null,$b$Gâp mâu gŭ ndrel ma phung bu pâl rlưn răm maak; ƀiă lah gâp gŭ êng du huê yor ti may dra ta gâp; yor lah may mbêng jêh gâp bêng nau ji nuih.$b$,true),
('bunong-vn','JER',15,18,null,$b$Mâm ƀư nau, nđêh nji tâm gâp ăt hôm e mro? Mâm ƀư nau sôt gâp mâu dơi săm jêh ri păng mâu blau bah ôh? May mra njêng lĕ ăn ma gâp nâm bu dak n'hor ndơm, tâm ban tu dak lĕ suăt dak tu?$b$,true),
('bunong-vn','JER',15,19,null,$b$Yor nây, Yêhôva lah pô aơ: “Tơ lah may nhăl rmal, gâp mra njêng tay may gay ma may dơi pah kan ma gâp. Tơ lah may mbơh nau khlay jêh ri mâu ngơi ôh nau lă lêng, may mra jêng nâm bu bâr mbung gâp, khân păng mra plơ̆ sĭt ndrel may; ƀiă lah may lơi ta plơ̆ sĭt ndrel ma khân păng.$b$,true),
('bunong-vn','JER',15,20,null,$b$Gâp mra ăn may jêng mpêr kông nâp ma phung ƀon lan aơ, khân păng mra tâm lơh đah may, ƀiă lah khân păng mâu mra dơi đah may ôh, yor lah gâp mra gŭ ndrel may, gay rklaih may jêh ri ăn may jêng kon me. Yêhôva lah.$b$,true),
('bunong-vn','JER',15,21,null,$b$“Gâp mra rklaih may bơh ti phung ƀai, jêh ri sâm chuai may bơh phung djơh mhĭk.$b$,true),
('bunong-vn','JER',16,1,null,$b$Nau Yêhôva lah ma gâp pô aơ:$b$,true),
('bunong-vn','JER',16,2,null,$b$“Lơi may gŭ ur, mâu dơi lĕ deh phung bu klâu mâu lah kon bu ur tâm ntŭk aơ.”$b$,false),
('bunong-vn','JER',16,3,null,$b$Yor lah Yêhôva lah pô aơ ma phung kon bu klâu jêh ri bu ur bu deh tâm ntŭk aơ, jêh ri ma phung me mbơ̆ nơm hŏ deh khân păng tâm neh aơ, nâm bu pô aơ:$b$,false),
('bunong-vn','JER',16,4,null,$b$“Khân păng mra khĭt ma nau ji ntưp ƀư nkhĭt, mâu geh bunuyh nhĭm ăt mâu lĕ geh bunuyh tâp brôi khân păng; săk jăn khân păng mra jêng nâm bu buh ta klơ neh. Khân păng khĭt ma mpiăt đao jêh ri ât ji ngot, jêh ri nting nđăng khân păng mra jêng mpa sa ma phung sĭm mpăr jêh ri ma mpô mpa bri.”$b$,false),
('bunong-vn','JER',16,5,null,$b$Yêhôva lah pô aơ: “Lơi ta lăp tâm trôm ngih bu njor khĭt, mâu lah hăn nhĭm vơl klâng ndrê ma khân păng; yor lah gâp lĕ sŏk sĭt jêh nau đăp mpăn, nau ueh lăng, nau yô̆ klâng gâp bơh phung ƀon lan aơ.” Yêhôva lah.$b$,true),
('bunong-vn','JER',16,6,null,$b$Bunuyh toyh lư n'găr jêh ri phung jê̆ rhên khĭt da dê tâm bri neh aơ; mâu geh nuyh tâp, mâu lĕ geh nuyh nhĭm vơl ma khân păng; bu mâu rek tor săk jăn nơm, mâu lah koh sŏk tŭt yor khân păng.$b$,true),
('bunong-vn','JER',16,7,null,$b$Mâu geh nơm mra pêch tâm pă piăng let ma phung klâng ndrê, gay bonh leng khân păng yor bunuyh khĭt; kŏ mâu geh lĕ nơm ăn kachok dak nhêt ma nau leng yor ma khĭt mbơ̆ mâu lah mê̆ păng gay tâm pă nau rngot.$b$,false),
('bunong-vn','JER',16,8,null,$b$Ăt tâm ban lĕ, lơi ta lăp tâm jrô sông sa, gay nhêt sa ndrel khân păng.$b$,true),
('bunong-vn','JER',16,9,null,$b$Yor lah, Yêhôva ma phung ta han, Brah Ndu Israel, lah pô aơ: Aơ, gâp mra ăn nau rlu ta năp măt khân may, dôl rnôk rô̆ khân may, gâp mra ƀư tâm bri aơ mâu hôm geh nau răm maak ma bâr mprơ, mâu hôm geh bâr bu klâu ntơm văng ur jêh ri bâr bu ur ntơm đăp ma sai.$b$,false),
('bunong-vn','JER',16,10,null,$b$Tơ lah may ntuh nau ngơi aơ ma phung ƀon lan, nanê̆ khân păng mra ôp may: “Mâm ƀư Yêhôva mbơh nkhơng nau mhĭk aơ mra tât ma hên? Moh nau kue hên hŏ ƀư jêh? Moh nau tih hên lĕ ƀư jêh đah Yêhôva Brah Ndu$b$,true),
('bunong-vn','JER',16,11,null,$b$may plơ̆ sĭt lah ma khân păng pô aơ: Yêhôva lah: Nây yor tă bơh phung che khân may cha lơi jêh gâp, jêh ri tĭng ndô̆ brah êng, rhŏ ma păng jêh ri mbah yơk ma brah nây, yor nây khân păng hŏ cha lơi jêh gâp, jêh ri mâu djôt prăp ôh nau vay gâp ntăm.$b$,false),
('bunong-vn','JER',16,12,null,$b$Bi khân may ƀư mhĭk rlau lơn ma phung che khân may. Yor lah, aơ, ăp nơm khân may tĭng nau dăng tâm nuih n'hâm mhĭk păng nơm, mâu mĭn rvê ma gâp ôh.$b$,false),
('bunong-vn','JER',16,13,null,$b$Yor nây yơh, gâp mra mprơh khân may, du luh bơh bri aơ tât ma bri êng, jêng bri khân may jêh ri phung che khân may mâu mâp gĭt năl ôh; ta nây khân may mra rhŏ (pah kan) ma brah êng nar măng, yor lah gâp mâu mra ăn nau ueh ôh ma khân may.$b$,true),
('bunong-vn','JER',16,14,null,$b$Yor ri, Yêhôva lah pô aơ: ‘Aơ, nar lĕ tât, bu mâu mra lah đŏng ôh! Tĭng nâm Yêhôva gŭ rêh, jêng Nơm hŏ njŭn leo jêh kon sau Israel du luh bơh n'gor bri Êjipt.$b$,true),
('bunong-vn','JER',16,15,null,$b$Ƀiă lah bu mra lah: ‘Tĭng nâm Yêhôva gŭ rêh, Nơm njŭn leo kon sau phung Israel hao tă bơh bri dor pa lơ, jêh ri tă bơh lĕ rngôch bri păng mprơh jêh khân ô băl.’ Yor lah gâp mra njŭn khân păng sĭt ma bri khân păng nơm gâp hŏ ton ăn jêh ma phung che khân păng.$b$,false),
('bunong-vn','JER',16,16,null,$b$“Aơ, gâp prơh hăn âk phung seng ka, Yêhôva lah, jêh ri khân păng mra nhŭp phung ƀon lan Israel; jêh nây đŏng, gâp mra prơh hăn âk phung nchron pănh, jêh ri khân păng mra hăn nchron pănh, phung ƀon lan Israel bơh ăp yôk, ăp gôl, jêh ri tâm ăp nđa lŭ.$b$,true),
('bunong-vn','JER',16,17,null,$b$Yor lah măt gâp gŭ uănh tâm lĕ trong khân păng chuat hăn, trong nây mâu dơi ndâp ôh tra năp măt gâp, nau tih khân păng kŏ mâu dơi pôn ndâp lĕ đah măt gâp.$b$,false),
('bunong-vn','JER',16,18,null,$b$Lor lơn gâp mra mbơh nau kue jêh ri nau tih khân păng n'hao bar tơ̆ âk lơn, yor lah khân păng hŏ ƀư ƀơ̆ ƀơch jêh bri neh gâp yor tă bơh phung rup brah khân păng, jêh ri djôt leo lĕ rngôch nau gâp tâm rmot ƀư bêng drăp gâp ndơn.$b$,true),
('bunong-vn','JER',16,19,null,$b$Ơ Yêhôva, may jêng n'hâm suan dăng ktang gâp, pôih mpêr ma gâp, jêng ntŭk gâp nde krap tâm nar geh nau uh ah! Lĕ bri dak ntơm bơh bôl dŭt neh ntu mra văch tât ma may, jêh ri lah: “Phung che hên sŏk dơn knŏng nau mƀruh, jêng nau dơm dam, jêh ri mâu geh nau khlay ôh.$b$,true),
('bunong-vn','JER',16,20,null,$b$Dơi lĕ bunuyh njêng êng phung brah ma păng nơm? Ndơ pô nây mâu jêng brah ngăn ôh!”$b$,true),
('bunong-vn','JER',16,21,null,$b$“Yor nây, aơ, gâp mra ăn ma khân păng gĭt, du tơ̆ aơ gâp mra ăn khân păng gĭt n'hêl nanê̆ nau ktang jêh ri nau brah gâp, jêh ri khân păng mra gĭt amoh gâp jêng Yêhôva.”$b$,true),
('bunong-vn','JER',17,1,null,$b$Nau tih Yuđa bu chih jêh đah mâng chih loih, ma chiông lŭ mplanh diamôn bu tor kach tâm rlat nuih n'hâm khân păng, jêh ri ta nke nơng khân păng.$b$,true),
('bunong-vn','JER',17,2,null,$b$Lah kon sau khân păng kah gĭt jêh ma nơng ƀư brah jêh ri rup trah brah Asêrim, khân păng hŏ ndâk êp ta meng tơm si ndrêh jêh ri ta klơ gôl prêh.$b$,true),
('bunong-vn','JER',17,3,null,$b$Ơ gôl yôk tâm bri rdah, gâp mra jao drăp ndơ jêh ri lĕ drăp khlay may, ăn bu sŏk pit nđâp ma ntŭk prêh may, yor nau tih lam ntŭk văr jŭm may.$b$,true),
('bunong-vn','JER',17,4,null,$b$May mra roh neh drăp may ndơn gâp ăn jêh ma may, nây jêng may ƀư êng nơm; jêh ri gâp mra ăn may pah kan ma phung rlăng may tâm bri may mâu mâp gĭt năl ôh, yor lah khân may nsônh nau gâp ji nuih geh ŭnh hit mra su mro mrăng.”$b$,true),
('bunong-vn','JER',17,5,null,$b$Yêhôva lah pô aơ: Di ma bu rtăp rak ngăn yơh nơm nsing ma bunuyh, jêh ri nsing ma nau ktang bơh nglay săk, nuih n'hâm păng lĕ nkhah du bơh Yêhôva.$b$,true),
('bunong-vn','JER',17,6,null,$b$Păng jêng nâm bu rlô pôm tâm bri rdah, păng mâu mra saơ ôh nau ueh tât. Ƀiă lah păng mra gŭ tâm bri rdah ntŭk kro đang, tâm neh bu phal boh mâu geh bunuyh gŭ ôh.$b$,false),
('bunong-vn','JER',17,7,null,$b$“Ueh maak ngăn mbu nơm nsing ma Yêhôva, jêh ri sŏk Yêhôva ƀư nau păng nsing.$b$,true),
('bunong-vn','JER',17,8,null,$b$Păng jêng nâm bu du n'gâng tơm si tăm dăch dak, hung reh păng êp meng dak n'hor, hên ri nkhêp lah trôk duh mâu klach ôh, n'ha păng ăt luh nse ƀa ƀơ. Tơ lah tât năm phang kŏ mâu rvê ir lĕ, yor lah păng play mro, mâu rlu ôh.”$b$,true),
('bunong-vn','JER',17,9,null,$b$Nuih n'hâm jêng ndơ blau ndơm lơn ma lĕ rngôch, jêh ri bêng ma nau ƀai: Mbu dơi gĭt rbăng nau nây?$b$,true),
('bunong-vn','JER',17,10,null,$b$“Gâp, jêng Yêhôva nơm kâp sek uănh nau mĭn, jêh ri rlong uănh nuih n'hâm bu, gay ăn ma ăp nơm tĭng nâm trong păng hăn, tĭng nâm geh play bơh kan păng pah.”$b$,true),
('bunong-vn','JER',17,11,null,$b$Phung dơi geh nau ndrŏng kuăng mâu ŭch tĭng ôh nau sŏng, nâm bu sĭm tat-ta păn tăp tat-ta êng, bi păng nơm mâu mâp deh ôh; tât n'gul rô̆ păng, nau ndrŏng nây mra du lĕ bơh păng; jêh ri dăch dŭt nau rêh păng mra jêng du huê rluk.$b$,true),
('bunong-vn','JER',17,12,null,$b$Du mlâm sưng hađăch chrêk rmah bu ndâk ntŭk klơ ntơm bơh sa ơm, nây jêng ntŭk kloh ma ƀon lan he yơk mbah!$b$,true),
('bunong-vn','JER',17,13,null,$b$Ơ Yêhôva, may jêng nau kâp gân ma phung Israel, lĕ rngôch mbu nơm cha lơi may mra prêng da dê! Phung nkhah du ma gâp nâm bu amoh bu chih ta neh, yor lah khân păng cha lơi jêh Yêhôva, nơm jêng tu dak nau rêh.$b$,false),
('bunong-vn','JER',17,14,null,$b$Ơ Yêhôva! Dăn may ƀư bah gâp, jêh ri gâp mra bah; dăn may sâm rklaih gâp, jêh ri gâp mra klaih.$b$,true),
('bunong-vn','JER',17,15,null,$b$Aơ, khân păng lah ma gâp: “Ta ntŭk geh nau Yêhôva ngơi? Ăn nau nây tât tâm di!”$b$,true),
('bunong-vn','JER',17,16,null,$b$Bi ma gâp, gâp mâu dun jêh ri du bơh kan jêng rmăk biăp ta năp may. Gâp, ăt mâu ŭch lĕ ma nar nau ƀư rai tât, may gĭt jêh nau nây. Nau ngơi tă luh bơh bâr mbung gâp may lĕ gĭt da dê jêh.$b$,true),
('bunong-vn','JER',17,17,null,$b$May jêng ntŭk ma gâp nde krap tâm nar rêh ni, lơi ta may jêng ndơ nhhu ăn gâp krit klach!$b$,true),
('bunong-vn','JER',17,18,null,$b$Ăn may ƀư prêng ma phung ƀư mhĭk ma gâp, ƀiă lah lơi ta ƀư prêng gâp ôh, ăn khân păng rdja nuih n'hâm ƀiă lah lơi ăn gâp rdja nuih n'hâm ôh. Ăn tât ma khân păng nau rêh ni, ƀư rai khân păng tơ̆ bar!$b$,true),
('bunong-vn','JER',17,19,null,$b$Yêhôva lah ma gâp pô aơ: “Hăn hom, gŭ dâk ta mpông pêr phung ƀon lan, ta nây phung hađăch Yuđa lăp jêh ri luh, ta nây lĕ rngôch mpông pêr ƀon Yêrusalem,$b$,true),
('bunong-vn','JER',17,20,null,$b$jêh ri lah: “Iăt hom nau Yêhôva ngơi, khân may phung hađăch Yuđa, jêh ri lĕ rngôch phung Yuđa, jêh ri lĕ rngôch phung ƀon lan gŭ ta ƀon Yêrusalem, phung lăp mpông pêr aơ.$b$,false),
('bunong-vn','JER',17,21,null,$b$Yêhôva lah pô aơ: “Njrăng hom jêh ri lơi anh jâk ôh ta nar Saƀat, mâu lah leo ndơ nây ta mpông pêr ƀon Yêrusalem.$b$,true),
('bunong-vn','JER',17,22,null,$b$Tâm nar Saƀat, lơi ta tung mbăk luh bơh ngih khân may, jêh ri lơi pah du ntil kan ôh, ƀiă lah kah gĭt yơk nar Saƀat jêng kloh ueh, tĭng nâm gâp hŏ ntăm jêh ma phung che khân may.$b$,false),
('bunong-vn','JER',17,23,null,$b$Ƀiă lah khân păng mâu ŭch iăt nau gâp ôh, mâu lĕ rkêng tôr khân păng, ƀiă lah ƀư dăng nuih n'hâm khân păng mâu dơi iăt jêh ri mâu tông nau ntĭm nti.$b$,false),
('bunong-vn','JER',17,24,null,$b$Yêhôva lah pô aơ: ‘Tơ lah khân may gơih iăt gâp, tơ lah khân may mâu tung mbăk jâk lăp mpông pêr ƀon nây tâm nar Saƀat, ƀiă lah kah gĭt yơk nar Saƀat jêng kloh ueh jêh ri mâu pah ôh kan nar nây.$b$,true),
('bunong-vn','JER',17,25,null,$b$Pô nây mơ phung hađăch mra lăp ta mpông pêr ƀon aơ, jêh ri gŭ ta sưng hađăch Đavit, ncho ndeh seh jêh ri seh, nđâp ma phung kôranh phung Yuđa, jêh ri phung ƀon lan gŭ ta ƀon Yêrusalem; jêh ri ƀon nây mra geh bunuyh gŭ n'ho ro.$b$,true),
('bunong-vn','JER',17,26,null,$b$Jêh ri bu mra văch tât tă bơh lĕ rngôch ƀon n'gor Yuđa, jêh ri tă bơh ăp ntŭk văr jŭm Yêrusalem, bơh n'gor Benjamin, bơh bri neh lâng, bơh bri dor klơ, jêh ri bri rđŭng pa dâng djôt leo mpa nhhơr gŭch jêh ri mpa ƀư brah, mpa nhhơr rnih muy jêh ri ndơ ƀâu kah, jêh ri djôt leo ndơ nhhơr tâm rnê ma ngih Yêhôva.$b$,true),
('bunong-vn','JER',17,27,null,$b$Ƀiă lah tơ lah khân may mâu iăt ôh gâp gay kah gĭt yơk ma nar Saƀat jêng kloh ueh, lah tâm nar Saƀat tung mbăk jâk leo lăp mpông pêr ƀon Yêrusalem, pô ri gâp mra sênh ŭnh ta mpông pêr ƀon, ŭnh nây mra sa lĕ ngih hađăch ƀon Yêrusalem jêh ri mâu mra dơi nhhât ôh.’ ”$b$,true),
('bunong-vn','JER',18,1,null,$b$Nau Yêhôva ngơi lah ma Y-Yêrêmi, pô aơ:$b$,true),
('bunong-vn','JER',18,2,null,$b$“May hăn hom, jŭr tâm ngih bunuyh mon glah, jêh ri ta nây gâp mra ăn may tăng bâr gâp.”$b$,false),
('bunong-vn','JER',18,3,null,$b$Gâp jŭr hăn tâm ngih bunuyh mon glah, aơ, păng dôl piăch rli uk mon glah ta klơ sưng.$b$,false),
('bunong-vn','JER',18,4,null,$b$Tơ lah glah păng hŏ mon rdâk jêh đah uk lĕ djơh mâu tâm di ôh, păng mon tay njêng glah êng, tĭng nâm păng nơm ŭch ƀư.$b$,false),
('bunong-vn','JER',18,5,null,$b$Nôk nây, geh bâr Yêhôva ngơi lah ma gâp pô aơ:$b$,true),
('bunong-vn','JER',18,6,null,$b$Yêhôva lah: “Ơ ngih Israel, mâu di hĕ gâp dơi ƀư ma khân may nâm bu nơm mon glah aơ ƀư jêh?” Yêhôva lah: “Aơ, nâm bu uk gŭ tâm ti nơm mon, tâm ban pô nây lĕ khân may gŭ tâm ti gâp, Ơ ngih Israel.$b$,false),
('bunong-vn','JER',18,7,null,$b$Tơ lah gâp mbơh nau di ma du ndŭl mpôl mâu lah ma du ƀon bri hađăch nau gâp mra rôk lơi, rlâm lơi, jêh ri ƀư rai lơi păng,$b$,false),
('bunong-vn','JER',18,8,null,$b$tơ lah ndŭl mpôl gâp ngơi nây plơ̆ sĭt bơh nau mhĭk, gâp plơ̆ sĭt tôr, mâu mra ƀư nau mhĭk gâp hŏ mĭn jêh ŭch ƀư ma păng.$b$,false),
('bunong-vn','JER',18,9,null,$b$Jêh ri ăt geh lĕ gâp mbơh nau di ma du ndŭl mpôl du bri dak ŭch ndâk njêng păng, tăm păng;$b$,false),
('bunong-vn','JER',18,10,null,$b$tơ lah bri dak nây ƀư nau mhĭk ta năp măt gâp, mâu tông ôh bâr gâp, nôk nây gâp mra tâm rgâl nau ueh gâp mĭn jêh gay ŭch ăn ma păng.$b$,false),
('bunong-vn','JER',18,11,null,$b$Yor nây aƀaơ ri, lah hom ma phung Yuđa jêh ri phung gŭ tâm ƀon Yêrusalem, mbơh khân păng pô aơ: ‘Yêhôva lah pô aơ: Aơ, gâp dôl nkra nau mhĭk tât ma khân may, dăp kan tâm rdâng đah khân may. Ăn ăp nơm plơ̆ rŭch du hom bơh trong mhĭk păng, jêh ri nkra tay ăn ueh trong khân may jêh ri nau khân may ƀư.’$b$,true),
('bunong-vn','JER',18,12,null,$b$Ƀiă lah khân păng mra lah: Nau nây dơm dam! Hên mra tĭng nâm dăp kan hên nơm, jêh ri ăp nơm mra ƀư tĭng nâm nau dăng nuih n'hâm mhĭk păng nơm.”$b$,false),
('bunong-vn','JER',18,13,null,$b$Yor nây, Yêhôva lah pô aơ: “Ôp hom ma phung ndŭl mpôl bunuyh: Mbu moh lĕ tăng jêh nau tâm ban pô nây? Bu druh Israel ƀư jêh du nau djơh mhĭk ngăn.$b$,true),
('bunong-vn','JER',18,14,null,$b$Dak pler bri Liban lĕ mâp tă du bơh lŭ ntŭk bri rdah lĕ? Mâu lah mbu moh saơ dak krong nđik tă bơh ngai dôl hoch geh suăt hêng lĕ?$b$,true),
('bunong-vn','JER',18,15,null,$b$Ƀiă lah phung ƀon lan gâp lĕ chuêl hêng jêh gâp; khân păng su ndơ ƀâu kah ma brah êng mâu jêng brah ngăn khân păng chêh prah tâm trong khân păng, rŏ trong ơm, jêh ri teng n'gŏ rlong mâu du trong toyh ôh,$b$,true),
('bunong-vn','JER',18,16,null,$b$njêng bri neh khân păng jêng ntŭk rngol, du ntil ndơ bu gơm mưch mro mrăng. Ăp nơm prot rŏ nây geh nau klach da dê jêh ri rteh bôk păng.$b$,false),
('bunong-vn','JER',18,17,null,$b$Nâm bu sial tă bơh lơ, gâp mra rpuh đô̆ rdu khân păng ta năp phung rlăng khân păng; gâp mra tâm mpơl chŭr kuyh gâp ma khân păng mâu du muh măt ôh, tâm dôl rô̆ khân păng geh nau rêh ni.” Mhĭk. Nau Y-Yêrêmi Mbơh Sơm$b$,true),
('bunong-vn','JER',18,18,null,$b$Khân păng lah pô aơ: “Văch hom he, tâm chră nau mra ƀư ma Y-Yêrêmi; yor lah nau vay mâu roh yot ôh, bơh phung kôranh ƀư brah, bunuyh gĭt mleh kŏ mâu roh yot lĕ nau gĭt mleh, nơm mbơh lor ăt hôm mâu dơi roh nau mbơh lor. Văch hom he dong păng ma nau ngơi, jêh ri lơi ta he rkêng tôr iăt ôh nau păng ngơi.”$b$,false),
('bunong-vn','JER',18,19,null,$b$Ơ Yêhôva, gâp dăn yor gâp nkêng tôr iăt nau ngơi phung tâm djrel đah gâp!$b$,true),
('bunong-vn','JER',18,20,null,$b$Nau ƀư mhĭk jêng nau nkhôm di ma nau ƀư ueh lĕ? Ƀiă lah khân păng kuyh jêh ntu gay ƀư ngroh lơi huêng gâp. Dăn may kah gĭt ma gâp lĕ tă gŭ dâk ta năp măt may gay dăn nau ueh yor khân păng, gay ƀư bah nau May ji nuih đah khân păng.$b$,true),
('bunong-vn','JER',18,21,null,$b$Yor nây, dăn may jao kon khân păng ma nau ât ji ngot; jêh ri jao hom khân păng nơm ma đao dao nkhĭt; ăn ur khân păng khĭt kon jêh ri jêng ndrô gâng, ăn sai khĭt ji ntưp. Ăn bu nkhĭt phung mom ndăm ma đao tâm ntŭk tâm lơh.$b$,true),
('bunong-vn','JER',18,22,null,$b$Ăn bu tăng nau nhĭm nđor bơh ngih khân păng, tơ lah may ăn tât jêh phung hăn lơh khân păng! Yor lah khân păng hŏ kuyh jêh ntu ŭch nhŭp gâp, jêh ri sân dăk tâm jâng gâp.$b$,true),
('bunong-vn','JER',18,23,null,$b$Ơ Yêhôva, may nơm gĭt jêh lĕ rngôch nau khân păng tâm chră ŭch nkhĭt gâp. Lơi ta yô̆ an ôh ma nau kue khân păng, kŏ mâu lĕ dơi jut nau tih khân păng bơh ta năp măt may; ƀiă lah ăn khân păng chôt prah pa năp măt may; ăn may tâm rmal khân păng tâm dôl nau may ji nuih!$b$,true),
('bunong-vn','JER',19,1,null,$b$Yêhôva lah pô aơ: “Hăn rvăt hom du mlâm yăng neh, ntŭk bu nơm mon, jêh ri leo ndrel ƀa ƀă phung bu bŭnh bu ranh tâm phung ƀon lan, jêh ri bu ranh tâm mpôl n'gâng kan ƀư brah hăn ndrel may,$b$,true),
('bunong-vn','JER',19,2,null,$b$tât ta rlŭng kon bu klâu Hinôm, Ta ntŭk lăp Mpông Pêr Rsong Yăng Chah, ta nây, mbơh hom nau gâp mra ngơi ma may.$b$,false),
('bunong-vn','JER',19,3,null,$b$Ăn may lah: ‘Nau Yêhôva ngơi, Ơ phung hađăch Yuđa jêh ri phung gŭ ta ƀon Yêrusalem iăt hom. Pô aơ Yêhôva ma phung ta han, Brah Ndu Israel lah: “Aơ, gâp mra ăn tât nau mhĭk ma ntŭk aơ, kŏ tât mbu nơm tăng nau ngơi nây mra ji tôr;$b$,false),
('bunong-vn','JER',19,4,null,$b$yor lah khân păng hŏ cha lơi jêh gâp, jêh ri ƀư ƀơ̆ jêh ntŭk aơ ma nau khân păng su ndơ ƀâu kah ma brah êng, khân păng, phung che khân păng phung hađăch Yuđa mâu mâp gĭt năl ôh; jêh ri yor lah khân păng ƀư ƀơ̆ jêh ntŭk aơ ma mham mâu mâp geh nau tih ôh.$b$,false),
('bunong-vn','JER',19,5,null,$b$Jêh ri khân păng ndâk ntŭk prêh ăn brah Baal gay gŭch kon bu klâu khân păng tâm ŭnh jêng ndơ nhhơr gŭch ma brah Baal, nau nây gâp mâu mâp ntĭnh, mâu lĕ mâp đă, mâu lĕ gâp mâp mĭn ma nau nây.$b$,false),
('bunong-vn','JER',19,6,null,$b$Yor nây, Yêhôva lah: Aơ, nar mra tât, aƀaơ ntŭk aơ bu mâu mra tŏ ntơ Tôphet mâu lah rlŭng Hinôm đŏng ôh, ƀiă lah bu mra ntơ Rlŭng Sreh Nkhĭt.$b$,false),
('bunong-vn','JER',19,7,null,$b$Tâm ntŭk aơ gâp mra ƀư roh lơi nau ŭch ƀư bơh phung Yuđa jêh ri phung ƀon Yêrusalem, jêh ri gâp mra ăn phung ƀon lan khân păng khĭt ma đao ta năp phung rlăng khân păng, jêh ri ma phung joi ƀư roh nau rêh khân păng. Gâp mra jao phan khân păng jêng ndơ sa ăn klang, grât jêh ri mpô mpa bri ta neh ntu.$b$,false),
('bunong-vn','JER',19,8,null,$b$Gâp mra njêng ƀon aơ du ntŭk bu gơm mưch; ăp nơm mbu prot găn ta nĕ bu klach jêh ri bu gơm mưch yor lĕ nau tât nây.$b$,false),
('bunong-vn','JER',19,9,null,$b$Gâp mra ƀư ăn khân păng sa puăch (puăch) kon bu klâu, bu ur khân păng jêh ri ăp nơm mra sa puăch (puăch) nơm chiau meng păng dôl rnôk bu nchueng lơh ƀư uh ah khân păng, ma nau nây phung rlăng jêh ri phung joi ŭch ƀư ngroh nau rêh ƀư rêh ni khân păng.$b$,false),
('bunong-vn','JER',19,10,null,$b$Jêh ri ăn may nchah yăng ta năp phung bu klâu hăn ndrel ma păng,$b$,true),
('bunong-vn','JER',19,11,null,$b$jêh ri lah ma khân may. Pô aơ Yêhôva ma phung ta han lah: Tâm ban pô nây lĕ gâp mra nchah phung ƀon lan aơ, nâm bu bu nchah du mlâm yăng, tât bu mâu hôm dơi nkra ôh. Bu mra tâp phung bunuyh tâm Tôphet kŏ tât mâu hôm tŏng ntŭk tâp ôh.$b$,false),
('bunong-vn','JER',19,12,null,$b$Tâm ban pô nây gâp mra ƀư ma ntŭk aơ. Yêhôva lah, jêh ri ma phung gŭ tâm ntŭk aơ njêng ƀon aơ nâm bu Tôphet.$b$,false),
('bunong-vn','JER',19,13,null,$b$Lĕ rngôch ngih tâm ƀon Yêrusalem, jêh ri lĕ rngôch ngih phung hađăch Yuđa lĕ rngôch ngih bu su jêh ta klơ chor ndơ ƀâu kah ma mănh tâm trôk jêh ri mâp nkhŭt jêh ndơ nhhơr nhêt ma brah êng bu mra ƀư ƀơ̆ tâm ban ntŭk Tôphet.$b$,false),
('bunong-vn','JER',19,14,null,$b$Jêh ri Y-Yêrêmi tă sĭt bơh Tôphet, ntŭk Yêhôva prơh păng hăn jêh ăn mbơh lor, jêh ri gŭ dâk tâm nhuang ngih Yêhôva, jêh ri lah ma lĕ rngôch phung ƀon lan:$b$,true),
('bunong-vn','JER',19,15,null,$b$“Pô aơ Yêhôva ma phung ta han, Brah Ndu phung Israel lah: “Aơ, gâp ăn tât ma ƀon toyh aơ jêh ri ma lĕ rngôch ƀon jê̆ păng ăp ntil nau mhĭk gâp mbơh jêh ma păng, yor lah khân păng ƀư dăng jêh nuih n'hâm khân păng, dun mâu ŭch iăt ôh nau gâp ngơi.”$b$,false),
('bunong-vn','JER',20,1,null,$b$Kôranh ƀư brah Y-Pashur kon bu klâu Y-Imer, nơm jêng kôranh chiă uănh ngih Yêhôva tăng Y-Yêrêmi mbơh nau aơ.$b$,true),
('bunong-vn','JER',20,2,null,$b$Pô ri Y-Pashur dong kôranh nơm mbơh lor Y-Yêrêmi jêh ri nkông ô băl tâm mpông pêr Benjamin mpeh klơ tâm ngih Yêhôva.$b$,false),
('bunong-vn','JER',20,3,null,$b$Nar pa kơi, Y-Pashur mƀơk Y-Yêrêmi bơh nkông, Y-Yêrêmi lah ma păng: “Yêhôva mâu ntơ amoh may Y-Pashur ôh, ƀiă lah ntơ may Magor Misabip.$b$,true),
('bunong-vn','JER',20,4,null,$b$Yor lah pô aơ nau Yêhôva lah: “Aơ, gâp mra jao may ƀư nau klach krit ma may nơm jêh ri lĕ rngôch mĭt jiăng may. Khân păng mra khĭt ma đao phung rlăng khân păng dôl may gŭ uănh. Jêh ri gâp mra jao lĕ rngôch phung Yuđa tâm ti hađăch Babilôn: Păng mra njŭn leo khân păng jêng bu nă ma bri Babilôn, jêh ri mra nkhĭt khân ô băl ma đao.$b$,false),
('bunong-vn','JER',20,5,null,$b$Jêh ri gâp mra jao lĕ rngôch nau ndrŏng ƀon aơ, jêh ri lĕ ndơ khân păng bun prăp jêh, lĕ rngôch ndơ khlay păng, jêh ri lĕ rngôch drăp ndơ phung hađăch Yuđa tâm ti phung rlăng khân păng. Phung nây mra pit in ndơ nây jêh ri leo ma bri Babilôn.$b$,false),
('bunong-vn','JER',20,6,null,$b$Bi may, ơ Y-Pashur jêh ri lĕ rngôch phung gŭ tâm ngih may, mra hăn jêng bu nă; may mra hăn ma bri Babilôn jêh ri ta nây may mra khĭt. Bu mra tâp may ta nây, may jêh ri lĕ rngôch phung mĭt jiăng may, ma phung nây may mbơh jêh nau mƀruh.”$b$,false),
('bunong-vn','JER',20,7,null,$b$Ơ Yêhôva, may ndơm jêh gâp, jêh ri gâp dơn jêh nau ndơm; may jêng ktang lơn ma gâp jêh ri may dơi jêh đah gâp. Gâp jêng jêh du ntil ndơ bu gơm mưch ăp nar; ăp nơm mưch ma gâp.$b$,true),
('bunong-vn','JER',20,8,null,$b$Yor lah tơ lah gâp ngơi, gâp nter, gâp nter huy, “Nau djơh mhĭk jêh ri nau ƀư rai!” Yor lah nau Yêhôva ngơi lĕ jêng jêh ma gâp nau bu nduyh jêh ri gơm mưch ăp nar.$b$,true),
('bunong-vn','JER',20,9,null,$b$Tơ lah gâp lah: “Gâp mâu mra rơ đŏng ma păng ôh, mâu lĕ hôm ngơi tâm amoh păng.” Nau may ngơi jêng tâm nuih n'hâm gâp nâm bu ŭnh dôl hit. Put ndâp tâm nting gâp, Jêh ri gâp rgănh djôt prăp nau nây, jêh ri gâp mâu hôm dơi ôh.$b$,true),
('bunong-vn','JER',20,10,null,$b$Gâp tăng geh âk nau bu mưch rmot “Nau krit klach ăp ntil! Lĕ rngôch mĭt jiăng gâp gŭ uănh nau gâp chôt prah, jêh ri lah: Phong hom păng! Ăn he phong hom păng! Năng ai păng mra geh nau ndơm, pô ri he dơi ƀư ma păng, jêh ri har plơng bôk păng.$b$,true),
('bunong-vn','JER',20,11,null,$b$Ƀiă lah Yêhôva gŭ ndrel ma gâp nâm bu du huê ta han tâm lơh bu rnam klach ngăn. Yor nây phung ƀư mhĭk ma gâp mra chôt prah. Khân păng mâu mra dơi đah gâp ôh. Khân păng mra prêng hâu ngăn ngên yor lah khân păng mâu mra dơi ôh. Nau prêng khân păng gŭ n'ho ro, bu mâu mra chuêl ôh.$b$,true),
('bunong-vn','JER',20,12,null,$b$Ơ Yêhôva ma phung ta han, Nơm rlong uănh phung sŏng, sek uănh tâm nuih n'hâm jêh ri tâm nau mĭn; ăn gâp saơ nau may har plơng bôk tât ma khân păng, yor lah gâp djôt jêh kan gâp mpơl ma may$b$,true),
('bunong-vn','JER',20,13,null,$b$Mprơ hom ma Yêhôva. Mât ton hom ma Yêhôva! Yor lah Păng tâm rklaih jêh nau rêh phung o ach bơh ti phung ƀư mhĭk.$b$,false),
('bunong-vn','JER',20,14,null,$b$Rtăp rak hom ma nar bu deh ma gâp! Lơi ăn geh nau ueh uĭn ôh ma nar mê̆ hŏ deh ma gâp!$b$,true),
('bunong-vn','JER',20,15,null,$b$Rtăp rak lơi ma bunuyh nơm mbơh nau mhe ma mbơ̆ gâp. “Bu deh jêh ma may du huê kon bu klâu.” Ăn ma mbơ̆ gâp bêng ma nau răm maak.$b$,true),
('bunong-vn','JER',20,16,null,$b$Ăn bunuyh nây jêng nâm bu lĕ rngôch ƀon toyh Yêhôva ƀư rai jêh mâu yô̆ ôh; ăn păng tăng nau nhĭm vơl dôl ơm ôi jêh ri bâr kuăl mbơh ma nau tâm lơh dôl nar nklang bôk.$b$,true),
('bunong-vn','JER',20,17,null,$b$Yor lah păng mâu nkhĭt gâp ôh dôl hôm tâm ndŭl; tât mê̆ gâp jêng môch ma gâp, jêh ri păng mâu mâp deh ma gâp ôh.$b$,true),
('bunong-vn','JER',20,18,null,$b$Mâm ƀư gâp luh du bơh trôm ndŭl, gay saơ nau rêh ni, rngot rvê jêh ri du bông nau rêh anh nau prêng?$b$,true),
('bunong-vn','JER',21,1,null,$b$Aơ nau Yêhôva ngơi ma Y-Yêrêmi, rnôk hađăch Sêdêkia prơh hăn ma păng Y-Pashur, kon bu klâu Y-Machhia jêh ri kôranh ƀư brah Y-Sêphani, kon bu klâu Y-Maseja, lah:$b$,true),
('bunong-vn','JER',21,2,null,$b$“Ôp hom ma Yêhôva yor ma hên, yor lah Nêbukatnetsar, hađăch Babilôn văch tât gay tâm lơh đah hên; klăp lah Yêhôva mra ƀư ueh ma hên tĭng nâm lĕ rngôch kan khlay Păng, jêh ri mra ăn hađăch Babilôn du bơh hên.”$b$,false),
('bunong-vn','JER',21,3,null,$b$Y-Yêrêmi lah ma khân păng: “Ăn khân may lah ma Y-Sêdêkia nau aơ,$b$,true),
('bunong-vn','JER',21,4,null,$b$‘Pô aơ nau Yêhôva Brah Ndu Israel lah: Aơ, gâp ăn rŭch plơ̆ lơi ndơ tâm lơh khân may djôt tâm ti khân may, ma ndơ nây khân may tâm lơh đah hađăch Babilôn jêh ri đah phung Kaldê gŭ nchueng pa dih mpêr ƀon khân may; jêh ri gâp mra njŭn leo khân păng ndrel n'grŭp lăp tâm nklang ƀon aơ.$b$,false),
('bunong-vn','JER',21,5,null,$b$Nđâp gâp nơm mra tâm lơh đah khân may ma ti hŏ yơr jêh, jêh ri đo tur dăng ktang ma nau nuih hâu ngăn ngên.$b$,true),
('bunong-vn','JER',21,6,null,$b$Gâp mra dong phung gŭ tâm ƀon aơ, nđâp bunuyh jêh ri mpô mpa; khân păng mra khĭt ma nau ji tưp hâu ngăn.’$b$,false);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','JER',21,7,null,$b$Jêh nau nây Yêhôva, lah: “Jêh ta nây, gâp mra jao Y-Sêdêkia, hađăch Yuđa, oh mon păng jêh ri phung ƀon lan păng, nâm bu ntĭt lĕ rngôch phung hôm klen tâm ƀon, klaih bơh nau ji tưp, bơh tak đao, jêh ri bơh nau ât ji ngot, gâp ma jao khân păng tâm ti Nêbukatnetsar, hađăch Babilôn, jêh ri ma ti phung rlăng khân păng, ma ti phung joi ƀư ngroh lơi nau rêh khân păng. Hađăch Babilôn mra sreh khân păng ma đao, păng mâu mra yô̆ ma khân păng ôh, mâu lĕ nhhuach ma khân păng.$b$,false),
('bunong-vn','JER',21,8,null,$b$May lah đah phung ƀon lan aơ: Yêhôva lah pô aơ: Aơ, gâp dơm ta năp khân may trong nau rêh jêh ri trong nau khĭt.$b$,true),
('bunong-vn','JER',21,9,null,$b$Mbu nơm gŭ tă ƀon aơ mra khĭt ma đao, ma nau ât ji ngot, jêh ri ma nau ji tưp; ƀiă lah mbu nơm du luh lăp phung Kaldê gŭ nchuang ƀư ma khân may aƀaơ aơ mra gŭ rêh jêh ri mra klaih nau rêh păng.$b$,false),
('bunong-vn','JER',21,10,null,$b$Yor lah gâp săch jêh ŭch ƀư mhĭk ma ƀon aơ mâu di ŭch ƀư ueh ôh. Yêhôva, lah: “Gâp mra jao ƀon aơ tâm ti hađăch Babilôn, jêh ri păng mra su ƀon aơ ma ŭnh.”$b$,false),
('bunong-vn','JER',21,11,null,$b$“Lah hom ma ngih hađăch Yuđa, Iăt hom nau Yêhôva ngơi.$b$,true),
('bunong-vn','JER',21,12,null,$b$Ơ ngih Y-Đavit pô aơ Yêhôva lah: Ƀư hom nau sŏng ăp ôi, jêh ri tâm rklaih hom nơm bu ntŭng tă bơh ti nơm tŭn jot, klach lah nau gâp nuih mra luh nâm bu ŭnh. Jêh ri hit mâu geh nơm dơi nhhât ôh. Yor lah nau mhĭk khân may ƀư.$b$,false),
('bunong-vn','JER',21,13,null,$b$Aơ, gâp tâm rdâng đah khân may Ơ phung gŭ tâm rlŭng. Ơ lŭ tâm ntŭk neh lâng, Yêhôva lah. Phung khân may lah: “Mbu nơm mra jŭr ƀư ma hên, mâu lah mbu dơi lăp tâm ngih hên?”$b$,true),
('bunong-vn','JER',21,14,null,$b$Gâp mra tâm rmal khân may tĭng nâm kan khân may ƀư, Yêhôva lah. Gâp mra sênh ŭnh tâm bri krŏng păng, jêh ri ŭnh mra sa lĕ rngôch ndơ gŭ văr jŭm păng.”$b$,true),
('bunong-vn','JER',22,1,null,$b$Pô aơ nau Yêhôva lah: “Hăn trŭnh hom rlet ma ngih hađăch Yuđa jêh ri ngơi nau aơ ta nây:$b$,true),
('bunong-vn','JER',22,2,null,$b$‘Iăt hom nau Yêhôva ngơi, nơm gŭ ta sưng hađăch Đavit, may, phung oh mon may, jêh ri phung ƀon lan may lăp ta mpông pêr aơ.’$b$,false),
('bunong-vn','JER',22,3,null,$b$Pô aơ nau Yêhôva lah: “Ƀư hom nau sŏng jêh ri nau di, jêh ri tâm rklaih hom bơh ti nơm tŭn jot nơm bu ntŭng jêh ndơ păng. Jêh ri lơi ƀư nau tih mâu lah nau ƀai ôh ma phung bu năch, ma phung kon đơi mbơ̆ , jêh ri ma phung bu ur ndrô khĭt sai, mâu lĕ dơi pling mham tâm ntŭk aơ nơm mâu geh nau tih.$b$,false),
('bunong-vn','JER',22,4,null,$b$Yor lah tơ lah khân may tông bâr nanê̆ ngăn ma nau ngơi aơ pô ri mra geh phung hađăch gŭ ta klơ sưng hađăch Y-Đavit, ncho seh jêh ri ndeh seh, khân păng, phung oh mon khân păng, jêh ri phung ƀon lan khân păng lăp tâm mpông per ngih aơ.$b$,false),
('bunong-vn','JER',22,5,null,$b$Ƀiă lah tơ lah khân may mâu ŭch rkêng tôr iăt ôh nau aơ, Yêhôva lah, gâp ton săk knŏng ma gâp nơm, ngih aơ mra jêng rngol.$b$,false),
('bunong-vn','JER',22,6,null,$b$Yêhôva lah di ma ngih hađăch phung Yuđa pô nây: Gâp uănh khân may jêng nâm bu bri Galaat, nâm bu n'glơn yôk Liban, nanê̆ gâp mra njêng khân may bri rdah, jêh ri ƀon mâu geh bunuyh gŭ ôh.$b$,true),
('bunong-vn','JER',22,7,null,$b$Gâp mra prơh hăn phung ƀư rai lơh đah khân may, ăp nơm djôt ndơ tâm lơh da dê; khân păng mra kăl tơm si dêdar ueh uĭn khân may geh, jêh ri klŭp khân păng tâm ŭnh.$b$,true),
('bunong-vn','JER',22,8,null,$b$“Geh âk ntil mpôl bunuyh mra hăn dăch rgăn ƀon aơ, jêh ri ăp nơm mra tâm lah ndrăng khân păng, ‘Mâm ƀư Yêhôva hŏ lơh jêh ƀon toyh aơ pô aơ?”$b$,true),
('bunong-vn','JER',22,9,null,$b$Khân păng mra plơ̆ lah: ‘Yor lah khân păng lơi jêh nau tâm rnglăp đah Yêhôva Brah Ndu khân păng, jêh ri mbah yơk ma brah êng jêh ri rhŏ ma brah nây.’ ”$b$,false),
('bunong-vn','JER',22,10,null,$b$Lơi ta nhĭm ôh ma bunuyh lĕ khĭt jêh, mâu lĕ nhĭm vơl ma păng; ƀiă lah nhĭm hom ma nau rngot ma nơm du hăn jêh bơh bri nơm, yor lah păng mâu mra lŏ plơ̆ sĭt đŏng ôh gay saơ bri nơm.$b$,true),
('bunong-vn','JER',22,11,null,$b$Yor lah Yêhôva lah pô aơ nau ma Y-Salum, kon bu klâu Y-Jôsia hađăch Yuđa, nơm chiă uănh thoi mbơ̆ păng, jêh ri nơm hŏ du jêh bơh ntŭk aơ: “Păng mâu mra plơ̆ đŏng ôh ma ntŭk aơ,$b$,true),
('bunong-vn','JER',22,12,null,$b$ƀiă lah tâm ntŭk bu njŭn leo păng jêng bu nă, ta nĕ păng mra khĭt, jêh ri păng mâu mra mâp saơ đŏng ôh bri aơ.”$b$,false),
('bunong-vn','JER',22,13,null,$b$“Rêh ni ngăn ma nơm ndâk ngih păng ma nau kue, jêh ri jrô prêh klơ păng ma nau mâu sŏng; nơm ăn phung chiau meng păng pah kan mâu geh nkhôm ôh mâu ƀơk ôh prăk khân păng kan,$b$,true),
('bunong-vn','JER',22,14,null,$b$păng lah: ‘Gâp nơm mra ndâk du ngih toyh geh jrô prêh klơ toyh huy,’ jêh ri ƀư mpông bloh păng, ƀư mpir ma tơm si sêdar, jêh mhĭng nhom mpir nây ma dak chăng.$b$,false),
('bunong-vn','JER',22,15,null,$b$May mĭn may jêng hađăch lĕ. Yor lah may ƀư ngih ma tơm si sêdar ueh rlau lơn ma phung êng? Mâu di hĕ mbơ̆ may kăl e lĕ sông sa lĕ nhêt jêh ri ƀư nau sŏng, jêh ri nau di? Pô nây nau ueh uĭn tât ma păng.$b$,true),
('bunong-vn','JER',22,16,null,$b$Păng phat dôih ma nau sŏng ma nau phung o ach jêh ri phung rêh ni; pô nây nau ueh uĭn tât ma păng. Mâu di hĕ nau ƀư pô nây jêng nau gĭt năl gâp, “Yêhôva lah?$b$,true),
('bunong-vn','JER',22,17,null,$b$Ƀiă lah măt jêh ri nuih n'hâm may knŏng ŭch sa kao ma nau mâu geh rah vah, ŭch pling mham nơm mâu mâp tih ôh, ƀư nau tŭn jot jêh ri djơh mhĭk.”$b$,true),
('bunong-vn','JER',22,18,null,$b$Yor nây, pô aơ Yêhôva lah nau ma Y-Jêhôjakim, kon bu klâu Y-Jôsia hađăch Yuđa: “Khân păng mâu mra nhĭm vơl ma ô băl ôh, lah: ‘Hơi nâu gâp ơi!’ Mâu lah ‘Hơi yuh gâp ơi!’ Khân păng mâu mra nhĭm vơl ma ô băl ôh lah: ‘Ơ kôranh ah!’ Mâu lah ‘Ơ nau chrêk rmah păng!’$b$,true),
('bunong-vn','JER',22,19,null,$b$Nâm bu bu tâp du mlâm seh bri, pô nây lĕ bu tâp ô băl, bu mra uih pa dih jêh ri mƀăr ngai bơh mpông pêr ƀon Yêrusalem.”$b$,false),
('bunong-vn','JER',22,20,null,$b$“Hăn hao hom ma bri Liban, jêh ri nter, jêh ri nter ăn huy tâm bri Basan; nter hom bơh klơ yôk ntŭk Abarim! Yor lah lĕ rngôch phung may rŏng lĕ rai lôch jêh.$b$,true),
('bunong-vn','JER',22,21,null,$b$Gâp ngơi jêh ma may dôl nôk may geh nau ueh maak, ƀiă lah may lah: ‘Gâp mâu ŭch gŭ iăt ôh.’ Aơ nau may ƀư jêh ntơm bơh may jêng druh ndăm, may mâu mâp tông bâr ma gâp ôh.$b$,true),
('bunong-vn','JER',22,22,null,$b$Sial mra đô̆ rdu lĕ rngôch phung rmăk biăp may, jêh ri phung may rŏng mra hăn jêng bu nă; nôk nây mra prêng jêh ri uh ah yor lĕ rngôch nau kue may ƀư jêh.$b$,true),
('bunong-vn','JER',22,23,null,$b$Ơ nơm gŭ tâm bri Liban, gŭ ta nklang tơm si Sêdar, may mra nter vơl hâu ngăn ngên tơ lah nau ji tât ma may. Nâm bu nau ji du huê bu ur bêch veng ŭnh!$b$,true),
('bunong-vn','JER',22,24,null,$b$Yêhôva lah: “Tĭng nâm gâp gŭ rêh, nđâp lah Y-Jêhôjakin, kon bu klâu Y-Jêhôjakim, hađăch Yuđa, jêng rgên chrăk ta ti ma gâp, ƀiă lah ăt gâp mra doh lơi,$b$,true),
('bunong-vn','JER',22,25,null,$b$jêh ri jao may ma ti nơm joi ƀư roh nau rêh may ma ti phung may klach, ma ti Nêbukatnetsar hađăch Babilôn jêh ri ma ti phung Kaldê.$b$,false),
('bunong-vn','JER',22,26,null,$b$Gâp mra mprơh may jêh ri me deh ma may tâm bri êng, ntŭk bu mâu mâp deh ma may ôh; jêh ri ta nĕ may mra khĭt.$b$,false),
('bunong-vn','JER',22,27,null,$b$Ƀiă lah khân păng mâu mra sĭt ôh ma bri khân păng klâng ŭch sĭt.”$b$,false),
('bunong-vn','JER',22,28,null,$b$Di lĕ Y-Jêhôjakin jêng yăng chah jêh bu tâm rmot, ô băl mâu geh nơm ŭch ôh? Mâm ƀư bu mprơh lơi păng jêh ri phung kon păng rlet ma bri khân păng mâu gĭt năl ôh?$b$,true),
('bunong-vn','JER',22,29,null,$b$Ơ neh, neh, neh, iăt hom nau Yêhôva ngơi!$b$,true),
('bunong-vn','JER',22,30,null,$b$Pô aơ Yêhôva lah: “Chih hom bu săch jêh ma bu klâu aơ mâu mra geh kon ôh, păng jêng du huê bunuyh mâu mra dơi ôh dôl păng gŭ rêh; yor lah mâu geh ôh tâm phung sau păng mra dơi gŭ ta sưng hađăch Đavit, jêh ri jêng đŏng kôranh chiă uănh bri Yuđa.”$b$,true),
('bunong-vn','JER',23,1,null,$b$“Rêh ni ngăn ma phung rmăk biăp ƀư rai jêh ri pru pra lơi biăp tâm ndrêch gơ̆ gâp!” Yêhôva lah,$b$,true),
('bunong-vn','JER',23,2,null,$b$Yor nây Yêhôva Brah Ndu phung Israel lah pô aơ nau geh ma phung rmăk biăp chiă uănh phung ƀon lan gâp: “Khân may pru pra jêh biăp gâp, jêh ri mprơh jêh khân ô băl, jêh ri khân may mâu njrăng ma khân ô băl ôh. Aơ, gâp mra tâm rmal khân may yor nau mhĭk khân may ƀư jêh.” Yêhôva lah,$b$,false),
('bunong-vn','JER',23,3,null,$b$Jêh ri gâp nơm mra rƀŭn biăp gâp hôm klen luh bơh lĕ rngôch bri gâp mprơh jêh khân ô băl, jêh ri njŭn khân păng sĭt rlet ma ndrêch gơ̆ khân păng nơm, jêh ri khân păng mra geh tay kon sau jêh ri bĭk rơ̆ .$b$,false),
('bunong-vn','JER',23,4,null,$b$Gâp mra dơm phung rmăk biăp chiă uănh khân păng ăn ueh, jêh ri khân păng mâu mra klach đŏng ôh, mâu lĕ rdja nuih, mâu lĕ mra geh bunuyh roh.” Yêhôva lah,$b$,false),
('bunong-vn','JER',23,5,null,$b$“Aơ, nar mra tât,” Yêhôva lah, tơ lah gâp mra ăn hon ma Y-Đavit du tơm N'gĭng Sŏng, Păng mra jêng hađăch chiă uănh ƀư ma nau gĭt mĭn, Jêh ri mra ƀư ma nau sŏng jêh ri nau di tâm bri dak.$b$,false),
('bunong-vn','JER',23,6,null,$b$Tâm rnôk păng phung Yuđa mra geh nau tâm rklaih, jêh ri phung Israel mra gŭ đăp rmên. Aơ amoh bu mra ntơ ăn păng: Yêhôva nau sŏng srăng he.$b$,true),
('bunong-vn','JER',23,7,null,$b$Yêhôva lah: “Yor nây, aơ, nar mra tât tơ lah phung bunuyh mâu hôm mra lah đŏng ôh, ‘Tĭng nâm Yêhôva gŭ rêh, Nơm njŭn jêh phung Israel du luh bơh bri Êjipt,’$b$,true),
('bunong-vn','JER',23,8,null,$b$ƀiă lah bu mra lah: Tĭng nâm Yêhôva gŭ rêh, Nơm njŭn jêh kon sau ngih Israel du luh bơh bri dor lơ jêh ri bơh lĕ rngôch bri păng mprơh jêh khân ô băl, jêh ri khân păng mra gŭ tâm bri khân ô băl nơm.”$b$,false),
('bunong-vn','JER',23,9,null,$b$Nau di ma phung kôranh nơm mbơh lor: Nuih n'hâm gâp lĕ chah rai jêh tâm trôm, lĕ rngôch nting gâp mpât n'gơ, gâp jêng nâm bu du huê bunuyh nhŭl ndrănh, nâm bu bunuyh rvah vi rvâng yor ndrănh, yor tă Yêhôva jêh ri yor nau ngơi kloh ueh$b$,true),
('bunong-vn','JER',23,10,null,$b$Yor lah bri dak bêng ma phung văng tĭr, yor geh nau rtăp rak, bri geh nau klâng ndrê jêh ri gơ̆ ndrêch tâm bri rdah lĕ kro da dê. Khân păng nchuăt tĭng trong ƀư nau mhĭk, jêh ri dŏng n'hâm suan khân păng ŭch ƀư nau mâu di ôh.$b$,false),
('bunong-vn','JER',23,11,null,$b$“Nđâp phung kôranh nơm mbơh lor jêh ri kôranh ƀư brah mâu lĕ yơk ma Brah Ndu, nđâp tâm ngih gâp, gâp saơ jêh nau ƀai khân păng ƀư,” Yêhôva lah.$b$,true),
('bunong-vn','JER',23,12,null,$b$“Yor nây trong khân păng mra jêng mbĭr, bu mra mprơh khân păng ma nau ngo jêh ri khân păng mra cha lôt ta nây. Yor lah gâp mra ăn tât nau mhĭk ma khân păng. Tâm năm gâp tâm rmal khân păng,” Yêhôva lah.$b$,false),
('bunong-vn','JER',23,13,null,$b$“Gâp saơ nau gâp mâu ŭch ôh tâm phung kôranh nơm mbơh lor bri Samari; khân păng mbơh lor ma amoh brah Baal jêh ri njŭn ƀon lan gâp Israel nkhah du.$b$,true),
('bunong-vn','JER',23,14,null,$b$Ƀiă lah gâp saơ du nau mhĭk ngăn tâm phung kôranh nơm mbơh lor ƀon Yêrusalem; khân păng văng tĭr jêh ri chuat tâm nau mƀruh, khân păng ƀư ktang ti phung ƀư ƀai, pô nây lĕ mâu geh ôh nơm plơ̆ sĭt tă bơh nau ƀai khân păng; gâp kơp lĕ rngôch khân păng jêng jêh nâm bu ƀon Sôdôm; jêh ri phung ƀon lan khân păng nâm bu ƀon Gômôrơ.”$b$,false),
('bunong-vn','JER',23,15,null,$b$Yor nây pô aơ Yêhôva ma phung ta han lah di ma phung kôranh nơm mbơh lor: “Aơ, gâp mra siăm khân păng ma tơm si tăng, jêh ri ăn khân păng nhêt dak kăch, yor lah tă bơh phung kôranh nơm mbơh lor ƀon Yêrusalem nau mâu yơk ma Brah Ndu hăn jêh lam bri neh ntu.”$b$,true),
('bunong-vn','JER',23,16,null,$b$Pô aơ Yêhôva ma phung ta han lah: “Lơi ta iăt ôh nau phung kôranh nơm mbơh lor ngơi, phung mbơh ma khân may nau kâp gân dơm dam; khân păng ngơi nau tâm saơ tĭng nâm nau mĭn khân păng nơm, mâu geh tă trôm mbung Yêhôva ôh.”$b$,true),
('bunong-vn','JER',23,17,null,$b$Khân păng lah ƀa ƀơ phung tâm rmot ma gâp, ‘Yêhôva ngơi khân may mra geh nau đăp mpăn! Jêh ri khân păng lah ma ăp nơm Tĭng ndô̆ nau nuih n'hâm dăng khân păng nơm ŭch, ‘Mâu geh nau mhĭk mra tât ma khân păng ôh.’$b$,true),
('bunong-vn','JER',23,18,null,$b$Ƀiă lah mbu nơm tâm phung khân păng mâp gĭt rbăng jêh nau Yêhôva kơl chră rŏ, gay sek uănh jêh ri tăng nau păng ngơi? Mâu lah mbu mâp rkêng tôr jêh ri gŭ iăt nau păng ngơi?$b$,false),
('bunong-vn','JER',23,19,null,$b$Aơ, sial phŭt tă bơh Yêhôva! Nau păng nuih luh hăn jêh, nâm sial vănh blông ktang, nau nây tât ndal ƀât lât ma bôk phung ƀai.$b$,true),
('bunong-vn','JER',23,20,null,$b$Nau Yêhôva nuih mâu mra rŭch ôh tât păng ƀư jêh ri ăn tât nau păng mĭn ŭch ƀư tâm rnôk dăch lôch khân may gĭt rbăng ang rah vah nau nây.$b$,true),
('bunong-vn','JER',23,21,null,$b$Gâp mâu mâp prơh hăn phung kôranh nơm mbơh lor nây ôh, ƀiă lah ăt khân păng nchuăt hăn; gâp mâu mâp ngơi ma khân păng ôh, ăt khân păng mbơh lor.$b$,true),
('bunong-vn','JER',23,22,null,$b$Ƀiă lah tơ lah khân păng gŭ jêh tâm nau gâp kơl chră, pô ri khân păng mra mbơh nau gâp ngơi ma phung ƀon lan gâp, jêh ri ăn khân păng plơ̆ sĭt tă bơh trong tih khân păng, nđâp ma nau mhĭk khân păng ƀư tâm ban lĕ.$b$,true),
('bunong-vn','JER',23,23,null,$b$“Mâu di hĕ gâp jêng Brah Ndu gŭ dăch,” Yêhôva lah,$b$,true),
('bunong-vn','JER',23,24,null,$b$Dơi lĕ du huê pôn păng nơm tâm ntŭk ndâp. Tât gâp mâu dơi saơ păng ôh? Yêhôva lah. “Mâu di hĕ gâp mbêng phung trôk nđâp neh ntu lĕ?” Yêhôva lah.$b$,false),
('bunong-vn','JER',23,25,null,$b$“Gâp tăng jêh nau phung kôranh mbơh lor lah, phung mbơh lor nau mƀruh tâm amoh gâp, lah, ‘Gâp mbơi jêh, gâp mbơi jêh!’$b$,true),
('bunong-vn','JER',23,26,null,$b$Ndah jŏ mra geh nau mƀruh tâm nuih n'hâm phung kôranh nơm mbơh lor mƀruh, phung mbơh lor nau ndơm tĭng nâm nuih n'hâm khân păng nơm?$b$,false),
('bunong-vn','JER',23,27,null,$b$Khân păng mĭn ŭch ăn phung ƀon lan gâp chuêl amoh gâp ma nau khân păng mbơi, nau nây khân păng mbơh ndrăng khân păng, nâm bu phung mbơ̆ khân păng chuêl amoh gâp gay kah gĭt ma brah Baal.$b$,false),
('bunong-vn','JER',23,28,null,$b$Ăn kôranh nơm mbơh lor geh jêh du nau mbơi mpơl nau mbơi nây, ƀiă lah ăn mbu nơm geh jêh nau gâp ngơi, ngơi hom nau gâp ma nau răp jăp. Moh khlay rhe tơ lah ăn tâm ban ma ba?” Yêhôva lah,$b$,false),
('bunong-vn','JER',23,29,null,$b$“Mâu di hĕ nau gâp ngơi jêng nâm bu ŭnh,” Yêhôva lah, “jêh ri nâm bu me nôp ăn chah jê̆ jê̆ glo lŭ?$b$,false),
('bunong-vn','JER',23,30,null,$b$“Yor nây, aơ, gâp tâm rdâng đah phung kôranh nơm mbơh lor, phung ntŭng nau gâp ngơi ndrăng khân păng nơm.”$b$,true),
('bunong-vn','JER',23,31,null,$b$Yêhôva lah: “Aơ, gâp tâm rdâng đah phung kôranh nơm mbơh lor, phung dŏng mpiăt khân păng,” jêh ri lah: ‘Pô aơ Yêhôva ngơi.’$b$,false),
('bunong-vn','JER',23,32,null,$b$Yêhôva lah: “Aơ, gâp tâm rdâng đah phung mbơh lor mbơi mƀruh jêh ri phung mbơh nau nây njŭn phung ƀon lan gâp nhhơt bri ma nau khân păng mƀruh jêh ri ƀư blă blơ, ƀiă lah gâp mâu prơh hăn jêh ri ăt mâu geh đă lĕ khân păng; pô ri khân păng mâu geh nau kơl ôh ma phung ƀon lan aơ,” Yêhôva lah.$b$,false),
('bunong-vn','JER',23,33,null,$b$“Tơ lah phung ƀon lan aơ, phung kôranh nơm mbơh lor, mâu lah du huê kôranh ƀư brah ôp may: ‘May nau jâk Yêhôva ŭch lah?’ Ăn may lah ma khân păng, ‘Moh nau jâk? Yêhôva lah: Gâp mra dun ma khân may.$b$,true),
('bunong-vn','JER',23,34,null,$b$Bi ma kôranh nơm mbơh lor, kôranh ƀư brah, mâu lah du huê tâm phung ƀon lan lah: ‘Pô aơ nau Yêhôva ăn jâk,’ gâp mra tâm rmal nơm nây ndrel ma phung tâm ngih vâl păng.$b$,false),
('bunong-vn','JER',23,35,null,$b$Pô aơ khân may mra lah ma ăp nơm chiau meng păng jêh ri ăp nơm ma oh nâu păng, ‘Mâm nau Yêhôva hŏ plơ̆ sĭt lah jêh?’ Mâu lah “Mâm nau Yêhôva ngơi jêh?’$b$,false),
('bunong-vn','JER',23,36,null,$b$Ƀiă lah lơi ta khân may ngơi lah đŏng ôh, ‘Nau Yêhôva ăn jâk,’ yor lah nau jâk jêng nau ăp nơm ngơi, jêh ri khân may nsŭk ăn ƀư tih ma nau Yêhôva, Yêhôva ma phung ta han, Yêhôva he ngơi.$b$,false),
('bunong-vn','JER',23,37,null,$b$Pô aơ khân may mra lah ma kôranh nơm mbơh lor, ‘Mâm nau Yêhôva hŏ plơ̆ lah jêh ma may?’ Mâu lah “Mâm nau Yêhôva lah jêh ma may?’ Mâu lah ‘Mâm nau Yêhôva hŏ ngơi jêh?’$b$,false),
('bunong-vn','JER',23,38,null,$b$Ƀiă lah tơ lah khân may lah, ‘Nau Yêhôva ƀư jâk’ pô aơ Yêhôva lah, yor lah khân may lah jêh nau ngơi aơ, “Nau Yêhôva ƀư jâk,” tơ lah gâp prơh bu hăn ma khân may, lah: Lơi ăn khân may lah ôh, ‘Nau Yêhôva ƀư jâk.’$b$,false),
('bunong-vn','JER',23,39,null,$b$Yor nây, aơ, nanê̆ gâp mra chuêl khân may jêh ri lơi khân may, jêh ri nđâp ƀon gâp hŏ ăn ma khân may jêh ri phung che khân may, ngai bơh măt gâp.$b$,false),
('bunong-vn','JER',23,40,null,$b$Jêh ri gâp mra ăn nau tât ma khân may nau nduyh jêh ri nau prêng ƀa ƀơ n'ho ro, bu mâu mra chuêl ôh.$b$,true),
('bunong-vn','JER',24,1,null,$b$Jêh Nêbukatnetsar hađăch Babilôn nhŭp njêng bu nă jêh tă bơh ƀon Yêrusalem Y-Jêhôjakin kon bu klâu Y-Jêhôjakim hađăch Yuđa, ndrel ma phung kôranh bri Yuđa, phung njêh, phung chiăr jêh ri njŭn leo khân ô băl rlet ma bri Babilôn, Yêhôva tâm mpơl ma gâp nau tâm saơ aơ: Aơ geh bar mlâm bĭ play rvi bu dơm jêh pa năp ngih Yêhôva.$b$,true),
('bunong-vn','JER',24,2,null,$b$Du mlâm bĭ geh play rvi ueh ngăn, nâm bu play rvi dŭm sa ơm, ƀiă lah bai êng geh play rvi mhĭk ngăn, mhĭk ngăn kŏ tât bu mâu dơi sa ôh.$b$,false),
('bunong-vn','JER',24,3,null,$b$Yêhôva lah ma gâp: “Moh ndơ may saơ, Ơ Y-Yêrêmi?” Gâp lah: “Play rvi, play rvi ueh ngăn jêh ri play rvi mhĭk ngăn kŏ tât bu mâu dơi sa ôh.”$b$,true),
('bunong-vn','JER',24,4,null,$b$Jêh ri Y-Yêhôva ngơi ma gâp:$b$,false),
('bunong-vn','JER',24,5,null,$b$“Pô aơ Yêhôva, Brah Ndu phung Israel lah: ‘Nâm bu play rvi ueh aơ, tâm ban pô nây lĕ phung bună tă bơh bri Yuđa gâp mprơh jêh bơh ntŭk aơ ăn khân păng hăn rlet ma bri Kaldê, nau nây jêng mƀrơn ma khân păng.$b$,false),
('bunong-vn','JER',24,6,null,$b$Gâp mra kâp rmiăng gay ƀư nau ueh ma khân păng, jêh ri gâp mra njŭn tay khân păng plơ̆ sĭt ma bri aơ. Gâp mra ndâk njêng khân păng, jêh ri mâu ƀư rai khân păng ôh; gâp mra tăm khân păng jêh ri mâu mra rôk khân păng ôh.$b$,false),
('bunong-vn','JER',24,7,null,$b$Gâp mra ăn ma khân păng nuih n'hâm gĭt năl gâp jêng Yêhôva; jêh ri khân păng mra jêng ƀon lan gâp, jêh ri gâp mra jêng Brah Ndu khân păng, yor lah khân păng mra plơ̆ sĭt tay ma gâp ma lĕ nuih n'hâm khân păng.$b$,false),
('bunong-vn','JER',24,8,null,$b$“Ƀiă lah pô aơ Yêhôva lah: Bi ma play rvi mhĭk nây jêng mhĭk ngăn ngên tât bu mâu dơi sa ôh, pô nây lĕ gâp mra ƀư ma Y-Sêdêkia hađăch Yuđa, phung kôranh păng phung hôm e bơh phung ƀon Yêrusalem hôm e tâm bri aơ, mâu lah phung gŭ tâm bri Êjipt.$b$,true),
('bunong-vn','JER',24,9,null,$b$Gâp mra njêng khân păng nau nkrit ma lĕ rngôch ƀon bri hađăch ta neh ntu, ăn jêng du nau prêng, nau bu gơm mưch, nau bu ntêh rmot jêh ri nau bu rak rtăp tâm ƀon lan ntŭk grăp mra mprơh khân păng.$b$,false),
('bunong-vn','JER',24,10,null,$b$Jêh ri gâp mra ăn tât ma khân păng tak đao, nau ât ji ngot, jêh ri nau ji tưp tât khân păng rai lĕ bơh bri gâp ăn jêh ma khân păng jêh ri ma phung che khân păng.”$b$,false),
('bunong-vn','JER',25,1,null,$b$Aơ nau Yêhôva ngơi ma Y-Yêrêmi lah ma lĕ rngôch phung ƀon lan Yuđa, tâm năm rơh puăn Y-Jêhôjakim, kon bu klâu Y-Jôsia jêng hađăch chiă uănh n'gor Yuđa (năm nây jêng năm rơh nguay rô̆ Y-Nêbukatnetsar jêng hađăch bri Babilôn).$b$,true),
('bunong-vn','JER',25,2,null,$b$Nau nây kôranh nơm mbơh lor Y-Yêrêmi ngơi jêh ma lĕ rngôch phung ƀon lan n'gor Yuđa jêh ri lĕ rngôch phung gŭ tâm ƀon Yêrusalem.$b$,true),
('bunong-vn','JER',25,3,null,$b$Dôl tâm bar jât ma pe năm ntơm bơh năm rơh jât ma pe rô̆ Y-Jôsia kon bu klâu Y-Amôn jêng hađăch n'gor Yuđa tât ma nar aơ, Yêhôva ngơi ma gâp, jêh ri gâp ngơi ƀa ƀơ jêh ma khân may, ƀiă lah khân may mâu ŭch iăt ôh.$b$,false),
('bunong-vn','JER',25,4,null,$b$Yêhôva hŏ prơh hăn phung oh mon Păng, jêng phung kôranh nơm mbơh lor, tât ma khân may, lĕ ơm jêh lah ma khân may; ƀiă lah phung khân may mâu iăt nau, mâu lĕ rkêng tôr iăt.$b$,false),
('bunong-vn','JER',25,5,null,$b$Lĕ rngôch phung oh mon nây lah: “Ăn ăp nơm tâm phung khân may cha lơi hom tă bơh trong tih jêh ri nau mhĭk păng ƀư, jêh ri gŭ tâm bri Yêhôva ăn jêh ma khân may, jêh ri phung che khân may bơh rnôk sa ơm kŏ tât ƀa ƀơ n'ho ro.$b$,false),
('bunong-vn','JER',25,6,null,$b$Lơi tĭng ndô̆ brah êng ôh ŭch pah kan jêh ri yơk mbah ma khân păng; jêh ri lơi nsônh nuih gâp ôh ăn gâp ji nuih ma kan ti khân may ƀư. Pô ri mơ gâp mâu mra ƀư mhĭk ôh ma khân may.”$b$,false),
('bunong-vn','JER',25,7,null,$b$Ƀiă lah khân may mâu iăt gâp ôh,” Yêhôva lah, “tât khân may dơi nsônh nuih gâp ăn gâp nuih ma kan ti khân may ƀư ăn tât nau mhĭk ma khân may nơm.$b$,false),
('bunong-vn','JER',25,8,null,$b$Yor nây, Yêhôva ma phung ta han lah pô aơ: Yor lah khân may mâu tông ôh bâr gâp,$b$,true),
('bunong-vn','JER',25,9,null,$b$aơ, gâp mra prơh bu hăn kuăl lĕ rngôch băl mpôl bunuyh tâm bri dor pa lơ,” Yêhôva lah, jêh ri kuăl Y-Nêbukatnetsar hađăch bri Babilôn oh mon gâp, jêh ri gâp mra njŭn khân păng ƀư ma bri aơ jêh ri phung gŭ tâm bri nĕ, jêh ri ƀư ma lĕ rngôch mpôl băl gŭ văr jŭm nây. Gâp mra ƀư rai lĕ rngôch khân păng, jêh ri njêng khân păng nau ƀư nkrit bu, nau bu ntêh rmot, jêh ri nau prêng mro mrăng.$b$,false),
('bunong-vn','JER',25,10,null,$b$Rlau ma nây gâp mra ngroh lơi khân păng bâr mprơ maak jêh ri bâr răm maak, bâr bu klâu ntơm gŭ ur, jêh ri bâr bu ur ntơm gŭ sai, nteh bu rvah mpăl jêh ri nau nchrat ang ŭnh kađen.$b$,true),
('bunong-vn','JER',25,11,null,$b$Lĕ rngôch bri aơ mra jêng du mbŭch ndơ lĕ rai jêh ri nsoih dơm, jêh ri phung mpôl băl aơ mra pah kan ma hađăch bri Babilôn tâm dôl pơh jât năm.$b$,false),
('bunong-vn','JER',25,12,null,$b$Lĕ lôch jêh pơh jât năm, gâp mra tâm rmal hađăch bri Babilôn jêh ri mpôl băl nây, bri phung Kaldê, yor nau kue khân păng,’ Yêhôva lah, “njêng bri khân păng rngol ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','JER',25,13,null,$b$Gâp mra ăn nau tât ma bri nây lĕ rngôch nau ngơi gâp mbơh tâm rdâng jêh đah păng, lĕ rngôch nau chih jêh tâm ndrom sămƀŭt aơ, nau Y-Yêrêmi mbơh lor jêh tâm rdâng đah lĕ rngôch phung băl mpôl bunuyh.$b$,false),
('bunong-vn','JER',25,14,null,$b$Yor lah âk mpôl băl bunuyh jêh ri phung hađăch ton mra njêng khân păng dĭk tâm ban lĕ; jêh ri gâp mra phat dôih khân păng tĭng nâm nau khân păng ƀư jêh ri kan ti khân păng.”$b$,false),
('bunong-vn','JER',25,15,null,$b$Pô aơ Yêhôva Brah Ndu phung Israel lah ma gâp: “Sŏk hom tă bơh ti gâp kchok dak play kriăk ƀâu nau nuih aơ, jêh ri ăn lĕ rngôch mpôl băl bunuyh gâp prơh may hăn nhêt păng.$b$,true),
('bunong-vn','JER',25,16,null,$b$Khân păng mra nhêt jêh ri chuat hăn ndĭt ndĭr, jêh ri jêng trơi yor pêih đao gâp njuăl ta nklang khân păng.”$b$,false),
('bunong-vn','JER',25,17,null,$b$Pô nây gâp sŏk kchok nĕ bơh ti Yêhôva, jêh ri ăn lĕ rngôch mpôl băl bunuyh Yêhôva prơh gâp hăn ăn nhêt.$b$,true),
('bunong-vn','JER',25,18,null,$b$Ƀon Yêrusalem jêh ri lĕ rngôch ƀon n'gor Yuđa, phung hađăch jêh ri phung kôranh păng, ăn khân păng jêng rngol jêh ri nsoih, du ntil nau bu ntêh rmot jêh ri nau rtăp rak nâm bu tât jêh nar aơ;$b$,false),
('bunong-vn','JER',25,19,null,$b$Pharaôn hađăch n'gor bri Êjipt, phung oh mon păng, phung kôranh păng, lĕ rngôch phung ƀon lan păng,$b$,false),
('bunong-vn','JER',25,20,null,$b$jêh ri lĕ rngôch phung bu năch gŭ ndrel ma khân păng; lĕ rngôch hađăch n'gor bri Us jêh ri lĕ rngôch hađăch bri Philistin ƀon Askalôn, ƀon Gaxa, ƀon Êkron, jêh ri du gâl phung Asdôt hôm;$b$,false),
('bunong-vn','JER',25,21,null,$b$bri Êdon, bri Môap, jêh ri phung kon bu klâu Y-Amôn;$b$,false),
('bunong-vn','JER',25,22,null,$b$jêh ri lĕ rngôch hađăch n'gor bri Tir, lĕ rngôch hađăch n'gor bri Sidôn, jêh ri lĕ rngôch phung hađăch bri kơh đah ri dak mƀŭt;$b$,false),
('bunong-vn','JER',25,23,null,$b$bri Dêdan, bri Têma, bri Bus, jêh ri lĕ rngôch phung kreh sŏk jŭm bôk;$b$,false),
('bunong-vn','JER',25,24,null,$b$lĕ rngôch phung hađăch bri Arabi jêh ri lĕ rngôch phung hađăch mpôl băl tâm rlŭk gŭ tâm bri rdah;$b$,false),
('bunong-vn','JER',25,25,null,$b$lĕ rngôch hađăch bri Simri, lĕ rngôch hađăch bri Êlam, jêh ri lĕ rngôch hađăch bri Mêdơ;$b$,false),
('bunong-vn','JER',25,26,null,$b$lĕ rngôch hađăch bri dor pa lơ, ngai jêh ri dăch, bri aơ jêh ri bri ri, jêh ri ƀon lan ƀon bri hađăch ta klơ neh ntu. Jêh khân păng nhêt, hađăch bri Sêsăk mra nhêt tâm ban lĕ.$b$,false),
('bunong-vn','JER',25,27,null,$b$“Jêh ri ăn may lah ma khân păng, ‘pô aơ Yêhôva ma phung ta han, Brah Ndu phung Israel lah: Nhêt hôm kŏ tât nhŭl jêh ri hok, cha lôt mâu hôm dâk ôh yor đao dao gâp njuăl tâm nklang khân may.’$b$,true),
('bunong-vn','JER',25,28,null,$b$Tơ lah khân may dun mâu dơn ôh kchok bơh ti may ăn nhêt, pô ri ăn may lah ma khân păng, Pô aơ nau Yêhôva ma phung ta han lah: ‘Ăn khân may nhêt hom!$b$,false),
('bunong-vn','JER',25,29,null,$b$Yor lah aơ, gâp ntơm ăn tât nau mhĭk ma ƀon toyh bu ntơ ma Amoh gâp, jêh ri may mra klaih ma nau tâm rmal lĕ? May mâu mra klaih ôh ma nau tâm rmal, yor lah gâp kuăl đao dao ƀư ma lĕ rngôch phung gŭ ta neh ntu,’ Yêhôva ma phung ta han lah:$b$,false),
('bunong-vn','JER',25,30,null,$b$“Yor nây ăn may mbơh lor lĕ rngôch nau ngơi aơ tâm rdâng đah khân păng, lah: ‘Yêhôva mra nter troh bơh ntŭk ta klơ, jêh ri ăn bu tăng bâr păng bơh ntŭk kloh ueh Păng gŭ; păng mra ngrông ktang hâu ngăn tâm rdâng đah phung păng, jêh ri troh nâm bu phung gŭ jot play kriăk ƀâu tâm rdâng đah lĕ rngôch phung gŭ ta neh ntu.$b$,false),
('bunong-vn','JER',25,31,null,$b$Bu mra tăng nter drơu-drơu tât ta bôl neh ntu, yor lah Yêhôva geh nau đah lĕ rngôch phung mpôl băl bunuyh; păng ntơm phat dôih lĕ rngôch bunuyh, jêh ri păng mra nkhĭt phung ƀai ma đao dao.’ Yêhôva lah.$b$,true),
('bunong-vn','JER',25,32,null,$b$Pô aơ Yêhôva ma phung ta han lah: “Aơ, nau mhĭk lĕ dâk hăn jêh tă bơh du mpôl băl bunuyh hăn rlet ma du mpôl băl bunuyh êng, jêh ri phŭt chuănh hâu ntơm tât tă bơh ntŭk ngai ngăn ta neh ntu!”$b$,true),
('bunong-vn','JER',25,33,null,$b$jêh ri phung khĭt Yêhôva hŏ nkhĭt tâm nar nây, mra bêng neh ntu ntơm bơh bôl aơ tât bôl đah ri; mâu geh bunuyh nhĭm vơl, mâu geh chông njor, mâu geh tâp lĕ phan khân păng; khân păng jêng nâm bu ŭnh buh ta klơ neh ntu.$b$,true),
('bunong-vn','JER',25,34,null,$b$Nhĭm vơl hom, Hơi phung rmăk biăp jêh ri nhĭm, rlă hom tâm ŭnh buh Ơ phung kôranh leo phung biăp, yor lah lĕ tât jêh nar bu sreh nkhĭt khân may, jêh ri khân may mra cha lôt jêh ri khân may mra chah nâm bu glah uk ueh.$b$,true),
('bunong-vn','JER',25,35,null,$b$Phung rmăk biăp mâu hôm geh ntŭk du krap ôh, ma phung kôranh leo phung biăp kŏ mâu dơi klaih lĕ.$b$,true),
('bunong-vn','JER',25,36,null,$b$Phung chiăp biăp ntơm nhĭm, jêh ri phung kôranh leo phung biăp nhĭm vơl! Yor lah Yêhôva gŭ ƀư ngroh lơi Ndrêch gơ̆ khân păng.$b$,true),
('bunong-vn','JER',25,37,null,$b$Jêh ri ƀư rai ndrung (n'gar) biăp đăp mpăn hŏ jêng rngot njăp yor nau nuih Yêhôva hâu ngăn.$b$,true),
('bunong-vn','JER',25,38,null,$b$Păng jêng nâm bu du mlâm yau mŭr, păng mra luh du tă bơh rsuăn păng, jêh ri bri khân păng mra jêng rngol yor đao hơr ngăn jêh ri yor nau nuih păng duh hâu ngăn.$b$,true),
('bunong-vn','JER',26,1,null,$b$Tâm rnôk ntơm sa ơm nau Y-Jêhôjakim kon bu klâu Y-Jôsia hađăch Yuđa chiă uănh. Yêhôva ngơi pô aơ:$b$,true),
('bunong-vn','JER',26,2,null,$b$“Pô aơ Yêhôva lah: Gŭ dâk hom tâm nhuang ngih Yêhôva, jêh ri ngơi ma lĕ rngôch phung ƀon lan n'gor Yuđa văch yơk mbah tâm ngih Yêhôva lĕ rngôch nau ngơi gâp ntĭnh jêh ma may ngơi ma khân păng; lơi ta n'hŭch du rplay ngơi ôh.$b$,false),
('bunong-vn','JER',26,3,null,$b$Nanê̆ khân păng mra gŭ iăt, jêh ri ăp nơm mra plơ̆ sĭt tă bơh trong mhĭk khân păng gay ma gâp dơi rgâl nau gâp mĭn ƀư nau mhĭk ma khân păng yor nau tih khân păng ƀư.$b$,false),
('bunong-vn','JER',26,4,null,$b$Ăn may lah ma khân păng, ‘Pô aơ Yêhôva lah: Tơ lah khân may mâu ŭch iăt ôh nau gâp, mâu chuat tâm nau vay gâp ndâk jêh ta năp khân may,$b$,true),
('bunong-vn','JER',26,5,null,$b$tơ lah khân may mâu iăt nau phung oh mon gâp, jêng phung kôranh nơm mbơh lor ngơi gâp prơh hăn ma khân may âk tơ̆ , ƀiă lah khân may mâu ŭch iăt ôh ma khân păng,$b$,false),
('bunong-vn','JER',26,6,null,$b$pô ri gâp mra ƀư ma ngih aơ nâm bu gâp ƀư jêh ma ƀon Silô, jêh ri gâp mra ăn ƀon aơ jêng du nau rak rtăp ma lĕ rngôch mpôl băl bunuyh ta neh ntu.”$b$,false),
('bunong-vn','JER',26,7,null,$b$Phung kôranh ƀư brah jêh ri phung kôranh nơm mbơh lor jêh ri lĕ rngôch phung ƀon lan tăng jêh nau Y-Yêrêmi ngơi nau aơ tâm ngih Yêhôva.$b$,true),
('bunong-vn','JER',26,8,null,$b$Tơ lah Y-Yêrêmi ngơi lĕ jêh nau Yêhôva ntăm ăn păng ngơi ma lĕ rngôch phung ƀon lan, pô ri phung kôranh ƀư brah, kôranh nơm mbơh lor, jêh ri ƀon lan phung ƀon lan nhŭp rdâng păng, lah: “May mra khĭt!$b$,false),
('bunong-vn','JER',26,9,null,$b$Moh nau may mbơh lor tâm amoh Yêhôva, lah: ‘Ngih aơ mra jêng nâm bu ƀon Silô, jêh ri ƀon toyh aơ mra jêng rngol, mâu geh bunuyh gŭ ôh?” Jêh ri lĕ rngôch phung ƀon lan tâm rƀŭn jŭm Y-Yêrêmi tâm ngih Yêhôva.$b$,false),
('bunong-vn','JER',26,10,null,$b$Tơ lah phung kôranh Yuđa tăng nau aơ, tă bơh ngih hađăch khân păng hăn tât ma ngih Yêhôva jêh ri gŭ ntŭk lăp Mpông Pêr Mhe ngih Yêhôva.$b$,true),
('bunong-vn','JER',26,11,null,$b$Phung kôranh ƀư brah jêh ri kôranh nơm mbơh lor lah ma phung kôranh jêh ri ma lĕ rngôch phung ƀon lan, “Bu klâu aơ di ma nau tâm rmal tât khĭt, yor lah păng mbơh lor jêh nau tâm rdâng đah ƀon toyh aơ, tĭng nâm khân may tăng jêh ma tôr khân may nơm.”$b$,false),
('bunong-vn','JER',26,12,null,$b$Jêh ri Y-Yêrêmi ngơi ma lĕ rngôch phung kôranh jêh ri ma lĕ rngôch phung ƀon lan, lah: “Yêhôva prơh gâp hăn gay mbơh lor nau tâm rdâng đah ngih aơ jêh ri đah ƀon toyh aơ lĕ nau ngơi khân may hŏ tăng jêh.$b$,true),
('bunong-vn','JER',26,13,null,$b$Yor nây aƀaơ ri tâm rgâl hom trong khân may jêh ri nau khân may ƀư, jêh ri tông hom bâr Yêhôva Brah Ndu khân may, jêh ri Yêhôva mra tâm rgâl nau păng mbơh jêh ŭch ƀư mhĭk ma khân may.$b$,false),
('bunong-vn','JER',26,14,null,$b$Ƀiă lah bi gâp, aơ, gâp gŭ tâm ti khân may. Ƀư hom ma gâp tĭng nâm khân may mĭn ueh jêh ri di.$b$,true),
('bunong-vn','JER',26,15,null,$b$Nđâp lah pô nây ăn khân may gĭt nanê̆, lah khân may ŭch nkhĭt gâp, khân may mra nsŭk êng săk khân may nơm, ma ƀon toyh aơ, jêh ri lĕ rngôch phung gŭ tâm ƀon aơ ma mham mâu geh ôh nau tih, yor lah n'hêl nanê̆ ngăn Yêhôva prơh gâp hăn ăn ngơi ma tôr khân may lĕ rngôch nau ngơi aơ.”$b$,false),
('bunong-vn','JER',26,16,null,$b$Pô ri lĕ rngôch phung kôranh jêh ri lĕ rngôch phung ƀon lan lah ma phung kôranh ƀư brah jêh ri lĕ rngôch phung kôranh nơm mbơh lor: “Bu klâu aơ mâu khư ma nau tâm rmal tât khĭt ôh, yor lah păng ngơi jêh ma he tâm amoh Yêhôva Brah Ndu he.”$b$,true),
('bunong-vn','JER',26,17,null,$b$Ƀa ƀă phung bu bŭnh bu ranh tâm bri nĕ dâk jêh ri ngơi ma lĕ rngôch phung ƀon lan hŏ tâm rƀŭn, lah,$b$,false),
('bunong-vn','JER',26,18,null,$b$“Y-Mika ƀon Môreset mbơh lor jêh tâm rnôk Y-Hêsêkia hađăch Yuđa, jêh ri lah ma lĕ rngôch phung ƀon lan n'gor Yuđa, “Pô aơ nau Yêhôva ma phung ta han lah. “Bu mra chuar (kai) ƀon Siôn nâm bu du lôk mir; ƀon Yêrusalem mra jêng du mbŭch ndơ lĕ rai, jêh ri yôk ngih brah mra jêng yôk bri krŏng.”$b$,false),
('bunong-vn','JER',26,19,null,$b$Y-Hêsêkia, hađăch Yuđa, jêh ri ƀon lan phung Yuđa nkhĭt lơi păng lĕ? Mâu di hĕ ô băl klach yơk ma Yêhôva jêh ri vơh vơl ma Yêhôva yô̆ an; pô ri gay ma Yêhôva rgâl lơi nau Păng hŏ mbơh jêh ŭch ƀư mhĭk ma khân păng? Ƀiă lah he lĕ dăch ntơm tât nau mhĭk toyh ngăn ma he nơm.”$b$,true),
('bunong-vn','JER',26,20,null,$b$Geh du huê êng mbơh lor jêh tâm amoh Yêhôva, jêng Y-Uri kon bu klâu Y-Sêmaya bơh ƀon Kiriat-Jêarim. Păng mbơh lor nau tâm rdâng đah ƀon toyh aơ jêh ri đah bri aơ nau ngơi tâm ban Y-Yêrêmi aơ.$b$,true),
('bunong-vn','JER',26,21,null,$b$Tơ lah hađăch Y-Yêhôgiakim ndrel ma lĕ rngôch phung ta han păng jêh ri lĕ rngôch phung kôranh tăng nau păng ngơi, hađăch joi nkhĭt ô băl, ƀiă lah tơ lah Y-Uri tăng nau nây, păng klach jêh ri du rlet ma n'gor bri Êjipt gay ma klaih.$b$,false),
('bunong-vn','JER',26,22,null,$b$Hađăch Jêhôjakim prơh ƀa ƀă bunuyh hăn ma bri Êjipt, Y-Êlnathan kon bu klâu Y-Akbôr jêh ri phung êng ndrel ma păng.$b$,false),
('bunong-vn','JER',26,23,null,$b$Khân păng nhŭp Y-Uria bơh bri Êjipt jêh ri têk leo ma hađăch Y-Jêhôjakim. Hađăch sreh ô băl ma đao jêh ri klŭp săk jăn ô băl tâm môch phung ƀon lan.$b$,false),
('bunong-vn','JER',26,24,null,$b$Ƀiă lah Y-Ahikam kon bu klâu Y-Saphan kơl king Y-Yêrêmi, pô nây bu mâu jao ô băl ăn phung ƀon lan nkhĭt ôh.$b$,true),
('bunong-vn','JER',27,1,null,$b$Tâm rnôk ntơm sa ơm Y-Sêdêkia kon bu klâu Y-Jôsia hađăch Yuđa chiă uănh, Yêhôva ngơi ma Y-Yêrêmi pô aơ:$b$,true),
('bunong-vn','JER',27,2,null,$b$Pô aơ Yêhôva lah ma gâp: “Nkra hom ma may nơm rse ntâu jêh ri mâng mbăk, jêh ri văn kât ta trô ko may nơm.$b$,false),
('bunong-vn','JER',27,3,null,$b$Njuăl sămƀŭt ma hađăch bri Êđôm, hađăch bri Môap, hađăch phung kon bu klâu Y-Amôn, hađăch bri Tir, jêh ri hađăch bri Sidôn ma phung oh mon văch jêh ma ƀon Yêrusalem hăn jêh ma Y-Sêdêkia hađăch Yuđa.$b$,false),
('bunong-vn','JER',27,4,null,$b$Ăn khân păng djôt leo ma phung kôranh khân păng nau ntĭnh aơ: ‘Pô aơ Yêhôva ma phung ta han, Brah Ndu Israel lah: Nau aơ ăn khân may lah ma phung kôranh khân may:$b$,false),
('bunong-vn','JER',27,5,null,$b$“Gâp yơh jêng Nơm rhăk njêng neh, bunuyh bunun jêh ri lĕ rngôch mpô mpa ta neh ntu, ma nau brah dŭt toyh ngăn jêh ri gâp jao neh ntu ma mbu nâm gâp mĭn di.$b$,false),
('bunong-vn','JER',27,6,null,$b$Aƀaơ, gâp hŏ jao jêh bri aơ tâm ti Y-Nêbukatnetsar hađăch bri Babilôn, oh mon gâp, jêh ri tâm ban lĕ gâp jao ma păng lĕ rngôch mpô mpa bri ăn pah kan ma păng.$b$,false),
('bunong-vn','JER',27,7,null,$b$Lĕ rngôch mpôl băl bunuyh mra pah kan ma păng jêh ri ma kon bu klâu păng, jêh ri ma sau păng, kŏ tât rnôk dăch dŭt tât ma bri păng; nôk nây âk mpôl băl bunuyh jêh ri phung hađăch toyh mra njêng păng dĭk ma khân păng.$b$,false),
('bunong-vn','JER',27,8,null,$b$“Ƀiă lah tơ lah geh mpôl băl bunuyh mâu lah ƀon bri hađăch mâu mra pah kan ôh ma Y-Nêbukatnetsar hađăch Babilôn, jêh ri mâu ndô ôh mâng mbăk hađăch Babilôn, gâp mra tâm rmal mpôl băl bunuyh nây ma đao dao, ma nau sa sât ji ngot, jêh ri ji tưp, Yêhôva lah, tât gâp ƀư rai lơi bri nây ma ti păng.$b$,true),
('bunong-vn','JER',27,9,null,$b$Pô ri lơi ta iăt ôh ma phung kôranh nơm mbơh lor khân may, phung gru, rƀên khân may, phung nkoch mbơi khân may, phung sek uănh mănh, mâu lah phung n'hŭm, khân păng lah ma khân may, Khân may mâu mra pah kan ma hađăch Babilôn ôh.$b$,false),
('bunong-vn','JER',27,10,null,$b$Nau khân păng mbơh lor nây ma khân may jêng mƀruh, ƀiă lah nau ngăn jêng bu mra têk leo khân may luh bơh bri khân may nơm rlet ma bri ngai, jêh ri gâp mra mprơh khân may, jêh ri khân may mra rai lôch.$b$,false),
('bunong-vn','JER',27,11,null,$b$Ƀiă lah mbu mpôl băl bunuyh mra dơm trô ko păng tâm dâng mâng mbăk hađăch Babilôn jêh ri pah kan ma hađăch nây, pô nây, Yêhôva lah: Gâp mra ăn păng gŭ tâm bri păng nơm, gay tuch-tăm jêh ri gŭ ta nây,”$b$,false),
('bunong-vn','JER',27,12,null,$b$Gâp ngơi tâm ban pô nây lĕ ma Y-Sêdêkia hađăch Yuđa: ‘Ndô hom mâng mbăk hađăch Babilôn, jêh ri pah kan ma păng jêh ri ma ƀon lan păng, ri mơ khân may dơi rêh.$b$,true),
('bunong-vn','JER',27,13,null,$b$Mâm ƀư may jêh ri phung ƀon lan may rŏng khĭt đah đao tak, sa sât ji ngot, jêh ri nau ji tưp tĭng nâm Yêhôva ngơi jêh di ma mpôl băl bunuyh mâu mra pah kan ôh ma hađăch Babilôn?$b$,false),
('bunong-vn','JER',27,14,null,$b$Lơi ta iăt ôh nau phung kôranh nơm mbơh lor lah ma may pô aơ: ‘May mâu mra pah kan ôh ma hađăch Babilôn!’ Nây jêng nau mƀruh khân păng mbơh ma may.$b$,false),
('bunong-vn','JER',27,15,null,$b$Yêhôva ngơi lah: ‘Gâp mâu mâp prơh khân păng hăn ôh.’ Ƀiă lah khân păng mbơh lor tâm amoh gâp ma nau mƀruh, nau ngăn gâp mra mprơh khân may bơh bri neh jêh ri khân may mra rai lôch, may jêh ri phung kôranh nơm mbơh lor hŏ mbơh lor ma may.$b$,false),
('bunong-vn','JER',27,16,null,$b$Jêh ri gâp ngơi ma phung kôranh ƀư brah, jêh ri lĕ rngôch phung ƀon lan aơ, lah, “Yêhôva ngơi, lah pô aơ: Lơi iăt ôh nau phung kôranh mbơh lor khân may, mbơh lor ma khân may lah: ‘Aơ, hôm djê̆ dơm bu mra djôt mplơ̆ tă bơh ƀon Babilôn ndơ dŏng tâm ngih Yêhôva,’ yor lah jêng nau mƀruh khân păng mbơh lor ma khân may.$b$,true),
('bunong-vn','JER',27,17,null,$b$Lơi ta iăt khân păng ôh, pah kan hom ma hađăch Babilôn ri mơ dơi rêh; Mâm ƀư ƀon toyh aơ jêng nkhơng rngol?$b$,true),
('bunong-vn','JER',27,18,null,$b$Tơ lah khân păng jêng kôranh nơm mbơh lor, jêh ri tơ lah nau Yêhôva ngơi gŭ ndrel ma khân păng, pô nây ăn khân păng mbơh sơm ma Yêhôva ma phung ta han, gay ma ndơ dŏng hôm e tâm ngih Yêhôva, tâm ngih hađăch Yuđa, jêh ri tâm ƀon Yêrusalem bu mâu ndjôt leo ôh ma bri Babilôn.$b$,false),
('bunong-vn','JER',27,19,null,$b$Yor lah pô aơ Yêhôva ma phung ta han lah di ma meh jrŏng, dak mƀŭt, ma ndơ bri krŏng păng, jêh ri ma khăl ngan hôm e tâm ƀon aơ,$b$,false),
('bunong-vn','JER',27,20,null,$b$Y-Nêbukatnetsar hađăch Babilôn mâu ndjôt leo ôh dôl păng têk leo bơh ƀon Yêrusalem tât ma ƀon Babilôn Y-Jêhôjakin kon bu klâu Y-Jêhôjakim hađăch Yuđa, jêh ri lĕ rngôch phung kôranh n'gor Yuđa jêh ri ƀon Yêrusalem.$b$,false),
('bunong-vn','JER',27,21,null,$b$Pô aơ Yêhôva ma phung ta han Brah Ndu Israel ngơi lah pô aơ ma khăl ngan hôm e tâm ngih Yêhôva tâm ngih hađăch Yuđa, jêh ri tâm ƀon Yêrusalem:$b$,false),
('bunong-vn','JER',27,22,null,$b$‘Lĕ rngôch ndơ nây bu mra ndjôt leo rlet ma ƀon Babilôn jêh ri ndơ nây mra gŭ ta nây tât nar gâp kah gĭt ma khân păng.’ Yêhôva lah. Jêh ri gâp mra ndjôt sĭt ndơ nây jêh ri ăn tay tâm ntŭk aơ.”$b$,false),
('bunong-vn','JER',28,1,null,$b$Tâm nây lĕ ta rnôk ntơm sa ơm nau Y-Sêdêkia chiă uănh tâm khay prăm ta năm rơh puăn, Y-Hanania kon bu klâu Y-Asur kôranh nơm mbơh lor tă bơh ƀon Gabaôn ngơi ma gâp tâm ngih Yêhôva ta phung kôranh ƀư brah jêh ri lĕ rngôch phung ƀon lan, lah,$b$,true),
('bunong-vn','JER',28,2,null,$b$“Pô aơ Yêhôva ma phung ta han Brah Ndu Israel lah: ‘Gâp mra nkêch lơi mâng mbăk hađăch Babilôn ăn ndô.$b$,false),
('bunong-vn','JER',28,3,null,$b$Tâm bar năm gâp mra leo sĭt ma ntŭk aơ lĕ rngôch khăl ngan tâm ngih Yêhôva, ndơ Y-Nêbukatnetsar hađăch Babilôn sŏk rdu jêh bơh ntŭk aơ jêh ri leo ma ƀon Babilôn.$b$,false),
('bunong-vn','JER',28,4,null,$b$Yêhôva ngơi, lah: Gâp mra njŭn sĭt Y-Jêhôjakin, kon bu klâu Y-Jêhôjakim, hađăch Yuđa, jêh ri lĕ rngôch phung Yuđa nhŭp jêng bu nă hăn gŭ jêh tâm bri Babilôn ăt plơ̆ sĭt da dê tâm ntŭk aơ, yor lah gâp nkêch lơi mâng mbăk hađăch Babilôn ndô.$b$,false),
('bunong-vn','JER',28,5,null,$b$Jêh ri kôranh nơm mbơh lor Y-Yêrêmi ơh ngơi ma kôranh nơm mbơh lor Y-Hanania ta năp phung kôranh ƀư brah jêh ri lĕ rngôch phung ƀon lan gŭ dâk tâm ngih Yêhôva.$b$,false),
('bunong-vn','JER',28,6,null,$b$Kôranh nơm mbơh lor Y-Yêrêmi, lah: “Amen! Ăn Yêhôva ƀư nâm bu pô nây; ăn Yêhôva ăn tât ngăn nau may mbơh lor jêh, jêh ri leo sĭt ma ntŭk aơ tă bơh bri Babilôn khăl ngan tâm ngih Yêhôva jêh ri njŭn sĭt lĕ rngôch phung bu nă.$b$,false),
('bunong-vn','JER',28,7,null,$b$Ƀiă lah aƀaơ ri iăt hom nau gâp ngơi aơ ma tôr may jêh ri lĕ rngôch phung ƀon lan.$b$,false),
('bunong-vn','JER',28,8,null,$b$Phung kôranh nơm mbơh lor rnôk sa ơm lor ma may jêh ri gâp mbơh lor mra geh nau tâm lơh, nau sa sât ji ngot, jêh ri nau ji tưp mra tât ma âk rplay bri (n'gor bri) jêh ri ma âk ƀon bri hađăch toyh.$b$,false),
('bunong-vn','JER',28,9,null,$b$Bi ma kôranh nơm mbơh lor nau đăp mpăn, tơ lah nau kôranh nơm mbơh lor nây mbơh tât ngăn, nôk nây bu mra gĭt n'hêl nanê̆ ngăn Yêhôva prơh hăn kôranh nơm mbơh lor nây.”$b$,false),
('bunong-vn','JER',28,10,null,$b$Pô ri, kôranh nơm mbơh lor Y-Hanania sŏk mâng mbăk bơh trô ko kôranh nơm mbơh lor Y-Yêrêmi jêh ri nkêch lơi păng.$b$,true),
('bunong-vn','JER',28,11,null,$b$Jêh ri Y-Hanania ngơi ta năp lĕ rngôch phung ƀon lan; lah: “Pô aơ Yêhôva lah: ‘Nâm bu nĕ lĕ tâm bar năm gâp mra nkêch lơi mâng mbăk Y-Nêbukatnetsar hađăch Babilôn ndô ta trô ko lĕ rngôch phung mpôl băl bunuyh.” Jêh ri kôranh nơm mbơh lor Y-Yêrêmi du hăn.$b$,true),
('bunong-vn','JER',28,12,null,$b$Jêh kôranh nơm mbơh lor Y-Hanania sŏk nkêch mâng mbăk nây bơh trô ko kôranh nơm mbơh lor Y-Yêrêmi, Yêhôva ngơi ma Y-Yêrêmi:$b$,true),
('bunong-vn','JER',28,13,null,$b$“Hăn mbơh hom ma Y-Hanania, pô aơ Yêhôva lah: May nkêch jêh mâng tơm si, ƀiă lah gâp mra ntrok tay mâng loih.$b$,false),
('bunong-vn','JER',28,14,null,$b$Yor lah pô aơ Yêhôva ma phung ta han Brah Ndu Israel lah: Gâp dơm jêh ta trô ko lĕ rngôch phung mpôl băl aơ mâng mbăk loih nau jêng dĭk ma Y-Nêbukatnetsar hađăch Babilôn, jêh ri khân păng mra pah kan ma păng, yor lah gâp jao jêh ma păng nđâp mpô mpa bri.”$b$,false),
('bunong-vn','JER',28,15,null,$b$Kôranh nơm mbơh lor Y-Yêrêmi lah ma kôranh nơm mbơh lor Y-Hanania, “Gŭ iăt hom, Ơ Hanania, Yêhôva mâu mâp prơh may hăn ôh, jêh ri may ăn phung ƀon lan aơ rnơm ma nau mƀruh.$b$,true),
('bunong-vn','JER',28,16,null,$b$Yor nây Yêhôva lah pô aơ: Aơ, gâp mra mprơh may bơh klơ neh ntu. Năm aơ ro may mra khĭt, yor lah may ngơi jêh nau tâm rdâng đah Yêhôva.”$b$,false),
('bunong-vn','JER',28,17,null,$b$Năm nây lĕ, ta khay pơh kôranh nơm mbơh lor Y-Hanania khĭt.$b$,true),
('bunong-vn','JER',29,1,null,$b$Aơ jêng nau ngơi sămƀŭt kôranh nơm mbơh lor Y-Yêrêmi tă ƀon Yêrusalem njuăl ma phung bu bŭnh bu ranh dôl jêng bu nă, ndrel ma phung kôranh ƀư brah, ma phung kôranh nơm mbơh lor, jêh ri ma lĕ rngôch phung ƀon lan, phung Y-Nêbukatnetsar hŏ nhŭp veng tă bơh ƀon Yêrusalem leo ma bri Babilôn.$b$,true),
('bunong-vn','JER',29,2,null,$b$Păng njuăl sămƀŭt nây, pa kơi jêh hađăch Jêhôjakin, hađăch bu ur, phung kôranh bu char, phung kôranh Yuđa jêh ri, ƀon Yêrusalem, phung tôp chiăr, phung njêh luh bơh ƀon Yêrusalem.$b$,true),
('bunong-vn','JER',29,3,null,$b$Păng njuăl sămƀŭt nây ăn Y-Êlasa kon bu klâu Y-Saphan jêh ri Y-Gêmaria kon bu klâu Y-Hilkia ndjôt an, phung nây Y-Sêdêkia hađăch Yuđa prơh hăn ma bri Babilôn ma Y-Nêbukatnetsar hađăch Babilôn. Păng chih pô aơ:$b$,false),
('bunong-vn','JER',29,4,null,$b$Pô aơ Yêhôva ma phung ta han Brah Ndu Israel lah ma lĕ rngôch phung bu nhŭp veng jêh rlet bri, Babilôn, phung gâp prơh hăn jêng bu nă tă ƀon Yêrusalem tât ma bri Babilôn:$b$,false),
('bunong-vn','JER',29,5,null,$b$“Ndâk hom ngih vâl jêh ri gŭ tâm ngih nây, ƀư đang biăp n'ha jêh ri sa n'ha păng.$b$,false),
('bunong-vn','JER',29,6,null,$b$Gŭ ur geh kon bu klâu, bu ur; nsông ur ma kon bu klâu khân may jêh ri nđăp sai ma phung kon bu ur khân may, gay ăn khân păng geh kon bu ur jêh ri bu klâu. Tâm ban lĕ; ăn khân may jêng bĭk rơ̆ ta nây, jêh ri lơi ăn roh hêng ôh.$b$,false),
('bunong-vn','JER',29,7,null,$b$Ƀiă lah joi nau ueh ma ƀon toyh ntŭk gâp prơh hăn khân may jêng jêh bu nă, jêh ri mbơh sơm ma Yêhôva kơl ntŭk nây, yor lah tơ lah ntŭk nây geh nau ueh, khân may mra geh nau ueh tâm ban lĕ.”$b$,false),
('bunong-vn','JER',29,8,null,$b$Yor lah pô aơ Yêhôva ma phung ta han Brah Ndu Israel lah: “Lơi ta ăn phung kôranh nơm mbơh lor jêh ri phung rƀên ta nklang khân may ndơm khân may ôh, jêh ri lơi iăt lĕ nau mbơi khân may saơ.$b$,false),
('bunong-vn','JER',29,9,null,$b$Yor lah khân păng mbơh nau mƀruh ma khân may tâm amoh gâp; gâp mâu mâp prơh khân păng hăn ôh.” Yêhôva lah.$b$,false),
('bunong-vn','JER',29,10,null,$b$Yêhôva lah pô aơ “Tơ lah lôch jêh pơh jât năm prăp ma phung Babilôn chiă uănh, gâp mra hăn chop khâl khân may, jêh ri gâp mra ƀư nanê̆ nau gâp ton jêh ma khân may, jêh ri mra njŭn leo khân may plơ̆ sĭt ma ntŭk aơ.$b$,true),
('bunong-vn','JER',29,11,null,$b$Yor lah gâp gĭt mâm nau gâp mĭn ăn ma khân may.” Yêhôva lah, mbor kan ăn jêng ueh mâu geh ôh nau mhĭk ma khân may, gay ma khân may geh nau kâp gân ma kăndơ̆ .$b$,false),
('bunong-vn','JER',29,12,null,$b$Nôk nây khân may mra kuăl amoh gâp jêh ri văch mbơh sơm ma gâp, jêh ri gâp mra iăt khân may.$b$,false),
('bunong-vn','JER',29,13,null,$b$Khân may mra joi gâp jêh ri tâm mâp đah gâp tơ lah khân may tĭng joi ma lĕ nuih n'hâm,$b$,false),
('bunong-vn','JER',29,14,null,$b$gâp mra ăn khân may mâp gâp,” Yêhôva lah, “jêh ri gâp mra mplơ̆ sĭt phung bu nă khân may jêh ri rgum tâm rƀŭn tay khân may bơh lĕ rngôch ntil mpôl bunuyh jêh ri bơh lĕ rngôch ntŭk gâp hŏ mprơh khân may.” Yêhôva lah, “jêh ri gâp mra njŭn sĭt khân may rlet ma ntŭk sa ơm tă bơh nĕ gâp nhŭp rdu jêh khân may ma bri êng.”$b$,false),
('bunong-vn','JER',29,15,null,$b$Yor lah khân may lah jêh, “Yêhôva ăn jêh ma hên phung kôranh nơm mbơh lor tâm Babilôn,”$b$,true),
('bunong-vn','JER',29,16,null,$b$pô aơ Yêhôva lah di ma hađăch gŭ ta sưng hađăch Đavit jêh ri di ma lĕ rngôch phung ƀon lan gŭ tâm ƀon toyh aơ, phung mpôl băl khân may bu mâu mprơh jêng bu nă ndrel khân may ôh.$b$,false),
('bunong-vn','JER',29,17,null,$b$Pô ri, aơ jêng nau ngơi Yêhôva ma phung ta han lah: “Aơ, gâp mra juăl đao dao, nau ât ji ngot, nau ji tưp, jêh ri gâp mra njêng khân păng nâm bu play rvi mhĭk ngăn kŏ tât bu mâu dơi sa ôh.$b$,false),
('bunong-vn','JER',29,18,null,$b$Gâp mra prơh khân păng ma đao dao, nau ât ji ngot, nau ji tưp, jêh ri gâp mra njêng khân păng du ntil ndơ nkrit ma lĕ rngôch phung ƀon bri hađăch ta neh ntu, ăn khân păng jêng du ntil ndơ bu rak rtăp, ntêh rmot, gơm mưch, jêh ri nau bu nduyh ta nklang lĕ rngôch mpôl băl bunuyh gâp hŏ mprơh jêh khân păng.$b$,false),
('bunong-vn','JER',29,19,null,$b$Yor lah khân păng mâu ŭch iăt ôh nau gâp ngơi,” Yêhôva lah, “nau ngơi nây gâp njuăl ƀa ƀơ ma khân may ta phung oh mon gâp jêng phung kôranh nơm mbơh lor, ƀiă lah khân may mâu ŭch iăt ôh,” Yêhôva lah.$b$,true),
('bunong-vn','JER',29,20,null,$b$Pô ri, iăt hom nau Yêhôva ngơi, Ơ lĕ rngôch phung bu nă gâp mprơh jêh tă ƀon Yêrusalem tât ma bri Babilôn:$b$,true),
('bunong-vn','JER',29,21,null,$b$Pô aơ Yêhôva ma phung ta han Brah Ndu Israel lah ma Y-Ahap kon bu klâu Y-Kôlaya, jêh ri Y-Sêdêkia kon bu klâu Y-Maseya, phung nây mbơh nau mƀruh ma khân may tâm amoh gâp: “Aơ, gâp mra jao khân păng ma ti Y-Nêbukatnetsar hađăch Babilôn, jêh ri păng mra nkhĭt khân păng ta năp khân may.$b$,false),
('bunong-vn','JER',29,22,null,$b$Yor ma khân păng lĕ rngôch phung Yuđa bu nhŭp veng tă bơh n'gor Yuđa gŭ tâm bri Babilôn ƀư bu nă mra sŏk bar hê aơ jêng nau ngơi rak rtăp, lah: ‘Dăn Yêhôva ăn ma may jêng nâm bu Y-Sêdêkia jêh ri Y-Ahap, hađăch Babilôn hŏ pâr jêh tâm ŭnh.’$b$,true),
('bunong-vn','JER',29,23,null,$b$Yor lah khân păng ƀư khân păng hŏ ƀư jêh nau rluk tâm bri Israel, khân păng văng tĭr jêh đah ur phung chiau meng khân păng, jêh ri khân păng ngơi jêh nau mƀruh tâm amoh gâp, nau gâp mâu mâp ntĭnh ôh ma khân păng. Gâp yơh jêng nơm gĭt nau nây, jêh ri jêng nơm mbơh ngăn,” Yêhôva lah.$b$,false),
('bunong-vn','JER',29,24,null,$b$Ăn may lah ma Y-Sêmaya tă ƀon Nêhêlam:$b$,true),
('bunong-vn','JER',29,25,null,$b$“Pô aơ Yêhôva ma phung ta han Brah Ndu Israel lah: May njuăl jêh ƀa ƀă sămƀŭt tâm amoh may nơm ma lĕ rngôch phung ƀon lan gŭ ta ƀon Yêrusalem jêh ri ma kôranh ƀư brah Y-Sôphôni kon bu klâu Y-Maseya, jêh ri ma lĕ rngôch phung kôranh ƀư brah, lah,$b$,false),
('bunong-vn','JER',29,26,null,$b$Yêhôva njêng jêh may kôranh ƀư brah ntrok an kôranh ƀư brah Y-Jêhôida, ăn may chiă uănh kan tâm ngih Yêhôva jêng kôranh ma mbu nơm rluk ntơ êng jêng nơm mbơh lor, gay nkông jêh ri gron lơi.$b$,false),
('bunong-vn','JER',29,27,null,$b$Pô ri mâm ƀư may mâu nduyh Y-Yêrêmi gŭ ta ƀon Anathôt mbơh lor ma may?$b$,false),
('bunong-vn','JER',29,28,null,$b$Yor lah păng hŏ njuăl jêh sămƀŭt ma hên tâm bri Babilôn, lah nau bu veng may tă bơh bri nơm mra jêng jŏ; ndâk hom ngih vâl, jêh ri gŭ tâm ngih nây, jêh ri ƀư đang biăp n'ha jêh ri sa n'ha păng.’ ”$b$,false),
('bunong-vn','JER',29,29,null,$b$Kôranh ƀư brah Y-Saphôni uănh sămƀŭt aơ ăn kôranh nơm mbơh lor Y-Yêrêmi iăt.$b$,true),
('bunong-vn','JER',29,30,null,$b$Nôk nây Yêhôva ngơi lah ma Y-Yêrêmi:$b$,false),
('bunong-vn','JER',29,31,null,$b$“Chih njuăl hom sămƀŭt ăn ma lĕ rngôch phung bu hŏ veng jêh, lah: ‘Pô aơ nau Yêhôva ngơi di ma Y-Sêmaya tă ƀon Nêhêlam: Yor lah Y-Sêmaya mbơh lor jêh ma khân may ƀiă lah gâp mâu mâp prơh păng hăn ôh, jêh ri păng ăn may rnơm ma nau mƀruh,’$b$,false),
('bunong-vn','JER',29,32,null,$b$yor nây Yêhôva lah pô aơ: ‘Aơ, gâp mra tâm rmal Y-Sêmaya, tă ƀon Nêhêlam, jêh ri ndŭl mpôl păng đŏng. Ma ndŭl mpôl păng, mâu mra geh du huê tâm phung ƀon lan păng hôm rêh mra saơ nau ueh gâp mra ƀư ma phung ƀon lan gâp, yor lah păng hŏ ngơi nau tâm rdâng đah Yêhôva.’ ” Yêhôva lah.$b$,false),
('bunong-vn','JER',30,1,null,$b$Yêhôva ngơi ma Y-Yêrêmi:$b$,true),
('bunong-vn','JER',30,2,null,$b$“Pô aơ Yêhôva Brah Ndu Israel lah: ‘Chih hom du lơp sămƀŭt lĕ rngôch nau gâp ngơi ma may.$b$,false),
('bunong-vn','JER',30,3,null,$b$Yor lah aơ, nar mra tât.’ Yêhôva lah, tơ lah gâp mra mplơ̆ sĭt tay nau ueh uĭn ma phung ƀon lan gâp, phung Israel jêh ri phung Yuđa, Yêhôva lah, ‘jêh ri gâp mra njŭn khân păng sĭt rlet ma bri gâp ăn jêh ma phung che khân păng, jêh ri khân păng mra gŭ chăm bri nây.’ ”$b$,false),
('bunong-vn','JER',30,4,null,$b$Aơ nau Yêhôva ngơi di ma phung Israel jêh ri phung Yuđa:$b$,true),
('bunong-vn','JER',30,5,null,$b$“Pô aơ Yêhôva ngơi, lah: ‘He tăng jêh bâr nter yor nau uh ah, nau djơh mhĭk, jêh ri mâu di nau đăp mpăn ôh.$b$,false),
('bunong-vn','JER',30,6,null,$b$Ôp hom aƀaơ ri jêh ri gĭt, dơi lĕ du huê bu klâu deh du huê kon? Pô ri mâm ƀư gâp saơ ăp nơm bu klâu kuăn ta gang bŭt păng nâm bu du huê bu ur veng deh? Mâm ƀư muh măt ăp nơm Jêng nglang pal da dê?$b$,true),
('bunong-vn','JER',30,7,null,$b$Krit ngăn! Nar nây dŭt toyh, kŏ tât mâu dơi geh ôh nar ƀa ƀă tâm ban pô nây; nây jêng rơh nau rêh ni tât ma phung Yakôp, ƀiă lah păng mra klaih bơh nau nây.$b$,true),
('bunong-vn','JER',30,8,null,$b$“Jêh ri mra geh nau tât nor nây,’ Yêhôva ma phung ta han lah, Gâp mra nkêch lơi mâng mbăk ta trô ko khân păng, jêh ri gâp mra ntăch lơi rse kât khân păng, jêh ri phung bu năch mâu mra njêng đŏng ma khân păng dĭk ôh.$b$,true),
('bunong-vn','JER',30,9,null,$b$Ƀiă lah khân păng mra pah kan ma Yêhôva Brah Ndu khân păng jêh ri Y-Đavit hađăch khân păng, nơm gâp mra ngluh ma khân păng.$b$,true),
('bunong-vn','JER',30,10,null,$b$“Pô ri, lơi klach ôh, Ơ phung Yakôp oh mon gâp,’ Yêhôva lah, mâu lĕ rdja nuih n'hâm, Ơ phung Israel, yor lah aơ, gâp mra rklaih may tă ntŭk ngai, jêh ri phung kon sau may bơh bri khân păng jêng bu nă. Phung Yakôp mra plơ̆ sĭt ueh lăng, đăp rmên jêh ri mâu geh nuyh ôh ƀư ma păng geh nau krit klach.$b$,true),
('bunong-vn','JER',30,11,null,$b$Yor lah gâp gŭ ndrel may ŭch tâm rklaih may,’ Yêhôva lah, ‘Lĕ rngôch phung mpôl băl êng gâp mra ƀư rai lĕ, tă nklang phung mpôl băl nây, gâp mprơh jêh may, ƀiă lah may gâp mâu mra ƀư rai lĕ ôh. Gâp mra nduyh nkra may ma nau tâm di, ƀiă lah mâu om ôh ăn may dơi klaih tă bơh nau tâm rmal?$b$,true),
('bunong-vn','JER',30,12,null,$b$“Yor lah pô aơ nau Yêhôva lah: ‘Nau ji may mâu blau bah ôh, jêh ri sôt rmanh may glăm ngăn.$b$,true),
('bunong-vn','JER',30,13,null,$b$Mâu geh ôh du huê gŭ mpeh ma may, mâu geh dak si săm bah sôt may, mâu geh nau ƀư bah ma may ôh,$b$,true),
('bunong-vn','JER',30,14,null,$b$Lĕ rngôch phung may rŏng lĕ chuêl jêh may, khân păng mâu chrê ôh ma may: Yor lah gâp hŏ dong may kŏ sôt nâm bu du huê rlăng dong, nau tâm rmal may nâm bu bunuyh rlăng mâu blau yô̆ ôh, yor lah nau may tih lĕ jêng toyh, yor lah nau tih may lĕ glăm jêh.$b$,false),
('bunong-vn','JER',30,15,null,$b$Mâm ƀư may nter yor ji sôt rmanh? Nau ji may mâu dơi bah, ôh. Yor lah nau may tih lĕ jêng toyh, Yor lah nau tih may lĕ glăm jêh, gâp ƀư jêh nau aơ ma may.$b$,true),
('bunong-vn','JER',30,16,null,$b$Yor nây lĕ rngôch mbu nơm kăp rvăn may bu mra kăp rvăn khân păng; jêh ri lĕ rngôch phung rlăng may, tâm ăp nơm, mra hăn jêng bu nă; jêh ri lĕ rngôch phung pit in may, mra jêng ndơ bu pit in, jêh ri lĕ rngôch phung nhŭp may, gâp mra ăn bu nhŭp khân păng tâm ban lĕ.$b$,true),
('bunong-vn','JER',30,17,null,$b$Yor lah gâp mra ƀư bah may, jêh ri ntŭk sôt may gâp mra ƀư bah lơi, Yêhôva lah: ‘Yor lah khân păng ntơ ma may nơm bu mƀăr lơi pa dih: Jêng ƀon Siôn yơh, mâu geh nơm chrê ma ô băl ôh!’$b$,true),
('bunong-vn','JER',30,18,null,$b$Pô aơ nau Yêhôva lah: ‘Aơ, gâp mra mplơ̆ sĭt nau ueh uĭn ma ngih bok phung Yakôp, jêh ri yô̆ an ntŭk khân păng gŭ; bu mra ndâk đŏng ƀon toyh ta klơ ntŭk ƀon ơm. Jêh ri ngih hađăch mra geh bunuyh gŭ tra ntŭk ơm păng gŭ kăl e.$b$,false),
('bunong-vn','JER',30,19,null,$b$Tă bơh ƀon nây bu mra tăng bâr mprơ tâm rnê, jêh ri bâr phung răm rhơn, Gâp mra ăn khân păng bĭk rơ̆ , jêh ri khân păng mâu mra jêng phung mpôl ƀhôi ôh; gâp mra ăn ma khân păng jêng phung bu yơk, jêh ri khân păng mâu mra jêng jê̆ ôh.$b$,true),
('bunong-vn','JER',30,20,null,$b$Phung kon khân păng mra jêng nâm bu rnôk sa ơm, jêh ri phung tâm rƀŭn mra jêng nâp ta năp gâp; jêh ri gâp mra tâm rmal lĕ rngôch phung tŭn jot khân păng.$b$,true),
('bunong-vn','JER',30,21,null,$b$Kôranh khân păng jêng du huê tâm phung khân păng nơm hađăch khân păng luh tă tâm nklang khân păng. Gâp mra ăn păng văch dăch gâp, jêh ri păng mra tât, Yor lah mbu nơm janh văch dăch gâp tơ lah gâp mâu jă ôh păng? Yêhôva lah.$b$,true),
('bunong-vn','JER',30,22,null,$b$Jêh ri khân may mra jêng phung ƀon lan gâp, jêh ri gâp mra jêng Brah Ndu khân may.”$b$,true),
('bunong-vn','JER',30,23,null,$b$Aơ, sial phŭt bơh Yêhôva! Nau nuih luh du jêh, nâm sial vănh blông ktang; Păng mra tât ƀât lât ta bôk phung ƀai.$b$,true),
('bunong-vn','JER',30,24,null,$b$Nau Yêhôva nuih duh mâu mra rŭch plơ̆ ôh tât păng ƀư ăn jêh. Jêh ri păng mĭn ŭch ƀư. Tâm rnôk nglĕ dŭt, khân may mra gĭt rbăng nau aơ.$b$,true),
('bunong-vn','JER',31,1,null,$b$Yêhôva lah: “Tâm rnôk nây, gâp mra jêng Brah Ndu ma lĕ rngôch mpôl băl Israel, jêh ri khân păng mra jêng phung ƀon lan gâp.”$b$,true),
('bunong-vn','JER',31,2,null,$b$Yêhôva lah pô aơ: “Phung ƀon lan hôm klen klaih bơh tak đao, geh jêh nau yô̆ tâm bri rdah, tơ lah gâp ăn phung Israel geh nau rlu.”$b$,true),
('bunong-vn','JER',31,3,null,$b$Yêhôva tâm mpơl jêh ma păng ntơm bơh sa ơm, lah: “Gâp hŏ rŏng jêh ma khân may ma nau rŏng n'ho ro; Yor nây gâp ut ra-u khân may ma nau ueh.$b$,true),
('bunong-vn','JER',31,4,null,$b$Gâp mra ndâk tay khân may, jêh ri khân may mra gŭ nâp, Ơ bu druh tang-tat phung Israel! Khân may mra ndjôt gâr jê̆ khân may jêh ri khân may mra hăn talơ̆ (kdŏ) ndrel ma phung ƀư nau răm maak.$b$,true),
('bunong-vn','JER',31,5,null,$b$Khân may tăm tay tơm play kriăk ƀâu ta klơ yôk Samari; phung tăm mra tăm, jêh ri mra sa play păng.$b$,true),
('bunong-vn','JER',31,6,null,$b$Yor lah mra geh du nar tơ lah phung gak mra kuăl tâm bri klơ dor Êphraim. ‘Dâk hom, ăn he hăn hao ma ƀon Siôn, ma Yêhôva Brah Ndu he.’ ”$b$,true),
('bunong-vn','JER',31,7,null,$b$Yor lah nteh ma nau răm rhơn yor phung Yakôp, jêh ri nter troh yor kôranh phung mpôl băl bunuyh; mbơh hom, tâm rnê hom, jêh ri lah, ‘Ơ Yêhôva, tâm rklaih hom phung ƀon lan may. Phung hôm klen tâm phung Israel,’$b$,true),
('bunong-vn','JER',31,8,null,$b$Aơ, gâp mra njŭn khân păng luh bơh bri dor jêh ri gâp mra rgum tâm rƀŭn khân păng bơh ntŭk bôl dŭt neh ntu ngai lơn, ta nklang khân păng phung chieh măt jêh ri phung rvĕn, phung bu ur hŏ ntreo jêh, jêh ri bu ur veng deh, du phung âk ngăn ngên mra sĭt ta aơ.$b$,false),
('bunong-vn','JER',31,9,null,$b$Khân păng mra văch ma nau nhĭm, gâp mra njŭn khân păng sĭt ma nau mbơh sơm. Gâp mra ăn khân păng chuat hăn ta meng n'hor dak, Ta du ntŭk trong sŏng ƀoi rŏ trong nây khân păng mâu geh nau chêh prah ôh. Yor lah gâp jêng mbơ̆ ma phung Israel, Jêh ri phung Êphraim jêng kon bu klâu gâp deh ntơm sa ơm.$b$,true),
('bunong-vn','JER',31,10,null,$b$“Iăt hom nau Yêhôva ngơi, Ơ phung mpôl băl bunuyh; jêh ri mbơh nau nây ma phung gŭ tâm kô mƀŭt ngai ri; “Nơm lơh pru pra jêh phung Israel mra tâm rƀŭn tay khân păng, jêh ri mra chiă uănh khân păng nâm bu rmăk biăp mât chiăp phung biăp păng,”$b$,true),
('bunong-vn','JER',31,11,null,$b$Yor lah Yêhôva sâm chuai jêh phung Yakôp, jêh ri hŏ rklaih jêh khân păng tă bơh ti nơm dăng ktang lơn ma khân păng.$b$,true),
('bunong-vn','JER',31,12,null,$b$Khân păng mra tât jêh ri mprơ nteh ta klơ yôk Siôn, jêh ri khân păng mra răm rhơn yor nau ueh Yêhôva; yor ba, dak play kriăk ƀâu, jêh ri dak play Ôlivơ, jêh ri yor âk kon biăp, be, ndrôk, jêh ri seh; huêng khân păng mra jêng nâm bu đang biăp n'ha djrah bĕ dak. Jêh ri khân păng mâu mra rngot đŏng ôh.$b$,true),
('bunong-vn','JER',31,13,null,$b$Phung bu druh tang-tat mra rhơn dôl talơ̆ (kdŏ), jêh ri phung bu klâu ndăm nđâp ma bu klâu bu ranh mra răm maak. Gâp mra tâm rgâl nau klân rvê khân păng jêng nau hâk răm, Gâp mra bonh leng khân păng jêh ri ăn ma khân păng nau hâk răm ntrok nau rngot.$b$,true),
('bunong-vn','JER',31,14,null,$b$Gâp mra ăn ma kôranh ƀư brah ndơ sông sa ueh uĭn, jêh ri phung ƀon lan gâp mra hơm ma nau ueh gâp.” Yêhôva lah.$b$,true),
('bunong-vn','JER',31,15,null,$b$Pô aơ Yêhôva lah: “Tâm ƀon Rama bu tăng bâr nau nhĭm vơl rngot, H'Rachel nhĭm vơl yor kon păng; păng mâu dơn ôh nau bu bonh leng păng, yor lah phung kon păng mâu hôm rêh ôh.”$b$,true),
('bunong-vn','JER',31,16,null,$b$Pô aơ nau Yêhôva lah: “Ât, lơi hôm ay nhĭm ôh lơi hôm ay hor dak măt ôh yor lah kan khân ay bu geh nau nkhôm; jêh ri khân păng mra plơ̆ sĭt tă bri phung rlăng khân păng. Yêhôva ngơi lah.$b$,true),
('bunong-vn','JER',31,17,null,$b$Yêhôva lah: “Mra geh nau kâp gân ma rnôk nglĕ dŭt, jêh ri phung kon khân may mra plơ̆ sĭt rlet ma bri khân păng nơm.$b$,true),
('bunong-vn','JER',31,18,null,$b$Gâp tăng jêh phung Êphraim vơl, lah: “May hŏ đăp-nkra jêh gâp, nâm bu du mlâm kon ndrôk ê hŏ bu dăp jêh ri gâp lĕ dơn jêh nau nây; njŭn hom gâp plơ̆ sĭt gay ma gâp dơi geh nau ueh uĭn, yor lah may jêng Yêhôva Brah Ndu gâp.$b$,true),
('bunong-vn','JER',31,19,null,$b$Nanê̆, lah gâp plơ̆ sĭt jêh, gâp hŏ nhăl rmal, jêh bu ƀăp nti gâp, gâp hŏ tap ta blu gâp nơm; gâp prêng jêh, jêh ri gâp uh ah, yor lah gâp anh nau bu mưch rmot bơh nôk gâp hôm mom.$b$,true),
('bunong-vn','JER',31,20,null,$b$Pô ri, di lĕ phung Êphraim jêng kon bu klâu gâp rŏng? Di lĕ khân păng jêng kon gâp mƀrô? Yor lah ndah tơ̆ gâp ngơi rdâng đah păng gâp ăt kah gĭt lĕ ma păng. Yor nây nuih n'hâm gâp klâng, n'hêl nanê̆ gâp mra yô̆ ma păng.” Yêhôva lah.$b$,true),
('bunong-vn','JER',31,21,null,$b$“Ndâk hom n'gâng nau tâm nal ƀĭt gai; ntĭm trong; sek uănh nanê̆ trong toyh, njŏ trong nây may hŏ chuat jêh. Plơ̆ sĭt hom, Ơ bu druh tang tat Israel, plơ̆ sĭt hom lĕ rngôch ƀon toyh aơ jêng ƀon khân may!$b$,true),
('bunong-vn','JER',31,22,null,$b$Ndah nâm jŏ khân ay mra du mblêng, Ơ phung bu ur mâu geh nau răp jăp ôh? Yor lah Yêhôva hŏ rhăk njêng jêh du ntil ndơ mhe ta klơ neh ntu: Nây jêng du huê bu ur mra nkŭm nking du huê bu klâu.”$b$,true),
('bunong-vn','JER',31,23,null,$b$Pô aơ Yêhôva ma phung ta han Brah Ndu Israel, lah: “Tơ lah gâp hŏ ndjôt leo lĕ rngôch phung bu nă plơ̆ sĭt jêh, pô ri tâm n'gor Yuđa jêh ri lĕ rngôch phung ƀon toyh păng, bu mâu hôm ngơi nau ngơi aơ: ‘Hơi ntŭk nau sŏng gŭ, ntŭk gôl yôk nau kloh ueh ri, dăn ma Yêhôva ăn nau ueh uĭn ma khân may!$b$,true),
('bunong-vn','JER',31,24,null,$b$N'gor Yuđa jêh ri lĕ rngôch ƀon toyh păng, phung ƀư mir jêh ri phung rmăk leo phung biăp mra gŭ ndrel ta nây.$b$,true),
('bunong-vn','JER',31,25,null,$b$Yor lah gâp mra ƀư nuih n'hâm hŏt ra-ah dơi hơm răm, jêh ri gâp mra n'hao nuih phung rngot”.$b$,true),
('bunong-vn','JER',31,26,null,$b$Nôk nây gâp kah rngăl jêh ri uănh, gâp bêch jêh dăp mpăn.$b$,true),
('bunong-vn','JER',31,27,null,$b$Yêhôva ngơi, lah: “Aơ, nar mra tât, nôk nĕ gâp mra sŏk ntil bunuyh jêh ri ntil mpô mpa srih tâm ntŭk ngih Israel jêh ri Yuđa.$b$,true),
('bunong-vn','JER',31,28,null,$b$Nâm bu gâp sek uănh jêh ma khân păng gay rôk, ƀư rai, nklơ̆ , rlâm, jêh ri ăn tât nau mhĭk, tâm ban pô nây lĕ gâp mra chiă njrăng khân păng gay ndâk tay jêh ri tăm,” Yêhôva lah pô nây.$b$,true),
('bunong-vn','JER',31,29,null,$b$Tâm nar nây khân păng mâu hôm lah ôh: ‘Mbơ̆ sa play kriăk ƀâu srat yor kon sau hĭr sêk.’$b$,false),
('bunong-vn','JER',31,30,null,$b$Ƀiă lah ăp nuyh mra khĭt yor nau tih păng nơm; ăp nơm mbu moh sa play kriăk ƀâu srat mra kĭr sêk păng nơm.$b$,false),
('bunong-vn','JER',31,31,null,$b$Yêhôva lah: “Aơ, nôk mra tât, ta nây gâp mra ƀư du nau tâm rnglăp mhe đah ngih Israel jêh ri đah ngih Yuđa.$b$,true),
('bunong-vn','JER',31,32,null,$b$Nau tâm rnglăp aơ mâu di ôh nâm bu nau tâm rnglăp gâp hŏ ƀư jêh đah phung che khân păng tâm nar gâp tâm kuăn ti đah khân păng gay njŭn khân păng du luh tă bơh n'gor bri Êjipt, nau gâp tâm rnglăp nây khân păng hŏ rlau lơi jêh, nđâp lah gâp jêng sai khân păng kđôi lĕ.” Yêhôva lah.$b$,false),
('bunong-vn','JER',31,33,null,$b$Yêhôva lah: “Aơ jêng nau tâm rnglăp gâp mra ƀư đah ngih Israel pa kơi jêh nar nây. Gâp mra dơm nau vay tâm trôm ndŭl khân păng jêh ri gâp mra chih nau nây tâm nuih n'hâm khân păng; jêh ri gâp mra jêng Brah Ndu khân păng jêh ri khân păng mra jêng ƀon lan gâp.$b$,true),
('bunong-vn','JER',31,34,null,$b$Ăp nơm mâu mra sâm nti ôh ma nơm chiau meng păng jêh ri oh nâu păng, lah: ‘Gĭt năl hom Yêhôva! Yor lah lĕ rngôch khân păng gĭt năl gâp, ntơm bơh nơm jê̆ lơn tât ma nơm toyh lơn,’ Yêhôva lah, “Yor lah gâp mra yô̆ an khân păng, jêh ri gâp mâu mra nkah đŏng ôh nau tih khân păng.”$b$,false),
('bunong-vn','JER',31,35,null,$b$Yêhôva, jêng Nơm hŏ ăn jêh măt nar dơi sol ang dôl nar, jêh ri tâm nal jêh ma khay jêh ri mănh dôl măng, nơm ƀư mpât dak mƀŭt ăn păng rbuh. Yêhôva ma phung ta han jêng amoh Păng:$b$,true),
('bunong-vn','JER',31,36,null,$b$“Tơ lah nau vay nây roh jêh bơh ta năp gâp,” Yêhôva lah, “pô nây lĕ phung kon sau Israel mra lôch dŭt, mâu hôm jêng du mpôl băl ta năp gâp n'ho ro, Yêhôva lah.$b$,false),
('bunong-vn','JER',31,37,null,$b$Pô aơ nau Yêhôva lah: “Tơ lah dơi veh trôk ta klơ, jêh ri tơ lah bu dơi sek uănh mbon neh ntu tâm dâng, nôk nĕ gâp mra ngroh lơi (ƀư roh) lĕ rngôch phung kon sau Israel yor nau khân păng ƀư ăp ntil, Yêhôva lah,$b$,true),
('bunong-vn','JER',31,38,null,$b$“Aơ, nôk nar tât” Yêhôva lah, “tơ lah bu ndâk ƀon ma Yêhôva ntơm bơh ngih tŭm Hananel tât Mpông Pêr Njônh.$b$,false),
('bunong-vn','JER',31,39,null,$b$Nau veh mra tât ngai lơn, tâm sŏng đah gôl Garep, jêh ri tă bơh nây rlĕ mpeh Gôa.$b$,true),
('bunong-vn','JER',31,40,null,$b$Glom lĕ rlŭng drô phan jêh ri ŭnh buh, lĕ rngôch mir ngai n'gŏ dak n'hor Kitdrôn, tât ta njônh Mpông pêr seh mpeh pa lơ, mra jêng ntŭk prăp ăn ma Yêhôva. Bu mâu mra rôk lơi păng đŏng ôh, mâu lĕ mra rlâm lơi n'ho ro.”$b$,true),
('bunong-vn','JER',32,1,null,$b$Yêhôva ngơi ma Y-Yêrêmi tâm năm rơh jât Y-Sêdêkia jêng hađăch Yuđa, jêng năm rơh jât ma pham Y-Nêbukatnetsar chiă uănh.$b$,true),
('bunong-vn','JER',32,2,null,$b$Tâm rnôk nĕ phung ta han hađăch Babilôn gŭ nchueng lơh ƀon Yêrusalem, jêh ri bu krŭng jêh kôranh nơm mbơh lor Y-Yêrêmi tâm nhuang ngih, phung ta han gak tâm ngih hađăch Yuđa.$b$,false),
('bunong-vn','JER',32,3,null,$b$Yor lah Y-Sêsêkia hađăch Yuđa hŏ krŭng jêh ô băl, lah: “Moh nau may mbơh lor, lah, ‘pô aơ Yêhôva lah: Aơ, gâp jao ƀon toyh aơ ma ti hađăch Babilôn, jêh ri păng mra dơi pit in ô băl;$b$,false),
('bunong-vn','JER',32,4,null,$b$Y-Sêdêkia hađăch Yuđa mâu mra klaih ôh bơh ti phung Kaldê, ƀiă lah nanê̆ ngăn bu mra jao ô băl tâm ti hađăch Babilôn, jêh ri ô băl mra ngơi ma hađăch Babilôn, mbung ndrăng mbung, măt uănh măt;$b$,false),
('bunong-vn','JER',32,5,null,$b$hađăch nhŭp Y-Sêdêkia leo nsĭt rlet Babilôn, păng mra gŭ ta nây kŏ tât gâp chop khâl păng, Yêhôva lah. Nđâp lah khân may tâm lơh đah phung Kaldê kđôi, may mâu mra dơi ôh.”$b$,false),
('bunong-vn','JER',32,6,null,$b$Y-Yêrêmi lah; “Yêhôva ngơi ma gâp lah:$b$,true),
('bunong-vn','JER',32,7,null,$b$Aơ, Y-Hanamel kon bu klâu Y-Salum kônh may mra văch ma may jêh ri lah, ‘Rvăt hom mir gâp ta ƀon Anathôt, yor lah nau dơi chuai ma rnoh prăk jêng di ma may.’$b$,false),
('bunong-vn','JER',32,8,null,$b$Pô ri Y-Hanamel kon bu klâu kônh gâp, văch ma gâp tâm nhuang ntŭk phung ta han gak, tĭng nâm nau Yêhôva ngơi. Jêh ri lah ma gâp, ‘Rvăt hom mir gâp ta ƀon Anathôt tâm bri Benjamin, yor lah nau vay dơi geh jêh ri chuai jêng ndơ ma may; rvăt hom păng ăn ma may nơm; pô ri gâp gĭt nau nây jêng nau Yêhôva ngơi!$b$,false),
('bunong-vn','JER',32,9,null,$b$“Jêh ri gâp rvăt mir ta ƀon Anathôt bơh Y-Hanamel kon kônh gâp, jêh ri klăp rnoh prăk ăn ma păng, jât ma pơh sêkel prăk.$b$,true),
('bunong-vn','JER',32,10,null,$b$Gâp chih amoh săk ta sămƀŭt rvăt, tâp pŏng păng, jă bunuyh mbơh gĭt nanê̆ jêh ri rnhueh rnoh prăk ta klơ njing.$b$,true),
('bunong-vn','JER',32,11,null,$b$Jêh ri gâp sŏk săm ƀŭt rvăt, tâp pŏng jêh geh nau vay tâm nkol chih jêh tâm nĕ, jêh ri sămƀŭt chih kơt mâu geh tâp pŏng ôh;$b$,false),
('bunong-vn','JER',32,12,null,$b$jêh ri gâp ăn săm ƀŭt rvăt nây ma Y-Baruk kon bu klâu Y-Nêria sau Y-Mahseya, ta năp Y-Hanamel kon kônh gâp, ta năp bunuyh mbơh gĭt nanê̆ phung nây chih kach amoh khân păng ta săm ƀŭt rvăt, jêh ri ta năp lĕ rngôch phung Yuđa gŭ tâm nhuang ntŭk phung ta han gak.$b$,false),
('bunong-vn','JER',32,13,null,$b$Gâp ntĭnh ma Y-Baruk ta năp khân păng, lah,$b$,false),
('bunong-vn','JER',32,14,null,$b$“Pô aơ Yêhôva ma phung ta han Brah Ndu Israel lah: Sŏk hom sămƀŭt rvăt aơ, sămƀŭt lĕ tâp pŏng jêh, nđâp sămƀŭt ê hŏ tâp pŏng ôh, dơm ăn khân păng tâm yăng gay dơi prăp jŏ.$b$,false),
('bunong-vn','JER',32,15,null,$b$Yor lah pô aơ nau Yêhôva ma phung ta han Brah Ndu Israel lah: ‘Bu mra rvăt đŏng ngih, mir, jêh ri đang play kriăk ƀâu tâm bri aơ.’$b$,false),
('bunong-vn','JER',32,16,null,$b$“Jêh ri gâp jao sămƀŭt rvăt nây ma Y-Baruk kon bu klâu Y-Nêria, gâp mbơh sơm ma Yêhôva, lah:$b$,false),
('bunong-vn','JER',32,17,null,$b$Ơ Yêhôva Brah Ndu ơi! May yơh geh nau brah toyh jêh ri mpang ti may rhăk jêh trôk jêh ri neh ntu; mâu geh ôh du ntil nau jêng jêh ir ma may.$b$,false),
('bunong-vn','JER',32,18,null,$b$May tâm mpơl nau yô̆ âk rbăn nuyh, ƀiă lah ăn tŭp nau jêng tih phung mbơ̆ tât ma phung kon sau khân păng thoi pa kơi. May jêng Brah Ndu dŭt toyh, jêng Nơm geh nau brah, amoh may jêng Yêhôva ma phung ta han,$b$,false),
('bunong-vn','JER',32,19,null,$b$geh nau blau mĭn toyh jêh ri brah dơi ƀư lĕ rngôch; nơm gŭ uănh ma lĕ rngôch trong bunuyh, ăn nau nkhôm ma ăp nơm bunuyh tĭng nâm trong păng, jêh ri tĭng nâm play tă bơh kan păng ƀư;$b$,false),
('bunong-vn','JER',32,20,null,$b$nơm tâm mpơl jêh nau mbên jêh ri nau khlay ir ar tâm n'gor bri Êjipt n'ho tât ma nar aơ tâm bri Israel jêh ta nklang lĕ rngôch mpôl băl bunuyh, jêh ri ăn amoh may geh nau lư n'găr jêh, nâm bu geh jêh tâm nar aơ.$b$,false),
('bunong-vn','JER',32,21,null,$b$May hŏ njŭn leo jêh phung ƀon lan may Israel du luh tă bơh n'gor bri Êjipt geh nau mbên jêh ri nau khlay ir ar, ma mpang ti ktang jêh ri ti yơr jêh, jêh ri nau nkrit toyh.$b$,false),
('bunong-vn','JER',32,22,null,$b$May hŏ ăn jêh bri aơ ma khân păng, bri may hŏ ton săk jêh ma phung che khân păng kăl e gay ăn ma khân păng, du mlâm bri geh ndơ sông sa rmeh ler.”$b$,false),
('bunong-vn','JER',32,23,null,$b$Khân păng lăp sŏk chăm jêh bri nây. Ƀiă lah khân păng mâu ŭch tông bâr may ôh, mâu lĕ ŭch chuat hăn tĭng nau vay may; khân păng mâu ôh du ntil tâm lĕ rngôch nau may ntăm jêh ma khân păng. Yor nây may ăn tât jêh lĕ nau mhĭk aơ ma khân păng.$b$,true),
('bunong-vn','JER',32,24,null,$b$“Aơ, ăp ntŭk pôih! Khân păng hŏ nchueng tât êp ƀon toyh, gay lơh pit in păng. Yor ma tak đao, sa sât ji ngot nau ji tưp, bu jao jêh ƀon aơ tâm ti phung Kaldê dôl tâm lơh đah khân păng. Nau may ngơi hŏ jêng nanê̆ ngăn jêh, aơ, may hŏ saơ nau nây.$b$,true),
('bunong-vn','JER',32,25,null,$b$Ơ Yêhôva, may hŏ ngơi lah jêh ma gâp: ‘Rvăt hom mir ma rnoh prăk jêh ri joi hom bunuyh mbơh gĭt nanê̆ ’, nđâp lah bu jao jêh ƀon aơ tâm ti phung Kaldê kđôi.”$b$,false),
('bunong-vn','JER',32,26,null,$b$Yêhôva ngơi ma Y-Yêrêmi:$b$,true),
('bunong-vn','JER',32,27,null,$b$Aơ, gâp jêng Yêhôva Brah Ndu ma lĕ rngôch bunuyh, geh lĕ moh nau jêr ir ma gâp mâu dơi ƀư ôh?$b$,false),
('bunong-vn','JER',32,28,null,$b$Yor ri, Yêhôva lah pô aơ: Aơ, gâp jao ƀon aơ tâm ti phung Kaldê jêh ri ma ti Y-Nêbukatnetsar hađăch Babilôn, jêh ri păng mra lơh pit in.$b$,false),
('bunong-vn','JER',32,29,null,$b$Phung Kaldê dôl tâm lơh đah ƀon aơ mra văch tât su ƀon aơ, mpoh ŭnh jêh ri su ro, su nđâp ma ngih bu su ndơ ƀâu kah nhhơr ma brah Baal ta klơ chor, jêh ri bu nkhŭt ndơ nhhơr nhêt ăn ma brah êng, gay nsônh nuih gâp.$b$,true),
('bunong-vn','JER',32,30,null,$b$Yor lah phung kon Israel jêh ri phung kon Yuđa, ntơm bơh nôk khân păng mom, ƀư knŏng nau mhĭk ta năp măt gâp; yor lah phung kon Israel knŏng nsônh ăn gâp ji nuih yor kan ti khân păng ƀư, Yêhôva lah.$b$,true),
('bunong-vn','JER',32,31,null,$b$Ƀon aơ ŭch n'hao nau gâp ji nuih jêh ri nau nuih ntơm bơh nar bu ndâk păng n'ho tât nar aơ, pô ri gâp mra ƀư rai păng tra năp măt gâp.$b$,true),
('bunong-vn','JER',32,32,null,$b$Yor lah lĕ rngôch nau mhĭk phung kon Israel jêh ri phung kon Yuđa hŏ ƀư gay nsônh nuih gâp, phung hađăch khân păng, phung kôranh khân păng, phung kôranh ƀư brah, jêh ri phung kôranh nơm mbơh lor khân păng, phung Yuđa jêh ri phung gŭ tâm ƀon Yêrusalem đŏng.$b$,false),
('bunong-vn','JER',32,33,null,$b$Khân păng ndôn kơi khân păng ma gâp jêh ri pôn muh măt khân păng; nđâp lah gâp hŏ nti khân păng, ƀa ƀơ kđôi, khân păng mâu ŭch iăt ro, jêh ri mâu dơn nau ntĭm nti.$b$,false),
('bunong-vn','JER',32,34,null,$b$Khân păng hŏ ndâk jêh ndơ gâp tâm rmot tâm trôm ngih bu ntơ ma Amoh gâp, gay ƀư ƀơ̆ ƀơch.$b$,false),
('bunong-vn','JER',32,35,null,$b$Khân păng hŏ ndâk jêh ntŭk prêh klơ ăn ma brah Baal tâm rlŭng kon bu klâu Y-Hinôm, gay nhhơr ma brah Môlok phung kon bu klâu jêh ri phung kon bu ur khân păng tâm ŭnh, nây jêng nau gâp mâu geh ntăm ma khân păng ôh, mâu mâp lĕ mĭn ma nau nây, gay ma khân păng ƀư nau gâp tâm rmot aơ, gay ăn phung Yuđa ƀư tih.$b$,false),
('bunong-vn','JER',32,36,null,$b$“Yor nây Yêhôva Brah Ndu Israel lah nau aơ di ma ƀon may lah aơ. Bu jao jêh ƀon aơ tâm ti hađăch Babilôn ma đao dao, nau sa sât ji ngot jêh ri nau ji tưp;$b$,true),
('bunong-vn','JER',32,37,null,$b$aơ, gâp mra rgum tâm rƀŭn khân păng tă bơh lĕ rngôch bri gâp mprơh khân păng yor ma gâp hao nuih jêh ri ji nuih ngăn. Gâp mra njŭn khân păng plơ̆ sĭt ma ntŭk aơ, jêh ri gâp mra ăn khân păng gŭ ma nau đăp rmên.$b$,false),
('bunong-vn','JER',32,38,null,$b$Khân păng mra jêng phung ƀon lan gâp, jêh ri gâp mra jêng Brah Ndu khân păng.$b$,false),
('bunong-vn','JER',32,39,null,$b$Gâp mra ăn ma khân păng du nuih n'hâm jêh ri du trong, gay ma khân păng dơi klach yơk ma gâp n'ho ro, nau nây jêng ueh ma khân păng nơm jêh ri jêng ueh ma phung kon sau khân păng kăndơ̆ .$b$,false),
('bunong-vn','JER',32,40,null,$b$Gâp mra ƀư nau tâm rnglăp n'ho ro đah khân păng, gay ma gâp mâu lơi ôh nau ƀư ueh ma khân păng; jêh ri gâp mra dơm nau klach yơk ma gâp tâm nuih n'hâm khân păng, gay ma khân păng mâu cha lơi ôh gâp.$b$,false),
('bunong-vn','JER',32,41,null,$b$Gâp mra maak ƀư nau ueh ma khân păng, jêh ri gâp mra tăm khân păng ma nau ngăn tâm bri aơ, ma lĕ nuih n'hâm jêh ri ma lĕ huêng gâp.$b$,false),
('bunong-vn','JER',32,42,null,$b$“Yêhôva ngơi lah pô aơ: Nâm bu gâp hŏ ăn tât jêh nau mhĭk toyh ma phung ƀon lan aơ, tâm ban pô nây lĕ gâp mra ăn tât ma khân păng lĕ nau ueh gâp, hŏ ton jêh ma khân păng,$b$,true),
('bunong-vn','JER',32,43,null,$b$Bu mra rvăt mir tâm bri aơ, ma bri nây may ngơi aƀaơ ri, Păng lĕ jêng rngol jêh, mâu geh bunuyh gŭ ôh, mâu lĕ hôm geh mpô mpa; bu jao jêh ô băl tâm ti phung Kaldê?$b$,false),
('bunong-vn','JER',32,44,null,$b$Bu mra rvăt mir ma prăk, jêh ri bu mra chih sămƀŭt rvăt, jêh ri tâp pŏng, joi bu nuyh nơm gĭt nanê̆ ma sămƀŭt rvăt tâm bri Benjamin, tâm ntŭk văr jŭm ƀon Yêrusalem, jêh ri tâm lĕ rngôch ƀon n'gor Yuđa, tâm lĕ rngôch bri klơ dor, jêh ri lĕ rngôch bri neh lâng, jêh ri tâm lĕ rngôch ƀon bri rđŭng pa dâng. Yor lah gâp mra ăn phung jêng bu nă plơ̆ sĭt tay đŏng, Yêhôva lah.$b$,false),
('bunong-vn','JER',33,1,null,$b$Yêhôva ngơi ma Y-Yêrêmi tŏ bar dôl păng hôm bu krŭng tâm nhuang ntŭk ta han gak:$b$,true),
('bunong-vn','JER',33,2,null,$b$“Pô aơ Yêhôva lah, Nơm njêng jêh neh ntu, Yêhôva jêng Nơm rhăk njêng păng, jêh ri ŭch ƀư nâp păng Yêhôva jêng amoh păng:$b$,false),
('bunong-vn','JER',33,3,null,$b$Kuăl mbơh sơm hom ma gâp, jêh ri gâp mra plơ̆ sĭt lah ma may, jêh ri gâp mra mbơh ma may ndơ toyh jêh ri ndâp, ndơ may mâu mâp gĭt ôh!$b$,false),
('bunong-vn','JER',33,4,null,$b$Yor lah pô aơ Yêhôva Brah Ndu Israel lah nau di ma ngih tâm ƀon aơ jêh ri ngih phung hađăch Yuđa bu rơih jêh gay njêng mpêr king nau bu nchueng lơh jêh ri king đah đao dao$b$,false),
('bunong-vn','JER',33,5,null,$b$Dôl phung Kaldê, văch mŭt ŭch tâm lơh: ‘Gâp mra ăn bêng ngih vâl aơ ma drô phan (bunuyh khĭt) phung gâp hŏ nkhĭt ma gâp duh nuih jêh ri ji nuih, yor lah gâp pôn jêh muh măt gâp tă ƀon aơ yor nau mhĭk khân păng.$b$,false),
('bunong-vn','JER',33,6,null,$b$Aơ, gâp mra ăn n'hâm suan ngăch prăl ma păng, jêh ri nau ƀư bah; gâp mra ƀư bah khân păng, mra tâm mpơl ma khân păng saơ nau chăt jêng rmeh ler jêh ri đăp rmên ngăn ngên.$b$,false),
('bunong-vn','JER',33,7,null,$b$Gâp mra ăn nau ueh uĭn ma phung bu nă Yuđa jêh ri bu nă Israel plơ̆ sĭt; ndâk tay khân păng nâm bu sa-ơm.$b$,true),
('bunong-vn','JER',33,8,null,$b$Gâp mra ƀư kloh khân păng lĕ rngôch nau tih jêh đah gâp jêh ri gâp mra yô̆ an lĕ rngôch nau khân păng jêng tih; jêh ri nau khân păng hŏ tâm rdâng jêh đah gâp.$b$,false),
('bunong-vn','JER',33,9,null,$b$Ƀon aơ mra ăn ma gâp geh amoh răm maak, nau tâm rnê, nau chrêk lơp ta năp măt lĕ rngôch phung mpôl băl bunuyh ta neh ntu, khân păng mra tăng lĕ rngôch nau ueh gâp ƀư ăn khân păng, pô ri khân păng klaih da dê jêh ri râm nsâr yor lah lĕ nau ueh jêh ri nau chăt jêng gâp mra ăn ma ƀon aơ.$b$,false),
('bunong-vn','JER',33,10,null,$b$“Pô aơ nau Yêhôva lah: ‘Tâm ntŭk aơ khân may lah, ‘Ntŭk nsoih mâu geh bunuyh jêh ri mpô mpa ôh,” tâm lĕ rngôch ƀon n'gor Yuđa jêh ri tâm trong ƀon toyh Yêrusalem lĕ jêng rngol jêh, mâu geh bunuyh, ƀon lan gŭ, mâu lĕ mpô mpa,$b$,true),
('bunong-vn','JER',33,11,null,$b$bu mra hôm tăng ta nĕ bâr răm maak jêh ri, răm rhơn, bâr bu klâu ntơm nđăp ur jêh ri bâr ƀăn mhe, bâr phung mprơ dôl khân păng leo ndơ nhhơr tâm rnê tâm ngih Yêhôva: “Tâm rnê hom ma Yêhôva ma phung ta han, yor lah Yêhôva jêng ueh; yor lah nau ueh Păng gŭ ƀa ƀơ n'ho ro!” Jêh ri phung leo ndơ nhhơr tâm rnê tâm ngih Yêhôva. Yor lah gâp mra ăn phung bu nă bri aơ plơ̆ sĭt, ƀư nâm bu sa ơm, Yêhôva hŏ lah jêh.$b$,false),
('bunong-vn','JER',33,12,null,$b$Yêhôva ma phung ta han lah pô aơ: Tâm ntŭk aơ jêng ntŭk lĕ rngot, mâu geh bunuyh bunun ôh, mâu lĕ hôm geh mpô mpa, jêh ri tâm ăp rplay ƀon păng, mra lâp jêng ntŭk ma phung rmăk biăp gay ăn phung biăp păng gŭ rlu.$b$,true),
('bunong-vn','JER',33,13,null,$b$Tâm lĕ rngôch ƀon bri klơ dor, tâm lĕ rngôch ƀon bri rđŭng pa dâng, tâm bri Benjamin, ntŭk gŭ jŭm ƀon Yêrusalem, jêh ri tâm lĕ rngôch ƀon n'gor Yuđa, biăp mra geh tâm ti bunuyh kơp khân păng.’ Yêhôva lah.$b$,false),
('bunong-vn','JER',33,14,null,$b$“Aơ, nôk nar tât” Yêhôva lah, ‘nôk nĕ gâp mra ƀư di n'hêl nê̆ nau gâp hŏ ton jêh ma ngih Israel jêh ri ma ngih Yuđa.$b$,true),
('bunong-vn','JER',33,15,null,$b$Tâm nar nây jêh ri tâm rô̆ nây, gâp mra ăn hon chăt du N'gĭng nau sŏng ăn Y-Đavit; Nơm nây dơi ƀư nau sŏng jêh ri nau di tâm bri nĕ.$b$,true),
('bunong-vn','JER',33,16,null,$b$Tâm nar nây n'gor Yuđa mra klaih; ƀon Yêrusalem mra gŭ ma nau đăp rmên.’ Jêh ri amoh păng bu mra dơi ntơ pô aơ: Yêhôva Nau Sŏng He.$b$,false),
('bunong-vn','JER',33,17,null,$b$Pô ri, Yêhôva ngơi lah pô aơ: ‘Y-Đavit mâu mra pưt ôh du huê bu klâu gay gŭ ta sưng hađăch ngih Israel,$b$,false),
('bunong-vn','JER',33,18,null,$b$phung kôranh ƀư brah, jêng phung Lêvi, ăt mâu pưt lĕ du huê bunuyh ta năp măt gâp gay nhhơr ndơ nhhơr gŭch, gŭch ndơ nhhơr piăng let rnih, jêh ri gŭ ƀư brah ƀa ƀơ.’$b$,false),
('bunong-vn','JER',33,19,null,$b$Nau Yêsu lah ma Y-Yêrêmi pô aơ:$b$,false),
('bunong-vn','JER',33,20,null,$b$“Yêhôva lah: ‘Tơ lah khân may dơi rlau nau gâp tâm rnglăp đah nar jêh ri nau gâp tâm rnglăp đah măng, kŏ tât mâu geh ôh nar jêh ri măng tât di rơh păng,$b$,false),
('bunong-vn','JER',33,21,null,$b$ri mơ dơi rlau nau tâm rnglăp gâp đah Y-Đavit, oh mon gâp, tât păng mâu hôm geh ôh kon sau jêng hađăch chiă uănh gŭ ta sưng hađăch păng, jêh ri dơi rlau nau gâp tâm rnglăp đah kôranh ƀư brah Lêvi, phung pah kan ma gâp.$b$,false),
('bunong-vn','JER',33,22,null,$b$Bu mâu dơi kơp ôh mănh klơ trôk, jêh ri mâu dơi rnhueh ôh choih dak mƀŭt, tâm ban pô nây lĕ gâp ăn bĭk rơ̆ phung kon sau oh mon gâp Y-Đavit, jêh ri phung kôranh brah Lêvi pah kan ma gâp.’ ”$b$,false),
('bunong-vn','JER',33,23,null,$b$Nau Yêhôva ngơi lah tay ma Y-Yêrêmi pô aơ:$b$,true),
('bunong-vn','JER',33,24,null,$b$“May mâu sek uănh hĕ nau phung ƀon lan aơ ngơi? Khân păng lah: Bar ndŭl mpôl Yêhôva hŏ săch, pô ri lĕ Păng cha lơi jêh. Pô nây, khân păng mưch rmot ƀon lan gâp, tât khân păng mâu hôm uănh geh jêng du ndŭl mpôl (du bri dak) đŏng ôh!$b$,false),
('bunong-vn','JER',33,25,null,$b$Ƀiă lah, aơ jêng nau Yêhôva lah: “Tơ lah nau gâp tâm rnglăp đah nar jêh ri đah măng mâu jêng nâp rjăp ôh, tơ lah gâp mâu hŏ nal ôh nau vay ăn ma trôk jêh ri neh,$b$,true),
('bunong-vn','JER',33,26,null,$b$ăt tâm ban lĕ, gâp mra cha lơi ndŭl mpôl Y-Yakôp jêh ri ndŭl mpôl Y-Đavit, oh moh gâp, kŏ tât gâp mâu hôm săch tâm trôm ndŭl mpôl păng ăn chiă uănh phung kon sau Y-Abraham, Y-Isăk, jêh ri Y-Yakôp. Yor lah gâp mra njŭn phung bu nă plơ̆ sĭt, ăn tay nau ueh uĭn ma khân păng, jêh ri mra yô̆ ma khân păng.”$b$,false),
('bunong-vn','JER',34,1,null,$b$Aơ jêng nau ngơi tă Yêhôva ma Y-Yêrêmi, tơ lah Y-Nêbukatnetsar, hađăch Babilôn ndrel ma lĕ rngôch phung ta han păng, jêh ri lĕ rngôch bri dak ta neh ntu gŭ tâm dâng nau păng chiă uănh, jêh ri lĕ rngôch ƀon lan, dôl tâm lơh đah ƀon Yêrusalem jêh ri ƀon toyh ƀa ƀă:$b$,true),
('bunong-vn','JER',34,2,null,$b$“Pô aơ Yêhôva Brah Ndu Israel lah: Hăn ngơi hom ma Y-Sêdêkia, hađăch Yuđa, jêh ri lah: Ma păng, ‘Pô aơ Yêhôva lah: Aơ, gâp jao ƀon aơ ma ti hađăch Babilôn jêh ri păng mra su ô băl ma ŭnh.$b$,false),
('bunong-vn','JER',34,3,null,$b$May mâu mra klaih tă bơh păng ôh, ƀiă lah n'hêl nanê̆ bu mra nhŭp jao may tâm ti păng; may mra saơ muh măt hađăch Babilôn jêh ri may ngơi ndrel ma păng; jêh ri may mra hăn ma bri Babilôn.$b$,false),
('bunong-vn','JER',34,4,null,$b$Nđâp lah kơt nĕ, hơi Y-Sêdêkia, hađăch Yuđa, iăt hom nau Yêhôva! Pô aơ nau Yêhôva ngơi lah ma may: May mâu mra khĭt đah đao ôh.$b$,false),
('bunong-vn','JER',34,5,null,$b$May mra khĭt tâm nau đăp mpăn; bu mra su ndơ ƀâu ăn ma may, tâm ban nây lĕ bu hŏ su ndơ ƀâu kah ma phung che may, phung hađăch lor ma may, jêh ri bu nhĭm vơl klâng may, lah: “Vơ, Hơi kôranh ơi! Nây jêng gâp nơm ngơi nau aơ, pô nây Yêhôva lah.”$b$,false),
('bunong-vn','JER',34,6,null,$b$Pô nây, kôranh nơm mbơh lor Y-Yêrêmi ngơi lĕ nau nây ma Y-Sêdêkia hađăch Yuđa, tâm ƀon Yêrusalem,$b$,true),
('bunong-vn','JER',34,7,null,$b$dôl phung ta han hađăch Babilôn tâm lơh đah ƀon Yêrusalem jêh ri ma lĕ rngôch ƀon n'gor Yuđa hôm e, ƀon Lakis, jêh ri ƀon Asêka; yor lah knŏng bar ƀon geh mpêr nâp dơm hôm e tâm n'gor Yuđa.$b$,false),
('bunong-vn','JER',34,8,null,$b$Nau Yêhôva ngơi lah ma Y-Yêrêmi jêh hađăch Sêdêkia ƀư jêh du nau tâm rnglăp đah lĕ rngôch phung ƀon lan ƀon Yêrusalem gay mbơh nau jêng kon me ma khân păng,$b$,true),
('bunong-vn','JER',34,9,null,$b$ăn ăp nơm dơi jêng kon me phung dĭk mâu lah nă, jêng phung bu klâu mâu lah bu ur Hêbrơ ăn dơi gŭ păn thơ, pô ri mơ mâu geh du huê mra ăn du huê Yuđa oh nâu păng ƀư dĭk đŏng ôh.$b$,false),
('bunong-vn','JER',34,10,null,$b$Lĕ rngôch phung kôranh jêh ri lĕ rngôch phung ƀon lan dơi tông tĭng nau tâm rnglăp nây, ăp nơm tông bâr dơi ƀư kon me ăn ma dĭk bu klâu mâu lah bu ur dơi gŭ păn thơ, gay ma khân păng mâu hôm jêng dĭk đŏng ôh. Khân păng tông jêh ri ăn kon me khân ô băl.$b$,false),
('bunong-vn','JER',34,11,null,$b$Ƀiă lah jêh ta nây khân păng mplĕch tay nau mĭn, plơ̆ nhŭp tay bu klâu jêh ri bu ur dĭk khân păng lĕ ăn kon me jêh, jêh ri plơ̆ pah kan păng ƀư dĭk bu.$b$,false),
('bunong-vn','JER',34,12,null,$b$Rnôk nây, geh nau Yêhôva ngơi lah ma Y-Yêrêmi pô aơ:$b$,true),
('bunong-vn','JER',34,13,null,$b$Yêhôva, Brah Ndu Israel lah: “Gâp hŏ ƀư jêh nau tâm rnglăp đah phung che khân may tâm nar gâp leo khân păng du luh tă n'gor bri Êjipt, klaih tă jêng dĭk, lah$b$,false),
('bunong-vn','JER',34,14,null,$b$Tơ lah tăch prao năm, ăn ăp nơm khân may ăn kon me bunuyh Hêbrơ, bu tăch jêh ma khân may jêh ri pah kan ma khân may prao năm; gay khân may ăn kon me ma ô băl dơi gŭ păn thơ. Ƀiă lah phung che khân may mâu ŭch iăt ôh gâp, mâu lĕ rkêng tôr khân păng ma gâp.$b$,false),
('bunong-vn','JER',34,15,null,$b$Bi khân may, hŏ nhăl rmal jêh ri ƀư jêh nau tih ta năp măt gâp, ăp nơm mbơh ma nơm chiau meng păng dơi gŭ păn thơ; jêh ri hŏ ƀư nau tâm rnglăp ta năp măt gâp, nâm bu ntĭt tâm ngih bu ntơ ma Amoh gâp.$b$,true),
('bunong-vn','JER',34,16,null,$b$Ƀiă lah khân may hŏ plĕch nau mĭn, hŏ ƀư nau ƀơ̆ ƀơch amoh gâp; khân may plơ̆ nhŭp tay dĭk bu klâu jêh ri dĭk bu ur khân may lĕ ăn kon me jêh tĭng nâm khân ô băl ŭch, jêh ri khân may nhŭp tay njêng khân ô băl dĭk bu.$b$,true),
('bunong-vn','JER',34,17,null,$b$Yor nây, nau Yêhôva ngơi lah, pô aơ: Khân may mâu tĭng ôh bâr gâp, yor lah khân may mâu mbơh ôh nau kon me, ma oh nâu păng jêh ri nơm chiau meng păng; aơ, gâp mbơh ma khân may du nau kon me, nâm ntĭt mƀơk khân may luh ăn ma tak đao, nau ji tưp sa sât ji ngot, mra ƀư ma khân may, Yêhôva lah. Gâp mra njêng khân may du nau nkrit ma lĕ rngôch bri dak ta neh ntu.$b$,true),
('bunong-vn','JER',34,18,null,$b$Gâp mra jao phung bu klâu ƀư rlau nau gâp tâm rnglăp, jêh ri mâu djôt prăp ôh lĕ nau tâm rnglăp hŏ ƀư jêh ta năp gâp, tơ lah khân păng sreh ndrôk kon ƀư bar gâl, jêh ri hăn rgăn ta vah vang n'gul gâl ndrôk kon nây;$b$,false),
('bunong-vn','JER',34,19,null,$b$nanê̆ ngăn, gâp mra jao lĕ rngôch phung kôranh Yuđa jêh ri phung kôranh Yêrusalem, kôranh bu char, kôranh ƀư brah, jêh ri lĕ rngôch phung ƀon nây hŏ hăn rgăn jêh ta vah vang n'gul gâl ndrôk kon;$b$,false),
('bunong-vn','JER',34,20,null,$b$gâp mra jao khân păng tâm ti phung rlăng, khân păng, jêh ri ma ti phung ŭch ngroh lơi (ƀư roh) nau rêh khân păng. Drô phan khân păng mra jêng ndơ ăn ma sĭm klơ trôk sa jêh ri ma mpô mpa bri.$b$,false),
('bunong-vn','JER',34,21,null,$b$Ăt tâm ban lĕ, gâp mra jao Y-Sêdêkia, hađăch Yuđa, jêh ri phung kôranh păng ma ti phung rlăng khân păng jêh ri ma ti phung joi ƀư ngroh lơi nau rêh khân păng, ma ti phung ta han hađăch Babilôn jêng phung mhe du bơh khân may.$b$,false),
('bunong-vn','JER',34,22,null,$b$Aơ, gâp mra mbơh Yêhôva lah, jêh ri ăn khân păng văch ma ƀon aơ: Jêh ri khân păng mra lơh ƀon aơ, mra sŏk pit jêh ri n'ho sŏk ŭnh su ro. Gâp mra ƀư lĕ rngôch ƀon n'gor Yuđa, mra jêng rngol, mâu geh bunuyh gŭ ôh.”$b$,false),
('bunong-vn','JER',35,1,null,$b$Yêhôva ngơi ma Y-Yêrêmi tâm rnôk Y-Jêhôjakim kon bu klâu Y-Jôsia chiă uănh n'gor Yuđa:$b$,true),
('bunong-vn','JER',35,2,null,$b$“Hăn hom ma ngih phung Rêkap, ngơi ma khân păng jêh ri njŭn leo khân păng ma ngih Yêhôva rlet ma du mlâm jrô; jêh ri ăn khân păng nhêt dak play kriăk ƀâu.”$b$,false),
('bunong-vn','JER',35,3,null,$b$Pô ri gâp leo Y-Jasania, kon bu klâu Y-Yêrêmi, sau Y-Habasinia, jêh ri phung oh nâu păng, jêh ri lĕ rngôch phung kon bu klâu păng, jêh ri nŭm lĕ rngôch phung Rêkap.$b$,false),
('bunong-vn','JER',35,4,null,$b$Gâp leo khân păng ma ngih Yêhôva lăp tâm jrô phung kon bu klâu Y-Hanan kon bu klâu Y-Igdalia, bunuyh Brah Ndu, gŭ êp jrô phung kôranh jêh ri ta klơ jrô Y-Maseya, kon bu klâu Y-Salum, nơm chiă njrăng ntŭk lăp mpông.$b$,false),
('bunong-vn','JER',35,5,null,$b$Gâp n'gân ta năp phung Rêkap du mlâm yăng bêng dak play kriăk ƀâu, jêh ri ăn nđâp ma kachok đŏng, jêh ri gâp lah ma khân păng, “Nhêt hom dak play kriăk ƀâu gâp aơ.”$b$,true),
('bunong-vn','JER',35,6,null,$b$Ƀiă lah khân păng plơ̆ lah: “Hên mâu mra nhêt ôh dak play kriăk ƀâu, yor lah Y-Jônadap kon bu klâu Rêkap chô che hên ntĭnh jêh ma hên, ‘Lơi ta khân may nhêt ôh dak play kriăk ƀâu, khân may nơm kŏ tât ma kon ma sau khân may ƀa ƀơ n'ho ro.$b$,false),
('bunong-vn','JER',35,7,null,$b$Lơi ta ndâk ôh du mlâm ngih, mâu lah srih ntil, mâu lah tăm play kriăk ƀâu, ƀiă lah ăn khân may gŭ tâm ngih bok lĕ nar khân may gŭ rêh, gay ma khân may gŭ rêh jŏ nar tâm bri khân may gŭ njơh ƀât lât,’$b$,false),
('bunong-vn','JER',35,8,null,$b$Hên tông jêng bâr Y-Jônadap, kon bu klâu Rêkap, chô che hên, tâm lĕ ntil nau păng hŏ ntĭnh jêh ma hên, mâu ăn hên nhêt ôh dak play kriăk ƀâu tâm lĕ nar hên gŭ rêh, n'ho tât ma ur, ma kon bu ur, bu klâu hên, kŏ mâu dơi lĕ nhêt dak play kriăk ƀâu (ndrănh)$b$,false),
('bunong-vn','JER',35,9,null,$b$Hên mâu dơi ndâk ngih gŭ, mâu geh tơm play kriăk ƀâu, mâu lah mir, mâu lah ntil găr,$b$,false),
('bunong-vn','JER',35,10,null,$b$ƀiă lah ăn hên gŭ tâm ngih bok jêh ri hŏ tông bâr chô yau Y-Jônadap pô nây, jêh ri ƀư tĭng nâm nau păng hŏ ntăm jêh ma hên.$b$,false),
('bunong-vn','JER',35,11,null,$b$Ƀiă lah tơ lah Y-Nêbukatnetsar văch lơh bri dak, hên tâm lah êng! Kay lŏng he hăn hao Yêrusalem yor lah klach ma phung ta han Kaldê jêh ri phung ta han Syri! Pô ri hên gŭ tâm ƀon Yêrusalem.”$b$,false),
('bunong-vn','JER',35,12,null,$b$Rnôk nây, geh nau Yêhôva ngơi lah ma Y-Yêrêmi, pô aơ:$b$,true),
('bunong-vn','JER',35,13,null,$b$“Yêhôva ma phung ta han, Brah Ndu Israel, lah pô aơ: Hăn hom, lah ma phung Yuđa, jêh ri phung gŭ ta ƀon Yêrusalem,’ khân may mâu mra sŏk dơn hĕ nau nti jêh ri mâu iăt ôh hĕ nau gâp ngơi? Yêhôva lah.$b$,false),
('bunong-vn','JER',35,14,null,$b$Nau Y-Jônadap kon bu klâu Y-Rêkap ntĭnh ma phung kon bu klâu păng, lơi nhêt ôh play kriăk ƀâu (ndrănh) khân păng iăt nau ro, khân păng mâu nhêt n'ho tât nar aơ, yor lah khân păng hŏ tông jêh nau chô che khân păng ntăm. Bi gâp, lĕ rngôch ngơi ƀa ƀơ ma khân may, ƀiă lah khân may mâu iăt gâp ôh.$b$,true),
('bunong-vn','JER',35,15,null,$b$Gâp prơh hăn jêh ma khân may lĕ rngôch phung oh mon gâp, jêng phung kôranh nơm mbơh lor, hăn tât ma khân may, lah: “Aƀaơ ri ăn ăp nơm khân may plơ̆ sĭt tă bơh trong mhĭk păng, jêh ri tâm rgâl nau khân may ƀư, jêh ri lơi ta tĭng ndô̆ ôh phung brah êng gay pah kan ma khân păng, pô ri mơ khân may dơi gŭ tâm bri gâp hŏ ăn jêh ma khân may jêh ri ma phung che khân may.” Ƀiă lah khân may mâu mâp rkêng tôr iăt gâp ôh.$b$,false),
('bunong-vn','JER',35,16,null,$b$Phung kon bu klâu Y-Jônadap, kon bu klâu Y-Rêkap, djôt prăp jêh nau phung che khân păng hŏ ntăm jêh ma khân păng, ƀiă lah phung ƀon lan aơ mâu mâp tông ma gâp ôh.”$b$,false),
('bunong-vn','JER',35,17,null,$b$“Yor nây Yêhôva Brah Ndu ma phung ta han, Brah Ndu Israel lah: Aơ, gâp ăn tât ma phung Yuđa jêh ri lĕ rngôch phung gŭ tâm ƀon Yêrusalem lĕ rngôch nau mhĭk djơh gâp hŏ mbơh jêh ma khân păng; yor lah gâp hŏ ngơi jêh khân păng mâu iăt, gâp kuăl khân păng mâu plơ̆ lah.’ ”$b$,true),
('bunong-vn','JER',35,18,null,$b$Jêh ta nây, Y-Yêrêmi ngơi lah ma ngih phung Rêkap, pô aơ: Yêhôva ma phung ta han Brah Ndu Israel, lah: Yor lah khân may hŏ tông jêh nau Y-Jônadap chô yau khân may ntăm, jêh ri djôt prăp lĕ rngôch nau vay păng, jêh ri ƀư jêh lĕ rngôch nau păng ntăm ma khân may,$b$,true),
('bunong-vn','JER',35,19,null,$b$yor nây, Yêhôva ma phung ta han, Brah Ndu Israel, lah pô aơ: Y-Jônadap kon bu klâu Y-Rêkap mâu mra pưt ôh du huê bunuyh, bu klâu dâk pa năp gâp n'ho ro.’ ”$b$,false),
('bunong-vn','JER',36,1,null,$b$Năm rơh puăn Y-Jêhôjakim, kon bu klâu Y-Jôsia, hađăch Yuđa, Yêhôva ngơi ma Y-Yêrêmi pô aơ:$b$,true),
('bunong-vn','JER',36,2,null,$b$“Sŏk hom du ndrom sămƀŭt ntâu, jêh ri chih ta nây lĕ rngôch nau gâp hŏ ngơi jêh ma may tâm rdâng đah phung Israel, phung Yuđa, jêh ri ma lĕ rngôch mpôl bunuyh, ntơm bơh nar gâp ngơi jêh ma may, bơh rnôk Y-Jôsia, tât nar aơ.$b$,false),
('bunong-vn','JER',36,3,null,$b$Tơ lah phung Yuđa mra gĭt lĕ rngôch nau mhĭk gâp mĭn jêh ŭch ƀư ma khân păng, pô ri ăp nơm dơi plơ̆ sĭt tă bơh trong mhĭk păng, gay ma gâp yô̆ an nau kue jêh ri nau tih khân păng.”$b$,true),
('bunong-vn','JER',36,4,null,$b$Y-Yêrêmi kuăl Y-Baruk, kon bu klâu Y-Nêria, jêh ri Y-Baruk chih ta ndrom sămƀŭt ntâu tĭng nâm nau Y-Yêrêmi mbơh lĕ rngôch nau Yêhôva ngơi jêh ma păng.$b$,true),
('bunong-vn','JER',36,5,null,$b$Y-Yêrêmi ntĭnh ma Y-Baruk, lah, “Bu kân, buay mâu ăn gâp hăn ma ngih Yêhôva ôh;$b$,true),
('bunong-vn','JER',36,6,null,$b$pô nây ăn may hăn ta nar ver ât sông sa jêh ri uănh nau Yêhôva ngơi may hŏ chih jêh ta ndrom sămƀŭt ntâu tĭng nâm gâp lah an jêh, ăn lĕ rngôch phung ƀon lan tăng tâm ngih Yêhôva. Tâm ban lĕ ăn may uănh sămƀŭt nây ăn lĕ rngôch phung Yuđa văch ta ƀon khân păng nơm iăt đŏng.$b$,false),
('bunong-vn','JER',36,7,null,$b$Klăp lah khân păng mra vơh vơl ta năp Yêhôva, jêh ri ăp nơm mra plơ̆ sĭt tă bơh trong mhĭk păng, yor lah nau Yêhôva nuih jêh ri hao nuih păng mbơh jêh tâm rdâng đah ƀon lan aơ jêng toyh ngăn.”$b$,false),
('bunong-vn','JER',36,8,null,$b$Y-Baruk, kon bu klâu Y-Nêria, ƀư lĕ rngôch nau kôranh nơm lor Y-Yêrêmi hŏ nti jêh ma păng, păng nti nau Yêhôva ngơi bơh ndrom sămƀŭt ntâu tâm ngih Yêhôva.$b$,true),
('bunong-vn','JER',36,9,null,$b$Tâm năm rơh prăm Y-Jêhôjakim, kon bu klâu Y-Jôsia, hađăch Yuđa, ta khay sĭn, lĕ rngôch phung ƀon lan tâm ƀon Yêrusalem, jêh ri lĕ rngôch phung ƀon lan văch tă lĕ rngôch ƀon tâm n'gor Yuđa hăn ma ƀon Yêrusalem tâm năng ver ât sông sa ta năp Yêhôva.$b$,true),
('bunong-vn','JER',36,10,null,$b$Pô ri lĕ rngôch phung ƀon lan iăt, uănh nau Y-Yêrêmi ngơi chih tâm ndrom sămƀŭt ntâu tâm ngih Yêhôva, tâm jrô Y-Gêmaria kon bu klâu Y-Saphan, kôranh chih sămƀŭt, gŭ ta nhuang ta klơ ta ntŭk lăp Mpông Pêr Mhe tâm ngih Yêhôva.$b$,false),
('bunong-vn','JER',36,11,null,$b$Tơ lah Y-Mika kon bu klâu Y-Gêmaria sau Y-Saphan, hŏ tăng jêh bu rŏ lĕ rngôch nau Yêhôva ngơi tâm ndrom sămƀŭt ntâu nây,$b$,true),
('bunong-vn','JER',36,12,null,$b$păng trŭnh rlet ngih hađăch, lăp tâm kôranh chih sămƀŭt; jêh ri lĕ rngôch phung kôranh gŭ ta nây: Geh Y-Êlisama jêng kôranh chih sămƀŭt Y-Dêlaya kon bu klâu Y-Sêmaya, Y-Êlnathan kon bu klâu Y-Akbôr, Y-Gêmaria kon bu klâu Y-Saphan, Y-Sêdêkia kon bu klâu Y-Hanania, jêh ri lĕ rngôch phung kôranh.$b$,false),
('bunong-vn','JER',36,13,null,$b$Y-Mika mbơh ma khân păng lĕ rngôch nau ngơi ô băl tăng jêh, tơ lah Y-Baruk uănh ndrom sămƀŭt ntâu ăn phung ƀon lan iăt.$b$,false),
('bunong-vn','JER',36,14,null,$b$Yor ri phung kôranh prơh hăn Y-jêhudi kon bu klâu Y-Nêthania sau Y-Sêlêmia, se Y-Kusi gay lah ma Y-Baruk, djôt hom tâm ti may ndrom sămƀŭt ntâu may uănh jêh ăn phung ƀon lan iăt, jêh ri văch hom.” Pô ri Y-Baruk kon Y-Nêria djôt ndrom sămƀŭt ntâu nây jêh ri hăn ma khân păng.$b$,true),
('bunong-vn','JER',36,15,null,$b$Khân păng lah ma ô băl, “Gŭ hom jêh ri uănh ăn hên iăt.” Y-Baruk uănh sămƀŭt nây ma khân păng.$b$,false),
('bunong-vn','JER',36,16,null,$b$Ƀiă lah, tơ lah khân păng tăng lĕ rngôch nau ngơi, khân păng klach tâm rle uănh ndrăng nơm, jêh ri khân păng lah ma Y-Baruk, “Hên mra mbơh lĕ nau ngơi aơ ma hađăch.”$b$,false),
('bunong-vn','JER',36,17,null,$b$Khân păng ôp ma Y-Baruk, “Mbơh ma hên, mâm may dơi chih lĕ rngôch nau ngơi aơ? Di lĕ tĭng nâm Y-Yêrêmi sâm lah an?”$b$,false),
('bunong-vn','JER',36,18,null,$b$Y-Baruk plơ̆ sĭt lah ma khân păng, “Păng kâp lah an lĕ rngôch nau ngơi aơ ma gâp dôl gâp chih ma dak ôch ta ndrom sămƀŭt ntâu.”$b$,false),
('bunong-vn','JER',36,19,null,$b$Pô ri phung kôranh lah ma Y-Baruk, “Hăn du krap hom, may jêh ri Y-Yêrêmi, lơi ăn du huê bunuyh gĭt ôh ta khân may gŭ.”$b$,false),
('bunong-vn','JER',36,20,null,$b$Jêh nây lĕ rngôch phung kôranh prăp ndrom sămƀŭt ntâu tâm jrô kôranh chih sămƀŭt Y-Êlisama, khân păng lăp tâm nhuang ngih hađăch, jêh ri nkoch ƀoi lĕ rngôch nau ngơi ăn hađăch iăt.$b$,false),
('bunong-vn','JER',36,21,null,$b$Jêh ri hađăch prơh Y-Jêhudi hăn sŏk ndrom sămƀŭt ntâu nây, tă tâm jrô kôranh chih sămƀŭt Y-Êlisama, jêh ri djôt leo rŏ uănh ăn hađăch jêh ri lĕ rngôch phung kôranh gŭ êp hađăch tăng da dê.$b$,false),
('bunong-vn','JER',36,22,null,$b$Nar nây jêng khay sĭn; jêh ri hađăch gŭ tâm ngih păng dôl Yan sĭt puh, jêh ri geh ŭnh tâm năk hit pa năp păng.$b$,true),
('bunong-vn','JER',36,23,null,$b$Dôl Y-Jêhudi uănh geh pe puăn kô̆ tâm ndrom sămƀŭt, hađăch sŏk pêih jê̆ tor lơi kô̆ nây ma pêih, jêh ri pŭr tâm ŭnh, kŏ tât ŭnh sa lĕ ndrom sămƀŭt tâm ŭnh năk.$b$,false),
('bunong-vn','JER',36,24,null,$b$Hađăch nđâp ma mpôl oh mon păng tăng lĕ rngôch nau ngơi, mâu geh nau klach ôh, mâu lĕ khân păng nkhêk bok ao khân păng.$b$,true),
('bunong-vn','JER',36,25,null,$b$Nđâp lah Y-Êlnathan, Y-Dêlaya, jêh ri Y-Gêmaria dăn nkân hađăch lơi su ôh sămƀŭt nây, păng mâu ŭch iăt ôh nau khân păng.$b$,false),
('bunong-vn','JER',36,26,null,$b$Hađăch ntĭnh ma Y-Jêrah mêel kon bu klâu hađăch jêh ri Y-Sêraya kon bu klâu Y-Asriêl, jêh ri Y-Sêlêmia kon bu klâu Y-Apdel hăn nhŭp chăp kôranh chih sămƀŭt Y-Baruk jêh ri kôranh nơm mbơh lor, ƀiă lah Yêhôva pôn bar hê nây.$b$,false),
('bunong-vn','JER',36,27,null,$b$Jêh hađăch su lơi ndrom sămƀŭt ntâu nây geh nau ngơi Y-Baruk hŏ chih tĭng nâm Y-Yêrêmi kâp sâm lah an, nau Yêhôva ngơi ma Y-Yêrêmi:$b$,true),
('bunong-vn','JER',36,28,null,$b$“Sŏk đŏng ndrom sămƀŭt ntâu êng jêh ri chih ta nây lĕ rngôch nau ngơi hŏ chih jêh tâm ndrom sămƀŭt saơ nây, sămƀŭt nâu Y-Jêhôjakim, hađăch Yuđa, su jêh.$b$,false),
('bunong-vn','JER',36,29,null,$b$Bi ma Y-Jêhôjakim, hađăch Yuđa, ăn may lah ma păng, ‘Pô aơ nau Yêhôva lah, may lĕ su lơi jêh ndrom sămƀŭt ntâu nây, jêh ri lah: “Mâm ƀư may chih jêh tâm nây nau hađăch Babilôn mra văch tât nanê̆ ngăn jêh ri ƀư rai bri aơ, jêh ri mra ƀư rai phung bunuyh nđâp mpô mpa tâm bri aơ?”$b$,false),
('bunong-vn','JER',36,30,null,$b$Yor nây, aơ jêng nau ngơi Yêhôva lah ma Y-Jêhôjakim, hađăch Yuđa: Mâu mra geh du huê nơm gŭ ta sưng hađăch Đavit, jêh ri phan păng bu mra klŭp lơi tâm nklang duh nar, jêh ri ma nau ji kăt rngêt bri măng.$b$,true),
('bunong-vn','JER',36,31,null,$b$Jêh ri gâp mra tâm rmal păng, jêh ri phung kon sau păng, nđâp phung oh mon păng, yor nau kue khân păng; gâp mra ăn tât ma khân păng jêh ri ma phung gŭ tâm ƀon Yêrusalem, jêh ri phung Yuđa, lĕ rngôch nau mhĭk gâp mbơh jêh nau tâm rdâng đah khân păng, yor lah khân păng mâu ŭch iăt ôh.”$b$,true),
('bunong-vn','JER',36,32,null,$b$Pô ri, Y-Yêrêmi sŏk đŏng ndrom sămƀŭt ntâu êng ăn ma kôranh chih sămƀŭt Y-Baruk, kon bu klâu Y-Nêria. Păng chih tĭng bâr Y-Yêrêmi sâm lah an lĕ rngôch nau ngơi tâm ndrom sămƀŭt ntâu Y-Jêhôjakim hađăch Yuđa su jêh tâm ŭnh, jêh ri kơi ntop âk nau ngơi tâm ban nglăp ta nây.$b$,true),
('bunong-vn','JER',37,1,null,$b$Y-Sêdêkia, kon bu klâu Y-Jôsia, nơm Y-Nêbukatnetsar hađăch Babilôn, njêng păng hađăch, chiă uănh n'gor Yuđa ntrok Y-Jêhoyakin, kon bu klâu Y-Jêhôjakim.$b$,true),
('bunong-vn','JER',37,2,null,$b$Ƀiă lah păng, phung oh mon păng, jêh ri phung ƀon lan păng tâm bri dak mâu iăt ôh ma nau Yêhôva ngơi jêh ma kôranh nơm mbơh lor Y-Yêrêmi.$b$,false),
('bunong-vn','JER',37,3,null,$b$Hađăch Sêdêkia prơh hăn Y-Jêhukal, kon bu klâu Y-Sêlêmia, jêh ri kôranh ƀư brah Y-Sôphôni, kon bu klâu kôranh ƀư brah Y-Maseya, hăn tât ma kôranh nơm mbơh lor Y-Yêrêmi, lah: “Mbơh sơm ma Yêhôva Brah Ndu he dăn kơl he ƀă.”$b$,false),
('bunong-vn','JER',37,4,null,$b$Rnôk nây Y-Yêrêmi, hôm dôl hăn nsong tâm nklang phung ƀon lan, yor lah ê hŏ nhŭp krŭng păng ôh.$b$,false),
('bunong-vn','JER',37,5,null,$b$Phung ta han Pharaôn hŏ luh jêh tă bri Êjipt; jêh ri phung Kaldê dôl nchueng lơh ƀon Yêrusalem tăng nau nây pô ri khân păng mâu hôm nchueng ƀon Yêrusalem.$b$,false),
('bunong-vn','JER',37,6,null,$b$Nôk nây, Yêhôva ngơi ma kôranh nơm mbơh lor Y-Yêrêmi:$b$,true),
('bunong-vn','JER',37,7,null,$b$“Pô aơ, Yêhôva Brah Ndu Israel lah: Ăn khân may lah ma hađăch Yuđa nơm prơh may hăn ôp ma gâp, pô aơ: Aơ, phung ta han Pharaôn hŏ văch gay kơl may, dăch plơ̆ sĭt rlet bri Êjipt, ma bri khân păng nơm.$b$,false),
('bunong-vn','JER',37,8,null,$b$Phung Kaldê mra plơ̆ văch đŏng tâm lơh đah ƀon aơ; khân păng mra pit in ƀon aơ jêh ri su ô băl ma ŭnh.$b$,false),
('bunong-vn','JER',37,9,null,$b$Yêhôva ngơi lah pô nây: Lơi ta ndơm khân may nơm ôh, lah, “N'hêl nanê̆ phung Kaldê mra du ngai bơh he,” yor lah khân păng mâu mra du trơn ngai ôh.$b$,true),
('bunong-vn','JER',37,10,null,$b$Nđâp lah phung Kaldê văch tât tâm lơh đah khân may, tâm phung khân păng hôm e knŏng phung sôt rmanh, ƀiă lah ăp nơm ăt du dâk tă tâm ngih bok păng jêh ri su ƀon aơ ma ŭnh.’ ”$b$,false),
('bunong-vn','JER',37,11,null,$b$Tơ lah phung ta han Kaldê du jêh bơh ƀon Yêrusalem, yor klach đah phung ta han Pharaôn lĕ văch dăch,$b$,true),
('bunong-vn','JER',37,12,null,$b$Y-Yêrêmi ntơm luh bơh ƀon Yêrusalem hăn rlet ma bri Benjamin, gay sŏk drăp păng ndơn ta nây ta nklang phung ƀon lan nây.$b$,false),
('bunong-vn','JER',37,13,null,$b$Ƀiă lah dôl păng tât ta mpông pêr Benjamin, du huê ta han rong gak, amoh păng Y-Irijah, kon bu klâu Y-Sêlêmia, sau Y-Hanania, nhŭp chăp kôranh nơm mbơh lor Y-Yêrêmi, jêh ri lah: “May cha lơi phung Israel hăn gŭ mpeh phung Kaldê.”$b$,false),
('bunong-vn','JER',37,14,null,$b$Y-Yêrêmi plơ̆ lah: “Ngơi nklă! Gâp mâu hăn gŭ mpeh phung Kaldê ôh.” Ƀiă lah Y-Irijah mâu ŭch iăt nau păng ôh, jêh ri nhŭp chăp Y-Yêrêmi, têk leo tât ta năp phung kôranh.$b$,false),
('bunong-vn','JER',37,15,null,$b$Phung kôranh nuih ngăn ma Y-Yêrêmi, khân păng dong ô băl jêh ri krŭng ô băl tâm ngih kôranh chih sămƀŭt Y-Jônathan, yor lah khân păng njêng jêh ngih păng jêng ndrung bu nă.$b$,false),
('bunong-vn','JER',37,16,null,$b$Y-Yêrêmi bu krŭng, tâm ndrung ngo, jêh ri păng gŭ ta nây jŏ nar.$b$,true),
('bunong-vn','JER',37,17,null,$b$Pô nây, Hađăch Sêdêkia prơh bunuyh hăn jă ô băl, jêh ri păng rom ô băl. Hađăch ôp ma ô băl ma nau ndâp tâm ngih păng, lah: Geh lĕ nau Yêhôva ngơi?” Y-Yêrêmi lah, “Geh lĕ”. Pô ri ô băl lah: “Bu mra jao may ma ti hađăch Babilôn.”$b$,true),
('bunong-vn','JER',37,18,null,$b$Tâm ban lĕ Y-Yêrêmi lah ma Hađăch Sêdêkia, “Moh nau mhĭk gâp ƀư ma may, ma phung oh mon may, mâu lah ma phung ƀon lan aơ, tât may nhŭp krŭng gâp?$b$,false),
('bunong-vn','JER',37,19,null,$b$Ta ntŭk phung kôranh mbơh lor may, mbơh jêh ma may, lah: ‘Hađăch Babilôn mâu mra tât văch lơh đah may jêh ri ma bri aơ ôh?’$b$,false),
('bunong-vn','JER',37,20,null,$b$Aƀaơ ri, iăt hom nau gâp vơl dăn ma may, Ơ kôranh gâp hađăch, dăn ma may sŏk dơn, jêh ri lơi ta njŭn sĭt gâp ma ngih kôranh chih sămƀŭt Y-Jônathan, klach lah gâp mra khĭt ta nây.”$b$,false),
('bunong-vn','JER',37,21,null,$b$Pô ri Hađăch Sêdêkia ntĭnh ăn bu leo njŭn Y-Yêrêmi tâm nhuang phung ta han gak, jêh ri bu ăn ma păng ăp nar du glo piăng let tă bơh phung ƀư piăng let, kŏ tât ƀon nây lĕ piăng let jêh. Pô ri Y-Yêrêmi ăt hôm gŭ tâm nhuang ta han gak pô nây.$b$,true),
('bunong-vn','JER',38,1,null,$b$Y-Sêphatia, kon bu klâu Y-Matan, Y-Gêdalia kon bu klâu Y-Pashur, Y-Jukal kon bu klâu Y-Sêlêma, jêh ri Y-Pashur kon bu klâu Y-Malkia tăng nau Y-Yêrêmi ngơi ma lĕ rngôch phung ƀon lan.$b$,true),
('bunong-vn','JER',38,2,null,$b$“Pô aơ Yêhôva lah: Mbu nơm gŭ tâm ƀon aơ mra khĭt ma tak đao, ma nau sa sât ji ngot, jêh ri ma nau ji tưp, ƀiă lah mbu nơm luh hăn ma phung Kaldê mra rêh; păng mra rklaih nau rêh păng!$b$,true),
('bunong-vn','JER',38,3,null,$b$Pô aơ Yêhôva lah: N'hêl nanê̆ bu mra jao ƀon aơ ma ti phung ta han hađăch Babilôn nhŭp ô băl.”$b$,false),
('bunong-vn','JER',38,4,null,$b$Pô ri phung kôranh lah ma hađăch, “Ăn bu nkhĭt lơi bunuyh aơ, yor lah păng ƀư rdja nuih n'hâm phung ta han hôm tâm ƀon aơ, jêh ri lĕ rngôch phung ƀon lan, yor lah păng ngơi nâm bu pô nây ma khân ô băl. Yor lah bunuyh aơ mâu joi ôh nau ueh ma phung ƀon lan, ƀiă lah joi nau mhĭk ma khân ô băl.”$b$,true),
('bunong-vn','JER',38,5,null,$b$Hađăch Sedêkia plơ̆ sĭt lah, Aơ, păng gŭ tâm ti khân may, yor lah hađăch mâu dơi tâm rdâng đah khân may ôh.”$b$,false),
('bunong-vn','JER',38,6,null,$b$Pô ri khân păng nhŭp Y-Yêrêmi jêh ri nklăch tâm ntu dak Y-Malkija kon bu klâu hađăch, ndrâm ntu nây tâm nhuang phung ta han gak. Khân păng ntrŭnh Y-Yêrêmi ma rse brăt. Mâu geh dak ôh tâm ntu nây, geh bŏk dơm, jêh ri Y-Yêrêmi rhuh tâm bŏk nây.$b$,false),
('bunong-vn','JER',38,7,null,$b$Tơ lah Y-Êbet-Mêlek du huê Êthiôpi oh mon bu char gŭ tâm ngih hađăch tăng nau khân păng nklăch Y-Yêrêmi tâm ntu dak, dôl hađăch gŭ ta Mpông Pêr Benjamin,$b$,true),
('bunong-vn','JER',38,8,null,$b$Y-Êbetmêlek luh tă bơh ngih hađăch ngơi đah hađăch,$b$,false),
('bunong-vn','JER',38,9,null,$b$“Ơ kôranh gâp hađăch, phung bu klâu aơ ƀư nau mhĭk tâm lĕ rngôch nau, khân păng ƀư jêh ma kôranh nơm mbơh lor Y-Yêrêmi; nklăch ô băl tâm ntu dak, jêh ri ô băl mra khĭt ji ngot ta nây; yor lah mâu geh ndơ sông sa ôh tâm ƀon nây.”$b$,false),
('bunong-vn','JER',38,10,null,$b$Pô ri hađăch ntĭnh ma Y-Êbet-Mêlek du huê Êthiôpi, “Sŏk hom pe jât nuyh bu klâu ndrel ma may bơh ntŭk aơ, jêh ri đŏt ngluh kôranh nơm mbơh lor Y-Yêrêmi luh bơh ntu dak ê lor ma ô băl khĭt.”$b$,false),
('bunong-vn','JER',38,11,null,$b$Pô nây, Y-Êbet-Mêlek, leo phung bu klâu ndrel ma păng, jêh ri hăn tât ma ngih hađăch ta ntŭk jay prăp kho aơ; jêh ri sŏk tă tâm nây bok ao sat, jêh ri ntrŭnh ma rse brăt ma Y-Yêrêmi tâm ntu dak.$b$,false),
('bunong-vn','JER',38,12,null,$b$Y-Êbet-Mêlek, du huê Êthiôpi lah ma Y-Yêrêmi, “Dơm bok ao sat nây ta pă-nhuak săp rse brăt.” Y-Yêrêmi ƀư pô nây.$b$,false),
('bunong-vn','JER',38,13,null,$b$Khân păng đŏt huai Y-Yêrêmi ma rse brăt n'hao ngluh tă dak. Jêh ri Y-Yêrêmi hôm e tâm nhuang phung ta han gak.$b$,false),
('bunong-vn','JER',38,14,null,$b$Hađăch Sêdêkia prơh bu hăn kuăl kôranh nơm mbơh lor Y-Yêrêmi jêh ri păng vơt rom ô băl ta ntŭk lăp tal pe tâm ngih brah Yêhôva. Hađăch lah ma Y-Yêrêmi, “Gâp mra ôp ma may du nau aơ; lơi mo ma gâp ôh.”$b$,true),
('bunong-vn','JER',38,15,null,$b$Y-Yêrêmi lah ma Y-Sêdêkia, Tơ lah gâp mbơh ntil nau nây, mâu hĕ may nkhĭt gâp? Jêh ri tơ lah gâp mbơh êng ma may, kŏ may mâu mra iăt lĕ nau gâp.”$b$,false),
('bunong-vn','JER',38,16,null,$b$Pô ri hađăch ton săk ma nau ndâp ma Y-Yêrêmi, “Tĭng nâm Yêhôva gŭ rêh. Nơm hŏ rhăk njêng jêh huêng aơ ăn ma he, gâp mâu mra nkhĭt may ôh mâu lah jao may ma ti phung joi ngroh lơi nau rêh may ôh.”$b$,true),
('bunong-vn','JER',38,17,null,$b$Pô ri Y-Yêrêmi lah ma Y-Sêdêkia “Pô aơ Yêhôva Brah Ndu ma phung ta han. Brah Ndu Israel lah, “Tơ lah may mra lăp phung kôranh ma hađăch Babilôn, pô nây bu mra prăp may rêh, jêh ri bu mâu mra su ôh ƀon aơ; may jêh ri phung tâm ngih may mra gŭ rêh.$b$,true),
('bunong-vn','JER',38,18,null,$b$Ƀiă lah tơ lah may mâu lăp ôh phung kôranh ma hađăch Babilôn, bu mra jao ƀon aơ ma ti phung Kaldê, jêh ri khân păng mra su ƀon aơ ma ŭnh jêh ri may mâu mra klaih ôh tă bơh ti khân păng.’ ”$b$,false),
('bunong-vn','JER',38,19,null,$b$Hađăch Sêdêkia lah ma Y-Yêrêmi, “Gâp klach ma phung Yuđa gŭ jêh tĭng mpeh phung Kaldê, klach lah bu jao gâp ma khân păng, jêh ri khân păng lĕ thăm ơm jêh ma gâp.”$b$,true),
('bunong-vn','JER',38,20,null,$b$Y-Yêrêmi lah: “Bu mâu mra jao may ma khân păng ôh. Ăn may tông hom ma Yêhôva aƀaơ ri ro tĭng nâm nau gâp hŏ lah, jêh ri nau ueh mra tât ma may, jêh ri bu mra om may gŭ rêh.$b$,false),
('bunong-vn','JER',38,21,null,$b$Ƀiă lah tơ lah may dun mâu ran lăp ôh phung Kaldê, aơ jêng nau Yêhôva hŏ tâm saơ jêh đah gâp.$b$,false),
('bunong-vn','JER',38,22,null,$b$Aơ, lĕ phung bu ur hôm tâm ngih hađăch Yuđa bu mra veng leo ma phung kôranh hađăch Babilôn; ƀiă lah phung bu ur nây lah ma hađăch: “Phung mĭt jiăng may nsing lĕ ndơm jêh may, khân păng lĕ dơi jêh; pô ri, aƀaơ jâng may lĕ rluh jêh tâm bŏk, phung mĭt jiăng may lĕ dơi jêh may.$b$,false),
('bunong-vn','JER',38,23,null,$b$“Lĕ rngôch phung ur jêh ri phung kon hađăch bu mra veng leo ma phung Kaldê, jêh ri may nơm mâu mra klaih ôh bơh ti khân păng, ƀiă lah hađăch Babilôn mra chăp may, jêh ri bu mra su ƀon aơ ma ŭnh.”$b$,true),
('bunong-vn','JER',38,24,null,$b$Nôk aơ Y-Sêdêkia lah ma Y-Yêrêmi, “Lơi ta ăn bu gĭt nau ngơi aơ, jêh ri may mâu mra khĭt ôh.$b$,true),
('bunong-vn','JER',38,25,null,$b$Tơ lah phung kôranh tăng nau gâp ngơi ndrel jêh đah may jêh ri lah bu văch ôp ma may, lah: ‘Mbơh ma hên moh nau lah jêh ma hađăch, jêh ri moh nau hađăch hŏ lah jêh đah may, lơi ta pôn mo du ntil ndơ ăn ma hên ôh, jêh ri hên mâu mra ƀư nkhĭt may ôh.’$b$,false),
('bunong-vn','JER',38,26,null,$b$Pô nây mơ ăn may lah ma khân păng, ‘Gâp vơh vơl jêh ma hađăch ma nau deh rhêt gay ma păng mâu mra prơh gâp hăn rlet ma ngih Y-Jônathan ăn gâp khĭt ta nây.’ ”$b$,false),
('bunong-vn','JER',38,27,null,$b$Lĕ rngôch phung kôranh văch tât joi Y-Yêrêmi, jêh ri ôp păng. Păng plơ̆ sĭt lah ma phung kôranh tĭng nâm hađăch ntăm jêh ma păng. Pô ri, khân păng mâu hôm ôp ôh ma păng, yor lah bu mâu iăt ôh ma nau ngơi nây.$b$,false),
('bunong-vn','JER',38,28,null,$b$Y-Yêrêmi gŭ tâm nhuang ntŭk ta han gak, kŏ tât nar bu lơh sŏk ƀon Yêrusalem. Tơ lah bu sŏk ƀon nây, bi păng ăt hôm ta nây.$b$,false),
('bunong-vn','JER',39,1,null,$b$Năm rơh sĭn rô̆ Y-Sêdêkia, hađăch Yuđa, khay jât, Y-Nêbukatnetsar, hađăch Babilôn, tât ndrel ma phung ta han păng, nchueng ƀon Yêrusalem.$b$,true),
('bunong-vn','JER',39,2,null,$b$Năm rơh jât ma nguay rô̆ Y-Sêdêkia, ta khay puăn, nar lơ sĭn, ƀon toyh bu lơh rai.$b$,false),
('bunong-vn','JER',39,3,null,$b$Lĕ rngôch phung kôranh bri Babilôn lăp tâm ƀon toyh gŭ ta mpông pêr tâm nklang. Nây jêng Y-Nergal-Sarêser, Y-Samgar- Nêbô, Y-Sarsêkim, ƀư bôk kôranh bu char, Y-Nergal-Sarêser, ƀư bôk kôranh dak si ndrel ma lĕ rngôch phung kôranh ƀa ƀă phung hađăch Babilôn.$b$,false),
('bunong-vn','JER',39,4,null,$b$Y-Sêdêkia, hađăch Yuđa, nđâp lĕ rngôch phung ta han păng n'gơr uănh saơ phung nây, luh du ro tă ƀon toyh dôl bri măng, tĭng trong đang trao hađăch, găn mpông pêr vah vang bar kơn mpêr; jêh ri khân păng hăn rlet Arabah.$b$,false),
('bunong-vn','JER',39,5,null,$b$Ƀiă lah phung ta han Kaldê tĭng gôk, jêh ri tĭng ban Y-Sêdêkia tâm bri lâng ƀon Yêrêko; pô ri nhŭp jêh ri njŭn ma Y-Nêbukatnetsar, hađăch Babilôn, ta ƀon Riblah tâm bri Hamôt. Ta nây Y-Nêbukatnetsar phat dôih Y-Sêdêkia.$b$,true),
('bunong-vn','JER',39,6,null,$b$Hađăch Babilôn nkhĭt kon bu klâu Y-Sêdêkia ta ƀon Riblah ta năp măt Y-Sêdêkia; jêh ri hađăch Babilôn nkhĭt lĕ rngôch phung kôranh Yuđa.$b$,true),
('bunong-vn','JER',39,7,null,$b$Păng rloch găr măt Y-Sêdêkia, jêh ri kât ma rse rvăk gay têk leo ma bri Babilôn.$b$,false),
('bunong-vn','JER',39,8,null,$b$Phung Kaldê su ngih hađăch jêh ri ngih vâl phung ƀon lan, ƀư rai lơi mpêr ƀon toyh Yêrusalem.$b$,false),
('bunong-vn','JER',39,9,null,$b$Y-Nebusaradan, kôranh ta han phung ta han gak, nhŭp lĕ rngôch phung ƀon lan hôm klen tâm ƀon, jêh ri phung hŏ lăp păng, jêh ri phung ƀon lan hôm klen tâm ƀon nây, djôt leo njêng bu nă tâm bri Babilôn.$b$,true),
('bunong-vn','JER',39,10,null,$b$Y-Nebusaradan kôranh ta han, phung ta han gak cha lơi tâm bri Yuđa; ƀa ƀă phung ƀon lan o ach ngăn mâu hôm geh mir ba ôh, jêh ri ăn ma khân ô băl đang play kriăk ƀâu nđâp ma mir ro.$b$,true),
('bunong-vn','JER',39,11,null,$b$Y-Nêbukatnetsar hađăch Babilôn, ntrŭnh nau ăn ma Y-Nebusarada kôranh ta han, phung ta han gak, ma nau Y-Yêrêmi, lah pô aơ:$b$,true),
('bunong-vn','JER',39,12,null,$b$“Njŭn păng, chiă uănh păng ăn ueh, lơi ta ƀư mhĭk ma păng ôh, ƀiă lah ƀư tĭng nau păng nơm ueh,”$b$,false),
('bunong-vn','JER',39,13,null,$b$Pô nây Y-Nebusaradan kôranh ta han, phung ta han gak, Y-Neburaban, ƀư bôk phung kôranh bu char, Y-Nergal-Sarêser, ƀư bôk kôranh dak si, jêh ri lĕ rngôch phung kôranh ta han hađăch Babilôn.$b$,false),
('bunong-vn','JER',39,14,null,$b$Prơh hăn joi Y-Yêrêmi tâm nhuang phung ta han gak. Khân păng jao ô băl ma Y-Gadalia kon bu klâu Y-Ahikam sau Y-Saphan ăn păng njŭn ô băl ma ngih ô băl nơm. Pô ri Y-Yêrêmi gŭ ndrel phung ƀon lan păng.$b$,false),
('bunong-vn','JER',39,15,null,$b$Yêhôva ngơi ma Y-Yêrêmi dôl bu krŭng păng tâm nhuang phung ta han gak:$b$,true),
('bunong-vn','JER',39,16,null,$b$“Hăn lah hom ma Y-Êbet-Mêlek, du huê Êthiôpi, ‘Pô aơ Yêhôva ma phung ta han, Brah Ndu Israel lah, Aơ, tât nar nây gâp mra ƀư tra năp măt may lĕ nau gâp hŏ ngơi tâm rdâng jêh đah ƀon aơ jêng nau mhĭk jêh ri mâu dơi geh nau ueh uĭn ôh.$b$,false),
('bunong-vn','JER',39,17,null,$b$Yêhôva lah: Ƀiă lah tâm nar nây, gâp mra rklaih may, pô ri may mâu mra jao tâm ti phung bunuyh may klach ôh.$b$,false),
('bunong-vn','JER',39,18,null,$b$Yor lah nanê̆ ngăn gâp mra rklaih may, jêh ri may mâu mra khĭt ma tak đao ôh; ƀiă lah may ăt hôm rêh yor lah may rnơm jêh ma gâp, Yêhôva lah.’ ”$b$,false),
('bunong-vn','JER',40,1,null,$b$Yêhôva lĕ ngơi ma Y-Yêrêmi jêh, geh Y-Nebusaradan kôranh ta han phung gak, mƀơh Y-Yêrêmi hăn ta Rama, geh nau ngơi lah ma păng. Tơ lah Y-Nebusaradan prơh joi, bi Y-Yêrêmi dôl bu nkông ta nklang phung bu nă êng ƀon Yêrusalem jêh ri Yuđa jêng phung bunuyh bu nhŭp djôt leo rlet ma Babilôn.$b$,true),
('bunong-vn','JER',40,2,null,$b$Kôranh ta han phung gak djôt leo Y-Yêrêmi jêh ri lah: “Yêhôva Brah Ndu khân ay may mbơh jêh nau mhĭk tâm rdâng đah ntŭk aơ;$b$,true),
('bunong-vn','JER',40,3,null,$b$Yêhôva ăn tât nau nây, jêh ri ƀư jêh tĭng nau păng lah. Yor lah khân ay may tih jêh đah mham Yêhôva jêh ri mâu tông bâr păng ôh, pô ri nau aơ tât jêh ma khân ay may.$b$,false),
('bunong-vn','JER',40,4,null,$b$Ƀiă lah may saơ jêh nar aơ gâp rklaih may dơi klaih tă bơh nkông ta ti may. Tơ lah may mĭn ueh hăn ndrel gâp ma bri Babilôn, hăn hom, gâp mra mât mray ăn ueh. Tơ lah may mĭn mâu ueh ôh hăn ndrel gâp ma bri Babilôn, lơi ta hăn ôh; aơ, lam bri gŭ pa năp măt may, hăn hom ta ntŭk may mĭn ueh jêh ri di.”$b$,false),
('bunong-vn','JER',40,5,null,$b$Yor lah Y-Yêrêmi ê hŏ plơ̆ sĭt ôh, yor ri Y-Nebusara dăn lah đŏng: “Tơ lah may ăt hôm gŭ ta aơ, sĭt hom ma Y-Gêdalia kon bu klâu Y-Ahikam sau Y-Saphan, nơm hađăch Babilôn njêng kôranh chiă uănh ma lĕ rngôch ƀon tâm n'gor bri Yuđa, jêh ri gŭ ndrel ma păng ta nklang phung ƀon lan; mâu lah hăn hom ta ntŭk may mĭn jêng di.” Pô nây kôranh ta han phung gak ăn ma păng du kô̆ ndơ sông sa jêh ri ndơ nhhơr, jêh ri ăn păng hăn.$b$,false);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','JER',40,6,null,$b$Y-Yêrêmi hăn rlet ma Y-Gêdalia kon bu klâu Y-Ahikam ta ƀon Mispa jêh ri gŭ ndrel ma păng ta nklang phung ƀon lan bu om hôm klen tâm n'gor.$b$,false),
('bunong-vn','JER',40,7,null,$b$Tơ lah lĕ rngôch phung kôranh ta han jêh ri phung ta han khân păng hôm gŭ tâm bri dak nơm tăng nau hađăch Babilôn hŏ njêng Gêdalia, kon bu klâu Y-Ahikam jêng kôranh toyh chiă uănh bri dak, jêh ri tăng hađăch hŏ jao jêh phung bu klâu, bu ur, jêh ri kon se nđâp ma phung ndĭt trơi tâm bri dak, bu mâu veng leo ôh rlet ma bri Babilôn ƀư bu nă.$b$,true),
('bunong-vn','JER',40,8,null,$b$Khân păng hăn ma Y-Gêdalia ta ƀon Mispa geh: Y-Ismaêl kon bu klâu Y-Nêthania; Y-Jôharian jêh ri Y-Jônathan phung kon bu klâu Y-Karêa, Y-Sêraya kon bu klâu Y-Tanhumet, phung kon bu klâu Y-Êphai bunuyh mpôl băl Nêtôphat, Y-Jêsanian kon bu klâu bunuyh ndŭl mpôl Makat, nđâp ma phung hăn ndrel ma khân păng.$b$,false),
('bunong-vn','JER',40,9,null,$b$Y-Gêdalia, kon bu klâu Y-Ahikam, sau Y-Saphan, ngơi ton đah khân păng jêh ri phung băl khân păng, jêh ri lah: “Lơi klach ôh pah kan ma phung Kaldê; gŭ hom tâm bri dak jêh ri pah kan ma hađăch Babilôn, jêh ri may mra geh nau ueh uĭn.$b$,true),
('bunong-vn','JER',40,10,null,$b$Bi gâp be, gâp mra gŭ ta ƀon Mispa, tâm tang khân may ta năp phung Kaldê mra văch ma he; bi khân may, bun hom dak play kriăk ƀâu, play si Yan Vai, jêh ri dak play Ôlivơ, jêh ri prăp khân păng tâm Yăng, jêh ri gŭ tâm ƀon khân may hŏ pit in jêh.$b$,false),
('bunong-vn','JER',40,11,null,$b$Lĕ rngôch phung Yuđa gŭ tâm bri Môap, jêh ri ndrel ma phung Amôn jêh ri tâm bri Êđôm jêh ri tâm bri êng tăng jêh hađăch Babilôn om phung hôm klen tâm n'gor bri Yuđa, jêh ri njêng jêh Y-Gêdalia kon bu klâu Y-Ahikam sau Y-Saphan, jêng kôranh toyh chiă uănh khân păng,$b$,true),
('bunong-vn','JER',40,12,null,$b$pô ri lĕ rngôch phung Yuđa lâp plơ̆ sĭt ma n'gor bri Yuđa tă bơh lĕ rngôch ntŭk bu mprơh jêh khân păng, plơ̆ sĭt ma Y-Gêdalia ta ƀon Mispa, jêh ri khân păng bun prăp dak play kriăk ƀâu jêh ri play si Yan vai ăn âk.$b$,false),
('bunong-vn','JER',40,13,null,$b$Y-Jôhnan kon bu klâu Y-Karêa jêh ri lĕ rngôch phung kôranh phung ta han khân păng hôm e gŭ chăm ntŭk ngât ndrâm, văch ma Y-Gêdalia, ta ƀon Mispa,$b$,true),
('bunong-vn','JER',40,14,null,$b$jêh ri lah ma păng pô aơ: “May gĭt lĕ Y-Balis hađăch Amôn prơh Y-Ismaêl kon bu klâu Y-Nêthania hăn ŭch nkhĭt may?” Ƀiă lah Y-Gêdalia kon bu klâu Y-Ahikam mâu iăt ôh nau khân păng mbơh.$b$,false),
('bunong-vn','JER',40,15,null,$b$Y-Jôhanan kon bu klâu Y-Karêa ngơi ma nau ndâp đah Y-Gêdalia ta ƀon Mispa, “Ăn gâp hăn nkhĭt lơi Y-Ismaêl kon bu klâu Y-Nêthania, jêh ri mâu geh nuyh mra dơi gĭt nau nây. Moh nau khlay păng nkhĭt lơi may, kŏ tât lĕ rngôch phung Yuđa gŭ ndrel ma may mra chah rai pru pra, êng êng, jêh ri phung Yuđa hôm klen mra rai lôch?”$b$,false),
('bunong-vn','JER',40,16,null,$b$Ƀiă lah Y-Gêdalia, kon bu klâu Y-Ahikam, lah ma Y-Jôhanan kon bu klâu Y-Karêa, “Lơi may ƀư ôh nau nây, yor lah nau may ngơi di ma Y-Ismaêl mâu ngăn ôh.”$b$,false),
('bunong-vn','JER',41,1,null,$b$Tâm khay pơh, Y-Ismaêl kon bu klâu Y-Nêthania, sau Y-Êlisama ndŭl mpôl hađăch, du kôranh ma phung ta han hađăch, văch ndrel ma jât nuyh bu klâu tât ma Y-Gêdalia, kon bu klâu Y-Ahikam, ta ƀon Mispa. Dôl khân păng gŭ sông sa ndrel ta ƀon Mispa,$b$,true),
('bunong-vn','JER',41,2,null,$b$Y-Ismaêl kon bu klâu Y-Nêthania jêh ri jât nuyh bu klâu ndrel ma păng dâk nkhĭt Y-Gêdalia kon bu klâu Y-Ahikam, sau Y-Saphan ma đao, nơm hađăch Babilôn hŏ njêng kôranh toyh chiă uănh bri dak.$b$,false),
('bunong-vn','JER',41,3,null,$b$Tâm ban lĕ Y-Ismaêl nkhĭt lĕ rngôch phung Yuđa gŭ ndrel ma Y-Gêdalia ta ƀon Mispa, nđâp ma phung Kaldê gŭ ta nây.$b$,false),
('bunong-vn','JER',41,4,null,$b$Jêh nar bu nkhĭt Y-Gêdalia, ê hŏ geh bunuyh gĭt nau nây;$b$,true),
('bunong-vn','JER',41,5,null,$b$geh pham jât nuyh bu klâu tă bơh ƀon Sichem, ƀon Silô, jêh ri ƀon Samari, khân păng poih lĕ têp kang, khân păng nsoh bok ao sat, jêh ri săk jăn khân păng rek tor đah pêih, djôt leo ndơ nhhơr rnih muy jêh ri ndơ ƀâu kah prăp nhhơr ta ngih Yêhôva.$b$,false),
('bunong-vn','JER',41,6,null,$b$Y-Ismaêl, kon bu klâu Y-Nethania, tă bơh ƀon Mispa ŭch tâm mâp đah khân păng dôl hăn nhĭm jăng jai. Tơ lah păng lĕ tâm mâp jêh đah khân păng, păng lah ma khân păng, “Văch hom tâm mâp, đah Y-Gêdalia kon bu klâu Y-Ahikam.”$b$,false),
('bunong-vn','JER',41,7,null,$b$Dôl khân păng hăn tât tâm nklang ƀon, Y-Ismaêl kon bu klâu Y-Nêthania jêh ri phung hăn ndrel ma păng, nkhĭt mpôl khân ô băl jêh ri mƀăr tâm ntu dak.$b$,true),
('bunong-vn','JER',41,8,null,$b$Ƀiă lah geh jât nuyh tâm phung nây lah ma Y-Ismaêl, Lơi ta nkhĭt hên ôh, yor lah hên geh jay ba ƀlê (ba răch), ba orgơ, dak play ôlivơ, jêh ri dak sŭt lĕ pôn jêh tâm mir khân păng ndrel ma phung băl khân păng. Pô nây Y-Ismaêl mâu nkhĭt ôh khân ô băl ndrel ma băl khân păng.$b$,false),
('bunong-vn','JER',41,9,null,$b$Ntu dak, ntŭk Y-Ismaêl mƀăr drô phan phung bu klâu păng nkhĭt jêh, êp kêng Y-Gêdalia jêng ntu dak toyh hađăch Asa kuyh jêh, yor lah klach ma Y-Baêsa, hađăch Israel. Tâm ntu nây đŏng Y-Ismaêl, kon bu klâu Y-Nêthania, hŏ mbêng tay đŏng bêng bunuyh khĭt jêh.$b$,true),
('bunong-vn','JER',41,10,null,$b$Jêh ri Y-Ismaêl nhŭp lĕ rngôch phung bunuyh ƀon lan hôm klen tâm ƀon Mispa djôt leo ƀư bu nă: Jêng phung kon bu ur hađăch, jêh ri lĕ rngôch ƀon lan bu om gŭ ta ƀon Mispa, phung Y-Nebusaradan, kôranh phung ta han gak, jao jêh ma Y-Gêdalia, kon bu klâu Y-Ahikam. Y-Ismaêl nhŭp khân ô băl jêng bu nă, jêh ri hăn găn ntŭk kon sau bri Amôn.$b$,false),
('bunong-vn','JER',41,11,null,$b$Ƀiă lah tơ lah Y-Jôhanan, kon bu klâu Y-Karêa jêh ri lĕ rngôch phung kôranh ta han ndrel ma păng tăng jêh lĕ rngôch nau mhĭk Y-Ismaêl, kon bu klâu Y-Nêthania hŏ ƀư jêh,$b$,true),
('bunong-vn','JER',41,12,null,$b$khân păng nhŭp lĕ rngôch phung bu klâu khân păng jêh ri hăn tâm lơh đah Y-Ismaêl kon bu klâu Y-Nêthania. Khân păng ban păng ta dak nglao toyh ta ƀon Gabaôn.$b$,false),
('bunong-vn','JER',41,13,null,$b$Geh nau tâm lơh, tơ lah mpôl ta han tĭng Y-Ismaêl n'gơr saơ Y-Jôhanan, kon bu klâu Y-Karêa, jêh ri lĕ rngôch phung kôranh ndrel ma păng, pô ri khân păng hâk răm ngăn.$b$,false),
('bunong-vn','JER',41,14,null,$b$Lĕ rngôch phung ƀon lan Y-Ismaêl leo jêng bu nă tă bơh ƀon Misap plơ̆ sĭt ma Y-Jôhanan, kon bu klâu Y-Karêa.$b$,false),
('bunong-vn','JER',41,15,null,$b$Bi Y-Ismaêl, kon bu klâu Y-Nêthania, ndrel ma pham nuyh du klaih bơh Y-Jôhanan jêh ri hăn tât ntŭk kon sau bri Amôn.$b$,false),
('bunong-vn','JER',41,16,null,$b$Y-Jôhanan, kon bu klâu Y-Karêa, jêh ri lĕ rngôch phung kôranh ta han ndrel ma păng sŏk lĕ rngôch phung ƀon lan hôm tă bơh phung Y-Ismaêl kon bu klâu Y-Nêthania veng leo jêng bu nă tă bơh ƀon Mispa jêh nau nkhĭt Y-Gêdalia, kon bu klâu Y-Ahikam. Lĕ rngôch phung ta han tâm lơh, bu ur, kon se, kôranh bu char, phung Y-Jôhanan djôt sĭt tă bơh ƀon Gabaôn.$b$,true),
('bunong-vn','JER',41,17,null,$b$Khân păng dâk hăn jêh ri veh njưh ta Kimham êp ƀon Ƀêtlêhem, mĭn ŭch hăn n'gor bri Êjipt,$b$,true),
('bunong-vn','JER',41,18,null,$b$yor klach ma phung Kaldê; yor lah Y-Ismaêl kon bu klâu Y-Nêthania hŏ nkhĭt jêh Y-Gêdalia kon bu klâu Y-Ahikam, nơm hađăch Babilôn njêng jêh kôranh toyh chiă uănh bri dak.$b$,false),
('bunong-vn','JER',42,1,null,$b$Lĕ rngôch phung kôranh ta han jêh ri Y-Jôhanan, kon bu klâu Y-Karêa, jêh ri Y-Asaria kon bu klâu Y-Hôsaya, jêh ri lĕ rngôch phung ƀon lan, ntơm bơh kon se tât bunuyh toyh,$b$,true),
('bunong-vn','JER',42,2,null,$b$văch tât da dê ma kôranh nơm mbơh lor Y-Yêrêmi, lah pô aơ: Iăt hom nau hên dăn ma may jêh ri mbơh sơm ma Yêhôva Brah Ndu may kơl hên, yor lah lĕ rngôch phung hên hôm gŭ ta aơ knŏng djê̆ dơm tĭng nâm may saơ hên,$b$,false),
('bunong-vn','JER',42,3,null,$b$gay ma Yêhôva Brah Ndu may dơi tâm mpơl ma hên trong hên mra hăn jêh ri hên mra ƀư.”$b$,false),
('bunong-vn','JER',42,4,null,$b$Kôranh nơm mbơh lor Y-Yêrêmi lah ma khân păng, “Gâp tăng jêh nau khân may; aơ, gâp mra mbơh sơm ma Yêhôva Brah Ndu khân may tĭng nâm nau khân may dăn, jêh ri mâm nau Yêhôva plơ̆ lah, gâp mra mbơh ma khân may. Gâp mâu mra pôn du nau ma khân may ôh.”$b$,false),
('bunong-vn','JER',42,5,null,$b$Khân păng lah đŏng ma Y-Yêrêmi, “Ăn Yêhôva jêng nơm mbơh n'hêl nanê̆ ngăn tơ lah hên tâm rdâng đah Yêhôva Brah Ndu may prơh may ngơi ma hên!$b$,false),
('bunong-vn','JER',42,6,null,$b$Gĭt lah jêng ueh mâu lah jêng mhĭk, hên mra tông bâr Yêhôva Brah Ndu hên, ma nơm nây hên prơh may hăn gay ma nau ueh uĭn mra tât ma hên tơ lah hên tông bâr Brah Ndu hên.”$b$,false),
('bunong-vn','JER',42,7,null,$b$Jêh lôch jât nar, Yêhôva ngơi ma Y-Yêrêmi.$b$,true),
('bunong-vn','JER',42,8,null,$b$Pô ri Y-Yêrêmi kuăl Y-Yôhanan, kon bu klâu Y-Karêa, jêh ri lĕ rngôch phung kôranh ta han gŭ ndrel păng, jêh ri lĕ rngôch phung ƀon lan ntơm bơh kon se jê̆ tât ma bunuyh toyh,$b$,false),
('bunong-vn','JER',42,9,null,$b$jêh ri khân păng lah: Pô aơ nau Yêhôva, Brah Ndu Israel lah, jêng Nơm khân may hŏ prơh gâp hăn gay mpơl nau khân may vơl dăn ma păng.$b$,false),
('bunong-vn','JER',42,10,null,$b$Tơ lah khân may mra gŭ tâm n'gor bri aơ, pô ri gâp ndâk khân may jêh ri mâu geh ôh bunuyh n'glưh khân may; gâp mra tăm khân may jêh ri mâu rôk ôh; yor lah gâp rngot nau mhĭk gâp ƀư jêh ma khân may.$b$,true),
('bunong-vn','JER',42,11,null,$b$Lơi ta klach ôh ma hađăch Babilôn, ma nơm nây khân ay may klach, lơi klach ôh ma păng, Yêhôva lah, yor lah gâp gŭ ndrel ma khân ay may ŭch tâm rklaih ay may tă bơh ti păng.$b$,false),
('bunong-vn','JER',42,12,null,$b$Gâp mra ăn nau yô̆ ma ay may, gay ma păng mra yô̆ ma khân ay may jêh ri ăn ay may gŭ tâm bri khân ay may nơm!$b$,false),
('bunong-vn','JER',42,13,null,$b$Ƀiă lah tơ lah ma nau mâu tông bâr ôh ma Yêhôva Brah Ndu ay may, jêh ri lah: ‘Hên mâu mra gŭ tâm bri aơ ôh.’$b$,false),
('bunong-vn','JER',42,14,null,$b$Jêh ri lah: ‘Mâu, hên mra hăn ma n'gor bri Êjipt, ta nây hên mâu mra saơ nau tâm lơh mâu lah tăng bâr nŭng, mâu lah sa sât ji ngot ôh, jêh ri hên mra gŭ ta nây yơh,’$b$,false),
('bunong-vn','JER',42,15,null,$b$pô nây iăt hom nau Yêhôva lah, Ơ phung Yuđa hôm e ta aơ. Pô ri Yêhôva ma phung ta han Brah Ndu Israel lah: ‘Tơ lah khân ay may săch ŭch hăn rlet ma n'gor bri Êjipt jêh ri gŭ ta nây,$b$,false),
('bunong-vn','JER',42,16,null,$b$rnôk nây tak đao khân may klach mra tĭng ban khân ay may ta nây tâm n'gor bri Êjipt; jêh ri nau sa sât ji ngot khân ay may klach mra tĭng prăl tât ma n'gor bri Êjipt, jêh ri ta nây khân ay may mra khĭt.$b$,false),
('bunong-vn','JER',42,17,null,$b$Lĕ rngôch phung bunuyh săch hăn rlet ma bri Êjipt gay gŭ ta nây mra khĭt đah mpiăt đao, jêh ri nau sa sât ji ngot, jêh ri nau ji tưp; khân păng mâu mra geh ôh nơm hôm e rêh klaih bơh nau mhĭk gâp mra ăn tât ma khân păng ta nây!’$b$,false),
('bunong-vn','JER',42,18,null,$b$Yor lah pô aơ nau Yêhôva ma phung ta han, Brah Ndu Israel lah: ‘Nâm bu gâp nkhĭt jêh nau gâp nuih jêh ri nau ji nuih ma phung gŭ tâm ƀon Yêrusalem, pô nây lĕ gâp mra nkhŭt nau gâp nuih ma khân ay may tơ lah ay may sŏl hăn rôih hăn rlet ma bri Êjipt. Khân ay may mra jêng nâm bu ŭnh buh, ndơ nkrit bu, ndơ bu rak rtăp jêh ri ndơ bu ntêh rmot. Khân ay may mâu mra hôm saơ ntŭk aơ ôh!’$b$,false),
('bunong-vn','JER',42,19,null,$b$Yêhôva lah jêh ma khân may, “Ơ phung Yuđa hôm gŭ ta aơ, Lơi ta hăn ôh ma n'gor bri Êjipt. Ăn khân ay may gĭt ngăn nar aơ gâp mbơh ăn khân ay may njrăng,$b$,false),
('bunong-vn','JER',42,20,null,$b$yor lah khân ay may ndơm khân ay may nơm; khân ay may hŏ prơh jêh gâp hăn ma Yêhôva Brah Ndu ay may, lah: ‘Mbơh sơm hom ma Yêhôva Brah Ndu he kơl he moh nau Yêhôva Brah Ndu he lah, jêh ri he mra tông ma nau nây!$b$,false),
('bunong-vn','JER',42,21,null,$b$Nar aơ gâp mbơh jêh nau nây ma khân ay may, ƀiă lah khân ay may mâu tông ôh bâr Yêhôva Brah Ndu ay may tâm du ntil nau păng prơh jêh gâp hăn mbơh ma khân ay may.$b$,false),
('bunong-vn','JER',42,22,null,$b$Yor nây aƀaơ ri ăn khân ay may gĭt nanê̆ ngăn ma ay may mra khĭt đah tak đao, ma nau sa sât ji ngot, jêh ri ma nau ji tưp tâm ntŭk khân ay may ŭch hăn gŭ nây.”$b$,false),
('bunong-vn','JER',43,1,null,$b$Tơ lah lôch jêh nau Y-Yêrêmi mbơh ma lĕ rngôch phung ƀon lan lĕ nau Yêhôva Brah Ndu khân păng ngơi, ma nau ngơi nây Yêhôva Brah Ndu khân păng prơh hăn jêh ô băl hăn tât ma khân păng,$b$,true),
('bunong-vn','JER',43,2,null,$b$Y-Asaria kon bu klâu Y-Hôsaya jêh ri Y-Jôhanan kon bu klâu Y-Karêa jêh ri lĕ rngôch phung bu klâu mhĭk lah ma Y-Yêrêmi, “may mbơh nau mƀruh. Yêhôva Brah Ndu he mâu prơh ôh may hăn mbơh nau aơ, ‘Lơi hăn ôh ma bri Êjipt ŭch gŭ ta nây;’$b$,false),
('bunong-vn','JER',43,3,null,$b$ƀiă lah Y-Baruk kon bu klâu Y-Nêria ăn may tâm rdâng đah hên, ŭch jao hên tâm ti bri Kaldê, ăn khân păng nkhĭt hên mâu lah njŭn leo hên jêng bu nă tâm bri Babilôn.”$b$,false),
('bunong-vn','JER',43,4,null,$b$Pô ri Y-Jôhanan kon bu klâu Y-Karêa jêh ri lĕ rngôch phung kôranh ta han jêh ri lĕ rngôch phung ƀon lan mâu tông ôh bâr Yêhôva ăn ŭch gŭ tâm bri Yuđa.$b$,false),
('bunong-vn','JER',43,5,null,$b$Ƀiă lah Y-Jôhanan kon bu klâu Y-Karêa jêh ri lĕ rngôch phung kôranh ta han leo lĕ rngôch phung Yuđa hôm e klen, jêng phung plơ̆ sĭt tay jêh tă bơh lĕ rngôch mpôl băl bu mprơh jêh khân păng; ŭch gŭ tâm bri Yuđa.$b$,true),
('bunong-vn','JER',43,6,null,$b$Phung bu klâu, phung bu ur, phung kon se, phung kon bu ur hađăch, jêh ri ăp nơm Y-Nebusaradan, kôranh ta han gak, hŏ lơi jêh ndrel Y-Gêdalia, kon bu klâu Y-Ahikam, sau Y-Saphan, nđâp ma kôranh nơm mbơh lor Y-Yêrêmi, jêh ri Y-Baruk kon bu klâu Y-Nêria.$b$,false),
('bunong-vn','JER',43,7,null,$b$Khân păng tât bri Êjipt, tât ta Tahpanhes; yor lah khân păng mâu tông tĭng nau Yêhôva.$b$,false),
('bunong-vn','JER',43,8,null,$b$Yêhôva ngơi ma Y-Yêrêmi ta ƀon Tahpanhes:$b$,true),
('bunong-vn','JER',43,9,null,$b$“Djôt ta ti may glo lŭ toyh, jêh ri pôn lŭ nây tâm ndơ tâm krêp ntŭk lŭ ta trong lăp ngih hađăch Pharaôn tâm ƀon Tahpanhes ta năp măt phung bu klâu Yuđa saơ da dê.$b$,false),
('bunong-vn','JER',43,10,null,$b$May lah ma khân păng, pô aơ Yêhôva ma phung ta han, Brah Ndu Israel lah: Aơ, gâp mra prơh hăn Y-Nêbukatnetsar, hađăch Babilôn, oh mon gâp, jêh ri păng mra ndâk sưng hađăch păng ta klơ lŭ pôn aơ, jêh ri păng mra ling bok ao ăn gui n'hâm ta klơ lŭ aơ.$b$,false),
('bunong-vn','JER',43,11,null,$b$Păng mra văch tâm lơh đah bri Êjipt, jao ma nau ji tưp, phung bu săch jêh ma nau ji tưp, jao ma nau jêng bu nă phung bu săch ma nau jêng bu nă, jêh ri jao ma tak đao nkhĭt phung bu săch jêh ma tak đao.$b$,false),
('bunong-vn','JER',43,12,null,$b$Gâp mra sĭnh ŭnh tâm ngih phung brah n'gor bri Êjipt; jêh ri Y-Nêbukatnetsar mra su ngih nây ma ŭnh jêh ri njŭn leo phung brah khân păng jêng bu nă, jêh ri nâm bu rmăk biăp nsoh bok ao păng, pô ri păng mra nsoh păng nơm đah bri Êjipt, jêh ri păng mra du hăn tă bơh ntŭk nây ma nau đăp mpăn.$b$,false),
('bunong-vn','JER',43,13,null,$b$Păng mra ƀư chah lơi n'gâng lŭ bu kach nsêr ta Bet-Sêmes tâm bri Êjipt; jêh ri păng mra su đah ŭnh lĕ rngôch ngih brah n'gor bri Êjipt.”$b$,true),
('bunong-vn','JER',44,1,null,$b$Yêhôva ngơi ma Y-Yêrêmi nau di ma lĕ rngôch phung Yuđa gŭ tâm n'gor bri Êjipt ta ƀon Mikdôl, ƀon Tahpanhes, ta ƀon Nôp, jêh ri tâm bri Pathrôs,$b$,true),
('bunong-vn','JER',44,2,null,$b$Pô aơ Yêhôva ma phung ta han Brah Ndu Israel lah: Khân may saơ jêh nau mhĭk gâp ăn tât jêh ma ƀon Yêrusalem jêh ri ma lĕ rngôch ƀon n'gor bri Yuđa. Aơ, lĕ ƀon toyh nây nar aơ jêng rngol mâu geh bunuyh gŭ,$b$,false),
('bunong-vn','JER',44,3,null,$b$yor ma nau tih phung bunuyh ƀon lan păng hŏ ƀư tih jêh. Ƀư nsônh nuih gâp, ma nau khân păng su ndơ ƀâu kah jêh ri pah kan ma phung brah êng, khân păng, khân may, nđâp ma phung che khân may mâu mâp gĭt năl ôh.$b$,false),
('bunong-vn','JER',44,4,null,$b$Ƀiă lah gâp ăt prơh hăn jêh ma khân may ƀa ƀơ lĕ rngôch phung oh mon gâp phung kôranh nơm mbơh lor, lah, ‘Lơi ta ƀư ôh nau mhĭk gâp tâm rmot aơ!’$b$,false),
('bunong-vn','JER',44,5,null,$b$Ƀiă lah khân păng mâu iăt mâu lĕ rkêng tôr iăt, gay plơ̆ rŭch tă bơh nau ƀai khân păng, jêh ri lơi hôm su ôh ndơ ƀâu kah ăn ma brah êng.$b$,false),
('bunong-vn','JER',44,6,null,$b$Yor nây gâp nkhŭt jêh nau gâp nuih jêh ri ji nuih ma lĕ rngôch ƀon bri Yuđa jêh ri tâm trong toyh ƀon Yêrusalem; jêh ri khân păng jêng ntŭk nsoih jêh ri rngol nâm bu geh jêh nar aơ.$b$,false),
('bunong-vn','JER',44,7,null,$b$Aƀaơ ri pô aơ Yêhôva Brah Ndu ma phung ta han, Brah Ndu Israel lah: Moh nau khân may ƀư nau ƀai toyh aơ ƀư mhĭk ay may nơm, ŭch ngroh lơi phung bu klâu jêh ri phung bu ur, phung oh bê, jêh ri phung kon tă tâm nklang n'gor bri Yuđa mâu hôm geh nơm hôm e ôh?$b$,true),
('bunong-vn','JER',44,8,null,$b$Moh nau khân may nsônh nuih gay ăn gâp nuih ma kan ti khân ay may ƀư, su ndơ ƀâu kah ăn ma phung brah êng tâm n'gor bri Êjipt, ntŭk khân may văch ŭch gŭ, gay ma bu ƀư ngroh khân may, jêh ri njêng khân may ndơ rak rtăp jêh ri bu ntêh rmot ta nklang lĕ rngôch ntil mpôl bunuyh ta neh ntu?$b$,false),
('bunong-vn','JER',44,9,null,$b$Khân may chuêl hêng jêh nau ƀai phung che khân may, nau ƀai phung hađăch Yuđa, nau ƀai phung ur khân păng, nau ƀai khân ay may nơm, jêh ri nau ƀai phung ur khân may ƀư jêh tâm n'gor bri Yuđa jêh ri tâm trong toyh ƀon Yêrusalem?$b$,false),
('bunong-vn','JER',44,10,null,$b$Khân păng mâu mâp ƀư nau dêh-rhêt êng khân păng nơm ôh kŏ tât ma nar aơ, mâu lĕ khân păng klach, mâu lĕ ŭch chuat tĭng nau vay jêh ri nau ntăm jêh, nau gâp hŏ ăn jêh ma khân ay may jêh ri phung che khân ay may.$b$,false),
('bunong-vn','JER',44,11,null,$b$“Yor nây, pô aơ nau Yêhôva ma phung ta han, Brah Ndu Israel lah: Aơ, gâp mra tâm rdâng ƀư nau mhĭk ăn ma khân ay may, gay ngroh lơi lĕ rngôch phung Yuđa.$b$,true),
('bunong-vn','JER',44,12,null,$b$Gâp mra sŏk phung Yuđa hôm klen, phung săch jêh ŭch hăn ta bri Êjipt, jêh ri mra ƀư ngroh lơi khân păng; khân păng mra khĭt tâm bri Êjipt; khân păng mra khĭt đah tak đao jêh ri sa sât ji ngot, ntơm bơh kon se jê̆ tât ma bunuyh toyh khân păng mra khĭt yor tak đao yor sa sât ji ngot da dê, khân păng jêng nâm bu ŭnh buh, ndơ bu ƀư nkrit, ndơ bu rak rtăp, jêh ri ndơ bu ntêh rmot.$b$,false),
('bunong-vn','JER',44,13,null,$b$Gâp mra tâm rmal phung gŭ tâm bri Êjipt, nâm bu gâp tâm rmal jêh ƀon Yêrusalem đah tak đao, nau sa sât ji ngot, jêh ri nau ji tưp,$b$,true),
('bunong-vn','JER',44,14,null,$b$kŏ tât mâu hôm geh du huê bunuyh hôm klen đơ phung hăn ran gŭ jêh tâm bri Êjipt, gay dơi klaih mâu lah hôm rêh, mâu lah plơ̆ sĭt tay ma bri Yuđa, jêng ntŭk khân păng ŭch plơ̆ sĭt gŭ. Ƀiă lah khân păng mâu mra plơ̆ sĭt gŭ ôh, knŏng ƀa ƀă phung nchuăt du klaih nây dơm.”$b$,false),
('bunong-vn','JER',44,15,null,$b$Pô ri lĕ rngôch phung bu klâu gĭt jêh phung ur păng su ndơ ƀâu kah ăn ma phung brah êng, jêh ri lĕ rngôch phung bu ur văch êp ta nây, geh phung tâm rƀŭn âk, lĕ rngôch phung ƀon lan gŭ tâm ƀon Pathrôs tâm bri Êjipt plơ̆ sĭt lah ma Y-Yêrêmi,$b$,false),
('bunong-vn','JER',44,16,null,$b$“Bi ma nau may ngơi jêh ma hên tâm amoh Yêhôva, hên mâu mra iăt nau may ôh.$b$,false),
('bunong-vn','JER',44,17,null,$b$Ƀiă lah hên mra ƀư lĕ nau hên ton jêh, su ndơ ƀâu kal ma hađăch bu ur tâm trôk jêh ri nkhŭt ndơ nhêt ăn ma păng, nâm bu hên hŏ ƀư jêh, nđâp ma hên, jêh ri phung che hên, phung hađăch hên, jêh ri phung kôranh hên tâm ƀon toyh n'gor Yuđa jêh ri n'gŏ trong toyh ƀon Yêrusalem; yor lah nôk nây hên geh ndơ sông sa âk rmeh, jêh ri geh nau chăt hao, mâu geh nau mhĭk tât ôh.$b$,false),
('bunong-vn','JER',44,18,null,$b$Ƀiă lah ntơm bơh hên cha lơi nau su ndơ ƀâu kah ma hađăch bu ur tâm trôk jêh ri nkhŭt ndơ nhhơr nhêt ma păng, hên pah pưt ăp ntil ndơ jêh ri tak đao jêh ri nau sa sât ji ngot lĕ ƀư rai jêh hên.”$b$,false),
('bunong-vn','JER',44,19,null,$b$Phung bu ur lah, “Nôk dôl hên su ndơ ƀâu kah ma hađăch bu ur tâm trôk jêh ri nkhŭt ndơ nhhơr nhêt ma păng, sai hên mâu dơn lĕ hên ƀư ƀănh ma păng tĭng nâm rup păng jêh ri nkhŭt ndơ nhhơr nhêt ma păng?”$b$,false),
('bunong-vn','JER',44,20,null,$b$Y-Yêrêmi lah ma lĕ rngôch phung ƀon lan, ma phung bu klâu jêh ri bu ur, ma lĕ rngôch phung plơ̆ sĭt lah ma păng pô aơ!$b$,true),
('bunong-vn','JER',44,21,null,$b$“Bi ma ndơ ƀâu kah khân ay may su jêh tâm ƀon toyh n'gor bri Yuđa jêh ri tâm trong toyh ƀon Yêrusalem, khân may jêh ri phung che khân may, phung hađăch jêh ri phung kôranh khân ay may, phung ƀon lan tâm lam bri nây, hŏ tă su jêh ndơ ƀâu kah tâm ăp ƀon toyh n'gor Yuđa jêh ri lĕ trong toyh ƀon Yêrusalem, mâu hĕ Yêhôva hŏ kah gĭt jêh ri hŏ prăp jêh tâm nau mĭn Păng?”$b$,true),
('bunong-vn','JER',44,22,null,$b$Yor tă ma nau mhĭk kan khân ay may ƀư jêh ri ndơ bu tâm rmot khân ay may hŏ ƀư tih jêh, yor ri Yêhôva mâu hôm dơi srôih đŏng ôh. Yor nây bri dak khân ay may jêng rngol, ntŭk nsoih, jêh ri ntŭk bu rak rtăp, mâu geh bunuyh gŭ ôh, nâm bu n'ho tât jêh nar aơ.$b$,false),
('bunong-vn','JER',44,23,null,$b$Yor lah khân ay may su ndơ ƀâu kah, jêh ri yor lah khân ay may hŏ ƀư tih jêh ma Yêhôva, mâu tông bâr ma Yêhôva, mâu chuat ôh tâm nau vay păng jêh ri nau păng ntăm jêh ri nau păng mbơh, pô ri nau djơh mhĭk aơ tât jêh ma khân ay may, nâm bu geh nar aơ.”$b$,false),
('bunong-vn','JER',44,24,null,$b$Y-Yêrêmi lah ma lĕ rngôch phung ƀon lan jêh ri ma lĕ rngôch phung bu ur, “Iăt hom nau Yêhôva ngơi, Ơ lĕ rngôch phung Yuđa gŭ tâm n'gor bri Êjipt,$b$,true),
('bunong-vn','JER',44,25,null,$b$pô aơ Yêhôva ma phung ta han, Brah Ndu Israel lah: Khân may jêh ri ur khân may mbơh jêh ma bâr mbung khân ay may, jêh ri ăn tât jêh nau nây ma ti khân ay may ƀư lôch jêh ntil nau tă bâr ay may nơm hŏ lah: ‘N'hêl nanê̆ hên mra ƀư ngăn nau hên ton jêh, ŭch su ndơ ƀâu kah ma hađăch bu ur tâm trôk jêh ri nkhŭt ndơ nhhơr nhêt ma păng.’ Pô ri ƀư ngăn jêh ri ăn tât hom nau ay may ton!$b$,false),
('bunong-vn','JER',44,26,null,$b$Yor nây iăt hom nau Yêhôva ngơi, Ơ lĕ rngôch phung Yuđa gŭ tâm bri Êjipt: Aơ, gâp ton ma amoh toyh gâp, Yêhôva lah, gay lơi geh du huê bunuyh kuăl amoh gâp ta nklang phung Yuđa gŭ tâm bri Êjipt lah, ‘Tĭng nâm Yêhôva Brah Ndu rêh.’$b$,true),
('bunong-vn','JER',44,27,null,$b$Aơ, gâp gŭ kâp uănh ma khân păng ŭch ƀư mhĭk, mâu geh ŭch ƀư nau ueh ôh; tak đao jêh ri ât ji ngot mra ƀư rai lĕ rngôch phung bu klâu Yuđa gŭ tâm bri Êjipt, kŏ tât khân păng rai lôch lĕ.$b$,false),
('bunong-vn','JER',44,28,null,$b$Jêh ri hôm knŏng djê̆ dơm klaih tă bơh tak đao nchuăt du tă bơh bri Êjipt plơ̆ sĭt ma bri Yuđa; Jêh ri lĕ rngôch phung Yuđa hôm klen, jêng nơm hŏ tât jêh ŭch gŭ tâm n'gor bri Êjipt aơ, mra gĭt mbu nau ngơi jêng di ngăn, nau ngơi gâp mâu lah nau ngơi khân păng.$b$,false),
('bunong-vn','JER',44,29,null,$b$Yêhôva lah: Aơ, jêng nau mbên ma khân may yor tă bơh nau nây gĭt gâp mra tâm rmal khân ay may tâm ntŭk aơ gay khân ay may gĭt ma nau gâp ngơi mra jêng ngăn ăn tât nau mhĭk ma khân ay may.$b$,false),
('bunong-vn','JER',44,30,null,$b$Pô aơ nau Yêhôva lah, Aơ, gâp mra jao Pharaôn Hôphra hađăch bri Êjipt ma ti phung rlăng păng jêh ri ma phung joi ŭch ƀư ngroh lơi nau rêh păng, nâm bu gâp jao jêh Y-Sêdêkia hađăch n'gor Yuđa tâm ti Y-Nêbukatnetsar hađăch, bri Babilôn, nơm jêng rlăng păng jêh ri joi nkhĭt păng.”$b$,false),
('bunong-vn','JER',45,1,null,$b$Pô aơ nau kôranh nơm mbơh lor Y-Yêrêmi ngơi ma Y-Baruk, kon bu klâu Y-Nêria, dôl păng chih nau ngơi aơ tâm du ndrom sămƀŭt tĭng nâm Y-Yêrêmi kâp sâm lah an, tâm năm rơh puăn Y-Jêhôjakim kon bu klâu Y-Jôsia hađăch Yuđa:$b$,true),
('bunong-vn','JER',45,2,null,$b$“Pô aơ Yêhôva Brah Ndu Israel lah ma may, Ơ Y-Baruk:$b$,false),
('bunong-vn','JER',45,3,null,$b$May lah jêh, Rêh ni ngăn ma gâp! Yor lah Yêhôva ntop jêh nau rngot ma nau ji gâp; gâp rgănh ma nau nđor nau rngot, jêh ri mâu geh nau rlu ôh.”$b$,false),
('bunong-vn','JER',45,4,null,$b$Yêhôva lah, “Pô aơ ăn may lah ma păng, Aơ, moh gâp ndâk jêh gâp klưh lơi păng, jêh ri moh ndơ gâp tăm jêh gâp rôk lơi păng tâm lĕ rngôch n'gor bri.$b$,false),
('bunong-vn','JER',45,5,null,$b$Bi may, may mâp joi nau toyh ma may nơm lĕ? Lơi ta joi nau nây ôh; yor lah aơ, gâp gŭ ăn tât nau mhĭk ma lĕ rngôch bunuyh, Yêhôva lah, ƀiă lah gâp mra prăp may rêh tâm lĕ ntŭk may hăn.”$b$,false),
('bunong-vn','JER',46,1,null,$b$Nau Yêhôva ngơi ma kôranh nơm mbơh lor Y-Yêrêmi di ma phung ndŭl mpôl bunuyh.$b$,true),
('bunong-vn','JER',46,2,null,$b$Di ma bri Êjipt; ma phung ta han Pharaôn Nêkô hađăch Êjipt gŭ ta kơh dak krong Ơphrat ta ƀon Karkêmis ma phung nây Y-Nêbukatnetsar hađăch Babilôn hŏ dơi jêh tâm năm rơh puăn Y-Jêhôjakim kon bu klâu Y-Jôsia hađăch Yuđa:$b$,true),
('bunong-vn','JER',46,3,null,$b$“Ndrăp rơm hom khêl jê̆ jêh ri khêl toyh, jêh ri rduh hom ma nau tâm lơh!$b$,false),
('bunong-vn','JER',46,4,null,$b$Dăp hom ưn seh, ncho hom, ơ phung ta han ncho seh! Hăn dăp hom ta ntŭk khân may jêh ri ndô môk loih, theng tak khân may, jêh ri nsoh hom ao loih khân may!$b$,true),
('bunong-vn','JER',46,5,null,$b$Mâm ƀư gâp lĕ saơ jêh nau nây? Khân păng rdja nuih jêh, jêh ri rŭch jêh. Phung ta han tâm lơh khân păng cha lôt jêh, jêh ri ngăch ma du ro, khân păng mâu hôm plơ̆ n'gĭl pa kơi ôh, geh nau nhhu nkrit jŭm chiau meng!” Yêhôva lah.$b$,true),
('bunong-vn','JER',46,6,null,$b$“Nơm dŭt prăl ăt mâu dơi ôh nchuăt, bunuyh dŭt dăng ăt mâu dơi klaih lĕ; tâm bri dor pa lơ ta kơh dak krong Ơphrat khân păng chêh jêh ri prah!$b$,true),
('bunong-vn','JER',46,7,null,$b$“Mbu nơm aơ hao nâm bu dak krong Nil, nâm bu dak krong lip?$b$,true),
('bunong-vn','JER',46,8,null,$b$Bri Êjipt hao nâm bu dak krong Nil, nâm bu dak krong lip. Păng lah, Gâp mra hao, gâp mra lip lam neh ntu; Gâp mra ƀư rai ƀon toyh jêh ri bunuyh gŭ tâm ƀon nây.$b$,true),
('bunong-vn','JER',46,9,null,$b$Rduh hom, ơ seh, jêh ri rduh hom, ơ phung ƀĭt ndeh seh! Ăn phung ta han tâm lơh ran rlet pa năp: Phung bu klâu n'gor Êthiôpi jêh ri n'gor Put phung djôt khêl. Phung bu klâu n'gor Lidi blau sŏng pănh na.$b$,true),
('bunong-vn','JER',46,10,null,$b$Nar nây jêng nar Yêhôva Brah Ndu ma phung ta han, jêng nar nau har plơng bôk ŭch har plơng ma phung rlăng păng. Đao dao mra sreh nkhĭt jêh ri Nhêt mham khân păng kŏ tât hơm. Yor lah Yêhôva Brah Ndu ma phung ta han ƀư brah, tâm bri dor pa lơ ta kơh dak krong Ơphrat.$b$,true),
('bunong-vn','JER',46,11,null,$b$Hăn hao hom ma bri Galaat jêh ri sŏk dak si, Ơ kon bu druh tang tat bri Êjipt! Khân ay dŏng âk ntil dak si kŏ mâu khlay lĕ; mâu geh nau ƀư bah ma khân ay ôh$b$,true),
('bunong-vn','JER',46,12,null,$b$Lĕ ntil mpôl bunuyh tăng lư jêh nau bêk prêng khân ay may, jêh ri lam bri neh ntu bu tăng lư nau ay may nhhiăng nhĭm; yor lah du huê ta han chêh prah đah du huê ta han êng; lĕ bar hê khân păng cha lôt jêh ndrel n'grŭp.”$b$,false),
('bunong-vn','JER',46,13,null,$b$Nau Yêhôva ngơi ma kôranh nơm mbơh lor Y-Yêrêmi di ma Y-Nêbukatnetsar hađăch bri Babilôn văch ŭch tâm lơh đah bri Êjipt:$b$,true),
('bunong-vn','JER',46,14,null,$b$“Mbơh hom tâm bri Êjipt, jêh ri tâm mpơl hom tâm ƀon Mikdôl; tâm mpơl hom tâm ƀon Nôp jêh ri ƀon Tahpanhes; lah hom, ‘Ndrăp rơm hom jêh ri nkra mra nau tâm lơh, yor lah đao dao mra sa văr jŭm khân ay may.’$b$,false),
('bunong-vn','JER',46,15,null,$b$Mâm ƀư phung ta han may lĕ cha lôt jêh? Khân păng mâu dơi dâk ôh, Yor lah Yêhôva n'glưh jêh khân păng.$b$,false),
('bunong-vn','JER',46,16,null,$b$Khân păng chêh prah ƀa ƀơ, jêh ri khân păng cha lôt ndrăng khân păng nơm. Khân păng lah, ‘Dâk jêh ri plơ̆ sĭt hom ma phung ndŭl mpôl he nơm, jêh ri ma bri me deh ma he, du ngai đah ntŭk tak đao nơm tŭn jot!’$b$,true),
('bunong-vn','JER',46,17,null,$b$Ta nây, khân păng mra lah, ‘Pharaôn, hađăch bri Êjipt, lĕ rai yot jêh; păng hŏ roh jêh nau ƀun lah.’$b$,false),
('bunong-vn','JER',46,18,null,$b$“Tĭng nâm gâp gŭ rêh.” Hađăch lah, amoh păng jêng Yêhôva ma phung ta han, “du huê mra jêng nâm bu yôk Tabor ta nklang âk gôl yôk, jêh ri nâm bu yôk Karmel êp dak mƀŭt.$b$,false),
('bunong-vn','JER',46,19,null,$b$Nkra hom ndô ndơ ay may hăn ƀư bu nă, Ơ bu druh tang tat gŭ tâm bri Êjipt! Yor lah ƀon Nôp mra jêng rngol, jêng du Ntŭk bu bun ndơ lĕ rai jêh, mâu geh ôh bunuyh gŭ.$b$,true),
('bunong-vn','JER',46,20,null,$b$“Bri Êjipt jêng du mlâm kon ndrôk me ueh, ƀiă lah du mlâm jop tă dor lơ tât kăp păng.$b$,true),
('bunong-vn','JER',46,21,null,$b$Nđâp ma phung ta han păng nkhôm jêh ndrel ma păng jêng nâm bu kon ndrôk lay; n'hêl nanê̆, khân păng ndôn kơi lĕ nchuăt du jêh ndrel n'grŭp, khân păng mâu tâm đâng ôh; yor lah nar rêh ni tât jêh ma khân păng, nar bu tâm rmal ma khân păng.$b$,true),
('bunong-vn','JER',46,22,null,$b$Nau nteh păng nâm bu hung bêh; yor lah phung rlăng khân păng rduh ran ktang ngăn; jêh ri văch ƀư ma păng djôt sung nâm bu kăl tơm si$b$,true),
('bunong-vn','JER',46,23,null,$b$Khân păng mra kăl si krŏng păng,” Yêhôva lah, “Nđâp lah bri nây krŏng mbâl, yor lah khân păng jêng âk lơn ma phung krah, bu mâu dơi kơp khân păng ôh.$b$,false),
('bunong-vn','JER',46,24,null,$b$Bu mra ăn prêng kon bu ur bri Êjipt, bu mra jao păng ma ti du phung ƀon lan tă dor lơ.”$b$,true),
('bunong-vn','JER',46,25,null,$b$Yêhôva ma phung ta han, Brah Ndu Israel lah: Aơ, gâp ăn tât nau tâm rmal ma phung Amôn ta ƀon Thêbes, hađăch Pharaôn, bri Êjipt jêh ri phung brah, jêh ri phung hađăch păng, jêh ri phung rnơm ma hađăch Pharaôn.$b$,true),
('bunong-vn','JER',46,26,null,$b$Gâp mra jao khân păng ma ti nơm joi nkhĭt khân păng, tâm ti Y-Nêbukatnetsar hađăch Babilôn jêh ri ma phung kôranh ta han păng. Jêh ta nây bu mra plơ̆ gŭ đŏng ta bri Êjipt nâm bu rnôk sa ơm,” Yêhôva lah.$b$,false),
('bunong-vn','JER',46,27,null,$b$“Ƀiă lah lơi ta klach ôh, Ơ phung Yakôb, phung oh mon gâp, mâu lĕ rdja nuih, ơ phung Israel; yor lah aơ, gâp mra rklaih khân ay may tă bơh ntŭk ngai, jêh ri phung kon sau ay may tă bơh ntŭk khân păng jêng bu nă. Phung Yakôb mra plơ̆ sĭt tay jêh ri gŭ đăp mpăn, jêh ri mâu geh du huê mra nhhu nkrit khân păng ôh.$b$,true),
('bunong-vn','JER',46,28,null,$b$Lơi ta klach ôh, Ơ phung Yakôb, phung oh mon gâp,” Yêhôva lah, “Yor lah gâp gŭ ndrel ma ay may, gâp mra ƀư rai lĕ rngôch phung mpôl băl bunuyh ta nklang khân păng nây yơh gâp hŏ mprơh khân ay may tât jêh; bi khân ay may, gâp mâu mra ƀư rai lĕ rngôch ôh. Gâp mra nkra khân ay may di keh, jêh ri gâp mâu lơi dơm ôh khân ay may klaih bơh nau tâm rmal.”$b$,true),
('bunong-vn','JER',47,1,null,$b$Nau Yêhôva ngơi ma kôranh nơm mbơh lor Y-Yêrêmi di ma phung Philistin, lor ma Pharaôn tâm lơh đah ƀon Gaxa:$b$,true),
('bunong-vn','JER',47,2,null,$b$Pô aơ Yêhôva lah, “Aơ, dak hao tă dor lơ, jêh ri mra jêng du n'hor dak thăng ler kŏ tât lip; khân păng mra lip bŭk bri dak jêh ri ndô ndơ tâm bri dak. Bŭk nđâp ma ƀon, nđâp ma bunuyh gŭ tâm ƀon. Phung bu klâu mra nhhiăng nhĭm, jêh ri lĕ rngôch bunuyh gŭ tâm trôm bri mra nhĭm vơl.$b$,false),
('bunong-vn','JER',47,3,null,$b$Tơ lah tăng nteh jâng seh păng, jêh ri nteh jâng ndeh seh rduh rlet pa năp, phung mbơ̆ mâu hôm n'gĭl uănh ma kon khân păng ôh, yor lah ti khân păng lĕ ra-ai ngăn$b$,true),
('bunong-vn','JER',47,4,null,$b$Yor lah lĕ tât nar jêh ŭch ƀư rai lĕ rngôch phung Philistin, gay ƀư ngroh lơi tâm ƀon Tir jêh ri ƀon Sidôn ăp nơm phung hôm e kơl păng. Yor lah Yêhôva mra ƀư rai phung ƀon lan Philistin, jêng phung hôm klen tă kô dak mƀŭt Kaphtôr.$b$,false),
('bunong-vn','JER',47,5,null,$b$Gaxa hŏ jêng jêh ntŭk hil; ƀon Askalôn lĕ rai yot jêh. Ơ phung hôm tâm neh lâng, ndah nâm jŏ khân ay may mra rek tor săk jăn ay may nơm?$b$,true),
('bunong-vn','JER',47,6,null,$b$Ơ đao dao Yêhôva! Ndah nâm jŏ dĭng may rlu? Ăn may ntrŭp hom tâm ndrop may, rlu jêh ri gŭ đăp mpăn!$b$,true),
('bunong-vn','JER',47,7,null,$b$Mâm păng dơi đăp gŭ mpăn, tơ lah Yêhôva ntăm jêh ma păng? Păng ntăm jêh ma ô băl ăn ƀư ma ƀon Askalôn jêh ri ma bri kơh dak mƀŭt.”$b$,true),
('bunong-vn','JER',48,1,null,$b$Nau di ma bri Môap: Pô aơ nau Yêhôva ma phung ta han, Brah Ndu Israel lah: “Rêh ni ngăn ma yôk Nêbô, yor lah bu mra ƀư rai jêh păng! Ƀon Kiriathaim bu ƀư prêng jêh păng, jêh ri bu sŏk pit jêh; bu ƀư rlâm jêh Misgap jêh ri păng dơn nau bêk prêng;$b$,true),
('bunong-vn','JER',48,2,null,$b$Mâu hôm geh ôh nau rnê ma bri Môap Tâm ƀon Hêsbon bu nchră ƀư mhĭk ma păng: ‘Văch hom, ăn he ƀư rai lơi kŏ tât păng mâu hôm jêng du ndŭl mpôl bunuyh ôh!’ may tâm ban lĕ, Ơ Matmen, bu mra ăn may roh rklăk; tak đao mra tĭng may.$b$,false),
('bunong-vn','JER',48,3,null,$b$Iăt hom! Geh bâr nter tă bơh ƀon Hôrônaim, ‘nau jêng rngol jêh ri nau ƀư rai toyh ngăn!’$b$,true),
('bunong-vn','JER',48,4,null,$b$‘Bri Môap lĕ rai jêh.’ Bu tăng bâr phung kon se jê̆ nter!$b$,false),
('bunong-vn','JER',48,5,null,$b$Yor lah ta ntŭk hao yôk Luhit, khân păng hao ma nau nhhiăng nhĭm; yor lah ta ntŭk njŭr sop tă ƀon Hôrônaim khân păng tăng jêh nau nter nhĭm vơl yor nau ƀư rai.$b$,true),
('bunong-vn','JER',48,6,null,$b$Du hom! Rklaih êng nau rêh khân ay may nơm! nâm bu tơm pôm tâm bri rdah!$b$,true),
('bunong-vn','JER',48,7,null,$b$Yor lah may rnơm ma kan jêh ri drăp ndơ may, nđâp ma may lĕ bu nhŭp jêng bu nă, jêh ri ƀon Kêmôs mra du luh tă bơh bri dak hăn jêng bu nă, ndrel ma phung kôranh ƀư brah jêh ri phung kôranh păng.$b$,true),
('bunong-vn','JER',48,8,null,$b$Nơm ƀư rai mra tât ma ăp rplay ƀon toyh, jêh ri mâu geh du rplay ƀon dơi klaih; bu mra ƀư rai rlŭng, jêh ri bri klơ dor lâng tâm ban lĕ, tĭng nâm Yêhôva ngơi jêh.$b$,true),
('bunong-vn','JER',48,9,null,$b$Ăn hom nting năr ma bri Môap, yor lah păng mra mpăr hăn du; lĕ rngôch ƀon toyh păng mra jêng rngol, mâu geh bunuyh gŭ tâm nây ôh.$b$,true),
('bunong-vn','JER',48,10,null,$b$“Rak rtăp hom ma nơm pah kan ma Yêhôva ma nau mƀruh; jêh ri rak rtăp hom ma nơm dun ma đao dao păng mâu ŭch ôh nkhŭt mham bu;$b$,true),
('bunong-vn','JER',48,11,null,$b$“Phung Môap gŭ đăp mpăn ntơm bơh rnôk păng hôm mom jêh ri gŭ jêh tâm ntŭk nđơh rngêt. Bu mâp nkhŭt păng tă bơh du mlâm yăng troch du mlâm yăng êng, mâu lĕ bu mâp mprơh păng tă bơh bri aơ leo bri êng; păng jêng nâm bu dak play kriăk ƀâu mâu blau sât ôh, jêh ri ƀâu ndrôm păng mâu blau rgâl ôh.$b$,false),
('bunong-vn','JER',48,12,null,$b$Yor nây, Yêhôva lah: Aơ, nar lĕ tât, rnôk nây gâp mra prơh hăn ndrel ma păng bunuyh nkhŭt, khân păng mra nkhŭt lơi păng, ăn nsoih lơi yăng, jêh ri dong lơi yăng jêng rsong hăch rhên.$b$,true),
('bunong-vn','JER',48,13,null,$b$Nôk nây phung Môap mra prêng ma ƀon Kêmôs, nâm bu ngih Israel prêng đah ƀon Bethel, ntŭk khân păng rnơm.$b$,true),
('bunong-vn','JER',48,14,null,$b$“Mâm khân may dơi lah, ‘Hên jêng phung janh nănh jêh ri phung ta han ktang tâm nau tâm lơh’?$b$,true),
('bunong-vn','JER',48,15,null,$b$Bu ƀư rai lĕ jêh ri Môap jêh ri tâm lơh bu lăp lĕ rngôch ƀon toyh păng, jêh ri phung bu klâu ndăm păng blau ueh ngăn lĕ bu nkhĭt.” Hađăch, amoh păng jêng Yêhôva ma phung ta han, hŏ lah jêh.$b$,true),
('bunong-vn','JER',48,16,null,$b$“Nau rai lôch ma bri Môap dăch tât jêh, jêh ri nau rêh ni păng tât gơnh ngăn.$b$,true),
('bunong-vn','JER',48,17,null,$b$Nhhiăng nhĭm hom ma păng, Ơ lĕ rngôch phung ay may gŭ văr jŭm păng, lĕ rngôch phung gĭt năl nau lư n'găr păng; lah hom, ‘Mâm ƀư mâng jra hađăch ktang ngăn lĕ pă jêh, mâng chrêk lơp nây.’$b$,true),
('bunong-vn','JER',48,18,null,$b$“Ơ bu ur druh gŭ tâm ƀon Di bôn! jŭr hom tă bơh nau chrêk lơp ay jêh ri gŭ hom ta neh sơh Yor lah nơm ƀư rai bri Môap tât jêh ŭch ƀư ma ay, păng ƀư rai jêh pôih nâp ay$b$,false),
('bunong-vn','JER',48,19,null,$b$Ăn khân ay may gŭ êp meng trong jêh ri kâp uănh, Ơ phung gŭ ta ƀon Arôer! Ôp hom ma bu klâu nchuăt du jêh ri bu ur lĕ klaih jêh; lah hom, ‘Moh nau tât jêh?’$b$,false),
('bunong-vn','JER',48,20,null,$b$Bu ƀư prêng jêh ri Môap, yor lah păng lĕ chah jêh, nhĭm vơl hom! Nkoch bri ta kơh dak krong Arnôn Bri Môap lĕ rai jêh.$b$,false),
('bunong-vn','JER',48,21,null,$b$Nau phat dôih tât jêh ma bri klơ dor lâng, ma ƀon Hôlon, ƀon Jahsa, ƀon Mêphat,$b$,true),
('bunong-vn','JER',48,22,null,$b$jêh ri ƀon Dibôn, ma yôk Nêbô, jêh ri ƀon Bet-Diblathaim$b$,false),
('bunong-vn','JER',48,23,null,$b$ƀon Kiriathaim, ƀon Bet-Gamul, jêh ri ƀon Bet-Mêôn,$b$,false),
('bunong-vn','JER',48,24,null,$b$ƀon Kêriôt, ƀon Bôsra, jêh ri lĕ rngôch ƀon toyh tâm bri Môap, ngai jêh ri dăch.$b$,false),
('bunong-vn','JER',48,25,null,$b$Bu lĕ kăt jêh nke bri Môap, jêh ri ti tur păng lĕ deh (pă) jêh,” Yêhôva lah,$b$,true),
('bunong-vn','JER',48,26,null,$b$“N'hơk ăn păng nhêt ndrănh kŏ nhŭl, yor lah păng n'hao êng păng nơm ŭch tâm rdâng đah Yêhôva; pô ri bri Môap mra pung tâm hok păng, jêh ri bu mra ntêh rmot ma păng đŏng.$b$,false),
('bunong-vn','JER',48,27,null,$b$Mâu di hĕ khân may lĕ tă ntêh rmot jêh ma phung Israel? Bu saơ phung Israel ndrel ma phung ntŭng, Nkhêp tơ lah khân may ngơi di ma păng khân may rteh bôk?$b$,true),
('bunong-vn','JER',48,28,null,$b$Du hom tă bơh ƀon toyh jêh ri gŭ tâm trôm lŭ, Ơ phung gŭ tâm bri Môap! Ăn khân may jêng nâm bu plŭk ƀư rsuăn tâm bâr trôm yôk.$b$,true),
('bunong-vn','JER',48,29,null,$b$“Hên tăng jêh nau sưr bri Môap, păng jêng sưr ngăn. Păng min ta klơ ir, păng ƀư khưm, nuih n'hâm păng bêng ma nau sưr.$b$,true),
('bunong-vn','JER',48,30,null,$b$Gâp gĭt nau djơh mhĭk păng,” Yêhôva lah, nau nây jêng dơm dam, nau păng ngơi sưr mâu dơi ôh.$b$,true),
('bunong-vn','JER',48,31,null,$b$Yor nây yơh gâp nhĭm vơl yor bri Môap; gâp nter yor lĕ rngôch phung Môap. Gâp klâng ndrê ma phung bu klâu tâm ƀon Kir-Hêres.$b$,true),
('bunong-vn','JER',48,32,null,$b$Gâp nhĭm yor may âk lơn ma ƀon Jaser, Ơ tơm play kriăk ƀâu ƀon Sipma! N'gĭng may nchrông ta klơ dak mƀŭt, kŏ tât ta dak mƀŭt Jaser; nơm ƀư rai văch tât lơh ma play may yan ta vai jêh ri play kriăk ƀâu may.$b$,true),
('bunong-vn','JER',48,33,null,$b$Bu sŏk hut jêh nau hâk răm jêh ri nau maak tă bơh đang jêh ri mir bri Môap; gâp nsuăt lơi dak play kriăk ƀâu tă bơh ntŭk păt kĭn; mâu geh nơm păt kĭn khân păng ma nau troh rhơn ôh; nau troh mâu di nau troh ma nau răm rhơn ôh.$b$,true),
('bunong-vn','JER',48,34,null,$b$“Ƀon Hêsbon jêh ri ƀon Êlêala nter, bu tăng bâr khân păng tât ta ƀon Jahas bơh ƀon Sôar tât ta ƀon Hôrônaim jêh ri ƀon Êglat-Sêlisiya. Yor lah dak ƀon Nimrim lĕ suăt tâm ban lĕ.”$b$,true),
('bunong-vn','JER',48,35,null,$b$Yêhôva lah, “Gâp mra ngroh lơi tâm bri Môap Mbu nơm nhhơr ndơ ƀư brah tâm ntŭk prêh, jêh ri su ndơ ƀâu kah ma brah păng.$b$,true),
('bunong-vn','JER',48,36,null,$b$Yor nây nuih n'hâm gâp nđor yor bri Môap nâm bu bâr n'hôm, nuih n'hâm gâp nđor tâm ban lĕ yor phung bu klâu tâm ƀon Kir-Hêres, nâm bu n'hôm; yor lah nau drŏng khân păng hŏ bun lĕ rai jêh.$b$,true),
('bunong-vn','JER',48,37,null,$b$Yor lah lĕ rngôch bôk bu poih têp kang ăp nơm kreh lĕ ƀhiau; lĕ rngôch ti bu tor da dê, jêh ri ăp nơm mbăn ƀau sat.$b$,true),
('bunong-vn','JER',48,38,null,$b$Ăp ta klơ chor ngih tâm n'gor Môap, jêh ri tâm nhuang ƀon păng, geh dơm nâu nhĭm vơl, yor lah gâp hŏ mbang chah bri Môap. Nâm bu du mlâm yăng bu mâu hôm ŭch ôh.” Yêhôva lah.$b$,true),
('bunong-vn','JER',48,39,null,$b$Ri, păng lĕ chah ngăn ro! Khân păng vơl dŭt hâu ngăn! Môap ndôn kơi jêh ma nau prêng! Pô ri bri Môap mra jêng ntŭk bu ntêh rmot jêh ri nau krit-klach ma lĕ rngôch bunuyh gŭ jŭm khân păng.”$b$,true),
('bunong-vn','JER',48,40,null,$b$Yor lah pô aơ Yêhôva lah: Aơ, mpôl rlăng mpăr seng nâm bu klang, jêh ri lĭ nting năr păng lơh đah bri Môap.$b$,true),
('bunong-vn','JER',48,41,null,$b$Bu mra pit in lĕ rngôch ƀon toyh, jêh ri lĕ rngôch pôih bu lĕ nchueng jêh. Tâm nar nây nuih n'hâm phung ta han bri Môap jêng nâm bu nuih n'hâm du huê bu ur bêch veng deh.$b$,true),
('bunong-vn','JER',48,42,null,$b$Bri Môap mra rai, jêh ri păng mâu hôm jêng du mpôl bunuyh ôh, yor lah khân păng n'hao êng nơm tâm rdâng đah Yêhôva.$b$,true),
('bunong-vn','JER',48,43,null,$b$Yêhôva lah: “Hơi phung Môap! Nau djơh mhĭk, ntu soh, dăk bu sân, dôl bu ƀư pa năp khân may.$b$,true),
('bunong-vn','JER',48,44,null,$b$“Mbu moh du nchuăt tă bơh nau djơh mhĭk nây mra rhuh tâm ntu soh, jêh ri mbu nơm hao du luh tă ntu soh mra geh dăk bu sân. Yor lah gâp mra ăn năm aơ nau tâm rmal tât ma bri Môap,’ Yêhôva lah.$b$,true),
('bunong-vn','JER',48,45,null,$b$Phung nchuăt du lĕ huăr jêh nde n'hâm gui ƀon Hêsbon, yor lah hit ŭnh luh tă Hêsbon, mpiăt ŭnh bơh ngih phung Sihôn; ŭnh nây ƀư rai njônh bri Môap, jêh ri nting bôk phung ƀư drơu-drơu$b$,true),
('bunong-vn','JER',48,46,null,$b$Rêh ni ngăn ma may, Ơ Môap! Bunuyh ƀon lan ƀon Kêmôs rai lôch jêh; yor lah phung kon bu klâu jêh ri bu ur khân păng bu djôt leo ƀư bu nă.$b$,false),
('bunong-vn','JER',48,47,null,$b$Ƀiă lah, tât ta nar nglĕ dŭt gâp mra leo phung bu nă Môap plơ̆ sĭt, Yêhôva lah. Pô ri nau phat dôih ma bri Môap tât dŭt nây dơm.$b$,true),
('bunong-vn','JER',49,1,null,$b$Pô aơ nau di ma phung Amôn, Yêhôva lah: “Bri Israel mâu geh hĕ kon bu klâu? Khân păng mâu geh hĕ bunuyh ndơn drăp? Pô ri, mâm ƀư brah Malkôm pit in Ndô ndơ phung Gat, jêh ri phung ƀon lan păng gŭ tâm ƀon toyh khân păng?$b$,true),
('bunong-vn','JER',49,2,null,$b$Yor nây, Yêhôva lah: “Aơ, nar mra tât,” “rnôk nây gâp mra ăn bu tăng bâr nŭng tâm lơh nteh huy lơh đah Raba tâm bri Amôn; ƀon nây mra jêng du gôl rngol jêh ri lĕ rngôch ƀon jê̆ păng bu mra su ma ŭnh. Rnôk nây phung Israel mra pit in ndô ndơ phung hŏ pit jêh ndơ khân păng.” Yêhôva lah.$b$,true),
('bunong-vn','JER',49,3,null,$b$“Nhĭm nhhiăng hom, Ơ ƀon Hêsbon, yor lah bu lĕ ƀư rai jêh ƀon Ahi! Hơi kon bu ur Raba! Nhĭm vơl hom. Nsoh hom ƀau sat, nchuăt nsong dâng lơ tâm nklang pêr nđâp ma nhĭm nhhiăng! Yor lah bu mra mprơh brah Malkôm hăn ƀư bu nă ndrel ma phung kôranh ƀư brah jêh ri phung kôranh păng luh du bơh n'gor.$b$,true),
('bunong-vn','JER',49,4,null,$b$Mâm ƀư khân may ntưih ir ma ntŭk rlŭng khân may, jêng ntŭk rlŭng geh play âk? Ơ kon bu ur mâu geh răp jăp ôh, Nơm nsing ma drăp ndơ khlay păng, jêh ri lah: ‘Mbu nơm mra dơi văch lơh ma gâp?’$b$,true),
('bunong-vn','JER',49,5,null,$b$Aơ, kôranh Brah, jêng Yêhôva ma phung ta han, lah: Aơ, gâp mra ƀư ăn tât nau djơh mhĭk ma khân may,” Tă bơh lĕ rngôch phung gŭ jŭm khân may, jêh ri bu mra mprơh khân may, ăp nơm rlet pa năp păng, mâu geh bunuyh mra rgum phung nchuăt du ôh.$b$,false),
('bunong-vn','JER',49,6,null,$b$Ƀiă lah năr kăndơ̆ gâp mra njŭn sĭt phung kon sau Amôn tă bơh nau jêng dĭk nă,” Yêhôva lah.$b$,true),
('bunong-vn','JER',49,7,null,$b$Nau di ma bri Êđôm. Pô aơ Yêhôva ma phung ta han lah: “Tâm ƀon Têman mâu hôm geh hĕ nau blau mĭn. Phung blau mĭn mâu hôm kơl nkah hĕ? Nau blau mĭn khân păng hŏ roh jêh mâu?$b$,true),
('bunong-vn','JER',49,8,null,$b$Hơi ƀon lan gŭ ta ƀon Dêdan! Nchuăt du hom, plơ̆ sĭt hom, hăn gŭ tâm lĕ trôm yôk jru; Yor lah gâp mra ƀư ăn tât nau ƀư rai ma Êsau, jêng nar gâp mra tâm rmal păng.$b$,true),
('bunong-vn','JER',49,9,null,$b$Phung pĕ play kriăk ƀâu tât ma may, mâu hôm hĕ ăn klen djê̆ djănh? Phung ntŭng tât dôl măng, mâu hĕ khân păng ntŭng man tŏng ma khân păng nơm?$b$,true),
('bunong-vn','JER',49,10,null,$b$Ƀiă lah gâp lĕ sŏk lơi jêh ndơ Êsau, gâp ăn mpơl lĕ jêh ntŭk khân păng krap, jêh ri khân păng mâu dơi pôn ndâp khân păng nơm ôh. Bu ƀư rai jêh kon sau, oh nâu, nđâp ma phung chiau meng khân păng, jêh ri khân păng nơm kŏ mâu hôm geh lĕ.$b$,true),
('bunong-vn','JER',49,11,null,$b$Cha lơi hom phung kon đơi may; gâp mra rong nau rêh khân păng, jêh ri lĕ phung bu ur ndrô may nsing ma gâp!”$b$,true),
('bunong-vn','JER',49,12,null,$b$Yor lah pô aơ Yêhôva lah: Aơ, lĕ rngôch phung mâu vay nhêt kachok aơ, nanê̆ mra nhêt ro; jêh ri may mra klaih lĕ đah nau tâm rmal? May mâu mra klaih ôh đah nau tâm rmal, ƀiă lah nanê̆ ngăn mra nhêt kachok nây.$b$,true),
('bunong-vn','JER',49,13,null,$b$Yêhôva lah: Yor lah gâp hŏ ton lah ma gâp nơm,” ƀon Bôsra mra jêng ndơ djơh mhĭk, ndơ bu ntêh rmot, ntŭk lĕ rai, jêh ri ntŭk bu rak rtăp; jêh ri lĕ rngôch ƀon toyh păng mra jêng rngol n'ho ro.$b$,true),
('bunong-vn','JER',49,14,null,$b$Aơ jêng nau mhe mhan tă bơh Yêhôva, ăn gâp tăng, jêh ri bu prơh hăn jêh du huê nơm mbơh ta nklang phung mpôl băl bunuyh: “Tâm rgum hom khân may du ai, jêh ri văch hăn lơh păng, du dâk hăn tâm lơh hom!$b$,false),
('bunong-vn','JER',49,15,null,$b$“Yor lah aơ, gâp hŏ ƀư may jêng jê̆-lê̆ ta nklang phung mpôl băl bunuyh, phung bunuyh mra mưch rmot ma may.$b$,true),
('bunong-vn','JER',49,16,null,$b$Hơi nơm gŭ tâm trôm nđa lŭ, nơm gŭ ta klơ n'glơn yôk ri, lah ma may jêng bunuyh klach ngăn, nuih n'hâm sưr may hŏ ndơm jêh may; nđâp tơ lah may ƀư rsuăn may ta ntŭk klơ nâm bu klang, gâp mra n'glưh may tŭp tă ntŭk nây.” Yêhôva lah.$b$,true),
('bunong-vn','JER',49,17,null,$b$Êđôm mra jêng du nau bu krit klach; ăp nơm mbu moh prot găn dăch ta nây mra klach ngăn ngên; jêh ri bu nsŭch n'găp yor lah lĕ rngôch nau rêh ni tât jêh ma khân păng$b$,true),
('bunong-vn','JER',49,18,null,$b$Nâm bu dôl rnôk bu n'glưh ƀon Sôdôm, ƀon Gômôrơ, jêh ri ƀon toyh chiau meng, Yêhôva lah, “Êđôm mâu mra geh bunuyh gŭ đŏng ôh, mâu geh lĕ bunuyh mra gŭ njưh ta nây.$b$,false),
('bunong-vn','JER',49,19,null,$b$Aơ, geh nâm bu yau mŭr tă hao văch tă bơh bri krŏng dak krong Yurdan ŭch tâm rdâng đah ntŭk gŭ nâp rjăp ngăn. Ƀât lât gâp mra ăn ma phung Êđôm nchuăt du luh bơh n'gor, jêh ri gâp mra njêng bunuyh gâp hŏ săch jêh gay chiă uănh păng: Yor lah mbu moh jêng nâm bu gâp? Mbu nơm mra dơi tâm rdâng đah gâp? Mbu rmăk biăp dơi dâk ta năp gâp?”$b$,true),
('bunong-vn','JER',49,20,null,$b$Pô ri iăt hom nau plĕch Yêhôva hŏ nkra jêh tâm rdâng đah Êđôm, jêh ri nau păng mĭn ŭch tâm rdâng phung gŭ tâm ƀon Têman: N'hêl nê̆ nđâp ma lĕ phung biăp bu mra nhŭp leo rdu; ntŭk gŭ khân păng jêng ngol.$b$,true),
('bunong-vn','JER',49,21,null,$b$Tơ lah tăng nau nteh khân păng tŭp, neh ntu mra n'găr; bu mra tăng nau khân păng nter tât ta Dak Mƀŭt Chăng.$b$,true),
('bunong-vn','JER',49,22,null,$b$Aơ, du huê bunuyh rlăng mpăr nâm bu klang, jêh ri lĭ nting năr, păng ŭch lơh đah ƀon Bôsra, jêh ri tâm nar nây nuih n'hâm phung bu klâu janh nănh tâm bri Êđôm mra jêng nâm bu nuih n'hâm du huê bu ur veng deh.”$b$,true),
('bunong-vn','JER',49,23,null,$b$Nau di ma ƀon Damas: “Ƀon Hamat jêh ri ƀon Arpat geh nau prêng, yor lah khân păng tăng jêh nau mhĭk; khân păng djoh nuih n'hâm, khân păng uh ah nâm bu rbuh dak lêng, mâu ŭch gŭ rngân ôh.$b$,true),
('bunong-vn','JER',49,24,null,$b$Ƀon Damas lĕ jêng rdja jêh, khân păng n'gĭl ŭch nchuăt du, jêh ri nau krit-klach ƀư ma păng, nau rngot rvê jêh ri nđêh nji ƀư ma păng, nâm bu du huê bu ur veng deh.$b$,true),
('bunong-vn','JER',49,25,null,$b$Pô ri moh nau bu mâu om ƀon geh nau lư n'găr, jêng ƀon ƀư nau răm maak ma gâp?$b$,true),
('bunong-vn','JER',49,26,null,$b$Yêhôva ma phung ta han lah: Yor ri, tâm nar nây, phung bu klâu ndăm păng mra cha lôt tâm trong ƀon, jêh ri lĕ rngôch phung ta han păng mra rai yor tâm nar nây.”$b$,true),
('bunong-vn','JER',49,27,null,$b$“Gâp mra su ŭnh ta mpêr ƀon Damas, jêh ri ŭnh nây mra sa pôih nâp hađăch Y-Ben-Hadat.”$b$,true),
('bunong-vn','JER',49,28,null,$b$Nau di ma phung Kêdar jêh ri Ƀon bri hađăch Hasôr, ma phung nây Y-Nêbukatnetsar hađăch Babilôn tâm lơh: Pô aơ Yêhôva lah: “Dâk hom, rduh lơh ma phung Kêdar! Ƀư rai lơi phung ƀon lan bri pa lơ!$b$,true),
('bunong-vn','JER',49,29,null,$b$Bu mra sŏk ngih bok jêh ri biăp khân păng, ngih vâl jêh ri ndô ndơ khân păng; bu mra djôt rdu seh samô khân păng, jêh ri phung bu klâu mra nter ma khân păng, lah: ‘Geh nau klach krit nchueng gŭ jŭm khân may!$b$,true),
('bunong-vn','JER',49,30,null,$b$Yêhôva lah: Ơ phung gŭ tâm ƀon Bri hađăch Hasôr, du hom gơnh! Du ntŭk ngai hom! Joi hom tâm ntŭk trôm yôk jru.” Yor lah Y-Nêbukatnetsar, hađăch Babilôn ndrăp, nkra nau ŭch tâm rdâng đah khân păng; păng hŏ rơm jêh nau gay ƀư rai khân may.$b$,true),
('bunong-vn','JER',49,31,null,$b$Yêhôva lah: “Dâk hom, rduh lơh du phung ƀon lan gŭ mpăn mâu geh nau mĭn rvê ôh.” Phung ƀon lan nây mâu geh mpông pêr, mâu lĕ geh mâng rnăng pêr; jêng du phung mpôl băl bunuyh gŭ êng.$b$,true),
('bunong-vn','JER',49,32,null,$b$Seh samô khân păng jêng ndơ bu pit in, phung ndrôk, biăp âk khân păng jêng ndơ n'hơm ma bu pit in. Gâp mra ƀư ma phung nơm poih têp kang du chah rai pru pra lam bri neh ntu, jêh ri gâp mra ƀư rai tât ma khân păng tă bơh ăp ntŭk gŭ jŭm khân păng.” Yêhôva lah:$b$,true),
('bunong-vn','JER',49,33,null,$b$“Ƀon bri hađăch Hasôr, mra jêng trôm ma so bri gŭ, geh du ntŭk hŏng mro mrăng; mâu geh bunuyh mra gŭ ta nây ôh, kŏ mâu geh lĕ bunuyh gŭ njưh ta nây.”$b$,false),
('bunong-vn','JER',49,34,null,$b$Nau Yêhôva ngơi ma kôranh nơm mbơh lor Y-Yêrêmi, lah ma bri Êlam, rnôk Y-Sêdêkia, hađăch Yuđa ntơm chiă uănh.$b$,true),
('bunong-vn','JER',49,35,null,$b$Pô aơ Yêhôva ma phung ta han lah: “Aơ, gâp mra nklah lơi na bri Êlam, jêng tơm nau dăng ktang khân păng.$b$,true),
('bunong-vn','JER',49,36,null,$b$Jêh ri gâp mra ƀư ăn tât ma bri Êlam puăn ntil Sial, tă bơh puăn njônh trôk; jêh ri gâp ma ƀư ma khân păng du chah rai pru pra ăp puăn njônh sial nây, jêh ri phung Êlam gâp mprơh jêh mra tât ma ăp ntil mpôl bunuyh.$b$,true),
('bunong-vn','JER',49,37,null,$b$Gâp mra ƀư rai phung Êlam ta năp phung rlăng khân păng, jêh ri ta năp phung ŭch nkhĭt khân păng; gâp mra ăn tât nau mhĭk ma khân păng, jêng nau gâp hao duh nuih đah khân păng;” Yêhôva lah. “Gâp mra njuăl đao tĭng pa kơi khân păng, kŏ tât gâp ƀư rai lĕ khân păng;$b$,true),
('bunong-vn','JER',49,38,null,$b$jêh ri gâp mra ndâk sưng hađăch gâp tâm bri Êlam; jêh ri gâp ƀư rai hađăch jêh ri phung kôranh păng khân păng.” Yêhôva lah.$b$,false),
('bunong-vn','JER',49,39,null,$b$Ƀiă lah tâm rnôk kăndơ̆ gâp mra mplơ̆ sĭt phung Êlam tă jêng dĭk nă bu.” Yêhôva lah.$b$,true),
('bunong-vn','JER',50,1,null,$b$Aơ nau Yêsu ngơi ma kôranh nơm mbơh lor Y-Yêrêmi, nau lah ma bri Babilôn, ma bri neh phung Kaldê:$b$,true),
('bunong-vn','JER',50,2,null,$b$“Mbơh tâm mpơl hom ta nklang phung ntil mpôl bunuyh, n'hao bok pla jêh ri mbơh hom, lơi ta pôn mo ôh nau nây, jêh ri lah: ‘Babilôn lĕ bu sŏk jêh, brah Bel lĕ prêng jêh, brah Mêrôdak bêng ma nau klach, Bu ƀư prêng jêh rup trah păng, rup brah păng lĕ ƀư rlâm rai jêh.’$b$,false),
('bunong-vn','JER',50,3,null,$b$Yor lah geh du ndŭl mpôl tă bơh dor lơ văch hao lơh păng ăn bri păng jêng rngol, jêh ri mâu mra geh bunuyh gŭ ta nây ôh; nđâp bunuyh jêh ri mpô mpa du der, jêh ri roh hêng.$b$,false),
('bunong-vn','JER',50,4,null,$b$Yêhôva lah: “Tâm nar nây jêh ri tâm rô̆ nây,” phung kon sau Israel jêh ri phung kon sau Yuđa plơ̆ sĭt ndrel n'grŭp, hăn jăng jai jêh ri nhĭm jăng jai, jêh ri khân păng ŭch joi Yêhôva Brah Ndu khân păng.$b$,true),
('bunong-vn','JER',50,5,null,$b$Khân păng ôp trong hăn ma ƀon Siôn, muh măt khân păng rle ma ƀon Siôn, khân păng mra văch jêh ri tâm nkol khân păng đah Yêhôva du nau tâm rnglăp n'ho ro khân păng mâu mra chuêl ôh$b$,true),
('bunong-vn','JER',50,6,null,$b$“Phung ƀon lan gâp lĕ jêng nâm bu biăp chuêl trong jêh; phung rmăk khân păng ƀư vĭ trong, ăn ma khân păng nsong mblêng ta yôk, hăn pơh yôk hao nor, khân păng chuêl ndrung n'gar khân păng nơm.$b$,false),
('bunong-vn','JER',50,7,null,$b$Ma mbu moh mâp khân păng sreh sa gŭch khân păng, jêh ri phung rlăng khân păng lah: ‘Hên mâu jêng tih ôh, yor lah khân păng hŏ ƀư tih jêh ma Yêhôva, jêng ntŭk gŭ tâm nau sŏng (ntŭk gơ̆ se khân păng ngăn), nâm bu ntĭt Yêhôva, Nơm phung che khân păng kâp gân.’$b$,true),
('bunong-vn','JER',50,8,null,$b$“Du hom tă bơh ƀon Babilôn, jêh ri du luh bơh bri Kaldê, jêh ri jêng nâm bu be nkuăng hăn leo mpôl!$b$,false),
('bunong-vn','JER',50,9,null,$b$Yor lah aơ, gâp mra nsônh âk ntil mpôl bunuyh du dâk tă bơh bri dor lơ, jêh ri tâm lơh đah Babilôn, lĕ rngôch phung mpôl băl nây khân păng mra dăp ta han lơh Babilôn, jêh ri ntơm bơh nây dơi bu mra sŏk ƀon Babilôn. Hăr khân păng jêng nâm bu ta han lĕ blau ngăn, mâu sĭt ti dơm ôh.$b$,true),
('bunong-vn','JER',50,10,null,$b$Bu mra pit in phung Kaldê; ma phung pit in păng mra dơi hơm răm ngăn,” Yêhôva lah.$b$,true),
('bunong-vn','JER',50,11,null,$b$“Yor lah khân may rhơn jêh ri răm, Ơ phung pit in drăp ndơn gâp, yor lah khân may hăn pâl nâm bu du mlâm ndrôk druh tâm ndrêch gơ̆ nse, jêh ri krĭk nâm bu seh nkuăng gar me.$b$,true),
('bunong-vn','JER',50,12,null,$b$Yor nây, mê̆ khân may mra prêng; bu mra ƀư bêk-prêng nơm deh ma khân may. Aơ, ô băl mra jêng nơm dơm dam Lor ma phung mpôl băl bunuyh êng, du ntŭk bri rdah, jêh ri ntŭk neh kroh đang, jêh ri bri dơm.$b$,true),
('bunong-vn','JER',50,13,null,$b$Yor nau Yêhôva nuih mâu mra geh đŏng ôh bunuyh gŭ ta nây, knŏng păng mra jêng rngol da dê; ma mbu hăn prot dăch ƀon Babilôn mra hih rhâl ngăn, jêh ri gơm mưch lĕ nau sôt rmanh păng.$b$,true),
('bunong-vn','JER',50,14,null,$b$Ơ lĕ rngôch phung rnă na! (Djôt na) dăp hom phung ta han tâm lơh đah Babilôn gŭ jŭm; pănh păng, lơi ta têm ôh hăr: Yor lah păng hŏ ƀư tih jêh đah Yêhôva.$b$,true),
('bunong-vn','JER',50,15,null,$b$Troh nter hom gŭ jŭm tâm lơh đah păng, Păng hŏ ran lăp khân may jêh, pôih nâp păng rlâm rai jêh. Mpêr ƀon păng lĕ klưh rlâm: Nây jêng nau Yêhôva har plơng bôk! Plơng hom bôk păng, ƀư ma păng nâm bu păng hŏ ƀư jêh ma phung êng,$b$,true),
('bunong-vn','JER',50,16,null,$b$Ƀư rai lơi nơm srih ntil tă bơh Babilôn, nđâp ma nơm ndjôt nhuĕ dôl yan rek; yor lah klach ma đao dao nơm tŭn jot, ăn ăp nơm plơ̆ sĭt ma bri ƀon păng nơm, jêh ri ăp nơm nchuăt du ma bri păng nơm.$b$,false),
('bunong-vn','JER',50,17,null,$b$“Israel jêng du mlâm biăp chah rai nhhơt jêh, phung yau mŭr tĭng kăp jêh. Ntơm sa ơm hađăch Asiri hêk sa jêh păng. Jêh ri kêng dăch dŭt Y-Nêbukatnetsar hađăch Babilôn gĭnh jêh nting păng.”$b$,true),
('bunong-vn','JER',50,18,null,$b$Yor nây, pô aơ Yêhôva ma phung ta han, Brah Ndu Israel lah: “Aơ, gâp mra tâm rmal hađăch Babilôn, jêh ri bri dak păng, Nâm bu gâp hŏ tâm rmal jêh hađăch bri Asiri.$b$,true),
('bunong-vn','JER',50,19,null,$b$Pô ri, gâp mra njŭn sĭt Israel ma ntŭk păng nơm, jêh ri khân păng mra sa gơ̆ ta yôk Karmel jêh ri tâm bri Basan, nuih n'hâm păng hơm mpay ta klơ gôl yôk bri Êphraim jêh ri tâm bri Galaat.$b$,true),
('bunong-vn','JER',50,20,null,$b$Yêhôva lah: “Tâm nar nây, jêh ri rnôk nây, bu mra joi nau kue tâm phung Israel, ƀiă lah mâu mra saơ ôh; bu mra joi nau tih tâm phung Yuđa, ƀiă lah mâu mra saơ ôh; yor lah gâp mra yô̆ an nau tih ma phung khân păng hôm e gâp prăp.”$b$,true),
('bunong-vn','JER',50,21,null,$b$Yêhôva lah: “Hăn hao lơh hom bri Mêrathaim, jêh ri ƀư ma phung gŭ tâm bri Pêkôt. Nkhĭt jêh ri ƀư rai lĕ khân păng.” Jêh ri ƀư tĭng nâm lĕ ntil nau gâp hŏ ntĭnh jêh ma may!$b$,true),
('bunong-vn','JER',50,22,null,$b$Nteh nau tâm lơh bu tăng tâm n'gor; jêh ri nau ƀư rai toyh ngăn$b$,true),
('bunong-vn','JER',50,23,null,$b$Me nôp ma lam neh ntu, bu ƀư pă (deh) jêh chah nâm nây ro! Babilôn hŏ jêng rngol jêh ta nklang ntĭl mpôl bunuyh nây ro!$b$,false),
('bunong-vn','JER',50,24,null,$b$Gâp hŏ sân jêh dăk ma may, jêh ri may geh dăk jêh ƀiă lah mâu gĭt! Lor ma may gĭt nau nây, bu saơ jêh ri nhŭp may, yor lah may hŏ tâm rdâng jêh đah Yêhôva.$b$,true),
('bunong-vn','JER',50,25,null,$b$Yêhôva pơk jêh ntŭk prăp ndơ tâm lơh păng, jêh ri ngluh jêh ndơ păng tâm lơh yor nau păng nuih; yor lah Yêhôva, Brah Ndu ma phung ta han, geh du nau kan ŭch ƀư, tâm bri phung Kaldê.$b$,true),
('bunong-vn','JER',50,26,null,$b$Hăn tât hom tă bơh bri dŭt ngai tâm lơh đah păng; pơk han ntŭk prăp ndơ tâm lơh păng, bun hom păng nâm bu bun mbŭch, jêh ri ƀư rai hom lĕ ƀhiau, lơi hôm om djê̆ djănh!$b$,true),
('bunong-vn','JER',50,27,null,$b$Nkhĭt hom lĕ rngôch ndrôk nkuăng păng, ndjôt leo ntŭk bu ƀư puăch (puăch)! Rêh ni ngăn ma khân păng, yor lah nar ma khân păng hŏ tât jêh, jêng rnôk tâm rmal ma khân păng!$b$,true),
('bunong-vn','JER',50,28,null,$b$Iăt hom! Bâr phung nchuăt du nter, jêh ri phung lĕ klaih tă bơh bri Babilôn mbơh tâm ƀon Siôn nau Yêhôva Brah Ndu he har plơng bôk, nau plơng bôk ma ngih brah Păng.$b$,true),
('bunong-vn','JER',50,29,null,$b$“Kuăl hom lĕ rngôch phung djôt rnă na, ăp nơm phung blau pănh hăn tât lơh Babilôn; ƀư rmblak gŭ jŭm păng; lơi hôm ăn du huê dơi klaih! Nsĭt hom ma păng tĭng nâm kan păng hŏ ƀư jêh, ƀư ma păng tĭng nâm lĕ rngôch nau păng hŏ tă mâp ƀư jêh; yor lah păng hŏ tâm rdâng jêh đah Yêhôva, Nơm Kloh Ueh he.$b$,true),
('bunong-vn','JER',50,30,null,$b$Yor nây phung bu klâu ndăm păng mra cha lôt tâm trong ƀon păng, jêh ri lĕ rngôch phung ta han păng mra rai yot tâm nar nây.” Yêhôva lah.$b$,true),
('bunong-vn','JER',50,31,null,$b$“Aơ, gâp gŭ tâm rdâng đah may, Ơ nơm sưr,” Yêhôva Brah Ndu ma phung ta han lah: “Yor lah nar ma may hŏ tât jêh, jêng rnôk gâp tâm rmal ma may.$b$,true),
('bunong-vn','JER',50,32,null,$b$Nơm sưr mra chêh jêh ri prah, mâu geh nơm rdâk păng ôh, jêh ri gâp mra su ŭnh tâm ƀon toyh păng, jêh ri ŭnh mra sa lĕ rngôch ndơ gŭ jŭm păng.$b$,true),
('bunong-vn','JER',50,33,null,$b$Pô aơ Yêhôva ma phung ta han lah: “Bu tŭn jot jêh phung kon sau Israel, nđâp phung kon sau Yuđa ndrel ma khân păng; lĕ rngôch phung nhŭp leo khân păng jêng bu nă nkân ăn rjăp, lah khân păng dun kŏ mâu mƀơk lĕ.$b$,true),
('bunong-vn','JER',50,34,null,$b$Nơm Tâm chuai khân păng jêng ktang ngăn, amoh Păng jêng Yêhôva Brah Ndu ma phung ta han. N'hêl nanê̆ Păng mra king kan khân păng, gay ăn ma lĕ rngôch bri dak gŭ mpăn, jêh ri ƀư rŭng răng ma phung gŭ tâm bri Babilôn.$b$,true),
('bunong-vn','JER',50,35,null,$b$Yêhôva lah: “Ăn du mlâm đao dao lơh ma phung Kaldê.” “Lơh nđâp ma phung gŭ tâm ƀon Babilôn, ma phung kôranh jêh ri phung blau mĭn khân păng!$b$,true),
('bunong-vn','JER',50,36,null,$b$Ăn geh du mlâm pêih đao ƀư ma phung sưr rlau, gay ma khân păng jêng rluk! Ăn du mlâm pêih đao ƀư ma phung ta han khân păng, gay ma khân păng rai yot!$b$,true),
('bunong-vn','JER',50,37,null,$b$Ăn du mlâm pêih-đao ƀư ma seh jêh ri ndeh seh khân păng, jêh ri nđâp ma lĕ rngôch phung mpôl bunuyh gŭ tâm pot tâm nklang khân păng gay ma khân păng jêng nâm bu bu ur! Ăn du mlâm pêih-đao ƀư ma lĕ rngôch drăp ndơ khân păng, gay ma bu dơi pit in prăp ndơ nây!$b$,true),
('bunong-vn','JER',50,38,null,$b$Ăn trôk prăng ta klơ n'hor dak khân păng, gay ma khân păng suăt, kroh! Yor lah bri păng jêng bri bêng ma rup trah, jêh ri phung nây rluk yor rup brah.$b$,true),
('bunong-vn','JER',50,39,null,$b$Yor nây mpô mpa bri jêh ri so bri mra gŭ tâm ƀon Babilôn, jêh ri sĭm ôtrus mra gŭ tâm păng; mâu mra geh bunuyh gŭ n'ho ro đŏng ôh tâm ƀon Babilôn, ntơm bơh rô̆ aơ tât rô̆ kăndơ̆ bu mâu mra gŭ ôh ta nây.”$b$,true),
('bunong-vn','JER',50,40,null,$b$Pô aơ Yêhôva lah: “Păng mra jêng nâm bu Sôdôm, Gômôrơ, jêh ri ƀon chiau meng păng, tơ lah Brah Ndu ƀư rai lĕ rngôch ƀon nây; mâu mra geh bunuyh gŭ đŏng ôh, kŏ mâu geh lĕ bunuyh hăn tât gŭ ta nây.”$b$,true),
('bunong-vn','JER',50,41,null,$b$Aơ, geh du mpôl bunuyh ƀon lan văch ta bri dor lơ; du ntil mpôl bunuyh ktang jêh ri geh âk hađăch ntơm du dâk tă bơh ntŭk bôl neh ntu.$b$,true),
('bunong-vn','JER',50,42,null,$b$Khân păng djôt na jêh ri tak; khân păng jêng djơh mhĭk, jêh ri mâu gĭt nau yô̆ ôh. Nteh khân păng nâm bu nteh ktang târ dak lêng; Ơ phung kon bu ur ƀon Babilôn! Khân păng hŏ ncho seh văch tât jêh, Lĕ dăp nthăng nam bu bunuyh ma nau tâm lơh; gay tâm rdâng đah may.$b$,true),
('bunong-vn','JER',50,43,null,$b$Hađăch ƀon Babilôn lĕ tăng jêh nau bu mbơh ma khân păng, jêh ri ti păng jêng ra-ai; nau rngot-rvê kuăn păng, geh nau ji nâm bu ur veng deh.$b$,true),
('bunong-vn','JER',50,44,null,$b$Aơ, nơm rlăng nâm bu du mlâm yau mŭr hao tă bơh bri krŏng dak krong Yurdan ŭch tâm rdâng đah ntŭk gŭ nâp, ƀât lât, gâp mra ăn phung Kaldê nchuăt du, jêh ri gâp njêng dơm bunuyh gâp hŏ săch jêh chiă uănh khân păng. Yor lah, mbu moh jêng nâm bu gâp? Mra dơi tâm rdâng đah gâp? Mbu rmăk biăp dơi gŭ ndâk ta năp gâp?”$b$,true),
('bunong-vn','JER',50,45,null,$b$Yor nây iăt hom nau Yêhôva nkra jêh ŭch ƀư ma ƀon Babilôn, jêh ri nau păng nkra jêh ŭch ƀư ma bri phung Kaldê: N'hêl nê̆, bu mra nhŭp rdu kon biăp bơh ndrung n'gar păng; gay ƀư rai ntŭk ndrêch gơ̆ khân păng jêng rngol!$b$,true),
('bunong-vn','JER',50,46,null,$b$Tơ lah tăng nteh bu sŏk ƀon Babilôn, neh ntu mra n'găr, jêh ri nau nter bu mra tăng ta nklang lam bri neh ntu.$b$,true),
('bunong-vn','JER',51,1,null,$b$Pô aơ Yêhôva lah: “Aơ, gâp mra ăn sial ƀư rai tâm rdâng đah ƀon Babilôn, jêh ri phung gŭ tâm ƀon Lip-Kamai (bri Kaldê).$b$,true),
('bunong-vn','JER',51,2,null,$b$Gâp mra prơh hăn phung bunăch tât rkhŭk ƀon Babilôn, jêh ri khân păng gŭm-nsiăng bri dak păng, yor lah lĕ tât nar ƀư rai jêh, khân păng mra văch ƀư ma Babilôn tă bơh puăn njônh bri gŭ jŭm păng.$b$,true),
('bunong-vn','JER',51,3,null,$b$Lơi ăn ta han djôt na van na păng ôh, jêh ri lơi ăn păng gŭ dâk nsoh ao loih păng ôh. Lơi hôm om ôh phung ta han ndăm păng, ƀư rai lĕ rngôch phung ta han păng.$b$,true),
('bunong-vn','JER',51,4,null,$b$Khân păng mra chôt khĭt tâm bri phung Kaldê, jêh ri bu ntâp tât khĭt tâm trong toyh păng.$b$,true),
('bunong-vn','JER',51,5,null,$b$Jêh ri phung Israel nđâp phung Yuđa bu mâu dun cha lơi ôh yor lah Brah Ndu khân păng, Brah Ndu Yêhôva ma phung ta han; nđâp lah bri dak khân păng bêng ma nau tih mhĭk kđôi lĕ ta năp Nơm Kloh Ueh Israel.$b$,true),
('bunong-vn','JER',51,6,null,$b$“Du hom tă bơh ƀon Babilôn, ăn ăp nơm nchuăt du tâm rklaih nau rêh păng! Lơi ăn rai yot ôh yor ma nau tih ô băl, yor lah aơ jêng rnôk Yêhôva plơng bôk, Păng mra mplơ̆ sĭt ma păng tĭng nâm kan păng hŏ ƀư jêh.$b$,true),
('bunong-vn','JER',51,7,null,$b$Ƀon Babilôn jêng du mlâm kachok mah tâm ti Yêhôva, ăn lĕ rngôch lam bri neh ntu nhŭl ndrănh; phung ndŭl mpôl bunuyh hŏ nhêt jêh ndrănh păng, yor nây yơh dĭng jêng brŭt rluk.$b$,true),
('bunong-vn','JER',51,8,null,$b$Ƀât lât ƀon Babilôn lĕ tŭp jêh ri chah rai jêh; yor na păng nhĭm vơl hom! Sŏk hom dak si săm nau ji păng, gĭt lah păng dơi bah ji?$b$,true),
('bunong-vn','JER',51,9,null,$b$He ăt ŭch lĕ gay ƀư bah ƀon Babilôn, ƀiă lah ô băl mâu dơi bah ôh Cha lơi hom păng, jêh ri ăn ăp nơm hăn sĭt rlet ma bri păng nơm; yor lah nau tâm rmal ma păng hao tât klơ trôk, păng hao klơ tât ma ndâr tŭk.$b$,true),
('bunong-vn','JER',51,10,null,$b$‘Yêhôva hŏ tâm mpơl jêh nau he jêng sŏng srăng; văch hom, ăn he mbơh tâm ƀon Siôn kan Yêhôva Brah Ndu he hŏ ƀư jêh.’$b$,true),
('bunong-vn','JER',51,11,null,$b$“Lah hom hăr! Kuăn khêl ăn nâp! Yêhôva hŏ nsônh jêh nau ŭch mĭn phung hađăch bri Mêdơ, Yor lah nau păng ŭch ƀư jêng nau ƀư rai lơi ƀon Babilôn; Yêhôva mra plơng bôk, Păng mra plơng bôk ma ngih brah Păng.$b$,false),
('bunong-vn','JER',51,12,null,$b$N'hao bok pla tâm rdâng đah mpêr ƀon Babilôn, ntop phung gak ăn ktang, dơm phung gak, kâp ƀư ma khân păng; yor lah Yêsu hŏ nkra jêh nau Păng ŭch ƀư jêh ri nau Păng ngơi lah ma phung gŭ tâm ƀon Babilôn.$b$,true),
('bunong-vn','JER',51,13,null,$b$Hơi ƀon toyh ndrŏng ma drăp ndơ khlay, gŭ dăch âk n'hor dak, nau rai lôch ma may tât jêh, rnôk bu mra ƀư rai may.$b$,true),
('bunong-vn','JER',51,14,null,$b$Yêhôva ma phung ta han ton săk êng ma păng nơm; n'hêl nê̆gâp mra ăn ma may bêng phung băl bu êng âk râk nâm bu krah; jêh ri khân păng mra nter troh yor lah khân păng dơi jêh tâm rdâng đah may.$b$,true),
('bunong-vn','JER',51,15,null,$b$“Yêhôva yơh jêng Nơm hŏ rhăk njêng jêh neh ntu ma nau brah Păng. Păng ƀư nâp neh ntu ma nau blau mĭn Păng, jêh ri ma nau gĭt rbăng Păng lăk jêh phung trôk.$b$,true),
('bunong-vn','JER',51,16,null,$b$Tơ lah tăng Păng ngơi, geh nteh dak ro rŏch tâm phung trôk, jêh ri Păng ăn dak ngom hao thŭl bơh bôl dŭt neh ntu. Păng njêng lơp ndrel ma dak mih, jêh ri tă tâm jay Păng luh du sial.$b$,true),
('bunong-vn','JER',51,17,null,$b$Yor ri geh âk nuyh jêng rluk, jêh ri mâu geh nau gĭt rbăng ôh; nơm rhăk mah prêng da dê yor ma rup trah brah păng, yor lah rup trah khân păng mâu ngăn ôh, jêh ri mâu geh nsôr n'hâm ôh (suh n'hâm) tâm rup nây.$b$,true),
('bunong-vn','JER',51,18,null,$b$Ndơ nây mâu khlay ôh, du ntil kan ndơm bu; ta rnôk tât nau tâm rmal ma khân păng, khân păng mra rai-yot.$b$,true),
('bunong-vn','JER',51,19,null,$b$Drăp ndơn Y-Yakôb mâu jêng nâm bu ndơ nây ôh, yor lah Păng yơh jêng Nơm hŏ rhăk njêng lĕ rngôch ndô ndơ, mpôl băl Israel jêng drăp ndơn Păng; Amoh Păng jêng Yêhôva ma phung ta han.$b$,true),
('bunong-vn','JER',51,20,null,$b$“May jêng me nôp jêh ri ndơ gâp rnă tâm lơh; gâp dŏng may ƀư chah lĕ rngôch phung mpôl bunuyh jêh ri ma may gâp ƀư rai âk ƀon bri hađăch.$b$,true),
('bunong-vn','JER',51,21,null,$b$Gâp mra dŏng may ƀư chah hăch rhên. Seh jêh ri rmăk păng, ma may gâp ƀư chah hăch-rhên ndeh seh jêh ri rmăk păng,$b$,true),
('bunong-vn','JER',51,22,null,$b$ma may gâp ƀư rai bu ur jêh ri bu klâu, ma may gâp ƀư rai bu klâu ranh jêh ri phung bu mom, ma may gâp ƀư rai phung bu klâu ndăm jêh ri bu druh tang-tat,$b$,false),
('bunong-vn','JER',51,23,null,$b$ma may gâp ƀư rai rmăk biăp nđâp ma biăp păng, ma may gâp ƀư rai nơm ƀư mir jêh ri ndrôk chuar mir păng ma may gâp ƀư rai kôranh toyh jêh ri phung kôranh ta han.$b$,false),
('bunong-vn','JER',51,24,null,$b$“Gâp mra mplơ̆ sĭt ma ƀon Babilôn jêh ri lĕ rngôch phung gŭ tâm bri Kaldê ta năp măt khân may yor lĕ rngôch nau mhĭk khân păng hŏ mâp ƀư jêh tâm ƀon Siôn.” Yêhôva lah.$b$,true),
('bunong-vn','JER',51,25,null,$b$“Aơ, gâp tâm rdâng ma may, Ơ yôk gĭt ƀư rai.” Yêhôva lah, “nơm ƀư rai lĕ neh ntu; Gâp mra yơr ti gâp ƀư ma may, jêh ri mra rlă may bơh pŭng yôk, ƀư ăn may jêng yôk ŭnh sa jêh.$b$,true),
('bunong-vn','JER',51,26,null,$b$Bu mâu mra sŏk du mlâm lŭ tă bơh may dơm ta njônh, jêh ri mâu lĕ sŏk du mlâm lŭ nây ƀư mbon đŏng, ƀiă lah may mra jêng ntŭk rngol ƀa ƀơ n'ho ro,” Yêhôva lah.$b$,true),
('bunong-vn','JER',51,27,null,$b$“N'hao hom du blah bok pla ta klơ neh ntu, uh hom nŭng ta nklang phung mpôl băl bunuyh; Ndrăp rơm hom phung mpôl băl bunuyh gay tâm lơh đah păng. Kuăl hom phung bri hađăch Ararat, Mini, jêh ri Askênas văch tât ƀư ma păng! Dơm hom du huê kôranh ta han toyh tâm rdâng đah păng, djôt leo hom seh ăn âk râk nâm bu krah!$b$,true),
('bunong-vn','JER',51,28,null,$b$Rơm ndrăp hom ntil mpôl bunuyh tâm lơh đah păng, phung hađăch bri Mêdơ ndrel ma phung kôranh toyh jêh ri phung kôranh păng, jêh ri lĕ rngôch bri khân păng chiă uănh.$b$,true),
('bunong-vn','JER',51,29,null,$b$Neh tât n'găr jêh ri mpât n'gơ yor lah nau Yêsu nkra ŭch ƀư ma ƀon Babilôn hŏ nâp ngăn, ŭch ăn bri Babilôn jêng rngol mâu geh bunuyh gŭ ta nây ôh.$b$,true),
('bunong-vn','JER',51,30,null,$b$Phung ta han bri Babilôn rlu jêh tâm lơh, khân păng ăt gŭ tâm pôih nâp khân păng; nau ktang khân păng lĕ roh jêh, khân păng jêng nâm bu bu ur; ngih vâl khân păng mra bu su ma ŭnh, mâng rnăng mpông pêr pă jêh (deh jêh).$b$,true),
('bunong-vn','JER',51,31,null,$b$Tahan gak rmlak, văch mbơh tâm mâp ndrel đah nơm êng, du huê nơm ntuh bâr tâm mâp đah nơm ntuh bâr êng gay mbơh ma hađăch Babilôn ma nau ƀon khân păng lĕ bu sŏk jêh jŭm pŭng meng;$b$,true),
('bunong-vn','JER',51,32,null,$b$Mbong dak ntŭk bu vay lăp rgăn lĕ bu sŏk jêh, ntŭk djut rhuh lĕ bu su jêh ma ŭnh, jêh ri phung ta han lĕ klach nsâr.”$b$,false),
('bunong-vn','JER',51,33,null,$b$Yor lah pô aơ Yêhôva Brah Ndu Israel lah: “Kon bu ur ƀon Babilôn jêng nâm bu ntŭk bu mprah ba ta yan bu plên ba, hôm knŏng djê̆ lê̆, jêh ri yan bu rek păng mra tât.”$b$,true),
('bunong-vn','JER',51,34,null,$b$“Y-Nêbukatnetsar, hađăch Babilôn, hŏ gĭnh rvăn gâp jêh, ƀư chah gâp, cha lơi gâp nâm bu yăng nsoih; păng sa rvăn gâp, păng jêng nâm bu mpô mpa bri toyh; păng mbêng ndŭl păng ma ndơ kah gâp; păng mprơh luh pa dih.”$b$,true),
('bunong-vn','JER',51,35,null,$b$Ăn phung gŭ tâm ƀon Siôn lah: “Ăn nau ƀư ƀai hŏ ƀư ma gâp jêh ri ma nglay săk gâp tât ma ƀon Babilôn,” ăn phung gŭ tâm ƀon Yêrusalem lah, “Ăn mham gâp hoch ta klơ phung gŭ tâm bri Kaldê.”$b$,true),
('bunong-vn','JER',51,36,null,$b$Yor nây pô aơ Yêhôva lah: Aơ, gâp mra king nau kon may, jêh ri har plơng bôk ăn ma may. Gâp mra nsuăt lơi dak mƀŭt păng, jêh ri ăn tu păng sơh, kroh.$b$,true),
('bunong-vn','JER',51,37,null,$b$Ƀon Babilôn mra jêng du mbŭch ndơ djơh rai, ntŭk so bri gŭ, du ntil ndơ bu nkrit, jêh ri ndơ bu nsŭch n'găp, mâu hôm geh bunuyh gŭ ôh.$b$,true),
('bunong-vn','JER',51,38,null,$b$Khân păng mra ngrông ndrel n'grŭp nâm bu yau mŭr khân păng mra rđuh nâm bu kla mŭr kon.$b$,true),
('bunong-vn','JER',51,39,null,$b$Dôl khân păng nsônh nuih ŭch ƀư khân păng nkra nau sông sa toyh ma khân păng, jêh ri ăn khân păng nhŭl ndrănh kŏ tât khân păng troh nter jêh ri gơm, jêh ri n'ho lêt bêch, mâu hôm kah rngăl ôh,” Yêhôva lah.$b$,true),
('bunong-vn','JER',51,40,null,$b$“Gâp mra njŭn khân păng jŭr ma ntŭk bu sreh nkhĭt nâm bu kon biăp, nâm bu biăp nkuăng jêh ri be nkuăng.$b$,true),
('bunong-vn','JER',51,41,null,$b$“Sêsăk lĕ bu sŏk jêh, jêh ri ƀon chrêk ma lơp ma lĕ rngôch neh ntu moh nau dĭng bu sŏk! Babilôn hŏ jêng rngol jêh ta nklang ntil mpôl bunuyh!$b$,true),
('bunong-vn','JER',51,42,null,$b$Dak mƀŭt lip bŭk jêh bri Babilôn; bri nây lĕ nkŭm jêh ma dak rbuh.$b$,true),
('bunong-vn','JER',51,43,null,$b$Ƀon bri Babilôn lĕ jêng ntŭk rngol, du n'gor bri sơh, jêh ri bri hŏng, bri mâu geh bunuyh gŭ ôh, jêh ri mâu geh du huê kon bunuyh văch rgăn ta nây ôh.$b$,true),
('bunong-vn','JER',51,44,null,$b$Gâp mra tâm rmal brah Bel tâm bri Babilôn, jêh ri sŏk ntơt bơh trôm mbung păng moh ndơ păng lĕ rvăn jêh. Phung mpôl băl bunuyh mâu mra yơk mbah đŏng ma păng ôh; mpêr ƀon Babilôn lĕ rlâm jêh.$b$,true),
('bunong-vn','JER',51,45,null,$b$“Luh du hom tă bơh ta nklang păng, Ơ phung ƀon lan gâp! Nchuăt du hom gay tâm rklaih nau rêh khân may! klaih tă bơh nau Yêhôva duh nuih!$b$,true),
('bunong-vn','JER',51,46,null,$b$Lơi ta djôh nuih n'hâm ôh, jêh ri mâu klach lĕ ma nau bu nkoch mbơh tâm bri dak aơ. Yor lah tâm năm aơ geh du nau bu tât mbơh, jêh ri tâm năm pa kơi taơ ăt geh nau bu mbơh êng; mbơh nau bu ƀư djơh tâm n'gor, jêh ri kôranh chiă uănh tâm rdâng ndrăng kôranh chiă uănh êng.$b$,true),
('bunong-vn','JER',51,47,null,$b$Yor ri, aơ, mra tât nar, gâp mra tâm rmal lĕ rup brah ƀon Babilôn, lĕ rngôch bri neh păng geh nau bêk prêng; jêh ri lĕ rngôch bunuyh gŭ tâm nklang păng mra chôt khĭt.$b$,true),
('bunong-vn','JER',51,48,null,$b$Nôk nây, phung klơ trôk jêh ri tâm neh ntu, geh bâr mprơ maak yor ƀon Babilôn; yor lah phung ƀư rai tă bơh dor lơ mra văch tât lơh đah ƀon Babilôn.” Yêhôva lah.$b$,true),
('bunong-vn','JER',51,49,null,$b$“Nâm bu ƀon Babilôn hŏ ƀư jêh ma phung nkhĭt Israel chôt khĭt, ăt tâm ban lĕ, phung nkhĭt Babilôn ăt mra chôt khĭt tâm lam bri neh păng.$b$,true),
('bunong-vn','JER',51,50,null,$b$Phung khân may jêng phung hŏ klaih jêh bơh đao, du hom, lơi hôm gŭ gâng ôh! Tă bơh bri ngai kah gĭt hom ma Yêhôva, jêh ri klân rvê hom ma Yêrusalem.”$b$,true),
('bunong-vn','JER',51,51,null,$b$“Bu ƀư prêng he jêh, yor lah he tăng jêh nau bu nduyh; nau prêng nkŭm jêh muh măt he, yor lah phung bu năch lăp jêh tâm ntŭk kloh ueh ngih Yêhôva.$b$,true),
('bunong-vn','JER',51,52,null,$b$Yor ri, Yêhôva lah: “Aơ, nar mra tât, tơ lah gâp mra phat dôih rup brah păng, phung sôt rmanh mra nter lam bri păng.”$b$,true),
('bunong-vn','JER',51,53,null,$b$Nđâp tơ lah ƀon Babilôn mra hao tât ta trôk, jêh ri nđâp lah păng ƀư ƀon toyh nâp ngăn ta klơ ntŭk prêh kđôi, ăt phung ƀư nau tă bơh gâp prơh hăn mra tât ma păng,” Yêhôva lah.$b$,true),
('bunong-vn','JER',51,54,null,$b$“Iăt hom! Geh nau nter tă bơh ƀon Babilôn! Nteh nau ƀư rai toyh bơh bri phung Kaldê!$b$,true),
('bunong-vn','JER',51,55,null,$b$Yor lah Yêhôva ƀư ma Babilôn jêng rngol, jêh ri ăn rngơt bâr păng drơu drơu tâm nây gŭ rklăk. Phung ƀư rai troh mâu bu n'gô dak toyh, Bu tăng bâr khân păng nter huy;$b$,true),
('bunong-vn','JER',51,56,null,$b$Yor lah nơm ƀư rai văch ƀư jêh ma ƀon Babilôn; bu lĕ nhŭp jêh ta han păng, na păng lĕ klah jêh, yor lah Yêhôva jêng Brah Ndu plơng bôk nau di, tĭng nâm kan păng ƀư, n'hêl nê̆ păng mra plơng ăn nŭm.$b$,false),
('bunong-vn','JER',51,57,null,$b$Hađăch lah, amoh Păng jêng Yêhôva ma phung ta han, lah: Gâp mra ƀư ăn nhŭl ndrănh phung kôranh toyh, lĕ rngôch phung blau mĭn, phung kôranh chiă uănh, phung kôranh ta han nđâp ma phung ta han tâm ban lĕ. Khân păng mra lêt bêch mro, mâu hôm kah rngăl ôh,”$b$,true),
('bunong-vn','JER',51,58,null,$b$Pô aơ nau Yêhôva ma phung ta han lah: “Mpêr ƀon Babilôn nđâp lah huy ngăn, mra klưh rlâm lĕ ƀhiau, mpông pêr nđâp lah prêh ngăn, bu mra su ma ŭnh. Nây yor, nau hŏt ra ah ƀon lan pah kan dơm dam, jêh ri phung mpôl bunuyh bri êng pah kan hŏt rgănh, knŏng prăp ăn ma ŭnh.”$b$,true),
('bunong-vn','JER',51,59,null,$b$Aơ jêng nau ngơi kôranh nơm mbơh lor Y-Yêrêmi ntĭnh ma Y-Sêraya ƀon bu klâu Y-Nêria sau Y-Mahseya tơ lah păng hăn ndrel ma Y-Sêdêkia hađăch bri Yuđa ma bri Babilôn tâm năm rơh puăn păng chiă uănh. Y-Sêraya jêng nơm mât trôm jrô ngih.$b$,true),
('bunong-vn','JER',51,60,null,$b$Y-Yêrêmi chih du ndrom sămƀŭt lĕ rngôch nau mhĭk tât ma ƀon Babilôn, jêng lĕ rngôch nau ngơi hŏ chih jêh nkoch Babilôn.$b$,true),
('bunong-vn','JER',51,61,null,$b$Y-Yêrêmi lah ma Y-Sêraya: “Tơ lah may hŏ tât Babilôn, ăn may uănh lĕ nau ngơi ao,$b$,true),
('bunong-vn','JER',51,62,null,$b$jêh ri lah, ‘Ơ Yêhôva, may hŏ lah jêh mra ƀư rai ƀon aơ, pô ri mâu geh du ntil ndơ mra gŭ tâm păng ôh, mâu geh bunuyh lĕ, n'ho tât ma mpô mpa kŏ mâu geh lĕ jêh ri păng mra jêng rngol ƀa ƀơ n'ho ro.’$b$,false),
('bunong-vn','JER',51,63,null,$b$Tơ lah may uănh hŏ lĕ ndrom sămƀŭt aơ, kât du glo lŭ ndop ma păng, jêh ri mƀăr tâm dak krong Ơphrat.$b$,false),
('bunong-vn','JER',51,64,null,$b$Jêh ri lah, ‘Pô nây ƀon Babilôn mra ngâm tâm ban nây lĕ! Păng mâu mra ntoh du (du dâk) đŏng ôh, yor lah nau mhĭk gâp ƀư mra tât ma păng. Jêh ri phung ƀon lan păng mra cha lôt.’ ” Nau ngơi Y-Yêrêmi dŭt aơ.$b$,false),
('bunong-vn','JER',52,1,null,$b$Tơ lah Y-Sêdêkia ntơm ƀư hađăch, geh bar jât ma nguay năm; chiă uănh jât ma nguay năm ta ƀon Yêrusalem. Me hađăch amoh jêng H'Hamutal kon bu ur Y-Yêrêmi ƀon Lipna.$b$,true),
('bunong-vn','JER',52,2,null,$b$Păng ƀư nau nhĭm ta năp măt Yêhôva nâm bu lĕ rngôch nau Y-Jêhôjakim ƀư jêh.$b$,false),
('bunong-vn','JER',52,3,null,$b$Nanê̆ yor nau Yêhôva nuih ma nau mhĭk bu ƀư ta ƀon Yêrusalem jêh ri n'gor bri Yuđa, păng mprơh phung nây du bơh ta năp păng. Y-Sêdêkia tâm rdâng đah Babilôn.$b$,false),
('bunong-vn','JER',52,4,null,$b$Tâm năm rơh sĭn nôk păng chiă uănh nar jât, khay jât, geh Y-Nêbukatnetsar, hađăch Babilôn tât ndrel ma lĕ rngôch phung ta han păng lơh Ƀon Yêrusalem. Khân păng nchueng ƀon ƀư mpêr văr jŭm nây, jêng ntŭk dơi tâm lơh đah ƀon Yêrusalem.$b$,true),
('bunong-vn','JER',52,5,null,$b$Pô ri bu nchueng ƀư ma ƀon kŏ tât năm jât ma nguay Hađăch Sêdêkia chiă uănh.$b$,false),
('bunong-vn','JER',52,6,null,$b$Ta nar sĭn khay puăn, nau ât ji ngot hâu ngăn tâm ƀon, kŏ tât mâu hôm geh ndơ sông sa ma phung ƀon lan.$b$,false),
('bunong-vn','JER',52,7,null,$b$Jêh ri mpêr ƀon lĕ bu ƀư klưh rlâm jêh; lĕ rngôch phung ta han nchuăt du dôl bri măng tĭng trong mpông pêr vah vang bar đah mpêr êp n'gar kao hađăch, dôl phung Kaldê gŭ jŭm ƀon. Khân păng hăn rlet Arabah.$b$,false),
('bunong-vn','JER',52,8,null,$b$Ƀiă lah phung ta han Kaldê tĭng hađăch Sêdêkia jêh ri ban păng ta neh lâng Yêrêkô; jêh ri lĕ rngôch phung ta han păng tâm nkhah bơh păng jêh ri nchuăt pru êng êng.$b$,false),
('bunong-vn','JER',52,9,null,$b$Pô ri phung ta han Kaldê nhŭp hađăch, njŭn leo păng ma hađăch Babilôn ta ƀon Ribla tâm bri Hamat, ntŭk nây hađăch Babilôn phat dôih păng.$b$,false),
('bunong-vn','JER',52,10,null,$b$Hađăch Babilôn nkhĭt phung kon bu klâu Y-Sêdêkia tra năp măt păng, jêh ri nkhĭt lĕ rngôch phung kôranh n'gor bri Yuđa ta ƀon Ribla.$b$,false),
('bunong-vn','JER',52,11,null,$b$Păng rlek lơi găr măt Y-Sêdêkia, jêh ri kât ô băl ma rse rvăk, jêh ri hađăch Babilôn njŭn leo Y-Sêdêkia ma bri Babilôn, jêh ri krŭng ô băl kŏ tât nar păng khĭt.$b$,false),
('bunong-vn','JER',52,12,null,$b$Tâm khay prăm ta nar jât khay nây jêng năm rơh jât ma sĭn Hađăch Nêbukatnetsar chiă uănh bri Babilôn$b$,true),
('bunong-vn','JER',52,13,null,$b$Y-Nêbukatnetsar kôranh ta han ma phung gak hađăch Babilôn lăp tâm ƀon Yêrusalem lĕ rngôch ngih toyh ŭnh sa lĕ.$b$,false),
('bunong-vn','JER',52,14,null,$b$Lĕ rngôch phung ta han Kaldê hăn ndrel ma kôranh ta han njrăng hađăch ƀư rlâm lĕ rngôch mpêr jŭm ƀon Yêrusalem.$b$,false),
('bunong-vn','JER',52,15,null,$b$Y-Nebusaradan kôranh ta han gak njrăng hađăch njŭn leo jêng bu nă ƀă phung o ach lơn jêh ri phung ƀon lan hôm klen gŭ tâm ƀon Yêrusalem, jêh ri phung du ntŭng gŭ mpeh ma hađăch Babilôn, ndrel ma lĕ rngôch phung blau rhăk hôm klen.$b$,true),
('bunong-vn','JER',52,16,null,$b$Ƀiă lah Y-Nebusaradan kôranh ta han ma phung gak njrăng hađăch lơi ƀa ƀă phung o ach ngăn hôm gŭ tâm n'gor bri, gay ăn tâm play kriăk ƀâu jêh ri ƀư mir.$b$,false),
('bunong-vn','JER',52,17,null,$b$Jrŏng gâng kông tâm ngih Yêhôva, thŭng dak toyh ƀư ma kông nđâp ma jâng păng gŭ tâm trôm ngih Yêhôva, phung Kaldê châm hăch rhên jêh ri ndjôt leo lĕ kông nây leo ma bri Babilôn.$b$,true),
('bunong-vn','JER',52,18,null,$b$Khân păng sŏk glah, ndroh, nglăm, gri grưng, n'hoi ndơ nkhĭt ŭnh jrêng, ngan prăp si ƀâu kah, jêh ri lĕ rngôch khăl ngan kông bu dŏng mprơ ma kan ngih brah;$b$,false),
('bunong-vn','JER',52,19,null,$b$kôranh ta han gak njrăng hađăch nchuăn lĕ ƀhiau âk ngan jê̆, ndơ dơ sa ônh, ngan grưng, glah, jâng jrêng, ndơ su si ƀâu kah, khăl nglŭng dơm ndơ nhhơr nhêt, moh ndơ bu ƀư ma mah sŏk mah ro, ndơ bu ƀư prăk sŏk prăk ro.$b$,false),
('bunong-vn','JER',52,20,null,$b$Bi ma bar mlâm jrŏng gâng (meh), thŭng dak toyh, jât ma bar mlâm rup ndrôk nkuăng ƀư ma kông tâm dâng thŭng dak toyh ndơ hađăch Salômôn ƀư jêh ma ngih Yêhôva, kông ma lĕ rngôch ndơ nây bu mâu dơi rnhueh ôh.$b$,false),
('bunong-vn','JER',52,21,null,$b$Bi ma jrŏng gâng, jong du mlâm jrŏng gâng jât ma pham hăt, rvang mlâm păng jât ma bar hăt, mbâl păng puăn nglau ti, geh trôm sŭng ta nklang.$b$,false),
('bunong-vn','JER',52,22,null,$b$Bi ma chiông păng ƀư ma kông jong prăm hăt; văr jŭm geh ndơ tanh sră jal jêh ri rup pom gra nat, lĕ rngôch ƀư ma kông da dê. Jrŏng gâng rơh bar bu ƀư tâm ban lĕ, geh nđâp ma rup pom gra nat.$b$,false),
('bunong-vn','JER',52,23,null,$b$Geh sĭn jât ma prao rup play pom gra nat puăn pŭng, lĕ rngôch rup play pom gra nat geh du rhiăng mlâm ta văr jŭm ndơ tanh sră jal.$b$,false),
('bunong-vn','JER',52,24,null,$b$Kôranh ta han gak njrăng hađăch nhŭp Y-Sêraya kôranh ƀư brah toyh Y-Sôphônia groi kôranh ƀư brah, jêh ri nđâp pe nuyh gak mpông sâng ngih brah;$b$,true),
('bunong-vn','JER',52,25,null,$b$jêh ri păng nhŭp tă tâm ƀon toyh du huê kôranh bu char uănh ta han tâm lơh, jêh ri pơh nuyh tâm mpôl tâm chră ndrel hađăch bu saơ tâm ƀon; kôranh chih sămƀŭt ma kôranh ta han nơm kơp phung ƀon lan tâm n'gor bri; jêh ri prao jât nuyh ƀon lan n'gor bri nây bu mâp tâm nklang ƀon toyh.$b$,false),
('bunong-vn','JER',52,26,null,$b$Y-Nebusaradan kôranh ta han gak njrăng hađăch nhŭp khân ô băl jêh ri njŭn leo khân ô băl ma hađăch Babilôn ta ƀon Ribla.$b$,false),
('bunong-vn','JER',52,27,null,$b$Hađăch Babilôn nkhĭt khân ô băl ta ƀon Ribla tâm bri Hamat. Nây yơh bu veng phung Yuđa leo jêng bu nă tâm n'gor bri êng.$b$,false),
('bunong-vn','JER',52,28,null,$b$Aơ jêng rnoh phung ƀon lan Y-Nêbukatnetsar njŭn jêng bună: Tâm năm rơh pơh, pe rbăn bar jât ma pe phung Yuđa;$b$,true),
('bunong-vn','JER',52,29,null,$b$tâm năm rơh jât ma pham rnôk Y-Nêbukatnetsar chiă uănh păng njŭn leo jêng bună tă bơh ƀon Yêrusalem pham rhiăng pe jât ma nuyh;$b$,false),
('bunong-vn','JER',52,30,null,$b$tâm năm rơh bar jât ma pe Y-Nêbukatnetsar chiă uănh, Y-Nêbusaradan kôranh ta han gak njrăng hađăch njŭn leo jêng bună pơh rhiăng puăn jât ma prăm nuyh phung Yuđa; rnoh lĕ rngôch puăn rbăn prao rhiăng nuyh.$b$,false),
('bunong-vn','JER',52,31,null,$b$Tâm năm rơh pe jât ma pơh rnôk Y-Jêhôjakin hađăch Yuđa jêng bună, tâm khay jât ma bar, ta nar bar jât ma prăm, Y-Êvil-Merôdak, hađăch Babilôn tâm năm ntơm chiă uănh, mƀơk Y-Jêhôjakin hađăch Yuđa ăn luh tă bơh ndrung;$b$,true),
('bunong-vn','JER',52,32,null,$b$jêh ri păng ngơi ueh ma ô băl, jêh ri ăn ô băl rnơl gŭ ta klơ lơn ma phung hađăch êng ndrel ma păng tâm ƀon Babilôn.$b$,false),
('bunong-vn','JER',52,33,null,$b$Pô ri Y-Jêhôjakin doh kho ao păng jêng bună.$b$,false),
('bunong-vn','JER',52,34,null,$b$Dôl păng gŭ rêh ăp nar păng sông sa ƀa ƀơ ndrel ma hađăch; bi prăk bu ƀơk păng, hađăch ăn ma păng tĭng nâm tŏng ma ăp nar tât nar păng khĭt.$b$,false);
