('bunong-vn','JER',7,16,1,'heading',$b$Brah Ndu Ji Nuih Ma Nau Mbah Rup Brah$b$),
('bunong-vn','JER',7,21,2,'heading',$b$Nau Tâm Rmal Yor Phung Yuđa Tâm Rdâng$b$),
('bunong-vn','JER',8,1,0,'heading',$b$Nau Ngo Nkum Phung Yuđa$b$),
('bunong-vn','JER',8,4,1,'heading',$b$Nau Tih Jêh Ri Nau Phat Dôih$b$),
('bunong-vn','JER',8,18,2,'heading',$b$Nau Nhĭm Vơl Ma Bri Yuđa Jêh Ri Ƀon Yêrusalem$b$),
('bunong-vn','JER',9,1,0,'heading',$b$Nau Y-Yêrimi Nđêng$b$),
('bunong-vn','JER',9,12,1,'heading',$b$Brah Ndu Thăm Ƀư Rai Jêh Ri Mprơh Bơh Bri$b$),
('bunong-vn','JER',9,23,2,'heading',$b$Nau Gĭt Năl Brah Ndu Jêng Nau Chrêk Lơp Ma Bunuyh$b$),
('bunong-vn','JER',10,1,0,'heading',$b$Brah Ndu Jêh Ri, Phung Rup Brah Nau Ƀư Rai Yêrusalem$b$),
