insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','LAM',1,1,null,$b$Ƀon aơ kăl e âk ngăn bunuyh, uănh aƀaơ gŭ êng du huê! Kăl e ƀư toyh ta nklang mpôl băl bunuyh! Aƀaơ păng jêng nâm bu bu ur ndrô, Kăl e jêng hađăch bu ur ta nklang âk bri dak, Aƀaơ ri jêng nkhơng dĭk bu.$b$,true),
('bunong-vn','LAM',1,2,null,$b$Păng nhĭm dôl măng bêng ma nau rngot, dak măt hoch tât ta trôm bom păng; ta nklang lĕ rngôch phung rŏng ma păng, mâu geh ôh nơm bonh păng; lĕ rngôch phung mĭt jiăng păng ƀlăch ƀlêr ma păng, jêh ri jêng rlăng ma păng.$b$,true),
('bunong-vn','LAM',1,3,null,$b$Phung Yuđa lĕ hăn ƀư bună jêh, dơn rêh ni jêh ri jêng dĭk ma nau hŏt rgănh păng gŭ ta nklang phung mpôl băl bunuyh, ƀiă lah mâu saơ ntŭk rlu ôh; phung tĭng păng lĕ ban jêh păng ta ntŭk tâm nklang nau rêh ni.$b$,true),
('bunong-vn','LAM',1,4,null,$b$Lĕ trong hăn ma ƀon Siôn rngot klâng ngăn yor lah mâu geh nơm hăn ma năng tâm nal jêh; lĕ rngôch mpông pêr păng lĕ jêng rngol; phung kôranh ƀư brah păng nter vơl; bu ur druh tang tat păng rngot klâng. Jêh ri păng nơm rngot ngăn$b$,true),
('bunong-vn','LAM',1,5,null,$b$Phung rlăng păng lĕ jêng kôranh ma păng, phung rlăng păng geh nau chăt hao, yor lah Yêhôva ăn păng dơn nau rêh ni yor nau tih păng âk ir; phung kon păng lĕ hăn ƀư bună ta năp phung rlăng păng.$b$,false),
('bunong-vn','LAM',1,6,null,$b$Kon bu ur ƀon Siôn lĕ roh jêh nau rnam păng; phung kôranh păng jêng nâm bu jun mâu geh gơ̆ ndrêch ôh; khân păng dâk hăn mâu geh nau ktang ôh ta năp phung tĭng khân păng.$b$,true),
('bunong-vn','LAM',1,7,null,$b$Tâm nar nau rêh ni păng nsong mblêng, ƀon Yêrusalem kah gĭt ma lĕ rngôch ndơ khlay păng, ndơ păng geh ntơm bơh rô̆ sa ơm. Tơ lah phung ƀon lan păng tŭp tâm ti phung rlăng, Mâu geh nơm kơl păng ôh, Phung rlăng uănh ma păng jêh ri mưch rmot ma nau păng tŭp.$b$,true),
('bunong-vn','LAM',1,8,null,$b$Ƀon Yêrusalem ƀư tih glăm jêh, yor nây păng jêng ƀơ̆ . Lĕ rngôch mbu nơm yơk ma păng lor sa ơm Aƀaơ ri tâm rmot ma păng, Yor lah khân păng saơ nau rhôk păng; Păng nơm vơl êng, plơ̆ pôn muh măt păng.$b$,true),
('bunong-vn','LAM',1,9,null,$b$Nau ƀơ̆ ƀơch păng krêp tâm nah bŭt păng; păng mâu mĭn ôh ma nau mhĭk mra tât ma păng! Yor nây nau păng lĕ tŭp jêng mha ngăn, Mâu geh nơm bonh leng păng ôh! Hơi Yêhôva, uănh hom ma nau rêh ni gâp, Yor lah phung rlăng hŏ yơk n'hao êng ma păng nơm ƀư toyh.$b$,true),
('bunong-vn','LAM',1,10,null,$b$Phung rlăng hŏ yơr ti khân păng ŭch sŏk lĕ rngôch ndơ ueh păng; Yor lah păng hŏ saơ jêh mpôl bunuyh Bunăch lăp tâm ntŭk ueh păng. Phung nây may hŏ buay: Mâu dơi ăn lăp ôh tâm nau tâm rƀŭn may.$b$,true),
('bunong-vn','LAM',1,11,null,$b$Lĕ rngôch phung ƀon lan păng nter vơl dôl khân păng ŭch geh ndơ sông sa; khân păng tâm rgâl drăp ndơ khân păng gay geh ndơ sông sa, gay ăn mpay ma huêng khân păng. Hơi Yêhôva, “uănh hom, Yor lah bu tâm rmot ma gâp!$b$,true),
('bunong-vn','LAM',1,12,null,$b$Hơi lĕ rngôch bunuyh hăn rgăn ta nây, khân may mâu chrê ôh hĕ? Uănh sek hom gĭt geh lĕ nau rngot rvê nâm bu nau rngot rvê gâp, nau bu ƀư jêh ma gâp. Nau rêh ni Yêhôva hŏ ƀư jêh ma gâp ta nôk nar Păng ji nuih.$b$,true),
('bunong-vn','LAM',1,13,null,$b$Păng hŏ ntŭp ŭnh tă ntŭk prêh klơ, ŭnh nây lăp tâm nting nđăng gâp; jêh ri dơi. Păng hŏ nthăng nhuăl tâm dâng jâng gâp, ƀư ăn gâp plơ̆ sĭt pa kơi, Păng hŏ ƀư ăn gâp khĭt huăr ăp nar kŏ tât siăr-rvĕn.$b$,true),
('bunong-vn','LAM',1,14,null,$b$Bu sŏk nau tih gâp njêng mâng mbăk ma gâp; Păng kât ndrel ta ti. Bu rkleng lĕ ndơ jâk ăn ta trô ko gâp, Păng ƀư djoh nau dăng ktang gâp. Yêhôva hŏ jao jêh tâm ti khân păng, ƀiă lah gâp mâu dơi tâm rdâng ôh.$b$,true),
('bunong-vn','LAM',1,15,null,$b$Yêhôva hŏ ƀư ăn ta han lơh jêng dơm dam ta nklang gâp Păng hŏ rgum mpôl âk tâm rdâng đah gâp, gay jot plên phung bu klâu ndăm gâp; Yêhôva hŏ jot jêh bu ur druh tang-tat phung Yuđa, nâm bu tâm sưng bu kĭn dak play kriăk ƀâu$b$,true),
('bunong-vn','LAM',1,16,null,$b$Yor nây gâp nhĭm nhhiăng, gâp hor âk dak măt; nơm bonh leng gâp gŭ ngai ma gâp, mâu geh nơm n'hao nuih gâp ôh; phung kon gâp rêh ni, yor lah lĕ dơi phung rlăng jêh.”$b$,false),
('bunong-vn','LAM',1,17,null,$b$Ƀon Siôn lĕ yơr ti jêh, ƀiă lah mâu geh nơm bonh long păng ôh; Yêhôva ntĭnh jêh nau tâm rdâng đah phung Yakôb, gay ma phung chiau meng păng jêng rlăng păng; ƀon Yêrusalem lĕ jêng jêh du ntil ndơ ƀơ̆ ta nklang khân păng.$b$,true),
('bunong-vn','LAM',1,18,null,$b$“Yêhôva jêng sŏng, yor lah gâp hŏ tâm rdâng jêh đah nau păng ngơi. Iăt hom, Hơi lĕ rngôch phung ƀon lan, uănh hom ma nau rêh ni gâp; phung bu ur druh tang-tat jêh ri phung bu klâu ndăm gâp lĕ hăn ƀư bună jêh.$b$,true),
('bunong-vn','LAM',1,19,null,$b$Gâp kuăl phung rŏng ma gâp, ƀiă lah khân păng ndơm jêh gâp; phung kôranh ƀư brah jêh ri phung bu bŭnh bu ranh gâp rai lôch jêh tâm ƀon, dôl khân păng joi ndơ sông sa gay geh đŏng nau mpay ma huêng khân păng.$b$,true),
('bunong-vn','LAM',1,20,null,$b$Uănh hom, Hơi Yêhôva, yor lah gâp jêng jêh ri, huêng gâp geh nau uh ah, nuih n'hâm gâp geh nau tăng tâm trôm, yor lah gâp jêng jêh nơm tâm rdâng ngăn. Tâm trong sâng geh pêih đao ăn bu nhĭm nhhiăng, tâm ngih vâl geh knŏng nau khĭt.$b$,true),
('bunong-vn','LAM',1,21,null,$b$Bu tăng jêh nau gâp nter vơl, ƀiă lah mâu geh ôh nơm bonh leng gâp. Lĕ rngôch phung rlăng gâp tăng jêh nau uh ah gâp, khân păng maak yor may ƀư jêh nau nây. Nar may hŏ mbơh, may mra ƀư ăn tât! khân păng mra jêng tâm ban gâp lĕ!$b$,true),
('bunong-vn','LAM',1,22,null,$b$Ăn lĕ rngôch nau mhĭk khân păng ƀư tât ta năp măt may, jêh ri ƀư hom ma khân păng nâm bu may ƀư jêh ma gâp, yor lĕ rngôch nau tih gâp; yor lah gâp nter vơl ngăn, jêh ri nuih n'hâm gâp djoh jêh.”$b$,true),
('bunong-vn','LAM',2,1,null,$b$Mâm Yêhôva ji nuih, ndâr tŭk nkâm ndâp kon bu ur Siôn? Păng hŏ nklơ̆ lơi nau ueh uĭn Israel tă klơ trôk tŭp tâm neh. Tâm nar ji nuih, Păng mâu hôm kah gĭt ôh ma ndơ păng chrong jâng.$b$,true),
('bunong-vn','LAM',2,2,null,$b$Yêhôva ƀư rai jêh mâu geh nau yô̆ ôh lĕ rngôch ntŭk phung Yakôb gŭ, tâm nau păng ji nuih păng ƀư rlâm lơi pôih nâp kon bu ur Yuđa; păng nklơ̆ jêh ta neh ma nau ƀư bêk prêng ƀon bri hađăch jêh ri phung kôranh chiă uănh păng$b$,true),
('bunong-vn','LAM',2,3,null,$b$Tâm nau ji nuih, Păng koh lơi nke phung Israel. Păng hŏ rhuăt ti pa ma tă bơh ta năp măt phung rlăng. Păng hŏ ƀư rai jêh bri Yakôb nâm bu ŭnh hit sa lĕ rngôch ndơ gŭ jŭm.$b$,false),
('bunong-vn','LAM',2,4,null,$b$Păng van jêh na păng nâm bu du huê nuyh rlăng, ma ti pa ma păng gay ƀư nâm bu rlăng; păng hŏ nkhĭt lĕ rngôch ndơ ueh măt hên uănh. Tâm ngih bok kon druh Siôn, Păng nkhŭt nau păng ji nuih nâm bu ŭnh.$b$,true),
('bunong-vn','LAM',2,5,null,$b$Yêhôva jêng nâm bu du huê rlăng, păng ƀư rai jêh Israel; ƀư rai lĕ rngôch ngih hađăch păng, ƀư rai lĕ ƀhiau pôih păng nâp ngăn; păng ƀư ăn kon druh Yuđa lơ âk nau rngot klâng jêh ri nhhiăng nhĭm.$b$,true),
('bunong-vn','LAM',2,6,null,$b$Păng nklơ̆ ndưp ma nau ktang nâm bu ndưp tâm n'gar trao; păng ƀư rai lơi ntŭk păng prăp ma nau tâm rƀŭn; Yêhôva ăn jêh ƀon Siôn chuêl nau nhêt sa jêh ri nar Saƀat hŏ tâm nal jêh, jêh ri ma nau păng ji nuih biănh hâu ngăn păng dun jêh hađăch jêh ri kôranh ƀư brah.$b$,true),
('bunong-vn','LAM',2,7,null,$b$Păng hŏ cha lơi jêh nơng ƀư brah, jêh ri lơi jêh jrô kloh ueh păng; păng hŏ jao jêh mpêr ngih hađăch păng ma ti phung rlăng, phung nây ƀư drơu drơu tâm ngih Yêhôva nâm bu tâm nar năng tâm nal jêh.$b$,true),
('bunong-vn','LAM',2,8,null,$b$Yêhôva hŏ ŭch mĭn ƀư rai mpêr ƀon kon druh Siôn; păng hŏ nthăng jêh rse veh păng, păng mâu krŏt ôh ti ma nau ƀư rai; Păng ƀư ma mpêr king jêh ri mpêr ƀon nhhiăng nhĭm, Rngot klâng ndrel.$b$,true),
('bunong-vn','LAM',2,9,null,$b$Mpông pêr păng rlâm jêh ta neh; păng ƀư rai jêh ri nkêch lơi mâng rnăng păng. Hađăch jêh ri phung kôranh păng gŭ ta nklang mpôl băl bunuyh; mâu hôm geh nau vay ôh, phung kôranh nơm mbơh lor păng mâu hôm tâm saơ ôh tă bơh Yêhôva.$b$,true),
('bunong-vn','LAM',2,10,null,$b$Phung bu bŭnh bu ranh kon bu ur ƀon Siôn gŭ iăt săk răk klăk gŭ tâm neh; Bôk pot neh muy, săk jăn nsoh ƀau mhay. Phung bu ur druh tang-tat ƀon Yêrusalem kŭnh bôk tât ta neh.$b$,true),
('bunong-vn','LAM',2,11,null,$b$Măt gâp lĕ hêr jêh yor nau nhĭm, tâm huêng gâp uh ah ngăn; nuih n'hâm gâp lĕ nkhŭt tâm neh. Yor lah nau ƀư rai phung ƀon lan gâp, yor lah phung kon se jê̆ jêh ri oh bê khĭt huăr tâm trong ƀon.$b$,true),
('bunong-vn','LAM',2,12,null,$b$Khân păng lah đah me păng, “Ta ntŭk joi phe jêh ri dak kriăk ƀâu?” Tơ lah lĕ huăr jêh nâm bu bunuyh sôt rmanh, tâm trong ƀon; Jêh ri tơ lah khân păng lĕ tăch n'hâm ta ntang ntơh me păng.$b$,true),
('bunong-vn','LAM',2,13,null,$b$Mâm gâp dơi lah ma may? Moh ndơ gâp sŏk gay tâm rđĭl đah may gay bonh leng may, Hơi bu ur druh tang tat ƀon Siôn? Nau ƀư rai may toyh nâm bu dak mƀŭt. Mbu nơm dơi ƀư bah may.$b$,true),
('bunong-vn','LAM',2,14,null,$b$Phung kôranh nơm mbơh lor may saơ jêh nau tâm saơ mƀruh jêh ri ndơm; khân păng mâu mâp tâm mpơl ôh nau kue may, gay leo bună plơ̆ sĭt. Ƀiă lah tâm saơ jêh ma may nau tâm mpơl mƀruh jêh ri ndơm$b$,true),
('bunong-vn','LAM',2,15,null,$b$Lĕ rngôch bunuyh rgăn rŏ trong tap ti yor may, khân păng nsŭch jêh ri rteh bôk yor kon bu ur ƀon Yêrusalem; Lah pô aơ: “Di lĕ aơ jêng ƀon bu ntơ Ƀon ueh reh nanê̆ ngăn, nau răm rhơn ma lĕ rngôch neh ntu lĕ?$b$,false),
('bunong-vn','LAM',2,16,null,$b$Lĕ rngôch phung rlăng may nduyh may, hĭk sêk ma may, rdâng đah may, khân păng nsŭch, rchiăt sêk, Khân păng nter lah: “He ƀư rai jêh păng! Aơ di ngăn jêng nar he gŭ kâp, he hŏ joi Hŏ saơ jêh, aƀaơ tât ngăn jêh!”$b$,true),
('bunong-vn','LAM',2,17,null,$b$Yêhôva ƀư ngăn jêh nau păng ŭch ƀư; ăn tât jêh nau păng thăm, tĭng nâm păng ntĭnh kăl e hŏ jŏ ngăn; Păng hŏ n'glưh lơi may mâu geh nau yô̆ ôh. Păng hŏ ăn jêh phung rlăng maak yor ma may, jêh ri n'hao nau ktang phung rlăng may.$b$,true),
('bunong-vn','LAM',2,18,null,$b$Nuih n'hâm phung ƀon lan nter huy ma Yêhôva! Hơi pêr ƀon kon bu ur Siôn, Ăn dak măt may hor nar măng nâm bu-hoch dak krong! Lơi may rlu ôh lơi ăn ôh măt may nhêp$b$,true),
('bunong-vn','LAM',2,19,null,$b$Dâk hom nhĭm nter dôl bri măng, ntơm bơh bu gak bôk măng! Nkhŭt nuih n'hâm may nâm bu dak ta năp Yêhôva! yơr ti may ma păng gay dăn nau rêh ma phung kon jê̆ may, khân păng huăr yor ji ngot ta njônh trong ƀon toyh.$b$,false),
('bunong-vn','LAM',2,20,null,$b$“Hơi Yêhôva, dăn may mêt uănh! Mbu may hŏ ƀư nâm bu pô nây? Geh lĕ me păng sa lơi kon păng nơm, Nâm bu ntŭk kon păng ut ra-u tâm ti păng? Kôranh ƀư brah nđâp kôranh nơm mbơh lor, geh lĕ bu nkhĭt tâm jrô kloh ueh Yêhôva?$b$,true),
('bunong-vn','LAM',2,21,null,$b$Phung mom ndăm jêh ri phung bu ranh lâng bêch mbrach ro tâm neh muy rŏ trong sâng; phung bu ur druh jêh ri bu klâu ndăm gâp cha lôt khĭt ma chiông đao. May nkhĭt lơi ta nar may ji nuih ma khân păng, nkhĭt mâu geh nau yô̆ ôh.$b$,true),
('bunong-vn','LAM',2,22,null,$b$May ăn tât nau ƀư nkrit jŭm gâp, nâm bu may jă bunuyh ma nau di năng tâm nal jêh; ta nar Yêhôva ji nuih mâu geh nơm klaih, mâu geh lĕ nơm hôm e rêh; Phung gâp hŏ tŭ ta blu jêh ri pêt rong tât toyh, lĕ rngôch hŏ phung rlăng nkhĭt jêh.”$b$,true),
('bunong-vn','LAM',3,1,null,$b$Gâp jêng du huê bunuyh hŏ saơ jêh nau rêh ni luh tă mâng nau Păng ji nuih.$b$,true),
('bunong-vn','LAM',3,2,null,$b$Păng hŏ leo gâp ăn gâp chuat hăn tâm nau ngo, mâu hăn ôh tâm nau ang.$b$,true),
('bunong-vn','LAM',3,3,null,$b$N'hêl nanê̆ păng yơr ti păng tâm rdâng đah gâp ƀa-ƀơ âk tơ̆ .$b$,true),
('bunong-vn','LAM',3,4,null,$b$Păng hŏ ƀư siăr nglay puăch jêh ri ntâu hêk rai, jêh ri hŏ nkêch lơi nting gâp.$b$,true),
('bunong-vn','LAM',3,5,null,$b$Păng hŏ nchueng gâp jêh ri nkŭm gâp ma nau rngot jêh ri nau rêh ni.$b$,true),
('bunong-vn','LAM',3,6,null,$b$Gay ăn gâp gŭ tâm ntŭk ngo klĕng, nâm bu bunuyh khĭt hŏ jŏ năm.$b$,true),
('bunong-vn','LAM',3,7,null,$b$Păng ƀư mpêr jŭm gâp pô ri gâp mâu dơi du ôh; păng hŏ kât jêh gâp ma rse rvăk jâk ngăn.$b$,true),
('bunong-vn','LAM',3,8,null,$b$Nđâp tơ lah gâp kuăl vơh vơl dăn nau kơl păng dun mâu iăt ôh nau gâp mbơh sơm$b$,true),
('bunong-vn','LAM',3,9,null,$b$Păng ƀư bâp trong gâp ma lŭ bu hŏ trah jêh, ăn trong gâp jêng kue.$b$,false),
('bunong-vn','LAM',3,10,null,$b$Păng ƀư đah gâp nâm bu du mlâm kau moch rmiăt kăp, nâm bu yau mŭr rmiăt tâm ntŭk ndâp.$b$,true),
('bunong-vn','LAM',3,11,null,$b$Gay ăn gâp nhhơt trong jêh ri sa hêk gâp hăch rhên; păng ăn gâp gŭ êng.$b$,true),
('bunong-vn','LAM',3,12,null,$b$Păng hŏ van na păng jêh ri săch gâp ƀư mpot ma hăr păng.$b$,true),
('bunong-vn','LAM',3,13,null,$b$Păng hŏ pănh hăr bơh dĭng kăm păng lăp geh ta klơm leh gâp;$b$,true),
('bunong-vn','LAM',3,14,null,$b$gâp jêng ndơ phung ƀon lan mưch rmot khân păng sŏk gâp ƀư nau mprơ ăp nar.$b$,false),
('bunong-vn','LAM',3,15,null,$b$Păng hŏ ăn gâp bêng ma nau rngot, ăn gâp hơm ma gŭn rđang.$b$,true),
('bunong-vn','LAM',3,16,null,$b$Păng hŏ sŏk lŭ ƀư rŭng sêk gâp; jêh ri jot plên gâp tâm ndruyh neh.$b$,true),
('bunong-vn','LAM',3,17,null,$b$May rdu huêng gâp ngai đah nau đăp mpăn, gâp hŏ chuêl jêh nau ueh lăng.$b$,true),
('bunong-vn','LAM',3,18,null,$b$Pô ri gâp lah, “Nau ktang jêh ri nau gâp kâp gân lĕ roh jêh.”$b$,true),
('bunong-vn','LAM',3,19,null,$b$Gâp kah gĭt ma nau rêh ni jêh ri nau gâp nsong mblêng, jêng gŭn rđang jêh ri play măt tăng.$b$,true),
('bunong-vn','LAM',3,20,null,$b$Huêng gâp hôm kah gĭt ƀa ƀơ nau nây, jêh ri huêng gâp lĕ rngôch rdja.$b$,true),
('bunong-vn','LAM',3,21,null,$b$Gâp kah gĭt nau nây, ri mơ geh nau kâp gân.$b$,true),
('bunong-vn','LAM',3,22,null,$b$Nây jêng nau ueh bơh Yêhôva, hên mâu mâp nau rai yot ôh. Yor lah nau May yô̆ klâng mâu blau lôch ôh.$b$,true),
('bunong-vn','LAM',3,23,null,$b$Ăp ôi dơi jêng mhe mro, nau răp jăp May jêng toyh ngăn.$b$,true),
('bunong-vn','LAM',3,24,null,$b$“Yêhôva jêng drăp gâp ndơn,” huêng gâp lah, “pô ri gâp mra kâp gân păng.”$b$,true),
('bunong-vn','LAM',3,25,null,$b$Yêhôva jêng nau ueh ăn ma phung kâp gân păng, ăn ma huêng tĭng joi păng.$b$,true),
('bunong-vn','LAM',3,26,null,$b$Ueh ngăn yơh mbu nơm gŭ klăk klêm kâp gân nau tâm rklaih bơh Yêhôva.$b$,true),
('bunong-vn','LAM',3,27,null,$b$Ueh ngăn yơh ma bunuyh anh mâng mbăk dôl hôm e kon se.$b$,true),
('bunong-vn','LAM',3,28,null,$b$Di ngăn, ăn păng gŭ êng du huê jêh ri gŭ khưm, yor lah Yêhôva hŏ kât jêh mâng mbăk ta păng.$b$,true),
('bunong-vn','LAM',3,29,null,$b$Ăn păng chŭn muh măt tâm ndruyh neh! klăp lah geh đŏng nau kâp gân.$b$,true),
('bunong-vn','LAM',3,30,null,$b$Păng ăn trô bom păng ma bu tap, jêh ri dơn nau bu gơm mưch.$b$,true),
('bunong-vn','LAM',3,31,null,$b$Yor lah Yêhôva mâu cha lơi ƀa ƀơ n'ho ro ôh.$b$,true),
('bunong-vn','LAM',3,32,null,$b$Nđâp tơ lah păng hŏ ƀư ăn rngot rvê, hôm e mra geh nau yô̆ klâng tĭng nau ueh păng rmeh ler.$b$,true),
('bunong-vn','LAM',3,33,null,$b$Yor lah nau nây, mâu di ôh Păng kơnh ŭch ƀư ăn ma phung kon bunuyh rêh ni jêh ri rngot klâng.$b$,true),
('bunong-vn','LAM',3,34,null,$b$Tơ lah bu ŭch jot plên lĕ rngôch bunuyh bu krŭng tâm bri neh.$b$,true),
('bunong-vn','LAM',3,35,null,$b$Tơ lah ŭch dun nau sŏng ma du huê bunuyh ta năp Nơm Ta Klơ Lơn,$b$,true),
('bunong-vn','LAM',3,36,null,$b$Tơ lah ŭch ndơm bu ăn roh lơi nau di ma du huê bunuyh,$b$,false),
('bunong-vn','LAM',3,37,null,$b$Yêhôva mâu dơn ôh nau Yêhôva ntrŭnh, mbu dơi ntĭnh jêh ri nau nây dơi tât ngăn?$b$,false),
('bunong-vn','LAM',3,38,null,$b$Mâu di hĕ bơh trôm mbung Nơm Ta Klơ Lơn luh du nau ueh jêh ri nau mhĭk?$b$,true),
('bunong-vn','LAM',3,39,null,$b$Moh yor du huê bunuyh gŭ rêh ngơi ƀrôk ma nau tâm rmal ma nau tih?$b$,true),
('bunong-vn','LAM',3,40,null,$b$Ăn he nơm lŏng nâl sek uănh trong he, jêh ri plơ̆ sĭt ma Yêhôva!$b$,true),
('bunong-vn','LAM',3,41,null,$b$Ăn he joi Brah Ndu tâm trôk jêh ri mbơh sơm ma păng:$b$,true),
('bunong-vn','LAM',3,42,null,$b$“Hên ƀư tih jêh ri tâm rdâng jêh, jêh ri may mâu yô̆ an ôh.$b$,false),
('bunong-vn','LAM',3,43,null,$b$May sŏk nau ji nuih nkŭm may nơm jêh ri tĭng jêh hên, nkhĭt mâu geh nau yô̆ ôh$b$,true),
('bunong-vn','LAM',3,44,null,$b$may pôn săk tâm ndâr tŭk, kŏ tât nau mbơh sơm mâu dơi rgăn ôh tât ma may.$b$,false),
('bunong-vn','LAM',3,45,null,$b$May njêng hên luh ndơ ƀơ̆ jêh ri njŏk (ndŏk) ta nklang phung ƀon lan.$b$,true),
('bunong-vn','LAM',3,46,null,$b$Lĕ rngôch phung rlăng hên nter huy tâm rdâng đah hên.$b$,true),
('bunong-vn','LAM',3,47,null,$b$Hên hŏ khan jêh tâm nau krit klach, tâm ntu jru, tâm nau rai yot, jêh ri djơh mhĭk.$b$,true),
('bunong-vn','LAM',3,48,null,$b$Măt gâp hor dak măt, yor kon bu ur phung ƀon lan gâp lĕ rai yot jêh.$b$,true),
('bunong-vn','LAM',3,49,null,$b$Măt gâp hor dak măt mâu rlu ôh,$b$,true),
('bunong-vn','LAM',3,50,null,$b$kŏ tât Yêhôva mêt uănh, tă bơh klơ trôk uănh tâm dâng.$b$,false),
('bunong-vn','LAM',3,51,null,$b$Măt gâp saơ ƀư rngot huêng gâp, yor nau tât ma lĕ rngôch phung bu ur druh ƀon gâp.$b$,true),
('bunong-vn','LAM',3,52,null,$b$Phung mâu geh nau ŭch tâm rkeh đah gâp hŏ tĭng pănh jêh gâp nâm bu joi pănh sĭm.$b$,true),
('bunong-vn','LAM',3,53,null,$b$Khân păng ŭch nkhĭt gâp ntŭk ntu ngo, jêh ri klŭp lŭ ta gâp.$b$,true),
('bunong-vn','LAM',3,54,null,$b$Dak băm klơ bôk gâp; gâp lah, ‘Gâp lĕ khĭt roh jêh!$b$,true),
('bunong-vn','LAM',3,55,null,$b$Hơi Yêhôva, gâp tă tâm ntu jru ngo ngăn kuăl mbơh sơm ma amoh may.$b$,true),
('bunong-vn','LAM',3,56,null,$b$May tăng jêh nau gâp vơh vơl: “Lơi may nsêt lơi trôm tôr may ma nau gâp nter vơh vơl dăn nau kơl?”$b$,true),
('bunong-vn','LAM',3,57,null,$b$Nar gâp mbơh sơm ma may, may hŏ văch dăch jêh gâp, may hŏ lah: “Lơi klach ôh!”$b$,true),
('bunong-vn','LAM',3,58,null,$b$may king jêh gâp, Hơi Yêhôva, may tâm chuai jêh nau rêh gâp.$b$,true),
('bunong-vn','LAM',3,59,null,$b$Hơi Yêhôva, may saơ jêh nau mhĭk bu ƀư ma gâp, ăn may phat an dôih gâp.$b$,true),
('bunong-vn','LAM',3,60,null,$b$May hŏ saơ jêh lĕ rngôch nau khân păng plơng bôk, lĕ rngôch nau khân păng ƀư ma gâp.$b$,true),
('bunong-vn','LAM',3,61,null,$b$May tăng jêh nau khân păng gơm rmot ma gâp, Hơi Yêhôva. Lĕ rngôch nau khân păng mưch ma gâp.$b$,true),
('bunong-vn','LAM',3,62,null,$b$Phung rlăng ma gâp ngơi jêh ri mĭn nau mhĭk tâm rdâng ma gâp ăp nar.$b$,true),
('bunong-vn','LAM',3,63,null,$b$May uănh hom nau khân păng gŭ mâu lah dâk; khân păng mprơ mưch ma gâp.$b$,true),
('bunong-vn','LAM',3,64,null,$b$Hơi Yêhôva, may mra plơng bôk phat dôih khân păng tĭng nâm kan ti khân păng ƀư.$b$,true),
('bunong-vn','LAM',3,65,null,$b$Ăn may ƀư dăng nuih n'hâm khân păng, ăn may rak rtăp khân păng.$b$,true),
('bunong-vn','LAM',3,66,null,$b$May mra sŏk nau ji nuih jêh ri tĭng khân păng, jêh ri ƀư rai lơi khân păng tă bơh tâm dâng trôk Yêhôva.$b$,true),
('bunong-vn','LAM',4,1,null,$b$Vơ, mah lĕ roh nau chrêk păng, mah chrêk lĕ rgâl êng jêh! Lŭ khlay ntŭk kloh ueh lĕ đăt du ta aơ ta ri, bu saơ lĕ rngôch ta njônh trong sâng!$b$,true),
('bunong-vn','LAM',4,2,null,$b$Phung kon bu klâu Siôn khlay ngăn nâm bu mah chrêk lĕ, Aƀaơ lĕ jêng nâm bu yăng bu mon uk, jêng kan ti phung mon păng!$b$,true),
('bunong-vn','LAM',4,3,null,$b$Phung so bri ăt hôm e ăn toh ma kon păng pu; Ƀiă lah kon bu ur phung ƀon lan gâp jêng djơh, nâm bu sĭm (ôtrus) klang kŭk ntŭk bri rdah.$b$,true),
('bunong-vn','LAM',4,4,null,$b$Kon mhe deh ji hir ngăn, mpiăt krêp đah rmlông Kon se jê̆ ŭch joi piăng let mâu geh nuyh sâm pêch an khân păng.$b$,true),
('bunong-vn','LAM',4,5,null,$b$Phung mơng sa ndơ ƀâu kah gŭ rêh ni êng tâm trong sâng ƀon toyh; phung bu mât rong tâm bok rvanh chăng-krăk aƀaơ ri pung tâm ŭnh buh.$b$,true),
('bunong-vn','LAM',4,6,null,$b$Nau tih rmal kon bu ur phung ƀon lan gâp toyh rlau lơn nau rmal nau tih Sôdôm ƀon nây bu n'glưh ƀât lât dơm, mâu geh ôh ti bunuyh kơt păng.$b$,true),
('bunong-vn','LAM',4,7,null,$b$Phung kôranh toyh lư păng rsang lơn pler, nglang lơn dak toh; săk jăn khân păng dŭm lơn ma lŭ tâm dâng săt dak mƀŭt nau ueh săk jăn khân păng nâm bu lŭ saphir$b$,true),
('bunong-vn','LAM',4,8,null,$b$Aƀaơ ri muh măt khân păng krăk kher rlau sa ônh; mâu geh ôh bunuyh gĭt năl khân păng ta trong; ntâu khân păng lĕ klêu dop klơ nting khân păng, lĕ kêng kro nâm bu long.$b$,false),
('bunong-vn','LAM',4,9,null,$b$Phung khĭt yor đao nkhĭt jêng ueh lơn ma phung khĭt nau ât ji ngot: Khân păng khĭt rngot yor mâu geh play tă tâm mir, păng huăr-huơi mbrơi-mbrơi nâm bu khĭt bu ntâp.$b$,true),
('bunong-vn','LAM',4,10,null,$b$Ma ti khân păng nơm phung bu ur ăt geh lĕ nuih n'hâm yô̆ klâng, hŏ gâm jêh kon khân păng nơm; khân ô băl jêng ndơ ma khân păng sông sa dôl nau ƀư rai tât ma kon bu ur phung ƀon lan gâp.$b$,true),
('bunong-vn','LAM',4,11,null,$b$Yêhôva ăn tât lĕ nau păng ji nuih, păng nkhŭt jêh nau păng duh nuih; jêh ri păng sĭnh ŭnh ta ƀon Siôn, ŭnh nây sa lĕ ăp ƀon păng.$b$,true),
('bunong-vn','LAM',4,12,null,$b$Phung hađăch gŭ ta neh ntu mâu ntôn lah geh nau nây ôh Phung rlăng tâm lơh lam lĕ lăp ăp Mpông pêr ƀon Yêrusalem.$b$,true),
('bunong-vn','LAM',4,13,null,$b$Nây jêng yor tă bơh nau tih phung kôranh nơm mbơh lor păng, jêh ri nau djơh mhĭk phung kôranh ƀư brah păng. Khân păng hŏ ăn pling jêh ta nklang păng Mham phung sŏng srăng.$b$,true),
('bunong-vn','LAM',4,14,null,$b$Khân păng ndăch jŭm rŏ trong nâm bu bunuyh chieh măt; lĕ mham ƀư ƀơ̆ khân păng kŏ tât mâu geh nuyh pah bi bok ao khân păng.$b$,true),
('bunong-vn','LAM',4,15,null,$b$Bu kuăl dat khân păng, “Du der hom! Nơm ƀơ̆ !” “Du hom! Du hom! Lơi brot hên ôh!” Tơ lah khân păng du der hăn mblêng jêh, phung mpôl bunuyh bunăch lah: “Khân păng mâu mra gŭ ta aơ đŏng ôh.$b$,true),
('bunong-vn','LAM',4,16,null,$b$Nau ji nuih Yêhôva hŏ ƀư khân păng chah rai pru pra, păng mâu mra mât mray khân păng ôh. Bu mâu hôm yơk ôh ma kôranh ƀư brah, tâm ban lĕ bu mâu mpơl ôh nau yô̆ an ma phung bu ranh.$b$,true),
('bunong-vn','LAM',4,17,null,$b$Măt he lĕ hêr kâp uănh ƀa ƀơ dơm dam nau kâp kơl! He n'gơr uănh klơ vâl tŭm ma du Mpôl băl mâu dơi tâm rklaih he ôh.$b$,true),
('bunong-vn','LAM',4,18,null,$b$Khân păng kâp moch ta nhuat he, kŏ tât he mâu hôm dơi chuat ôh n'gŏ trong ƀon toyh. Nau lôch dŭt ma he hŏ dăch tât jêh!$b$,true),
('bunong-vn','LAM',4,19,null,$b$Phung tĭng he prăl lơn ma klang klơ trôk khân păng tĭng he ta klơ yôk, khân păng kâp lơh he tâm bri rdah.$b$,true),
('bunong-vn','LAM',4,20,null,$b$Nơm Yêhôva tŏ jêh dak ƀâu kah, nơm jêng nau nsôr n'hâm he; geh dăk khân păng sân jêh, Ma păng he vay lah: “He mra gŭ tâm dâng n'hâm gui păng; jêh ri gŭ rêh ta nklang phung mpôl băl bunuyh.”$b$,true),
('bunong-vn','LAM',4,21,null,$b$Hơi kon bu ur Êđôm, hâk răm hom, nơm gŭ tâm bri Us; kachok nau aơ mra tât tâm ban lĕ may mra nhŭl ndrănh jêh ri gŭ săk hưl.$b$,true),
('bunong-vn','LAM',4,22,null,$b$Hơi kon bu ur ƀon Siôn, nau tâm rmal yor nau kue ay lĕ lôch jêh, păng mâu hôm nsot ay hăn ƀư bu nă đŏng ôh! Hơi kon bu ur Êđôm, prăng mra tâm rmal nau kue ay, păng mra tâm mpơl nau tih ay.$b$,true),
('bunong-vn','LAM',5,1,null,$b$Hơi Yêhôva, kah gĭt hom ma nau tât ma hên; Uănh hom nau bêk prêng hên!$b$,true),
('bunong-vn','LAM',5,2,null,$b$Drăp ndơ hên lĕ pha ma phung bunăch jêh, phung bunăch pit in jêh ngih vâl hên.$b$,true),
('bunong-vn','LAM',5,3,null,$b$Hên lĕ roh mbơ̆ , lĕ jêng kon đơi, Mê̆ hên lĕ jêng ndrô jêh.$b$,true),
('bunong-vn','LAM',5,4,null,$b$Phung hên rvăt lah ŭch nhêt dak. Rvăt mơ dĭng geh long sĭnh.$b$,true),
('bunong-vn','LAM',5,5,null,$b$Phung tĭng lĕ ban jêh hên! glăn trô ko hên. Hên lĕ rgănh huăr jêh, mâu geh rlu ôh!$b$,true),
('bunong-vn','LAM',5,6,null,$b$Hên nchŏng ti rlet mpeh phung Êjipt jêh ri Asiri, gay geh tŏng ndơ sông sa.$b$,true),
('bunong-vn','LAM',5,7,null,$b$Chô che hên hŏ ƀư tih jêh, aƀaơ ri mâu hôm ôh khân păng. Jêh ri hên anh nau kue khân păng$b$,true),
('bunong-vn','LAM',5,8,null,$b$Phung dĭk jêng kôranh ma hên, Mâu geh ôh bunuyh sâm rklaih hên tă bơh ti khân păng.$b$,false),
('bunong-vn','LAM',5,9,null,$b$Hên sân săk jăn ri mơ geh ndơ sông sa. Yor lah bu kâp nkhĭt hên tâm bri rdah.$b$,true),
('bunong-vn','LAM',5,10,null,$b$Ntâu săk hên duh ring nâm bu ŭnh năk yor lah nau ât ji ngot kŏ tât ji kop$b$,true),
('bunong-vn','LAM',5,11,null,$b$Bu tom bu ur tâm ƀon Siôn, jêh ri nđâp ma bu ur druh tang tat tâm ƀon n'gor Yuđa.$b$,false),
('bunong-vn','LAM',5,12,null,$b$Bu kât yông phung kôranh ta ti khân păng, bu mâu yơk ôh ma phung bu ranh.$b$,true),
('bunong-vn','LAM',5,13,null,$b$Bu nchâp phung mom ndăm rvah mpăl; jêh ri bu klâu kon se prah chôt tâm dâng nchăp long jâk ngăn.$b$,true),
('bunong-vn','LAM',5,14,null,$b$Phung bu ranh du hăn mâu hôm gŭ ôh ta mpông pêr ƀon. Phung mom ndăm mâu hôm mpât mprơ ôh.$b$,true),
('bunong-vn','LAM',5,15,null,$b$Nau maak tâm nuih n'hâm hên du jêh; nau ta lô̆ pâl jêng nau rngot klâng.$b$,true),
('bunong-vn','LAM',5,16,null,$b$Đon hađăch tŭp jêh bơh klơ bôk hên; rêh ni ngăn ma hên, yor lah hên ƀư tih jêh!$b$,true),
('bunong-vn','LAM',5,17,null,$b$Yor nau aơ nuih n'hâm hên khĭt huăr, yor nau aơ măt hên lĕ hêr jêh,$b$,true),
('bunong-vn','LAM',5,18,null,$b$Yor yôk Siôn jêng rngol jêh, so bri nsong ta nây.$b$,false),
('bunong-vn','LAM',5,19,null,$b$Hơi Yêhôva, may hôm ƀa ƀơ n'ho ro sưng hađăch ăt hôm ƀa ƀơ lĕ rngôch rnôk.$b$,true),
('bunong-vn','LAM',5,20,null,$b$Mâm ƀư may chuêl ma hên mro mrăng. Cha lơi êng hên jŏ ngăn jêh?$b$,true),
('bunong-vn','LAM',5,21,null,$b$Hơi Yêhôva, sŏk sĭt hom hên, gay ma hên dơi plơ̆ sĭt, ƀư mhe đŏng nar hên nâm bu kăl e!$b$,true),
('bunong-vn','LAM',5,22,null,$b$Ƀiă lah may cha lơi lĕ rngôch hên, may ji nuih ma hên hâu ngăn.$b$,true);
